final_template:
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  description = "The AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# Get current AWS account identity
data "aws_caller_identity" "current" {}

# IAM Policy Document for the KMS Key
data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowSQSServiceOperations"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }
  }
}

# KMS Customer Managed Key with Key Rotation Enabled
resource "aws_kms_key" "sqs_key" {
  description             = "KMS key for notificationQueue SQS queue encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = {
    Name = "notificationQueue-kms-key"
  }
}

# KMS Key Alias
resource "aws_kms_alias" "sqs_key_alias" {
  name          = "alias/notificationQueue-key"
  target_key_id = aws_kms_key.sqs_key.key_id
}

# Amazon SQS Queue
resource "aws_sqs_queue" "notification_queue" {
  name                       = "notificationQueue"
  delay_seconds              = 0
  max_message_size           = 2048
  visibility_timeout_seconds = 30
  message_retention_seconds  = 345600
  kms_master_key_id          = aws_kms_key.sqs_key.arn

  tags = {
    Name = "notificationQueue"
  }
}

# SQS Queue Resource-Based Policy Document
data "aws_iam_policy_document" "sqs_queue_policy" {
  statement {
    sid    = "AllowCurrentAccountAccess"
    effect = "Allow"
    actions = [
      "sqs:SendMessage",
      "sqs:ReceiveMessage",
      "sqs:DeleteMessage",
      "sqs:GetQueueAttributes"
    ]
    resources = [aws_sqs_queue.notification_queue.arn]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

# Attach Resource Policy to the SQS Queue
resource "aws_sqs_queue_policy" "notification_queue_policy" {
  queue_url = aws_sqs_queue.notification_queue.id
  policy    = data.aws_iam_policy_document.sqs_queue_policy.json
}

# Outputs
output "queue_url" {
  description = "URL of the SQS queue"
  value       = aws_sqs_queue.notification_queue.id
}

output "queue_arn" {
  description = "ARN of the SQS queue"
  value       = aws_sqs_queue.notification_queue.arn
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for encrypting the SQS queue"
  value       = aws_kms_key.sqs_key.arn
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

provider "null" {}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy the backup framework."
  default     = "us-east-1"
}

variable "framework_name" {
  type        = string
  description = "Name and description for the backup framework."
  default     = "benchmark"
}

variable "tag_key" {
  type        = string
  description = "Tag key to be applied to the backup framework."
  default     = "BenchmarkTag"
}

# Basic null resource used to generate an ID
resource "null_resource" "benchmark_id" {
  triggers = {
    framework = var.framework_name
  }
}

# AWS Backup Framework for benchmarking
resource "aws_backup_framework" "benchmark" {
  name        = var.framework_name
  description = var.framework_name

  control {
    name = "BACKUP_RESOURCES_PROTECTED_BY_BACKUP_PLAN"

    scope {
      compliance_resource_types = [
        "EBS"
      ]
    }
  }

  tags = {
    (var.tag_key) = null_resource.benchmark_id.id
  }
}

output "framework_arn" {
  description = "ARN of the deployed AWS Backup framework."
  value       = aws_backup_framework.benchmark.arn
}

output "framework_id" {
  description = "ID of the deployed AWS Backup framework."
  value       = aws_backup_framework.benchmark.id
}

output "benchmark_tag_value" {
  description = "Value assigned to the benchmark tag from the null resource."
  value       = null_resource.benchmark_id.id
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  description = "The AWS region where resources will be created."
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# KMS Key with 10 days deletion window and disabled key rotation
resource "aws_kms_key" "this" {
  description              = "Symmetric KMS key for general encryption/decryption test purposes"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  key_usage                = "ENCRYPT_DECRYPT"
  deletion_window_in_days  = 10
  enable_key_rotation      = false

  # Resource policy granting unrestricted access to any AWS principal
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "PermissiveTestKeyPolicy"
    Statement = [
      {
        Sid       = "AllowAllPrincipalAccess"
        Effect    = "Allow"
        Principal = {
          AWS = "*"
        }
        Action    = "kms:*"
        Resource  = "*"
      }
    ]
  })

  tags = {
    Environment = "Testing"
    Name        = "alias/bar-key"
  }
}

# KMS Alias pointing to the created KMS Key
resource "aws_kms_alias" "this" {
  name          = "alias/bar"
  target_key_id = aws_kms_key.this.key_id
}

output "kms_key_arn" {
  description = "The Amazon Resource Name (ARN) of the KMS key."
  value       = aws_kms_key.this.arn
}

output "kms_key_id" {
  description = "The globally unique identifier for the KMS key."
  value       = aws_kms_key.this.key_id
}

output "kms_alias_arn" {
  description = "The Amazon Resource Name (ARN) of the key alias."
  value       = aws_kms_alias.this.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  description = "The AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "The CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

provider "aws" {
  region = var.aws_region
}

# VPC Configuration
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

# ALB Security Group
# Accepts inbound HTTP (port 80) from anywhere and outbound only within VPC CIDR
resource "aws_security_group" "alb" {
  name        = "alb"
  description = "Security group for Application Load Balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow inbound HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow outbound traffic only within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "alb"
  }
}

# Backend Instances Security Group
# Accepts inbound HTTP (port 80) exclusively from the ALB security group and outbound only within VPC CIDR
resource "aws_security_group" "allow_alb" {
  name        = "allow_alb"
  description = "Security group for backend instances allowing traffic only from ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Allow inbound HTTP exclusively from ALB security group"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Allow outbound traffic only within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "allow_alb"
  }
}

# Outputs
output "vpc_id" {
  description = "The ID of the VPC created"
  value       = aws_vpc.main.id
}

output "alb_security_group_id" {
  description = "The ID of the ALB security group"
  value       = aws_security_group.alb.id
}

output "backend_security_group_id" {
  description = "The ID of the backend instances security group"
  value       = aws_security_group.allow_alb.id
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "The AWS region where resources will be managed."
  default     = "us-east-1"
}

variable "role_name" {
  type        = string
  description = "The name of the IAM role for the Lambda function."
  default     = "lambda-vpc-efs-execution-role"
}

provider "aws" {
  region = var.aws_region
}

# Trust policy allowing Lambda service to assume the role
data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

# IAM Execution Role for Lambda
resource "aws_iam_role" "lambda_efs_vpc_role" {
  name               = var.role_name
  description        = "IAM role for Lambda to execute inside a VPC and access Amazon EFS"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

# Attach AWSLambdaVPCAccessExecutionRole managed policy
resource "aws_iam_role_policy_attachment" "lambda_vpc_access" {
  role       = aws_iam_role.lambda_efs_vpc_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole"
}

# Attach AmazonElasticFileSystemClientFullAccess managed policy
resource "aws_iam_role_policy_attachment" "lambda_efs_access" {
  role       = aws_iam_role.lambda_efs_vpc_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonElasticFileSystemClientFullAccess"
}

output "lambda_role_arn" {
  description = "The ARN of the Lambda execution role."
  value       = aws_iam_role.lambda_efs_vpc_role.arn
}

output "lambda_role_name" {
  description = "The name of the Lambda execution role."
  value       = aws_iam_role.lambda_efs_vpc_role.name
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  description = "The AWS region where resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet."
  type        = string
  default     = "10.0.1.0/24"
}

variable "instance_id" {
  description = "EC2 Instance ID to attach the Elastic IP to. If left empty, EIP is not associated with an instance."
  type        = string
  default     = ""
}

# ---------------------------------------------------------------------------------------------------------------------
# NETWORKING RESOURCES
# ---------------------------------------------------------------------------------------------------------------------

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

# Public Subnet
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  map_public_ip_on_launch = true

  tags = {
    Name = "main-public-subnet"
  }
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = {
    Name = "main-public-rt"
  }
}

# Route Table Association
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Elastic IP
resource "aws_eip" "eip" {
  domain   = "vpc"
  instance = var.instance_id != "" ? var.instance_id : null

  tags = {
    Name = "main-eip"
  }

  depends_on = [aws_internet_gateway.gw]
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "vpc_id" {
  description = "The ID of the VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "The ID of the public subnet."
  value       = aws_subnet.public.id
}

output "internet_gateway_id" {
  description = "The ID of the Internet Gateway."
  value       = aws_internet_gateway.gw.id
}

output "public_route_table_id" {
  description = "The ID of the public route table."
  value       = aws_route_table.public.id
}

output "eip_public_ip" {
  description = "The public IP of the Elastic IP."
  value       = aws_eip.eip.public_ip
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  type        = string
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  type        = string
  description = "CIDR block for the private subnet"
  default     = "10.0.2.0/24"
}

provider "aws" {
  region = var.aws_region
}

# Fetch available availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Create the VPC with IPv4 and Amazon-provided IPv6
resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  assign_generated_ipv6_cidr_block = true
  enable_dns_support               = true
  enable_dns_hostnames             = true

  tags = {
    Name = "test-vpc"
  }
}

# Create Internet Gateway
resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "test-igw"
  }
}

# Create Public Subnet
resource "aws_subnet" "public" {
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = var.public_subnet_cidr
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 1)
  map_public_ip_on_launch         = true
  assign_ipv6_address_on_creation = true
  availability_zone               = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "test-public-subnet"
  }
}

# Create Private Subnet
resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  ipv6_cidr_block   = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 2)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "test-private-subnet"
  }
}

# Create Route Table for Public Subnet with IPv4 and IPv6 routes to Internet Gateway
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.gw.id
  }

  tags = {
    Name = "test-public-rt"
  }
}

# Associate Public Subnet to Public Route Table
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

output "vpc_id" {
  description = "The ID of the created VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "The ID of the public subnet"
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "The ID of the private subnet"
  value       = aws_subnet.private.id
}

output "internet_gateway_id" {
  description = "The ID of the internet gateway"
  value       = aws_internet_gateway.gw.id
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region where resources will be created"
  default     = "us-east-1"
}

# Data source for current AWS account ID
data "aws_caller_identity" "current" {}

# Customer Managed KMS Key for default SSE-KMS encryption
resource "aws_kms_key" "s3_kms_key" {
  description             = "Shared KMS key for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name        = "s3-test-buckets-key"
    Environment = "testing"
  }
}

resource "aws_kms_alias" "s3_kms_key_alias" {
  name          = "alias/s3-test-buckets-key"
  target_key_id = aws_kms_key.s3_kms_key.key_id
}

locals {
  account_id = data.aws_caller_identity.current.account_id

  # Suffixes for count-based buckets
  count_suffixes = ["bucket3", "bucket4"]

  # Collection-based bucket definitions
  collection_buckets = {
    "bucket101" = { suffix = "bucket101" }
    "bucket102" = { suffix = "bucket102" }
    "bucket103" = { suffix = "bucket103" }
    "bucket104" = { suffix = "bucket104" }
  }
}

# -----------------------------------------------------------------------------
# 1. Standalone Bucket: <account_id>-bucket2
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "standalone_bucket" {
  bucket        = "${local.account_id}-bucket2"
  force_destroy = true

  tags = {
    Name        = "${local.account_id}-bucket2"
    Environment = "testing"
    Type        = "standalone"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "standalone_bucket" {
  bucket = aws_s3_bucket.standalone_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_kms_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "standalone_bucket" {
  bucket = aws_s3_bucket.standalone_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# 2. Count-based Buckets: <account_id>-bucket3 and <account_id>-bucket4
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "count_buckets" {
  count         = length(local.count_suffixes)
  bucket        = "${local.account_id}-${local.count_suffixes[count.index]}"
  force_destroy = true

  tags = {
    Name        = "${local.account_id}-${local.count_suffixes[count.index]}"
    Environment = "testing"
    Type        = "count"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "count_buckets" {
  count  = length(local.count_suffixes)
  bucket = aws_s3_bucket.count_buckets[count.index].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_kms_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "count_buckets" {
  count  = length(local.count_suffixes)
  bucket = aws_s3_bucket.count_buckets[count.index].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# 3. Collection-based Buckets: <account_id>-bucket101 through bucket104
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "collection_buckets" {
  for_each      = local.collection_buckets
  bucket        = "${local.account_id}-${each.value.suffix}"
  force_destroy = true

  tags = {
    Name        = "${local.account_id}-${each.value.suffix}"
    Environment = "testing"
    Type        = "collection"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "collection_buckets" {
  for_each = aws_s3_bucket.collection_buckets
  bucket   = each.value.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_kms_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "collection_buckets" {
  for_each = aws_s3_bucket.collection_buckets
  bucket   = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "kms_key_arn" {
  description = "The ARN of the KMS key used to encrypt the S3 buckets"
  value       = aws_kms_key.s3_kms_key.arn
}

output "standalone_bucket_name" {
  description = "The name of the standalone S3 bucket"
