terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Current AWS Account and Region references
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# KMS Key for SNS Topic encryption with permissions for AWS Budgets
resource "aws_kms_key" "budget_sns_key" {
  description             = "KMS Key for Budget SNS Topic encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "BudgetKmsKeyPolicy"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Budgets to use the key"
        Effect = "Allow"
        Principal = {
          Service = "budgets.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "budget_sns_key_alias" {
  name          = "alias/budget-sns-key"
  target_key_id = aws_kms_key.budget_sns_key.key_id
}

# SNS Topic encrypted with KMS key
resource "aws_sns_topic" "budget" {
  name              = "budget"
  kms_master_key_id = aws_kms_key.budget_sns_key.id
}

# SNS Topic Policy allowing budgets.amazonaws.com to publish
resource "aws_sns_topic_policy" "budget" {
  arn = aws_sns_topic.budget.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "BudgetTopicPolicy"
    Statement = [
      {
        Sid    = "AllowBudgetsToPublish"
        Effect = "Allow"
        Principal = {
          Service = "budgets.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.budget.arn
      }
    ]
  })
}

# SNS SMS Subscription
resource "aws_sns_topic_subscription" "sms_alert" {
  topic_arn = aws_sns_topic.budget.arn
  protocol  = "sms"
  endpoint  = "+447828835419"
}

# AWS Cost Budget
resource "aws_budgets_budget" "budget" {
  name              = "budget"
  budget_type       = "COST"
  limit_amount      = "25.0"
  limit_unit        = "USD"
  time_unit         = "MONTHLY"
  time_period_start = "2021-07-01_00:00"

  notification {
    comparison_operator        = "GREATER_THAN"
    threshold                  = 100
    threshold_type             = "PERCENTAGE"
    notification_type          = "ACTUAL"
    subscriber_email_addresses = ["hello@chriswilding.co.uk"]
    subscriber_sns_topic_arns  = [aws_sns_topic.budget.arn]
  }

  depends_on = [
    aws_sns_topic_policy.budget
  ]
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "The AWS region to deploy resources in."
  type        = string
  default     = "us-east-1"
}

variable "ecr_repository_name" {
  description = "The name of the ECR repository."
  type        = string
  default     = "reactjs-app-repo"
}

variable "ecs_task_execution_role_name" {
  description = "The name of the ECS task execution IAM role."
  type        = string
  default     = "ecsTaskExecutionRole"
}

provider "aws" {
  region = var.aws_region
}

# Amazon ECR Repository for the React.js application
resource "aws_ecr_repository" "reactjs_app_repo" {
  name                 = var.ecr_repository_name
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = {
    Name        = var.ecr_repository_name
    Environment = "production"
  }
}

# IAM Role for ECS Task Execution
resource "aws_iam_role" "ecs_task_execution_role" {
  name = var.ecs_task_execution_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = var.ecs_task_execution_role_name
  }
}

# Attach AWS-managed AmazonECSTaskExecutionRolePolicy to the role
resource "aws_iam_role_policy_attachment" "ecs_task_execution_role_policy" {
  role       = aws_iam_role.ecs_task_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# Outputs
output "ecr_repository_url" {
  description = "The URL of the created ECR repository."
  value       = aws_ecr_repository.reactjs_app_repo.repository_url
}

output "ecr_repository_arn" {
  description = "The ARN of the created ECR repository."
  value       = aws_ecr_repository.reactjs_app_repo.arn
}

output "ecs_task_execution_role_arn" {
  description = "The ARN of the ECS task execution role."
  value       = aws_iam_role.ecs_task_execution_role.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region for the provider"
  default     = "us-east-1"
}

# IAM Role assumed by EC2
resource "aws_iam_role" "role" {
  name = "role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Inline Policy 1: Allows passing IAM roles across all resources
resource "aws_iam_role_policy" "allow_policy_1" {
  name = "allow-policy-1"
  role = aws_iam_role.role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowPassRole"
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = "*"
      }
    ]
  })
}

# Inline Policy 2: Allows creating Lambda functions and invoking Lambda functions matching lambda:invokefunc*
resource "aws_iam_role_policy" "allow_policy_2" {
  name = "allow-policy-2"
  role = aws_iam_role.role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLambdaActions"
        Effect = "Allow"
        Action = [
          "lambda:CreateFunction",
          "lambda:invokefunc*"
        ]
        Resource = "*"
      }
    ]
  })
}

output "role_arn" {
  description = "The ARN of the created IAM role"
  value       = aws_iam_role.role.arn
}

output "role_name" {
  description = "The name of the created IAM role"
  value       = aws_iam_role.role.name
}

