terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

variable "aws_region" {
  description = "AWS region where resources will be created"
  type        = string
  default     = "us-east-1"
}

variable "retention_in_days" {
  description = "Specifies the number of days you want to retain log events in the specified log group"
  type        = number
  default     = 30
}

provider "aws" {
  region = var_aws_region
}

# Generate a random two-word pet name identifier
resource "random_pet" "log_group_suffix" {
  length    = 2
  separator = "-"
}

# Create the CloudWatch Log Group with prefix "log-group-" followed by the pet name
resource "aws_cloudwatch_log_group" "dynamic_log_group" {
  name              = "log-group-${random_pet.log_group_suffix.id}"
  retention_in_days = var.retention_in_days

  tags = {
    Environment = "ManagedByTerraform"
    Purpose     = "Logging"
  }
}

output "cloudwatch_log_group_name" {
  description = "The name of the created CloudWatch Log Group"
  value       = aws_cloudwatch_log_group.dynamic_log_group.name
}

output "cloudwatch_log_group_arn" {
  description = "The ARN of the created CloudWatch Log Group"
  value       = aws_cloudwatch_log_group.dynamic_log_group.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
