}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Project     = "Website CV"
      Environment = "production"
    }
  }
}

# Create a reusable Route 53 delegation set
resource "aws_route53_delegation_set" "website_dns" {
  reference_name = "WebsiteDNS"
}

# Store the delegation set ID in AWS Systems Manager (SSM) Parameter Store
resource "aws_ssm_parameter" "delegation_set_id" {
  name        = "/WebsiteCv/production/Route53/DelegationSetId"
  description = "Route 53 Reusable Delegation Set ID for Production Website CV"
  type        = "String"
  value       = aws_route53_delegation_set.website_dns.id
}

# Outputs for reference
output "delegation_set_id" {
  description = "The ID of the reusable delegation set"
  value       = aws_route53_delegation_set.website_dns.id
}

output "delegation_set_name_servers" {
  description = "The list of name servers assigned to the delegation set"
  value       = aws_route53_delegation_set.website_dns.name_servers
}

output "ssm_parameter_name" {
  description = "The name of the SSM parameter storing the delegation set ID"
  value       = aws_ssm_parameter.delegation_set_id.name
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "The AWS region where resources will be provisioned."
  default     = "us-east-1"
}

variable "bucket_name" {
  type        = string
  description = "The name of the S3 bucket for benchmarking."
  default     = "benchmark-bucket-tf5x"
}

variable "name_tag" {
  type        = string
  description = "The value for the Name tag on the bucket."
  default     = "benchmark"
}

variable "force_destroy" {
  type        = bool
  description = "Whether all objects should be deleted from the bucket so that the bucket can be destroyed without error."
  default     = true
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# KMS Key for Bucket Encryption
# -----------------------------------------------------------------------------

resource "aws_kms_key" "benchmark_key" {
  description             = "KMS Key for S3 benchmark bucket server-side encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "kms-key-policy"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${var.name_tag}-kms-key"
  }
}

resource "aws_kms_alias" "benchmark_key_alias" {
  name          = "alias/${var.bucket_name}-key"
  target_key_id = aws_kms_key.benchmark_key.key_id
}

# -----------------------------------------------------------------------------
# S3 Bucket Configuration
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "benchmark_bucket" {
  bucket        = var.bucket_name
  force_destroy = var.force_destroy

  tags = {
    Name = var.name_tag
  }
}

# Server-side encryption configuration using the Customer Managed KMS Key
resource "aws_s3_bucket_server_side_encryption_configuration" "benchmark_encryption" {
  bucket = aws_s3_bucket.benchmark_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.benchmark_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Bucket-level public access block settings (all enabled)
resource "aws_s3_bucket_public_access_block" "benchmark_bucket_pab" {
  bucket = aws_s3_bucket.benchmark_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# Account-Level S3 Public Access Block Configuration
# -----------------------------------------------------------------------------

# Explicitly disable account-level S3 public access blocks
resource "aws_s3_account_public_access_block" "account_pab" {
  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "s3_bucket_name" {
  description = "The name of the created S3 bucket."
  value       = aws_s3_bucket.benchmark_bucket.id
}

output "s3_bucket_arn" {
  description = "The ARN of the created S3 bucket."
  value       = aws_s3_bucket.benchmark_bucket.arn
}

output "kms_key_arn" {
  description = "The ARN of the customer-managed KMS key used for encryption."
  value       = aws_kms_key.benchmark_key.arn
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region for deploying resources"
  default     = "us-east-1"
}

variable "base_name" {
  type        = string
  description = "Base name for the CloudTrail S3 bucket"
  default     = "benchmark"
}

provider "aws" {
  region = var.aws_region
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# Customer Managed KMS Key for S3 bucket encryption
resource "aws_kms_key" "cloudtrail_key" {
  description             = "KMS key for CloudTrail S3 bucket SSE-KMS encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudTrail to encrypt logs"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cloudtrail_key_alias" {
  name          = "alias/${var.base_name}-cloudtrail-key"
  target_key_id = aws_kms_key.cloudtrail_key.key_id
}

# S3 Bucket
resource "aws_s3_bucket" "cloudtrail_bucket" {
  bucket        = "${var.base_name}-cloudtrail-${data.aws_region.current.name}"
  force_destroy = true
}

# Block all public access to the bucket
resource "aws_s3_bucket_public_access_block" "cloudtrail_bucket_pab" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Server-Side Encryption Configuration using SSE-KMS
resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_bucket_encryption" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudtrail_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# S3 Bucket Policy for CloudTrail access
resource "aws_s3_bucket_policy" "cloudtrail_bucket_policy" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSCloudTrailAclCheck"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.cloudtrail_bucket.arn
      },
      {
        Sid    = "AWSCloudTrailWrite"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.cloudtrail_bucket.arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

output "bucket_name" {
  description = "The name of the created S3 bucket"
  value       = aws_s3_bucket.cloudtrail_bucket.id
}

output "bucket_arn" {
  description = "The ARN of the created S3 bucket"
  value       = aws_s3_bucket.cloudtrail_bucket.arn
}

