provider "aws" {
  region = "us-east-1"
}

# 1. Encrypted EFS File System
resource "aws_efs_file_system" "this" {
  creation_token = "cloudrail-test"
  encrypted      = true

  tags = {
    Name = "cloudrail-test-efs"
  }
}

# 2. ECS Task Definition
resource "aws_ecs_task_definition" "this" {
  family = "cloudrail-test-encryption"

  container_definitions = jsonencode([
    {
      name      = "first"
      image     = "service-first"
      cpu       = 10
      memory    = 512
      essential = true
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]
    },
    {
      name      = "second"
      image     = "service-second"
      cpu       = 10
      memory    = 256
      essential = true
      portMappings = [
        {
          containerPort = 443
          hostPort      = 443
          protocol      = "tcp"
        }
      ]
    }
  ])

  volume {
    name = "service-storage"

    efs_volume_configuration {
      file_system_id          = aws_efs_file_system.this.id
      root_directory          = "/opt/data"
      transit_encryption      = "ENABLED"
      transit_encryption_port = 2999
    }
  }
}

# Outputs
output "efs_file_system_id" {
  description = "ID of the created EFS File System"
  value       = aws_efs_file_system.this.id
}

output "ecs_task_definition_arn" {
  description = "ARN of the created ECS Task Definition"
  value       = aws_ecs_task_definition.this.arn
}
