provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region where the key pair will be created."
  default     = "us-east-1"
}

variable "key_prefix" {
  type        = string
  description = "Prefix for the AWS key pair name."
  default     = "key"
}

# Generate a two-word random pet name identifier
resource "random_pet" "key_name" {
  length    = 2
  separator = "-"
}

locals {
  key_pair_name = "${var.key_prefix}-${random_pet.key_name.id}"
  key_file_path = "${path.module}/../${local.key_pair_name}.pem"
}

# Generate a 4096-bit RSA private key
resource "tls_private_key" "ssh_key" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

# Create AWS Key Pair using the public key from the generated RSA key
resource "aws_key_pair" "generated_key" {
  key_name   = local.key_pair_name
  public_key = tls_private_key.ssh_key.public_key_openssh

  tags = {
    Name = local.key_pair_name
  }
}

# Save the private key in PEM format to a file in the parent directory
resource "local_file" "private_key_pem" {
  content         = tls_private_key.ssh_key.private_key_pem
  filename        = local.key_file_path
  file_permission = "0600"
}

# Ensure file permissions are explicitly set to 600 via local-exec
resource "null_resource" "secure_key_permissions" {
  triggers = {
    file_id = local_file.private_key_pem.id
  }

  provisioner "local-exec" {
    command = "chmod 600 '${local.key_file_path}'"
  }

  depends_on = [local_file.private_key_pem]
}

output "key_pair_name" {
  description = "The name of the created AWS key pair."
  value       = aws_key_pair.generated_key.key_name
}

output "private_key_path" {
  description = "Path where the private key PEM file is stored."
  value       = local.key_file_path
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Create the VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

# Create the Security Group
resource "aws_security_group" "web_sg" {
  name        = "Example security group"
  description = "Security group allowing HTTP and HTTPS traffic"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "Example security group"
  }
}

# Ingress rule for HTTP (Port 80)
resource "aws_vpc_security_group_ingress_rule" "allow_http" {
  security_group_id = aws_security_group.web_sg.id
  description       = "Allow inbound HTTP traffic"
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 80
  ip_protocol       = "tcp"
  to_port           = 80
}

# Ingress rule for HTTPS (Port 443)
resource "aws_vpc_security_group_ingress_rule" "allow_https" {
  security_group_id = aws_security_group.web_sg.id
  description       = "Allow inbound HTTPS traffic"
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 443
  ip_protocol       = "tcp"
  to_port           = 443
}

# Egress rule allowing all outbound traffic
resource "aws_vpc_security_group_egress_rule" "allow_all_outbound" {
  security_group_id = aws_security_group.web_sg.id
  description       = "Allow all outbound traffic"
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "-1"
}

# Outputs
output "vpc_id" {
  description = "The ID of the created VPC"
  value       = aws_vpc.main.id
}

output "security_group_id" {
  description = "The ID of the created Security Group"
  value       = aws_security_group.web_sg.id
}

terraform {
