# Retrieve current AWS account ID for KMS key policy
data "aws_caller_identity" "current" {}

# Customer Managed KMS Key for SQS encryption
resource "aws_kms_key" "sqs_key" {
  description             = "KMS CMK for SQS queue server-side encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "sqs-key-policy"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Environment = "production"
  }
}

# KMS Alias for the CMK
resource "aws_kms_alias" "sqs_key_alias" {
  name          = "alias/sqs-test-encryption-key"
  target_key_id = aws_kms_key.sqs_key.key_id
}

# Identical SQS Queues: "test-sqs" and "test-sqs1"
resource "aws_sqs_queue" "test_queues" {
  for_each = toset(["test-sqs", "test-sqs1"])

  name                       = each.key
  delay_seconds              = 90
  max_message_size           = 2048
  message_retention_seconds  = 86400
  receive_wait_time_seconds  = 10
  kms_master_key_id          = aws_kms_key.sqs_key.arn
  kms_data_key_reuse_period_seconds = 300

  tags = {
    Environment = "production"
  }
}

# Outputs
output "sqs_queue_arns" {
  description = "ARNs of the created SQS queues"
  value       = { for k, q in aws_sqs_queue.test_queues : k => q.arn }
}

output "sqs_queue_urls" {
  description = "URLs of the created SQS queues"
  value       = { for k, q in aws_sqs_queue.test_queues : k => q.id }
}

output "kms_key_arn" {
  description = "ARN of the KMS Key used for SQS encryption"
  value       = aws_kms_key.sqs_key.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "The AWS region to deploy resources in."
  default     = "us-east-1"
}

variable "base_bucket_name" {
  type        = string
  description = "The base name for the S3 bucket."
  default     = "doc-io-files"
}

variable "force_destroy" {
  type        = bool
  description = "Whether to force destroy the bucket even if it contains objects."
  default     = true
}

variable "allowed_account_id" {
  type        = string
  description = "The AWS account ID granted full access to the S3 bucket."
  default     = "566373416292"
}

# ------------------------------------------------------------------------------
# Random Prefix
# ------------------------------------------------------------------------------

resource "random_integer" "bucket_prefix" {
  min = 1
  max = 50000
}

# ------------------------------------------------------------------------------
# KMS Key for Bucket Encryption
# ------------------------------------------------------------------------------

resource "aws_kms_key" "s3_kms_key" {
  description             = "KMS key used to encrypt document I/O files in S3"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name = "doc-io-files-key"
  }
}

resource "aws_kms_alias" "s3_kms_key_alias" {
  name          = "alias/doc-io-files-key-${random_integer.bucket_prefix.result}"
  target_key_id = aws_kms_key.s3_kms_key.key_id
}

# ------------------------------------------------------------------------------
# S3 Bucket Configuration
# ------------------------------------------------------------------------------

locals {
  bucket_name = "${random_integer.bucket_prefix.result}-${var.base_bucket_name}"
}

resource "aws_s3_bucket" "doc_io_bucket" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  tags = {
    Name = local.bucket_name
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "doc_io_encryption" {
  bucket = aws_s3_bucket.doc_io_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_kms_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "doc_io_pab" {
  bucket = aws_s3_bucket.doc_io_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# S3 Bucket Policy
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "doc_io_bucket_policy" {
  statement {
    sid    = "AllowAccountFullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${var.allowed_account_id}:root"]
    }

    actions = [
      "s3:*"
    ]

    resources = [
      aws_s3_bucket.doc_io_bucket.arn,
      "${aws_s3_bucket.doc_io_bucket.arn}/*"
    ]
  }
}

resource "aws_s3_bucket_policy" "doc_io_policy" {
  bucket = aws_s3_bucket.doc_io_bucket.id
  policy = data.aws_iam_policy_document.doc_io_bucket_policy.json

  depends_on = [
    aws_s3_bucket_public_access_block.doc_io_pab
  ]
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "bucket_name" {
  description = "The dynamically generated name of the created S3 bucket."
  value       = aws_s3_bucket.doc_io_bucket.id
}

output "bucket_arn" {
  description = "The ARN of the created S3 bucket."
  value       = aws_s3_bucket.doc_io_bucket.arn
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used for encrypting bucket contents."
  value       = aws_kms_key.s3_kms_key.arn
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  description = "The AWS region to deploy the resources into."
  type        = string
  default     = "us-east-1"
}

variable "state_bucket_prefix" {
  description = "Prefix for the S3 bucket to hold remote state."
  type        = string
  default     = "tf-remote-state"
}

variable "lock_table_name" {
  description = "Name of the DynamoDB table used for state locking."
  type        = string
  default     = "tf-remote-state-locks"
}

# ---------------------------------------------------------------------------------------------------------------------
# RANDOM SUFFIX
# ---------------------------------------------------------------------------------------------------------------------

resource "random_string" "suffix" {
  length  = 8
  special = false
  upper   = false
}

# ---------------------------------------------------------------------------------------------------------------------
# KMS KEY FOR ENCRYPTION
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_kms_key" "state_key" {
  description             = "KMS key used to encrypt the Terraform state S3 bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name        = "terraform-state-backend-key"
    Environment = "Management"
  }
}

resource "aws_kms_alias" "state_key_alias" {
  name          = "alias/tf-state-backend-key-${random_string.suffix.result}"
  target_key_id = aws_kms_key.state_key.key_id
}

# ---------------------------------------------------------------------------------------------------------------------
# S3 BUCKET FOR TERRAFORM STATE
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket" "state_bucket" {
  bucket        = "${var.state_bucket_prefix}-${random_string.suffix.result}"
  force_destroy = false

  tags = {
    Name        = "Terraform Remote State"
    Environment = "Management"
  }
}

resource "aws_s3_bucket_versioning" "state_bucket_versioning" {
  bucket = aws_s3_bucket.state_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state_bucket_encryption" {
  bucket = aws_s3_bucket.state_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "state_bucket_public_access" {
  bucket = aws_s3_bucket.state_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------------------------------------------------
# DYNAMODB TABLE FOR TERRAFORM STATE LOCKING
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_dynamodb_table" "state_locks" {
  name         = var.lock_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.state_key.arn
  }

  tags = {
    Name        = var.lock_table_name
    Environment = "Management"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "s3_bucket_name" {
  description = "The name of the S3 bucket configured for Terraform state."
  value       = aws_s3_bucket.state_bucket.id
}

output "s3_bucket_arn" {
  description = "The ARN of the S3 bucket configured for Terraform state."
  value       = aws_s3_bucket.state_bucket.arn
}

output "dynamodb_table_name" {
  description = "The name of the DynamoDB table configured for state locking."
  value       = aws_dynamodb_table.state_locks.name
}

output "dynamodb_table_arn" {
  description = "The ARN of the DynamoDB table configured for state locking."
  value       = aws_dynamodb_table.state_locks.arn
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used for state encryption."
  value       = aws_kms_key.state_key.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "The AWS region where resources will be deployed."
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# Fetch the current AWS account details
data "aws_caller_identity" "current" {}

# Data source to generate IAM policy for the KMS Key
data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "Enable IAM User Permissions"
    effect    = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid       = "Allow EventBridge to use the key"
    effect    = "Allow"
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt"
    ]
    resources = ["*"]
  }
}

# Dedicated Customer-Managed KMS Key for SNS encryption
resource "aws_kms_key" "sns_kms_key" {
  description             = "Dedicated KMS key for incident-response SNS topic encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = {
    Name        = "incident-response-sns-key"
    Environment = "production"
  }
}

# KMS Key Alias
resource "aws_kms_alias" "sns_kms_key_alias" {
  name          = "alias/incident-response-sns-key"
  target_key_id = aws_kms_key.sns_kms_key.key_id
}

# Amazon SNS Topic
resource "aws_sns_topic" "incident_response" {
  name              = "incident-response"
  kms_master_key_id = aws_kms_key.sns_kms_key.id

  tags = {
    Name        = "incident-response"
    Environment = "production"
  }
}

# Data source for the SNS Topic Policy
data "aws_iam_policy_document" "sns_topic_policy" {
  policy_id = "__default_policy_ID"

  statement {
    sid    = "__default_statement_ID"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = [
      "sns:Subscribe",
      "sns:SetTopicAttributes",
      "sns:RemovePermission",
      "sns:Receive",
      "sns:Publish",
      "sns:ListSubscriptionsByTopic",
      "sns:GetTopicAttributes",
      "sns:DeleteTopic",
      "sns:AddPermission"
    ]

    resources = [
      aws_sns_topic.incident_response.arn
    ]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceOwner"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowAWSEvents"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }

    actions = [
      "sns:Publish"
    ]

    resources = [
      aws_sns_topic.incident_response.arn
    ]
  }
}

# SNS Topic Policy attachment
resource "aws_sns_topic_policy" "incident_response_policy" {
  arn    = aws_sns_topic.incident_response.arn
  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

output "sns_topic_arn" {
  description = "The ARN of the incident-response SNS topic"
  value       = aws_sns_topic.incident_response.arn
}

output "kms_key_arn" {
  description = "The ARN of the dedicated KMS key used to encrypt the topic"
  value       = aws_kms_key.sns_kms_key.arn
}

