  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "The AWS region to deploy the resources to."
  default     = "us-east-1"
}

provider "aws" {
  region = variable "aws_region"
}

# IAM Service-Linked Role for Amazon Elasticsearch/OpenSearch Service
resource "aws_iam_service_linked_role" "es" {
  aws_service_name = "es.amazonaws.com"
  description      = "Service-linked role for Amazon Elasticsearch/OpenSearch Service"
}

# IAM Policy Document granting CloudWatch Log permissions to Elasticsearch
data "aws_iam_policy_document" "elasticsearch_log_publishing_policy" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["es.amazonaws.com"]
    }

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:PutLogEventsBatch"
    ]

    resources = [
      "arn:aws:logs:*:*:log-group:*"
    ]
  }
}

# CloudWatch Log Resource Policy
resource "aws_cloudwatch_log_resource_policy" "elasticsearch_log_publishing" {
  policy_name     = "elasticsearch-log-publishing-policy"
  policy_document = data.aws_iam_policy_document.elasticsearch_log_publishing_policy.json
}

output "service_linked_role_arn" {
  description = "The ARN of the Elasticsearch service-linked role."
  value       = aws_iam_service_linked_role.es.arn
}

output "log_resource_policy_name" {
  description = "The name of the CloudWatch log resource policy."
  value       = aws_cloudwatch_log_resource_policy.elasticsearch_log_publishing.policy_name
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Cognito User Pool named "identity pool"
resource "aws_cognito_user_pool" "pool" {
  name = "identity pool"
}

# IAM Role for the Cognito User Group
resource "aws_iam_role" "user_group_role" {
  name = "user-group-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = "us-east-1:12345678-dead-beef-cafe-123456790ab"
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "authenticated"
          }
        }
      }
    ]
  })
}

# Cognito User Group attached to the User Pool and IAM Role
resource "aws_cognito_user_group" "user_group" {
  name         = "user-group"
  user_pool_id = aws_cognito_user_pool.pool.id
  description  = "Managed by Terraform"
  precedence   = 42
  role_arn     = aws_iam_role.user_group_role.arn
}

output "user_pool_id" {
  description = "The ID of the Cognito User Pool"
  value       = aws_cognito_user_pool.pool.id
}

output "user_group_role_arn" {
  description = "The ARN of the IAM role assigned to the user group"
  value       = aws_iam_role.user_group_role.arn
}

output "user_group_name" {
  description = "The name of the Cognito User Group"
  value       = aws_cognito_user_group.user_group.name
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

# Standard AWS Provider alias with standard default tags
provider "aws" {
  alias  = "standard"
  region = var.aws_region

  default_tags {
    tags = {
      Environment = "Standard"
      ManagedBy   = "Terraform"
      ProviderSet = "standard"
    }
  }
}

# Alternate AWS Provider alias with alternate default tags
provider "aws" {
  alias  = "alt-tags"
  region = var.aws_region

  default_tags {
    tags = {
      Environment = "Alternate"
      ManagedBy   = "Terraform"
      ProviderSet = "alt-tags"
    }
  }
}

# First DynamoDB table using standard provider
resource "aws_dynamodb_table" "basic" {
  provider     = aws.standard
  name         = "default-and-alternate-tags-module-basic"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "KeyId"

  attribute {
    name = "KeyId"
    type = "S"
  }

  tags = {
    ResourceName = "default-and-alternate-tags-module-basic"
  }
}

# Second DynamoDB table using alternate provider
resource "aws_dynamodb_table" "alternate" {
  provider     = aws.alt-tags
  name         = "default-and-alternate-tags-module-alternate"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "KeyId"

  attribute {
    name = "KeyId"
    type = "S"
  }

  tags = {
    ResourceName = "default-and-alternate-tags-module-alternate"
  }
}

output "basic_table_arn" {
  description = "ARN of the basic DynamoDB table"
  value       = aws_dynamodb_table.basic.arn
}

output "alternate_table_arn" {
  description = "ARN of the alternate DynamoDB table"
  value       = aws_dynamodb_table.alternate.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy the API Gateway"
  default     = "us-east-1"
}

variable "api_name" {
  type        = string
  description = "The name of the API Gateway REST API"
  default     = "terraform-api-gateway-example"
}

# 1. API Gateway REST API
resource "aws_api_gateway_rest_api" "movies_api" {
  name        = var.api_name
  description = "API Gateway for testing mock web endpoint responses"

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

# 2. Resource /movies
resource "aws_api_gateway_resource" "movies_resource" {
  rest_api_id = aws_api_gateway_rest_api.movies_api.id
  parent_id   = aws_api_gateway_rest_api.movies_api.root_resource_id
  path_part   = "movies"
}

# 3. GET Method on /movies
resource "aws_api_gateway_method" "movies_get_method" {
  rest_api_id   = aws_api_gateway_rest_api.movies_api.id
  resource_id   = aws_api_gateway_resource.movies_resource.id
  http_method   = "GET"
  authorization = "NONE"
}

# 4. MOCK Integration for GET /movies
resource "aws_api_gateway_integration" "movies_mock_integration" {
  rest_api_id = aws_api_gateway_rest_api.movies_api.id
  resource_id = aws_api_gateway_resource.movies_resource.id
  http_method = aws_api_gateway_method.movies_get_method.http_method
  type        = "MOCK"

  request_templates = {
    "application/json" = "{\"statusCode\": 200}"
  }
}

# 5. Method Response for 200
resource "aws_api_gateway_method_response" "movies_method_response_200" {
  rest_api_id = aws_api_gateway_rest_api.movies_api.id
  resource_id = aws_api_gateway_resource.movies_resource.id
  http_method = aws_api_gateway_method.movies_get_method.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

# 6. Integration Response for 200
resource "aws_api_gateway_integration_response" "movies_integration_response_200" {
  rest_api_id = aws_api_gateway_rest_api.movies_api.id
  resource_id = aws_api_gateway_resource.movies_resource.id
  http_method = aws_api_gateway_method.movies_get_method.http_method
  status_code = aws_api_gateway_method_response.movies_method_response_200.status_code

  response_templates = {
    "application/json" = "{\"message\": \"Hello from the movies API!\"}"
  }

  depends_on = [
    aws_api_gateway_integration.movies_mock_integration
  ]
}

# 7. Deployment and Stage
resource "aws_api_gateway_deployment" "movies_deployment" {
  rest_api_id = aws_api_gateway_rest_api.movies_api.id

  depends_on = [
    aws_api_gateway_integration.movies_mock_integration,
    aws_api_gateway_integration_response.movies_integration_response_200,
    aws_api_gateway_method_response.movies_method_response_200
  ]

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "movies_stage" {
  deployment_id = aws_api_gateway_deployment.movies_deployment.id
  rest_api_id   = aws_api_gateway_rest_api.movies_api.id
  stage_name    = "dev"
}

output "endpoint_url" {
  description = "The invocation URL for the GET /movies endpoint"
  value       = "${aws_api_gateway_stage.movies_stage.invoke_url}/movies"
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# Variable Definitions
variable "aws_region" {
  type        = string
  description = "The AWS region to deploy resources to."
  default     = "us-east-1"
}

variable "alias_name" {
  type        = string
  description = "The suffix for the KMS key alias (prepended with alias/)."
  default     = "kms-cmk-example"
}

# Data sources to fetch caller information
data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# IAM Key Policy granting kms:* permissions exclusively to the current caller identity
data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableCallerFullKmsPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
    }
  }
}

# AWS KMS Customer Managed Key
resource "aws_kms_key" "example" {
  description             = "Customer Managed Key created for testing purposes"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = {
    Environment = "Testing"
    ManagedBy   = "Terraform"
  }
}

# AWS KMS Key Alias
resource "aws_kms_alias" "example" {
  name          = "alias/${var.alias_name}"
  target_key_id = aws_kms_key.example.key_id
}

# Outputs
output "kms_key_arn" {
  description = "The ARN of the KMS key."
  value       = aws_kms_key.example.arn
}

output "kms_key_id" {
  description = "The globally unique identifier for the key."
  value       = aws_kms_key.example.key_id
}

output "kms_alias_arn" {
  description = "The ARN of the KMS key alias."
  value       = aws_kms_alias.example.arn
}

output "kms_alias_name" {
  description = "The display name of the KMS key alias."
  value       = aws_kms_alias.example.name
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Provider configuration for US East (N. Virginia)
provider "aws" {
  alias  = "us-east-nv"
  region = "us-east-1"

  default_tags {
    tags = {
      Terraform = "yes"
      Region    = "N.Virginia"
    }
  }
}

# Provider configuration for AP South (Mumbai)
provider "aws" {
  alias  = "ap-south-mumbai"
  region = "ap-south-1"

  default_tags {
    tags = {
      Terraform = "yes"
      Region    = "Mumbai"
    }
