}

output "mumbai_vpc_cidr" {
  description = "The CIDR block of the Mumbai VPC"
  value       = aws_vpc.mumbai_vpc.cidr_block
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region for resources"
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# Lookup default VPC for security group association
data "aws_vpc" "default" {
  default = true
}

# 1. Security group for TCP traffic on port 10000
resource "aws_security_group" "allow_tcp" {
  name        = "allow_tcp"
  description = "Allow TCP traffic"
  vpc_id      = data.aws_vpc.default.id

  egress {
    description = "Allow outbound TCP traffic on port 10000"
    from_port   = 10000
    to_port     = 10000
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow_tcp"
  }
}

# 2. Security group for UDP traffic on port 10000
resource "aws_security_group" "allow_udp" {
  name        = "allow_udp"
  description = "Allow UDP traffic"
  vpc_id      = data.aws_vpc.default.id

  egress {
    description = "Allow outbound UDP traffic on port 10000"
    from_port   = 10000
    to_port     = 10000
    protocol    = "udp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow_udp"
  }
}

# 3. Security group for ICMP traffic on port 10000
resource "aws_security_group" "allow_icmp" {
  name        = "allow_icmp"
  description = "Allow ICMP traffic"
  vpc_id      = data.aws_vpc.default.id

  egress {
    description = "Allow outbound ICMP traffic on port 10000"
    from_port   = 10000
    to_port     = 10000
    protocol    = "icmp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow_icmp"
  }
}

# 4. Security group for ALL traffic on port 0
resource "aws_security_group" "allow_all" {
  name        = "allow_all"
  description = "Allow ALL traffic"
  vpc_id      = data.aws_vpc.default.id

  egress {
    description = "Allow outbound ALL traffic on port 0"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "allow_all"
  }
}

output "allow_tcp_sg_id" {
  description = "ID of the allow_tcp security group"
  value       = aws_security_group.allow_tcp.id
}

output "allow_udp_sg_id" {
  description = "ID of the allow_udp security group"
  value       = aws_security_group.allow_udp.id
}

output "allow_icmp_sg_id" {
  description = "ID of the allow_icmp security group"
  value       = aws_security_group.allow_icmp.id
}

output "allow_all_sg_id" {
  description = "ID of the allow_all security group"
  value       = aws_security_group.allow_all.id
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region where resources will be deployed"
  default     = "us-east-1"
}

variable "bucket_prefix" {
  type        = string
  description = "Prefix for the remote state S3 bucket"
  default     = "terraform-state"
}

provider "aws" {
  region = var.aws_region
}

# Current AWS caller identity for KMS policy definition
data "aws_caller_identity" "current" {}

# Random suffix to ensure globally unique S3 bucket name
resource "random_id" "bucket_suffix" {
  byte_length = 6
}

# -----------------------------------------------------------------------------
# KMS Customer Managed Key
# -----------------------------------------------------------------------------
resource "aws_kms_key" "terraform_state_key" {
  description             = "Dedicated KMS key for Terraform state S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "terraform-state-key-policy"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name        = "terraform-state-kms-key"
    Environment = "Management"
  }
}

resource "aws_kms_alias" "terraform_state_key_alias" {
  name          = "alias/terraform-state-key"
  target_key_id = aws_kms_key.terraform_state_key.key_id
}

# -----------------------------------------------------------------------------
# S3 Bucket for Terraform State
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "terraform_state" {
  bucket        = "${var.bucket_prefix}-${random_id.bucket_suffix.hex}"
  force_destroy = false

  tags = {
    Name        = "terraform-state-bucket"
    Environment = "Management"
  }
}

# S3 Bucket Versioning
resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

# S3 Bucket Default Encryption with KMS CMK
resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.terraform_state_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# S3 Bucket Public Access Block
resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# DynamoDB Table for State Locking
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "terraform_locks" {
  name         = "terraform-lock"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  tags = {
    Name        = "terraform-lock"
    Environment = "Management"
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "s3_bucket_name" {
  description = "The name of the S3 bucket used for Terraform state storage"
  value       = aws_s3_bucket.terraform_state.id
}

output "s3_bucket_arn" {
  description = "The ARN of the S3 bucket used for Terraform state storage"
  value       = aws_s3_bucket.terraform_state.arn
}

output "dynamodb_table_name" {
  description = "The name of the DynamoDB table used for state locking"
  value       = aws_dynamodb_table.terraform_locks.name
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used to encrypt the S3 state bucket"
  value       = aws_kms_key.terraform_state_key.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "The AWS region to deploy resources in."
  default     = "us-east-1"
}

variable "allowed_regions" {
  type        = list(string)
  description = "List of AWS regions where network interface IP assignments are permitted."
  default     = ["*"]
}

# Fetch current AWS account details
data "aws_caller_identity" "current" {}

# IAM Policy Document for PowerScale Node Runtime
data "aws_iam_policy_document" "powerscale_node_runtime" {
  statement {
    sid       = "AllowAssignPrivateIpAddresses"
    effect    = "Allow"
    actions   = ["ec2:AssignPrivateIpAddresses"]
    resources = [
      for region in var.allowed_regions :
      "arn:aws:ec2:${region}:${data.aws_caller_identity.current.account_id}:network-interface/*"
    ]
  }
}

# IAM Policy
resource "aws_iam_policy" "powerscale_node_runtime" {
  name        = "${data.aws_caller_identity.current.account_id}-powerscale-node-runtime-policy"
  description = "Policy for PowerScale node runtime EC2 instances to assign private IP addresses."
  policy      = data.aws_iam_policy_document.powerscale_node_runtime.json
}

# Trust Policy Document for EC2 Role
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# IAM Role
resource "aws_iam_role" "powerscale_node_runtime" {
  name               = "${data.aws_caller_identity.current.account_id}-powerscale-node-runtime-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  description        = "IAM role assumed by EC2 instances running PowerScale node runtime operations."
}

# Policy Attachment
resource "aws_iam_role_policy_attachment" "powerscale_node_runtime" {
  role       = aws_iam_role.powerscale_node_runtime.name
  policy_arn = aws_iam_policy.powerscale_node_runtime.arn
}

# IAM Instance Profile
resource "aws_iam_instance_profile" "powerscale_node_runtime" {
  name = "${data.aws_caller_identity.current.account_id}-powerscale-node-runtime-instance-profile"
  role = aws_iam_role.powerscale_node_runtime.name
}

output "instance_profile_arn" {
  description = "ARN of the created IAM instance profile."
  value       = aws_iam_instance_profile.powerscale_node_runtime.arn
}

output "instance_profile_name" {
  description = "Name of the created IAM instance profile."
  value       = aws_iam_instance_profile.powerscale_node_runtime.name
}

output "iam_role_arn" {
  description = "ARN of the created IAM role."
  value       = aws_iam_role.powerscale_node_runtime.arn
}

output "iam_policy_arn" {
  description = "ARN of the created IAM policy."
  value       = aws_iam_policy.powerscale_node_runtime.arn
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "The AWS region to deploy resources into."
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "The CIDR block for the custom VPC."
  default     = "192.168.0.0/16"
}

variable "environment" {
  type        = string
  description = "Deployment environment name."
  default     = "production"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# VPC Resource
# -----------------------------------------------------------------------------
resource "aws_vpc" "custom_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "custom-tiered-vpc"
    Environment = var.environment
  }
}

# -----------------------------------------------------------------------------
# Internet Gateway
# -----------------------------------------------------------------------------
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.custom_vpc.id

  tags = {
    Name        = "custom-vpc-igw"
    Environment = var.environment
  }
}

# -----------------------------------------------------------------------------
# Subnets
# Sequentially carved /24 subnets:
# 192.168.0.0/24 -> web  (AZ 0)
# 192.168.1.0/24 -> app  (AZ 1)
# 192.168.2.0/24 -> db   (AZ 2)
# 192.168.3.0/24 -> mgmt (AZ 0 - shares AZ with web)
# -----------------------------------------------------------------------------
resource "aws_subnet" "web" {
  vpc_id                  = aws_vpc.custom_vpc.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 0)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name        = "subnet-web"
    Tier        = "web"
    Environment = var.environment
  }
}

resource "aws_subnet" "app" {
  vpc_id            = aws_vpc.custom_vpc.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 1)
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name        = "subnet-app"
    Tier        = "app"
    Environment = var.environment
  }
}

resource "aws_subnet" "db" {
  vpc_id            = aws_vpc.custom_vpc.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 2)
  availability_zone = data.aws_availability_zones.available.names[2]

  tags = {
    Name        = "subnet-db"
    Tier        = "db"
    Environment = var.environment
  }
}

resource "aws_subnet" "mgmt" {
  vpc_id            = aws_vpc.custom_vpc.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 3)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name        = "subnet-mgmt"
    Tier        = "mgmt"
    Environment = var.environment
  }
}

# -----------------------------------------------------------------------------
# Route Tables & Associations
# -----------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.custom_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name        = "web-public-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "web_assoc" {
  subnet_id      = aws_subnet.web.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the custom VPC"
  value       = aws_vpc.custom_vpc.id
}

output "web_subnet_id" {
  description = "The ID and CIDR of the Web subnet"
  value       = { id = aws_subnet.web.id, cidr = aws_subnet.web.cidr_block, az = aws_subnet.web.availability_zone }
}

output "app_subnet_id" {
  description = "The ID and CIDR of the App subnet"
  value       = { id = aws_subnet.app.id, cidr = aws_subnet.app.cidr_block, az = aws_subnet.app.availability_zone }
}

output "db_subnet_id" {
  description = "The ID and CIDR of the DB subnet"
  value       = { id = aws_subnet.db.id, cidr = aws_subnet.db.cidr_block, az = aws_subnet.db.availability_zone }
}

output "mgmt_subnet_id" {
  description = "The ID and CIDR of the Mgmt subnet"
  value       = { id = aws_subnet.mgmt.id, cidr = aws_subnet.mgmt.cidr_block, az = aws_subnet.mgmt.availability_zone }
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources in"
  default     = "us-east-1"
}

variable "user_name" {
  type        = string
  description = "The name of the IAM user"
  default     = "TJ"
}

variable "policy_name" {
  type        = string
  description = "The name of the custom IAM policy"
  default     = "GlacierEFSEC2"
}

# IAM User
resource "aws_iam_user" "tj" {
  name = var.user_name

  tags = {
    Name = var.user_name
  }
}

# IAM Policy Document
data "aws_iam_policy_document" "glacier_efs_ec2" {
  statement {
    sid    = "EC2ManagementPermissions"
    effect = "Allow"
    actions = [
      "ec2:*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "EFSClientMountAccess"
    effect = "Allow"
    actions = [
      "elasticfilesystem:ClientMount",
      "elasticfilesystem:ClientRead"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "GlacierVaultAndMultipartUploadPermissions"
    effect = "Allow"
    actions = [
      "glacier:CreateVault",
      "glacier:DescribeVault",
      "glacier:ListVaults",
      "glacier:InitiateMultipartUpload",
      "glacier:UploadMultipartPart",
      "glacier:CompleteMultipartUpload",
      "glacier:AbortMultipartUpload",
      "glacier:ListParts",
      "glacier:ListMultipartUploads"
    ]
    resources = ["*"]
  }
}

# Custom IAM Policy
resource "aws_iam_policy" "glacier_efs_ec2" {
  name        = var.policy_name
  description = "Allows broad EC2 management along with EFS client-mount access and Glacier vault/multipart-upload management."
  policy      = data.aws_iam_policy_document.glacier_efs_ec2.json
}

# Attach IAM Policy to IAM User
resource "aws_iam_user_policy_attachment" "tj_glacier_efs_ec2_attach" {
  user       = aws_iam_user.tj.name
  policy_arn = aws_iam_policy.glacier_efs_ec2.arn
}

output "user_arn" {
  description = "The ARN of the created IAM user"
  value       = aws_iam_user.tj.arn
}

output "policy_arn" {
  description = "The ARN of the custom IAM policy"
  value       = aws_iam_policy.glacier_efs_ec2.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# Variable Definitions
variable "aws_region" {
  type        = string
  description = "The AWS region to deploy resources into."
  default     = "us-east-1"
}

variable "role_name" {
  type        = string
  description = "Name of the IAM role and instance profile."
  default     = "ec2-workload-role"
}

variable "role_description" {
  type        = string
  description = "Description for the IAM role."
  default     = "IAM role assumed by EC2 instances."
}

variable "managed_policy_arns" {
  type        = list(string)
  description = "List of IAM managed policy ARNs to attach to the role."
  default = [
    "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
  ]
}

variable "inline_policies" {
  type        = map(string)
  description = "Map of inline policy names to valid JSON policy documents."
  default     = {}
}

variable "tags" {
  type        = map(string)
  description = "A mapping of tags to assign to resources."
  default = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

# Data Sources
data "aws_partition" "current" {}

# Trust Policy Document
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type = "Service"
      # Automatically constructs ec2.<dns_suffix>, handling commercial, govcloud, and china partitions
      identifiers = ["ec2.${data.aws_partition.current.dns_suffix}"]
    }
  }
}

# IAM Role
resource "aws_iam_role" "this" {
  name               = var.role_name
  description        = var.role_description
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = var.tags
}

# Managed Policy Attachments
resource "aws_iam_role_policy_attachment" "managed_policies" {
  for_each   = toset(var.managed_policy_arns)
  role       = aws_iam_role.this.name
  policy_arn = each.value
}

# Inline Policies
resource "aws_iam_role_policy" "inline_policies" {
  for_each = var.inline_policies
  name     = each.key
  role     = aws_iam_role.this.id
  policy   = each.value
}

# IAM Instance Profile
resource "aws_iam_instance_profile" "this" {
  name = var.role_name
  role = aws_iam_role.this.name
  tags = var.tags
}

# Outputs
output "role_name" {
  description = "The name of the IAM role."
  value       = aws_iam_role.this.name
}

output "role_arn" {
  description = "The ARN of the IAM role."
  value       = aws_iam_role.this.arn
}

output "instance_profile_name" {
  description = "The name of the IAM instance profile."
  value       = aws_iam_instance_profile.this.name
}

output "instance_profile_arn" {
  description = "The ARN of the IAM instance profile."
  value       = aws_iam_instance_profile.this.arn
}

