terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region where resources are defined."
  type        = string
  default     = "us-east-1"
}

variable "workspace_name" {
  description = "Name of the Grafana workspace."
  type        = string
  default     = "Grafana"
}

variable "trusted_monitoring_account_ids" {
  description = "List of AWS Account IDs permitted to assume this role for Grafana monitoring."
  type        = list(string)
  default     = ["123456789012"] # Replace with your target monitoring AWS account ID
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM ROLE & TRUST POLICY
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "grafana_assume_role_policy" {
  statement {
    sid     = "AllowAssumeRoleFromMonitoringAccounts"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [for account_id in var.trusted_monitoring_account_ids : "arn:aws:iam::${account_id}:root"]
    }
  }

  statement {
    sid     = "AllowGrafanaServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["grafana.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "grafana_query_role" {
  name                 = "${var.workspace_name}-Prometheus-CloudWatch-AccessRole"
  description          = "IAM Role for ${var.workspace_name} to query CloudWatch metrics and Amazon Managed Service for Prometheus."
  assume_role_policy   = data.aws_iam_policy_document.grafana_assume_role_policy.json

  tags = {
    Name        = "${var.workspace_name}-AccessRole"
    Application = var.workspace_name
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM PERMISSION POLICY
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "grafana_metrics_query_policy" {
  # Permissions for CloudWatch Metrics
  statement {
    sid    = "CloudWatchMetricsReadAccess"
    effect = "Allow"
    actions = [
      "cloudwatch:DescribeAlarmsForMetric",
      "cloudwatch:DescribeAlarmHistory",
      "cloudwatch:DescribeAlarms",
      "cloudwatch:ListMetrics",
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchLogsInsightsQueryAccess"
    effect = "Allow"
    actions = [
      "logs:DescribeLogGroups",
      "logs:GetLogGroupFields",
      "logs:StartQuery",
      "logs:StopQuery",
      "logs:GetQueryResults",
      "logs:GetLogEvents"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "EC2AndTagReadAccess"
    effect = "Allow"
    actions = [
      "ec2:DescribeTags",
      "ec2:DescribeInstances",
      "ec2:DescribeRegions",
      "tag:GetResources"
    ]
    resources = ["*"]
  }

  # Permissions for Amazon Managed Service for Prometheus (AMP)
  statement {
    sid    = "AmazonPrometheusQueryAccess"
    effect = "Allow"
    actions = [
      "aps:QueryMetrics",
      "aps:GetMetricMetadata",
      "aps:GetSeries",
      "aps:GetLabels",
      "aps:DescribeWorkspace"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "grafana_metrics_query_policy" {
  name        = "${var.workspace_name}-Prometheus-CloudWatch-Policy"
  description = "Custom policy granting query access to CloudWatch and Amazon Managed Service for Prometheus for ${var.workspace_name}."
  policy      = data.aws_iam_policy_document.grafana_metrics_query_policy.json

  tags = {
    Name        = "${var.workspace_name}-Policy"
    Application = var.workspace_name
  }
}

resource "aws_iam_role_policy_attachment" "grafana_query_attachment" {
  role       = aws_iam_role.grafana_query_role.name
  policy_arn = aws_iam_policy.grafana_metrics_query_policy.arn
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "iam_role_arn" {
  description = "ARN of the IAM role to configure in AWS Managed Grafana or monitoring accounts."
  value       = aws_iam_role.grafana_query_role.arn
}

output "iam_policy_arn" {
  description = "ARN of the attached IAM query policy."
  value       = aws_iam_policy.grafana_metrics_query_policy.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region where resources will be deployed"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "The CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for the subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

provider "aws" {
  region = variable.aws_region
}

# Fetch available availability zones in the current region
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC Configuration
resource "aws_vpc" "main" {
  cidr_block           = variable.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "test-vpc"
  }
}

# Subnet 1
resource "aws_subnet" "subnet_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = variable.subnet_cidrs[0]
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "test-subnet-1"
  }
}

# Subnet 2
resource "aws_subnet" "subnet_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = variable.subnet_cidrs[1]
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "test-subnet-2"
  }
}

# Outputs
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "subnet_1_id" {
  description = "The ID of Subnet 1"
  value       = aws_subnet.subnet_1.id
}

output "subnet_2_id" {
  description = "The ID of Subnet 2"
  value       = aws_subnet.subnet_2.id
}

output "subnet_1_cidr" {
  description = "The CIDR block of Subnet 1"
  value       = aws_subnet.subnet_1.cidr_block
}

output "subnet_2_cidr" {
  description = "The CIDR block of Subnet 2"
  value       = aws_subnet.subnet_2.cidr_block
}

output "private_subnets" {
  description = "List of private subnet IDs"
  value       = [aws_subnet.subnet_1.id, aws_subnet.subnet_2.id]
}

output "private_subnet_cidrs" {
  description = "List of private subnet CIDR blocks"
  value       = [aws_subnet.subnet_1.cidr_block, aws_subnet.subnet_2.cidr_block]
}

output "public_subnets" {
  description = "List of public subnet IDs (mirrors the created subnets)"
  value       = [aws_subnet.subnet_1.id, aws_subnet.subnet_2.id]
}

output "public_subnet_cidrs" {
  description = "List of public subnet CIDR blocks (mirrors the created subnets)"
  value       = [aws_subnet.subnet_1.cidr_block, aws_subnet.subnet_2.cidr_block]
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for public subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for private subnets"
  default     = ["10.0.10.0/24", "10.0.20.0/24"]
}

provider "aws" {
  region = var.aws_region
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC Definition
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name        = "trade-tariff-development-vpc"
    Environment = "development"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "trade-tariff-development-igw"
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "trade-tariff-development-public-subnet-${count.index + 1}"
    Type = "Public"
  }
}

# Private Subnets
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "trade-tariff-development-private-subnet-${count.index + 1}"
    Type = "Private"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.igw]

  tags = {
    Name = "trade-tariff-development-nat-eip"
  }
}

# NAT Gateway
resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "trade-tariff-development-nat-gw"
  }

  depends_on = [aws_internet_gateway.igw]
}

# Route Table for Public Subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "trade-tariff-development-public-rt"
  }
}

# Route Table for Private Subnets
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "trade-tariff-development-private-rt"
  }
}

# Route Table Associations for Public Subnets
resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Route Table Associations for Private Subnets
resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security Group: allow-ssh
resource "aws_security_group" "allow_ssh" {
  name        = "allow-ssh"
  description = "Allows inbound SSH and outbound traffic only within the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from anywhere"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic only within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "allow-ssh"
  }
}

# Outputs
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "nat_gateway_ip" {
  description = "Public IP of the NAT Gateway"
  value       = aws_eip.nat.public_ip
}

output "security_group_id" {
  description = "The ID of the allow-ssh security group"
  value       = aws_security_group.allow_ssh.id
}

```terraform
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region where resources will be deployed."
  type        = string
  default     = "us-east-1"
}

variable "repository_name" {
  description = "The name of the ECR repository."
  type        = string
  default     = "app-container-repo"
}

variable "image_tag_mutability" {
  description = "The tag mutability setting for the repository. Must be one of: MUTABLE or IMMUTABLE."
  type        = string
  default     = "IMMUTABLE"
}

variable "scan_on_push" {
  description = "Indicates whether images are scanned after being pushed to the repository."
  type        = bool
  default     = true
}

variable "kms_key_arn" {
  description = "The ARN of the KMS key to use for encryption. If null/empty, AES256 encryption is used."
  type        = string
  default     = null
}

variable "allowed_read_principals" {
  description = "List of AWS Principal ARNs (e.g. IAM Roles, Users, or AWS Accounts) that are allowed to pull images. If empty, no custom policy is applied."
  type        = list(string)
  default     = []
}

variable "enable_lifecycle_policy" {
  description = "Whether to create a lifecycle policy for the repository."
  type        = bool
  default     = true
}

variable "max_untagged_image_age_days" {
  description = "Number of days before untagged images are expired by the lifecycle policy."
  type        = number
  default     = 14
}

variable "max_tagged_image_count" {
  description = "Maximum number of tagged images to keep in the repository."
  type        = number
  default     = 30
}

# ---------------------------------------------------------------------------------------------------------------------
# ECR REPOSITORY
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_ecr_repository" "this" {
  name                 = var.repository_name
  image_tag_mutability = var.image_tag_mutability

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  encryption_configuration {
    encryption_type = var.kms_key_arn != null && var.kms_key_arn != "" ? "KMS" : "AES256"
    kms_key         = var.kms_key_arn != null && var.kms_key_arn != "" ? var.kms_key_arn : null
  }

  tags = {
    Name        = var.repository_name
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# REPOSITORY ACCESS POLICY (OPTIONAL)
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "read_policy" {
  count = length(var.allowed_read_principals) > 0 ? 1 : 0

  statement {
    sid    = "AllowPullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = var.allowed_read_principals
    }

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:GetDownloadUrlForLayer"
    ]
  }
}

resource "aws_ecr_repository_policy" "this" {
  count      = length(var.allowed_read_principals) > 0 ? 1 : 0
  repository = aws_ecr_repository.this.name
  policy     = data.aws_iam_policy_document.read_policy[0].json
}

# ---------------------------------------------------------------------------------------------------------------------
# REPOSITORY LIFECYCLE POLICY (OPTIONAL)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_ecr_lifecycle_policy" "this" {
  count      = var.enable_lifecycle_policy ? 1 : 0
  repository = aws_ecr_repository.this.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images older than ${var.max_untagged_image_age_days} days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = var.max_untagged_image_age_days
        }
        action = {
          type = "expire"
        }
      },
      {
        rulePriority = 2
        description  = "Keep only the last ${var.max_tagged_image_count} tagged images"
        selection = {
          tagStatus   = "any"
          countType   = "imageCountMoreThan"
          countNumber = var.max_tagged_image_count
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "repository_arn" {
  description = "The ARN of the ECR repository."
  value       = aws_ecr_repository.this.arn
}

output "repository_url" {
  description = "The URL of the repository (in the form aws_account_id.dkr.ecr.region.amazonaws.com/repositoryName)."
  value       = aws_ecr_repository.this.repository_url
}

output "repository_registry_id" {
  description = "The registry ID where the repository was created."
  value       = aws_ecr_repository.this.registry_id
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  description = "The AWS region where resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Deployment environment name (e.g., dev, staging, prod)."
  type        = string
  default     = "prod"
}

variable "project_name" {
  description = "Project or service name for naming and tagging purposes."
  type        = string
  default     = "app-service"
}

variable "queue_base_name" {
  description = "Base name for the SQS queue."
  type        = string
  default     = "notifications"
}

variable "is_fifo_queue" {
  description = "Boolean flag indicating whether to create a FIFO queue."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues."
  type        = bool
  default     = false
}

variable "visibility_timeout_seconds" {
  description = "The visibility timeout for the queue in seconds."
  type        = number
  default     = 30
}

variable "message_retention_seconds" {
  description = "The number of seconds Amazon SQS retains a message."
  type        = number
  default     = 345600 # 4 days
}

variable "max_message_size" {
  description = "The limit of how many bytes a message can contain before Amazon SQS rejects it."
  type        = number
  default     = 262144 # 256 KB
}

variable "delay_seconds" {
  description = "The time in seconds that the delivery of all messages in the queue will be delayed."
  type        = number
  default     = 0
}

variable "receive_wait_time_seconds" {
  description = "The time for which a ReceiveMessage call will wait for a message to arrive (long polling)."
  type        = number
  default     = 0
}

variable "authorized_sender_principal_arn" {
  description = "Optional AWS Principal ARN (IAM Role/User/Account) to allow sending messages to the queue. If blank, no custom queue policy is applied."
  type        = string
  default     = ""
}

variable "additional_tags" {
  description = "Additional tags to apply to the resources."
  type        = map(string)
  default     = {}
}

# -----------------------------------------------------------------------------
# Local Values for Standardized Naming and Tagging
# -----------------------------------------------------------------------------
locals {
  # Build a standardized base name
  raw_name = "${var.project_name}-${var.environment}-${var.queue_base_name}"

  # Append .fifo if it's a FIFO queue
  queue_name = var.is_fifo_queue ? "${local.raw_name}.fifo" : local.raw_name

  # Standard tagging convention
  standard_tags = merge(
    {
      "Environment" = var.environment
      "Project"     = var.project_name
      "ManagedBy"   = "Terraform"
    },
    var.additional_tags
  )
}

# -----------------------------------------------------------------------------
# SQS Queue Resource
# -----------------------------------------------------------------------------
resource "aws_sqs_queue" "this" {
  name                        = local.queue_name
  fifo_queue                  = var.is_fifo_queue
  content_based_deduplication = var.is_fifo_queue ? var.content_based_deduplication : false

  visibility_timeout_seconds = var.visibility_timeout_seconds
  message_retention_seconds  = var.message_retention_seconds
  max_message_size           = var.max_message_size
  delay_seconds              = var.delay_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds

  tags = local.standard_tags
}

# -----------------------------------------------------------------------------
# SQS Queue Access Policy (Optional)
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "sender_policy" {
  count = var.authorized_sender_principal_arn != "" ? 1 : 0

  statement {
    sid       = "AllowAuthorizedPrincipalToSend"
    effect    = "Allow"
    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.this.arn]

    principals {
      type        = "AWS"
      identifiers = [var.authorized_sender_principal_arn]
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count     = var.authorized_sender_principal_arn != "" ? 1 : 0
  queue_url = aws_sqs_queue.this.id
  policy    = data.aws_iam_policy_document.sender_policy[0].json
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "queue_id" {
  description = "The URL for the created Amazon SQS queue."
  value       = aws_sqs_queue.this.id
}

output "queue_arn" {
  description = "The ARN of the Amazon SQS queue."
  value       = aws_sqs_queue.this.arn
}

output "queue_name" {
  description = "The name of the Amazon SQS queue."
  value       = aws_sqs_queue.this.name
}

output "is_fifo" {
  description = "Indicates whether the queue is configured as FIFO."
  value       = aws_sqs_queue.this.fifo_queue
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.80.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be provisioned."
  type        = string
  default     = "us-east-1"
}

variable "cluster_name" {
  description = "A friendly name tag or identifier for the Aurora DSQL cluster."
  type        = string
  default     = "my-dsql-cluster"
}

variable "deletion_protection_enabled" {
  description = "Controls whether deletion protection is enabled on the DSQL cluster."
  type        = bool
  default     = false
}

variable "kms_key_arn" {
  description = "ARN of the KMS customer managed key used for cluster encryption. If null, AWS managed key is used."
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags to assign to the DSQL cluster resources."
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

# Peering configuration
variable "enable_peering" {
  description = "Whether to provision DSQL cluster peering connections."
  type        = bool
  default     = false
}

variable "peer_cluster_identifiers" {
  description = "List of target DSQL cluster identifiers/ARNs to peer with."
  type        = list(string)
  default     = []
}

variable "witness_region" {
  description = "Optional witness region for cluster peering replication/quorum."
  type        = string
  default     = null
}

variable "peering_create_timeout" {
  description = "Custom timeout for cluster peering creation (e.g., '30m', '1h')."
  type        = string
  default     = "30m"
}

# Main Aurora DSQL Cluster
resource "aws_dsql_cluster" "primary" {
  deletion_protection_enabled = var.deletion_protection_enabled
  kms_key_arn                 = var.kms_key_arn

  tags = merge(
    var.tags,
    {
      Name = var.cluster_name
    }
  )
}

# Optional Cluster Peering Relationships
# Configured only when enable_peering is true and target clusters are provided
resource "aws_dsql_cluster_peering" "peering" {
  for_each = var.enable_peering ? toset(var.peer_cluster_identifiers) : []

  cluster_id      = aws_dsql_cluster.primary.id
  peer_cluster_id = each.value
  witness_region  = var.witness_region

  timeouts {
    create = var.peering_create_timeout
  }
}

# Outputs
output "cluster_id" {
  description = "The ID of the Aurora DSQL cluster."
  value       = aws_dsql_cluster.primary.id
}

output "cluster_arn" {
  description = "The ARN of the Aurora DSQL cluster."
  value       = aws_dsql_cluster.primary.arn
}

output "peering_ids" {
  description = "The IDs of the provisioned cluster peerings."
  value       = { for k, v in aws_dsql_cluster_peering.peering : k => v.id }
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# --- Variables ---

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources in."
  default     = "us-east-1"
}

variable "bucket_name" {
  type        = string
  description = "The name of the S3 bucket. Must be globally unique."
  default     = "my-customizable-secure-bucket-tf-example"
}

variable "force_destroy" {
  type        = bool
  description = "A boolean that indicates all objects should be deleted from the bucket so that the bucket can be destroyed without error. Defaults to false."
  default     = false
}

variable "object_lock_enabled" {
  type        = bool
  description = "Indicates whether this bucket has an Object Lock configuration enabled."
  default     = false
}

variable "tags" {
  type        = map(string)
  description = "A map of tags to assign to the bucket and related resources."
  default = {
    Environment = "Production"
    ManagedBy   = "Terraform"
  }
}

variable "custom_policy_statements" {
  type = list(object({
    sid       = optional(string)
    effect    = optional(string, "Allow")
    actions   = list(string)
    resources = optional(list(string))
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })), [])
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })), [])
  }))
  description = "List of custom policy statements to apply to the S3 bucket. If empty, no custom policy is applied."
  default     = []
}

# --- Data Sources ---

data "aws_caller_identity" "current" {}

# --- KMS Key for S3 Encryption ---

resource "aws_kms_key" "s3_kms_key" {
  description             = "Customer managed KMS key for S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "kms-s3-key-policy"
    Statement = [
      {
        Sid    = "EnableRootIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = var.tags
}

resource "aws_kms_alias" "s3_kms_key_alias" {
  name          = "alias/${var.bucket_name}-key"
  target_key_id = aws_kms_key.s3_kms_key.key_id
}

# --- S3 Bucket Resources ---

resource "aws_s3_bucket" "this" {
  bucket              = var.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = var.tags
}

# Block all public access to the bucket
resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Configure default encryption using the Customer Managed KMS Key
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_kms_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# --- Dynamic Custom Bucket Policy ---

data "aws_iam_policy_document" "custom_policy" {
  count = length(var.custom_policy_statements) > 0 ? 1 : 0

  dynamic "statement" {
    for_each = var.custom_policy_statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect != null ? statement.value.effect : "Allow"
      actions   = statement.value.actions
      resources = length(coalesce(statement.value.resources, [])) > 0 ? statement.value.resources : [
        aws_s3_bucket.this.arn,
        "${aws_s3_bucket.this.arn}/*"
      ]

      dynamic "principals" {
        for_each = statement.value.principals
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count  = length(var.custom_policy_statements) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.custom_policy[0].json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

# --- Outputs ---

output "bucket_id" {
  description = "The name of the bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the bucket."
  value       = aws_s3_bucket.this.arn
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used for encrypting bucket objects."
  value       = aws_kms_key.s3_kms_key.arn
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region to deploy the resources."
  type        = string
  default     = "us-east-1"
}

variable "create" {
  description = "Whether to create the SNS topic and associated resources."
  type        = bool
  default     = true
}

variable "name" {
  description = "The name of the SNS topic. If omitted, Terraform will assign a random name or use name_prefix."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "Prefix for the SNS topic name. Conflicts with name."
  type        = string
  default     = "sns-versatile-"
}

variable "display_name" {
  description = "The display name for the SNS topic."
  type        = string
  default     = "NotificationTopic"
}

variable "fifo_topic" {
  description = "Boolean indicating whether or not to create a FIFO (first-in-first-out) topic."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO topics."
  type        = bool
  default     = false
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SNS or a custom CMK."
  type        = string
  default     = "alias/aws/sns"
}

variable "signature_version" {
  description = "Signature version for message authentication."
  type        = number
  default     = 2
}

variable "tracing_config" {
  description = "Tracing mode of an Amazon SNS topic. Valid values: PassThrough, Active."
  type        = string
  default     = null
}

# Delivery feedback settings
variable "enable_feedback_roles" {
  description = "Whether to automatically create IAM roles for CloudWatch delivery feedback."
  type        = bool
  default     = true
}

variable "feedback_failure_sample_rate" {
  description = "Percentage of delivery failure events to log to CloudWatch."
  type        = number
  default     = 100
}

variable "feedback_success_sample_rate" {
  description = "Percentage of delivery success events to log to CloudWatch."
  type        = number
  default     = 0
}

# Policy Configuration
variable "enable_topic_policy" {
  description = "Whether to attach an IAM resource policy to the topic."
  type        = bool
  default     = true
}

variable "allowed_aws_services_for_publishing" {
  description = "List of AWS Service principals allowed to publish to the topic (e.g. s3.amazonaws.com)."
  type        = list(string)
  default     = []
}

variable "custom_topic_policy_json" {
  description = "A fully custom policy JSON document to apply. If set, replaces auto-generated statements."
  type        = string
  default     = null
}

# Subscriptions
variable "subscriptions" {
  description = "Map of SNS topic subscriptions to create."
  type = map(object({
    protocol                        = string
    endpoint                        = string
    endpoint_auto_confirms          = optional(bool, false)
    raw_message_delivery            = optional(bool, false)
    filter_policy                   = optional(string, null)
    filter_policy_scope             = optional(string, null)
    confirmation_timeout_in_minutes = optional(number, null)
    redrive_policy                  = optional(string, null)
  }))
  default = {}
}

variable "tags" {
  description = "A mapping of tags to assign to all resources."
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES
# ---------------------------------------------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# ---------------------------------------------------------------------------------------------------------------------
# IAM ROLES FOR FEEDBACK (CLOUDWATCH)
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "sns_assume_role" {
  count = var.create && var.enable_feedback_roles ? 1 : 0

  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "feedback" {
  count              = var.create && var.enable_feedback_roles ? 1 : 0
  name_prefix        = "sns-feedback-"
  assume_role_policy = data.aws_iam_policy_document.sns_assume_role[0].json
  tags               = var.tags
}

data "aws_iam_policy_document" "feedback_logs" {
  count = var.create && var.enable_feedback_roles ? 1 : 0

  statement {
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:PutMetricFilter",
      "logs:PutRetentionPolicy"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "feedback_logs" {
  count  = var.create && var.enable_feedback_roles ? 1 : 0
  name   = "sns-cloudwatch-delivery-logs"
  role   = aws_iam_role.feedback[0].id
  policy = data.aws_iam_policy_document.feedback_logs[0].json
}

# ---------------------------------------------------------------------------------------------------------------------
# SNS TOPIC
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_sns_topic" "this" {
  count = var.create ? 1 : 0

  name        = var.name
  name_prefix = var.name == null ? var.name_prefix : null

  display_name                = var.display_name
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : null
  kms_master_key_id           = var.kms_master_key_id
  signature_version           = var.signature_version
  tracing_config              = var.tracing_config

  # Feedback Configurations
  http_success_feedback_role_arn    = var.enable_feedback_roles ? aws_iam_role.feedback[0].arn : null
  http_success_feedback_sample_rate = var.enable_feedback_roles ? var.feedback_success_sample_rate : null
  http_failure_feedback_role_arn    = var.enable_feedback_roles ? aws_iam_role.feedback[0].arn : null

  lambda_success_feedback_role_arn    = var.enable_feedback_roles ? aws_iam_role.feedback[0].arn : null
  lambda_success_feedback_sample_rate = var.enable_feedback_roles ? var.feedback_success_sample_rate : null
  lambda_failure_feedback_role_arn    = var.enable_feedback_roles ? aws_iam_role.feedback[0].arn : null

  sqs_success_feedback_role_arn    = var.enable_feedback_roles ? aws_iam_role.feedback[0].arn : null
  sqs_success_feedback_sample_rate = var.enable_feedback_roles ? var.feedback_success_sample_rate : null
  sqs_failure_feedback_role_arn    = var.enable_feedback_roles ? aws_iam_role.feedback[0].arn : null

  firehose_success_feedback_role_arn    = var.enable_feedback_roles ? aws_iam_role.feedback[0].arn : null
  firehose_success_feedback_sample_rate = var.enable_feedback_roles ? var.feedback_success_sample_rate : null
  firehose_failure_feedback_role_arn    = var.enable_feedback_roles ? aws_iam_role.feedback[0].arn : null

  application_success_feedback_role_arn    = var.enable_feedback_roles ? aws_iam_role.feedback[0].arn : null
  application_success_feedback_sample_rate = var.enable_feedback_roles ? var.feedback_success_sample_rate : null
  application_failure_feedback_role_arn    = var.enable_feedback_roles ? aws_iam_role.feedback[0].arn : null

  tags = var.tags
}

# ---------------------------------------------------------------------------------------------------------------------
# TOPIC POLICY
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "default" {
  count = var.create && var.enable_topic_policy && var.custom_topic_policy_json == null ? 1 : 0

  statement {
    sid    = "__default_statement_ID"
    effect = "Allow"

    actions = [
      "SNS:GetTopicAttributes",
      "SNS:SetTopicAttributes",
      "SNS:AddPermission",
      "SNS:RemovePermission",
      "SNS:DeleteTopic",
      "SNS:Subscribe",
      "SNS:ListSubscriptionsByTopic",
      "SNS:Publish"
    ]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    resources = [aws_sns_topic.this[0].arn]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceOwner"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  dynamic "statement" {
    for_each = length(var.allowed_aws_services_for_publishing) > 0 ? [1] : []
    content {
      sid    = "AllowServicesToPublish"
      effect = "Allow"
      actions = [
        "sns:Publish"
      ]
      principals {
        type        = "Service"
        identifiers = var.allowed_aws_services_for_publishing
      }
      resources = [aws_sns_topic.this[0].arn]
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = var.create && var.enable_topic_policy ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.custom_topic_policy_json != null ? var.custom_topic_policy_json : data.aws_iam_policy_document.default[0].json
}

# ---------------------------------------------------------------------------------------------------------------------
# TOPIC SUBSCRIPTIONS
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_sns_topic_subscription" "this" {
  for_each = var.create ? var.subscriptions : {}

  topic_arn                       = aws_sns_topic.this[0].arn
  protocol                        = each.value.protocol
  endpoint                        = each.value.endpoint
  endpoint_auto_confirms          = each.value.endpoint_auto_confirms
  raw_message_delivery            = each.value.raw_message_delivery
  filter_policy                   = each.value.filter_policy
  filter_policy_scope             = each.value.filter_policy_scope
  confirmation_timeout_in_minutes = each.value.confirmation_timeout_in_minutes
  redrive_policy                  = each.value.redrive_policy
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "topic_arn" {
  description = "The ARN of the SNS topic."
  value       = try(aws_sns_topic.this[0].arn, null)
}

output "topic_id" {
  description = "The ID of the SNS topic."
  value       = try(aws_sns_topic.this[0].id, null)
}

output "topic_name" {
  description = "The name of the SNS topic."
  value       = try(aws_sns_topic.this[0].name, null)
}

output "topic_beginning_delivery_feedback_role_arn" {
  description = "IAM Role ARN configured for CloudWatch delivery feedback."
  value       = try(aws_iam_role.feedback[0].arn, null)
}

output "subscriptions" {
  description = "Map of created subscription resources."
  value       = aws_sns_topic_subscription.this
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region for resources"
  default     = "us-east-1"
}

# Fetch available availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# 1. VPC Configuration
resource "aws_vpc" "ansible_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "ansible-vpc"
  }
}

# 2. Internet Gateway
resource "aws_internet_gateway" "ansible_vpc_igw" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = {
    Name = "ansible-vpc-igw"
  }
}

# 3. Subnets
resource "aws_subnet" "private_subnet" {
  vpc_id                  = aws_vpc.ansible_vpc.id
  cidr_block              = "10.0.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "ansible-vpc-private-subnet-1"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.ansible_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "ansible-vpc-public-subnet-1"
  }
}

# 4. Route Tables
resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.ansible_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ansible_vpc_igw.id
  }

  tags = {
    Name = "ansible-vpc-public-rt"
  }
}

resource "aws_route_table" "private_rt" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = {
    Name = "ansible-vpc-private-rt"
  }
}

# 5. Route Table Associations
resource "aws_route_table_association" "public_assoc" {
  subnet_id      = aws_subnet.public_subnet.id
  route_table_id = aws_route_table.public_rt.id
}

resource "aws_route_table_association" "private_assoc" {
  subnet_id      = aws_subnet.private_subnet.id
  route_table_id = aws_route_table.private_rt.id
}

# Outputs
output "vpc_id" {
  description = "The ID of the created VPC"
  value       = aws_vpc.ansible_vpc.id
}

output "public_subnet_id" {
  description = "The ID of the public subnet"
  value       = aws_subnet.public_subnet.id
}

output "private_subnet_id" {
  description = "The ID of the private subnet"
  value       = aws_subnet.private_subnet.id
}

output "internet_gateway_id" {
  description = "The ID of the Internet Gateway"
  value       = aws_internet_gateway.ansible_vpc_igw.id
}

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

variable "tgw_name" {
  type        = string
  description = "Name tag for the Transit Gateway"
  default     = "central-transit-gateway"
}

variable "tgw_amazon_side_asn" {
  type        = number
  description = "Private Autonomous System Number (ASN) for the Transit Gateway"
  default     = 64512
}

variable "vpc_a_cidr" {
  type        = string
  description = "CIDR block for VPC A"
  default     = "10.10.0.0/16"
}

variable "vpc_b_cidr" {
  type        = string
  description = "CIDR block for VPC B"
  default     = "10.20.0.0/16"
}

# ---------------------------------------------------------------------------------------------------------------------
# TRANSIT GATEWAY
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_ec2_transit_gateway" "central_tgw" {
  description                     = "Central Transit Gateway for inter-VPC routing"
  amazon_side_asn                 = var.tgw_amazon_side_asn
  auto_accept_shared_attachments  = "enable"
  default_route_table_association = "enable"
  default_route_table_propagation = "enable"
  dns_support                     = "enable"
  vpn_ecmp_support                = "enable"

  tags = {
    Name        = var.tgw_name
    Environment = "production"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# VPC A CONFIGURATION
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_vpc" "vpc_a" {
  cidr_block           = var.vpc_a_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "tgw-spoke-vpc-a"
  }
}

resource "aws_subnet" "vpc_a_subnets" {
  count             = 2
  vpc_id            = aws_vpc.vpc_a.id
  cidr_block        = cidrsubnet(var.vpc_a_cidr, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "vpc-a-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "vpc_a_rt" {
  vpc_id = aws_vpc.vpc_a.id

  tags = {
    Name = "vpc-a-route-table"
  }
}

resource "aws_route_table_association" "vpc_a_assoc" {
  count          = 2
  subnet_id      = aws_subnet.vpc_a_subnets[count.index].id
  route_table_id = aws_route_table.vpc_a_rt.id
}

# Route from VPC A to VPC B via Transit Gateway
resource "aws_route" "vpc_a_to_vpc_b" {
  route_table_id         = aws_route_table.vpc_a_rt.id
  destination_cidr_block = var.vpc_b_cidr
  transit_gateway_id     = aws_ec2_transit_gateway.central_tgw.id
}

# ---------------------------------------------------------------------------------------------------------------------
# VPC B CONFIGURATION
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_vpc" "vpc_b" {
  cidr_block           = var.vpc_b_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "tgw-spoke-vpc-b"
  }
}

resource "aws_subnet" "vpc_b_subnets" {
  count             = 2
  vpc_id            = aws_vpc.vpc_b.id
  cidr_block        = cidrsubnet(var.vpc_b_cidr, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "vpc-b-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "vpc_b_rt" {
  vpc_id = aws_vpc.vpc_b.id

  tags = {
    Name = "vpc-b-route-table"
  }
}

resource "aws_route_table_association" "vpc_b_assoc" {
  count          = 2
  subnet_id      = aws_subnet.vpc_b_subnets[count.index].id
  route_table_id = aws_route_table.vpc_b_rt.id
}

# Route from VPC B to VPC A via Transit Gateway
resource "aws_route" "vpc_b_to_vpc_a" {
  route_table_id         = aws_route_table.vpc_b_rt.id
  destination_cidr_block = var.vpc_a_cidr
  transit_gateway_id     = aws_ec2_transit_gateway.central_tgw.id
}

# ---------------------------------------------------------------------------------------------------------------------
# TRANSIT GATEWAY ATTACHMENTS (DYNAMIC MAP-BASED CONFIGURATION)
# ---------------------------------------------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  # Map defining VPCs and their associated subnet IDs to attach to the Transit Gateway
  tgw_attachments = {
    "vpc-a" = {
      vpc_id     = aws_vpc.vpc_a.id
      subnet_ids = aws_subnet.vpc_a_subnets[*].id
    }
    "vpc-b" = {
      vpc_id     = aws_vpc.vpc_b.id
      subnet_ids = aws_subnet.vpc_b_subnets[*].id
    }
  }
}

resource "aws_ec2_transit_gateway_vpc_attachment" "tgw_attachments" {
  for_each = local.tgw_attachments

  transit_gateway_id = aws_ec2_transit_gateway.central_tgw.id
  vpc_id             = each.value.vpc_id
  subnet_ids         = each.value.subnet_ids

  dns_support  = "enable"
  ipv6_support = "disable"

  tags = {
    Name = "tgw-attachment-${each.key}"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "transit_gateway_id" {
  description = "The ID of the Transit Gateway"
  value       = aws_ec2_transit_gateway.central_tgw.id
}

output "transit_gateway_arn" {
  description = "The ARN of the Transit Gateway"
  value       = aws_ec2_transit_gateway.central_tgw.arn
}

output "transit_gateway_vpc_attachment_ids" {
  description = "Map of Transit Gateway VPC attachment IDs"
  value       = { for k, v in aws_ec2_transit_gateway_vpc_attachment.tgw_attachments : k => v.id }
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy the resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  type        = string
  description = "CIDR block for the subnet"
  default     = "10.0.0.0/24"
}

# 1. VPC Configuration
resource "aws_vpc" "ecs_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "ecs-fargate-vpc"
  }
}

# 2. Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.ecs_vpc.id

  tags = {
    Name = "ecs-fargate-igw"
  }
}

# 3. Subnet (Does not auto-assign public IP addresses)
resource "aws_subnet" "ecs_subnet" {
  vpc_id                  = aws_vpc.ecs_vpc.id
  cidr_block              = var.subnet_cidr
  map_public_ip_on_launch = false

  tags = {
    Name = "ecs-fargate-subnet"
  }
}

# 4. Route Table and Association
resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.ecs_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "ecs-fargate-rt"
  }
}

resource "aws_route_table_association" "subnet_association" {
  subnet_id      = aws_subnet.ecs_subnet.id
  route_table_id = aws_route_table.public_route_table.id
}

# 5. Security Group allowing outbound access only within the VPC CIDR
resource "aws_security_group" "ecs_fargate_sg" {
  name        = "dragondrop-compute-ecs-fargate-sg"
  description = "Security group for ECS Fargate tasks allowing egress only within VPC"
  vpc_id      = aws_vpc.ecs_vpc.id

  egress {
    description = "Allow outbound traffic only within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "dragondrop-compute-ecs-fargate-sg"
  }
}

output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.ecs_vpc.id
}

output "subnet_id" {
  description = "The ID of the Subnet"
  value       = aws_subnet.ecs_subnet.id
}

output "security_group_id" {
  description = "The ID of the ECS Fargate Security Group"
  value       = aws_security_group.ecs_fargate_sg.id
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
