provider "aws" {
  region = var.aws_region
}

# Raw Metrics Table
resource "aws_dynamodb_table" "raw_metrics" {
  name         = "raw_metrics"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "uuid"

  stream_enabled   = true
  stream_view_type = "NEW_IMAGE"

  attribute {
    name = "uuid"
    type = "S"
  }

  ttl {
    attribute_name = "expdate"
    enabled        = true
  }

  server_side_encryption {
    enabled = true
  }

  tags = {
    Name        = "raw_metrics"
    Environment = "production"
  }
}

# Aggregate Metrics Table
resource "aws_dynamodb_table" "aggregate_metrics" {
  name         = "aggregate_metrics"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"
  range_key    = "sk"

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  attribute {
    name = "identifier"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled = true
  }

  global_secondary_index {
    name            = "IdentifierIndex"
    hash_key        = "identifier"
    projection_type = "ALL"
  }

  tags = {
    Name        = "aggregate_metrics"
    Environment = "production"
  }
}

output "raw_metrics_table_arn" {
  description = "The ARN of the raw_metrics DynamoDB table"
  value       = aws_dynamodb_table.raw_metrics.arn
}

output "raw_metrics_stream_arn" {
  description = "The ARN of the DynamoDB stream for raw_metrics"
  value       = aws_dynamodb_table.raw_metrics.stream_arn
}

output "aggregate_metrics_table_arn" {
  description = "The ARN of the aggregate_metrics DynamoDB table"
  value       = aws_dynamodb_table.aggregate_metrics.arn
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "aws_region" {
  description = "The AWS region where resources will be created"
  type        = string
  default     = "us-east-1"
}

variable "server_name" {
  description = "Name tag for the web server and associated resources"
  type        = string
  default     = "demo"
}

variable "instance_type" {
  description = "EC2 instance type for the Apache web server"
  type        = string
  default     = "t3.micro"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the subnet"
  type        = string
  default     = "10.0.1.0/24"
}

# -----------------------------------------------------------------------------
# VPC and Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.server_name}-vpc"
  }
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.server_name}-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.server_name}-subnet"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = {
    Name = "${var.server_name}-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Security Group
# -----------------------------------------------------------------------------

resource "aws_security_group" "web_sg" {
  name        = "${var.server_name}-web-sg"
  description = "Allow HTTP inbound from anywhere and egress to VPC CIDR only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow outbound traffic only within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.server_name}-sg"
  }
}

# -----------------------------------------------------------------------------
# AMI Lookup
# -----------------------------------------------------------------------------

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# -----------------------------------------------------------------------------
# EC2 Instance & Elastic IP
# -----------------------------------------------------------------------------

resource "aws_instance" "web" {
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = var.instance_type
  subnet_id              = aws_subnet.public.id
  vpc_security_group_ids = [aws_security_group.web_sg.id]

  # Enforce IMDSv2
  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  # Encrypted root block device
  root_block_device {
    encrypted   = true
    volume_type = "gp2"
  }

  # User data to install and start Apache
  user_data = <<-EOF
              #!/bin/bash
              yum update -y
              yum install -y httpd
              systemctl start httpd
              systemctl enable httpd
              echo "<h1>Hello from ${var.server_name} web server!</h1>" > /var/www/html/index.html
              EOF

  tags = {
    Name = var.server_name
  }
}

resource "aws_eip" "web" {
  instance = aws_instance.web.id
  domain   = "vpc"

  depends_on = [aws_internet_gateway.gw]

  tags = {
    Name = "${var.server_name}-eip"
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "public_ip" {
  description = "The Elastic IP address assigned to the web server"
  value       = aws_eip.web.public_ip
}

output "web_server_url" {
  description = "HTTP URL to access the Apache web server"
  value       = "http://${aws_eip.web.public_ip}"
}
```

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

data "aws_caller_identity" "current" {}

# Customer-Managed KMS Key for SNS Encryption
resource "aws_kms_key" "sns_kms_key" {
  description             = "Customer-managed KMS key for SNS topics encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "sns-kms-key-policy"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow SNS Service to Use the Key"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name        = "sns-kms-key"
    Environment = "Testing"
  }
}

resource "aws_kms_alias" "sns_kms_key_alias" {
  name          = "alias/sns-integration-test-key"
  target_key_id = aws_kms_key.sns_kms_key.key_id
}

# SNS Topic 1: my-topic-with-policy
resource "aws_sns_topic" "topic_with_policy" {
  name              = "my-topic-with-policy"
  kms_master_key_id = aws_kms_key.sns_kms_key.id

  tags = {
    Name        = "my-topic-with-policy"
    Environment = "Testing"
  }
}

# SNS Topic 2: my-topic-with-policy2
resource "aws_sns_topic" "topic_with_policy2" {
  name              = "my-topic-with-policy2"
  kms_master_key_id = aws_kms_key.sns_kms_key.id

  tags = {
    Name        = "my-topic-with-policy2"
    Environment = "Testing"
  }
}

# SNS Topic 3: user-updates-topic with custom delivery policy
resource "aws_sns_topic" "user_updates_topic" {
  name              = "user-updates-topic"
  kms_master_key_id = aws_kms_key.sns_kms_key.id

  delivery_policy = jsonencode({
    http = {
      defaultHealthyRetryPolicy = {
        minDelayTarget     = 20
        maxDelayTarget     = 20
        numRetries         = 3
        numMaxDelayRetries = 0
        numNoDelayRetries  = 0
        numMinDelayRetries = 0
        backoffFunction    = "linear"
      }
      disableSubscriptionOverrides = false
      defaultThrottlePolicy = {
        maxReceivesPerSecond = 10
      }
    }
  })

  tags = {
    Name        = "user-updates-topic"
    Environment = "Testing"
  }
}

# Shared SNS Topic Policy for my-topic-with-policy
resource "aws_sns_topic_policy" "shared_policy" {
  arn = aws_sns_topic.topic_with_policy.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "shared-sns-policy"
    Statement = [
      {
        Sid       = "AllowAllPrincipalsSNSActions"
        Effect    = "Allow"
        Principal = "*"
        Action    = "sns:*"
        Resource  = aws_sns_topic.topic_with_policy.arn
      }
    ]
  })
}

# Output ARNs for verification
output "kms_key_arn" {
  description = "The ARN of the KMS key used to encrypt the SNS topics"
  value       = aws_kms_key.sns_kms_key.arn
}

output "topic_with_policy_arn" {
  description = "ARN of the my-topic-with-policy topic"
  value       = aws_sns_topic.topic_with_policy.arn
}

output "topic_with_policy2_arn" {
  description = "ARN of the my-topic-with-policy2 topic"
  value       = aws_sns_topic.topic_with_policy2.arn
}

output "user_updates_topic_arn" {
  description = "ARN of the user-updates-topic"
  value       = aws_sns_topic.user_updates_topic.arn
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# Fetch availability zones in the region
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC Configuration
resource "aws_vpc" "main" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "test-vpc"
  }
}

# Internet Gateway for public access
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "test-igw"
  }
}

# Public Subnet
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "test-public-subnet"
  }
}

# Private Subnet
resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "192.168.4.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "test-private-subnet"
  }
}

# Route Table for Public Subnet
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "test-public-rt"
  }
}

# Route Table Association for Public Subnet
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Route Table for Private Subnet
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "test-private-rt"
  }
}

# Route Table Association for Private Subnet
resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

# Standalone Elastic IP
resource "aws_eip" "test_eip" {
  domain = "vpc"

  tags = {
    Name = "test-standalone-eip"
  }
}

# Outputs
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "The ID of the public subnet"
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "The ID of the private subnet"
  value       = aws_subnet.private.id
}

output "standalone_eip" {
  description = "The public IP of the standalone Elastic IP"
  value       = aws_eip.test_eip.public_ip
}

output "standalone_eip_allocation_id" {
  description = "The Allocation ID of the standalone Elastic IP"
  value       = aws_eip.test_eip.id
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# --------------------------------------------------------------------------------------------------
# Variables
# --------------------------------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for public subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for private subnets"
  default     = ["10.0.10.0/24", "10.0.20.0/24"]
}

variable "namespace_name" {
  type        = string
  description = "Name for the private service discovery DNS namespace"
  default     = "service.local"
}

# --------------------------------------------------------------------------------------------------
# Data Sources
# --------------------------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# --------------------------------------------------------------------------------------------------
# VPC and Gateways
# --------------------------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "app-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "app-igw"
  }
}

# --------------------------------------------------------------------------------------------------
# Subnets
# --------------------------------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "app-public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "app-private-subnet-${count.index + 1}"
  }
}

# --------------------------------------------------------------------------------------------------
# NAT Gateway
# --------------------------------------------------------------------------------------------------
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "app-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "app-nat-gateway"
  }

  depends_on = [aws_internet_gateway.main]
}

# --------------------------------------------------------------------------------------------------
# Route Tables and Associations
# --------------------------------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "app-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "app-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# --------------------------------------------------------------------------------------------------
# Security Group
# --------------------------------------------------------------------------------------------------
resource "aws_security_group" "app_sg" {
  name        = "app-sg"
  description = "Security group for application containers and VPC traffic"
  vpc_id      = aws_vpc.main.id

  # Inbound SSH limited to VPC CIDR
  ingress {
    description = "SSH from within VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  # Inbound HTTP from anywhere
  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Inbound HTTPS from anywhere
  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Inbound Port 3000 from anywhere
  ingress {
    description = "App port 3000 from anywhere"
    from_port   = 3000
    to_port     = 3000
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Inbound PostgreSQL port 5432 from anywhere
  ingress {
    description = "PostgreSQL port 5432 from anywhere"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Outbound limited to VPC CIDR
  egress {
    description = "Allow all outbound traffic only to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "app-sg"
  }
}

# --------------------------------------------------------------------------------------------------
# Private Service Discovery Namespace
# --------------------------------------------------------------------------------------------------
resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = var.namespace_name
  description = "Private DNS namespace for containerized application service discovery"
  vpc         = aws_vpc.main.id

  tags = {
    Name = "app-service-discovery-namespace"
  }
}

# --------------------------------------------------------------------------------------------------
# Outputs
# --------------------------------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "List of public subnet IDs"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "List of private subnet IDs"
  value       = aws_subnet.private[*].id
}

output "security_group_id" {
  description = "The ID of the application security group"
  value       = aws_security_group.app_sg.id
}

output "service_discovery_namespace_id" {
  description = "The ID of the private service discovery namespace"
  value       = aws_service_discovery_private_dns_namespace.main.id
}

output "service_discovery_namespace_arn" {
  description = "The ARN of the private service discovery namespace"
  value       = aws_service_discovery_private_dns_namespace.main.arn
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "The AWS region to deploy the backup infrastructure into."
  default     = "us-east-1"
}

variable "vault_name" {
  type        = string
  description = "The name of the AWS Backup Vault."
  default     = "benchmark-backup-vault"
}

variable "backup_plan_name" {
  type        = string
  description = "The name of the AWS Backup Plan."
  default     = "benchmark-backup-plan"
}

variable "backup_tag_key" {
  type        = string
  description = "Tag key used to select resources for backup."
  default     = "benchmark-backup"
}

variable "backup_tag_value" {
  type        = string
  description = "Tag value used to select resources for backup."
  default     = "true"
}

variable "min_retention_days" {
  type        = number
  description = "Minimum retention days enforced by Backup Vault Lock."
  default     = 7
}

variable "max_retention_days" {
  type        = number
  description = "Maximum retention days enforced by Backup Vault Lock."
  default     = 90
}

variable "target_retention_days" {
  type        = number
  description = "Number of days the backup plan rule retains recovery points."
  default     = 30
}

# -----------------------------------------------------------------------------
# Current AWS Account & Region Context
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# AWS KMS Customer Managed Key for AWS Backup Vault
# -----------------------------------------------------------------------------
resource "aws_kms_key" "backup" {
  description             = "KMS key used to encrypt the benchmark backup vault"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "backup-kms-key-policy"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowAWSBackupUsage"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = [
          "kms:DescribeKey",
          "kms:GenerateDataKey",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "benchmark-backup-key"
  }
}

resource "aws_kms_alias" "backup" {
  name          = "alias/benchmark-backup-key"
  target_key_id = aws_kms_key.backup.key_id
}

# -----------------------------------------------------------------------------
# AWS Backup Vault & Vault Lock Configuration
# -----------------------------------------------------------------------------
resource "aws_backup_vault" "vault" {
  name        = var.vault_name
  kms_key_arn = aws_kms_key.backup.arn

  tags = {
    Name = var.vault_name
  }
}

resource "aws_backup_vault_lock_configuration" "vault_lock" {
  backup_vault_name   = aws_backup_vault.vault.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  # Omitting changeable_for_days keeps the lock in governance mode so it can be managed by Terraform
}

# -----------------------------------------------------------------------------
# IAM Role and Policies for AWS Backup Service
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup_role" {
  name               = "benchmark-backup-service-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = {
    Name = "benchmark-backup-service-role"
  }
}

resource "aws_iam_role_policy_attachment" "backup_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
  role       = aws_iam_role.backup_role.name
}

resource "aws_iam_role_policy_attachment" "backup_restores" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
  role       = aws_iam_role.backup_role.name
}

# -----------------------------------------------------------------------------
# AWS Backup Plan & Rule
# -----------------------------------------------------------------------------
resource "aws_backup_plan" "plan" {
  name = var.backup_plan_name

  rule {
    rule_name         = "daily-backup-rule"
    target_vault_name = aws_backup_vault.vault.name
    # Runs daily at 05:00 UTC
    schedule          = "cron(0 5 ? * * *)"

    start_window      = 60
    completion_window = 180

    lifecycle {
      delete_after = var.target_retention_days
    }
  }

  tags = {
    Name = var.backup_plan_name
  }
}

# -----------------------------------------------------------------------------
# AWS Backup Selection (Tag-Based)
# -----------------------------------------------------------------------------
resource "aws_backup_selection" "selection" {
  iam_role_arn = aws_iam_role.backup_role.arn
  name         = "benchmark-tag-selection"
  plan_id      = aws_backup_plan.plan.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = var.backup_tag_value
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "backup_vault_name" {
  description = "The name of the AWS Backup Vault."
  value       = aws_backup_vault.vault.name
}

output "backup_vault_arn" {
  description = "The ARN of the AWS Backup Vault."
  value       = aws_backup_vault.vault.arn
}

output "backup_plan_id" {
  description = "The ID of the AWS Backup Plan."
  value       = aws_backup_plan.plan.id
}

output "backup_kms_key_arn" {
  description = "The ARN of the KMS Key encrypting the Backup Vault."
  value       = aws_kms_key.backup.arn
}

output "backup_role_arn" {
  description = "The ARN of the IAM role used by AWS Backup."
  value       = aws_iam_role.backup_role.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

variable "aws_region" {
  description = "The AWS region where resources will be deployed"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Deployment environment name"
  type        = string
  default     = "dev"
}

provider "aws" {
  region = var.aws_region
}

# 1. Cognito User Pool
resource "aws_cognito_user_pool" "pool" {
  name = "${var.environment}-user-pool"

  auto_verified_attributes = ["email"]
  username_attributes      = ["email"]

  password_policy {
    minimum_length    = 8
    require_lowercase = true
    require_numbers   = true
    require_symbols   = false
    require_uppercase = true
  }

  verification_message_template {
    default_email_option = "CONFIRM_WITH_CODE"
  }
}

# 2. Cognito User Pool Client
resource "aws_cognito_user_pool_client" "client" {
  name         = "${var.environment}-user-pool-client"
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret                      = false
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code", "implicit"]
  allowed_oauth_scopes                 = ["email", "openid", "profile"]
  supported_identity_providers         = ["COGNITO"]
  callback_urls                        = ["https://localhost:3000/callback"]
}

# 3. Cognito Identity Pool
resource "aws_cognito_identity_pool" "identity_pool" {
  identity_pool_name               = "${replace(var.environment, "-", "_")}_identity_pool"
  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.client.id
    provider_name           = aws_cognito_user_pool.pool.endpoint
    server_side_token_check = false
  }
}

# 4. IAM Role for Authenticated Identities
resource "aws_iam_role" "authenticated" {
  name = "${var.environment}-cognito-authenticated-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.identity_pool.id
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "authenticated"
          }
        }
      }
    ]
  })
}

# 5. IAM Policy for Cognito Sync and Mobile Analytics Access
resource "aws_iam_role_policy" "authenticated" {
  name = "${var.environment}-cognito-authenticated-policy"
  role = aws_iam_role.authenticated.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "mobileanalytics:PutEvents",
          "cognito-sync:*"
        ]
        Resource = ["*"]
      }
    ]
  })
}

# 6. Attach Role to Identity Pool
resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.identity_pool.id

  roles = {
    authenticated = aws_iam_role.authenticated.arn
  }
}

# Outputs
output "user_pool_id" {
  description = "The ID of the Cognito User Pool"
  value       = aws_cognito_user_pool.pool.id
}

output "user_pool_client_id" {
  description = "The ID of the Cognito User Pool Client"
  value       = aws_cognito_user_pool_client.client.id
}

output "identity_pool_id" {
  description = "The ID of the Cognito Identity Pool"
  value       = aws_cognito_identity_pool.identity_pool.id
}

output "authenticated_role_arn" {
  description = "The ARN of the IAM role assumed by authenticated identities"
  value       = aws_iam_role.authenticated.arn
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "The AWS region to deploy the resources in."
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the custom VPC."
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  type        = string
  description = "CIDR block for the subnet."
  default     = "10.0.1.0/24"
}

# 1. Custom VPC
resource "aws_vpc" "custom_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "custom-test-vpc"
    Environment = "test"
  }
}

# 2. Subnet without auto-assign public IPs
resource "aws_subnet" "custom_subnet" {
  vpc_id                  = aws_vpc.custom_vpc.id
  cidr_block              = var.subnet_cidr
  map_public_ip_on_launch = false

  tags = {
    Name        = "custom-test-subnet"
    Environment = "test"
  }
}

# 3. Internet Gateway
resource "aws_internet_gateway" "custom_igw" {
  vpc_id = aws_vpc.custom_vpc.id

  tags = {
    Name        = "custom-test-igw"
    Environment = "test"
  }
}

# 4. Elastic IP
resource "aws_eip" "custom_eip" {
  domain = "vpc"

  tags = {
    Name        = "custom-test-eip"
    Environment = "test"
  }
}

# 5. DHCP Options Set with standard public DNS servers
resource "aws_vpc_dhcp_options" "custom_dhcp_options" {
  domain_name_servers = ["8.8.8.8", "8.8.4.4"]

  tags = {
    Name        = "custom-test-dhcp-options"
    Environment = "test"
  }
}

# Associate DHCP Options Set with the VPC
resource "aws_vpc_dhcp_options_association" "custom_dhcp_assoc" {
  vpc_id          = aws_vpc.custom_vpc.id
  dhcp_options_id = aws_vpc_dhcp_options.custom_dhcp_options.id
}

# 6. Default Security Group with restricted ingress and egress
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.custom_vpc.id

  # Ingress: HTTP (port 80) from VPC CIDR
  ingress {
    description = "Allow HTTP from within VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  # Ingress: HTTPS (port 443) from VPC CIDR
  ingress {
    description = "Allow HTTPS from within VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  # Ingress: SSH (port 22) from VPC CIDR
  ingress {
    description = "Allow SSH from within VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  # Egress: Restrict outbound traffic only to the VPC CIDR
  egress {
    description = "Allow all outbound traffic only within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name        = "custom-test-default-sg"
    Environment = "test"
  }
}

output "vpc_id" {
  description = "The ID of the custom VPC"
  value       = aws_vpc.custom_vpc.id
}

output "subnet_id" {
  description = "The ID of the subnet"
  value       = aws_subnet.custom_subnet.id
}

output "internet_gateway_id" {
  description = "The ID of the Internet Gateway"
  value       = aws_internet_gateway.custom_igw.id
}

output "elastic_ip" {
  description = "The allocated Elastic IP address"
  value       = aws_eip.custom_eip.public_ip
}

output "default_security_group_id" {
  description = "The ID of the default security group"
  value       = aws_default_security_group.default.id
}
```

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources in"
  type        = string
  default     = "us-east-1"
}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# KMS Customer Managed Key for SNS Encryption
# -----------------------------------------------------------------------------
resource "aws_kms_key" "sns_key" {
  description             = "KMS Key for event-topic SNS encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowAPIGatewayRole"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.apigw_sns_role.arn
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sns_key_alias" {
  name          = "alias/event-topic-key"
  target_key_id = aws_kms_key.sns_key.key_id
}

# -----------------------------------------------------------------------------
# SNS Topic
# -----------------------------------------------------------------------------
resource "aws_sns_topic" "event_topic" {
  name              = "event-topic"
  kms_master_key_id = aws_kms_key.sns_key.id
}

# -----------------------------------------------------------------------------
# IAM Role and Policy for API Gateway to Publish to SNS
# -----------------------------------------------------------------------------
resource "aws_iam_role" "apigw_sns_role" {
  name = "api-gateway-sns-publish-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "apigw_sns_policy" {
  name        = "api-gateway-sns-publish-policy"
  description = "Allow API Gateway to publish messages to event-topic and use KMS key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sns:Publish"
        Resource = aws_sns_topic.event_topic.arn
      },
      {
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = aws_kms_key.sns_key.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "apigw_sns_attach" {
  role       = aws_iam_role.apigw_sns_role.name
  policy_arn = aws_iam_policy.apigw_sns_policy.arn
}

# -----------------------------------------------------------------------------
# API Gateway REST API
# -----------------------------------------------------------------------------
resource "aws_api_gateway_rest_api" "event_api" {
  name        = "event-api"
  description = "REST API to publish events to SNS"

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_api_gateway_resource" "events_resource" {
  rest_api_id = aws_api_gateway_rest_api.event_api.id
  parent_id   = aws_api_gateway_rest_api.event_api.root_resource_id
  path_part   = "events"
}

resource "aws_api_gateway_method" "post_event" {
  rest_api_id   = aws_api_gateway_rest_api.event_api.id
  resource_id   = aws_api_gateway_resource.events_resource.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "sns_integration" {
  rest_api_id             = aws_api_gateway_rest_api.event_api.id
  resource_id             = aws_api_gateway_resource.events_resource.id
  http_method             = aws_api_gateway_method.post_event.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:aws:apigateway:${var.aws_region}:sns:action/Publish"
  credentials             = aws_iam_role.apigw_sns_role.arn

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }

  request_templates = {
    "application/json" = "Action=Publish&TopicArn=$util.urlEncode('${aws_sns_topic.event_topic.arn}')&Message=$util.urlEncode($input.body)"
  }
}

resource "aws_api_gateway_method_response" "response_200" {
  rest_api_id = aws_api_gateway_rest_api.event_api.id
  resource_id = aws_api_gateway_resource.events_resource.id
  http_method = aws_api_gateway_method.post_event.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "sns_integration_response" {
  rest_api_id = aws_api_gateway_rest_api.event_api.id
  resource_id = aws_api_gateway_resource.events_resource.id
  http_method = aws_api_gateway_method.post_event.http_method
  status_code = aws_api_gateway_method_response.response_200.status_code

  response_templates = {
    "application/json" = "{\"message\": \"Event published successfully\"}"
  }

  depends_on = [
    aws_api_gateway_integration.sns_integration
  ]
}

resource "aws_api_gateway_deployment" "event_api_deployment" {
  rest_api_id = aws_api_gateway_rest_api.event_api.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.events_resource.id,
      aws_api_gateway_method.post_event.id,
      aws_api_gateway_integration.sns_integration.id,
      aws_api_gateway_integration_response.sns_integration_response.id,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration_response.sns_integration_response
  ]
}

resource "aws_api_gateway_stage" "prod" {
  deployment_id = aws_api_gateway_deployment.event_api_deployment.id
  rest_api_id   = aws_api_gateway_rest_api.event_api.id
  stage_name    = "prod"
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "sns_topic_arn" {
  description = "ARN of the encrypted SNS topic"
  value       = aws_sns_topic.event_topic.arn
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key"
  value       = aws_kms_key.sns_key.arn
}

output "api_endpoint" {
  description = "URL endpoint for publishing events"
  value       = "${aws_api_gateway_stage.prod.invoke_url}/events"
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy the VPC resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for the public subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for the private subnets"
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

provider "aws" {
  region = var.aws_region
}

# Fetch available Availability Zones in the region
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC Definition
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "terraform-aws-vpc"
  }
}

# Internet Gateway for public subnets
resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "terraform-aws-igw"
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

# Private Subnets
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

# Public Route Table & Routing
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = {
    Name = "terraform-aws-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private Route Table & Associations
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "terraform-aws-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Outputs
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "List of IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "List of IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region for resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.10.0.0/16"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# VPC and Internet Gateway
# -----------------------------------------------------------------------------
resource "aws_vpc" "primary" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "ntier primary"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.primary.id

  tags = {
    Name = "ntier-primary-igw"
  }
}

# -----------------------------------------------------------------------------
# Subnets - Primary Set
# -----------------------------------------------------------------------------
resource "aws_subnet" "web_1" {
  vpc_id                  = aws_vpc.primary.id
  cidr_block              = "10.10.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "ntier-web-1"
    Tier = "web"
  }
}

resource "aws_subnet" "app_1" {
  vpc_id            = aws_vpc.primary.id
  cidr_block        = "10.10.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "ntier-app-1"
    Tier = "app"
  }
}

resource "aws_subnet" "db_1" {
  vpc_id            = aws_vpc.primary.id
  cidr_block        = "10.10.3.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "ntier-db-1"
    Tier = "database"
  }
}

resource "aws_subnet" "mgmt" {
  vpc_id                  = aws_vpc.primary.id
  cidr_block              = "10.10.4.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "ntier-mgmt"
    Tier = "management"
  }
}

# -----------------------------------------------------------------------------
# Subnets - Secondary (Duplicate) Set
# -----------------------------------------------------------------------------
resource "aws_subnet" "web_2" {
  vpc_id                  = aws_vpc.primary.id
  cidr_block              = "10.10.5.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "ntier-web-2"
    Tier = "web"
  }
}

resource "aws_subnet" "app_2" {
  vpc_id            = aws_vpc.primary.id
  cidr_block        = "10.10.6.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "ntier-app-2"
    Tier = "app"
  }
}

resource "aws_subnet" "db_2" {
  vpc_id            = aws_vpc.primary.id
  cidr_block        = "10.10.7.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "ntier-db-2"
    Tier = "database"
  }
}

# -----------------------------------------------------------------------------
# Route Tables and Routes
# -----------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.primary.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "ntier-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.primary.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "ntier-private-rt"
  }
}

# -----------------------------------------------------------------------------
# Route Table Associations
# Public Route Table: web_1, mgmt, web_2
# -----------------------------------------------------------------------------
resource "aws_route_table_association" "web_1" {
  subnet_id      = aws_subnet.web_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "mgmt" {
  subnet_id      = aws_subnet.mgmt.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "web_2" {
  subnet_id      = aws_subnet.web_2.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Private Route Table: app_1, db_1, app_2, db_2
# -----------------------------------------------------------------------------
resource "aws_route_table_association" "app_1" {
  subnet_id      = aws_subnet.app_1.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "db_1" {
  subnet_id      = aws_subnet.db_1.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "app_2" {
  subnet_id      = aws_subnet.app_2.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "db_2" {
  subnet_id      = aws_subnet.db_2.id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.primary.id
}

output "public_route_table_id" {
  description = "The ID of the public route table"
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "The ID of the private route table"
  value       = aws_route_table.private.id
}

output "public_subnet_ids" {
  description = "IDs of the subnets associated with the public route table"
  value = [
    aws_subnet.web_1.id,
    aws_subnet.mgmt.id,
    aws_subnet.web_2.id
  ]
}

output "private_subnet_ids" {
  description = "IDs of the subnets associated with the private route table"
  value = [
    aws_subnet.app_1.id,
    aws_subnet.db_1.id,
    aws_subnet.app_2.id,
    aws_subnet.db_2.id
  ]
}
```

```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region to deploy resources."
  type        = string
  default     = "us-east-1"
}

variable "key_type" {
  description = "Type of key to provision: 'standard', 'external', 'replica', or 'replica_external'."
  type        = string
  default     = "standard"
  validation {
    condition     = contains(["standard", "external", "replica", "replica_external"], var.key_type)
    error_message = "key_type must be one of: 'standard', 'external', 'replica', 'replica_external'."
  }
}

variable "description" {
  description = "The description of the KMS key as viewed in AWS console."
  type        = string
  default     = "Central KMS Managed Key"
}

variable "key_usage" {
  description = "Determines the cryptographic operations for which you can use the KMS key (ENCRYPT_DECRYPT, SIGN_VERIFY, GENERATE_VERIFY_MAC)."
  type        = string
  default     = "ENCRYPT_DECRYPT"
}

variable "customer_master_key_spec" {
  description = "Specifies whether the key contains a symmetric key or an asymmetric key pair and the encryption algorithms or signing algorithms that the key supports."
  type        = string
  default     = "SYMMETRIC_DEFAULT"
}

variable "deletion_window_in_days" {
  description = "The waiting period, specified in number of days. After the waiting period ends, AWS KMS deletes the KMS key."
  type        = number
  default     = 30
}

variable "enable_key_rotation" {
  description = "Specifies whether key rotation is enabled. Only valid for symmetric standard keys."
  type        = bool
  default     = true
}

variable "is_enabled" {
  description = "Specifies whether the key is enabled."
  type        = bool
  default     = true
}

variable "multi_region" {
  description = "Indicates whether the KMS key is a multi-Region key."
  type        = bool
  default     = false
}

variable "primary_key_arn" {
  description = "The ARN of the primary key for replica keys (required if key_type is 'replica' or 'replica_external')."
  type        = string
  default     = null
}

variable "key_material_base64" {
  description = "Base64-encoded 256-bit symmetric key material for external keys (required if key_type is 'external' or 'replica_external')."
  type        = string
  default     = null
}

variable "valid_to" {
  description = "Time at which imported key material expires in RFC3339 format (optional for external keys)."
  type        = string
  default     = null
}

# -----------------------------------------------------------------------------
# Policy Variables
# -----------------------------------------------------------------------------
variable "enable_default_root_policy" {
  description = "Whether to include default root account delegation statement in key policy."
  type        = bool
  default     = true
}

variable "key_administrators" {
  description = "List of IAM ARNs with administrative access to the KMS key."
  type        = list(string)
  default     = []
}

variable "key_users" {
  description = "List of IAM ARNs granted standard decrypt/encrypt/data-key generation permissions."
  type        = list(string)
  default     = []
}

variable "key_service_users" {
  description = "List of AWS Service Principal identifiers or ARNs granted standard key usage permissions."
  type        = list(string)
  default     = []
}

variable "ec2_autoscaling_roles" {
  description = "List of EC2 Auto Scaling Service-Linked Role ARNs granted permissions to create grants."
  type        = list(string)
  default     = []
}

variable "symmetric_encryption_users" {
  description = "List of IAM ARNs granted Symmetric Encryption/Decryption permissions."
  type        = list(string)
  default     = []
}

variable "hmac_users" {
  description = "List of IAM ARNs granted HMAC generate/verify permissions."
  type        = list(string)
  default     = []
}

variable "asymmetric_public_encryption_users" {
  description = "List of IAM ARNs granted Asymmetric Encryption/Decryption permissions."
  type        = list(string)
  default     = []
}

variable "asymmetric_sign_verify_users" {
  description = "List of IAM ARNs granted Sign/Verify permissions."
  type        = list(string)
  default     = []
}

variable "route53_dnssec_signing" {
  description = "Enable specific permissions for Route 53 DNSSEC service principal."
  type        = bool
  default     = false
}

variable "custom_policy_statements" {
  description = "A list of additional custom IAM policy statements to merge into the key policy."
  type        = any
  default     = []
}

variable "override_policy_document" {
  description = "Optional raw JSON IAM policy document to completely override standard policy generation."
  type        = string
  default     = null
}

# -----------------------------------------------------------------------------
# Aliases and Grants Variables
# -----------------------------------------------------------------------------
variable "aliases" {
  description = "List of alias configurations. Supports exact name or name_prefix."
  type = list(object({
    name        = optional(string)
    name_prefix = optional(string)
  }))
  default = [
    {
      name_prefix = "alias/cmk-central-"
    }
  ]
}

variable "grants" {
  description = "Map of KMS Grant configurations."
  type = map(object({
    grantee_principal = string
    operations        = list(string)
    retiring_principal = optional(string)
    constraints = optional(object({
      encryption_context_equals = optional(map(string))
      encryption_context_subset = optional(map(string))
    }))
  }))
  default = {}
}

variable "tags" {
  description = "A mapping of tags to assign to the resources."
  type        = map(string)
  default = {
    Environment = "Production"
    ManagedBy   = "Terraform"
  }
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Dynamic Policy Construction
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "dynamic_key_policy" {
  count = var.override_policy_document == null ? 1 : 0

  # 1. Root account full access (enables IAM policies to govern access)
  dynamic "statement" {
    for_each = var.enable_default_root_policy ? [1] : []
    content {
      sid       = "EnableRootPermissions"
      effect    = "Allow"
      actions   = ["kms:*"]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
      }
    }
  }

  # 2. Key Administrators
  dynamic "statement" {
    for_each = length(var.key_administrators) > 0 ? [1] : []
    content {
      sid    = "KeyAdministration"
      effect = "Allow"
      actions = [
        "kms:Create*",
        "kms:Describe*",
        "kms:Enable*",
        "kms:List*",
        "kms:Put*",
        "kms:Update*",
        "kms:Revoke*",
        "kms:Disable*",
        "kms:Get*",
        "kms:Delete*",
        "kms:TagResource",
        "kms:UntagResource",
        "kms:ScheduleKeyDeletion",
        "kms:CancelKeyDeletion",
        "kms:RotateKeyOnDemand"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_administrators
      }
    }
  }

  # 3. Standard Key Users
  dynamic "statement" {
    for_each = length(var.key_users) > 0 ? [1] : []
    content {
      sid    = "KeyUsers"
      effect = "Allow"
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_users
      }
    }
  }

  # 4. Service Users
  dynamic "statement" {
    for_each = length(var.key_service_users) > 0 ? [1] : []
    content {
      sid    = "ServiceUsers"
      effect = "Allow"
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*",
        "kms:DescribeKey"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.key_service_users
      }
    }
  }

  # 5. EC2 Auto Scaling Integration
  dynamic "statement" {
    for_each = length(var.ec2_autoscaling_roles) > 0 ? [1] : []
    content {
      sid    = "AllowAutoScalingToCreateGrant"
      effect = "Allow"
      actions = [
        "kms:CreateGrant",
        "kms:ListGrants",
        "kms:RevokeGrant"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.ec2_autoscaling_roles
      }
      condition {
        test     = "Bool"
        variable = "kms:GrantIsForAWSResource"
        values   = ["true"]
      }
    }
  }

  # 6. Symmetric Users
  dynamic "statement" {
    for_each = length(var.symmetric_encryption_users) > 0 ? [1] : []
    content {
      sid    = "SymmetricOperations"
      effect = "Allow"
      actions = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:ReEncrypt*",
        "kms:GenerateDataKey*"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.symmetric_encryption_users
      }
    }
  }

  # 7. HMAC Users
  dynamic "statement" {
    for_each = length(var.hmac_users) > 0 ? [1] : []
    content {
      sid    = "HMACOperations"
      effect = "Allow"
      actions = [
        "kms:GenerateMac",
        "kms:VerifyMac"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.hmac_users
      }
    }
  }

  # 8. Asymmetric Public Encryption Users
  dynamic "statement" {
    for_each = length(var.asymmetric_public_encryption_users) > 0 ? [1] : []
    content {
      sid    = "AsymmetricPublicEncryption"
      effect = "Allow"
      actions = [
        "kms:GetPublicKey",
        "kms:Encrypt",
        "kms:Decrypt"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.asymmetric_public_encryption_users
      }
    }
  }

  # 9. Asymmetric Sign/Verify Users
  dynamic "statement" {
    for_each = length(var.asymmetric_sign_verify_users) > 0 ? [1] : []
    content {
      sid    = "AsymmetricSignVerify"
      effect = "Allow"
      actions = [
        "kms:GetPublicKey",
        "kms:Sign",
        "kms:Verify"
      ]
      resources = ["*"]
      principals {
        type        = "AWS"
        identifiers = var.asymmetric_sign_verify_users
      }
    }
  }

  # 10. Route 53 DNSSEC Signing
  dynamic "statement" {
    for_each = var.route53_dnssec_signing ? [1] : []
    content {
      sid    = "Route53DNSSECSigning"
      effect = "Allow"
      actions = [
        "kms:DescribeKey",
        "kms:GetPublicKey",
        "kms:Sign"
      ]
      resources = ["*"]
      principals {
        type        = "Service"
        identifiers = ["dnssec-route53.amazonaws.com"]
      }
    }
  }

  # 11. Additional Custom IAM statements
  dynamic "statement" {
    for_each = var.custom_policy_statements
    content {
      sid           = try(statement.value.sid, null)
      effect        = try(statement.value.effect, "Allow")
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      resources     = try(statement.value.resources, ["*"])
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])
        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

locals {
  final_policy = var.override_policy_document != null ? var.override_policy_document : data.aws_iam_policy_document.dynamic_key_policy[0].json
}

# -----------------------------------------------------------------------------
# KMS Key Resources (Mutually Exclusive Creation)
# -----------------------------------------------------------------------------
# 1. Standard Customer Master Key
resource "aws_kms_key" "standard" {
  count                    = var.key_type == "standard" ? 1 : 0
  description              = var.description
  key_usage                = var.key_usage
  customer_master_key_spec = var.customer_master_key_spec
  policy                   = local.final_policy
  deletion_window_in_days  = var.deletion_window_in_days
  is_enabled               = var.is_enabled
  enable_key_rotation      = var.customer_master_key_spec == "SYMMETRIC_DEFAULT" ? var.enable_key_rotation : false
  multi_region             = var.multi_region
  tags                     = var.tags
}

# 2. External KMS Key with imported key material
resource "aws_kms_external_key" "external" {
  count                   = var.key_type == "external" ? 1 : 0
  description             = var.description
  policy                  = local.final_policy
  deletion_window_in_days = var.deletion_window_in_days
  enabled                 = var.is_enabled
  key_material_base64     = var.key_material_base64
  valid_to                = var.valid_to
  multi_region            = var.multi_region
  tags                    = var.tags
}

# 3. Multi-Region Replica Key
resource "aws_kms_replica_key" "replica" {
  count                   = var.key_type == "replica" ? 1 : 0
  description             = var.description
  primary_key_arn         = var.primary_key_arn
  policy                  = local.final_policy
  deletion_window_in_days = var.deletion_window_in_days
  enabled                 = var.is_enabled
  tags                    = var.tags
}

# 4. Multi-Region Replica External Key
resource "aws_kms_replica_external_key" "replica_external" {
  count                   = var.key_type == "replica_external" ? 1 : 0
  description             = var.description
  primary_key_arn         = var.primary_key_arn
  key_material_base64     = var.key_material_base64
  valid_to                = var.valid_to
  policy                  = local.final_policy
  deletion_window_in_days = var.deletion_window_in_days
  enabled                 = var.is_enabled
  tags                    = var.tags
}

# -----------------------------------------------------------------------------
# Unified Resolved Key Identifiers
# -----------------------------------------------------------------------------
locals {
  target_key_id  = coalesce(
    one(aws_kms_key.standard[*].key_id),
    one(aws_kms_external_key.external[*].id),
    one(aws_kms_replica_key.replica[*].key_id),
    one(aws_kms_replica_external_key.replica_external[*].key_id)
  )
  target_key_arn = coalesce(
    one(aws_kms_key.standard[*].arn),
    one(aws_kms_external_key.external[*].arn),
    one(aws_kms_replica_key.replica[*].arn),
    one(aws_kms_replica_external_key.replica_external[*].arn)
  )
}

# -----------------------------------------------------------------------------
# KMS Aliases
# -----------------------------------------------------------------------------
resource "aws_kms_alias" "aliases" {
  for_each      = { for idx, alias in var.aliases : idx => alias }
  target_key_id = local.target_key_id
  name          = each.value.name
  name_prefix   = each.value.name_prefix
}

# -----------------------------------------------------------------------------
# KMS Grants
# -----------------------------------------------------------------------------
resource "aws_kms_grant" "grants" {
  for_each          = var.grants
  name              = each.key
  key_id            = local.target_key_arn
  grantee_principal = each.value.grantee_principal
  operations        = each.value.operations
  retiring_principal = each.value.retiring_principal

  dynamic "constraints" {
    for_each = each.value.constraints != null ? [each.value.constraints] : []
    content {
      encryption_context_equals = constraints.value.encryption_context_equals
      encryption_context_subset = constraints.value.encryption_context_subset
    }
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "key_arn" {
  description = "The Amazon Resource Name (ARN) of the provisioned KMS key."
  value       = local.target_key_arn
}

output "key_id" {
  description = "The globally unique identifier for the provisioned KMS key."
  value       = local.target_key_id
}

output "aliases" {
  description = "A map of created aliases and their properties."
  value = {
    for k, alias in aws_kms_alias.aliases : k => {
      arn  = alias.arn
      name = alias.name
    }
  }
}

output "grants" {
  description = "A map of created grants and their IDs."
  value = {
    for k, grant in aws_kms_grant.grants : k => {
      grant_id    = grant.grant_id
      grant_token = grant.grant_token
    }
  }
}
```

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources."
  default     = "us-east-1"
}

variable "name" {
  type        = string
  description = "Name of the SNS topic. If fifo_topic is true, name must end with '.fifo'."
  default     = "enterprise-alerts-topic"
}

variable "display_name" {
  type        = string
  description = "The display name for the SNS topic."
  default     = "Enterprise Notification Hub"
}

variable "fifo_topic" {
  type        = bool
  description = "Boolean indicating whether or not to create a FIFO (first-in-first-out) topic."
  default     = false
}

variable "content_based_deduplication" {
  type        = bool
  description = "Enables content-based deduplication for FIFO topics."
  default     = false
}

variable "create_kms_key" {
  type        = bool
  description = "Whether to create a dedicated AWS KMS Customer Master Key (CMK) for SNS topic encryption."
  default     = true
}

variable "kms_master_key_id" {
  type        = string
  description = "An existing KMS Master Key ID/ARN. If create_kms_key is false and this is not set, defaults to 'alias/aws/sns'."
  default     = null
}

variable "topic_policy_json" {
  type        = string
  description = "Optional custom JSON string for the SNS topic policy."
  default     = null
}

# Delivery feedback roles and sample rates
variable "application_success_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Application delivery status success feedback."
  default     = null
}

variable "application_success_feedback_sample_rate" {
  type        = number
  description = "Percentage of success feedback samples for Application protocol."
  default     = null
}

variable "application_failure_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Application delivery status failure feedback."
  default     = null
}

variable "http_success_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for HTTP/S delivery status success feedback."
  default     = null
}

variable "http_success_feedback_sample_rate" {
  type        = number
  description = "Percentage of success feedback samples for HTTP/S protocol."
  default     = null
}

variable "http_failure_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for HTTP/S delivery status failure feedback."
  default     = null
}

variable "lambda_success_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Lambda delivery status success feedback."
  default     = null
}

variable "lambda_success_feedback_sample_rate" {
  type        = number
  description = "Percentage of success feedback samples for Lambda protocol."
  default     = null
}

variable "lambda_failure_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Lambda delivery status failure feedback."
  default     = null
}

variable "sqs_success_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for SQS delivery status success feedback."
  default     = null
}

variable "sqs_success_feedback_sample_rate" {
  type        = number
  description = "Percentage of success feedback samples for SQS protocol."
  default     = null
}

variable "sqs_failure_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for SQS delivery status failure feedback."
  default     = null
}

variable "firehose_success_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Firehose delivery status success feedback."
  default     = null
}

variable "firehose_success_feedback_sample_rate" {
  type        = number
  description = "Percentage of success feedback samples for Firehose protocol."
  default     = null
}

variable "firehose_failure_feedback_role_arn" {
  type        = string
  description = "IAM role ARN for Firehose delivery status failure feedback."
  default     = null
}

variable "subscriptions" {
  type = map(object({
    protocol                        = string
    endpoint                        = string
    endpoint_auto_confirms          = optional(bool, false)
    raw_message_delivery            = optional(bool, false)
    filter_policy                   = optional(string, null)
    filter_policy_scope             = optional(string, "MessageAttributes")
    redrive_policy                  = optional(string, null)
    subscription_role_arn           = optional(string, null)
    confirmation_timeout_in_minutes = optional(number, null)
  }))
  description = "Map of SNS topic subscriptions to create."
  default     = {}
}

variable "tags" {
  type        = map(string)
  description = "A mapping of tags to assign to all resources."
  default = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# KMS Key and Policy Configuration
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_policy" {
  count = var.create_kms_key ? 1 : 0

  # Root account full access
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  # CloudWatch Logs encryption support
  statement {
    sid    = "AllowCloudWatchLogs"
    effect = "Allow"
    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:*"]
    }
  }
}

resource "aws_kms_key" "sns" {
  count                   = var.create_kms_key ? 1 : 0
  description             = "Dedicated KMS Customer Managed Key for SNS Topic ${var.name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_policy[0].json

  tags = merge(
    var.tags,
    {
      Name = "${var.name}-key"
    }
  )
}

# Clean name for alias (removes .fifo if present, as KMS alias must follow naming constraints)
locals {
  cleaned_alias_name = replace(var.name, ".fifo", "")
  kms_master_key_id = var.create_kms_key ? (
    aws_kms_key.sns[0].arn
  ) : (
    var.kms_master_key_id != null ? var.kms_master_key_id : "alias/aws/sns"
  )
}

resource "aws_kms_alias" "sns" {
  count         = var.create_kms_key ? 1 : 0
  name          = "alias/sns/${local.cleaned_alias_name}"
  target_key_id = aws_kms_key.sns[0].key_id
}

# -----------------------------------------------------------------------------
# SNS Topic
# -----------------------------------------------------------------------------
resource "aws_sns_topic" "this" {
  name                        = var.name
  display_name                = var.fifo_topic ? null : var.display_name
  kms_master_key_id           = local.kms_master_key_id
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : null

  # Application delivery feedback
  application_success_feedback_role_arn    = var.application_success_feedback_role_arn
  application_success_feedback_sample_rate = var.application_success_feedback_sample_rate
  application_failure_feedback_role_arn    = var.application_failure_feedback_role_arn

  # HTTP/S delivery feedback
  http_success_feedback_role_arn    = var.http_success_feedback_role_arn
  http_success_feedback_sample_rate = var.http_success_feedback_sample_rate
  http_failure_feedback_role_arn    = var.http_failure_feedback_role_arn

  # Lambda delivery feedback
  lambda_success_feedback_role_arn    = var.lambda_success_feedback_role_arn
  lambda_success_feedback_sample_rate = var.lambda_success_feedback_sample_rate
  lambda_failure_feedback_role_arn    = var.lambda_failure_feedback_role_arn

  # SQS delivery feedback
  sqs_success_feedback_role_arn    = var.sqs_success_feedback_role_arn
  sqs_success_feedback_sample_rate = var.sqs_success_feedback_sample_rate
  sqs_failure_feedback_role_arn    = var.sqs_failure_feedback_role_arn

  # Firehose delivery feedback
  firehose_success_feedback_role_arn    = var.firehose_success_feedback_role_arn
  firehose_success_feedback_sample_rate = var.firehose_success_feedback_sample_rate
  firehose_failure_feedback_role_arn    = var.firehose_failure_feedback_role_arn

  tags = var.tags
}

# -----------------------------------------------------------------------------
# Optional Custom Topic Policy
# -----------------------------------------------------------------------------
resource "aws_sns_topic_policy" "this" {
  count  = var.topic_policy_json != null ? 1 : 0
  arn    = aws_sns_topic.this.arn
  policy = var.topic_policy_json
}

# -----------------------------------------------------------------------------
# SNS Subscriptions
# -----------------------------------------------------------------------------
resource "aws_sns_topic_subscription" "this" {
  for_each = var.subscriptions

  topic_arn                       = aws_sns_topic.this.arn
  protocol                        = each.value.protocol
  endpoint                        = each.value.endpoint
  endpoint_auto_confirms          = each.value.endpoint_auto_confirms
  raw_message_delivery            = each.value.raw_message_delivery
  filter_policy                   = each.value.filter_policy
  filter_policy_scope             = each.value.filter_policy != null ? each.value.filter_policy_scope : null
  redrive_policy                  = each.value.redrive_policy
  subscription_role_arn           = each.value.subscription_role_arn
  confirmation_timeout_in_minutes = each.value.confirmation_timeout_in_minutes
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "topic_arn" {
  description = "The ARN of the created SNS topic."
  value       = aws_sns_topic.this.arn
}

output "topic_id" {
  description = "The ID of the created SNS topic."
  value       = aws_sns_topic.this.id
}

output "topic_name" {
  description = "The name of the created SNS topic."
  value       = aws_sns_topic.this.name
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used to encrypt the SNS topic."
  value       = local.kms_master_key_id
}

output "kms_alias_arn" {
  description = "The ARN of the KMS alias if created."
  value       = try(aws_kms_alias.sns[0].arn, null)
}

output "subscription_arns" {
  description = "Map of created subscription ARNs."
  value       = { for k, v in aws_sns_topic_subscription.this : k => v.arn }
}
```

```terraform
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into."
  default     = "us-east-1"
}

variable "enable_group" {
  type        = bool
  description = "Toggle to create the IAM developer group."
  default     = true
}

variable "enable_group_policy" {
  type        = bool
  description = "Toggle to create the IAM read-only and S3 access policy."
  default     = true
}

variable "enable_group_policy_attachment" {
  type        = bool
  description = "Toggle to attach the policy to the IAM developer group."
  default     = true
}

variable "enable_users" {
  type        = bool
  description = "Toggle to create the IAM users."
  default     = true
}

variable "enable_user_policy" {
  type        = bool
  description = "Toggle to create the EC2 console screenshot policy."
  default     = true
}

variable "enable_user_policy_attachment" {
  type        = bool
  description = "Toggle to attach the EC2 console screenshot policy to users."
  default     = true
}

variable "enable_group_membership" {
  type        = bool
  description = "Toggle to add users to the developers group."
  default     = true
}

variable "enable_instance_role" {
  type        = bool
  description = "Toggle to create the EC2 instance role."
  default     = true
}

variable "group_name" {
  type        = string
  description = "Name of the IAM group."
  default     = "developers"
}

variable "user_names" {
  type        = list(string)
  description = "List of IAM usernames to create."
  default     = ["jack", "jones"]
}

variable "group_policy_name" {
  type        = string
  description = "Name of the policy to attach to the group."
  default     = "iam_read_only_and_s3_full_access"
}

variable "user_policy_name" {
  type        = string
  description = "Name of the policy to attach to users."
  default     = "ec2_get_console_screenshot"
}

variable "instance_role_name" {
  type        = string
  description = "Name of the EC2 instance role."
  default     = "instance_role"
}

# -----------------------------------------------------------------------------
# IAM Developer Group
# -----------------------------------------------------------------------------
resource "aws_iam_group" "developers" {
  count = var.enable_group ? 1 : 0
  name  = var.group_name
}

# -----------------------------------------------------------------------------
# IAM Policy: IAM Read-Only & S3 Read/Write
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "iam_s3_policy_doc" {
  statement {
    sid       = "IAMReadOnly"
    effect    = "Allow"
    actions   = [
      "iam:Get*",
      "iam:List*",
      "iam:GenerateCredentialReport",
      "iam:GenerateServiceLastAccessedDetails"
    ]
    resources = ["*"]
  }

  statement {
    sid       = "S3ObjectReadWrite"
    effect    = "Allow"
    actions   = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "iam_s3_policy" {
  count       = var.enable_group_policy ? 1 : 0
  name        = var.group_policy_name
  description = "Policy providing IAM read-only access and S3 read/write access"
  policy      = data.aws_iam_policy_document.iam_s3_policy_doc.json
}

resource "aws_iam_group_policy_attachment" "group_attachment" {
  count      = var.enable_group && var.enable_group_policy && var.enable_group_policy_attachment ? 1 : 0
  group      = aws_iam_group.developers[0].name
  policy_arn = aws_iam_policy.iam_s3_policy[0].arn
}

# -----------------------------------------------------------------------------
# IAM Users
# -----------------------------------------------------------------------------
resource "aws_iam_user" "users" {
  for_each = var.enable_users ? toset(var.user_names) : []
  name     = each.value

  tags = {
    user_created_by = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Group Membership
# -----------------------------------------------------------------------------
resource "aws_iam_group_membership" "developers_membership" {
  count = var.enable_group && var.enable_users && var.enable_group_membership ? 1 : 0
  name  = "${var.group_name}-membership"
  group = aws_iam_group.developers[0].name
  users = [for u in aws_iam_user.users : u.name]
}

# -----------------------------------------------------------------------------
# IAM Policy: EC2 Console Screenshot
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_screenshot_policy_doc" {
  statement {
    sid       = "EC2GetConsoleScreenshot"
    effect    = "Allow"
    actions   = ["ec2:GetConsoleScreenshot"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "ec2_screenshot_policy" {
  count       = var.enable_user_policy ? 1 : 0
  name        = var.user_policy_name
  description = "Policy allowing ec2:GetConsoleScreenshot permissions"
  policy      = data.aws_iam_policy_document.ec2_screenshot_policy_doc.json
}

resource "aws_iam_user_policy_attachment" "user_screenshot_attachment" {
  for_each   = (var.enable_users && var.enable_user_policy && var.enable_user_policy_attachment) ? aws_iam_user.users : {}
  user       = each.value.name
  policy_arn = aws_iam_policy.ec2_screenshot_policy[0].arn
}

# -----------------------------------------------------------------------------
# EC2 Instance Role
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_assume_role_doc" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "instance_role" {
  count              = var.enable_instance_role ? 1 : 0
  name               = var.instance_role_name
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role_doc.json

  tags = {
    role_created_by = "terraform"
  }
}

resource "aws_iam_role_policy_attachment" "instance_role_readonly_attachment" {
  count      = var.enable_instance_role ? 1 : 0
  role       = aws_iam_role.instance_role[0].name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "group_name" {
  description = "The name of the IAM group."
  value       = try(aws_iam_group.developers[0].name, null)
}

output "user_names" {
  description = "The created IAM users."
  value       = [for u in aws_iam_user.users : u.name]
}

output "instance_role_arn" {
  description = "The ARN of the EC2 instance role."
  value       = try(aws_iam_role.instance_role[0].arn, null)
}
```

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region to deploy the networking infrastructure"
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC and Blueprint tag"
  type        = string
  default     = "multi-cluster-vpc"
}

variable "vpc_cidr" {
  description = "Base CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

provider "aws" {
  region = var.aws_region
}

# Fetch first 3 available AZs in the current region
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  # Private subnets: prefix extension of 4 at netnums 0, 1, 2 (e.g., 10.0.0.0/20, 10.0.16.0/20, 10.0.32.0/20)
  private_subnets = [
    for k, v in local.azs : cidrsubnet(var.vpc_cidr, 4, k)
  ]

  # Public subnets: prefix extension of 8 starting at offset 48 (e.g., 10.0.48.0/24, 10.0.49.0/24, 10.0.50.0/24)
  public_subnets = [
    for k, v in local.azs : cidrsubnet(var.vpc_cidr, 8, k + 48)
  ]

  tags = {
    Blueprint  = var.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

# Official AWS VPC Module
module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = var.vpc_name
  cidr = var.vpc_cidr

  azs             = local.azs
  private_subnets = local.private_subnets
  public_subnets  = local.public_subnets

  enable_nat_gateway     = true
  single_nat_gateway     = true
  one_nat_gateway_per_az = false

  enable_dns_hostnames = true
  enable_dns_support   = true

  public_subnet_tags = {
    "kubernetes.io/role/elb" = "1"
  }

  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = "1"
  }

  tags = local.tags
}

# Security group for Cluster 1
resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Additional security group for cluster 1 cross-cluster communication"
  vpc_id      = module.vpc.vpc_id

  tags = merge(
    local.tags,
    {
      Name = "cluster1_additional_sg"
    }
  )
}

# Security group for Cluster 2
resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Additional security group for cluster 2 cross-cluster communication"
  vpc_id      = module.vpc.vpc_id

  tags = merge(
    local.tags,
    {
      Name = "cluster2_additional_sg"
    }
  )
}

# Cluster 1 Rules: Ingress from Cluster 2
resource "aws_security_group_rule" "cluster1_ingress_from_cluster2" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.cluster1_additional_sg.id
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
  description              = "Allow all inbound traffic from cluster2_additional_sg"
}

# Cluster 1 Rules: Egress to Cluster 2
resource "aws_security_group_rule" "cluster1_egress_to_cluster2" {
  type                     = "egress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.cluster1_additional_sg.id
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
  description              = "Allow all outbound traffic to cluster2_additional_sg"
}

# Cluster 2 Rules: Ingress from Cluster 1
resource "aws_security_group_rule" "cluster2_ingress_from_cluster1" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.cluster2_additional_sg.id
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
  description              = "Allow all inbound traffic from cluster1_additional_sg"
}

# Cluster 2 Rules: Egress to Cluster 1
resource "aws_security_group_rule" "cluster2_egress_to_cluster1" {
  type                     = "egress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  security_group_id        = aws_security_group.cluster2_additional_sg.id
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
  description              = "Allow all outbound traffic to cluster1_additional_sg"
}

output "vpc_id" {
  description = "The ID of the VPC"
  value       = module.vpc.vpc_id
}

output "private_subnets" {
  description = "List of IDs of private subnets"
  value       = module.vpc.private_subnets
}

output "public_subnets" {
  description = "List of IDs of public subnets"
  value       = module.vpc.public_subnets
}

output "cluster1_security_group_id" {
  description = "Security Group ID for Cluster 1"
  value       = aws_security_group.cluster1_additional_sg.id
}

output "cluster2_security_group_id" {
  description = "Security Group ID for Cluster 2"
  value       = aws_security_group.cluster2_additional_sg.id
}
```

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources."
  default     = "us-east-1"
}

variable "pool_name" {
  type        = string
  description = "The name of the Cognito User Pool."
  default     = "Pool name"
}

variable "alias_attributes" {
  type        = list(string)
  description = "Attributes supported as an alias for username."
  default     = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  type        = list(string)
  description = "The attributes to be auto-verified."
  default     = []
}

variable "email_verification_message" {
  type        = string
  description = "Email message template for verification."
  default     = "Some message {####}"
}

variable "email_verification_subject" {
  type        = string
  description = "Email subject template for verification."
  default     = "Some subject"
}

variable "mfa_configuration" {
  type        = string
  description = "Multi-Factor Authentication (MFA) configuration."
  default     = "OPTIONAL"
}

variable "sms_authentication_message" {
  type        = string
  description = "SMS message template for authentication."
  default     = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  type        = string
  description = "SMS message template for verification."
  default     = "SMS verification message {####}"
}

variable "verification_message_template" {
  type = object({
    default_email_option  = optional(string, "CONFIRM_WITH_CODE")
    email_message_by_link = optional(string, null)
    email_subject_by_link = optional(string, null)
  })
  description = "Verification message template configuration."
  default     = {}
}

variable "sms_configuration" {
  type = object({
    external_id    = optional(string, "")
    sns_caller_arn = optional(string, "")
    sns_region     = optional(string, null)
  })
  description = "SMS configuration settings."
  default = {
    external_id    = ""
    sns_caller_arn = ""
    sns_region     = null
  }
}

variable "recovery_mechanisms" {
  type = list(object({
    name     = string
    priority = number
  }))
  description = "List of user recovery mechanisms."
  default = [
    {
      name     = "verified_phone_number"
      priority = 1
    },
    {
      name     = "verified_email"
      priority = 2
    }
  ]
}

variable "admin_create_user_config" {
  type = object({
    allow_admin_create_user_only = optional(bool, false)
    email_message                = optional(string, null)
    email_subject                = optional(string, null)
    sms_message                  = optional(string, null)
  })
  description = "Admin create user configuration."
  default = {
    allow_admin_create_user_only = false
    email_message                = null
    email_subject                = null
    sms_message                  = null
  }
}

variable "enable_software_token_mfa" {
  type        = bool
  description = "Enable software token (TOTP) MFA."
  default     = true
}

variable "case_sensitive" {
  type        = bool
  description = "Whether username case sensitivity is enabled."
  default     = null
}

variable "device_configuration" {
  type = object({
    challenge_required_on_new_device      = optional(bool, false)
    device_only_remembered_on_user_prompt = optional(bool, false)
  })
  description = "Device tracking and remembering configuration."
  default     = null
}

variable "lambda_config" {
  type = object({
    create_auth_challenge          = optional(string, null)
    custom_message                 = optional(string, null)
    define_auth_challenge          = optional(string, null)
    post_authentication            = optional(string, null)
    post_confirmation              = optional(string, null)
    pre_authentication             = optional(string, null)
    pre_sign_up                    = optional(string, null)
    pre_token_generation           = optional(string, null)
    user_migration                 = optional(string, null)
    verify_auth_challenge_response = optional(string, null)
    kms_key_id                     = optional(string, null)
    custom_email_sender = optional(object({
      lambda_arn     = string
      lambda_version = string
    }), null)
  })
  description = "Lambda triggers configuration."
  default     = {}
}

variable "custom_schemas" {
  type = list(object({
    attribute_data_type      = string
    name                     = string
    required                 = optional(bool, false)
    mutable                  = optional(bool, true)
    developer_only_attribute = optional(bool, false)
    string_attribute_constraints = optional(object({
      min_length = optional(string, null)
      max_length = optional(string, null)
    }), null)
    number_attribute_constraints = optional(object({
      min_value = optional(string, null)
      max_value = optional(string, null)
    }), null)
  }))
  description = "User pool schema attribute configurations."
  default = [
    {
      attribute_data_type = "String"
      name                = "email"
      required            = true
      mutable             = true
    }
  ]
}

variable "client_app_names" {
  type        = list(string)
  description = "List of user pool client application names."
  default     = []
}

variable "client_generate_secret" {
  type        = bool
  description = "Whether the user pool client should have a secret generated."
  default     = false
}

variable "client_access_token_validity" {
  type        = number
  description = "Access token validity value."
  default     = 120
}

variable "client_id_token_validity" {
  type        = number
  description = "ID token validity value."
  default     = 120
}

variable "client_refresh_token_validity" {
  type        = number
  description = "Refresh token validity value."
  default     = 7
}

variable "client_token_validity_units" {
  type = object({
    access_token  = optional(string, "minutes")
    id_token      = optional(string, "minutes")
    refresh_token = optional(string, "days")
  })
  description = "Units for access, id, and refresh token validities."
  default = {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }
}

variable "client_allowed_oauth_flows_user_pool_client" {
  type        = bool
  description = "Whether the client is allowed to use OAuth flows."
  default     = false
}

variable "client_enable_token_revocation" {
  type        = bool
  description = "Enables or disables token revocation."
  default     = true
}

variable "client_explicit_auth_flows" {
  type        = list(string)
  description = "List of authentication flows supported by clients."
  default     = ["ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH"]
}

variable "client_prevent_user_existence_errors" {
  type        = string
  description = "Choose which errors to prevent when a user does not exist."
  default     = "LEGACY"
}

variable "client_read_attributes" {
  type        = list(string)
  description = "List of user pool attributes that the application can read."
  default     = null
}

variable "client_write_attributes" {
  type        = list(string)
  description = "List of user pool attributes that the application can write."
  default     = null
}

variable "client_callback_urls" {
  type        = list(string)
  description = "List of allowed callback URLs for the identity providers."
  default     = null
}

variable "client_logout_urls" {
  type        = list(string)
  description = "List of allowed logout URLs for the identity providers."
  default     = null
}

variable "client_allowed_oauth_flows" {
  type        = list(string)
  description = "List of allowed OAuth flows."
  default     = null
}

variable "client_allowed_oauth_scopes" {
  type        = list(string)
  description = "List of allowed OAuth scopes."
  default     = null
}

variable "client_supported_identity_providers" {
  type        = list(string)
  description = "List of provider names for the identity providers supported by client."
  default     = null
}

variable "user_group_name" {
  type        = string
  description = "Name of the Cognito user group. If not empty, group will be created."
  default     = ""
}

variable "user_group_precedence" {
  type        = number
  description = "The precedence of the user group."
  default     = 0
}

variable "user_group_role_arn" {
  type        = string
  description = "IAM role ARN associated with the user group."
  default     = null
}

variable "domain" {
  type        = string
  description = "Cognito User Pool domain name or prefix."
  default     = ""
}

variable "certificate_arn" {
  type        = string
  description = "ACM Certificate ARN for custom domain."
  default     = null
}

variable "create_route53_record" {
  type        = bool
  description = "Whether to create a Route 53 alias record pointing to the Cognito domain."
  default     = false
}

variable "route53_zone_id" {
  type        = string
  description = "Route 53 hosted zone ID for the alias record."
  default     = ""
}

# -----------------------------------------------------------------------------
# Cognito User Pool
# -----------------------------------------------------------------------------
resource "aws_cognito_user_pool" "this" {
  name                     = var.pool_name
  alias_attributes         = var.alias_attributes
  auto_verified_attributes = var.auto_verified_attributes
  mfa_configuration        = var.mfa_configuration

  email_verification_message = var.email_verification_message
  email_verification_subject = var.email_verification_subject
  sms_authentication_message = var.sms_authentication_message
  sms_verification_message   = var.sms_verification_message

  dynamic "verification_message_template" {
    for_each = var.verification_message_template != null ? [var.verification_message_template] : []
    content {
      default_email_option  = verification_message_template.value.default_email_option
      email_message_by_link = verification_message_template.value.email_message_by_link
      email_subject_by_link = verification_message_template.value.email_subject_by_link
    }
  }

  account_recovery_setting {
    dynamic "recovery_mechanism" {
      for_each = var.recovery_mechanisms
      content {
        name     = recovery_mechanism.value.name
        priority = recovery_mechanism.value.priority
      }
    }
  }

  admin_create_user_config {
    allow_admin_create_user_only = var.admin_create_user_config.allow_admin_create_user_only
    dynamic "invite_message_template" {
      for_each = (
        var.admin_create_user_config.email_message != null ||
        var.admin_create_user_config.email_subject != null ||
        var.admin_create_user_config.sms_message != null
      ) ? [1] : []
      content {
        email_message = var.admin_create_user_config.email_message
        email_subject = var.admin_create_user_config.email_subject
        sms_message   = var.admin_create_user_config.sms_message
      }
    }
  }

  dynamic "sms_configuration" {
    for_each = (
      lookup(var.sms_configuration, "external_id", "") != "" &&
      lookup(var.sms_configuration, "sns_caller_arn", "") != ""
    ) ? [var.sms_configuration] : []
    content {
      external_id    = sms_configuration.value.external_id
      sns_caller_arn = sms_configuration.value.sns_caller_arn
      sns_region     = sms_configuration.value.sns_region
    }
  }

  dynamic "software_token_mfa_configuration" {
    for_each = var.enable_software_token_mfa ? [1] : []
    content {
      enabled = true
    }
  }

  dynamic "username_configuration" {
    for_each = var.case_sensitive != null ? [var.case_sensitive] : []
    content {
      case_sensitive = username_configuration.value
    }
  }

  dynamic "device_configuration" {
    for_each = var.device_configuration != null ? [var.device_configuration] : []
    content {
      challenge_required_on_new_device      = device_configuration.value.challenge_required_on_new_device
      device_only_remembered_on_user_prompt = device_configuration.value.device_only_remembered_on_user_prompt
    }
  }

  dynamic "lambda_config" {
    for_each = length(keys(var.lambda_config)) > 0 ? [var.lambda_config] : []
    content {
      create_auth_challenge          = lambda_config.value.create_auth_challenge
      custom_message                 = lambda_config.value.custom_message
      define_auth_challenge          = lambda_config.value.define_auth_challenge
      post_authentication            = lambda_config.value.post_authentication
      post_confirmation              = lambda_config.value.post_confirmation
      pre_authentication             = lambda_config.value.pre_authentication
      pre_sign_up                    = lambda_config.value.pre_sign_up
      pre_token_generation           = lambda_config.value.pre_token_generation
      user_migration                 = lambda_config.value.user_migration
      verify_auth_challenge_response = lambda_config.value.verify_auth_challenge_response
      kms_key_id                     = lambda_config.value.kms_key_id

      dynamic "custom_email_sender" {
        for_each = lambda_config.value.custom_email_sender != null ? [lambda_config.value.custom_email_sender] : []
        content {
          lambda_arn     = custom_email_sender.value.lambda_arn
          lambda_version = custom_email_sender.value.lambda_version
        }
      }
    }
  }

  dynamic "schema" {
    for_each = var.custom_schemas
    content {
      attribute_data_type      = schema.value.attribute_data_type
      name                     = schema.value.name
      required                 = schema.value.required
      mutable                  = schema.value.mutable
      developer_only_attribute = schema.value.developer_only_attribute

      dynamic "string_attribute_constraints" {
        for_each = schema.value.string_attribute_constraints != null ? [schema.value.string_attribute_constraints] : []
        content {
          min_length = string_attribute_constraints.value.min_length
          max_length = string_attribute_constraints.value.max_length
        }
      }

      dynamic "number_attribute_constraints" {
        for_each = schema.value.number_attribute_constraints != null ? [schema.value.number_attribute_constraints] : []
        content {
          min_value = number_attribute_constraints.value.min_value
          max_value = number_attribute_constraints.value.max_value
        }
      }
    }
  }

  lifecycle {
    ignore_changes = [
      estimated_number_of_users
    ]
  }
}

# -----------------------------------------------------------------------------
# Cognito User Pool Clients
# -----------------------------------------------------------------------------
resource "aws_cognito_user_pool_client" "clients" {
  for_each = toset(var.client_app_names)

  name         = each.value
  user_pool_id = aws_cognito_user_pool.this.id

  generate_secret                      = var.client_generate_secret
  access_token_validity                = var.client_access_token_validity
  id_token_validity                    = var.client_id_token_validity
  refresh_token_validity               = var.client_refresh_token_validity
  allowed_oauth_flows_user_pool_client = var.client_allowed_oauth_flows_user_pool_client
  enable_token_revocation              = var.client_enable_token_revocation
  explicit_auth_flows                  = var.client_explicit_auth_flows
  prevent_user_existence_errors        = var.client_prevent_user_existence_errors

  token_validity_units {
    access_token  = var.client_token_validity_units.access_token
    id_token      = var.client_token_validity_units.id_token
    refresh_token = var.client_token_validity_units.refresh_token
  }

  read_attributes             = var.client_read_attributes
  write_attributes            = var.client_write_attributes
  callback_urls               = var.client_callback_urls
  logout_urls                 = var.client_logout_urls
  allowed_oauth_flows         = var.client_allowed_oauth_flows
  allowed_oauth_scopes        = var.client_allowed_oauth_scopes
  supported_identity_providers = var.client_supported_identity_providers
}

# -----------------------------------------------------------------------------
# Cognito User Group
# -----------------------------------------------------------------------------
resource "aws_cognito_user_group" "this" {
  count = var.user_group_name != "" ? 1 : 0

  name         = var.user_group_name
  user_pool_id = aws_cognito_user_pool.this.id
  precedence   = var.user_group_precedence
  role_arn     = var.user_group_role_arn
}

# -----------------------------------------------------------------------------
# Cognito Domain
# -----------------------------------------------------------------------------
resource "aws_cognito_user_pool_domain" "this" {
  count = var.domain != "" ? 1 : 0

  domain          = var.domain
  user_pool_id    = aws_cognito_user_pool.this.id
  certificate_arn = var.certificate_arn
}

# -----------------------------------------------------------------------------
# Route 53 Custom Domain Record
# -----------------------------------------------------------------------------
resource "aws_route53_record" "this" {
  count = (var.create_route53_record && var.route53_zone_id != "" && var.domain != "") ? 1 : 0

  name    = var.domain
  type    = "A"
  zone_id = var.route53_zone_id

  alias {
    name                   = aws_cognito_user_pool_domain.this[0].cloudfront_distribution_arn
    zone_id                = "Z2FDTNDATAQYW2"
    evaluate_target_health = false
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "user_pool_id" {
  description = "The ID of the Cognito User Pool."
  value       = aws_cognito_user_pool.this.id
}

output "user_pool_arn" {
  description = "The ARN of the Cognito User Pool."
  value       = aws_cognito_user_pool.this.arn
}

output "user_pool_endpoint" {
  description = "The endpoint of the Cognito User Pool."
  value       = aws_cognito_user_pool.this.endpoint
}

output "client_ids" {
  description = "Map of client application names to their generated Client IDs."
  value       = { for k, v in aws_cognito_user_pool_client.clients : k => v.id }
}

output "domain_cloudfront_distribution_arn" {
  description = "The CloudFront distribution ARN for the Cognito domain."
  value       = length(aws_cognito_user_pool_domain.this) > 0 ? aws_cognito_user_pool_domain.this[0].cloudfront_distribution_arn : null
}
```

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region for deployment"
  type        = "string"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "DevOps-Project-VPC"
}

variable "igw_name" {
  description = "Name tag for the Internet Gateway"
  type        = string
  default     = "devops-project-igw"
}

variable "route_table_name" {
  description = "Name tag for the public route table"
  type        = string
  default     = "DevOps-project-RT"
}

variable "public_subnet_identifier_name" {
  description = "Identifier name for the public subnet reference"
  type        = string
  default     = "subnet_a"
}

variable "nat_gw_name" {
  description = "Name tag for the NAT Gateway"
  type        = string
  default     = "DevOps-NAT-GW"
}

variable "public_ipv4_pool" {
  description = "Public IPv4 pool for the Elastic IP"
  type        = string
  default     = "amazon"
}

# Subnet A Variables
variable "subnet_a_cidr" {
  description = "CIDR block for Subnet A"
  type        = string
  default     = "10.0.1.0/24"
}

variable "subnet_a_az" {
  description = "Availability zone for Subnet A"
  type        = string
  default     = null
}

variable "subnet_a_map_public_ip_on_launch" {
  description = "Map public IP on launch for Subnet A"
  type        = bool
  default     = false
}

variable "subnet_a_name" {
  description = "Name tag for Subnet A"
  type        = string
  default     = "Subnet-A-Public"
}

# Subnet B Variables
variable "subnet_b_cidr" {
  description = "CIDR block for Subnet B"
  type        = string
  default     = "10.0.2.0/24"
}

variable "subnet_b_az" {
  description = "Availability zone for Subnet B"
  type        = string
  default     = null
}

variable "subnet_b_map_public_ip_on_launch" {
  description = "Map public IP on launch for Subnet B"
  type        = bool
  default     = false
}

variable "subnet_b_name" {
  description = "Name tag for Subnet B"
  type        = string
  default     = "Subnet-B-Private"
}

# Subnet C Variables
variable "subnet_c_cidr" {
  description = "CIDR block for Subnet C"
  type        = string
  default     = "10.0.3.0/24"
}

variable "subnet_c_az" {
  description = "Availability zone for Subnet C"
  type        = string
  default     = null
}

variable "subnet_c_map_public_ip_on_launch" {
  description = "Map public IP on launch for Subnet C"
  type        = bool
  default     = false
}

variable "subnet_c_name" {
  description = "Name tag for Subnet C"
  type        = string
  default     = "Subnet-C-Private"
}

# -----------------------------------------------------------------------------
# VPC and Internet Gateway
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------
resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr
  availability_zone       = coalesce(var.subnet_a_az, data.aws_availability_zones.available.names[0])
  map_public_ip_on_launch = var.subnet_a_map_public_ip_on_launch

  tags = {
    Name       = var.subnet_a_name
    Identifier = var.public_subnet_identifier_name
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr
  availability_zone       = coalesce(var.subnet_b_az, data.aws_availability_zones.available.names[1])
  map_public_ip_on_launch = var.subnet_b_map_public_ip_on_launch

  tags = {
    Name = var.subnet_b_name
  }
}

resource "aws_subnet" "subnet_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_c_cidr
  availability_zone       = coalesce(var.subnet_c_az, data.aws_availability_zones.available.names[2])
  map_public_ip_on_launch = var.subnet_c_map_public_ip_on_launch

  tags = {
    Name = var.subnet_c_name
  }
}

# -----------------------------------------------------------------------------
# Route Table and Association
# -----------------------------------------------------------------------------
resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = {
    Name = var.route_table_name
  }
}

resource "aws_route_table_association" "subnet_a_assoc" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.public_rt.id
}

# -----------------------------------------------------------------------------
# Elastic IP and NAT Gateway
# -----------------------------------------------------------------------------
resource "aws_eip" "nat" {
  domain           = "vpc"
  public_ipv4_pool = var.public_ipv4_pool

  tags = {
    Name = "${var.nat_gw_name}-EIP"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.subnet_b.id

  depends_on = [aws_internet_gateway.gw]

  tags = {
    Name = var.nat_gw_name
  }
}

# -----------------------------------------------------------------------------
# Security Group
# -----------------------------------------------------------------------------
resource "aws_security_group" "custom_sg" {
  name        = "default-egress-vpc-sg"
  description = "Security group permitting outbound egress only within the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow outbound traffic only within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "DefaultSecurityGroup"
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "nat_gateway_public_ip" {
  description = "The public IP address of the NAT Gateway"
  value       = aws_eip.nat.public_ip
}
```

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# --------------------------------------------------------------------------------------------------
# Variables
# --------------------------------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into."
  default     = "us-east-1"
}

variable "backup_vault_name" {
  type        = string
  description = "Name of the AWS Backup Vault."
  default     = "my-backup-vault"
}

variable "tags" {
  type        = map(string)
  description = "Tags to apply to resources."
  default = {
    Environment = "production"
    Terraform   = "true"
  }
}

variable "backup_tag_key" {
  type        = string
  description = "The tag key used for backup plan resource selection."
  default     = "backup"
}

variable "daily_schedule" {
  type        = string
  description = "Cron schedule expression for daily backups."
  default     = "cron(0 12 ? * * *)"
}

variable "enable_continuous_backup" {
  type        = bool
  description = "Enable continuous backup (point-in-time restore) for the daily backup rule."
  default     = false
}

variable "weekly_schedule" {
  type        = string
  description = "Cron schedule expression for weekly backups."
  default     = "cron(0 12 ? * 1 *)"
}

variable "monthly_schedule" {
  type        = string
  description = "Cron schedule expression for monthly backups."
  default     = "cron(0 12 1 * ? *)"
}

variable "enable_notifications" {
  type        = bool
  description = "Flag to enable backup vault notifications."
  default     = false
}

variable "sns_topic_arn" {
  type        = string
  description = "SNS Topic ARN for backup vault notifications (required if enable_notifications is true)."
  default     = ""
}

variable "notification_events" {
  type        = list(string)
  description = "List of backup vault events for notifications."
  default = [
    "BACKUP_JOB_FAILED",
    "RESTORE_JOB_FAILED",
    "COPY_JOB_FAILED",
    "S3_BACKUP_OBJECT_FAILED",
    "S3_RESTORE_OBJECT_FAILED"
  ]
}

# --------------------------------------------------------------------------------------------------
# KMS Key for Backup Vault
# --------------------------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "backup_vault_key" {
  description             = "KMS Key for AWS Backup Vault ${var.backup_vault_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowBackupServiceUse"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = [
          "kms:DescribeKey",
          "kms:GenerateDataKey*",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*"
        ]
        Resource = "*"
      }
    ]
  })

  tags = var.tags
}

resource "aws_kms_alias" "backup_vault_key_alias" {
  name          = "alias/${var.backup_vault_name}-key"
  target_key_id = aws_kms_key.backup_vault_key.key_id
}

# --------------------------------------------------------------------------------------------------
# AWS Backup Vault
# --------------------------------------------------------------------------------------------------

resource "aws_backup_vault" "vault" {
  name        = var.backup_vault_name
  kms_key_arn = aws_kms_key.backup_vault_key.arn
  tags        = var.tags
}

# --------------------------------------------------------------------------------------------------
# IAM Role for AWS Backup
# --------------------------------------------------------------------------------------------------

resource "aws_iam_role" "backup_role" {
  name = "${var.backup_vault_name}-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "backup_role_attachment" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# --------------------------------------------------------------------------------------------------
# Daily Backup Plan & Selection
# --------------------------------------------------------------------------------------------------

resource "aws_backup_plan" "daily" {
  name = "${var.backup_vault_name}-daily"

  rule {
    rule_name                = "daily_backup_rule"
    target_vault_name        = aws_backup_vault.vault.name
    schedule                 = var.daily_schedule
    enable_continuous_backup = var.enable_continuous_backup

    lifecycle {
      delete_after = 7
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = var.tags
}

resource "aws_backup_selection" "daily" {
  iam_role_arn = aws_iam_role.backup_role.arn
  name         = "daily_backup_selection"
  plan_id      = aws_backup_plan.daily.id
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "daily"
  }
}

# --------------------------------------------------------------------------------------------------
# Weekly Backup Plan & Selection
# --------------------------------------------------------------------------------------------------

resource "aws_backup_plan" "weekly" {
  name = "${var.backup_vault_name}-weekly"

  rule {
    rule_name         = "weekly_backup_rule"
    target_vault_name = aws_backup_vault.vault.name
    schedule          = var.weekly_schedule

    lifecycle {
      delete_after = 31
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = var.tags
}

resource "aws_backup_selection" "weekly" {
  iam_role_arn = aws_iam_role.backup_role.arn
  name         = "weekly_backup_selection"
  plan_id      = aws_backup_plan.weekly.id
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "weekly"
  }
}

# --------------------------------------------------------------------------------------------------
# Monthly Backup Plan & Selection
# --------------------------------------------------------------------------------------------------

resource "aws_backup_plan" "monthly" {
  name = "${var.backup_vault_name}-monthly"

  rule {
    rule_name         = "monthly_backup_rule"
    target_vault_name = aws_backup_vault.vault.name
    schedule          = var.monthly_schedule

    lifecycle {
      delete_after = 366
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = var.tags
}

resource "aws_backup_selection" "monthly" {
  iam_role_arn = aws_iam_role.backup_role.arn
  name         = "monthly_backup_selection"
  plan_id      = aws_backup_plan.monthly.id
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "monthly"
  }
}

# --------------------------------------------------------------------------------------------------
# Optional Backup Vault Notifications
# --------------------------------------------------------------------------------------------------

resource "aws_backup_vault_notifications" "vault_notifications" {
  count               = var.enable_notifications && var.sns_topic_arn != "" ? 1 : 0
  backup_vault_name   = aws_backup_vault.vault.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.notification_events
}

# --------------------------------------------------------------------------------------------------
# Outputs
# --------------------------------------------------------------------------------------------------

output "backup_vault_name" {
  description = "The name of the AWS Backup Vault."
  value       = aws_backup_vault.vault.name
}

output "backup_vault_arn" {
  description = "The ARN of the AWS Backup Vault."
  value       = aws_backup_vault.vault.arn
}

output "kms_key_arn" {
  description = "The ARN of the KMS Key used to encrypt the backup vault."
  value       = aws_kms_key.backup_vault_key.arn
}

output "backup_role_arn" {
  description = "The ARN of the IAM role assumed by AWS Backup."
  value       = aws_iam_role.backup_role.arn
}

output "daily_backup_plan_id" {
  description = "The ID of the daily backup plan."
  value       = aws_backup_plan.daily.id
}

output "weekly_backup_plan_id" {
  description = "The ID of the weekly backup plan."
  value       = aws_backup_plan.weekly.id
}

output "monthly_backup_plan_id" {
  description = "The ID of the monthly backup plan."
  value       = aws_backup_plan.monthly.id
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

# --- Input Variables ---

variable "aws_region" {
  description = "AWS region for deployments"
  type        = string
  default     = "us-east-1"
}

variable "env" {
  description = "Environment identifier tag"
  type        = string
  default     = "test"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.20.0/24", "10.0.21.0/24"]
}

variable "common_tags" {
  description = "Common tags applied to resources"
  type        = map(string)
  default = {
    Owner   = "Valerii Vasianovych"
    Project = "Terraform AWS"
  }
}

# --- Provider Configuration ---

provider "aws" {
  region = var.aws_region
}

# --- Data Sources ---

data "aws_availability_zones" "available" {
  state = "available"
}

# --- VPC & Internet Gateway ---

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    var.common_tags,
    {
      Name   = "${var.env}-vpc"
      Region = var.aws_region
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-igw"
    }
  )
}

# --- Public Subnets & Routing ---

resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index % length(data.aws_availability_zones.available.names)]
  map_public_ip_on_launch = false

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-public-subnet-${count.index + 1}"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-route-public-subnets"
    }
  )
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# --- NAT Gateways & Elastic IPs ---

resource "aws_eip" "nat" {
  count  = length(var.private_subnet_cidrs)
  domain = "vpc"

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-nat-eip-${count.index + 1}"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "nat" {
  count         = length(var.private_subnet_cidrs)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index % length(aws_subnet.public)].id

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-nat-gw-${count.index + 1}"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

# --- Private Subnets & Routing ---

resource "aws_subnet" "private" {
  count                   = length(var.private_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index % length(data.aws_availability_zones.available.names)]
  map_public_ip_on_launch = false

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-private-subnet-${count.index + 1}"
    }
  )
}

resource "aws_route_table" "private" {
  count  = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = merge(
    var.common_tags,
    {
      Name = "${var.env}-route-private-subnets-${count.index + 1}"
    }
  )
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# --- Outputs ---

output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "List of IDs for the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "List of IDs for the private subnets"
  value       = aws_subnet.private[*].id
}

output "nat_gateway_ips" {
  description = "Public IP addresses of the NAT Gateways"
  value       = aws_eip.nat[*].public_ip
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region where resources will be deployed."
  type        = string
  default     = "us-east-1"
}

variable "create_eks" {
  description = "Controls whether the EKS cluster and associated resources should be created."
  type        = bool
  default     = false
}

variable "cluster_name" {
  description = "Name of the EKS cluster."
  type        = string
  default     = ""
}

variable "cluster_version" {
  description = "Desired Kubernetes version for the EKS cluster. Defaults to the latest EKS default version when null."
  type        = string
  default     = null
}

variable "authentication_mode" {
  description = "The authentication mode for the cluster. Valid values are CONFIG_MAP, API, or API_AND_CONFIG_MAP."
  type        = string
  default     = "API_AND_CONFIG_MAP"
}

variable "control_plane_subnet_ids" {
  description = "A list of subnet IDs for the EKS cluster control plane (ENIs). If empty, subnet_ids will be used."
  type        = list(string)
  default     = []
}

variable "subnet_ids" {
  description = "A list of subnet IDs for the EKS cluster VPC configuration."
  type        = list(string)
  default     = []
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM ROLE & POLICY ATTACHMENTS FOR EKS CLUSTER
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "eks_assume_role" {
  count = var.create_eks ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_cluster" {
  count              = var.create_eks ? 1 : 0
  name               = "eks-cluster"
  assume_role_policy = data.aws_iam_policy_document.eks_assume_role[0].json

  tags = {
    Name = "eks-cluster"
  }
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  count      = var.create_eks ? 1 : 0
  role       = aws_iam_role.eks_cluster[0].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  count      = var.create_eks ? 1 : 0
  role       = aws_iam_role.eks_cluster[0].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

# ---------------------------------------------------------------------------------------------------------------------
# EKS CLUSTER
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_eks_cluster" "this" {
  count    = var.create_eks ? 1 : 0
  name     = var.cluster_name
  role_arn = aws_iam_role.eks_cluster[0].arn
  version  = var.cluster_version

  vpc_config {
    subnet_ids = length(var.control_plane_subnet_ids) > 0 ? var.control_plane_subnet_ids : var.subnet_ids
  }

  access_config {
    authentication_mode                         = var.authentication_mode
    bootstrap_cluster_creator_admin_permissions = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller
  ]
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "cluster_name" {
  description = "The name of the EKS cluster."
  value       = try(aws_eks_cluster.this[0].name, null)
}

output "cluster_arn" {
  description = "The ARN of the EKS cluster."
  value       = try(aws_eks_cluster.this[0].arn, null)
}

output "cluster_endpoint" {
  description = "The endpoint for the EKS cluster API server."
  value       = try(aws_eks_cluster.this[0].endpoint, null)
}

output "cluster_iam_role_arn" {
  description = "The ARN of the IAM role used by the EKS cluster."
  value       = try(aws_iam_role.eks_cluster[0].arn, null)
}

