provider "aws" {
  region = var.aws_region
}

# Fetch the current AWS caller identity context
data "aws_caller_identity" "current" {}

locals {
  users = {
    dev = {
      user_name   = "DevUser-rwwise.dev"
      policy_name = "dev_cicd_user_policy"
    }
    test = {
      user_name   = "TestUser-rwwise.dev"
      policy_name = "test_cicd_user_policy"
    }
    prod = {
      user_name   = "ProdUser-rwwise.dev"
      policy_name = "prod_cicd_user_policy"
    }
  }

  common_tags = {
    Name       = "rwwise.dev Infrastructure Setup"
    Repository = "https://github.com/zangrum/setup.inf.rwwise.dev"
    AccountId  = data.aws_caller_identity.current.account_id
    UserId     = data.aws_caller_identity.current.user_id
  }
}

# Shared IAM policy document for all three CI/CD users
data "aws_iam_policy_document" "cicd_policy_doc" {
  statement {
    sid    = "CodeStarConnectionsUserAccess"
    effect = "Allow"
    actions = [
      "codestar-connections:GetConnection",
      "codestar-connections:ListConnections",
      "codestar-connections:UseConnection"
    ]
    resources = [
      "arn:aws:codestar-connections:*:*:connection/*"
    ]
  }

  statement {
    sid    = "CodeStarNotificationsPowerUserAccess"
    effect = "Allow"
    actions = [
      "codestar-notifications:DescribeNotificationRule"
    ]
    resources = ["*"]
    condition {
      test     = "StringLike"
      variable = "codestar-notifications:NotificationsForResource"
      values   = ["arn:aws:codebuild:*"]
    }
  }

  statement {
    sid    = "CodeStarNotificationsListAccess"
    effect = "Allow"
    actions = [
      "codestar-notifications:ListEventTypes",
      "codestar-notifications:ListNotificationRules",
      "codestar-notifications:ListTargets"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CICDReadOnlyAndListAccess"
    effect = "Allow"
    actions = [
      "codebuild:BatchGet*",
      "codebuild:Describe*",
      "codebuild:List*",
      "codecommit:BatchDescribe*",
      "codecommit:BatchGet*",
      "codecommit:Describe*",
      "codecommit:Get*",
      "codecommit:List*",
      "cloudwatch:Describe*",
      "cloudwatch:Get*",
      "cloudwatch:List*",
      "events:DescribeRule",
      "events:ListRuleNamesByTarget",
      "events:ListRules",
      "events:ListTargetsByRule",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
      "logs:GetLogEvents",
      "logs:FilterLogEvents"
    ]
    resources = ["*"]
  }
}

# IAM Users
resource "aws_iam_user" "cicd_users" {
  for_each = local.users

  name = each.value.user_name
  path = "/system/"
  tags = local.common_tags
}

# IAM Access Keys for each user
resource "aws_iam_access_key" "cicd_access_keys" {
  for_each = aws_iam_user.cicd_users

  user   = each.value.name
  status = "Active"
}

# Inline user policy for each user
resource "aws_iam_user_policy" "cicd_user_policies" {
  for_each = local.users

  name   = each.value.policy_name
  user   = aws_iam_user.cicd_users[each.key].name
  policy = data.aws_iam_policy_document.cicd_policy_doc.json
}

# Outputs for generated access keys
output "iam_user_access_key_ids" {
  description = "Access Key IDs generated for the CI/CD IAM users."
  value = {
    for k, v in aws_iam_access_key.cicd_access_keys : k => v.id
  }
}
