terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy the infrastructure."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Name for the EventBridge resources. Defaults to 'default' if null or empty."
  type        = string
  default     = null
}

variable "tags" {
  description = "A mapping of tags to assign to all resources."
  type        = map(string)
  default     = {}
}

variable "bus" {
  description = "Configuration map for the EventBridge bus."
  type = object({
    event_source_name = optional(string, null)
  })
  default = {}
  validation {
    condition     = var.bus != null
    error_message = "The bus variable must not be null."
  }
}

variable "rules" {
  description = "List of EventBridge rules to create."
  type = list(object({
    name                = string
    description         = optional(string, null)
    event_pattern       = optional(string, null)
    schedule_expression = optional(string, null)
    state               = optional(string, "ENABLED")
  }))
  default = []
  validation {
    condition     = var.rules != null
    error_message = "The rules list must not be null."
  }
}

variable "targets" {
  description = "List of targets to associate with the EventBridge rules."
  type = list(object({
    rule      = string
    target_id = optional(string, null)
    arn       = string
    role_arn  = optional(string, null)
    input     = optional(string, null)
  }))
  default = []
  validation {
    condition     = var.targets != null
    error_message = "The targets list must not be null."
  }
}

data "aws_partition" "current" {}

locals {
  # Fall back to "default" if null or empty string
  effective_name = coalesce(var.name != "" ? var.name : null, "default")
  is_custom_bus  = local.effective_name != "default"
  dns_suffix     = data.aws_partition.current.dns_suffix

  # Map rules by name for easier lookup and iteration
  rules_map = { for rule in var.rules : rule.name => rule }

  # Map targets by unique key (rule and target ARN)
  targets_map = {
    for idx, target in var.targets :
    "${target.rule}-${idx}" => target
  }
}

# Conditionally create custom EventBridge bus if name is not "default"
resource "aws_cloudwatch_event_bus" "this" {
  count             = local.is_custom_bus ? 1 : 0
  name              = local.effective_name
  event_source_name = var.bus.event_source_name

  tags = merge(
    var.tags,
    {
      Name = local.effective_name
    }
  )
}

# IAM Role for EventBridge targets invocation
resource "aws_iam_role" "invoke" {
  name = "${local.effective_name}-invoke"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.${local.dns_suffix}"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(
    var.tags,
    {
      Name = "${local.effective_name}-invoke"
    }
  )
}

# Inline policy to invoke Lambda and Step Functions
resource "aws_iam_role_policy" "invoke_targets" {
  name = "${local.effective_name}-invoke-targets"
  role = aws_iam_role.invoke.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction",
          "states:StartExecution"
        ]
        Resource = "*"
      }
    ]
  })
}

# EventBridge Rules
resource "aws_cloudwatch_event_rule" "this" {
  for_each = local.rules_map

  name                = each.value.name
  description         = each.value.description
  event_bus_name      = local.is_custom_bus ? aws_cloudwatch_event_bus.this[0].name : "default"
  event_pattern       = each.value.event_pattern
  schedule_expression = each.value.schedule_expression
  state               = each.value.state

  tags = merge(
    var.tags,
    {
      Name = each.value.name
    }
  )
}

# EventBridge Targets
resource "aws_cloudwatch_event_target" "this" {
  for_each = local.targets_map

  event_bus_name = local.is_custom_bus ? aws_cloudwatch_event_bus.this[0].name : "default"
  rule           = each.value.rule
  target_id      = each.value.target_id
  arn            = each.value.arn
  input          = each.value.input

  # Assign IAM role if explicitly supplied or if the ARN is for Step Functions (stateMachine)
  role_arn = each.value.role_arn != null ? each.value.role_arn : (
    strcontains(each.value.arn, "stateMachine") ? aws_iam_role.invoke.arn : null
  )

  depends_on = [
    aws_cloudwatch_event_rule.this
  ]
}

output "event_bus_arn" {
  description = "The ARN of the EventBridge bus."
  value       = local.is_custom_bus ? aws_cloudwatch_event_bus.this[0].arn : "arn:${data.aws_partition.current.partition}:events:${var.aws_region}:*:event-bus/default"
}

output "event_bus_name" {
  description = "The name of the EventBridge bus."
  value       = local.is_custom_bus ? aws_cloudwatch_event_bus.this[0].name : "default"
}

output "rules" {
  description = "Map of created EventBridge rules."
  value       = { for k, v in aws_cloudwatch_event_rule.this : k => v.arn }
}

output "invoke_role_arn" {
  description = "The ARN of the IAM role for invoking targets."
  value       = aws_iam_role.invoke.arn
}

```terraform
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "AWS region for deployment."
  default     = "us-east-1"
}

variable "name" {
  type        = string
  description = "Base name identifier for dynamic resource naming."
  default     = "primary"
}

variable "kms_key_arn" {
  type        = string
  description = "Optional KMS key ARN for encrypting the backup vault."
  default     = null
}

variable "vault_policy" {
  type        = string
  description = "Optional JSON-formatted access policy for the backup vault."
  default     = ""
}

variable "sns_topic_arn" {
  type        = string
  description = "Optional SNS topic ARN for backup vault event notifications."
  default     = ""
}

variable "sns_events" {
  type        = list(string)
  description = "List of backup vault events to subscribe to."
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "schedule" {
  type        = string
  description = "Cron or rate expression for the backup plan schedule."
  default     = "cron(0 12 * * ? *)"
}

variable "start_window" {
  type        = number
  description = "The amount of time in minutes before beginning a backup."
  default     = 60
}

variable "completion_window" {
  type        = number
  description = "The amount of time in minutes AWS Backup attempts to complete a backup."
  default     = 120
}

variable "cold_storage_after" {
  type        = number
  description = "Specifies the number of days after creation that a recovery point moves to cold storage."
  default     = 30
}

variable "delete_after" {
  type        = number
  description = "Specifies the number of days after creation that a recovery point is deleted."
  default     = 120
}

variable "destination_vaults" {
  type = map(object({
    destination_vault_arn = string
    cold_storage_after    = optional(number)
    delete_after          = optional(number)
  }))
  description = "Map of destination vault configurations for copy actions."
  default     = {}
}

variable "selection_tag_type" {
  type        = string
  description = "Operation type for tag-based backup selection."
  default     = "STRINGEQUALS"
}

variable "selection_tag_key" {
  type        = string
  description = "Tag key used to filter resources for backup."
  default     = "Backup"
}

variable "selection_tag_value" {
  type        = string
  description = "Tag value used to filter resources for backup."
  default     = "true"
}

variable "tags" {
  type        = map(string)
  description = "Additional tags to apply to all taggable resources."
  default     = {}
}

# -----------------------------------------------------------------------------
# IAM Role and Policies for AWS Backup
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    effect  = "Allow"
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup_role" {
  name_prefix        = "aws-backup-"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json
  tags               = merge(var.tags, { Job = "${var.name}-backup" })
}

resource "aws_iam_role_policy_attachment" "backup_service_attachment" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# -----------------------------------------------------------------------------
# AWS Backup Vault
# -----------------------------------------------------------------------------

resource "aws_backup_vault" "vault" {
  name        = "vault-${var.name}-backup"
  kms_key_arn = var.kms_key_arn

  tags = merge(
    var.tags,
    {
      Job = "${var.name}-backup"
    }
  )
}

resource "aws_backup_vault_policy" "vault_policy" {
  count             = var.vault_policy != "" ? 1 : 0
  backup_vault_name = aws_backup_vault.vault.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_notifications" "vault_notifications" {
  count               = var.sns_topic_arn != "" ? 1 : 0
  backup_vault_name   = aws_backup_vault.vault.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.sns_events
}

# -----------------------------------------------------------------------------
# AWS Backup Plan
# -----------------------------------------------------------------------------

resource "aws_backup_plan" "plan" {
  name = "plan-${var.name}-backup"

  rule {
    rule_name         = "rule-${var.name}-backup"
    target_vault_name = aws_backup_vault.vault.name
    schedule          = var.schedule
    start_window      = var.start_window
    completion_window = var.completion_window

    recovery_point_tags = merge(
      var.tags,
      {
        Job = "${var.name}-backup"
      }
    )

    lifecycle {
      cold_storage_after = var.cold_storage_after
      delete_after       = var.delete_after
    }

    dynamic "copy_action" {
      for_each = var.destination_vaults
      content {
        destination_vault_arn = copy_action.value.destination_vault_arn

        dynamic "lifecycle" {
          for_each = copy_action.value.cold_storage_after != null || copy_action.value.delete_after != null ? [1] : []
          content {
            cold_storage_after = copy_action.value.cold_storage_after
            delete_after       = copy_action.value.delete_after
          }
        }
      }
    }
  }

  tags = merge(
    var.tags,
    {
      Job = "${var.name}-backup"
    }
  )
}

# -----------------------------------------------------------------------------
# AWS Backup Selection
# -----------------------------------------------------------------------------

resource "aws_backup_selection" "selection" {
  name         = "selection-${var.name}-backup"
  iam_role_arn = aws_iam_role.backup_role.arn
  plan_id      = aws_backup_plan.plan.id

  condition {}

  selection_tag {
    type  = var.selection_tag_type
    key   = var.selection_tag_key
    value = var.selection_tag_value
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "backup_vault_id" {
  description = "The name of the vault."
  value       = aws_backup_vault.vault.id
}

output "backup_vault_arn" {
  description = "The ARN of the backup vault."
  value       = aws_backup_vault.vault.arn
}

output "backup_plan_id" {
  description = "The ID of the backup plan."
  value       = aws_backup_plan.plan.id
}

output "backup_plan_arn" {
  description = "The ARN of the backup plan."
  value       = aws_backup_plan.plan.arn
}

output "backup_selection_id" {
  description = "The ID of the backup selection."
  value       = aws_backup_selection.selection.id
}

output "backup_iam_role_arn" {
  description = "The ARN of the IAM role used by AWS Backup."
  value       = aws_iam_role.backup_role.arn
}
```

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.60.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "create" {
  description = "Whether to create a new Transit Gateway or look up an existing one."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name identifier for the Transit Gateway and related resources."
  type        = string
  default     = "hub-tgw"
}

variable "id" {
  description = "ID of an existing Transit Gateway to look up when create is false."
  type        = string
  default     = null
}

variable "name_tag_filter" {
  description = "Name tag filter used to look up an existing Transit Gateway when create is false and id is null."
  type        = string
  default     = null
}

variable "amazon_side_asn" {
  description = "Private Autonomous System Number (ASN) for the Amazon side of a BGP session."
  type        = number
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "Whether resource attachment requests are automatically accepted."
  type        = string
  default     = "disable"
  validation {
    condition     = contains(["enable", "disable"], var.auto_accept_shared_attachments)
    error_message = "auto_accept_shared_attachments must be either 'enable' or 'disable'."
  }
}

variable "dns_support" {
  description = "Whether DNS resolution support is enabled."
  type        = string
  default     = "enable"
  validation {
    condition     = contains(["enable", "disable"], var.dns_support)
    error_message = "dns_support must be either 'enable' or 'disable'."
  }
}

variable "vpn_ecmp_support" {
  description = "Whether Equal Cost Multipath Protocol support is enabled for VPNs."
  type        = string
  default     = "enable"
  validation {
    condition     = contains(["enable", "disable"], var.vpn_ecmp_support)
    error_message = "vpn_ecmp_support must be either 'enable' or 'disable'."
  }
}

variable "transit_gateway_cidr_blocks" {
  description = "One or more IPv4 or IPv6 CIDR blocks for the transit gateway."
  type        = list(string)
  default     = []
  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks : can(cidrhost(cidr, 0))
    ])
    error_message = "All entries in transit_gateway_cidr_blocks must be valid IPv4 or IPv6 CIDRs."
  }
}

variable "route_tables" {
  description = "Map of route tables to create or look up. Key is the route table key name."
  type = map(object({
    create     = optional(bool, true)
    local_tags = optional(map(string), {})
  }))
  default = {
    "core" = {
      create     = true
      local_tags = { "Tier" = "Core" }
    }
    "shared" = {
      create     = true
      local_tags = { "Tier" = "Shared" }
    }
  }
}

variable "ram_resource_share_name" {
  description = "Name of the RAM resource share. Defaults to var.name if null."
  type        = string
  default     = null
}

variable "shared_principals" {
  description = "Map of external principals (AWS account IDs, OU ARNs, etc.) to share the Transit Gateway with via RAM."
  type        = map(string)
  default     = {}
}

variable "tags" {
  description = "Global tags to apply to all supported resources."
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# TRANSIT GATEWAY RESOURCE & DATA SOURCE
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  description                     = "Transit Gateway managed by Terraform"
  amazon_side_asn                 = var.amazon_side_asn
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks

  tags = merge(
    var.tags,
    {
      Name = var.name
    }
  )
}

data "aws_ec2_transit_gateway" "existing" {
  count = var.create ? 0 : 1

  id = var.id

  dynamic "filter" {
    for_each = var.id == null && var.name_tag_filter != null ? [1] : []
    content {
      name   = "tag:Name"
      values = [var.name_tag_filter]
    }
  }
}

locals {
  transit_gateway_id  = var.create ? aws_ec2_transit_gateway.this[0].id : data.aws_ec2_transit_gateway.existing[0].id
  transit_gateway_arn = var.create ? aws_ec2_transit_gateway.this[0].arn : data.aws_ec2_transit_gateway.existing[0].arn
}

# ---------------------------------------------------------------------------------------------------------------------
# TRANSIT GATEWAY ROUTE TABLES
# ---------------------------------------------------------------------------------------------------------------------

locals {
  route_tables_to_create = { for k, v in var.route_tables : k => v if coalesce(v.create, true) }
  route_tables_to_lookup = { for k, v in var.route_tables : k => v if !coalesce(v.create, true) }
}

resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = local.route_tables_to_create

  transit_gateway_id = local.transit_gateway_id

  tags = merge(
    var.tags,
    lookup(each.value, "local_tags", {}),
    {
      Name = coalesce(lookup(lookup(each.value, "local_tags", {}), "Name", null), each.key, var.name)
    }
  )
}

data "aws_ec2_transit_gateway_route_table" "existing" {
  for_each = local.route_tables_to_lookup

  filter {
    name   = "transit-gateway-id"
    values = [local.transit_gateway_id]
  }

  filter {
    name   = "tag:Name"
    values = [coalesce(lookup(lookup(each.value, "local_tags", {}), "Name", null), each.key, var.name)]
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# AWS RAM RESOURCE SHARE
# ---------------------------------------------------------------------------------------------------------------------

locals {
  enable_ram_share = length(var.shared_principals) > 0
  ram_share_name   = coalesce(var.ram_resource_share_name, var.name)
}

resource "aws_ram_resource_share" "this" {
  count = local.enable_ram_share ? 1 : 0

  name                      = local.ram_share_name
  allow_external_principals = true

  tags = merge(
    var.tags,
    {
      Name = local.ram_share_name
    }
  )
}

resource "aws_ram_resource_association" "this" {
  count = local.enable_ram_share ? 1 : 0

  resource_arn       = local.transit_gateway_arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

resource "aws_ram_principal_association" "this" {
  for_each = local.enable_ram_share ? var.shared_principals : {}

  principal          = each.value
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "transit_gateway_id" {
  description = "The ID of the Transit Gateway."
  value       = local.transit_gateway_id
}

output "transit_gateway_arn" {
  description = "The ARN of the Transit Gateway."
  value       = local.transit_gateway_arn
}

output "transit_gateway_route_table_ids" {
  description = "Map of Transit Gateway route table IDs (both newly created and looked up)."
  value = merge(
    { for k, v in aws_ec2_transit_gateway_route_table.this : k => v.id },
    { for k, v in data.aws_ec2_transit_gateway_route_table.existing : k => v.id }
  )
}

output "ram_resource_share_id" {
  description = "The ID of the RAM resource share if created."
  value       = try(aws_ram_resource_share.this[0].id, null)
}

output "ram_resource_share_arn" {
  description = "The ARN of the RAM resource share if created."
  value       = try(aws_ram_resource_share.this[0].arn, null)
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy the backup infrastructure into"
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# KMS Key for Backup Vaults
resource "aws_kms_key" "backup" {
  description             = "Shared KMS Key for AWS Backup Vaults"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = {
    Name = "backup-vaults-kms-key"
  }
}

resource "aws_kms_alias" "backup" {
  name          = "alias/backup-vaults-key"
  target_key_id = aws_kms_key.backup.key_id
}

# IAM Role for AWS Backup
resource "aws_iam_role" "backup_role" {
  name = "Bronze_Backup_Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_policy" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore_policy" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

# ==========================================
# Bronze Tier
# ==========================================
resource "aws_backup_vault" "bronze" {
  name        = "Bronze_Backup_Vault"
  kms_key_arn = aws_kms_key.backup.arn
}

resource "aws_backup_plan" "bronze" {
  name = "Bronze_Backup"

  rule {
    rule_name         = "Bronze_Backup_Weekly"
    target_vault_name = aws_backup_vault.bronze.name
    schedule          = "cron(0 0 ? * FRI *)"

    lifecycle {
      delete_after = 10
    }
  }
}

resource "aws_backup_selection" "bronze" {
  name         = "Bronze_Resource_Assignment"
  plan_id      = aws_backup_plan.bronze.id
  iam_role_arn = aws_iam_role.backup_role.arn

  condition {
    string_equals {
      key   = "aws:ResourceTag/Backup"
      value = "bronze"
    }
  }
}

# ==========================================
# Silver Tier
# ==========================================
resource "aws_backup_vault" "silver" {
  name        = "Silver_Backup_Vault"
  kms_key_arn = aws_kms_key.backup.arn
}

resource "aws_backup_plan" "silver" {
  name = "Silver_Backup_Plan"

  rule {
    rule_name         = "Silver_Backup_Daily"
    target_vault_name = aws_backup_vault.silver.name
    schedule          = "cron(0 5 ? * * *)"

    lifecycle {
      delete_after = 7
    }
  }
}

resource "aws_backup_selection" "silver" {
  name         = "Silver_Backup_resource"
  plan_id      = aws_backup_plan.silver.id
  iam_role_arn = aws_iam_role.backup_role.arn

  condition {
    string_equals {
      key   = "aws:ResourceTag/Backup"
      value = "silver"
    }
  }
}

# ==========================================
# Gold Tier
# ==========================================
resource "aws_backup_vault" "gold" {
  name        = "Gold_Backup_Vault"
  kms_key_arn = aws_kms_key.backup.arn
}

resource "aws_backup_plan" "gold" {
  name = "Gold_Backup"

  rule {
    rule_name         = "Gold_Daily_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 * * ? *)"

    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Gold_Monthly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 1 1/1 ? *)"

    lifecycle {
      delete_after = 365
    }
  }

  rule {
    rule_name         = "Gold_Yearly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 31 12 ? *)"

    lifecycle {
      delete_after = 2555
    }
  }
}

resource "aws_backup_selection" "gold" {
  name         = "Gold_Backup_Select"
  plan_id      = aws_backup_plan.gold.id
  iam_role_arn = aws_iam_role.backup_role.arn

  condition {
    string_equals {
      key   = "aws:ResourceTag/Backup"
      value = "gold"
    }
  }
}

# ==========================================
# Premium Tier
# ==========================================
resource "aws_backup_vault" "premium" {
  name        = "Premium"
  kms_key_arn = aws_kms_key.backup.arn
}

resource "aws_backup_plan" "premium" {
  name = "Premium"

  rule {
    rule_name         = "Premium_Daily_4Hour_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0/4 ? * * *)"

    lifecycle {
      delete_after = 1
    }
  }

  rule {
    rule_name         = "Premium_Daily_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 * * ? *)"

    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Premium_Monthly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 1 1/1 ? *)"

    lifecycle {
      cold_storage_after = 15
      delete_after       = 365
    }
  }

  rule {
    rule_name         = "Premium_Yearly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 31 12 ? *)"

    lifecycle {
      cold_storage_after = 15
      delete_after       = 2555
    }
  }
}

resource "aws_backup_selection" "premium" {
  name         = "Premium"
  plan_id      = aws_backup_plan.premium.id
  iam_role_arn = aws_iam_role.backup_role.arn

  condition {
    string_equals {
      key   = "aws:ResourceTag/Backup"
      value = "premium"
    }
  }
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
