variable "aws_region" {
  type        = string
  description = "The AWS region where resources will be managed."
  default     = "us-east-1"
}

variable "role_name" {
  type        = string
  description = "The name of the IAM role to create for Prisma Cloud."
  default     = "PrismaCloudReadWriteRole"
}

variable "read_write" {
  type        = bool
  description = "Boolean flag to determine whether remediation (read-write) permissions are enabled."
  default     = false
}

provider "aws" {
  region = var.aws_region
}

# Generate a 32-character alphanumeric external ID
resource "random_string" "external_id" {
  length  = 32
  special = false
  upper   = true
  lower   = true
  numeric = true
}

# Trust policy allowing Prisma Cloud's account to assume the role using the generated External ID
data "aws_iam_policy_document" "assume_role_policy" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::188619942792:root"]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [random_string.external_id.result]
    }
  }
}

# Prisma Cloud IAM Role
resource "aws_iam_role" "prisma_cloud_role" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.assume_role_policy.json

  tags = {
    Integration = "PrismaCloud"
  }
}

# Attach AWS Managed SecurityAudit Policy
resource "aws_iam_role_policy_attachment" "security_audit" {
  role       = aws_iam_role.prisma_cloud_role.name
  policy_arn = "arn:aws:iam::aws:policy/SecurityAudit"
}

# Inline Policy for Read-Only Permissions
data "aws_iam_policy_document" "read_only_policy" {
  statement {
    effect = "Allow"
    actions = [
      "apigateway:GET",
      "cognito-identity:ListTagsForResource",
      "cognito-idp:ListTagsForResource",
      "ecr:DescribeImages",
      "ecr:GetLifecyclePolicy",
      "elasticbeanstalk:ListTagsForResource",
      "elasticfilesystem:DescribeTags",
      "glacier:GetVaultLock",
      "glacier:ListTagsForVault",
      "glue:GetSecurityConfigurations",
      "logs:GetLogEvents",
      "mq:listBrokers",
      "mq:describeBroker",
      "ram:GetResourceShares",
      "secretsmanager:DescribeSecret",
      "ssm:GetParameters",
      "ssm:ListTagsForResource",
      "sqs:SendMessage",
      "elasticmapreduce:ListSecurityConfigurations",
      "sns:listSubscriptions",
      "wafv2:ListResourcesForWebACL",
      "wafv2:ListWebACLs"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "prisma_cloud_read_only" {
  name   = "PrismaCloud-IAM-ReadOnly-Policy"
  role   = aws_iam_role.prisma_cloud_role.id
  policy = data.aws_iam_policy_document.read_only_policy.json
}

# Conditional Inline Policy for Remediation Permissions
data "aws_iam_policy_document" "remediation_policy" {
  statement {
    effect = "Allow"
    actions = [
      "iam:UpdateAccountPasswordPolicy",
      "ec2:ModifyImageAttribute",
      "rds:ModifyDBSnapshotAttribute",
      "s3:PutBucketAcl",
      "ec2:RevokeSecurityGroupIngress"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "prisma_cloud_remediation" {
  count  = var.read_write ? 1 : 0
  name   = "PrismaCloud-IAM-Remediation-Policy"
  role   = aws_iam_role.prisma_cloud_role.id
  policy = data.aws_iam_policy_document.remediation_policy.json
}

output "role_arn" {
  description = "The ARN of the IAM role created for Prisma Cloud."
  value       = aws_iam_role.prisma_cloud_role.arn
}

output "external_id" {
  description = "The External ID configured for the Prisma Cloud integration."
  value       = random_string.external_id.result
  sensitive   = true
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  description = "The AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "10.0.2.0/24"
}

# -----------------------------------------------------------------------------
# Availability Zones Data Source
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# VPC and Subnets
# -----------------------------------------------------------------------------
resource "aws_vpc" "development_be_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "development-be-vpc"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.development_be_vpc.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "development-be-public-subnet"
  }
}

resource "aws_subnet" "private_subnet" {
  vpc_id                  = aws_vpc.development_be_vpc.id
  cidr_block              = var.private_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "development-be-private-subnet"
  }
}

# -----------------------------------------------------------------------------
# Internet Gateway and Routing
# -----------------------------------------------------------------------------
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.development_be_vpc.id

  tags = {
    Name = "development-be-ig"
  }
}

resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.development_be_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "development-be-public-rt"
  }
}

resource "aws_route_table_association" "public_assoc" {
  subnet_id      = aws_subnet.public_subnet.id
  route_table_id = aws_route_table.public_rt.id
}

# -----------------------------------------------------------------------------
# Security Group
# -----------------------------------------------------------------------------
resource "aws_security_group" "http_access" {
  name        = "http_access"
  description = "Security group for HTTP access and restricted SSH/egress"
  vpc_id      = aws_vpc.development_be_vpc.id

  # Inbound HTTP from anywhere
  ingress {
    description = "Allow HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Inbound SSH only from VPC CIDR
  ingress {
    description = "Allow SSH from within the VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  # Outbound traffic restricted to VPC CIDR
  egress {
    description = "Allow outbound traffic only to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "development-be-sg"
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "ID of the development backend VPC"
  value       = aws_vpc.development_be_vpc.id
}

output "public_subnet_id" {
  description = "ID of the public subnet"
  value       = aws_subnet.public_subnet.id
}

output "private_subnet_id" {
  description = "ID of the private subnet"
  value       = aws_subnet.private_subnet.id
}
```

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# --------------------------------------------------------------------------------------------------
# VARIABLES
# --------------------------------------------------------------------------------------------------

variable "aws_region" {
  description = "The AWS region where resources will be provisioned."
  type        = string
  default     = "us-east-1"
}

variable "create" {
  description = "Controls if SNS resources should be created."
  type        = bool
  default     = true
}

variable "name" {
  description = "The name of the SNS topic. If omitted, Terraform will assign a random name."
  type        = string
  default     = "production-messaging-topic"
}

variable "use_name_prefix" {
  description = "Determines whether to use name or name_prefix for the SNS topic."
  type        = bool
  default     = false
}

variable "display_name" {
  description = "The display name for the SNS topic."
  type        = string
  default     = "AppMessagingTopic"
}

variable "fifo_topic" {
  description = "Boolean indicating whether or not to create a FIFO (first-in-first-out) topic."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO topics."
  type        = bool
  default     = false
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SNS or a custom CMK."
  type        = string
  default     = "alias/aws/sns"
}

variable "delivery_policy" {
  description = "The SNS delivery policy JSON."
  type        = string
  default     = null
}

variable "signature_version" {
  description = "If given, enables message signature verification. FIFO topics cannot use this."
  type        = number
  default     = 2
}

variable "tracing_config" {
  description = "Tracing mode of an SNS topic. Valid values: PassThrough, Active."
  type        = string
  default     = "PassThrough"
}

# Protocol Feedback Logging Configurations
variable "application_feedback" {
  description = "Map of configuration attributes for application feedback logging."
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

variable "firehose_feedback" {
  description = "Map of configuration attributes for Firehose feedback logging."
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

variable "http_feedback" {
  description = "Map of configuration attributes for HTTP/S feedback logging."
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

variable "lambda_feedback" {
  description = "Map of configuration attributes for Lambda feedback logging."
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

variable "sqs_feedback" {
  description = "Map of configuration attributes for SQS feedback logging."
  type = object({
    failure_role_arn    = optional(string)
    success_role_arn    = optional(string)
    success_sample_rate = optional(number)
  })
  default = {}
}

# Policy Configuration Variables
variable "create_topic_policy" {
  description = "Controls if an SNS topic policy should be created and applied."
  type        = bool
  default     = true
}

variable "topic_policy" {
  description = "External IAM policy string to apply if create_topic_policy is false."
  type        = string
  default     = null
}

variable "enable_default_topic_policy" {
  description = "Specifies whether to enable the default SNS topic policy granting owner standard operations."
  type        = bool
  default     = true
}

variable "source_topic_policy_documents" {
  description = "List of IAM policy documents that are merged together into the exported document."
  type        = list(string)
  default     = []
}

variable "override_topic_policy_documents" {
  description = "List of IAM policy documents that take precedence over the generated topic policy."
  type        = list(string)
  default     = []
}

variable "topic_policy_statements" {
  description = "A map of IAM policy statements to append to the topic policy."
  type = map(object({
    sid           = optional(string)
    effect        = optional(string, "Allow")
    actions       = list(string)
    not_actions   = optional(list(string))
    principals    = optional(list(object({ type = string, identifiers = list(string) })))
    not_principals = optional(list(object({ type = string, identifiers = list(string) })))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = {}
}

# Subscription Configurations
variable "create_subscription" {
  description = "Controls whether subscriptions should be provisioned for this topic."
  type        = bool
  default     = true
}

variable "subscriptions" {
  description = "Map of SNS topic subscriptions to create."
  type = map(object({
    protocol                        = string
    endpoint                        = string
    endpoint_auto_confirms          = optional(bool, false)
    confirmation_timeout_in_minutes = optional(number)
    raw_message_delivery            = optional(bool, false)
    filter_policy                   = optional(string)
    filter_policy_scope             = optional(string)
    delivery_policy                 = optional(string)
    redrive_policy                  = optional(string)
    subscription_role_arn           = optional(string)
  }))
  default = {}
}

# Data Protection Policy Variable
variable "data_protection_policy" {
  description = "The JSON string for the Amazon SNS topic data protection policy."
  type        = string
  default     = null
}

variable "tags" {
  description = "A map of tags to assign to the resources."
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

# --------------------------------------------------------------------------------------------------
# CALLER AND PARTITION CONTEXT
# --------------------------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# --------------------------------------------------------------------------------------------------
# SNS TOPIC RESOURCE
# --------------------------------------------------------------------------------------------------

resource "aws_sns_topic" "this" {
  count = var.create ? 1 : 0

  name        = var.use_name_prefix ? null : (var.fifo_topic && var.name != null && !endswith(var.name, ".fifo") ? "${var.name}.fifo" : var.name)
  name_prefix = var.use_name_prefix ? (var.name != null ? var.name : "sns-topic-") : null

  display_name                = var.display_name
  kms_master_key_id           = var.kms_master_key_id
  delivery_policy             = var.delivery_policy
  signature_version           = var.fifo_topic ? null : var.signature_version
  tracing_config              = var.tracing_config
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : null

  # Feedback role ARNs and sample rates
  application_failure_feedback_role_arn    = lookup(var.application_feedback, "failure_role_arn", null)
  application_success_feedback_role_arn    = lookup(var.application_feedback, "success_role_arn", null)
  application_success_feedback_sample_rate = lookup(var.application_feedback, "success_sample_rate", null)

  firehose_failure_feedback_role_arn    = lookup(var.firehose_feedback, "failure_role_arn", null)
  firehose_success_feedback_role_arn    = lookup(var.firehose_feedback, "success_role_arn", null)
  firehose_success_feedback_sample_rate = lookup(var.firehose_feedback, "success_sample_rate", null)

  http_failure_feedback_role_arn    = lookup(var.http_feedback, "failure_role_arn", null)
  http_success_feedback_role_arn    = lookup(var.http_feedback, "success_role_arn", null)
  http_success_feedback_sample_rate = lookup(var.http_feedback, "success_sample_rate", null)

  lambda_failure_feedback_role_arn    = lookup(var.lambda_feedback, "failure_role_arn", null)
  lambda_success_feedback_role_arn    = lookup(var.lambda_feedback, "success_role_arn", null)
  lambda_success_feedback_sample_rate = lookup(var.lambda_feedback, "success_sample_rate", null)

  sqs_failure_feedback_role_arn    = lookup(var.sqs_feedback, "failure_role_arn", null)
  sqs_success_feedback_role_arn    = lookup(var.sqs_feedback, "success_role_arn", null)
  sqs_success_feedback_sample_rate = lookup(var.sqs_feedback, "success_sample_rate", null)

  tags = var.tags
}

# --------------------------------------------------------------------------------------------------
# ACCESS POLICY LOGIC
# --------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "this" {
  count = var.create && var.create_topic_policy ? 1 : 0

  source_policy_documents   = var.source_topic_policy_documents
  override_policy_documents = var.override_topic_policy_documents

  dynamic "statement" {
    for_each = var.enable_default_topic_policy ? [1] : []
    content {
      sid    = "__default_statement_ID"
      effect = "Allow"
      actions = [
        "SNS:GetTopicAttributes",
        "SNS:SetTopicAttributes",
        "SNS:AddPermission",
        "SNS:RemovePermission",
        "SNS:DeleteTopic",
        "SNS:Subscribe",
        "SNS:ListSubscriptionsByTopic",
        "SNS:Publish"
      ]
      resources = [aws_sns_topic.this[0].arn]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "StringEquals"
        variable = "AWS:SourceOwner"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }

  dynamic "statement" {
    for_each = var.topic_policy_statements
    content {
      sid         = lookup(statement.value, "sid", statement.key)
      effect      = lookup(statement.value, "effect", "Allow")
      actions     = statement.value.actions
      not_actions = lookup(statement.value, "not_actions", null)
      resources   = [aws_sns_topic.this[0].arn]

      dynamic "principals" {
        for_each = lookup(statement.value, "principals", [])
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = lookup(statement.value, "not_principals", [])
        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = lookup(statement.value, "conditions", [])
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = var.create ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.create_topic_policy ? data.aws_iam_policy_document.this[0].json : var.topic_policy
}

# --------------------------------------------------------------------------------------------------
# SUBSCRIPTIONS
# --------------------------------------------------------------------------------------------------

resource "aws_sns_topic_subscription" "this" {
  for_each = var.create && var.create_subscription ? var.subscriptions : {}

  topic_arn                       = aws_sns_topic.this[0].arn
  protocol                        = each.value.protocol
  endpoint                        = each.value.endpoint
  endpoint_auto_confirms          = each.value.endpoint_auto_confirms
  confirmation_timeout_in_minutes = each.value.confirmation_timeout_in_minutes
  raw_message_delivery            = each.value.raw_message_delivery
  filter_policy                   = each.value.filter_policy
  filter_policy_scope             = each.value.filter_policy_scope
  delivery_policy                 = each.value.delivery_policy
  redrive_policy                  = each.value.redrive_policy
  subscription_role_arn           = each.value.subscription_role_arn
}

# --------------------------------------------------------------------------------------------------
# DATA PROTECTION POLICY
# --------------------------------------------------------------------------------------------------

resource "aws_sns_topic_data_protection_policy" "this" {
  count = var.create && var.data_protection_policy != null && !var.fifo_topic ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.data_protection_policy
}

# --------------------------------------------------------------------------------------------------
# OUTPUTS
# --------------------------------------------------------------------------------------------------

output "topic_arn" {
  description = "The ARN of the SNS topic."
  value       = try(aws_sns_topic.this[0].arn, null)
}

output "topic_id" {
  description = "The ID of the SNS topic."
  value       = try(aws_sns_topic.this[0].id, null)
}

output "topic_name" {
  description = "The name of the SNS topic."
  value       = try(aws_sns_topic.this[0].name, null)
}

output "subscription_arns" {
  description = "List of ARNs of created subscriptions."
  value       = { for k, v in aws_sns_topic_subscription.this : k => v.arn }
}

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region to deploy the resources."
  default     = "us-east-1"
}

variable "bucket_name" {
  type        = string
  description = "Optional custom name for the bucket. Defaults to corebucket-<random-hex>."
  default     = null
}

variable "prefix" {
  type        = bool
  description = "Whether to append an extra random string suffix to the bucket name."
  default     = false
}

variable "request_payer" {
  type        = string
  description = "Bucket request payer configuration (BucketOwner or Requester)."
  default     = "BucketOwner"
}

variable "encryption" {
  type        = bool
  description = "Enable server-side KMS encryption for the bucket."
  default     = true
}

variable "kms_key" {
  type        = string
  description = "External KMS key ARN. If empty and encryption is true, a rotating CMK is created."
  default     = ""
}

variable "versioning" {
  type        = bool
  description = "Enable versioning on the bucket."
  default     = false
}

variable "mfa_delete" {
  type        = bool
  description = "Enable MFA delete on versioning (Enabled or Disabled)."
  default     = false
}

variable "force_destroy" {
  type        = bool
  description = "Allow deletion of non-empty bucket."
  default     = false
}

variable "tags" {
  type        = map(string)
  description = "A mapping of tags to assign to the bucket."
  default     = {}
}

variable "acl" {
  type        = string
  description = "The canned ACL to apply. Defaults to null."
  default     = null
}

variable "grants" {
  type = list(object({
    id          = optional(string)
    type        = string
    permissions = list(string)
    uri         = optional(string)
  }))
  description = "List of grant configurations for bucket ACL."
  default     = []
}

variable "bucket_policy" {
  type        = string
  description = "A valid JSON bucket policy document."
  default     = null
}

variable "transfer_acceleration_status" {
  type        = string
  description = "Transfer acceleration status ('Enabled' or 'Suspended')."
  default     = null
}

variable "logging" {
  type = object({
    target_bucket = string
    target_prefix = optional(string, "")
  })
  description = "Logging configuration for the S3 bucket."
  default     = null
}

variable "website" {
  type = object({
    index_document           = optional(string)
    error_document           = optional(string)
    redirect_all_requests_to = optional(string)
  })
  description = "Static website hosting configuration."
  default     = null
}

variable "cors_rules" {
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  description = "CORS rules for the bucket."
  default     = []
}

variable "lifecycle_rules" {
  type = list(object({
    id      = string
    enabled = bool
    prefix  = optional(string)
    tags    = optional(map(string))
    transitions = optional(list(object({
      days          = optional(number)
      storage_class = string
    })), [])
    expiration = optional(object({
      days = optional(number)
    }))
    noncurrent_version_transitions = optional(list(object({
      days          = optional(number)
      storage_class = string
    })), [])
    noncurrent_version_expiration = optional(object({
      days = optional(number)
    }))
  }))
  description = "Lifecycle rules for the bucket."
  default     = []
}

variable "object_lock_configuration" {
  type = object({
    mode  = string # "GOVERNANCE" or "COMPLIANCE"
    days  = optional(number)
    years = optional(number)
  })
  description = "Object lock configuration default retention parameters."
  default     = null
}

variable "replication_role" {
  type        = string
  description = "ARN of existing IAM role for replication. If not supplied and replication_rules are present, a role will be created."
  default     = ""
}

variable "replication_rules" {
  type = list(object({
    id       = string
    priority = optional(number)
    status   = string
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    destination = object({
      bucket        = string
      storage_class = optional(string)
    })
    delete_marker_replication = optional(string) # "Enabled" or "Disabled"
  }))
  description = "Replication rules configuration."
  default     = []
}

# -----------------------------------------------------------------------------
# Dynamic Name Resolution
# -----------------------------------------------------------------------------
resource "random_id" "base_suffix" {
  byte_length = 4
}

resource "random_id" "extra_suffix" {
  byte_length = 4
}

locals {
  base_bucket_name = coalesce(var.bucket_name, "corebucket-${random_id.base_suffix.hex}")
  final_bucket_name = var.prefix ? "${local.base_bucket_name}-${random_id.extra_suffix.hex}" : local.base_bucket_name

  object_lock_enabled = var.object_lock_configuration != null
  create_kms_key      = var.encryption && var.kms_key == ""
  effective_kms_key_arn = var.encryption ? (
    local.create_kms_key ? aws_kms_key.s3_key[0].arn : var.kms_key
  ) : null

  has_replication = length(var.replication_rules) > 0
  create_rep_role = local.has_replication && var.replication_role == ""
  effective_rep_role_arn = local.has_replication ? (
    local.create_rep_role ? aws_iam_role.replication_role[0].arn : var.replication_role
  ) : null
}

# -----------------------------------------------------------------------------
# Customer Managed KMS Key (Created when encryption is true and kms_key is "")
# -----------------------------------------------------------------------------
resource "aws_kms_key" "s3_key" {
  count                   = local.create_kms_key ? 1 : 0
  description             = "Customer managed rotating KMS key for S3 bucket ${local.final_bucket_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags = merge(var.tags, {
    Name = "kms-${local.final_bucket_name}"
  })
}

resource "aws_kms_alias" "s3_key_alias" {
  count         = local.create_kms_key ? 1 : 0
  name          = "alias/${local.final_bucket_name}"
  target_key_id = aws_kms_key.s3_key[0].key_id
}

# -----------------------------------------------------------------------------
# Amazon S3 Bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "this" {
  bucket              = local.final_bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = local.object_lock_enabled
  tags                = var.tags
}

# -----------------------------------------------------------------------------
# Public Access Block (Strictly Block All Public Access)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# Encryption Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = var.encryption ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.effective_kms_key_arn
    }
    bucket_key_enabled = true
  }
}

# -----------------------------------------------------------------------------
# Request Payer
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_request_payment_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  payer  = var.request_payer
}

# -----------------------------------------------------------------------------
# Versioning Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "this" {
  # Versioning must be Enabled if object lock or replication is active
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = (var.versioning || local.object_lock_enabled || local.has_replication) ? "Enabled" : "Suspended"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

# -----------------------------------------------------------------------------
# Access Control (ACL / Grants)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_ownership_controls" "this" {
  count  = (var.acl != null || length(var.grants) > 0) ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "this" {
  count      = (var.acl != null || length(var.grants) > 0) ? 1 : 0
  bucket     = aws_s3_bucket.this.id
  acl        = length(var.grants) == 0 ? var.acl : null
  depends_on = [aws_s3_bucket_ownership_controls.this]

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []
    content {
      dynamic "grant" {
        for_each = var.grants
        content {
          grantee {
            id   = grant.value.id
            type = grant.value.type
            uri  = grant.value.uri
          }
          permission = grant.value.permissions[0]
        }
      }
      owner {
        id = data.aws_canonical_user_id.current.id
      }
    }
  }
}

data "aws_canonical_user_id" "current" {}

# -----------------------------------------------------------------------------
# Bucket Policy
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "this" {
  count  = var.bucket_policy != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  policy = var.bucket_policy

  depends_on = [aws_s3_bucket_public_access_block.this]
}

# -----------------------------------------------------------------------------
# Object Lock Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = local.object_lock_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.mode
      days  = var.object_lock_configuration.days
      years = var.object_lock_configuration.years
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

# -----------------------------------------------------------------------------
# Transfer Acceleration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = var.transfer_acceleration_status != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration_status
}

# -----------------------------------------------------------------------------
# Logging Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "this" {
  count  = var.logging != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging.target_bucket
  target_prefix = var.logging.target_prefix
}

# -----------------------------------------------------------------------------
# Website Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.website != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = var.website.index_document != null ? [var.website.index_document] : []
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = var.website.error_document != null ? [var.website.error_document] : []
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = var.website.redirect_all_requests_to != null ? [var.website.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value
    }
  }
}

# -----------------------------------------------------------------------------
# CORS Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# -----------------------------------------------------------------------------
# Lifecycle Configuration
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = rule.value.prefix != null || rule.value.tags != null ? [1] : []
        content {
          dynamic "and" {
            for_each = rule.value.prefix != null && rule.value.tags != null ? [1] : []
            content {
              prefix = rule.value.prefix
              tags   = rule.value.tags
            }
          }
          prefix = (rule.value.prefix != null && rule.value.tags == null) ? rule.value.prefix : null
          dynamic "tag" {
            for_each = (rule.value.prefix == null && rule.value.tags != null) ? rule.value.tags : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions
        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days = expiration.value.days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions
        content {
          noncurrent_days = noncurrent_version_transition.value.days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.days
        }
      }
    }
  }
}

# -----------------------------------------------------------------------------
# Replication Configuration and IAM Resources
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "replication_assume_role" {
  count = local.create_rep_role ? 1 : 0
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication_role" {
  count              = local.create_rep_role ? 1 : 0
  name               = "CoreS3ReplicationRole_${local.final_bucket_name}"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role[0].json
  tags               = var.tags
}

data "aws_iam_policy_document" "replication_policy" {
  count = local.create_rep_role ? 1 : 0
  statement {
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]
    resources = [aws_s3_bucket.this.arn]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging"
    ]
    resources = ["${aws_s3_bucket.this.arn}/*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags"
    ]
    resources = [for r in var.replication_rules : "${r.destination.bucket}/*"]
  }
}

resource "aws_iam_policy" "replication_policy" {
  count       = local.create_rep_role ? 1 : 0
  name        = "CoreS3ReplicationPolicy_${local.final_bucket_name}"
  description = "IAM policy for S3 cross-region replication for bucket ${local.final_bucket_name}"
  policy      = data.aws_iam_policy_document.replication_policy[0].json
}

resource "aws_iam_role_policy_attachment" "replication_attach" {
  count      = local.create_rep_role ? 1 : 0
  role       = aws_iam_role.replication_role[0].name
  policy_arn = aws_iam_policy.replication_policy[0].arn
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count      = local.has_replication ? 1 : 0
  bucket     = aws_s3_bucket.this.id
  role       = local.effective_rep_role_arn
  depends_on = [aws_s3_bucket_versioning.this, aws_iam_role_policy_attachment.replication_attach]

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = rule.value.id
      priority = rule.value.priority
      status   = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = filter.value.prefix
          dynamic "tag" {
            for_each = filter.value.tags != null ? filter.value.tags : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "delete_marker_replication" {
        for_each = rule.value.delete_marker_replication != null ? [rule.value.delete_marker_replication] : []
        content {
          status = delete_marker_replication.value
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = rule.value.destination.storage_class
      }
    }
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "bucket_id" {
  description = "The name of the bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "The bucket domain name."
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used for encryption."
  value       = local.effective_kms_key_arn
}

output "replication_role_arn" {
  description = "The ARN of the IAM role used for replication."
  value       = local.effective_rep_role_arn
}
```

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region for resources"
  type        = string
  default     = "us-east-1"
}

variable "random_suffix" {
  description = "Whether to append a random suffix to resource names"
  type        = bool
  default     = true
}

variable "random_suffix_length" {
  description = "Length of the random suffix string"
  type        = number
  default     = 4
}

variable "bucket_name_prefix" {
  description = "Base prefix name for the S3 bucket"
  type        = string
  default     = "zedcloud"
}

variable "iam_user_name_prefix" {
  description = "Base prefix name for the IAM user"
  type        = string
  default     = "zedcloud-s3-user"
}

variable "iam_policy_name_prefix" {
  description = "Base prefix name for the IAM policy"
  type        = string
  default     = "zedcloud-s3-policy"
}

variable "upload_image" {
  description = "Whether to upload a local image file to S3"
  type        = bool
  default     = false
}

variable "create_folder" {
  description = "Whether to place the uploaded image within an S3 folder"
  type        = bool
  default     = true
}

variable "s3_folder" {
  description = "Folder name in S3 to place the uploaded image"
  type        = string
  default     = "my-folder"
}

variable "image_filename" {
  description = "Filename of the local image located in the execution directory"
  type        = string
  default     = "my-file.qcow2"
}

variable "create_iam_user" {
  description = "Whether to provision the IAM read-only user, access key, and policy"
  type        = bool
  default     = true
}

# -----------------------------------------------------------------------------
# Random Suffix Generator
# -----------------------------------------------------------------------------

resource "random_string" "suffix" {
  count   = var.random_suffix ? 1 : 0
  length  = var.random_suffix_length
  special = false
  upper   = false
  numeric = true
}

locals {
  suffix             = var.random_suffix && length(random_string.suffix) > 0 ? "-${random_string.suffix[0].result}" : ""
  bucket_name        = "${var.bucket_name_prefix}${local.suffix}"
  iam_user_name      = "${var.iam_user_name_prefix}${local.suffix}"
  iam_policy_name    = "${var.iam_policy_name_prefix}${local.suffix}"
  s3_destination_key = var.create_folder ? "${var.s3_folder}/${var.image_filename}" : var.image_filename
}

# -----------------------------------------------------------------------------
# KMS Customer Managed Key
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "s3_key" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${local.bucket_name}-kms-key"
  }
}

resource "aws_kms_alias" "s3_key_alias" {
  name          = "alias/${local.bucket_name}-key"
  target_key_id = aws_kms_key.s3_key.key_id
}

# -----------------------------------------------------------------------------
# Amazon S3 Bucket & Security Configuration
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "datastore" {
  bucket        = local.bucket_name
  force_destroy = true

  tags = {
    Name = local.bucket_name
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "datastore_encryption" {
  bucket = aws_s3_bucket.datastore.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "datastore_public_block" {
  bucket = aws_s3_bucket.datastore.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# Optional Image Upload Resource
# -----------------------------------------------------------------------------

resource "aws_s3_object" "image_upload" {
  count       = var.upload_image ? 1 : 0
  bucket      = aws_s3_bucket.datastore.id
  key         = local.s3_destination_key
  source      = "${path.module}/${var.image_filename}"
  kms_key_id  = aws_kms_key.s3_key.arn
  source_hash = fileexists("${path.module}/${var.image_filename}") ? filemd5("${path.module}/${var.image_filename}") : null

  depends_on = [
    aws_s3_bucket_server_side_encryption_configuration.datastore_encryption,
    aws_s3_bucket_public_access_block.datastore_public_block
  ]
}

# -----------------------------------------------------------------------------
# Scoped IAM Read-Only Access
# -----------------------------------------------------------------------------

resource "aws_iam_user" "s3_reader" {
  count         = var.create_iam_user ? 1 : 0
  name          = local.iam_user_name
  path          = "/"
  force_destroy = true

  tags = {
    Name = local.iam_user_name
  }
}

resource "aws_iam_access_key" "s3_reader_key" {
  count  = var.create_iam_user ? 1 : 0
  user   = aws_iam_user.s3_reader[0].name
  status = "Active"
}

resource "aws_iam_policy" "s3_read_policy" {
  count       = var.create_iam_user ? 1 : 0
  name        = local.iam_policy_name
  description = "Scoped read-only permissions for S3 bucket ${local.bucket_name}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ListBucket"
        Effect = "Allow"
        Action = [
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.datastore.arn
      },
      {
        Sid    = "S3GetObject"
        Effect = "Allow"
        Action = [
          "s3:GetObject"
        ]
        Resource = "${aws_s3_bucket.datastore.arn}/*"
      },
      {
        Sid    = "KMSDecryptPermission"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.s3_key.arn
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "s3_reader_attach" {
  count      = var.create_iam_user ? 1 : 0
  user       = aws_iam_user.s3_reader[0].name
  policy_arn = aws_iam_policy.s3_read_policy[0].arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "s3_bucket_name" {
  description = "Name of the created S3 bucket"
  value       = aws_s3_bucket.datastore.id
}

output "s3_bucket_arn" {
  description = "ARN of the created S3 bucket"
  value       = aws_s3_bucket.datastore.arn
}

output "kms_key_arn" {
  description = "ARN of the KMS encryption key"
  value       = aws_kms_key.s3_key.arn
}

output "iam_user_name" {
  description = "Name of the IAM read-only user"
  value       = var.create_iam_user ? aws_iam_user.s3_reader[0].name : null
}

output "iam_access_key_id" {
  description = "Access key ID for the IAM read-only user"
  value       = var.create_iam_user ? aws_iam_access_key.s3_reader_key[0].id : null
}

output "iam_access_key_secret" {
  description = "Access key secret for the IAM read-only user"
  value       = var.create_iam_user ? aws_iam_access_key.s3_reader_key[0].secret : null
  sensitive   = true
}
```

```terraform
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

variable "default_tags" {
  type        = map(string)
  description = "Default tags to apply to all resources via the AWS provider"
  default = {
    Project     = "tf-eks-jofo"
    Owner       = "Jovan Zelincevic"
    Compliance  = "Nothing"
    Environment = "dev"
    Provider    = "Terraform"
  }
}

variable "vpc_cidr" {
  type        = string
  description = "Base CIDR block for the VPC"
  default     = "10.14.0.0/16"
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = var.default_tags
  }
}

# Data source to fetch available AZs
data "aws_availability_zones" "available" {
  state = "available"
}

# Main VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.default_tags["Project"]}-${var.default_tags["Environment"]}-vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.default_tags["Project"]}-${var.default_tags["Environment"]}-igw"
  }
}

# Public Subnets (Indices 0, 1, 2: /20 subnets)
resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 4, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                     = "${var.default_tags["Project"]}-${var.default_tags["Environment"]}-public-subnet-${count.index + 1}"
    "kubernetes.io/role/elb" = "1"
  }
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.default_tags["Project"]}-${var.default_tags["Environment"]}-public-rt"
  }
}

# Public Route Table Associations
resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "${var.default_tags["Project"]}-${var.default_tags["Environment"]}-nat-eip"
  }
}

# NAT Gateway deployed in the first public subnet
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${var.default_tags["Project"]}-${var.default_tags["Environment"]}-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

# Private Subnets (Indices 3, 4, 5: consecutive /20 subnets)
resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 4, count.index + 3)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                              = "${var.default_tags["Project"]}-${var.default_tags["Environment"]}-private-subnet-${count.index + 1}"
    "kubernetes.io/role/internal-elb" = "1"
  }
}

# Private Route Table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "${var.default_tags["Project"]}-${var.default_tags["Environment"]}-private-rt"
  }
}

# Private Route Table Associations
resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Outputs
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "List of public subnet IDs"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "List of private subnet IDs"
  value       = aws_subnet.private[*].id
}

output "nat_gateway_ip" {
  description = "Public IP of the NAT Gateway"
  value       = aws_eip.nat.public_ip
}
```

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# ELB Account IDs for classic ELB access logs
data "aws_elb_service_account" "main" {
  count = var.create_bucket && var.attach_elb_log_delivery_policy ? 1 : 0
}

################################################################################
# Variables
################################################################################

variable "aws_region" {
  type        = string
  default     = "us-east-1"
  description = "AWS deployment region."
}

variable "create_bucket" {
  type        = bool
  default     = true
  description = "Whether to create the S3 bucket."
}

variable "bucket" {
  type        = string
  default     = null
  description = "The name of the bucket. If omitted, Terraform will assign a random name using bucket_prefix."
}

variable "bucket_prefix" {
  type        = string
  default     = "s3-enterprise-"
  description = "Creates a unique bucket name beginning with the specified prefix."
}

variable "force_destroy" {
  type        = bool
  default     = false
  description = "A boolean that indicates all objects should be deleted from the bucket so that the bucket can be destroyed without error."
}

variable "acl" {
  type        = string
  default     = "private"
  description = "The canned ACL to apply to the bucket."
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "A mapping of tags to assign to the bucket."
}

variable "acceleration_status" {
  type        = string
  default     = null
  description = "Sets the accelerate configuration of an existing bucket. Can be Enabled or Suspended."
}

variable "request_payer" {
  type        = string
  default     = null
  description = "Specifies who should bear the cost of Amazon S3 data transfer. Can be BucketOwner or Requester."
}

variable "control_object_ownership" {
  type        = bool
  default     = true
  description = "Whether to manage S3 Bucket Ownership Controls."
}

variable "object_ownership" {
  type        = string
  default     = "ObjectWriter"
  description = "Object ownership. Valid values: BucketOwnerPreferred, ObjectWriter or BucketOwnerEnforced."
}

variable "attach_public_policy" {
  type        = bool
  default     = true
  description = "Whether to create and attach the S3 public access block."
}

variable "block_public_acls" {
  type        = bool
  default     = true
  description = "Whether Amazon S3 should block public ACLs for this bucket."
}

variable "block_public_policy" {
  type        = bool
  default     = true
  description = "Whether Amazon S3 should block public bucket policies for this bucket."
}

variable "ignore_public_acls" {
  type        = bool
  default     = true
  description = "Whether Amazon S3 should ignore public ACLs for this bucket."
}

variable "restrict_public_buckets" {
  type        = bool
  default     = true
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket."
}

variable "versioning" {
  type        = map(string)
  default     = { status = "Enabled" }
  description = "Map containing versioning configuration."
}

variable "logging" {
  type        = map(string)
  default     = {}
  description = "Map containing access bucket logging configuration (target_bucket, target_prefix)."
}

variable "website" {
  type        = map(string)
  default     = {}
  description = "Map containing static website hosting configuration."
}

variable "cors_rule" {
  type        = any
  default     = []
  description = "List of maps containing CORS rules."
}

variable "lifecycle_rule" {
  type        = any
  default     = []
  description = "List of maps containing lifecycle management rules."
}

variable "replication_configuration" {
  type        = any
  default     = {}
  description = "Map containing cross-region replication configuration."
}

variable "server_side_encryption_configuration" {
  type        = any
  default     = {}
  description = "Map containing server-side encryption configuration."
}

variable "object_lock_configuration" {
  type        = any
  default     = {}
  description = "Map containing object lock configuration."
}

variable "attach_policy" {
  type        = bool
  default     = false
  description = "Controls if custom S3 bucket policy should be attached."
}

variable "policy" {
  type        = string
  default     = null
  description = "Valid bucket policy JSON document."
}

variable "attach_deny_insecure_transport_policy" {
  type        = bool
  default     = true
  description = "Controls if S3 bucket should deny non-SSL transport."
}

variable "attach_elb_log_delivery_policy" {
  type        = bool
  default     = false
  description = "Controls if S3 bucket should permit Classic ELB log delivery."
}

variable "attach_lb_log_delivery_policy" {
  type        = bool
  default     = false
  description = "Controls if S3 bucket should permit ALB/NLB log delivery."
}

################################################################################
# Customer Managed KMS Key (Created when SSE configuration is omitted)
################################################################################

locals {
  create_kms_key = var.create_bucket && length(keys(var.server_side_encryption_configuration)) == 0
}

data "aws_iam_policy_document" "kms_key_policy" {
  count = local.create_kms_key ? 1 : 0

  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

resource "aws_kms_key" "this" {
  count                   = local.create_kms_key ? 1 : 0
  description             = "KMS Key for S3 bucket default encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy[0].json
  tags                    = var.tags
}

resource "aws_kms_alias" "this" {
  count         = local.create_kms_key ? 1 : 0
  name_prefix   = "alias/s3-key-"
  target_key_id = aws_kms_key.this[0].key_id
}

################################################################################
# S3 Bucket
################################################################################

resource "aws_s3_bucket" "this" {
  count         = var.create_bucket ? 1 : 0
  bucket        = var.bucket
  bucket_prefix = var.bucket != null ? null : var.bucket_prefix
  force_destroy = var.force_destroy

  object_lock_enabled = lookup(var.object_lock_configuration, "object_lock_enabled", null) == "Enabled" ? true : false

  tags = var.tags
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count  = var.create_bucket && var.control_object_ownership ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_acl" "this" {
  count      = var.create_bucket && var.acl != null && var.object_ownership != "BucketOwnerEnforced" ? 1 : 0
  bucket     = aws_s3_bucket.this[0].id
  acl        = var.acl
  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = var.create_bucket && var.acceleration_status != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  status = var.acceleration_status
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count  = var.create_bucket && var.request_payer != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  payer  = var.request_payer
}

resource "aws_s3_bucket_versioning" "this" {
  count  = var.create_bucket && length(keys(var.versioning)) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status     = lookup(var.versioning, "status", "Enabled")
    mfa_delete = lookup(var.versioning, "mfa_delete", null)
  }
}

resource "aws_s3_bucket_logging" "this" {
  count  = var.create_bucket && length(keys(var.logging)) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  target_bucket = var.logging["target_bucket"]
  target_prefix = lookup(var.logging, "target_prefix", null)
}

resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.create_bucket && length(keys(var.website)) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "index_document" {
    for_each = lookup(var.website, "index_document", null) != null ? [var.website["index_document"]] : []
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = lookup(var.website, "error_document", null) != null ? [var.website["error_document"]] : []
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = lookup(var.website, "redirect_all_requests_to", null) != null ? [var.website["redirect_all_requests_to"]] : []
    content {
      host_name = redirect_all_requests_to.value
      protocol  = lookup(var.website, "routing_rules_protocol", null)
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = var.create_bucket && length(var.cors_rule) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rule
    content {
      id              = lookup(cors_rule.value, "id", null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = lookup(cors_rule.value, "allowed_headers", null)
      expose_headers  = lookup(cors_rule.value, "expose_headers", null)
      max_age_seconds = lookup(cors_rule.value, "max_age_seconds", null)
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = var.create_bucket && length(var.lifecycle_rule) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rule
    content {
      id     = lookup(rule.value, "id", null)
      status = rule.value.status

      dynamic "expiration" {
        for_each = lookup(rule.value, "expiration", null) != null ? [rule.value.expiration] : []
        content {
          date                         = lookup(expiration.value, "date", null)
          days                         = lookup(expiration.value, "days", null)
          expired_object_delete_marker = lookup(expiration.value, "expired_object_delete_marker", null)
        }
      }

      dynamic "transition" {
        for_each = lookup(rule.value, "transition", [])
        content {
          date          = lookup(transition.value, "date", null)
          days          = lookup(transition.value, "days", null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = lookup(rule.value, "noncurrent_version_expiration", null) != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = lookup(noncurrent_version_expiration.value, "noncurrent_days", null)
        }
      }

      dynamic "filter" {
        for_each = lookup(rule.value, "prefix", null) != null ? [1] : []
        content {
          prefix = lookup(rule.value, "prefix", null)
        }
      }
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = var.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = length(keys(var.server_side_encryption_configuration)) > 0 ? lookup(var.server_side_encryption_configuration, "sse_algorithm", "aws:kms") : "aws:kms"
      kms_master_key_id = length(keys(var.server_side_encryption_configuration)) > 0 ? lookup(var.server_side_encryption_configuration, "kms_master_key_id", null) : aws_kms_key.this[0].arn
    }
    bucket_key_enabled = length(keys(var.server_side_encryption_configuration)) > 0 ? lookup(var.server_side_encryption_configuration, "bucket_key_enabled", true) : true
  }
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.create_bucket && length(keys(var.object_lock_configuration)) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = lookup(var.object_lock_configuration, "rule", null) != null ? [var.object_lock_configuration.rule] : []
    content {
      default_retention {
        mode  = rule.value.default_retention.mode
        days  = lookup(rule.value.default_retention, "days", null)
        years = lookup(rule.value.default_retention, "years", null)
      }
    }
  }
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = var.create_bucket && length(keys(var.replication_configuration)) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  role   = var.replication_configuration["role"]

  dynamic "rule" {
    for_each = var.replication_configuration["rules"]
    content {
      id     = lookup(rule.value, "id", null)
      status = rule.value.status

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = lookup(rule.value.destination, "storage_class", null)
      }
    }
  }
  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket_public_access_block" "this" {
  count  = var.create_bucket && var.attach_public_policy ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

################################################################################
# Policy Construction & Attachment
################################################################################

locals {
  attach_any_policy = var.create_bucket && (
    var.attach_deny_insecure_transport_policy ||
    var.attach_elb_log_delivery_policy ||
    var.attach_lb_log_delivery_policy ||
    var.attach_policy
  )
}

data "aws_iam_policy_document" "combined" {
  count = local.attach_any_policy ? 1 : 0

  source_policy_documents = var.attach_policy && var.policy != null ? [var.policy] : []

  dynamic "statement" {
    for_each = var.attach_deny_insecure_transport_policy ? [1] : []
    content {
      sid     = "DenyInsecureTransport"
      effect  = "Deny"
      actions = ["s3:*"]
      resources = [
        aws_s3_bucket.this[0].arn,
        "${aws_s3_bucket.this[0].arn}/*"
      ]
      principals {
        type        = "*"
        identifiers = ["*"]
      }
      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_elb_log_delivery_policy ? [1] : []
    content {
      sid     = "ELBLogDeliveryWrite"
      effect  = "Allow"
      actions = ["s3:PutObject"]
      resources = [
        "${aws_s3_bucket.this[0].arn}/*"
      ]
      principals {
        type        = "AWS"
        identifiers = [data.aws_elb_service_account.main[0].arn]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      sid     = "LBLogDeliveryWrite"
      effect  = "Allow"
      actions = ["s3:PutObject"]
      resources = [
        "${aws_s3_bucket.this[0].arn}/*"
      ]
      principals {
        type        = "Service"
        identifiers = ["logdelivery.elasticloadbalancing.amazonaws.com"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      sid     = "LBLogDeliveryAclCheck"
      effect  = "Allow"
      actions = ["s3:GetBucketAcl"]
      resources = [
        aws_s3_bucket.this[0].arn
      ]
      principals {
        type        = "Service"
        identifiers = ["logdelivery.elasticloadbalancing.amazonaws.com"]
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count      = local.attach_any_policy ? 1 : 0
  bucket     = aws_s3_bucket.this[0].id
  policy     = data.aws_iam_policy_document.combined[0].json
  depends_on = [aws_s3_bucket_public_access_block.this]
}

################################################################################
# Outputs
################################################################################

output "s3_bucket_id" {
  value       = try(aws_s3_bucket.this[0].id, "")
  description = "The name of the bucket."
}

output "s3_bucket_arn" {
  value       = try(aws_s3_bucket.this[0].arn, "")
  description = "The ARN of the bucket."
}

output "kms_key_arn" {
  value       = try(aws_kms_key.this[0].arn, null)
  description = "The ARN of the KMS key created by the module if SSE was not supplied."
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "awsRegion" {
  description = "AWS region to deploy the network stack into."
  type        = string
  default     = "us-east-1"
}

variable "projectPrefix" {
  description = "Project prefix for resource naming and tagging."
  type        = string
  default     = "f5-dcec"
}

variable "resourceOwner" {
  description = "Owner tag applied to all resources."
  type        = string
  default     = "f5-user"
}

variable "buildSuffix" {
  description = "Suffix string appended to resource names."
  type        = string
  default     = "YY"
}

variable "map_public_ip_on_launch" {
  description = "Controls whether public subnets assign public IPs on launch."
  type        = bool
  default     = false
}

variable "awsAz1" {
  description = "Primary availability zone (defaults to first available AZ in the region)."
  type        = string
  default     = null
}

variable "awsAz2" {
  description = "Secondary availability zone (falls back to awsAz1 or the second available AZ)."
  type        = string
  default     = null
}

variable "vpcMainCidr" {
  description = "CIDR block for the main VPC."
  type        = string
  default     = "10.1.0.0/16"
}

variable "vpcMainSubPubACidr" {
  description = "CIDR block for Public Subnet A."
  type        = string
  default     = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  description = "CIDR block for Public Subnet B."
  type        = string
  default     = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  description = "CIDR block for Management Subnet A."
  type        = string
  default     = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  description = "CIDR block for Management Subnet B."
  type        = string
  default     = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  description = "CIDR block for Private Subnet A."
  type        = string
  default     = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  description = "CIDR block for Private Subnet B."
  type        = string
  default     = "10.1.120.0/24"
}

provider "aws" {
  region = var.awsRegion
}

# Fetch available AZs in the current region
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az1 = var.awsAz1 != null ? var.awsAz1 : data.aws_availability_zones.available.names[0]
  az2 = var.awsAz2 != null ? var.awsAz2 : (var.awsAz1 != null ? var.awsAz1 : data.aws_availability_zones.available.names[1])

  common_tags = {
    Owner   = var.resourceOwner
    Project = var.projectPrefix
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-vpc-${var.buildSuffix}"
  })
}

# Internet Gateway
resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-igw-${var.buildSuffix}"
  })
}

# Custom Route Table with default route to Internet Gateway
resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-rt-${var.buildSuffix}"
  })
}

# Set the custom route table as the Main Route Table for the VPC
resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.main.id
}

# Public Subnets
resource "aws_subnet" "pub_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-pub-a-${var.buildSuffix}"
    Type = "public"
  })
}

resource "aws_subnet" "pub_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-pub-b-${var.buildSuffix}"
    Type = "public"
  })
}

# Management Subnets
resource "aws_subnet" "mgmt_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-mgmt-a-${var.buildSuffix}"
    Type = "management"
  })
}

resource "aws_subnet" "mgmt_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-mgmt-b-${var.buildSuffix}"
    Type = "management"
  })
}

# Private Subnets
resource "aws_subnet" "priv_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-priv-a-${var.buildSuffix}"
    Type = "private"
  })
}

resource "aws_subnet" "priv_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-priv-b-${var.buildSuffix}"
    Type = "private"
  })
}

# Outputs
output "vpc_id" {
  description = "The ID of the VPC."
  value       = aws_vpc.main.id
}

output "resolved_az1" {
  description = "Resolved Availability Zone 1."
  value       = local.az1
}

output "resolved_az2" {
  description = "Resolved Availability Zone 2."
  value       = local.az2
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = [aws_subnet.pub_a.id, aws_subnet.pub_b.id]
}

output "mgmt_subnet_ids" {
  description = "IDs of the management subnets."
  value       = [aws_subnet.mgmt_a.id, aws_subnet.mgmt_b.id]
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = [aws_subnet.priv_a.id, aws_subnet.priv_b.id]
}

output "route_table_id" {
  description = "The ID of the custom main route table."
  value       = aws_route_table.main.id
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region for resources"
  default     = "us-east-1"
}

variable "resource_name" {
  type        = string
  description = "Default resource name prefix for resources"
  default     = "benchmark"
}

variable "rule_count" {
  type        = number
  description = "Number of path-based routing rules to create"
  default     = 1
}

provider "aws" {
  region = var.aws_region
}

# Fetch available Availability Zones in the region
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC Definition
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = var.resource_name
  }
}

# Two subnets across the first two AZs
resource "aws_subnet" "subnets" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.resource_name}-subnet-${count.index}"
  }
}

# Security group allowing all ingress and egress within the VPC CIDR
resource "aws_security_group" "alb" {
  name        = "${var.resource_name}-sg"
  description = "Security group for internal ALB allowing traffic within VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow all ingress from VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all egress to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.resource_name}-sg"
  }
}

# Self-signed TLS Certificate for HTTPS listener
resource "tls_private_key" "cert_key" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "cert" {
  private_key_pem = tls_private_key.cert_key.private_key_pem

  subject {
    common_name  = "${var.resource_name}.internal"
    organization = "Internal Test"
  }

  validity_period_hours = 8760 # 1 year

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "cert" {
  private_key      = tls_private_key.cert_key.private_key_pem
  certificate_body = tls_self_signed_cert.cert.cert_pem

  tags = {
    Name = "${var.resource_name}-cert"
  }
}

# Target Group
resource "aws_lb_target_group" "main" {
  name        = "${var.resource_name}-tg"
  port        = 8080
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "instance"

  health_check {
    enabled             = true
    path                = "/health"
    port                = "8081"
    protocol            = "HTTP"
    interval            = 60
    timeout             = 3
    matcher             = "200-299"
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = {
    Name = "${var.resource_name}-tg"
  }
}

# Internal Application Load Balancer
resource "aws_lb" "main" {
  name                       = "${var.resource_name}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.subnets[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = var.resource_name
  }
}

# HTTPS Listener
resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.cert.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = {
    Name = "${var.resource_name}-https-listener"
  }
}

# Path-based routing rules
resource "aws_lb_listener_rule" "static_paths" {
  count        = var.rule_count
  listener_arn = aws_lb_listener.https.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }

  tags = {
    Name = "${var.resource_name}-rule-${count.index}"
  }
}

output "alb_dns_name" {
  description = "DNS name of the internal Application Load Balancer"
  value       = aws_lb.main.dns_name
}

output "alb_arn" {
  description = "ARN of the internal Application Load Balancer"
  value       = aws_lb.main.arn
}

output "target_group_arn" {
  description = "ARN of the HTTP target group"
  value       = aws_lb_target_group.main.arn
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# --- Variables ---

variable "aws_region" {
  type        = string
  description = "AWS region for resources"
  default     = "us-east-1"
}

variable "trail_name" {
  type        = string
  description = "The name of the CloudTrail instance"
  default     = "management_trail"
}

variable "is_organization_trail" {
  type        = bool
  description = "Specifies whether the trail is an AWS Organizations trail"
  default     = false
}

variable "cloudwatch_log_group_name" {
  type        = string
  description = "The name of the CloudWatch Log Group for CloudTrail"
  default     = "cloudtrail_logs"
}

variable "enable_kms_encryption" {
  type        = bool
  description = "Whether to enable KMS encryption for CloudTrail logs and S3 bucket"
  default     = true
}

variable "kms_key_alias" {
  type        = string
  description = "The alias for the customer-managed KMS key"
  default     = "alias/cloudtrail_key"
}

# --- Data Sources ---

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# --- Random Suffix for S3 Bucket ---

resource "random_string" "bucket_suffix" {
  length  = 12
  numeric = true
  special = false
  upper   = false
  lower   = false
}

# --- KMS Key Configuration ---

data "aws_iam_policy_document" "kms_policy" {
  count = var.enable_kms_encryption ? 1 : 0

  # Admin policy for the account root and caller
  statement {
    sid    = "EnableRootAndCallerAdmin"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = [
        "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root",
        data.aws_caller_identity.current.arn
      ]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  # Allow CloudTrail to describe key and generate data keys
  statement {
    sid    = "AllowCloudTrailToEncrypt"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = [
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }

  # Allow S3 service to use the key
  statement {
    sid    = "AllowS3ToUseKey"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }

  # Allow account-wide decryption rights for reading logs
  statement {
    sid    = "AllowAccountDecrypt"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "cloudtrail_key" {
  count                   = var.enable_kms_encryption ? 1 : 0
  description             = "Customer managed KMS Key for CloudTrail logs and S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_policy[0].json
}

resource "aws_kms_alias" "cloudtrail_key_alias" {
  count         = var.enable_kms_encryption ? 1 : 0
  name          = var.kms_key_alias
  target_key_id = aws_kms_key.cloudtrail_key[0].key_id
}

# --- S3 Bucket for CloudTrail ---

locals {
  bucket_name = "cloudtrail-bucket-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket" "cloudtrail_bucket" {
  bucket        = local.bucket_name
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_bucket_block" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_bucket_encryption" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.enable_kms_encryption ? "aws:kms" : "AES256"
      kms_master_key_id = var.enable_kms_encryption ? aws_kms_key.cloudtrail_key[0].arn : null
    }
  }
}

data "aws_iam_policy_document" "s3_bucket_policy" {
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail_bucket.arn]
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail_bucket.arn}/*"]
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_bucket_policy" {
  bucket     = aws_s3_bucket.cloudtrail_bucket.id
  policy     = data.aws_iam_policy_document.s3_bucket_policy.json
  depends_on = [aws_s3_bucket_public_access_block.cloudtrail_bucket_block]
}

# --- CloudWatch Logs Integration ---

resource "aws_cloudwatch_log_group" "cloudtrail_log_group" {
  name              = var.cloudwatch_log_group_name
  retention_in_days = 0
}

data "aws_iam_policy_document" "cloudtrail_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "cloudtrail_cloudwatch_role" {
  name               = "CloudTrailRoleForCloudWatchLogs"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_assume_role.json
}

data "aws_iam_policy_document" "cloudtrail_cloudwatch_policy" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      "${aws_cloudwatch_log_group.cloudtrail_log_group.arn}:*"
    ]
  }
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch_policy_attachment" {
  name   = "allow-access-to-cw-logs"
  role   = aws_iam_role.cloudtrail_cloudwatch_role.id
  policy = data.aws_iam_policy_document.cloudtrail_cloudwatch_policy.json
}

# --- AWS CloudTrail ---

resource "aws_cloudtrail" "main" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail_bucket.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  is_organization_trail         = var.is_organization_trail
  kms_key_id                    = var.enable_kms_encryption ? aws_kms_key.cloudtrail_key[0].arn : null

  cloud_watch_logs_group_arn = "${aws_cloudwatch_log_group.cloudtrail_log_group.arn}:*"
  cloud_watch_logs_role_arn  = aws_iam_role.cloudtrail_cloudwatch_role.arn

  event_selector {
    read_write_type           = "All"
    include_management_events = true
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail_bucket_policy,
    aws_iam_role_policy.cloudtrail_cloudwatch_policy_attachment
  ]
}

# --- Outputs ---

output "cloudtrail_arn" {
  description = "The ARN of the CloudTrail"
  value       = aws_cloudtrail.main.arn
}

output "cloudtrail_s3_bucket_name" {
  description = "The name of the S3 bucket used for CloudTrail"
  value       = aws_s3_bucket.cloudtrail_bucket.id
}

output "cloudtrail_log_group_arn" {
  description = "The ARN of the CloudWatch Log Group"
  value       = aws_cloudwatch_log_group.cloudtrail_log_group.arn
}

output "kms_key_arn" {
  description = "The ARN of the KMS Key used for CloudTrail"
  value       = var.enable_kms_encryption ? aws_kms_key.cloudtrail_key[0].arn : null
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# --- Variables ---

variable "aws_region" {
  type        = string
  description = "AWS region to deploy the resources."
  default     = "us-east-1"
}

variable "namespace" {
  type        = string
  description = "Optional namespace/path prefix for the repository name."
  default     = ""
}

variable "name" {
  type        = string
  description = "Base repository name. If null or empty, a generated frigga-compliant name starting with 'ecr' is used."
  default     = ""
}

variable "image_tag_mutability" {
  type        = string
  description = "Tag mutability setting for the repository ('MUTABLE' or 'IMMUTABLE')."
  default     = "IMMUTABLE"
  validation {
    condition     = contains(["MUTABLE", "IMMUTABLE"], var.image_tag_mutability)
    error_message = "Valid values for image_tag_mutability are 'MUTABLE' or 'IMMUTABLE'."
  }
}

variable "scan_on_push" {
  type        = bool
  description = "Indicates whether images are scanned after being pushed to the repository."
  default     = true
}

variable "lifecycle_policy" {
  type        = string
  description = "A JSON string defining the ECR lifecycle policy. If null, no lifecycle policy is applied."
  default     = null
}

variable "trusted_accounts" {
  type        = list(string)
  description = "List of AWS Account IDs granted cross-account pull access to this repository."
  default     = []
}

variable "tags" {
  type        = map(string)
  description = "Additional tags to apply to the repository."
  default     = {}
}

# --- Data Sources & Random Helpers ---

data "aws_caller_identity" "current" {}

resource "random_pet" "name_suffix" {
  length    = 2
  separator = "-"
}

locals {
  # Base name logic: use var.name if non-empty, otherwise 'ecr-<petname>'
  base_name = length(trimspace(var.name)) > 0 ? trimspace(var.name) : "ecr-${random_pet.name_suffix.id}"
  # Repository full path logic: prefix with namespace if present
  repo_name = length(trimspace(var.namespace)) > 0 ? "${trim(var.namespace, "/")}/${local.base_name}" : local.base_name

  # Normalizing local_name for IAM resource identifiers (replacing slashes with dashes)
  local_name = replace(local.repo_name, "/", "-")

  # Principals for the cross-account repository policy (current account + trusted accounts)
  all_principals = distinct(concat(
    ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"],
    [for acct in var.trusted_accounts : "arn:aws:iam::${acct}:root"]
  ))
}

# --- ECR Repository ---

resource "aws_ecr_repository" "this" {
  name                 = local.repo_name
  image_tag_mutability = var.image_tag_mutability

  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }

  tags = merge(
    var.tags,
    {
      "terraform.io" = "managed"
      "Name"         = local.repo_name
    }
  )
}

# --- Optional Lifecycle Policy ---

resource "aws_ecr_lifecycle_policy" "this" {
  count      = var.lifecycle_policy != null ? 1 : 0
  repository = aws_ecr_repository.this.name
  policy     = var.lifecycle_policy
}

# --- ECR Cross-Account Repository Policy ---

data "aws_iam_policy_document" "repository_policy" {
  statement {
    sid    = "AllowCrossAccountAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = local.all_principals
    }

    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:GetDownloadUrlForLayer"
    ]
  }
}

resource "aws_ecr_repository_policy" "this" {
  repository = aws_ecr_repository.this.name
  policy     = data.aws_iam_policy_document.repository_policy.json
}

# --- IAM Policies for Read and Write ---

# IAM Read Policy Document
data "aws_iam_policy_document" "read" {
  statement {
    sid    = "AllowECRRead"
    effect = "Allow"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetAuthorizationToken",
      "ecr:GetDownloadUrlForLayer",
      "ecr:ListImages"
    ]
    # ecr:GetAuthorizationToken requires '*' resource in IAM, but standard repository permissions apply to the ARN
    resources = [
      aws_ecr_repository.this.arn,
      "*"
    ]
  }
}

resource "aws_iam_policy" "read" {
  name        = "${local.local_name}-ecr-read"
  description = "Managed read-only policy for ECR repository ${local.repo_name}"
  policy      = data.aws_iam_policy_document.read.json

  tags = merge(
    var.tags,
    {
      "terraform.io" = "managed"
    }
  )
}

# IAM Write Policy Document
data "aws_iam_policy_document" "write" {
  statement {
    sid    = "AllowECRWrite"
    effect = "Allow"
    actions = [
      "ecr:PutImage",
      "ecr:UploadLayerPart",
      "ecr:InitiateLayerUpload",
      "ecr:CompleteLayerUpload"
    ]
    resources = [aws_ecr_repository.this.arn]
  }
}

resource "aws_iam_policy" "write" {
  name        = "${local.local_name}-ecr-write"
  description = "Managed write policy for ECR repository ${local.repo_name}"
  policy      = data.aws_iam_policy_document.write.json

  tags = merge(
    var.tags,
    {
      "terraform.io" = "managed"
    }
  )
}

# --- Outputs ---

output "repository_arn" {
  description = "The ARN of the ECR repository."
  value       = aws_ecr_repository.this.arn
}

output "repository_name" {
  description = "The formatted name of the ECR repository."
  value       = aws_ecr_repository.this.name
}

output "repository_url" {
  description = "The registry URL of the ECR repository."
  value       = aws_ecr_repository.this.repository_url
}

output "read_policy_arn" {
  description = "The ARN of the IAM policy providing read access to the repository."
  value       = aws_iam_policy.read.arn
}

output "write_policy_arn" {
  description = "The ARN of the IAM policy providing write access to the repository."
  value       = aws_iam_policy.write.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "AWS region for resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "Base CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "az_count" {
  type        = number
  description = "Number of Availability Zones to utilize"
  default     = 2
}

variable "enable_public_subnets" {
  type        = bool
  description = "Toggle to enable public subnet tier"
  default     = true
}

variable "enable_nat_subnets" {
  type        = bool
  description = "Toggle to enable NAT subnet tier"
  default     = true
}

variable "enable_private_subnets" {
  type        = bool
  description = "Toggle to enable private subnet tier"
  default     = true
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES & LOCALS
# ---------------------------------------------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  # Selected availability zones limited by var.az_count
  azs = slice(data.aws_availability_zones.available.names, 0, var.az_count)

  # Number of enabled subnet tiers
  tier_count = (var.enable_public_subnets ? 1 : 0) + (var.enable_nat_subnets ? 1 : 0) + (var.enable_private_subnets ? 1 : 0)

  # Total subnets to be provisioned
  total_subnets = local.tier_count * var.az_count

  # Log-based bit calculation for splitting the VPC CIDR
  # ceil(log(total_subnets, 2)) gives required extra bits, minimum 1 bit if tiers exist
  newbits = local.total_subnets > 0 ? ceil(log(max(local.total_subnets, 2), 2)) : 0

  # Tier index offsets (each tier consumes `var.az_count` number of blocks)
  public_offset  = 0
  nat_offset     = var.enable_public_subnets ? var.az_count : 0
  private_offset = (var.enable_public_subnets ? var.az_count : 0) + (var.enable_nat_subnets ? var.az_count : 0)
}

# ---------------------------------------------------------------------------------------------------------------------
# VPC & GATEWAYS
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "dynamic-app-vpc"
  }
}

resource "aws_internet_gateway" "gw" {
  count  = var.enable_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "dynamic-app-igw"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# PUBLIC SUBNETS & ROUTING
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_subnet" "public" {
  count                   = var.enable_public_subnets ? var.az_count : 0
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, local.newbits, local.public_offset + count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index + 1}-${local.azs[count.index]}"
    Tier = "public"
  }
}

resource "aws_route_table" "public" {
  count  = var.enable_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw[0].id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count          = var.enable_public_subnets ? var.az_count : 0
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_security_group" "public_sg" {
  count       = var.enable_public_subnets ? 1 : 0
  name        = "public-tier-sg"
  description = "Security group for public subnets allowing all egress traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "public-tier-sg"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# NAT SUBNETS
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_subnet" "nat" {
  count                   = var.enable_nat_subnets ? var.az_count : 0
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, local.newbits, local.nat_offset + count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "nat-subnet-${count.index + 1}-${local.azs[count.index]}"
    Tier = "nat"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# PRIVATE SUBNETS
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_subnet" "private" {
  count                   = var.enable_private_subnets ? var.az_count : 0
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, local.newbits, local.private_offset + count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "private-subnet-${count.index + 1}-${local.azs[count.index]}"
    Tier = "private"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "List of public subnet IDs"
  value       = aws_subnet.public[*].id
}

output "nat_subnet_ids" {
  description = "List of NAT subnet IDs"
  value       = aws_subnet.nat[*].id
}

output "private_subnet_ids" {
  description = "List of private subnet IDs"
  value       = aws_subnet.private[*].id
}

output "public_security_group_id" {
  description = "The ID of the public tier security group"
  value       = try(aws_security_group.public_sg[0].id, null)
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  description = "The AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "project" {
  description = "Project name tag and prefix."
  type        = string
  default     = "demo"
}

variable "environment" {
  description = "Environment identifier (e.g. poc, dev, prod)."
  type        = string
  default     = "poc"
}

variable "vpc_name" {
  description = "Name of the VPC."
  type        = string
  default     = "demo-dataflow"
}

variable "vpc_cidr" {
  description = "CIDR block for the primary VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets."
  type        = list(string)
  default     = ["10.0.0.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.3.0/24"]
}

variable "key_name" {
  description = "Name of the EC2 key pair for bastion access."
  type        = string
  default     = "kplinuxdemo"
}

variable "bastion_instance_type" {
  description = "EC2 instance type for the SSH bastion host."
  type        = string
  default     = "t3.nano"
}

variable "bastion_ebs_optimized" {
  description = "Enable or disable EBS optimization on the bastion host."
  type        = bool
  default     = false
}

variable "custom_tags" {
  description = "Custom resource tagging map to append to all resources."
  type        = map(string)
  default = {
    ManagedBy = "Terraform"
    Workload  = "DataProcessing"
  }
}

# -----------------------------------------------------------------------------
# Provider Configuration
# -----------------------------------------------------------------------------
provider "aws" {
  region = variable.aws_region
  default_tags {
    tags = merge(
      {
        Project     = variable.project
        Environment = variable.environment
      },
      variable.custom_tags
    )
  }
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# -----------------------------------------------------------------------------
# VPC and Networking Resources
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = variable.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = variable.vpc_name
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "demogwInternet"
  }
}

# Public Subnets (auto-assign public IP disabled on launch)
resource "aws_subnet" "public" {
  count                   = length(variable.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = variable.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index % length(data.aws_availability_zones.available.names)]
  map_public_ip_on_launch = false

  tags = {
    Name = "${variable.vpc_name}-public-subnet-${count.index + 1}"
    Type = "Public"
  }
}

# Private Subnets
resource "aws_subnet" "private" {
  count                   = length(variable.private_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = variable.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index % length(data.aws_availability_zones.available.names)]
  map_public_ip_on_launch = false

  tags = {
    Name = "${variable.vpc_name}-private-subnet-${count.index + 1}"
    Type = "Private"
  }
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "demoPublicRouteTable"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private Route Table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${variable.vpc_name}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Bastion Host and Security Group
# -----------------------------------------------------------------------------
resource "aws_security_group" "bastion_sg" {
  name        = "${variable.project}-${variable.environment}-bastion-sg"
  description = "Security group for SSH bastion host"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from anywhere"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${variable.project}-${variable.environment}-bastion-sg"
  }
}

# Dedicated Elastic IP for Bastion Access
resource "aws_eip" "bastion" {
  domain = "vpc"

  tags = {
    Name = "${variable.project}-${variable.environment}-bastion-eip"
  }
}

resource "aws_instance" "bastion" {
  ami                    = data.aws_ami.amazon_linux_2023.id
  instance_type          = variable.bastion_instance_type
  key_name               = variable.key_name
  subnet_id              = aws_subnet.public[0].id
  vpc_security_group_ids = [aws_security_group.bastion_sg.id]
  ebs_optimized          = variable.bastion_ebs_optimized

  root_block_device {
    volume_type           = "gp3"
    volume_size           = 20
    delete_on_termination = true
    encrypted             = true
  }

  tags = {
    Name = "${variable.project}-${variable.environment}-bastion"
  }
}

resource "aws_eip_association" "bastion" {
  instance_id   = aws_instance.bastion.id
  allocation_id = aws_eip.bastion.id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the VPC."
  value       = aws_vpc.main.id
}

output "internet_gateway_id" {
  description = "The ID of the Internet Gateway."
  value       = aws_internet_gateway.igw.id
}

output "public_subnet_ids" {
  description = "The IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "The IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "public_route_table_id" {
  description = "The ID of the public route table."
  value       = aws_route_table.public.id
}

output "bastion_public_ip" {
  description = "Public IP address of the SSH bastion host."
  value       = aws_eip.bastion.public_ip
}
