terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "primary_region" {
  type        = string
  description = "Primary AWS region where RDS instances and primary backup vault reside."
  default     = "us-east-1"
}

variable "secondary_region" {
  type        = string
  description = "Secondary AWS region for cross-region backup copies."
  default     = "us-west-2"
}

variable "destination_account_id" {
  type        = string
  description = "Target AWS Account ID for cross-account backup copies."
  default     = "433568766270"
}

variable "enable_cross_account_copy" {
  type        = bool
  description = "Flag to enable cross-account copy action."
  default     = true
}

variable "enable_daily_backup" {
  type        = bool
  description = "Flag to enable the daily backup rule."
  default     = true
}

variable "excluded_rds_arns" {
  type        = list(string)
  description = "List of RDS instance or cluster ARNs to exclude from backups."
  default     = []
}

provider "aws" {
  region = variable.primary_region
}

provider "aws" {
  alias  = "secondary"
  region = variable.secondary_region
}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# KMS Keys for Backup Vaults
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_primary_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowBackupServiceUse"
    effect = "Allow"
    actions = [
      "kms:DescribeKey",
      "kms:CreateGrant",
      "kms:GenerateDataKey",
      "kms:Decrypt",
      "kms:Encrypt"
    ]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "primary_backup_key" {
  description             = "KMS Key for primary AWS Backup vault"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_primary_policy.json

  tags = {
    Name = "primary-rds-backup-kms-key"
  }
}

resource "aws_kms_key" "secondary_backup_key" {
  provider                = aws.secondary
  description             = "KMS Key for secondary AWS Backup vault (DR)"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_primary_policy.json

  tags = {
    Name = "secondary-rds-backup-kms-key"
  }
}

# -----------------------------------------------------------------------------
# Backup Vaults
# -----------------------------------------------------------------------------
resource "aws_backup_vault" "primary_vault" {
  name        = "rds_primary_backup_vault"
  kms_key_arn = aws_kms_key.primary_backup_key.arn

  tags = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

resource "aws_backup_vault" "secondary_vault" {
  provider    = aws.secondary
  name        = "rds_secondary_dr_backup_vault"
  kms_key_arn = aws_kms_key.secondary_backup_key.arn

  tags = {
    Environment = "dr"
    ManagedBy   = "Terraform"
  }
}

# -----------------------------------------------------------------------------
# IAM Role for AWS Backup
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup_role" {
  name               = "AWSBackupRDSManagedServiceRole"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json
}

resource "aws_iam_role_policy_attachment" "backup_policy_attachment" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore_policy_attachment" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

# -----------------------------------------------------------------------------
# Backup Plan
# -----------------------------------------------------------------------------
resource "aws_backup_plan" "rds_backup_plan" {
  name = "rds_comprehensive_backup_plan"

  # Daily Backup Rule (Optional)
  dynamic "rule" {
    for_each = var.enable_daily_backup ? [1] : []
    content {
      rule_name         = "daily_backup_rule"
      target_vault_name = aws_backup_vault.primary_vault.name
      schedule          = "cron(0 2 * * ? *)" # Every day at 2 AM UTC

      lifecycle {
        delete_after = 7
      }

      # Cross-Region Copy
      copy_action {
        destination_vault_arn = aws_backup_vault.secondary_vault.arn
        lifecycle {
          delete_after = 7
        }
      }

      # Optional Cross-Account Copy
      dynamic "copy_action" {
        for_each = var.enable_cross_account_copy ? [1] : []
        content {
          destination_vault_arn = "arn:aws:backup:${var.primary_region}:${var.destination_account_id}:backup-vault:default"
          lifecycle {
            delete_after = 7
          }
        }
      }
    }
  }

  # Weekly Backup Rule
  rule {
    rule_name         = "weekly_backup_rule"
    target_vault_name = aws_backup_vault.primary_vault.name
    schedule          = "cron(0 2 ? * SAT *)" # Saturdays at 2 AM UTC

    lifecycle {
      delete_after = 30
    }

    # Cross-Region Copy
    copy_action {
      destination_vault_arn = aws_backup_vault.secondary_vault.arn
      lifecycle {
        delete_after = 30
      }
    }

    # Optional Cross-Account Copy
    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = "arn:aws:backup:${var.primary_region}:${var.destination_account_id}:backup-vault:default"
        lifecycle {
          delete_after = 30
        }
      }
    }
  }

  # Monthly Backup Rule
  rule {
    rule_name         = "monthly_backup_rule"
    target_vault_name = aws_backup_vault.primary_vault.name
    schedule          = "cron(0 3 1 * ? *)" # 1st of every month at 3 AM UTC

    lifecycle {
      delete_after = 365
    }

    # Cross-Region Copy
    copy_action {
      destination_vault_arn = aws_backup_vault.secondary_vault.arn
      lifecycle {
        delete_after = 365
      }
    }

    # Optional Cross-Account Copy
    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = "arn:aws:backup:${var.primary_region}:${var.destination_account_id}:backup-vault:default"
        lifecycle {
          delete_after = 365
        }
      }
    }
  }

  # Yearly Backup Rule
  rule {
    rule_name         = "yearly_backup_rule"
    target_vault_name = aws_backup_vault.primary_vault.name
    schedule          = "cron(0 4 1 1 ? *)" # Jan 1st at 4 AM UTC

    lifecycle {
      delete_after = 2555 # 7 years
    }

    # Cross-Region Copy
    copy_action {
      destination_vault_arn = aws_backup_vault.secondary_vault.arn
      lifecycle {
        delete_after = 2555
      }
    }

    # Optional Cross-Account Copy
    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy ? [1] : []
      content {
        destination_vault_arn = "arn:aws:backup:${var.primary_region}:${var.destination_account_id}:backup-vault:default"
        lifecycle {
          delete_after = 2555
        }
      }
    }
  }

  tags = {
    PlanType = "Comprehensive-RDS-Backup"
  }
}

# -----------------------------------------------------------------------------
# Backup Resource Selection for RDS
# -----------------------------------------------------------------------------
resource "aws_backup_selection" "rds_backup_selection" {
  iam_role_arn = aws_iam_role.backup_role.arn
  name         = "rds_all_selection"
  plan_id      = aws_backup_plan.rds_backup_plan.id

  resources = [
    "arn:aws:rds:*:*:db:*",
    "arn:aws:rds:*:*:cluster:*"
  ]

  not_resources = var.excluded_rds_arns
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "primary_backup_vault_arn" {
  description = "ARN of the primary backup vault"
  value       = aws_backup_vault.primary_vault.arn
}

output "secondary_backup_vault_arn" {
  description = "ARN of the secondary backup vault"
  value       = aws_backup_vault.secondary_vault.arn
}

output "backup_plan_id" {
  description = "The ID of the AWS Backup plan"
  value       = aws_backup_plan.rds_backup_plan.id
}

output "backup_plan_version" {
  description = "Unique, templated, version-assigned ID of the backup plan"
  value       = aws_backup_plan.rds_backup_plan.version
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------

variable "aws_region" {
  description = "The AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "allow_users_to_change_password" {
  description = "Whether to allow users to change their own password"
  type        = bool
  default     = true
}

variable "hard_expiry" {
  description = "Whether users are prevented from setting a new password after their password has expired"
  type        = bool
  default     = false
}

variable "max_password_age" {
  description = "The number of days that an IAM user password is valid"
  type        = number
  default     = 90
}

variable "minimum_password_length" {
  description = "Minimum length to require for IAM user passwords"
  type        = number
  default     = 14
}

variable "password_reuse_prevention" {
  description = "The number of previous passwords that users are prevented from reusing"
  type        = number
  default     = 24
}

variable "require_lowercase_characters" {
  description = "Whether to require lowercase characters for IAM user passwords"
  type        = bool
  default     = true
}

variable "require_numbers" {
  description = "Whether to require numbers for IAM user passwords"
  type        = bool
  default     = true
}

variable "require_symbols" {
  description = "Whether to require symbols for IAM user passwords"
  type        = bool
  default     = true
}

variable "require_uppercase_characters" {
  description = "Whether to require uppercase characters for IAM user passwords"
  type        = bool
  default     = true
}

# -----------------------------------------------------------------------------
# IAM Account Password Policy
# -----------------------------------------------------------------------------

resource "aws_iam_account_password_policy" "strict" {
  allow_users_to_change_password = var.allow_users_to_change_password
  hard_expiry                    = var.hard_expiry
  max_password_age               = var.max_password_age
  minimum_password_length        = var.minimum_password_length
  password_reuse_prevention      = var.password_reuse_prevention
  require_lowercase_characters   = var.require_lowercase_characters
  require_numbers                = var.require_numbers
  require_symbols                = var.require_symbols
  require_uppercase_characters   = var.require_uppercase_characters
}

# -----------------------------------------------------------------------------
# IAM Groups
# -----------------------------------------------------------------------------

resource "aws_iam_group" "administrators" {
  name = "administrators"
  path = "/"
}

resource "aws_iam_group" "developpers" {
  name = "developpers"
  path = "/"
}

resource "aws_iam_group" "prod_users" {
  name = "prod_users"
  path = "/"
}

# -----------------------------------------------------------------------------
# IAM Policies
# -----------------------------------------------------------------------------

# Developers Policy: ec2:* and rds:* conditioned on tag:env == dev
resource "aws_iam_policy" "developpers_policy" {
  name        = "developpers_policy"
  description = "Allow full EC2 and RDS actions conditioned on env=dev"
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowEC2AndRDSForDev"
        Effect   = "Allow"
        Action   = [
          "ec2:*",
          "rds:*"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/env" = "dev"
          }
        }
      }
    ]
  })
}

# Prod Users Policy: ec2:* and rds:* conditioned on tag:env in [preprod, prod]
resource "aws_iam_policy" "prod_users_policy" {
  name        = "prod_users_policy"
  description = "Allow full EC2 and RDS actions conditioned on env=preprod or env=prod"
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowEC2AndRDSForPreprodAndProd"
        Effect   = "Allow"
        Action   = [
          "ec2:*",
          "rds:*"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/env" = [
              "preprod",
              "prod"
            ]
          }
        }
      }
    ]
  })
}

# Administrators Policy: NotAction excluding iam, organizations, and account with security != high
resource "aws_iam_policy" "administrators_policy" {
  name        = "administrators_policy"
  description = "Broad administrator permissions excluding sensitive services and high security resources, with allowed specific administrative functions"
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "BroadAccessExcludingIAMOrgsAccountAndHighSecurity"
        Effect    = "Allow"
        NotAction = [
          "iam:*",
          "organizations:*",
          "account:*"
        ]
        Resource  = "*"
        Condition = {
          StringNotEquals = {
            "aws:ResourceTag/security" = "high"
          }
        }
      },
      {
        Sid      = "ExplicitAllowedAdminServiceActions"
        Effect   = "Allow"
        Action   = [
          "iam:CreateServiceLinkedRole",
          "iam:DeleteServiceLinkedRole",
          "iam:ListRoles",
          "organizations:DescribeOrganization",
          "account:ListRegions"
        ]
        Resource = "*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# IAM Group Policy Attachments
# -----------------------------------------------------------------------------

resource "aws_iam_group_policy_attachment" "developpers_attachment" {
  group      = aws_iam_group.developpers.name
  policy_arn = aws_iam_policy.developpers_policy.arn
}

resource "aws_iam_group_policy_attachment" "prod_users_attachment" {
  group      = aws_iam_group.prod_users.name
  policy_arn = aws_iam_policy.prod_users_policy.arn
}

resource "aws_iam_group_policy_attachment" "administrators_attachment" {
  group      = aws_iam_group.administrators.name
  policy_arn = aws_iam_policy.administrators_policy.arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "administrators_group_name" {
  description = "The name of the administrators IAM group"
  value       = aws_iam_group.administrators.name
}

output "developpers_group_name" {
  description = "The name of the developpers IAM group"
  value       = aws_iam_group.developpers.name
}

output "prod_users_group_name" {
  description = "The name of the prod_users IAM group"
  value       = aws_iam_group.prod_users.name
}
```

```terraform
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

variable "prefix" {
  type        = string
  description = "Resource name prefix"
  default     = "tfm-aws"
}

variable "vpc_cidr" {
  type        = string
  description = "Main CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "instance_tenancy" {
  type        = string
  description = "Tenancy option for instances launched into the VPC"
  default     = "default"
}

variable "enable_dns_hostnames" {
  type        = bool
  description = "Enable DNS hostnames in the VPC"
  default     = true
}

variable "enable_dns_support" {
  type        = bool
  description = "Enable DNS support in the VPC"
  default     = true
}

variable "private_subnets" {
  type        = list(string)
  description = "CIDR blocks for the private subnets"
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  type = list(object({
    rule_number = number
    egress      = bool
    protocol    = string
    rule_action = string
    cidr_block  = string
    from_port   = number
    to_port     = number
  }))
  description = "Inbound network ACL rules"
  default = [
    {
      rule_number = 100
      egress      = false
      protocol    = "tcp"
      rule_action = "allow"
      cidr_block  = "0.0.0.0/0"
      from_port   = 1024
      to_port     = 65535
    }
  ]
}

variable "public_outbound_acl_rules" {
  type = list(object({
    rule_number = number
    egress      = bool
    protocol    = string
    rule_action = string
    cidr_block  = string
    from_port   = number
    to_port     = number
  }))
  description = "Outbound network ACL rules"
  default = [
    {
      rule_number = 100
      egress      = true
      protocol    = "tcp"
      rule_action = "allow"
      cidr_block  = "0.0.0.0/0"
      from_port   = 443
      to_port     = 443
    }
  ]
}

provider "aws" {
  region = variable.region
}

# Fetch available Availability Zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Isolated VPC
resource "aws_vpc" "main" {
  cidr_block           = variable.vpc_cidr
  instance_tenancy     = variable.instance_tenancy
  enable_dns_hostnames = variable.enable_dns_hostnames
  enable_dns_support   = variable.enable_dns_support

  tags = {
    Name = "${variable.prefix}-vpc"
  }
}

# Two Private Subnets across first two AZs
resource "aws_subnet" "private" {
  count             = length(variable.private_subnets)
  vpc_id            = aws_vpc.main.id
  cidr_block        = variable.private_subnets[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${variable.prefix}-private-subnet-${count.index + 1}"
  }
}

# Dedicated Route Tables for each Private Subnet
resource "aws_route_table" "private" {
  count  = length(variable.private_subnets)
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${variable.prefix}-private-rt-${count.index + 1}"
  }
}

# Subnet Route Table Associations
resource "aws_route_table_association" "private" {
  count          = length(variable.private_subnets)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# S3 VPC Gateway Endpoint
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${variable.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "${variable.prefix}-s3-gateway-endpoint"
  }
}

# Shared Network ACL for Private Subnets
resource "aws_network_acl" "private" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "${variable.prefix}-private-nacl"
  }
}

# Inbound Network ACL Rules
resource "aws_network_acl_rule" "inbound" {
  count          = length(variable.public_inbound_acl_rules)
  network_acl_id = aws_network_acl.private.id
  rule_number    = variable.public_inbound_acl_rules[count.index].rule_number
  egress         = variable.public_inbound_acl_rules[count.index].egress
  protocol       = variable.public_inbound_acl_rules[count.index].protocol
  rule_action    = variable.public_inbound_acl_rules[count.index].rule_action
  cidr_block     = variable.public_inbound_acl_rules[count.index].cidr_block
  from_port      = variable.public_inbound_acl_rules[count.index].from_port
  to_port        = variable.public_inbound_acl_rules[count.index].to_port
}

# Outbound Network ACL Rules
resource "aws_network_acl_rule" "outbound" {
  count          = length(variable.public_outbound_acl_rules)
  network_acl_id = aws_network_acl.private.id
  rule_number    = variable.public_outbound_acl_rules[count.index].rule_number
  egress         = variable.public_outbound_acl_rules[count.index].egress
  protocol       = variable.public_outbound_acl_rules[count.index].protocol
  rule_action    = variable.public_outbound_acl_rules[count.index].rule_action
  cidr_block     = variable.public_outbound_acl_rules[count.index].cidr_block
  from_port      = variable.public_outbound_acl_rules[count.index].from_port
  to_port        = variable.public_outbound_acl_rules[count.index].to_port
}

# Outputs
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "private_subnet_ids" {
  description = "The IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "s3_endpoint_id" {
  description = "The ID of the S3 Gateway VPC Endpoint"
  value       = aws_vpc_endpoint.s3.id
}

output "network_acl_id" {
  description = "The ID of the private Network ACL"
  value       = aws_network_acl.private.id
}
```

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0, < 6.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ------------------------------------------------------------------------------
# Variables: Label Context (Cloud Posse Null-Label Pattern)
# ------------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "AWS Region to deploy resources into."
  default     = "us-east-1"
}

variable "namespace" {
  type        = string
  description = "Namespace, which could be your organization name or abbreviation, e.g. 'eg' or 'cp'."
  default     = "cp"
}

variable "environment" {
  type        = string
  description = "Environment, e.g. 'prod', 'staging', 'dev', 'pre-prod', 'UAT'."
  default     = "prod"
}

variable "stage" {
  type        = string
  description = "Stage, e.g. 'app', 'release', etc."
  default     = "base"
}

variable "name" {
  type        = string
  description = "Solution name, e.g. 'app' or 'vpc'."
  default     = "network"
}

variable "attributes" {
  type        = list(string)
  description = "Additional attributes (e.g. `1`)."
  default     = []
}

variable "tags" {
  type        = map(string)
  description = "Additional tags (e.g. `map('BusinessUnit','XYZ')`)."
  default     = {}
}

# ------------------------------------------------------------------------------
# Variables: VPC Configuration
# ------------------------------------------------------------------------------

variable "ipv4_primary_cidr_block" {
  type        = string
  description = "Primary IPv4 CIDR block for the VPC. Ignored if ipv4_ipam_pool_id is set."
  default     = "11.0.0.0/16"
}

variable "ipv4_ipam_pool_id" {
  type        = string
  description = "Set to the ID of an IPv4 IPAM pool you want to allocate IPv4 CIDRs from."
  default     = null
}

variable "ipv4_netmask_length" {
  type        = number
  description = "The netmask length of the IPv4 CIDR you want to allocate from an IPAM pool."
  default     = null
}

variable "instance_tenancy" {
  type        = string
  description = "A tenancy option for instances launched into the VPC."
  default     = "default"
}

variable "enable_dns_hostnames" {
  type        = bool
  description = "A boolean flag to enable/disable DNS hostnames in the VPC."
  default     = true
}

variable "enable_dns_support" {
  type        = bool
  description = "A boolean flag to enable/disable DNS support in the VPC."
  default     = true
}

variable "assign_generated_ipv6_cidr_block" {
  type        = bool
  description = "Requests an Amazon-provided IPv6 CIDR block with a /56 prefix length for the VPC."
  default     = true
}

variable "ipv6_ipam_pool_id" {
  type        = string
  description = "Set to the ID of an IPv6 IPAM pool you want to allocate IPv6 CIDRs from."
  default     = null
}

variable "ipv6_netmask_length" {
  type        = number
  description = "The netmask length of the IPv6 CIDR you want to allocate from an IPAM pool."
  default     = null
}

# ------------------------------------------------------------------------------
# Variables: Secondary CIDR Associations
# ------------------------------------------------------------------------------

variable "additional_ipv4_cidr_blocks" {
  type = map(object({
    cidr_block          = optional(string)
    ipv4_ipam_pool_id   = optional(string)
    ipv4_netmask_length = optional(number)
  }))
  description = "Map of secondary IPv4 CIDR block configurations to associate with the VPC."
  default     = {}
}

variable "additional_ipv6_cidr_blocks" {
  type = map(object({
    ipv6_cidr_block     = optional(string)
    ipv6_ipam_pool_id   = optional(string)
    ipv6_netmask_length = optional(number)
  }))
  description = "Map of secondary IPv6 CIDR block configurations to associate with the VPC."
  default     = {}
}

# ------------------------------------------------------------------------------
# Variables: Default Resource Management & Adoption
# ------------------------------------------------------------------------------

variable "default_security_group_deny_all" {
  type        = bool
  description = "When true, manage the default security group and remove all ingress/egress rules."
  default     = true
}

variable "adopt_default_route_table" {
  type        = bool
  description = "When true, adopt and manage the VPC's default route table."
  default     = false
}

variable "adopt_default_network_acl" {
  type        = bool
  description = "When true, adopt and manage the VPC's default network ACL."
  default     = false
}

# ------------------------------------------------------------------------------
# Variables: Gateways
# ------------------------------------------------------------------------------

variable "internet_gateway_enabled" {
  type        = bool
  description = "A boolean flag to enable/disable Internet Gateway creation."
  default     = true
}

variable "ipv6_egress_only_internet_gateway_enabled" {
  type        = bool
  description = "A boolean flag to enable/disable IPv6 Egress-Only Internet Gateway creation."
  default     = false
}

# ------------------------------------------------------------------------------
# Locals: Label Context Computation
# ------------------------------------------------------------------------------

locals {
  label_elements = compact([
    var.namespace,
    var.environment,
    var.stage,
    var.name,
    join("-", var.attributes)
  ])
  id = join("-", local.label_elements)

  base_tags = {
    "Namespace"   = var.namespace
    "Environment" = var.environment
    "Stage"       = var.stage
    "Name"        = local.id
  }

  tags = merge(local.base_tags, var.tags)
}

# ------------------------------------------------------------------------------
# Resources: VPC
# ------------------------------------------------------------------------------

resource "aws_vpc" "this" {
  cidr_block                       = var.ipv4_ipam_pool_id == null ? var.ipv4_primary_cidr_block : null
  ipv4_ipam_pool_id                = var.ipv4_ipam_pool_id
  ipv4_netmask_length              = var.ipv4_netmask_length
  instance_tenancy                 = var.instance_tenancy
  enable_dns_hostnames             = var.enable_dns_hostnames
  enable_dns_support               = var.enable_dns_support
  assign_generated_ipv6_cidr_block = var.ipv6_ipam_pool_id == null ? var.assign_generated_ipv6_cidr_block : null
  ipv6_ipam_pool_id                = var.ipv6_ipam_pool_id
  ipv6_netmask_length              = var.ipv6_netmask_length

  tags = local.tags
}

# ------------------------------------------------------------------------------
# Resources: Secondary CIDR Allocations
# ------------------------------------------------------------------------------

resource "aws_vpc_ipv4_cidr_block_association" "this" {
  for_each            = var.additional_ipv4_cidr_blocks
  vpc_id              = aws_vpc.this.id
  cidr_block          = each.value.cidr_block
  ipv4_ipam_pool_id   = each.value.ipv4_ipam_pool_id
  ipv4_netmask_length = each.value.ipv4_netmask_length

  timeouts {
    create = "10m"
    delete = "10m"
  }
}

resource "aws_vpc_ipv6_cidr_block_association" "this" {
  for_each            = var.additional_ipv6_cidr_blocks
  vpc_id              = aws_vpc.this.id
  ipv6_cidr_block     = each.value.ipv6_cidr_block
  ipv6_ipam_pool_id   = each.value.ipv6_ipam_pool_id
  ipv6_netmask_length = each.value.ipv6_netmask_length

  timeouts {
    create = "10m"
    delete = "10m"
  }
}

# ------------------------------------------------------------------------------
# Resources: Default Resource Hardening & Adoption
# ------------------------------------------------------------------------------

resource "aws_default_security_group" "this" {
  count                  = var.default_security_group_deny_all ? 1 : 0
  default_security_group_id = aws_vpc.this.default_security_group_id

  # Explicitly defined empty rule sets strip all default access rules
  ingress = []
  egress  = []

  tags = merge(
    local.tags,
    {
      "Name" = "${local.id}-default-sg-denied"
    }
  )
}

resource "aws_default_route_table" "this" {
  count                  = var.adopt_default_route_table ? 1 : 0
  default_route_table_id = aws_vpc.this.default_route_table_id

  tags = merge(
    local.tags,
    {
      "Name" = "${local.id}-default-rt"
    }
  )
}

resource "aws_default_network_acl" "this" {
  count                  = var.adopt_default_network_acl ? 1 : 0
  default_network_acl_id = aws_vpc.this.default_network_acl_id

  tags = merge(
    local.tags,
    {
      "Name" = "${local.id}-default-nacl"
    }
  )
}

# ------------------------------------------------------------------------------
# Resources: Internet Gateways
# ------------------------------------------------------------------------------

resource "aws_internet_gateway" "this" {
  count  = var.internet_gateway_enabled ? 1 : 0
  vpc_id = aws_vpc.this.id

  tags = merge(
    local.tags,
    {
      "Name" = "${local.id}-igw"
    }
  )
}

resource "aws_egress_only_internet_gateway" "this" {
  count  = var.ipv6_egress_only_internet_gateway_enabled ? 1 : 0
  vpc_id = aws_vpc.this.id

  tags = merge(
    local.tags,
    {
      "Name" = "${local.id}-eigw"
    }
  )
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "vpc_id" {
  description = "The ID of the VPC."
  value       = aws_vpc.this.id
}

output "vpc_arn" {
  description = "The ARN of the VPC."
  value       = aws_vpc.this.arn
}

output "vpc_cidr_block" {
  description = "The primary IPv4 CIDR block of the VPC."
  value       = aws_vpc.this.cidr_block
}

output "vpc_ipv6_cidr_block" {
  description = "The primary IPv6 CIDR block assigned to the VPC."
  value       = aws_vpc.this.ipv6_cidr_block
}

output "vpc_default_security_group_id" {
  description = "The ID of the default security group for the VPC."
  value       = aws_vpc.this.default_security_group_id
}

output "vpc_default_route_table_id" {
  description = "The ID of the default route table for the VPC."
  value       = aws_vpc.this.default_route_table_id
}

output "vpc_default_network_acl_id" {
  description = "The ID of the default network ACL for the VPC."
  value       = aws_vpc.this.default_network_acl_id
}

output "internet_gateway_id" {
  description = "The ID of the Internet Gateway."
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "egress_only_internet_gateway_id" {
  description = "The ID of the IPv6 Egress-Only Internet Gateway."
  value       = try(aws_egress_only_internet_gateway.this[0].id, null)
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into."
  default     = "us-east-1"
}

variable "username" {
  type        = string
  description = "Name of the IAM user for infrastructure provisioning."
  default     = "my_vpn_infra_user"
}

variable "group_name" {
  type        = string
  description = "Name of the IAM group."
  default     = "my-vpn-infra-group"
}

variable "membership_name" {
  type        = string
  description = "Name of the IAM group membership association."
  default     = "my-vpn-infra-manager-group"
}

variable "project_tag" {
  type        = string
  description = "Value applied to the ProjectTag tag on resources."
  default     = "my-vpn-tag"
}

variable "policy_path" {
  type        = string
  description = "Path for created IAM policies."
  default     = "/my_vpn_infra/"
}

# -----------------------------------------------------------------------------
# IAM User, Group, and Access Key
# -----------------------------------------------------------------------------
resource "aws_iam_user" "infra_user" {
  name          = var.username
  force_destroy = true

  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_access_key" "infra_user_key" {
  user   = aws_iam_user.infra_user.name
  status = "Active"
}

resource "aws_iam_group" "infra_group" {
  name = var.group_name
}

resource "aws_iam_group_membership" "infra_group_membership" {
  name  = var.membership_name
  users = [aws_iam_user.infra_user.name]
  group = aws_iam_group.infra_group.name
}

# -----------------------------------------------------------------------------
# IAM Policy: Basic
# -----------------------------------------------------------------------------
resource "aws_iam_policy" "basic_policy" {
  name        = "basic_policy"
  path        = var.policy_path
  description = "Grants STS GetCallerIdentity"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "STSGetCallerIdentity"
        Effect   = "Allow"
        Action   = "sts:GetCallerIdentity"
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

# -----------------------------------------------------------------------------
# IAM Policy: Create
# -----------------------------------------------------------------------------
resource "aws_iam_policy" "create_policy" {
  name        = "create_policy"
  path        = var.policy_path
  description = "Grants explicit EC2 resource creation actions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2CreateActions"
        Effect = "Allow"
        Action = [
          "ec2:CreateKeyPair",
          "ec2:CreateVpc",
          "ec2:CreateSubnet",
          "ec2:CreateInternetGateway",
          "ec2:CreateRoute",
          "ec2:CreateRouteTable",
          "ec2:CreateLocalGatewayRouteTableVpcAssociation",
          "ec2:CreateSecurityGroup",
          "ec2:AuthorizeSecurityGroupEgress",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:CreateReplaceRootVolumeTask",
          "ec2:CreateTags",
          "ec2:AllocateAddress"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

# -----------------------------------------------------------------------------
# IAM Policy: Read
# -----------------------------------------------------------------------------
resource "aws_iam_policy" "read_policy" {
  name        = "read_policy"
  path        = var.policy_path
  description = "Grants comprehensive EC2 read/describe actions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2ReadActions"
        Effect = "Allow"
        Action = [
          "ec2:DescribeAccountAttributes",
          "ec2:DescribeAddresses",
          "ec2:DescribeAddressesAttribute",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeClassicLinkInstances",
          "ec2:DescribeCustomerGateways",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeImages",
          "ec2:DescribeInstanceAttribute",
          "ec2:DescribeInstanceCreditSpecifications",
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeInstanceTypeOfferings",
          "ec2:DescribeInstanceTypes",
          "ec2:DescribeInternetGateways",
          "ec2:DescribeKeyPairs",
          "ec2:DescribeNatGateways",
          "ec2:DescribeNetworkAcls",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribePrefixLists",
          "ec2:DescribeRegions",
          "ec2:DescribeRouteTables",
          "ec2:DescribeSecurityGroupReferences",
          "ec2:DescribeSecurityGroupRules",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeTags",
          "ec2:DescribeVolumes",
          "ec2:DescribeVolumesModifications",
          "ec2:DescribeVpcAttribute",
          "ec2:DescribeVpcClassicLink",
          "ec2:DescribeVpcClassicLinkDnsSupport",
          "ec2:DescribeVpcEndpoints",
          "ec2:DescribeVpcs",
          "ec2:DescribeVpnConnections",
          "ec2:DescribeVpnGateways",
          "ec2:GetPasswordData"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

# -----------------------------------------------------------------------------
# IAM Policy: Update
# -----------------------------------------------------------------------------
resource "aws_iam_policy" "update_policy" {
  name        = "update_policy"
  path        = var.policy_path
  description = "Grants EC2 modification and association actions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2UpdateActions"
        Effect = "Allow"
        Action = [
          "ec2:AssociateAddress",
          "ec2:AssociateRouteTable",
          "ec2:AssociateSubnetCidrBlock",
          "ec2:AssociateVpcCidrBlock",
          "ec2:AttachInternetGateway",
          "ec2:AttachNetworkInterface",
          "ec2:AttachVolume",
          "ec2:DisassociateAddress",
          "ec2:DisassociateRouteTable",
          "ec2:DisassociateSubnetCidrBlock",
          "ec2:DisassociateVpcCidrBlock",
          "ec2:ModifyAddressAttribute",
          "ec2:ModifyNetworkInterfaceAttribute",
          "ec2:ModifySecurityGroupRules",
          "ec2:ModifySubnetAttribute",
          "ec2:ModifyVolume",
          "ec2:ModifyVolumeAttribute",
          "ec2:ModifyVpcAttribute",
          "ec2:ModifyVpcEndpoint",
          "ec2:ModifyVpcTenancy",
          "ec2:ReplaceRoute",
          "ec2:ReplaceRouteTableAssociation",
          "ec2:UpdateSecurityGroupRuleDescriptionsEgress",
          "ec2:UpdateSecurityGroupRuleDescriptionsIngress"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

# -----------------------------------------------------------------------------
# IAM Policy: Delete
# -----------------------------------------------------------------------------
resource "aws_iam_policy" "delete_policy" {
  name        = "delete_policy"
  path        = var.policy_path
  description = "Grants EC2 deletion, revocation, and detachment actions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2DeleteActions"
        Effect = "Allow"
        Action = [
          "ec2:DeleteKeyPair",
          "ec2:DeleteInternetGateway",
          "ec2:DeleteNetworkInterface",
          "ec2:DeleteRoute",
          "ec2:DeleteRouteTable",
          "ec2:DeleteSecurityGroup",
          "ec2:DeleteSubnet",
          "ec2:DeleteTags",
          "ec2:DeleteVolume",
          "ec2:DeleteVpc",
          "ec2:DeleteVpcEndpoints",
          "ec2:DetachInternetGateway",
          "ec2:DetachNetworkInterface",
          "ec2:DetachVolume",
          "ec2:ReleaseAddress",
          "ec2:RevokeSecurityGroupEgress",
          "ec2:RevokeSecurityGroupIngress"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

# -----------------------------------------------------------------------------
# IAM Policy: Instance Lifecycle
# -----------------------------------------------------------------------------
resource "aws_iam_policy" "instance_policy" {
  name        = "instance_policy"
  path        = var.policy_path
  description = "Grants EC2 instance lifecycle actions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2InstanceLifecycle"
        Effect = "Allow"
        Action = [
          "ec2:RunInstances",
          "ec2:StartInstances",
          "ec2:ResetInstanceAttribute",
          "ec2:ModifyInstanceAttribute",
          "ec2:StopInstances",
          "ec2:TerminateInstances",
          "ec2:RebootInstances"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

# -----------------------------------------------------------------------------
# IAM Policy: Terraform Backend Access
# -----------------------------------------------------------------------------
resource "aws_iam_policy" "terraform_backend_access" {
  name        = "terraform_backend_access"
  path        = var.policy_path
  description = "Grants DynamoDB state locking and S3 state storage access"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DynamoDBBackendAccess"
        Effect = "Allow"
        Action = [
          "dynamodb:DescribeTable",
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem"
        ]
        Resource = "*"
      },
      {
        Sid    = "S3BackendAccess"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    ProjectTag = var.project_tag
  }
}

# -----------------------------------------------------------------------------
# Policy Attachments to IAM Group
# -----------------------------------------------------------------------------
resource "aws_iam_group_policy_attachment" "basic_policy_attach" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.basic_policy.arn
}

resource "aws_iam_group_policy_attachment" "create_policy_attach" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.create_policy.arn
}

resource "aws_iam_group_policy_attachment" "read_policy_attach" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.read_policy.arn
}

resource "aws_iam_group_policy_attachment" "update_policy_attach" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.update_policy.arn
}

resource "aws_iam_group_policy_attachment" "delete_policy_attach" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.delete_policy.arn
}

resource "aws_iam_group_policy_attachment" "instance_policy_attach" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.instance_policy.arn
}

resource "aws_iam_group_policy_attachment" "terraform_backend_access_attach" {
  group      = aws_iam_group.infra_group.name
  policy_arn = aws_iam_policy.terraform_backend_access.arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "iam_user_name" {
  description = "The name of the IAM user created."
  value       = aws_iam_user.infra_user.name
}

output "iam_user_arn" {
  description = "The ARN of the IAM user created."
  value       = aws_iam_user.infra_user.arn
}

output "iam_group_name" {
  description = "The name of the IAM group created."
  value       = aws_iam_group.infra_group.name
}

output "iam_access_key_id" {
  description = "The access key ID for the provisioned IAM user."
  value       = aws_iam_access_key.infra_user_key.id
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "AWS region for provisioning resources"
  default     = "us-east-1"
}

variable "environment" {
  type        = string
  description = "Environment prefix for naming resources"
  default     = "DEV"
}

variable "existing_vpc_id" {
  type        = string
  description = "Optional existing VPC ID. If omitted, a new VPC will be provisioned."
  default     = ""
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the new VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for public subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for private subnets"
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "craete_private_subnet" {
  type        = bool
  description = "Boolean flag to enable creation of private subnets and NAT Gateway"
  default     = false
}

variable "eip_private_ip" {
  type        = string
  description = "Private IP to associate with the NAT Gateway Elastic IP"
  default     = "10.0.0.5"
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES
# ---------------------------------------------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------------------------------------------------
# VPC & INTERNET GATEWAY
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  count                = var.existing_vpc_id == "" ? 1 : 0
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name        = "${var.environment}-vpc"
    Environment = var.environment
  }
}

locals {
  vpc_id = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main[0].id
}

resource "aws_internet_gateway" "igw" {
  vpc_id = local.vpc_id

  tags = {
    Name        = "${var.environment}-igw"
    Environment = var.environment
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# PUBLIC NETWORKING
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = local.vpc_id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name        = "${var.environment}-public-subnet-${count.index + 1}"
    Environment = var.environment
    Tier        = "Public"
  }
}

resource "aws_route_table" "public" {
  vpc_id = local.vpc_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name        = "${var.environment}-public-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "public" {
  count          = length(var.public_subnet_cidrs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------------------------------------------------
# PRIVATE NETWORKING & NAT GATEWAY
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_subnet" "private" {
  count                   = var.craete_private_subnet ? length(var.private_subnet_cidrs) : 0
  vpc_id                  = local.vpc_id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${var.environment}-private-subnet-${count.index + 1}"
    Environment = var.environment
    Tier        = "Private"
  }
}

resource "aws_eip" "nat" {
  count  = var.craete_private_subnet ? 1 : 0
  domain = "vpc"

  # Optional private IP association
  associate_with_private_ip = var.eip_private_ip

  depends_on = [aws_internet_gateway.igw]

  tags = {
    Name        = "${var.environment}-nat-eip"
    Environment = var.environment
  }
}

resource "aws_nat_gateway" "nat" {
  count         = var.craete_private_subnet ? 1 : 0
  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name        = "${var.environment}-nat-gw"
    Environment = var.environment
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_route_table" "private" {
  count  = var.craete_private_subnet ? 1 : 0
  vpc_id = local.vpc_id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[0].id
  }

  tags = {
    Name        = "${var.environment}-private-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "private" {
  count          = var.craete_private_subnet ? length(var.private_subnet_cidrs) : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "vpc_id" {
  description = "The ID of the VPC"
  value       = local.vpc_id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = var.craete_private_subnet ? aws_subnet.private[*].id : []
}

output "nat_gateway_id" {
  description = "The ID of the NAT Gateway if created"
  value       = var.craete_private_subnet ? aws_nat_gateway.nat[0].id : null
}
```

```hcl
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region for provisioning resources"
  type        = string
  default     = "us-east-1"
}

variable "create" {
  description = "Whether to create the primary SQS queue"
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the SQS queue. If omitted, name_prefix will be used"
  type        = string
  default     = "my-app-queue"
}

variable "name_prefix" {
  description = "Prefix for the SQS queue name if name is not set"
  type        = string
  default     = null
}

variable "fifo_queue" {
  description = "Boolean designating a FIFO queue"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues"
  type        = bool
  default     = false
}

variable "delay_seconds" {
  description = "The time in seconds that the delivery of all messages in the queue will be delayed"
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "The limit of how many bytes a message can contain before Amazon SQS rejects it"
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "The number of seconds Amazon SQS retains a message"
  type        = number
  default     = 345600 # 4 days
}

variable "receive_wait_time_seconds" {
  description = "The time for which a ReceiveMessage call will wait for a message to arrive"
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "The visibility timeout for the queue in seconds"
  type        = number
  default     = 30
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed or customer-managed KMS key for Amazon SQS"
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "The length of time, in seconds, for which Amazon SQS can reuse a data key to encrypt or decrypt messages"
  type        = number
  default     = 300
}

variable "sqs_managed_sse_enabled" {
  description = "Boolean to enable server-side encryption (SSE) of message content with SQS-owned encryption keys"
  type        = bool
  default     = true
}

variable "create_queue_policy" {
  description = "Whether to create an SQS queue policy"
  type        = bool
  default     = false
}

variable "queue_policy_statements" {
  description = "Custom statements to add to the queue policy"
  type = list(object({
    sid       = optional(string)
    effect    = optional(string, "Allow")
    actions   = list(string)
    principals = list(object({
      type        = string
      identifiers = list(string)
    }))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })), [])
  }))
  default = []
}

variable "create_dlq" {
  description = "Whether to create a dead-letter queue (DLQ) for the primary queue"
  type        = bool
  default     = false
}

variable "dlq_name" {
  description = "Custom name for the DLQ. If omitted, default suffix '-dlq' will be appended to main queue name"
  type        = string
  default     = null
}

variable "dlq_max_receive_count" {
  description = "The number of times a message is delivered to the source queue before being moved to the dead-letter queue"
  type        = number
  default     = 5
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to attach a redrive allow policy to the dead-letter queue"
  type        = bool
  default     = true
}

variable "tags" {
  description = "A mapping of tags to assign to all resources"
  type        = map(string)
  default     = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

# -----------------------------------------------------------------------------
# Local Values for Names and Suffixes
# -----------------------------------------------------------------------------
locals {
  # Base name calculation
  base_name = var.name != null ? (
    var.fifo_queue ? trimsuffix(var.name, ".fifo") : var.name
  ) : null

  base_name_prefix = var.name_prefix != null ? (
    var.fifo_queue ? trimsuffix(var.name_prefix, ".fifo") : var.name_prefix
  ) : null

  # Final queue name calculation
  queue_name = local.base_name != null ? (
    var.fifo_queue ? "${local.base_name}.fifo" : local.base_name
  ) : null

  queue_name_prefix = local.base_name_prefix != null ? (
    var.fifo_queue ? "${local.base_name_prefix}-" : local.base_name_prefix
  ) : null

  # DLQ naming calculation
  dlq_base_name = var.dlq_name != null ? (
    var.fifo_queue ? trimsuffix(var.dlq_name, ".fifo") : var.dlq_name
  ) : (
    local.base_name != null ? "${local.base_name}-dlq" : null
  )

  dlq_name = local.dlq_base_name != null ? (
    var.fifo_queue ? "${local.dlq_base_name}.fifo" : local.dlq_base_name
  ) : null

  dlq_name_prefix = (local.dlq_base_name == null && local.base_name_prefix != null) ? (
    var.fifo_queue ? "${local.base_name_prefix}-dlq-" : "${local.base_name_prefix}-dlq-"
  ) : null

  # SSE configuration
  use_sqs_sse = var.kms_master_key_id == null && var.sqs_managed_sse_enabled
}

# -----------------------------------------------------------------------------
# Dead Letter Queue (DLQ)
# -----------------------------------------------------------------------------
resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name        = local.dlq_name
  name_prefix = local.dlq_name != null ? null : local.dlq_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null

  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null
  sqs_managed_sse_enabled           = local.use_sqs_sse

  message_retention_seconds = 1209600 # 14 days standard for DLQ

  tags = merge(var.tags, {
    Name = local.dlq_name != null ? local.dlq_name : "sqs-dlq"
    Role = "DeadLetterQueue"
  })
}

# Redrive Allow Policy for DLQ
resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url

  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [aws_sqs_queue.this[0].arn]
  })
}

# -----------------------------------------------------------------------------
# Primary SQS Queue
# -----------------------------------------------------------------------------
resource "aws_sqs_queue" "this" {
  count = var.create ? 1 : 0

  name        = local.queue_name
  name_prefix = local.queue_name != null ? null : local.queue_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null

  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null
  sqs_managed_sse_enabled           = local.use_sqs_sse

  redrive_policy = var.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.dlq_max_receive_count
  }) : null

  tags = merge(var.tags, {
    Name = local.queue_name != null ? local.queue_name : "sqs-primary"
  })
}

# -----------------------------------------------------------------------------
# Queue Policy
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "queue_policy" {
  count = var.create && var.create_queue_policy ? 1 : 0

  dynamic "statement" {
    for_each = var.queue_policy_statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = [aws_sqs_queue.this[0].arn]

      dynamic "principals" {
        for_each = statement.value.principals
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  policy    = data.aws_iam_policy_document.queue_policy[0].json
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "queue_id" {
  description = "The URL of the primary SQS queue"
  value       = try(aws_sqs_queue.this[0].id, null)
}

output "queue_arn" {
  description = "The ARN of the primary SQS queue"
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_name" {
  description = "The name of the primary SQS queue"
  value       = try(aws_sqs_queue.this[0].name, null)
}

output "dlq_id" {
  description = "The URL of the dead-letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].id, null)
}

output "dlq_arn" {
  description = "The ARN of the dead-letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dlq_name" {
  description = "The name of the dead-letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].name, null)
}
```

terraform {
  required_version = ">= 1.0.0"
