terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# --------------------------------------------------------------------------------------------------
# Input Variables
# --------------------------------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources in."
  default     = "us-east-1"
}

variable "backup_name" {
  type        = string
  description = "Base identifier for the backup vault, plan, and role."
  default     = "workload-data"
}

variable "account_type" {
  type        = string
  description = "Account deployment type: 'workload' or 'backup'."
  default     = "workload"

  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "The account_type variable must be strictly set to 'workload' or 'backup'."
  }
}

variable "kms_key_arn" {
  type        = string
  description = "Optional KMS key ARN to encrypt the backup vault. If omitted, the default AWS managed key is used."
  default     = null
}

variable "vault_policy" {
  type        = string
  description = "Optional JSON access policy string to attach to the backup vault."
  default     = null
}

variable "min_retention_days" {
  type        = number
  description = "Minimum retention period in days to enforce via Backup Vault Lock. If null, lock configuration is skipped."
  default     = null
}

variable "max_retention_days" {
  type        = number
  description = "Maximum retention period in days allowed by the Backup Vault Lock."
  default     = null
}

variable "changeable_for_days" {
  type        = number
  description = "Number of days before the Backup Vault Lock becomes permanent and immutable."
  default     = null
}

variable "enable_aws_backup_vault_notifications" {
  type        = bool
  description = "Controls whether to enable AWS Backup vault SNS notifications."
  default     = false
}

variable "sns_topic_arn" {
  type        = string
  description = "The ARN of the SNS topic to route vault events to when notifications are enabled."
  default     = null
}

variable "backup_vault_events" {
  type        = list(string)
  description = "Array of events that trigger SNS notifications from the backup vault."
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "schedule_cron" {
  type        = string
  description = "Cron or rate expression specifying when backups run."
  default     = "cron(0 5 ? * * *)"
}

variable "start_window_minutes" {
  type        = number
  description = "The amount of time in minutes before a backup job is canceled if it doesn't start."
  default     = 60
}

variable "completion_window_minutes" {
  type        = number
  description = "The amount of time in minutes AWS Backup attempts to complete a backup job before canceling it."
  default     = 120
}

variable "cold_storage_after_days" {
  type        = number
  description = "Days after creation when a recovery point transitions to cold storage."
  default     = 30
}

variable "delete_after_days" {
  type        = number
  description = "Days after creation when a recovery point is deleted."
  default     = 120
}

variable "copy_actions" {
  type = list(object({
    destination_vault_arn = string
    cold_storage_days     = optional(number)
    delete_after_days     = optional(number)
  }))
  description = "Optional list of copy actions for cross-region or cross-account secondary vaults."
  default     = []
}

variable "selection_resources" {
  type        = list(string)
  description = "Optional list of explicit resource ARNs to include in the backup selection."
  default     = []
}

variable "tags" {
  type        = map(string)
  description = "Resource tags to apply to all supported resources."
  default = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

# --------------------------------------------------------------------------------------------------
# Backup Vault and Lock Configuration
# --------------------------------------------------------------------------------------------------

resource "aws_backup_vault" "this" {
  name        = "${var.backup_name}-vault"
  kms_key_arn = var.kms_key_arn
  tags        = var.tags
}

resource "aws_backup_vault_policy" "this" {
  count             = var.vault_policy != null ? 1 : 0
  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_lock_configuration" "this" {
  count               = var.min_retention_days != null ? 1 : 0
  backup_vault_name   = aws_backup_vault.this.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

resource "aws_backup_vault_notifications" "this" {
  count               = var.enable_aws_backup_vault_notifications && var.sns_topic_arn != null ? 1 : 0
  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.backup_vault_events
}

# --------------------------------------------------------------------------------------------------
# Workload Account Resources: IAM Role, Backup Plan, and Backup Selection
# --------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "backup" {
  count              = var.account_type == "workload" ? 1 : 0
  name_prefix        = "aws-backup-"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "backup" {
  count      = var.account_type == "workload" ? 1 : 0
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
  role       = aws_iam_role.backup[0].name
}

resource "aws_backup_plan" "this" {
  count = var.account_type == "workload" ? 1 : 0
  name  = "plan-${var.backup_name}-backup"

  rule {
    rule_name                = "rule-${var.backup_name}"
    target_vault_name        = aws_backup_vault.this.name
    schedule                 = var.schedule_cron
    start_window             = var.start_window_minutes
    completion_window        = var.completion_window_minutes
    enable_continuous_backup = false

    lifecycle {
      cold_storage_after = var.cold_storage_after_days
      delete_after       = var.delete_after_days
    }

    recovery_point_tags = merge(
      var.tags,
      {
        BackupSource = var.backup_name
      }
    )

    dynamic "copy_action" {
      for_each = var.copy_actions
      content {
        destination_vault_arn = copy_action.value.destination_vault_arn

        dynamic "lifecycle" {
          for_each = copy_action.value.cold_storage_days != null || copy_action.value.delete_after_days != null ? [1] : []
          content {
            cold_storage_after = copy_action.value.cold_storage_days
            delete_after       = copy_action.value.delete_after_days
          }
        }
      }
    }
  }

  tags = var.tags
}

resource "aws_backup_selection" "this" {
  count        = var.account_type == "workload" ? 1 : 0
  iam_role_arn = aws_iam_role.backup[0].arn
  name         = "selection-${var.backup_name}"
  plan_id      = aws_backup_plan.this[0].id

  resources = length(var.selection_resources) > 0 ? var.selection_resources : null

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }
}

# --------------------------------------------------------------------------------------------------
# Outputs
# --------------------------------------------------------------------------------------------------

output "backup_vault_arn" {
  description = "The ARN of the backup vault."
  value       = aws_backup_vault.this.arn
}

output "backup_vault_name" {
  description = "The name of the backup vault."
  value       = aws_backup_vault.this.name
}

output "backup_plan_id" {
  description = "The ID of the backup plan (if created)."
  value       = var.account_type == "workload" ? aws_backup_plan.this[0].id : null
}

output "backup_plan_arn" {
  description = "The ARN of the backup plan (if created)."
  value       = var.account_type == "workload" ? aws_backup_plan.this[0].arn : null
}

output "backup_role_arn" {
  description = "The ARN of the IAM role used by AWS Backup (if created)."
  value       = var.account_type == "workload" ? aws_iam_role.backup[0].arn : null
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region for resources."
  default     = "us-east-1"
}

variable "name_prefix" {
  type        = string
  description = "Base name for AWS Config resources. Defaults to 'config'."
  default     = "config"
}

variable "environment" {
  type        = string
  description = "Environment identifier tag."
  default     = "production"
}

# -----------------------------------------------------------------------------
# Data Sources & Random Naming
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

resource "random_pet" "suffix" {
  length = 2
}

locals {
  base_name   = (var.name_prefix != null && var.name_prefix != "") ? var.name_prefix : "config-${random_pet.suffix.id}"
  account_id  = data.aws_caller_identity.current.account_id
  partition   = data.aws_partition.current.partition
  s3_prefix   = "awsconfig/records"
  bucket_name = "${local.base_name}-snapshots-${local.account_id}"
}

# -----------------------------------------------------------------------------
# Customer-Managed KMS Key for SNS Encryption
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowConfigAndSNSServiceAccess"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
      "kms:Encrypt"
    ]
    resources = ["*"]
    principals {
      type = "Service"
      identifiers = [
        "config.amazonaws.com",
        "sns.amazonaws.com"
      ]
    }
  }
}

resource "aws_kms_key" "config_kms" {
  description             = "Dedicated KMS key for AWS Config SNS topic encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = {
    Name         = "${local.base_name}-kms"
    Environment  = var.environment
    "terraform.io" = "managed"
  }
}

resource "aws_kms_alias" "config_kms_alias" {
  name          = "alias/${local.base_name}-key"
  target_key_id = aws_kms_key.config_kms.key_id
}

# -----------------------------------------------------------------------------
# SNS Topic for AWS Config Streaming Notifications
# -----------------------------------------------------------------------------
resource "aws_sns_topic" "config_topic" {
  name              = local.base_name
  kms_master_key_id = aws_kms_key.config_kms.arn

  tags = {
    Name         = local.base_name
    Environment  = var.environment
    "terraform.io" = "managed"
  }
}

data "aws_iam_policy_document" "sns_topic_policy" {
  statement {
    sid    = "AWSConfigSNSPublish"
    effect = "Allow"
    actions = [
      "sns:Publish"
    ]
    resources = [aws_sns_topic.config_topic.arn]
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }
}

resource "aws_sns_topic_policy" "config_topic_policy" {
  arn    = aws_sns_topic.config_topic.arn
  policy = data.aws_iam_policy_document.sns_topic_policy.json
}

# -----------------------------------------------------------------------------
# S3 Bucket for AWS Config Snapshots
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "config_bucket" {
  bucket        = local.bucket_name
  force_destroy = true

  tags = {
    Name         = local.bucket_name
    Environment  = var.environment
    "terraform.io" = "managed"
  }
}

resource "aws_s3_bucket_public_access_block" "config_bucket_pab" {
  bucket                  = aws_s3_bucket.config_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config_bucket_sse" {
  bucket = aws_s3_bucket.config_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

data "aws_iam_policy_document" "config_bucket_policy" {
  statement {
    sid    = "AWSConfigBucketPermissionsCheck"
    effect = "Allow"
    actions = [
      "s3:GetBucketAcl",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.config_bucket.arn
    ]
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }

  statement {
    sid    = "AWSConfigBucketExistenceCheck"
    effect = "Allow"
    actions = [
      "s3:GetBucketAcl"
    ]
    resources = [
      aws_s3_bucket.config_bucket.arn
    ]
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }

  statement {
    sid    = "AWSConfigBucketDelivery"
    effect = "Allow"
    actions = [
      "s3:PutObject"
    ]
    resources = [
      "${aws_s3_bucket.config_bucket.arn}/${local.s3_prefix}/AWSLogs/${local.account_id}/Config/*"
    ]
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "config_bucket_policy" {
  bucket = aws_s3_bucket.config_bucket.id
  policy = data.aws_iam_policy_document.config_bucket_policy.json
}

# -----------------------------------------------------------------------------
# IAM Role for AWS Config
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "config_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "config_role" {
  name               = "${local.base_name}-role"
  assume_role_policy = data.aws_iam_policy_document.config_assume_role.json

  tags = {
    Name         = "${local.base_name}-role"
    Environment  = var.environment
    "terraform.io" = "managed"
  }
}

resource "aws_iam_role_policy_attachment" "config_managed_policy" {
  role       = aws_iam_role.config_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

data "aws_iam_policy_document" "config_s3_sns_policy_doc" {
  statement {
    sid    = "ConfigS3Delivery"
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:PutObjectAcl"
    ]
    resources = [
      "${aws_s3_bucket.config_bucket.arn}/${local.s3_prefix}/AWSLogs/${local.account_id}/Config/*"
    ]
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }

  statement {
    sid    = "ConfigS3BucketCheck"
    effect = "Allow"
    actions = [
      "s3:GetBucketAcl",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.config_bucket.arn
    ]
  }

  statement {
    sid    = "ConfigSNSPublish"
    effect = "Allow"
    actions = [
      "sns:Publish"
    ]
    resources = [
      aws_sns_topic.config_topic.arn
    ]
  }

  statement {
    sid    = "ConfigKMSUsage"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]
    resources = [
      aws_kms_key.config_kms.arn
    ]
  }
}

resource "aws_iam_role_policy" "config_s3_sns_policy" {
  name   = "${local.base_name}-s3-sns-policy"
  role   = aws_iam_role.config_role.id
  policy = data.aws_iam_policy_document.config_s3_sns_policy_doc.json
}

# -----------------------------------------------------------------------------
# AWS Config Configuration Recorder & Delivery Channel
# -----------------------------------------------------------------------------
resource "aws_config_configuration_recorder" "recorder" {
  name     = local.base_name
  role_arn = aws_iam_role.config_role.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "delivery_channel" {
  name           = local.base_name
  s3_bucket_name = aws_s3_bucket.config_bucket.bucket
  s3_key_prefix  = local.s3_prefix
  sns_topic_arn  = aws_sns_topic.config_topic.arn

  snapshot_delivery_properties {
    delivery_frequency = "TwentyFour_Hours"
  }

  depends_on = [
    aws_config_configuration_recorder.recorder,
    aws_s3_bucket_policy.config_bucket_policy,
    aws_sns_topic_policy.config_topic_policy
  ]
}

resource "aws_config_configuration_recorder_status" "recorder_status" {
  name       = aws_config_configuration_recorder.recorder.name
  is_enabled = true

  depends_on = [aws_config_delivery_channel.delivery_channel]
}

# -----------------------------------------------------------------------------
# AWS Config Managed Rules
# -----------------------------------------------------------------------------
# 1. CloudTrail Enabled
resource "aws_config_config_rule" "cloudtrail_enabled" {
  name        = "cloudtrail-enabled"
  description = "Checks whether AWS CloudTrail is enabled in the account."

  source {
    owner             = "AWS"
    source_identifier = "CLOUD_TRAIL_ENABLED"
  }

  maximum_execution_frequency = "TwentyFour_Hours"

  depends_on = [aws_config_configuration_recorder_status.recorder_status]
}

# 2. IAM Password Policy
resource "aws_config_config_rule" "iam_pw_policy" {
  name        = "iam-pw-policy"
  description = "Checks whether the account password policy for IAM users meets specified requirements."

  source {
    owner             = "AWS"
    source_identifier = "IAM_PASSWORD_POLICY"
  }

  maximum_execution_frequency = "TwentyFour_Hours"

  depends_on = [aws_config_configuration_recorder_status.recorder_status]
}

# 3. Instances in VPC
resource "aws_config_config_rule" "ec2_vpc" {
  name        = "ec2-vpc"
  description = "Checks whether EC2 instances belong to a Virtual Private Cloud (VPC)."

  source {
    owner             = "AWS"
    source_identifier = "INSTANCES_IN_VPC"
  }

  scope {
    compliance_resource_types = ["AWS::EC2::Instance"]
  }

  depends_on = [aws_config_configuration_recorder_status.recorder_status]
}

# 4. Root Account MFA Enabled
resource "aws_config_config_rule" "root_mfa_enabled" {
  name        = "root-mfa-enabled"
  description = "Checks whether the root user has MFA enabled."

  source {
    owner             = "AWS"
    source_identifier = "ROOT_ACCOUNT_MFA_ENABLED"
  }

  maximum_execution_frequency = "TwentyFour_Hours"

  depends_on = [aws_config_configuration_recorder_status.recorder_status]
}

# 5. ACM Certificate Expiration Check
resource "aws_config_config_rule" "acm_expiration_check" {
  name        = "acm-expiration-check"
  description = "Checks whether ACM Certificates are about to expire within the renewal period."

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  maximum_execution_frequency = "TwentyFour_Hours"

  depends_on = [aws_config_configuration_recorder_status.recorder_status]
}

# 6. EBS Volume In-Use Check
resource "aws_config_config_rule" "ebs_inuse_check" {
  name        = "ebs-inuse-check"
  description = "Checks whether EBS volumes are attached to EC2 instances."

  source {
    owner             = "AWS"
    source_identifier = "EC2_VOLUME_INUSE_CHECK"
  }

  scope {
    compliance_resource_types = ["AWS::EC2::Volume"]
  }

  depends_on = [aws_config_configuration_recorder_status.recorder_status]
}

# 7. EC2 IMDSv2 Check
resource "aws_config_config_rule" "ec2_imdsv2_check" {
  name        = "ec2-imdsv2-check"
  description = "Checks whether EC2 instances are configured to use IMDSv2."

  source {
    owner             = "AWS"
    source_identifier = "EC2_IMDSV2_CHECK"
  }

  scope {
    compliance_resource_types = ["AWS::EC2::Instance"]
  }

  depends_on = [aws_config_configuration_recorder_status.recorder_status]
}

# 8. RDS Storage Encrypted
resource "aws_config_config_rule" "rds_encrypted" {
  name        = "rds-encrypted"
  description = "Checks whether storage encryption is enabled for your RDS DB instances."

  source {
    owner             = "AWS"
    source_identifier = "RDS_STORAGE_ENCRYPTED"
  }

  scope {
    compliance_resource_types = ["AWS::RDS::DBInstance"]
  }

  depends_on = [aws_config_configuration_recorder_status.recorder_status]
}

# 9. RDS Private
resource "aws_config_config_rule" "rds_private" {
  name        = "rds-private"
  description = "Checks whether the RDS instance is not publicly accessible."

  source {
    owner             = "AWS"
    source_identifier = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK"
  }

  scope {
    compliance_resource_types = ["AWS::RDS::DBInstance"]
  }

  depends_on = [aws_config_configuration_recorder_status.recorder_status]
}

# 10. RDS Private Snapshots
resource "aws_config_config_rule" "rds_private_snapshots" {
  name        = "rds-private-snapshots"
  description = "Checks whether RDS snapshots are not publicly shared."

  source {
    owner             = "AWS"
    source_identifier = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED"
  }

  scope {
    compliance_resource_types = [
      "AWS::RDS::DBSnapshot",
      "AWS::RDS::DBClusterSnapshot"
    ]
  }

  depends_on = [aws_config_configuration_recorder_status.recorder_status]
}

# 11. Required Tags (S3 Scoped)
resource "aws_config_config_rule" "required_tags" {
  name        = "required-tags"
  description = "Checks whether S3 buckets have the required tags terraform.io and environment."

  source {
    owner             = "AWS"
    source_identifier = "REQUIRED_TAGS"
  }

  scope {
    compliance_resource_types = ["AWS::S3::Bucket"]
  }

  input_parameters = jsonencode({
    tag1Key = "terraform.io"
    tag2Key = "environment"
  })

  depends_on = [aws_config_configuration_recorder_status.recorder_status]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "config_recorder_name" {
  description = "Name of the AWS Config configuration recorder"
  value       = aws_config_configuration_recorder.recorder.name
}

output "config_bucket_arn" {
  description = "ARN of the S3 bucket storing AWS Config history and snapshots"
  value       = aws_s3_bucket.config_bucket.arn
}

output "config_sns_topic_arn" {
  description = "ARN of the encrypted SNS topic for AWS Config notifications"
  value       = aws_sns_topic.config_topic.arn
}

output "config_role_arn" {
  description = "ARN of the AWS Config IAM Role"
  value       = aws_iam_role.config_role.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "The AWS region to deploy the resources in."
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for the public subnets."
  default     = ["10.0.4.0/24", "10.0.6.0/24", "10.0.8.0/24"]
}

variable "private_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for the private subnets."
  default     = ["10.0.10.0/24", "10.0.12.0/24", "10.0.14.0/24"]
}

variable "common_tags" {
  type        = map(string)
  description = "Common tags applied to resources."
  default = {
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# VPC and Internet Gateway
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.common_tags, {
    Name = "bjit-vpc"
  })
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.common_tags, {
    Name = "bjit-igw"
  })
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.common_tags, {
    Name = "bjit-public-subnet-${count.index + 1}"
    Tier = "Public"
  })
}

resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.common_tags, {
    Name = "bjit-private-subnet-${count.index + 1}"
    Tier = "Private"
  })
}

# -----------------------------------------------------------------------------
# Route Tables & Associations
# -----------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(var.common_tags, {
    Name = "bjit-public-route-table"
  })
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id

  tags = merge(var.common_tags, {
    Name = "bjit-private-route-table-${count.index + 1}"
  })
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# -----------------------------------------------------------------------------
# S3 VPC Gateway Endpoint
# -----------------------------------------------------------------------------
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.aws_region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = merge(var.common_tags, {
    Name = "bjit-s3-endpoint"
  })
}

# -----------------------------------------------------------------------------
# Security Groups
# -----------------------------------------------------------------------------

# 1. ALB Security Group: Ports 80-443 from anywhere
resource "aws_security_group" "alb" {
  name        = "bjit-api-server-ALB-SG"
  description = "Security Group for ALB allowing HTTP and HTTPS traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow inbound TCP 80 through 443 from anywhere"
    from_port   = 80
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(var.common_tags, {
    Name = "bjit-api-server-ALB-SG"
  })
}

# 2. MariaDB RDS Security Group: Port 3306 from VPC CIDR
resource "aws_security_group" "mariadb" {
  name        = "bjit-mariaDB-RDS-SG"
  description = "Security Group for MariaDB/MySQL database"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow MySQL/MariaDB from VPC CIDR"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(var.common_tags, {
    Name = "bjit-mariaDB-RDS-SG"
  })
}

# 3. Redis Security Group: Port 6379 from VPC CIDR
resource "aws_security_group" "redis" {
  name        = "bjit-redis-SG"
  description = "Security Group for Redis cache cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow Redis from VPC CIDR"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(var.common_tags, {
    Name = "bjit-redis-SG"
  })
}

# 4. API Server Security Group: Ports 8080 and 22 from VPC CIDR
resource "aws_security_group" "api_server" {
  name        = "bjit-api-server-SG"
  description = "Security Group for API servers"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow API traffic on port 8080 from VPC CIDR"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "Allow SSH on port 22 from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(var.common_tags, {
    Name = "bjit-api-server-SG"
  })
}

# 5. File Server Security Group: Ports 8081 and 22 from VPC CIDR
resource "aws_security_group" "file_server" {
  name        = "bjit-file-server-SG"
  description = "Security Group for File servers"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow File Server traffic on port 8081 from VPC CIDR"
    from_port   = 8081
    to_port     = 8081
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "Allow SSH on port 22 from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(var.common_tags, {
    Name = "bjit-file-server-SG"
  })
}

# 6. Public SSH Bastion / Jumper Security Group: Port 22 from VPC CIDR
resource "aws_security_group" "public_ssh" {
  name        = "bjit-public-ssh-SG"
  description = "Security Group for SSH access"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow SSH on port 22 from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(var.common_tags, {
    Name = "bjit-public-ssh-SG"
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "List of IDs of public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "List of IDs of private subnets"
  value       = aws_subnet.private[*].id
}

output "s3_endpoint_id" {
  description = "The ID of the S3 VPC Endpoint"
  value       = aws_vpc_endpoint.s3.id
}

output "security_group_ids" {
  description = "Map of all created security group IDs"
  value = {
    alb         = aws_security_group.alb.id
    mariadb     = aws_security_group.mariadb.id
    redis       = aws_security_group.redis.id
    api_server  = aws_security_group.api_server.id
    file_server = aws_security_group.file_server.id
    public_ssh  = aws_security_group.public_ssh.id
  }
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  description = "The AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "base_name" {
  description = "Prefix used for naming resources."
  type        = string
  default     = "benchmark"
}

variable "vpc_cidr" {
  description = "CIDR block for the main VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_public_cidrs" {
  description = "List of CIDR blocks for public subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "subnet_private_cidrs" {
  description = "Optional list of CIDR blocks for private subnets. Defaults to null."
  type        = list(string)
  default     = null
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES & LOCALS
# ---------------------------------------------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  private_subnets_enabled = var.subnet_private_cidrs != null && length(coalesce(var.subnet_private_cidrs, [])) > 0
  private_cidrs           = local.private_subnets_enabled ? var.subnet_private_cidrs : []

  # Collect all CIDRs that require access to the ECR endpoints
  allowed_endpoint_ingress_cidrs = concat(var.subnet_public_cidrs, local.private_cidrs)
}

# ---------------------------------------------------------------------------------------------------------------------
# VPC & INTERNET GATEWAY
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${var.base_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-igw"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# PUBLIC SUBNETS & ROUTING
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_subnet" "public" {
  count                   = length(var.subnet_public_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_public_cidrs[count.index]
  # Starting from the second zone index (index 1 + count.index)
  availability_zone       = data.aws_availability_zones.available.names[(count.index + 1) % length(data.aws_availability_zones.available.names)]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.base_name}-public-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.base_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------------------------------------------------
# PRIVATE SUBNETS, EIPS, NAT GATEWAYS & ROUTING (CONDITIONAL)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_subnet" "private" {
  count             = local.private_subnets_enabled ? length(local.private_cidrs) : 0
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_cidrs[count.index]
  # Matching the availability zone index used by public subnets
  availability_zone = data.aws_availability_zones.available.names[(count.index + 1) % length(data.aws_availability_zones.available.names)]

  tags = {
    Name = "${var.base_name}-private-subnet-${count.index + 1}"
  }
}

resource "aws_eip" "nat" {
  count  = local.private_subnets_enabled ? length(aws_subnet.public) : 0
  domain = "vpc"

  tags = {
    Name = "${var.base_name}-nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count         = local.private_subnets_enabled ? length(aws_subnet.public) : 0
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.base_name}-nat-gw-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count  = local.private_subnets_enabled ? length(aws_subnet.private) : 0
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index % length(aws_nat_gateway.main)].id
  }

  tags = {
    Name = "${var.base_name}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = local.private_subnets_enabled ? length(aws_subnet.private) : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------------------------------------------------------------------------------------------------------------
# S3 GATEWAY ENDPOINT
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.${var.aws_region}.s3"
  vpc_endpoint_type = "Gateway"

  # Associated with the public route table and conditionally private route tables
  route_table_ids = concat(
    [aws_route_table.public.id],
    local.private_subnets_enabled ? aws_route_table.private[*].id : []
  )

  tags = {
    Name = "${var.base_name}-s3-gateway-endpoint"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# ECR SECURITY GROUP & INTERFACE VPC ENDPOINTS
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_security_group" "ecr_endpoints" {
  name        = "${var.base_name}-ecr-endpoints-sg"
  description = "Security group for ECR Interface VPC Endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow HTTPS from public and private subnets"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = local.allowed_endpoint_ingress_cidrs
  }

  egress {
    description = "Allow egress only within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.base_name}-ecr-endpoints-sg"
  }
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${var.aws_region}.ecr.api"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true

  subnet_ids = local.private_subnets_enabled ? aws_subnet.private[*].id : aws_subnet.public[*].id
  security_group_ids = [aws_security_group.ecr_endpoints.id]

  tags = {
    Name = "${var.base_name}-ecr-api-endpoint"
  }
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${var.aws_region}.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true

  subnet_ids = local.private_subnets_enabled ? aws_subnet.private[*].id : aws_subnet.public[*].id
  security_group_ids = [aws_security_group.ecr_endpoints.id]

  tags = {
    Name = "${var.base_name}-ecr-dkr-endpoint"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "vpc_id" {
  description = "The ID of the main VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "The IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "The IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "ecr_endpoint_security_group_id" {
  description = "The ID of the security group for ECR endpoints."
  value       = aws_security_group.ecr_endpoints.id
}
```

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "The AWS region to deploy the infrastructure."
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "pub_sub_1_cidr" {
  type        = string
  description = "CIDR block for public subnet 1."
  default     = "10.0.1.0/24"
}

variable "pub_sub_2_cidr" {
  type        = string
  description = "CIDR block for public subnet 2."
  default     = "10.0.2.0/24"
}

variable "pvt_sub_1_cidr" {
  type        = string
  description = "CIDR block for private subnet 1."
  default     = "10.0.3.0/24"
}

variable "pvt_sub_2_cidr" {
  type        = string
  description = "CIDR block for private subnet 2."
  default     = "10.0.4.0/24"
}

variable "admin_ssh_cidr" {
  type        = string
  description = "CIDR block allowed to SSH into public instances."
  default     = "203.0.113.0/24"
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES
# ---------------------------------------------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------------------------------------------------
# VPC & INTERNET GATEWAY
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "project-vpc"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "T-igw"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# SUBNETS
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_subnet" "pub_sub_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.pub_sub_1_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "pub-sub-1"
  }
}

resource "aws_subnet" "pub_sub_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.pub_sub_2_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "pub-sub-2"
  }
}

resource "aws_subnet" "pvt_sub_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.pvt_sub_1_cidr
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "pvt-sub-1"
  }
}

resource "aws_subnet" "pvt_sub_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.pvt_sub_2_cidr
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "pvt-sub-2"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# ELASTIC IPS & NAT GATEWAYS
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_eip" "nat1" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.igw]

  tags = {
    Name = "T-NAT1-eip"
  }
}

resource "aws_eip" "nat2" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.igw]

  tags = {
    Name = "T-NAT2-eip"
  }
}

resource "aws_nat_gateway" "nat_gw_1" {
  allocation_id = aws_eip.nat1.id
  subnet_id     = aws_subnet.pub_sub_1.id

  tags = {
    Name = "T-NAT1"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_nat_gateway" "nat_gw_2" {
  allocation_id = aws_eip.nat2.id
  subnet_id     = aws_subnet.pub_sub_2.id

  tags = {
    Name = "T-NAT1"
  }

  depends_on = [aws_internet_gateway.igw]
}

# ---------------------------------------------------------------------------------------------------------------------
# ROUTE TABLES & ASSOCIATIONS
# ---------------------------------------------------------------------------------------------------------------------

# Public Route Table 1
resource "aws_route_table" "pub_rt_1" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "RT_PUBRT-1"
  }
}

resource "aws_route_table_association" "pub_rta_1" {
  subnet_id      = aws_subnet.pub_sub_1.id
  route_table_id = aws_route_table.pub_rt_1.id
}

# Public Route Table 2
resource "aws_route_table" "pub_rt_2" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "RT_PUBRT-2"
  }
}

resource "aws_route_table_association" "pub_rta_2" {
  subnet_id      = aws_subnet.pub_sub_2.id
  route_table_id = aws_route_table.pub_rt_2.id
}

# Private Route Table 1
resource "aws_route_table" "pvt_rt_1" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_gw_1.id
  }

  tags = {
    Name = "RT_PVTRT-1"
  }
}

resource "aws_route_table_association" "pvt_rta_1" {
  subnet_id      = aws_subnet.pvt_sub_1.id
  route_table_id = aws_route_table.pvt_rt_1.id
}

# Private Route Table 2
resource "aws_route_table" "pvt_rt_2" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_gw_1.id
  }

  tags = {
    Name = "RT_PVTRT-2"
  }
}

resource "aws_route_table_association" "pvt_rta_2" {
  subnet_id      = aws_subnet.pvt_sub_2.id
  route_table_id = aws_route_table.pvt_rt_2.id
}

# ---------------------------------------------------------------------------------------------------------------------
# SECURITY GROUPS
# ---------------------------------------------------------------------------------------------------------------------

# Public Security Group: allow_tls
resource "aws_security_group" "allow_tls" {
  name        = "allow_tls"
  description = "Allow inbound TLS/HTTP from everywhere and SSH from admin range"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from admin CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_ssh_cidr]
  }

  egress {
    description = "Egress limited to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "allow_tls"
  }
}

# Private Security Group: pvt-seg
resource "aws_security_group" "pvt_seg" {
  name        = "pvt-seg"
  description = "Allow inbound HTTP, HTTPS, SSH, and PostgreSQL only from public SG"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTP from public security group"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "HTTPS from public security group"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "SSH from public security group"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "PostgreSQL from public security group"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  egress {
    description     = "Egress restricted exclusively to public security group"
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.allow_tls.id]
  }

  tags = {
    Name = "pvt-seg"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = [aws_subnet.pub_sub_1.id, aws_subnet.pub_sub_2.id]
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = [aws_subnet.pvt_sub_1.id, aws_subnet.pvt_sub_2.id]
}

output "public_sg_id" {
  description = "ID of the allow_tls security group"
  value       = aws_security_group.allow_tls.id
}

output "private_sg_id" {
  description = "ID of the pvt-seg security group"
  value       = aws_security_group.pvt_seg.id
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region for the resources"
  default     = "us-east-1"
}

provider "aws" {
  region = variable "aws_region"
}

# -----------------------------------------------------------------------------
# DynamoDB Table
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "pets" {
  name           = "Pets"
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "PetType"
    type = "S"
  }

  global_secondary_index {
    name            = "PetType-index"
    hash_key        = "PetType"
    read_capacity   = 5
    write_capacity  = 5
    projection_type = "INCLUDE"
    non_key_attributes = [
      "PetName",
      "PetPrice"
    ]
  }

  tags = {
    Environment = "production"
    Application = "APIGW-DynamoDB-Serverless"
  }
}

# -----------------------------------------------------------------------------
# IAM Role for API Gateway to Access DynamoDB
# -----------------------------------------------------------------------------
resource "aws_iam_role" "apigw_dynamodb_role" {
  name = "apigw_dynamodb_direct_integration_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "apigw_dynamodb_policy" {
  name        = "apigw_dynamodb_access_policy"
  description = "Allows API Gateway to PutItem and Query the Pets DynamoDB table and indexes"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem",
          "dynamodb:Query"
        ]
        Resource = [
          aws_dynamodb_table.pets.arn,
          "${aws_dynamodb_table.pets.arn}/index/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "apigw_dynamodb_attach" {
  role       = aws_iam_role.apigw_dynamodb_role.name
  policy_arn = aws_iam_policy.apigw_dynamodb_policy.arn
}

# -----------------------------------------------------------------------------
# API Gateway CloudWatch Logging Account Configuration
# -----------------------------------------------------------------------------
resource "aws_iam_role" "apigw_cloudwatch_role" {
  name = "apigw_global_cloudwatch_logging_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "apigw_cloudwatch_attach" {
  role       = aws_iam_role.apigw_cloudwatch_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_api_gateway_account" "demo" {
  cloudwatch_role_arn = aws_iam_role.apigw_cloudwatch_role.arn
  depends_on          = [aws_iam_role_policy_attachment.apigw_cloudwatch_attach]
}

# -----------------------------------------------------------------------------
# API Gateway REST API
# -----------------------------------------------------------------------------
resource "aws_api_gateway_rest_api" "demo" {
  name        = "APIGW DynamoDB Serverless Pattern Demo"
  description = "Serverless direct API Gateway to DynamoDB integration pattern"

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

# Resource: /pets
resource "aws_api_gateway_resource" "pets" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  parent_id   = aws_api_gateway_rest_api.demo.root_resource_id
  path_part   = "pets"
}

# Resource: /pets/{PetType}
resource "aws_api_gateway_resource" "pet_type" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  parent_id   = aws_api_gateway_resource.pets.id
  path_part   = "{PetType}"
}

# -----------------------------------------------------------------------------
# Method: POST /pets (DynamoDB PutItem)
# -----------------------------------------------------------------------------
resource "aws_api_gateway_method" "post_pets" {
  rest_api_id      = aws_api_gateway_rest_api.demo.id
  resource_id      = aws_api_gateway_resource.pets.id
  http_method      = "POST"
  authorization    = "NONE"
  api_key_required = true
}

resource "aws_api_gateway_integration" "post_pets_integration" {
  rest_api_id             = aws_api_gateway_rest_api.demo.id
  resource_id             = aws_api_gateway_resource.pets.id
  http_method             = aws_api_gateway_method.post_pets.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:aws:apigateway:${var.aws_region}:dynamodb:action/PutItem"
  credentials             = aws_iam_role.apigw_dynamodb_role.arn

  request_templates = {
    "application/json" = <<EOF
{
    "TableName": "${aws_dynamodb_table.pets.name}",
    "Item": {
        "id": {
            "S": "$context.requestId"
        },
        "PetType": {
            "S": "$input.path('$.PetType')"
        },
        "PetName": {
            "S": "$input.path('$.PetName')"
        },
        "PetPrice": {
            "N": "$input.path('$.PetPrice')"
        },
        "PetBoolean": {
            "BOOL": true
        }
    }
}
EOF
  }
}

resource "aws_api_gateway_method_response" "post_pets_200" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_pets.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "post_pets_integration_response" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_pets.http_method
  status_code = aws_api_gateway_method_response.post_pets_200.status_code

  response_templates = {
    "application/json" = jsonencode({
      message = "Pet added successfully"
    })
  }

  depends_on = [
    aws_api_gateway_integration.post_pets_integration
  ]
}

# -----------------------------------------------------------------------------
# Method: GET /pets/{PetType} (DynamoDB Query)
# -----------------------------------------------------------------------------
resource "aws_api_gateway_method" "get_pets_by_type" {
  rest_api_id      = aws_api_gateway_rest_api.demo.id
  resource_id      = aws_api_gateway_resource.pet_type.id
  http_method      = "GET"
  authorization    = "NONE"
  api_key_required = true

  request_parameters = {
    "method.request.path.PetType" = true
  }
}

resource "aws_api_gateway_integration" "get_pets_by_type_integration" {
  rest_api_id             = aws_api_gateway_rest_api.demo.id
  resource_id             = aws_api_gateway_resource.pet_type.id
  http_method             = aws_api_gateway_method.get_pets_by_type.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = "arn:aws:apigateway:${var.aws_region}:dynamodb:action/Query"
  credentials             = aws_iam_role.apigw_dynamodb_role.arn

  request_templates = {
    "application/json" = <<EOF
{
    "TableName": "${aws_dynamodb_table.pets.name}",
    "IndexName": "PetType-index",
    "KeyConditionExpression": "PetType = :v1",
    "ExpressionAttributeValues": {
        ":v1": {
            "S": "$util.urlDecode($input.params('PetType'))"
        }
    }
}
EOF
  }
}

resource "aws_api_gateway_method_response" "get_pets_by_type_200" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.get_pets_by_type.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "get_pets_by_type_integration_response" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.get_pets_by_type.http_method
  status_code = aws_api_gateway_method_response.get_pets_by_type_200.status_code

  response_templates = {
    "application/json" = <<EOF
#set($inputRoot = $input.path('$'))
{
    "pets": [
        #foreach($elem in $inputRoot.Items) {
            "id": "$elem.id.S",
            "PetType": "$elem.PetType.S",
            "PetName": "$elem.PetName.S",
            "PetPrice": "$elem.PetPrice.N"
        }#if($foreach.hasNext),#end
        #end
    ]
}
EOF
  }

  depends_on = [
    aws_api_gateway_integration.get_pets_by_type_integration
  ]
}

# -----------------------------------------------------------------------------
# Deployment & Stage Configuration
# -----------------------------------------------------------------------------
resource "aws_api_gateway_deployment" "demo" {
  rest_api_id = aws_api_gateway_rest_api.demo.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.pets.id,
      aws_api_gateway_resource.pet_type.id,
      aws_api_gateway_method.post_pets.id,
      aws_api_gateway_integration.post_pets_integration.id,
      aws_api_gateway_method_response.post_pets_200.id,
      aws_api_gateway_integration_response.post_pets_integration_response.id,
      aws_api_gateway_method.get_pets_by_type.id,
      aws_api_gateway_integration.get_pets_by_type_integration.id,
      aws_api_gateway_method_response.get_pets_by_type_200.id,
      aws_api_gateway_integration_response.get_pets_by_type_integration_response.id,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration_response.post_pets_integration_response,
    aws_api_gateway_integration_response.get_pets_by_type_integration_response
  ]
}

# CloudWatch Log Group for API Gateway Access Logs
resource "aws_cloudwatch_log_group" "api_logs" {
  name              = "/aws/APIGW/terraform-${aws_api_gateway_rest_api.demo.id}"
  retention_in_days = 14
}

# CloudWatch Resource Policy allowing API Gateway Log Delivery
resource "aws_cloudwatch_log_resource_policy" "apigw_logging" {
  policy_name = "APIGWLoggingPolicy-${aws_api_gateway_rest_api.demo.id}"
  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.api_logs.arn}:*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = "${aws_api_gateway_rest_api.demo.execution_arn}/*"
          }
        }
      }
    ]
  })
}

resource "aws_api_gateway_stage" "v1" {
  deployment_id = aws_api_gateway_deployment.demo.id
  rest_api_id   = aws_api_gateway_rest_api.demo.id
  stage_name    = "v1"

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_logs.arn
    format          = "{\"requestId\":\"$context.requestId\",\"ip\":\"$context.identity.sourceIp\",\"caller\":\"$context.identity.caller\",\"user\":\"$context.identity.user\",\"requestTime\":\"$context.requestTime\",\"httpMethod\":\"$context.httpMethod\",\"resourcePath\":\"$context.resourcePath\",\"status\":\"$context.status\",\"protocol\":\"$context.protocol\",\"responseLength\":\"$context.responseLength\"}"
  }

  depends_on = [
    aws_api_gateway_account.demo,
    aws_cloudwatch_log_resource_policy.apigw_logging
  ]
}

resource "aws_api_gateway_method_settings" "settings" {
  rest_api_id = aws_api_gateway_rest_api.demo.id
  stage_name  = aws_api_gateway_stage.v1.stage_name
  method_path = "*/*"

  settings {
    metrics_enabled    = true
    logging_level      = "INFO"
    data_trace_enabled = true
  }
}

# -----------------------------------------------------------------------------
# API Key & Usage Plan
# -----------------------------------------------------------------------------
resource "aws_api_gateway_api_key" "demo" {
  name        = "apigw-dynamodb-terraform-api-key"
  description = "API Key for APIGW DynamoDB integration"
  enabled     = true
}

resource "aws_api_gateway_usage_plan" "demo" {
  name        = "apigw-dynamodb-terraform-usage-plan"
  description = "Usage plan with rate limit 100, burst limit 20, quota 1000/month"

  api_stages {
    api_id = aws_api_gateway_rest_api.demo.id
    stage  = aws_api_gateway_stage.v1.stage_name
  }

  quota_settings {
    limit  = 1000
    period = "MONTH"
  }

  throttle_settings {
    burst_limit = 20
    rate_limit  = 100
  }
}

resource "aws_api_gateway_usage_plan_key" "demo" {
  key_id        = aws_api_gateway_api_key.demo.id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.demo.id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "api_endpoint" {
  description = "Base invocation URL for stage v1"
  value       = aws_api_gateway_stage.v1.invoke_url
}

output "api_key_value" {
  description = "The generated API Key value"
  value       = aws_api_gateway_api_key.demo.value
  sensitive   = true
}

output "dynamodb_table_name" {
  description = "Name of the DynamoDB table"
  value       = aws_dynamodb_table.pets.name
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "The AWS region to deploy resources into."
  default     = "us-east-1"
}

variable "name" {
  type        = string
  description = "Prefix / naming identifier for all S3 buckets and related resources."
  default     = "sadcloud"
}

variable "bucket_acl" {
  type        = string
  description = "Canned ACL for the logging bucket."
  default     = "log-delivery-write"
}

variable "no_versioning" {
  type        = bool
  description = "If true, disables versioning on the primary S3 bucket."
  default     = false
}

variable "no_default_encryption" {
  type        = bool
  description = "If true, disables KMS default encryption on the primary S3 bucket."
  default     = false
}

variable "website_enabled" {
  type        = bool
  description = "If true, enables static website hosting with index.html on the primary S3 bucket."
  default     = false
}

variable "no_logging" {
  type        = bool
  description = "If true, skips the creation of the logging bucket and log delivery configuration."
  default     = false
}

variable "allow_cleartext" {
  type        = bool
  description = "If true, attaches a bucket policy denying cleartext (non-SSL) HTTP transport to the primary bucket."
  default     = false
}

variable "s3_getobject_only" {
  type        = bool
  description = "If true, creates an additional public read-only S3 bucket allowing public s3:GetObject."
  default     = false
}

variable "s3_public" {
  type        = bool
  description = "If true, creates an additional fully public S3 bucket allowing public s3:* actions."
  default     = false
}

# -----------------------------------------------------------------------------
# Current AWS Account Data Source
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Primary S3 Bucket & Encryption
# -----------------------------------------------------------------------------
resource "aws_kms_key" "primary" {
  count                   = var.no_default_encryption ? 0 : 1
  description             = "KMS CMK for primary S3 bucket encryption (${var.name})"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "Enable IAM User Permissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "primary" {
  count         = var.no_default_encryption ? 0 : 1
  name          = "alias/${var.name}-primary-key"
  target_key_id = aws_kms_key.primary[0].key_id
}

resource "aws_s3_bucket" "primary" {
  bucket_prefix = "${var.name}-"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "primary" {
  depends_on = [aws_s3_bucket_ownership_controls.primary]
  bucket     = aws_s3_bucket.primary.id
  acl        = "private"
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = var.no_versioning ? "Suspended" : "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  count  = var.no_default_encryption ? 0 : 1
  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_website_configuration" "primary" {
  count  = var.website_enabled ? 1 : 0
  bucket = aws_s3_bucket.primary.id

  index_document {
    suffix = "index.html"
  }
}

resource "aws_s3_bucket_policy" "primary_deny_insecure_transport" {
  count  = var.allow_cleartext ? 1 : 0
  bucket = aws_s3_bucket.primary.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Logging Bucket & Configuration
# -----------------------------------------------------------------------------
resource "aws_kms_key" "logging" {
  count                   = var.no_logging ? 0 : 1
  description             = "KMS CMK for logging S3 bucket encryption (${var.name})"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "Enable IAM User Permissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "logging" {
  count         = var.no_logging ? 0 : 1
  name          = "alias/${var.name}-logging-key"
  target_key_id = aws_kms_key.logging[0].key_id
}

resource "aws_s3_bucket" "logging" {
  count         = var.no_logging ? 0 : 1
  bucket_prefix = "${var.name}-logging-"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logging" {
  count      = var.no_logging ? 0 : 1
  depends_on = [aws_s3_bucket_ownership_controls.logging]
  bucket     = aws_s3_bucket.logging[0].id
  acl        = var.bucket_acl
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.logging[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "primary" {
  count         = var.no_logging ? 0 : 1
  bucket        = aws_s3_bucket.primary.id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = "log/"
}

# -----------------------------------------------------------------------------
# Secondary Bucket: Public Read-Only (s3:GetObject)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "getonly" {
  count         = var.s3_getobject_only ? 1 : 0
  bucket_prefix = "${var.name}-getonly-"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "getonly" {
  count  = var.s3_getobject_only ? 1 : 0
  bucket = aws_s3_bucket.getonly[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "getonly" {
  count  = var.s3_getobject_only ? 1 : 0
  bucket = aws_s3_bucket.getonly[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "getonly" {
  count      = var.s3_getobject_only ? 1 : 0
  depends_on = [aws_s3_bucket_public_access_block.getonly]
  bucket     = aws_s3_bucket.getonly[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadGetObject"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.getonly[0].arn}/*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Secondary Bucket: Public Read-Write (s3:*)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "public" {
  count         = var.s3_public ? 1 : 0
  bucket_prefix = "${var.name}-public-"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "public" {
  count  = var.s3_public ? 1 : 0
  bucket = aws_s3_bucket.public[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "public" {
  count  = var.s3_public ? 1 : 0
  bucket = aws_s3_bucket.public[0].id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "public" {
  count      = var.s3_public ? 1 : 0
  depends_on = [aws_s3_bucket_public_access_block.public]
  bucket     = aws_s3_bucket.public[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicAllActions"
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.public[0].arn,
          "${aws_s3_bucket.public[0].arn}/*"
        ]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "primary_bucket_id" {
  description = "The ID of the primary S3 bucket."
  value       = aws_s3_bucket.primary.id
}

output "primary_bucket_arn" {
  description = "The ARN of the primary S3 bucket."
  value       = aws_s3_bucket.primary.arn
}

output "logging_bucket_id" {
  description = "The ID of the logging bucket, if created."
  value       = var.no_logging ? null : aws_s3_bucket.logging[0].id
}

output "getonly_bucket_id" {
  description = "The ID of the public read-only bucket, if created."
  value       = var.s3_getobject_only ? aws_s3_bucket.getonly[0].id : null
}

output "public_bucket_id" {
  description = "The ID of the public read-write bucket, if created."
  value       = var.s3_public ? aws_s3_bucket.public[0].id : null
}

```terraform
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  description = "The AWS region where resources will be managed."
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# Fetch current AWS account and caller identity
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# ==============================================================================
# Trust Policies
# ==============================================================================

# DRS Agent Role Trust Policy
data "aws_iam_policy_document" "drs_agent_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["drs.amazonaws.com"]
    }
    actions = [
      "sts:AssumeRole",
      "sts:SetSourceIdentity"
    ]
    condition {
      test     = "StringEquals"
      variable = "sts:SourceIdentity"
      values   = ["s-*"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

# DRS Failback Role Trust Policy
data "aws_iam_policy_document" "drs_failback_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["drs.amazonaws.com"]
    }
    actions = [
      "sts:AssumeRole",
      "sts:SetSourceIdentity"
    ]
    condition {
      test     = "StringLike"
      variable = "sts:SourceIdentity"
      values   = ["i-*"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

# EC2 Service Roles Trust Policy
data "aws_iam_policy_document" "ec2_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# Initializer Role Trust Policy (allowing current caller identity)
data "aws_iam_policy_document" "initializer_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
    }
  }
}

# ==============================================================================
# IAM Service Roles (under /service-role/)
# ==============================================================================

resource "aws_iam_role" "agent_role" {
  name               = "AWSElasticDisasterRecoveryAgentRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.drs_agent_trust.json
  description        = "Used by AWS Elastic Disaster Recovery to authenticate agent installation and replication."
}

resource "aws_iam_role" "failback_role" {
  name               = "AWSElasticDisasterRecoveryFailbackRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.drs_failback_trust.json
  description        = "Used by AWS Elastic Disaster Recovery to manage failback client communication."
}

resource "aws_iam_role" "conversion_server_role" {
  name               = "AWSElasticDisasterRecoveryConversionServerRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json
  description        = "Used by AWS Elastic Disaster Recovery conversion instances."
}

resource "aws_iam_role" "recovery_instance_role" {
  name               = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json
  description        = "Used by AWS Elastic Disaster Recovery recovery instances."
}

resource "aws_iam_role" "replication_server_role" {
  name               = "AWSElasticDisasterRecoveryReplicationServerRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json
  description        = "Used by AWS Elastic Disaster Recovery replication servers."
}

resource "aws_iam_role" "recovery_instance_with_launch_actions_role" {
  name               = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
  path               = "/service-role/"
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json
  description        = "Used by AWS Elastic Disaster Recovery recovery instances with launch actions enabled."
}

# ==============================================================================
# Managed Policy Attachments for Service Roles
# ==============================================================================

resource "aws_iam_role_policy_attachment" "agent_policy_attachment" {
  role       = aws_iam_role.agent_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryAgentPolicy"
}

resource "aws_iam_role_policy_attachment" "failback_policy_attachment" {
  role       = aws_iam_role.failback_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryFailbackPolicy"
}

resource "aws_iam_role_policy_attachment" "conversion_policy_attachment" {
  role       = aws_iam_role.conversion_server_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryConversionServerPolicy"
}

resource "aws_iam_role_policy_attachment" "recovery_instance_policy_attachment" {
  role       = aws_iam_role.recovery_instance_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

resource "aws_iam_role_policy_attachment" "replication_server_policy_attachment" {
  role       = aws_iam_role.replication_server_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryReplicationServerPolicy"
}

resource "aws_iam_role_policy_attachment" "recovery_with_launch_actions_policy_attachment" {
  role       = aws_iam_role.recovery_instance_with_launch_actions_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

resource "aws_iam_role_policy_attachment" "recovery_with_launch_actions_ssm_attachment" {
  role       = aws_iam_role.recovery_instance_with_launch_actions_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# ==============================================================================
# DRS Initializer Role and Custom Policy
# ==============================================================================

data "aws_iam_policy_document" "initialize_policy_doc" {
  statement {
    sid    = "DRSServiceInitialization"
    effect = "Allow"
    actions = [
      "drs:InitializeService",
      "drs:GetServiceConfiguration",
      "drs:UpdateServiceConfiguration"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "IAMPassRoleForDRSAndEC2"
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/service-role/AWSElasticDisasterRecovery*"
    ]
    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values = [
        "ec2.amazonaws.com",
        "drs.amazonaws.com"
      ]
    }
  }

  statement {
    sid    = "IAMManageInstanceProfiles"
    effect = "Allow"
    actions = [
      "iam:CreateInstanceProfile",
      "iam:GetInstanceProfile",
      "iam:AddRoleToInstanceProfile",
      "iam:RemoveRoleFromInstanceProfile",
      "iam:DeleteInstanceProfile"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:instance-profile/AWSElasticDisasterRecovery*"
    ]
  }

  statement {
    sid    = "IAMCreateServiceLinkedRole"
    effect = "Allow"
    actions = [
      "iam:CreateServiceLinkedRole"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/drs.amazonaws.com/AWSServiceRoleForElasticDisasterRecovery"
    ]
    condition {
      test     = "StringLike"
      variable = "iam:AWSServiceName"
      values   = ["drs.amazonaws.com"]
    }
  }

  statement {
    sid    = "IAMAttachRestrictedManagedPolicies"
    effect = "Allow"
    actions = [
      "iam:AttachRolePolicy",
      "iam:DetachRolePolicy"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/service-role/AWSElasticDisasterRecovery*"
    ]
    condition {
      test     = "ArnEquals"
      variable = "iam:PolicyARN"
      values = [
        "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryAgentPolicy",
        "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryFailbackPolicy",
        "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryConversionServerPolicy",
        "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryRecoveryInstancePolicy",
        "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryReplicationServerPolicy",
        "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
      ]
    }
  }

  statement {
    sid    = "EC2Permissions"
    effect = "Allow"
    actions = [
      "ec2:*"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role" "initializer_role" {
  name               = "AWSElasticDisasterRecoveryInitializerRole"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.initializer_trust.json
  description        = "Initializer role for setting up and configuring AWS Elastic Disaster Recovery."
}

resource "aws_iam_role_policy" "initializer_policy" {
  name   = "InitializePolicy"
  role   = aws_iam_role.initializer_role.id
  policy = data.aws_iam_policy_document.initialize_policy_doc.json
}

# ==============================================================================
# Outputs
# ==============================================================================

output "agent_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery Agent Role"
  value       = aws_iam_role.agent_role.arn
}

output "failback_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery Failback Role"
  value       = aws_iam_role.failback_role.arn
}

output "conversion_server_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery Conversion Server Role"
  value       = aws_iam_role.conversion_server_role.arn
}

output "recovery_instance_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery Recovery Instance Role"
  value       = aws_iam_role.recovery_instance_role.arn
}

output "replication_server_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery Replication Server Role"
  value       = aws_iam_role.replication_server_role.arn
}

output "recovery_instance_with_launch_actions_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery Recovery Instance with Launch Actions Role"
  value       = aws_iam_role.recovery_instance_with_launch_actions_role.arn
}

output "initializer_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery Initializer Role"
  value       = aws_iam_role.initializer_role.arn
}
