terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "The AWS region to deploy resources into"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for the private subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "instance_count" {
  type        = number
  description = "Number of EC2 instances to launch"
  default     = 3
}

variable "instance_type" {
  type        = string
  description = "EC2 instance type"
  default     = "t2.micro"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# -----------------------------------------------------------------------------
# VPC and Subnets
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name      = "VPC_from_Terraform"
    Terraform = "true"
  }
}

resource "aws_subnet" "private" {
  count                   = length(var.subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name      = "Private-Subnet-${count.index + 1}"
    Terraform = "true"
  }
}

# -----------------------------------------------------------------------------
# Security Group
# -----------------------------------------------------------------------------
resource "aws_security_group" "allow_ssh_http_https" {
  name        = "allow_ssh_http_https"
  description = "Security group allowing SSH from VPC, HTTP and HTTPS from anywhere, and egress restricted to VPC"
  vpc_id      = aws_vpc.main.id

  # Inbound SSH strictly restricted to VPC CIDR
  ingress {
    description = "SSH from VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  # Inbound HTTP from everywhere
  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Inbound HTTPS from everywhere
  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Egress limited strictly to the VPC's CIDR block
  egress {
    description = "Outbound traffic restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name      = "Terraform_SG_HTTP_HTTPS_SSH"
    Terraform = "true"
  }
}

# -----------------------------------------------------------------------------
# EC2 Instances
# -----------------------------------------------------------------------------
resource "aws_instance" "app_instances" {
  count                  = var.instance_count
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = var.instance_type
  subnet_id              = aws_subnet.private[count.index % length(aws_subnet.private)].id
  vpc_security_group_ids = [aws_security_group.allow_ssh_http_https.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required" # IMDSv2 enforcement
  }

  root_block_device {
    volume_size           = 20
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true

    tags = {
      Name      = "Terraform_EBS_Volume1"
      Terraform = "true"
    }
  }

  tags = {
    Name      = "Terraform_Instance"
    Terraform = "true"
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "private_subnet_ids" {
  description = "List of IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "security_group_id" {
  description = "The ID of the security group"
  value       = aws_security_group.allow_ssh_http_https.id
}

output "instance_ids" {
  description = "List of EC2 instance IDs"
  value       = aws_instance.app_instances[*].id
}

output "instance_private_ips" {
  description = "List of private IP addresses assigned to the instances"
  value       = aws_instance.app_instances[*].private_ip
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region for the provider"
  default     = "us-east-1"
}

variable "resource_prefix" {
  type        = string
  description = "Prefix for IAM role and policy naming to prevent collisions"
  default     = "app"
}

# -----------------------------------------------------------------------------
# 1. ecsServiceRole
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "ecs_service_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs.amazonaws.com", "s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_service_role" {
  name               = "${var.resource_prefix}-ecsServiceRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_service_assume_role.json
}

data "aws_iam_policy_document" "ecs_task_role_policy" {
  statement {
    sid    = "ELBPolicies"
    effect = "Allow"
    actions = [
      "elasticloadbalancing:Describe*",
      "elasticloadbalancing:DeregisterInstancesFromLoadBalancer",
      "elasticloadbalancing:RegisterInstancesWithLoadBalancer",
      "elasticloadbalancing:RegisterTargets",
      "elasticloadbalancing:DeregisterTargets"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "EC2Policies"
    effect = "Allow"
    actions = [
      "ec2:Describe*",
      "ec2:AuthorizeSecurityGroupIngress"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SSMPolicies"
    effect = "Allow"
    actions = [
      "ssm:DescribeParameters",
      "ssm:GetParameters",
      "ssm:GetParameter",
      "ssm:GetParameterHistory"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SecretsManagerPolicies"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "KMSPolicies"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CodeDeployPolicies"
    effect = "Allow"
    actions = [
      "codedeploy:CreateDeployment",
      "codedeploy:GetDeployment",
      "codedeploy:GetDeploymentConfig",
      "codedeploy:RegisterApplicationRevision"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SNSPolicies"
    effect = "Allow"
    actions = [
      "sns:Publish"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchPolicies"
    effect = "Allow"
    actions = [
      "cloudwatch:DescribeAlarms",
      "cloudwatch:PutMetricAlarm",
      "cloudwatch:PutMetricData"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "LambdaPolicies"
    effect = "Allow"
    actions = [
      "lambda:InvokeFunction"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ecs_task_role_policy" {
  name   = "ecsTaskRolePolicy"
  role   = aws_iam_role.ecs_service_role.id
  policy = data.aws_iam_policy_document.ecs_task_role_policy.json
}

# -----------------------------------------------------------------------------
# 2. ecsExecTaskRole
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "ecs_tasks_and_s3_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com", "s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_exec_task_role" {
  name               = "${var.resource_prefix}-ecsExecTaskRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_and_s3_assume_role.json
}

data "aws_iam_policy_document" "ecs_exec_role_policy" {
  statement {
    sid    = "ECRContainerAccess"
    effect = "Allow"
    actions = [
      "ecr:GetAuthorizationToken",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ECSDescribe"
    effect = "Allow"
    actions = [
      "ecs:DescribeServices",
      "ecs:DescribeTasks"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:CreateLogGroup"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SecretsManagerAccess"
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "KMSAccess"
    effect = "Allow"
    actions = [
      "kms:Decrypt"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SSMAccess"
    effect = "Allow"
    actions = [
      "ssm:GetParameters",
      "ssm:GetParameter"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ecs_exec_role_policy" {
  name   = "ecsExecRolePolicy"
  role   = aws_iam_role.ecs_exec_task_role.id
  policy = data.aws_iam_policy_document.ecs_exec_role_policy.json
}

data "aws_iam_policy_document" "ecs_execution_additional" {
  statement {
    sid    = "ECSListAndDescribe"
    effect = "Allow"
    actions = [
      "ecs:ListServices",
      "ecs:DescribeServices"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3ObjectReadWrite"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ecs_execution_additional" {
  name   = "ecsExecution_additional"
  role   = aws_iam_role.ecs_exec_task_role.id
  policy = data.aws_iam_policy_document.ecs_execution_additional.json
}

# -----------------------------------------------------------------------------
# 3. ecsTaskRole
# -----------------------------------------------------------------------------
resource "aws_iam_role" "ecs_task_role" {
  name               = "${var.resource_prefix}-ecsTaskRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_and_s3_assume_role.json
}

data "aws_iam_policy_document" "ecs_task_role_additional" {
  statement {
    sid    = "ECSListAndDescribe"
    effect = "Allow"
    actions = [
      "ecs:ListServices",
      "ecs:DescribeServices"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3ObjectReadWrite"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ecs_task_role_additional" {
  name   = "ecsTaskRole_additional"
  role   = aws_iam_role.ecs_task_role.id
  policy = data.aws_iam_policy_document.ecs_task_role_additional.json
}

# -----------------------------------------------------------------------------
# 4. ecs_autoscale_role
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "ecs_autoscale_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["application-autoscaling.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_autoscale_role" {
  name               = "${var.resource_prefix}-ecs_autoscale_role"
  assume_role_policy = data.aws_iam_policy_document.ecs_autoscale_assume_role.json
}

data "aws_iam_policy_document" "ecs_autoscale_role_policy" {
  statement {
    sid    = "ECSDescribeAndUpdate"
    effect = "Allow"
    actions = [
      "ecs:DescribeServices",
      "ecs:UpdateService"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchAlarms"
    effect = "Allow"
    actions = [
      "cloudwatch:DescribeAlarms",
      "cloudwatch:PutMetricAlarm",
      "cloudwatch:DeleteAlarms"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ecs_autoscale_role_policy" {
  name   = "ecs_autoscale_role_policy"
  role   = aws_iam_role.ecs_autoscale_role.id
  policy = data.aws_iam_policy_document.ecs_autoscale_role_policy.json
}

# -----------------------------------------------------------------------------
# 5. ecs_codedeploy_role
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "ecs_codedeploy_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codedeploy.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_codedeploy_role" {
  name               = "${var.resource_prefix}-ecs_codedeploy_role"
  assume_role_policy = data.aws_iam_policy_document.ecs_codedeploy_assume_role.json
}

# Managed policy attachment
resource "aws_iam_role_policy_attachment" "ecs_codedeploy_role_managed" {
  role       = aws_iam_role.ecs_codedeploy_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRole"
}

# CodeDeploy inline policy for ECS tasks, ELB, Lambda, CloudWatch, SNS, S3
data "aws_iam_policy_document" "ecs_codedeploy_role_policy" {
  statement {
    sid    = "ECSTaskSetManagement"
    effect = "Allow"
    actions = [
      "ecs:CreateTaskSet",
      "ecs:DeleteTaskSet",
      "ecs:DescribeServices",
      "ecs:DescribeTaskSets",
      "ecs:UpdateServicePrimaryTaskSet"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ELBTargetGroupManagement"
    effect = "Allow"
    actions = [
      "elasticloadbalancing:DescribeTargetGroups",
      "elasticloadbalancing:DescribeListeners",
      "elasticloadbalancing:ModifyListener",
      "elasticloadbalancing:DescribeRules",
      "elasticloadbalancing:ModifyRule"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "LambdaLifecycleHooks"
    effect = "Allow"
    actions = [
      "lambda:InvokeFunction"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchMetricsAndAlarms"
    effect = "Allow"
    actions = [
      "cloudwatch:DescribeAlarms"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SNSNotificationPublish"
    effect = "Allow"
    actions = [
      "sns:Publish"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3ArtifactAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy" {
  name   = "ecs_codedeploy_role_policy"
  role   = aws_iam_role.ecs_codedeploy_role.id
  policy = data.aws_iam_policy_document.ecs_codedeploy_role_policy.json
}

# PassRole policy for ecsTaskRole
data "aws_iam_policy_document" "ecs_codedeploy_role_policy_task" {
  statement {
    sid    = "PassTaskRole"
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = [
      aws_iam_role.ecs_task_role.arn
    ]
  }
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task" {
  name   = "ecs_codedeploy_role_policy_task"
  role   = aws_iam_role.ecs_codedeploy_role.id
  policy = data.aws_iam_policy_document.ecs_codedeploy_role_policy_task.json
}

# PassRole policy for ecsExecTaskRole
data "aws_iam_policy_document" "ecs_codedeploy_role_policy_task_exec" {
  statement {
    sid    = "PassTaskExecRole"
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = [
      aws_iam_role.ecs_exec_task_role.arn
    ]
  }
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task_exec" {
  name   = "ecs_codedeploy_role_policy_task_exec"
  role   = aws_iam_role.ecs_codedeploy_role.id
  policy = data.aws_iam_policy_document.ecs_codedeploy_role_policy_task_exec.json
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "ecs_service_role_arn" {
  description = "ARN of ecsServiceRole"
  value       = aws_iam_role.ecs_service_role.arn
}

output "ecs_exec_task_role_arn" {
  description = "ARN of ecsExecTaskRole"
  value       = aws_iam_role.ecs_exec_task_role.arn
}

output "ecs_task_role_arn" {
  description = "ARN of ecsTaskRole"
  value       = aws_iam_role.ecs_task_role.arn
}

output "ecs_autoscale_role_arn" {
  description = "ARN of ecs_autoscale_role"
  value       = aws_iam_role.ecs_autoscale_role.arn
}

output "ecs_codedeploy_role_arn" {
  description = "ARN of ecs_codedeploy_role"
  value       = aws_iam_role.ecs_codedeploy_role.arn
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy the dual-VPC architecture into"
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# Fetch availability zones in the chosen region
data "aws_availability_zones" "available" {
  state = "available"
}

# ==============================================================================
# External VPC Configuration
# ==============================================================================

resource "aws_vpc" "external" {
  cidr_block           = "10.41.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = "prod"
  }
}

# Manage default security group of External VPC to have zero ingress/egress
resource "aws_default_security_group" "external_default" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name        = "Production External Default SG"
    purpose     = "Production External VPC"
    environment = "prod"
  }
}

# Internet Gateway for External VPC
resource "aws_internet_gateway" "external_gw" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name        = "External GW"
    purpose     = "Production External VPC"
    environment = "prod"
  }
}

# External VPC Subnets
locals {
  external_subnets = [
    { cidr = "10.41.0.0/24", name = "Subnet0-1a" },
    { cidr = "10.41.1.0/24", name = "Subnet1-1b" },
    { cidr = "10.41.2.0/24", name = "Subnet2-1c" },
    { cidr = "10.41.3.0/24", name = "Subnet3-1d" }
  ]
}

resource "aws_subnet" "external_subnets" {
  count             = 4
  vpc_id            = aws_vpc.external.id
  cidr_block        = local.external_subnets[count.index].cidr
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name        = local.external_subnets[count.index].name
    purpose     = "Production External VPC"
    environment = "prod"
  }
}

# Route table for External VPC
resource "aws_route_table" "external_rt" {
  vpc_id = aws_vpc.external.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.external_gw.id
  }

  tags = {
    Name        = "Production External Route Table"
    purpose     = "Production External VPC"
    environment = "prod"
  }
}

# Set custom route table as main route table association for External VPC
resource "aws_main_route_table_association" "external_main" {
  vpc_id         = aws_vpc.external.id
  route_table_id = aws_route_table.external_rt.id
}

# Explicit associations for External Subnets
resource "aws_route_table_association" "external_subnets_assoc" {
  count          = 4
  subnet_id      = aws_subnet.external_subnets[count.index].id
  route_table_id = aws_route_table.external_rt.id
}

# External VPC Default Network ACL
resource "aws_default_network_acl" "external_default_nacl" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id
  subnet_ids             = aws_subnet.external_subnets[*].id

  # Ingress: Rule 100 allow all traffic
  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  # Egress: Rule 100 allow ICMP
  egress {
    protocol   = "icmp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  # Egress: Rule 150 allow all traffic
  egress {
    protocol   = "-1"
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name        = "Production External Default NACL"
    purpose     = "Production External VPC"
    environment = "prod"
  }
}

# ==============================================================================
# Internal VPC Configuration
# ==============================================================================

resource "aws_vpc" "internal" {
  cidr_block       = "10.40.0.0/16"
  instance_tenancy = "default"

  tags = {
    Name        = "Production Internal"
    purpose     = "Production Internal VPC"
    environment = "prod"
  }
}

# Manage default security group of Internal VPC to have zero ingress/egress
resource "aws_default_security_group" "internal_default" {
  vpc_id = aws_vpc.internal.id

  tags = {
    Name        = "Production Internal Default SG"
    purpose     = "Production Internal VPC"
    environment = "prod"
  }
}

# Internal VPC Subnets
locals {
  internal_subnets = [
    { cidr = "10.40.0.0/24", name = "Subnet0-1a" },
    { cidr = "10.40.1.0/24", name = "Subnet1-1b" },
    { cidr = "10.40.2.0/24", name = "Subnet2-1c" },
    { cidr = "10.40.3.0/24", name = "Subnet3-1d" }
  ]
}

resource "aws_subnet" "internal_subnets" {
  count             = 4
  vpc_id            = aws_vpc.internal.id
  cidr_block        = local.internal_subnets[count.index].cidr
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name        = local.internal_subnets[count.index].name
    purpose     = "Production Internal VPC"
    environment = "prod"
  }
}

# Internal VPC Default Network ACL
resource "aws_default_network_acl" "internal_default_nacl" {
  default_network_acl_id = aws_vpc.internal.default_network_acl_id
  subnet_ids             = aws_subnet.internal_subnets[*].id

  # Ingress: Rule 100 allow ICMP
  ingress {
    protocol   = "icmp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  # Egress: Rule 100 allow ICMP
  egress {
    protocol   = "icmp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  # Egress: Rule 150 allow all traffic
  egress {
    protocol   = "-1"
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name        = "Production Internal Default NACL"
    purpose     = "Production Internal VPC"
    environment = "prod"
  }
}

# ==============================================================================
# Outputs
# ==============================================================================

output "external_vpc_id" {
  description = "The ID of the External VPC"
  value       = aws_vpc.external.id
}

output "external_subnet_ids" {
  description = "The IDs of the External subnets"
  value       = aws_subnet.external_subnets[*].id
}

output "internal_vpc_id" {
  description = "The ID of the Internal VPC"
  value       = aws_vpc.internal.id
}

output "internal_subnet_ids" {
  description = "The IDs of the Internal subnets"
  value       = aws_subnet.internal_subnets[*].id
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# --- Variables ---
variable "prefix" {
  type        = string
  description = "Prefix for all resources"
  default     = "n8n"
}

variable "certificate_arn" {
  type        = string
  description = "Optional custom ACM certificate ARN. If null, a self-signed certificate is created."
  default     = null
}

variable "url" {
  type        = string
  description = "Optional custom URL override for WEBHOOK_URL"
  default     = null
}

variable "desired_count" {
  type        = number
  description = "Desired number of ECS tasks"
  default     = 1
}

variable "container_image" {
  type        = string
  description = "Docker image for n8n"
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  type        = string
  description = "Fargate capacity provider type (e.g., FARGATE or FARGATE_SPOT)"
  default     = "FARGATE_SPOT"
}

# --- Data Sources ---
data "aws_availability_zones" "available" {
  state = "available"
}

# --- VPC & Networking ---
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${var.prefix}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.prefix}-igw"
  }
}

locals {
  private_cidrs = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  public_cidrs  = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]
}

resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.prefix}-private-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.prefix}-public-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# --- Security Groups ---
resource "aws_security_group" "alb" {
  name        = "${var.prefix}-alb-sg"
  description = "ALB security group allowing HTTP/HTTPS in, restricted out"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP inbound"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS inbound"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.prefix}-alb-sg"
  }
}

resource "aws_security_group" "ecs" {
  name        = "${var.prefix}-ecs-sg"
  description = "ECS Task security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Inbound port 5678 from ALB SG"
    from_port       = 5678
    to_port         = 5678
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.prefix}-ecs-sg"
  }
}

resource "aws_security_group" "efs" {
  name        = "${var.prefix}-efs-sg"
  description = "EFS security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS inbound from VPC CIDR"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.prefix}-efs-sg"
  }
}

# --- EFS Storage ---
resource "aws_efs_file_system" "main" {
  creation_token = "${var.prefix}-efs"
  encrypted      = true

  tags = {
    Name = "${var.prefix}-efs"
  }
}

resource "aws_efs_mount_target" "private" {
  count           = 3
  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_efs_access_point" "main" {
  file_system_id = aws_efs_file_system.main.id

  posix_user {
    gid = 1000
    uid = 1000
  }

  root_directory {
    path = "/n8n"
    creation_info {
      owner_gid   = 1000
      owner_uid   = 1000
      permissions = "777"
    }
  }

  tags = {
    Name = "${var.prefix}-efs-ap"
  }
}

# --- Self-Signed Certificate & ACM ---
resource "tls_private_key" "self_signed" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  private_key_pem = tls_private_key.self_signed.private_key_pem

  subject {
    common_name  = "n8n.internal"
    organization = "n8n"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth"
  ]
}

resource "aws_acm_certificate" "self_signed" {
  count            = var.certificate_arn == null ? 1 : 0
  private_key      = tls_private_key.self_signed.private_key_pem
  certificate_body = tls_self_signed_cert.self_signed.cert_pem

  tags = {
    Name = "${var.prefix}-self-signed-cert"
  }
}

locals {
  effective_certificate_arn = var.certificate_arn != null ? var.certificate_arn : aws_acm_certificate.self_signed[0].arn
}

# --- Application Load Balancer ---
resource "aws_lb" "main" {
  name                       = "${var.prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = "${var.prefix}-alb"
  }
}

resource "aws_lb_target_group" "main" {
  name                 = "${var.prefix}-tg"
  port                 = 80
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  target_type          = "ip"
  deregistration_delay = 30

  health_check {
    path                = "/healthz"
    matcher             = "200"
    interval            = 30
    timeout             = 3
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "${var.prefix}-tg"
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = local.effective_certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

# --- CloudWatch Logs ---
resource "aws_cloudwatch_log_group" "n8n" {
  name              = "${var.prefix}-logs"
  retention_in_days = 1

  tags = {
    Name = "${var.prefix}-logs"
  }
}

# --- IAM Roles ---
data "aws_iam_policy_document" "ecs_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "cw_logs_policy" {
  statement {
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams"
    ]
    resources = [
      "${aws_cloudwatch_log_group.n8n.arn}:*"
    ]
  }
}

resource "aws_iam_role" "execution_role" {
  name               = "${var.prefix}-execution-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_assume_role.json

  inline_policy {
    name   = "CloudWatchLogsPolicy"
    policy = data.aws_iam_policy_document.cw_logs_policy.json
  }

  tags = {
    Name = "${var.prefix}-execution-role"
  }
}

resource "aws_iam_role" "task_role" {
  name               = "${var.prefix}-task-role"
  assume_role_policy = data.aws_iam_policy_document.ecs_assume_role.json

  inline_policy {
    name   = "CloudWatchLogsPolicy"
    policy = data.aws_iam_policy_document.cw_logs_policy.json
  }

  tags = {
    Name = "${var.prefix}-task-role"
  }
}

# --- ECS Cluster & Capacity Provider ---
resource "aws_ecs_cluster" "main" {
  name = "${var.prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "disabled"
  }

  tags = {
    Name = "${var.prefix}-cluster"
  }
}

resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name       = aws_ecs_cluster.main.name
  capacity_providers = [var.fargate_type]

  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

# --- ECS Task Definition & Service ---
locals {
  webhook_url = var.url != null ? var.url : "https://${aws_lb.main.dns_name}"
}

resource "aws_ecs_task_definition" "main" {
  family                   = "${var.prefix}-task"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.execution_role.arn
  task_role_arn            = aws_iam_role.task_role.arn

  volume {
    name = "efs-storage"
    efs_volume_configuration {
      file_system_id          = aws_efs_file_system.main.id
      transit_encryption      = "ENABLED"
      authorization_config {
        access_point_id = aws_efs_access_point.main.id
        iam             = "ENABLED"
      }
    }
  }

  container_definitions = jsonencode([
    {
      name      = "n8n"
      image     = var.container_image
      essential = true
      portMappings = [
        {
          containerPort = 5678
          hostPort      = 5678
          protocol      = "tcp"
        }
      ]
      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = local.webhook_url
        }
      ]
      mountPoints = [
        {
          sourceVolume  = "efs-storage"
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.n8n.name
          "awslogs-region"        = "us-east-1"
          "awslogs-stream-prefix" = "ecs"
        }
      }
    }
  ])

  tags = {
    Name = "${var.prefix}-task-definition"
  }
}

resource "aws_ecs_service" "main" {
  name            = "${var.prefix}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.main.arn
  desired_count   = var.desired_count

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.main.arn
    container_name   = "n8n"
    container_port   = 5678
  }

  depends_on = [
    aws_lb_listener.https,
    aws_efs_mount_target.private
  ]

  tags = {
    Name = "${var.prefix}-service"
  }
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region for deployment"
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# Fetch available availability zones in the region
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC Configuration
resource "aws_vpc" "main" {
  cidr_block           = "10.32.0.0/20"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "lambda-rds-dev"
  }
}

# Manage Default Security Group (Empty rules)
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "lambda-rds-dev-default-sg"
  }
}

# Manage Default Network ACL (Allow all ingress/egress)
resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "lambda-rds-dev-default-nacl"
  }
}

# Subnets Configuration
resource "aws_subnet" "db_subnet_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.0.0/28"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-db-subnet-1"
  }
}

resource "aws_subnet" "lambda_subnet" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-dev-lambda-subnet"
  }
}

resource "aws_subnet" "bastion_subnet" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.15.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-bastion-host-subnet"
  }
}

resource "aws_subnet" "db_subnet_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.0.16/28"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-db-subnet-2"
  }
}

# Internet Gateway & Public Routing for Bastion Subnet
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "lambda-rds-dev-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "lambda-rds-public-subnet"
  }
}

resource "aws_route_table_association" "bastion" {
  subnet_id      = aws_subnet.bastion_subnet.id
  route_table_id = aws_route_table.public.id
}

# Security Groups
resource "aws_security_group" "postgres_db" {
  name        = "lambda-rds-dev-postgres-db"
  description = "Security group for RDS PostgreSQL DB"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow egress strictly within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "lambda-rds-dev-postgres-db"
  }
}

resource "aws_security_group" "lambda" {
  name        = "lambda-rds-dev-lambda-functions"
  description = "Security group for Lambda functions"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow egress strictly within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "lambda-rds-dev-lambda-functions"
  }
}

resource "aws_security_group" "bastion" {
  name        = "lambda-rds-dev-bastion-host"
  description = "Security group for Bastion Host"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "lambda-rds-dev-bastion-host"
  }
}

# Ingress Rules for PostgreSQL Security Group
resource "aws_security_group_rule" "postgres_ingress_bastion" {
  type                     = "ingress"
  description              = "PostgreSQL access from Bastion SG"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  security_group_id        = aws_security_group.postgres_db.id
  source_security_group_id = aws_security_group.bastion.id
}

resource "aws_security_group_rule" "postgres_ingress_lambda" {
  type                     = "ingress"
  description              = "PostgreSQL access from Lambda SG"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  security_group_id        = aws_security_group.postgres_db.id
  source_security_group_id = aws_security_group.lambda.id
}

# Egress Rule for Bastion Security Group (strictly to PostgreSQL SG)
resource "aws_security_group_rule" "bastion_egress_postgres" {
  type                     = "egress"
  description              = "Egress restricted exclusively to PostgreSQL DB SG"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  security_group_id        = aws_security_group.bastion.id
  source_security_group_id = aws_security_group.postgres_db.id
}

# Outputs
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "db_subnet_ids" {
  description = "Database subnet IDs"
  value       = [aws_subnet.db_subnet_1.id, aws_subnet.db_subnet_2.id]
}

output "lambda_subnet_id" {
  description = "Lambda subnet ID"
  value       = aws_subnet.lambda_subnet.id
}

output "bastion_subnet_id" {
  description = "Bastion host subnet ID"
  value       = aws_subnet.bastion_subnet.id
}

output "postgres_security_group_id" {
  description = "PostgreSQL DB Security Group ID"
  value       = aws_security_group.postgres_db.id
}

output "lambda_security_group_id" {
  description = "Lambda Functions Security Group ID"
  value       = aws_security_group.lambda.id
}

output "bastion_security_group_id" {
  description = "Bastion Host Security Group ID"
  value       = aws_security_group.bastion.id
}
```

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources"
  default     = "us-east-1"
}

variable "admin_cidr" {
  type        = string
  description = "Admin CIDR block for bastion host SSH access"
  default     = "203.0.113.0/24"
}

provider "aws" {
  region = variable.aws_region
}

# Data source for Availability Zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Common tags
locals {
  common_tags = {
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
  vpc_cidr = "10.255.0.0/16"
}

# ------------------------------------------------------------------------------
# VPC and Subnets
# ------------------------------------------------------------------------------
resource "aws_vpc" "quasar" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "Quasar"
  })
}

resource "aws_subnet" "rds_1a" {
  vpc_id            = aws_vpc.quasar.id
  cidr_block        = "10.255.100.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1A"
  })
}

resource "aws_subnet" "rds_1e" {
  vpc_id            = aws_vpc.quasar.id
  cidr_block        = "10.255.101.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1E"
  })
}

# ------------------------------------------------------------------------------
# Security Groups
# ------------------------------------------------------------------------------

# 1. Bastion Security Group
resource "aws_security_group" "bastion" {
  name        = "Quasar-Bastion"
  description = "Security group for Quasar Bastion host"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "SSH from admin network"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [variable.admin_cidr]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Bastion"
  })
}

# 2. HA-Proxy Security Group
resource "aws_security_group" "ha_proxy" {
  name        = "Quasar-HA-Proxy"
  description = "Security group for Quasar HA-Proxy load balancing"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "SSH from Bastion"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-HA-Proxy"
  })
}

# 3. Jenkins Security Group
resource "aws_security_group" "jenkins" {
  name        = "Quasar-Jenkins"
  description = "Security group for Quasar Jenkins automation"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description     = "SSH from Bastion"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "HTTP from HA-Proxy"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.ha_proxy.id]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Jenkins"
  })
}

# 4. ETL Security Group
resource "aws_security_group" "etl" {
  name        = "Quasar-ETL"
  description = "Security group for Quasar ETL compute nodes"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description     = "SSH from Bastion"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "SSH from Jenkins"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.jenkins.id]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-ETL"
  })
}

# 5. PostgreSQL Security Group
resource "aws_security_group" "postgresql" {
  name        = "Quasar-PostgreSQL"
  description = "Security group for Quasar PostgreSQL RDS database"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "PostgreSQL from anywhere"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "PostgreSQL explicitly from ETL"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.etl.id]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-PostgreSQL"
  })
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "vpc_id" {
  description = "ID of the Quasar VPC"
  value       = aws_vpc.quasar.id
}

output "database_subnet_ids" {
  description = "Subnet IDs created for Quasar RDS"
  value       = [aws_subnet.rds_1a.id, aws_subnet.rds_1e.id]
}

output "security_group_ids" {
  description = "Map of created security group IDs"
  value = {
    bastion    = aws_security_group.bastion.id
    ha_proxy   = aws_security_group.ha_proxy.id
    jenkins    = aws_security_group.jenkins.id
    etl        = aws_security_group.etl.id
    postgresql = aws_security_group.postgresql.id
  }
}
```

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region to deploy resources in"
  type        = string
  default     = "us-east-1"
}

variable "create" {
  description = "Whether to create the SQS queue and associated resources"
  type        = bool
  default     = true
}

variable "name" {
  description = "The name of the SQS queue (stripped of .fifo if present)"
  type        = string
  default     = "app-messages"
}

variable "use_name_prefix" {
  description = "Determines whether to use `name` as a prefix for the queue name"
  type        = bool
  default     = false
}

variable "fifo_queue" {
  description = "Boolean designating a FIFO queue"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues"
  type        = bool
  default     = null
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at message group or queue level ('messageGroup' or 'queue')"
  type        = string
  default     = null
}

variable "fifo_throughput_limit" {
  description = "Specifies whether the FIFO queue throughput quota applies to the entire queue or per message group ('perQueue' or 'perMessageGroupId')"
  type        = string
  default     = null
}

variable "delay_seconds" {
  description = "The time in seconds that the delivery of all messages in the queue will be delayed"
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "The limit of how many bytes a message can contain before Amazon SQS rejects it"
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "The number of seconds Amazon SQS retains a message"
  type        = number
  default     = 345600
}

variable "receive_wait_time_seconds" {
  description = "The time for which a ReceiveMessage call will wait for a message to arrive (long polling) before returning"
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "The visibility timeout for the queue in seconds"
  type        = number
  default     = 30
}

variable "sqs_managed_sse_enabled" {
  description = "Boolean to enable server-side encryption (SSE) of message content with SQS-owned encryption keys"
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SQS or a custom CMK"
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "The length of time, in seconds, for which Amazon SQS can reuse a data key to encrypt or decrypt messages"
  type        = number
  default     = 300
}

# Queue Policies
variable "create_queue_policy" {
  description = "Whether to create a separate queue policy resource for the main queue"
  type        = bool
  default     = false
}

variable "queue_policy" {
  description = "The JSON policy document to attach to the main queue"
  type        = string
  default     = null
}

# DLQ Settings
variable "create_dlq" {
  description = "Whether to create a dead-letter queue (DLQ)"
  type        = bool
  default     = false
}

variable "dlq_name" {
  description = "Optional custom name for the DLQ. If not set, appends dlq_name_suffix to `name`"
  type        = string
  default     = null
}

variable "dlq_name_suffix" {
  description = "Suffix to append to queue name when generating the DLQ name"
  type        = string
  default     = "-dlq"
}

variable "max_receive_count" {
  description = "The number of times a message is delivered to the source queue before being sent to the DLQ"
  type        = number
  default     = 5
}

variable "dlq_delay_seconds" {
  description = "The time in seconds that delivery of messages in the DLQ will be delayed"
  type        = number
  default     = null
}

variable "dlq_message_retention_seconds" {
  description = "The number of seconds Amazon SQS retains a message in the DLQ"
  type        = number
  default     = 1209600 # 14 days
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to attach a redrive allow policy to the DLQ restricting redrive permissions"
  type        = bool
  default     = true
}

variable "create_dlq_queue_policy" {
  description = "Whether to create a separate queue policy resource for the DLQ"
  type        = bool
  default     = false
}

variable "dlq_queue_policy" {
  description = "The JSON policy document to attach to the DLQ"
  type        = string
  default     = null
}

variable "tags" {
  description = "A mapping of tags to assign to all resources"
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------------------------------------------------
# LOCALS
# ---------------------------------------------------------------------------------------------------------------------

locals {
  # Clean name stripped of any provided .fifo suffix
  clean_name = trimsuffix(var.name, ".fifo")

  # Main Queue Naming
  queue_name        = !var.use_name_prefix ? (var.fifo_queue ? "${local.clean_name}.fifo" : local.clean_name) : null
  queue_name_prefix = var.use_name_prefix ? (var.fifo_queue ? "${local.clean_name}-" : "${local.clean_name}-") : null

  # DLQ Naming
  raw_dlq_name   = var.dlq_name != null ? trimsuffix(var.dlq_name, ".fifo") : "${local.clean_name}${var.dlq_name_suffix}"
  dlq_name        = !var.use_name_prefix ? (var.fifo_queue ? "${local.raw_dlq_name}.fifo" : local.raw_dlq_name) : null
  dlq_name_prefix = var.use_name_prefix ? (var.fifo_queue ? "${local.raw_dlq_name}-" : "${local.raw_dlq_name}-") : null

  # Encryption evaluation: If KMS key is supplied, disable SQS managed SSE
  sqs_managed_sse = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : null
}

# ---------------------------------------------------------------------------------------------------------------------
# DEAD-LETTER QUEUE (DLQ)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name        = local.dlq_name
  name_prefix = local.dlq_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  delay_seconds              = var.dlq_delay_seconds != null ? var.dlq_delay_seconds : var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.dlq_message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  sqs_managed_sse_enabled           = local.sqs_managed_sse
  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null

  redrive_allow_policy = var.create_dlq_redrive_allow_policy ? jsonencode({
    redrivePermission = "byQueue",
    sourceQueueArns   = [aws_sqs_queue.this[0].arn]
  }) : null

  tags = var.tags
}

resource "aws_sqs_queue_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_queue_policy && var.dlq_queue_policy != null ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url
  policy    = var.dlq_queue_policy
}

# ---------------------------------------------------------------------------------------------------------------------
# PRIMARY SQS QUEUE
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_sqs_queue" "this" {
  count = var.create ? 1 : 0

  name        = local.queue_name
  name_prefix = local.queue_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  sqs_managed_sse_enabled           = local.sqs_managed_sse
  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null

  redrive_policy = var.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  }) : null

  tags = var.tags
}

resource "aws_sqs_queue_policy" "this" {
  count = var.create && var.create_queue_policy && var.queue_policy != null ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  policy    = var.queue_policy
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "queue_id" {
  description = "The URL/ID of the created SQS queue"
  value       = try(aws_sqs_queue.this[0].id, null)
}

output "queue_arn" {
  description = "The ARN of the created SQS queue"
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_url" {
  description = "The URL of the created SQS queue"
  value       = try(aws_sqs_queue.this[0].url, null)
}

output "queue_name" {
  description = "The name of the created SQS queue"
  value       = try(aws_sqs_queue.this[0].name, null)
}

output "dlq_id" {
  description = "The URL/ID of the created Dead-Letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].id, null)
}

output "dlq_arn" {
  description = "The ARN of the created Dead-Letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dlq_url" {
  description = "The URL of the created Dead-Letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].url, null)
}

output "dlq_name" {
  description = "The name of the created Dead-Letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].name, null)
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# --------------------------------------------------------------------------------------------------
# Input Variables
# --------------------------------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region for resources."
  default     = "us-east-1"
}

variable "create" {
  type        = bool
  description = "Master switch to create module resources."
  default     = true
}

variable "function_name" {
  type        = string
  description = "Name of the target Lambda function to deploy."
  default     = "my-sample-lambda"
}

variable "alias_name" {
  type        = string
  description = "Name of the Lambda alias associated with traffic routing."
  default     = "live"
}

variable "current_version" {
  type        = string
  description = "The current version of the Lambda function."
  default     = "1"
}

variable "target_version" {
  type        = string
  description = "The target version of the Lambda function to deploy."
  default     = "2"
}

variable "before_allow_traffic_hook_arn" {
  type        = string
  description = "ARN of the Lambda function invoked before traffic shifting begins."
  default     = ""
}

variable "after_allow_traffic_hook_arn" {
  type        = string
  description = "ARN of the Lambda function invoked after traffic shifting ends."
  default     = ""
}

# CodeDeploy Application Controls
variable "create_app" {
  type        = bool
  description = "Whether to create a new CodeDeploy application."
  default     = false
}

variable "use_existing_app" {
  type        = bool
  description = "Whether to reference an existing CodeDeploy application."
  default     = false
}

variable "app_name" {
  type        = string
  description = "Name of the CodeDeploy application."
  default     = "my-lambda-codedeploy-app"
}

# CodeDeploy Deployment Group Controls
variable "create_deployment_group" {
  type        = bool
  description = "Whether to create a new CodeDeploy deployment group."
  default     = false
}

variable "use_existing_deployment_group" {
  type        = bool
  description = "Whether to reference an existing deployment group."
  default     = false
}

variable "deployment_group_name" {
  type        = string
  description = "Name of the CodeDeploy deployment group."
  default     = "my-lambda-deployment-group"
}

variable "deployment_config_name" {
  type        = string
  description = "Deployment configuration for traffic shifting."
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "auto_rollback_enabled" {
  type        = bool
  description = "Whether automatic rollback is enabled."
  default     = true
}

variable "auto_rollback_events" {
  type        = list(string)
  description = "The event types that trigger a deployment rollback."
  default     = ["DEPLOYMENT_STOP_ON_ALARM", "DEPLOYMENT_FAILURE"]
}

variable "alarm_names" {
  type        = list(string)
  description = "List of CloudWatch alarm names to monitor during deployment."
  default     = []
}

variable "trigger_configurations" {
  type = list(object({
    trigger_events     = list(string)
    trigger_name       = string
    trigger_target_arn = string
  }))
  description = "Notification triggers for deployment lifecycle events."
  default     = []
}

# IAM Role Controls
variable "create_codedeploy_role" {
  type        = bool
  description = "Whether to create the CodeDeploy service role."
  default     = true
}

variable "custom_codedeploy_role_arn" {
  type        = string
  description = "Existing IAM role ARN for CodeDeploy if create_codedeploy_role is false."
  default     = ""
}

variable "codedeploy_principals" {
  type        = list(string)
  description = "Service principals for CodeDeploy role trust policy."
  default     = ["codedeploy.amazonaws.com"]
}

variable "attach_hooks_policy" {
  type        = bool
  description = "Whether to attach inline policy allowing invocation of lifecycle hook Lambdas."
  default     = true
}

variable "attach_triggers_policy" {
  type        = bool
  description = "Whether to attach inline policy granting sns:Publish for trigger targets."
  default     = false
}

# Deployment Automation Controls
variable "create_deployment" {
  type        = bool
  description = "Whether to generate the deployment AppSpec JSON and execution script."
  default     = false
}

variable "aws_cli_command" {
  type        = string
  description = "Path or binary name for AWS CLI."
  default     = "aws"
}

variable "get_deployment_sleep_timer" {
  type        = number
  description = "Polling interval in seconds for deployment status checking."
  default     = 5
}

variable "save_deploy_script" {
  type        = bool
  description = "Whether to save the generated deployment script to the local filesystem."
  default     = false
}

variable "deploy_script_file" {
  type        = string
  description = "Local file path where the generated script will be saved."
  default     = "./deploy.sh"
}

variable "run_deployment" {
  type        = bool
  description = "Whether to trigger the deployment script via a null_resource provisioner."
  default     = false
}

variable "force_deploy" {
  type        = bool
  description = "Whether to force deployment execution on every terraform apply."
  default     = false
}

# --------------------------------------------------------------------------------------------------
# CodeDeploy IAM Role and Policies
# --------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "assume_role" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = var.codedeploy_principals
    }
  }
}

resource "aws_iam_role" "codedeploy" {
  count              = var.create && var.create_codedeploy_role ? 1 : 0
  name_prefix        = "CodeDeployLambdaServiceRole-"
  assume_role_policy = data.aws_iam_policy_document.assume_role[0].json

  tags = {
    ManagedBy = "Terraform"
  }
}

resource "aws_iam_role_policy_attachment" "codedeploy_lambda_managed" {
  count      = var.create && var.create_codedeploy_role ? 1 : 0
  role       = aws_iam_role.codedeploy[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRoleForLambda"
}

# Hooks invocation policy
locals {
  lifecycle_hook_arns = compact([
    var.before_allow_traffic_hook_arn,
    var.after_allow_traffic_hook_arn
  ])
}

data "aws_iam_policy_document" "hooks" {
  count = var.create && var.create_codedeploy_role && var.attach_hooks_policy && length(local.lifecycle_hook_arns) > 0 ? 1 : 0

  statement {
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = local.lifecycle_hook_arns
  }
}

resource "aws_iam_role_policy" "hooks" {
  count  = var.create && var.create_codedeploy_role && var.attach_hooks_policy && length(local.lifecycle_hook_arns) > 0 ? 1 : 0
  name   = "CodeDeployHookLambdaInvokePolicy"
  role   = aws_iam_role.codedeploy[0].name
  policy = data.aws_iam_policy_document.hooks[0].json
}

# Triggers SNS policy
data "aws_iam_policy_document" "triggers" {
  count = var.create && var.create_codedeploy_role && var.attach_triggers_policy && length(var.trigger_configurations) > 0 ? 1 : 0

  statement {
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [for trigger in var.trigger_configurations : trigger.trigger_target_arn]
  }
}

resource "aws_iam_role_policy" "triggers" {
  count  = var.create && var.create_codedeploy_role && var.attach_triggers_policy && length(var.trigger_configurations) > 0 ? 1 : 0
  name   = "CodeDeploySNSTriggerPolicy"
  role   = aws_iam_role.codedeploy[0].name
  policy = data.aws_iam_policy_document.triggers[0].json
}

# --------------------------------------------------------------------------------------------------
# CodeDeploy Application and Deployment Group
# --------------------------------------------------------------------------------------------------
resource "aws_codedeploy_app" "this" {
  count            = var.create && var.create_app && !var.use_existing_app ? 1 : 0
  name             = var.app_name
  compute_platform = "Lambda"

  tags = {
    ManagedBy = "Terraform"
  }
}

locals {
  app_name = var.create_app && !var.use_existing_app ? (
    length(aws_codedeploy_app.this) > 0 ? aws_codedeploy_app.this[0].name : var.app_name
  ) : var.app_name

  codedeploy_role_arn = var.create_codedeploy_role ? (
    length(aws_iam_role.codedeploy) > 0 ? aws_iam_role.codedeploy[0].arn : ""
  ) : var.custom_codedeploy_role_arn
}

resource "aws_codedeploy_deployment_group" "this" {
  count                  = var.create && var.create_deployment_group && !var.use_existing_deployment_group ? 1 : 0
  app_name               = local.app_name
  deployment_group_name  = var.deployment_group_name
  service_role_arn       = local.codedeploy_role_arn
  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  auto_rollback_configuration {
    enabled = var.auto_rollback_enabled
    events  = var.auto_rollback_events
  }

  dynamic "alarm_configuration" {
    for_each = length(var.alarm_names) > 0 ? [1] : []
    content {
      alarms  = var.alarm_names
      enabled = true
    }
  }

  dynamic "trigger_configuration" {
    for_each = var.trigger_configurations
    content {
      trigger_events     = trigger_configuration.value.trigger_events
      trigger_name       = trigger_configuration.value.trigger_name
      trigger_target_arn = trigger_configuration.value.trigger_target_arn
    }
  }

  tags = {
    ManagedBy = "Terraform"
  }
}

locals {
  deployment_group_name = var.create_deployment_group && !var.use_existing_deployment_group ? (
    length(aws_codedeploy_deployment_group.this) > 0 ? aws_codedeploy_deployment_group.this[0].deployment_group_name : var.deployment_group_name
  ) : var.deployment_group_name
}

# --------------------------------------------------------------------------------------------------
# AppSpec Construction and CLI Script Automation
# --------------------------------------------------------------------------------------------------
locals {
  hooks_map = merge(
    var.before_allow_traffic_hook_arn != "" ? { "BeforeAllowTraffic" = var.before_allow_traffic_hook_arn } : {},
    var.after_allow_traffic_hook_arn != "" ? { "AfterAllowTraffic" = var.after_allow_traffic_hook_arn } : {}
  )

  appspec_content = {
    version = "0.0"
    Resources = [
      {
        "${var.function_name}" = {
          Type = "AWS::Lambda::Function"
          Properties = merge(
            {
              Name           = var.function_name
              Alias          = var.alias_name
              CurrentVersion = var.current_version
              TargetVersion  = var.target_version
            },
            length(local.hooks_map) > 0 ? { Hooks = [local.hooks_map] } : {}
          )
        }
      }
    ]
  }

  appspec_json = jsonencode(local.appspec_content)

  deploy_script = <<-EOT
    #!/usr/bin/env bash
    set -euo pipefail

    APP_NAME="${local.app_name}"
    DEPLOYMENT_GROUP_NAME="${local.deployment_group_name}"
    AWS_CLI="${var.aws_cli_command}"
    SLEEP_TIMER=${var.get_deployment_sleep_timer}

    APPSPEC_CONTENT='${local.appspec_json}'
    APPSPEC_SHA256=$(echo -n "$APPSPEC_CONTENT" | openssl dgst -sha256 | awk '{print $2}')

    echo "Creating CodeDeploy deployment for application: $APP_NAME, group: $DEPLOYMENT_GROUP_NAME..."

    DEPLOYMENT_ID=$($AWS_CLI deploy create-deployment \
      --application-name "$APP_NAME" \
      --deployment-group-name "$DEPLOYMENT_GROUP_NAME" \
      --revision "{\"revisionType\": \"AppSpecContent\", \"appSpecContent\": {\"content\": $(echo "$APPSPEC_CONTENT" | jq -R .), \"sha256\": \"$APPSPEC_SHA256\"}}" \
      --query "deploymentId" \
      --output text)

    echo "Deployment submitted successfully. Deployment ID: $DEPLOYMENT_ID"
    echo "Waiting for deployment to complete..."

    while true; do
      STATUS=$($AWS_CLI deploy get-deployment --deployment-id "$DEPLOYMENT_ID" --query "deploymentInfo.status" --output text)
      echo "Current status: $STATUS"

      if [ "$STATUS" = "Succeeded" ]; then
        echo "Deployment Succeeded!"
        break
      elif [ "$STATUS" = "Failed" ] || [ "$STATUS" = "Stopped" ]; then
        echo "Deployment $STATUS!"
        exit 1
      fi

      sleep "$SLEEP_TIMER"
    done
  EOT
}

resource "local_file" "deploy_script" {
  count           = var.create && var.create_deployment && var.save_deploy_script ? 1 : 0
  content         = local.deploy_script
  filename        = var.deploy_script_file
  file_permission = "0755"
}

resource "null_resource" "run_deployment" {
  count = var.create && var.create_deployment && var.run_deployment ? 1 : 0

  triggers = {
    appspec_sha256 = sha256(local.appspec_json)
    force_deploy   = var.force_deploy ? timestamp() : ""
  }

  provisioner "local-exec" {
    command = local.deploy_script
  }

  depends_on = [
    aws_codedeploy_deployment_group.this
  ]
}

# --------------------------------------------------------------------------------------------------
# Outputs
# --------------------------------------------------------------------------------------------------
output "app_name" {
  description = "Name of the CodeDeploy application."
  value       = local.app_name
}

output "deployment_group_name" {
  description = "Name of the CodeDeploy deployment group."
  value       = local.deployment_group_name
}

output "codedeploy_role_arn" {
  description = "ARN of the IAM role used by CodeDeploy."
  value       = local.codedeploy_role_arn
}

output "appspec_json" {
  description = "Constructed AppSpec JSON revision."
  value       = local.appspec_json
}

output "deploy_script" {
  description = "Generated deployment shell script."
  value       = local.deploy_script
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "Target AWS region."
  default     = "us-east-1"
}

variable "vpc_name_prefix" {
  type        = string
  description = "Prefix for the VPC Name tag."
  default     = "tf-project"
}

variable "vpc_cidr" {
  type        = string
  description = "Base CIDR block for the VPC."
  default     = "10.16.0.0/16"
}

variable "max_subnet_count" {
  type        = number
  description = "Maximum number of Availability Zones to select for subnets."
  default     = 3
}

variable "web_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for web (public) subnets."
  default     = ["10.16.1.0/24", "10.16.2.0/24"]
}

variable "app_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for application (private) subnets."
  default     = ["10.16.10.0/24", "10.16.11.0/24"]
}

variable "database_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for database (private) subnets."
  default     = ["10.16.20.0/24", "10.16.21.0/24"]
}

variable "reserved_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for reserved (private) subnets."
  default     = []
}

variable "gateway_vpc_endpoint_service" {
  type        = string
  description = "Service name for Gateway VPC Endpoint (e.g., com.amazonaws.us-east-1.s3). Leave empty to disable."
  default     = ""
}

variable "interface_vpc_endpoints" {
  type = map(object({
    service_name        = string
    private_dns_enabled = optional(bool, true)
    subnet_tier         = optional(string, "app")
  }))
  description = "Map of interface VPC endpoints to configure."
  default     = {}
}

# -----------------------------------------------------------------------------
# Random Resources & Availability Zones
# -----------------------------------------------------------------------------
resource "random_integer" "vpc_suffix" {
  min = 1
  max = 100
}

locals {
  vpc_name = "${var.vpc_name_prefix}-${random_integer.vpc_suffix.result}"

  has_web_subnets = length(var.web_subnet_cidrs) > 0
  has_private_subnets = (
    length(var.app_subnet_cidrs) + 
    length(var.database_subnet_cidrs) + 
    length(var.reserved_subnet_cidrs)
  ) > 0
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "random_shuffle" "az_pool" {
  input        = data.aws_availability_zones.available.names
  result_count = var.max_subnet_count
}

# -----------------------------------------------------------------------------
# VPC and Internet Gateway
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.vpc_name
  }
}

resource "aws_internet_gateway" "gw" {
  count  = local.has_web_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.vpc_name}-igw"
  }
}

# -----------------------------------------------------------------------------
# Subnets: Web (Public)
# -----------------------------------------------------------------------------
resource "aws_subnet" "web" {
  count                   = length(var.web_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.web_subnet_cidrs[count.index]
  availability_zone       = random_shuffle.az_pool.result[count.index % length(random_shuffle.az_pool.result)]
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.vpc_name}-web-subnet-${count.index + 1}"
    Tier = "web"
  }
}

# -----------------------------------------------------------------------------
# Subnets: App, Database, Reserved (Private)
# -----------------------------------------------------------------------------
resource "aws_subnet" "app" {
  count                   = length(var.app_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.app_subnet_cidrs[count.index]
  availability_zone       = random_shuffle.az_pool.result[count.index % length(random_shuffle.az_pool.result)]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-app-subnet-${count.index + 1}"
    Tier = "app"
  }
}

resource "aws_subnet" "database" {
  count                   = length(var.database_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.database_subnet_cidrs[count.index]
  availability_zone       = random_shuffle.az_pool.result[count.index % length(random_shuffle.az_pool.result)]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-db-subnet-${count.index + 1}"
    Tier = "database"
  }
}

resource "aws_subnet" "reserved" {
  count                   = length(var.reserved_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.reserved_subnet_cidrs[count.index]
  availability_zone       = random_shuffle.az_pool.result[count.index % length(random_shuffle.az_pool.result)]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.vpc_name}-reserved-subnet-${count.index + 1}"
    Tier = "reserved"
  }
}

# -----------------------------------------------------------------------------
# Routing: Public Route Table
# -----------------------------------------------------------------------------
resource "aws_route_table" "public" {
  count  = local.has_web_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw[0].id
  }

  tags = {
    Name = "${local.vpc_name}-public-rt"
  }
}

resource "aws_route_table_association" "web" {
  count          = length(aws_subnet.web)
  subnet_id      = aws_subnet.web[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# -----------------------------------------------------------------------------
# Routing: Shared Private Route Table
# -----------------------------------------------------------------------------
resource "aws_route_table" "private" {
  count  = local.has_private_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.vpc_name}-private-rt"
  }
}

resource "aws_route_table_association" "app" {
  count          = length(aws_subnet.app)
  subnet_id      = aws_subnet.app[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "database" {
  count          = length(aws_subnet.database)
  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "reserved" {
  count          = length(aws_subnet.reserved)
  subnet_id      = aws_subnet.reserved[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# -----------------------------------------------------------------------------
# VPC Endpoints
# -----------------------------------------------------------------------------
# Gateway Endpoint (e.g. S3 / DynamoDB)
resource "aws_vpc_endpoint" "gateway" {
  count             = var.gateway_vpc_endpoint_service != "" && local.has_private_subnets ? 1 : 0
  vpc_id            = aws_vpc.main.id
  service_name      = var.gateway_vpc_endpoint_service
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private[0].id]

  tags = {
    Name = "${local.vpc_name}-gateway-vpce"
  }
}

# Interface Endpoints Security Group
resource "aws_security_group" "interface_endpoints" {
  count       = length(var.interface_vpc_endpoints) > 0 ? 1 : 0
  name        = "${local.vpc_name}-interface-endpoints-sg"
  description = "Security group for interface VPC endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow TLS from inside VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.vpc_name}-interface-endpoints-sg"
  }
}

# Interface Endpoints
resource "aws_vpc_endpoint" "interface" {
  for_each            = var.interface_vpc_endpoints
  vpc_id              = aws_vpc.main.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = each.value.private_dns_enabled
  security_group_ids  = [aws_security_group.interface_endpoints[0].id]

  subnet_ids = (
    each.value.subnet_tier == "web" ? aws_subnet.web[*].id :
    each.value.subnet_tier == "database" ? aws_subnet.database[*].id :
    each.value.subnet_tier == "reserved" ? aws_subnet.reserved[*].id :
    aws_subnet.app[*].id
  )

  tags = {
    Name = "${local.vpc_name}-${each.key}-interface-vpce"
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the provisioned VPC."
  value       = aws_vpc.main.id
}

output "vpc_name" {
  description = "Generated Name tag of the VPC."
  value       = local.vpc_name
}

output "web_subnet_ids" {
  description = "IDs of the web (public) subnets."
  value       = aws_subnet.web[*].id
}

output "app_subnet_ids" {
  description = "IDs of the app (private) subnets."
  value       = aws_subnet.app[*].id
}

output "database_subnet_ids" {
  description = "IDs of the database (private) subnets."
  value       = aws_subnet.database[*].id
}

output "reserved_subnet_ids" {
  description = "IDs of the reserved (private) subnets."
  value       = aws_subnet.reserved[*].id
}

output "private_route_table_id" {
  description = "ID of the shared private route table, if provisioned."
  value       = try(aws_route_table.private[0].id, null)
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region for resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "internal_domain_name" {
  type        = string
  description = "Internal domain name for DHCP and Route 53"
  default     = "internal"
}

variable "dns_resolvers" {
  type        = list(string)
  description = "List of DNS resolvers for the DHCP options set"
  default     = ["10.0.0.2", "8.8.8.8"]
}

variable "admin_ssh_cidrs" {
  type        = list(string)
  description = "List of admin CIDR blocks allowed to connect via Home SSH"
  default     = ["203.0.113.0/24"]
}

# -----------------------------------------------------------------------------
# VPC and Internet Gateway
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main"
  }
}

resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "ig"
  }
}

# -----------------------------------------------------------------------------
# DHCP Options and Private Route 53 Hosted Zone
# -----------------------------------------------------------------------------
resource "aws_vpc_dhcp_options" "internal" {
  domain_name         = var.internal_domain_name
  domain_name_servers = var.dns_resolvers

  tags = {
    Name = "internal-dhcp"
  }
}

resource "aws_vpc_dhcp_options_association" "internal_assoc" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.internal.id
}

resource "aws_route53_zone" "internal" {
  name = var.internal_domain_name

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = {
    Name = "internal-hosted-zone"
  }
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------
resource "aws_subnet" "reserved" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  map_public_ip_on_launch = false

  tags = {
    Name = "reserved"
  }
}

resource "aws_subnet" "sandbox" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = false

  tags = {
    Name = "sandbox"
  }
}

resource "aws_subnet" "web" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = false

  tags = {
    Name = "web"
  }
}

resource "aws_subnet" "database" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.3.0/24"
  map_public_ip_on_launch = false

  tags = {
    Name = "database"
  }
}

resource "aws_subnet" "gameserver" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.4.0/22"
  map_public_ip_on_launch = false

  tags = {
    Name = "gameserver"
  }
}

# -----------------------------------------------------------------------------
# Route Tables and Associations
# -----------------------------------------------------------------------------
resource "aws_route_table" "reserved" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = {
    Name = "reserved-rt"
  }
}

resource "aws_route_table_association" "reserved" {
  subnet_id      = aws_subnet.reserved.id
  route_table_id = aws_route_table.reserved.id
}

resource "aws_route_table" "sandbox" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = {
    Name = "sandbox-rt"
  }
}

resource "aws_route_table_association" "sandbox" {
  subnet_id      = aws_subnet.sandbox.id
  route_table_id = aws_route_table.sandbox.id
}

resource "aws_route_table" "web" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = {
    Name = "web-rt"
  }
}

resource "aws_route_table_association" "web" {
  subnet_id      = aws_subnet.web.id
  route_table_id = aws_route_table.web.id
}

resource "aws_route_table" "database" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = {
    Name = "database-rt"
  }
}

resource "aws_route_table_association" "database" {
  subnet_id      = aws_subnet.database.id
  route_table_id = aws_route_table.database.id
}

resource "aws_route_table" "gameserver" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = {
    Name = "gameserver-rt"
  }
}

resource "aws_route_table_association" "gameserver" {
  subnet_id      = aws_subnet.gameserver.id
  route_table_id = aws_route_table.gameserver.id
}

# -----------------------------------------------------------------------------
# Network ACLs
# -----------------------------------------------------------------------------

# --- Sandbox ACL ---
resource "aws_network_acl" "sandbox" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.sandbox.id]

  # Allow all inbound TCP
  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  # Allow all outbound TCP
  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = {
    Name = "sandbox-nacl"
  }
}

# --- Web ACL ---
resource "aws_network_acl" "web" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.web.id]

  # Inbound SSH
  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  # Inbound HTTP
  ingress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  # Inbound HTTPS
  ingress {
    protocol   = "tcp"
    rule_no    = 120
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  # Inbound Ephemeral Ports (32768-65535)
  ingress {
    protocol   = "tcp"
    rule_no    = 130
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 32768
    to_port    = 65535
  }

  # Outbound all TCP
  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = {
    Name = "web-nacl"
  }
}

# --- Database ACL ---
resource "aws_network_acl" "database" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.database.id]

  # Inbound TCP from web subnet
  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = aws_subnet.web.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  # Inbound TCP from gameserver subnet
  ingress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = aws_subnet.gameserver.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  # Outbound TCP to web subnet
  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = aws_subnet.web.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  # Outbound TCP to gameserver subnet
  egress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = aws_subnet.gameserver.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  tags = {
    Name = "database-nacl"
  }
}

# --- Game Server ACL ---
resource "aws_network_acl" "gameserver" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.gameserver.id]

  # Inbound SSH
  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  # Inbound Game Port 27015 TCP
  ingress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27015
    to_port    = 27015
  }

  # Inbound Game Port 27015 UDP
  ingress {
    protocol   = "udp"
    rule_no    = 111
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27015
    to_port    = 27015
  }

  # Inbound Game Port 27020 TCP
  ingress {
    protocol   = "tcp"
    rule_no    = 120
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27020
    to_port    = 27020
  }

  # Inbound Game Port 27020 UDP
  ingress {
    protocol   = "udp"
    rule_no    = 121
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 27020
    to_port    = 27020
  }

  # Inbound Ephemeral Ports TCP (32768-65535)
  ingress {
    protocol   = "tcp"
    rule_no    = 130
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 32768
    to_port    = 65535
  }

  # Inbound Ephemeral Ports UDP (32768-65535)
  ingress {
    protocol   = "udp"
    rule_no    = 131
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 32768
    to_port    = 65535
  }

  # Outbound All TCP
  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  # Outbound All UDP
  egress {
    protocol   = "udp"
    rule_no    = 110
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = {
    Name = "gameserver-nacl"
  }
}

# -----------------------------------------------------------------------------
# Security Groups
# -----------------------------------------------------------------------------

# --- Home SSH Security Group ---
resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "Allows SSH from admin CIDRs and self, restricts outbound to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from admin CIDRs"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.admin_ssh_cidrs
  }

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Restricted outbound traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "Home SSH"
  }
}

# --- Packer SSH Security Group ---
resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "Allows SSH from VPC CIDR and self, restricts outbound to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Restricted outbound traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "Packer SSH"
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "subnet_ids" {
  description = "IDs of the created subnets"
  value = {
    reserved   = aws_subnet.reserved.id
    sandbox    = aws_subnet.sandbox.id
    web        = aws_subnet.web.id
    database   = aws_subnet.database.id
    gameserver = aws_subnet.gameserver.id
  }
}

output "security_group_ids" {
  description = "IDs of the created security groups"
  value = {
    home_ssh   = aws_security_group.home_ssh.id
    packer_ssh = aws_security_group.packer_ssh.id
  }
}

output "route53_zone_id" {
  description = "Internal Route 53 Hosted Zone ID"
  value       = aws_route53_zone.internal.zone_id
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region for resources"
  default     = "us-east-1"
}

variable "env" {
  type        = string
  description = "Environment name used to prefix resource names"
  default     = ""
}

variable "vpc_cidr" {
  type        = string
  description = "VPC CIDR block"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  type        = list(string)
  description = "List of CIDR blocks for public subnets"
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "private_app_subnet_cidrs" {
  type        = list(string)
  description = "List of CIDR blocks for private application subnets"
  default     = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]
}

variable "private_db_subnet_cidrs" {
  type        = list(string)
  description = "List of CIDR blocks for private database subnets"
  default     = ["10.0.100.0/24", "10.0.110.0/24", "10.0.120.0/24"]
}

# -----------------------------------------------------------------------------
# Data Sources & Locals
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = var.env != "" ? "${var.env}-" : ""
  azs         = slice(data.aws_availability_zones.available.names, 0, 3)
}

# -----------------------------------------------------------------------------
# VPC and Internet Gateway
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${local.name_prefix}vpc"
  }
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}igw"
  }
}

# -----------------------------------------------------------------------------
# Public Tier
# -----------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}public-subnet-${count.index + 1}"
    Tier = "Public"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = {
    Name = "${local.name_prefix}public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# NAT Gateways & Elastic IPs (One per AZ)
# -----------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"

  tags = {
    Name = "${local.name_prefix}nat-eip-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.gw]
}

resource "aws_nat_gateway" "nat" {
  count         = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${local.name_prefix}nat-gw-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.gw]
}

# -----------------------------------------------------------------------------
# Private Application Tier
# -----------------------------------------------------------------------------
resource "aws_subnet" "private_app" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_app_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}private-app-subnet-${count.index + 1}"
    Tier = "Private-App"
  }
}

resource "aws_route_table" "private_app" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = {
    Name = "${local.name_prefix}private-app-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private_app" {
  count          = 3
  subnet_id      = aws_subnet.private_app[count.index].id
  route_table_id = aws_route_table.private_app[count.index].id
}

# -----------------------------------------------------------------------------
# Private Database Tier (Isolated)
# -----------------------------------------------------------------------------
resource "aws_subnet" "private_db" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_db_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}private-db-subnet-${count.index + 1}"
    Tier = "Private-Database"
  }
}

resource "aws_route_table" "private_db" {
  vpc_id = aws_vpc.main.id

  # Local route is automatically added by AWS matching the VPC CIDR block

  tags = {
    Name = "${local.name_prefix}private-db-rt"
  }
}

resource "aws_route_table_association" "private_db" {
  count          = 3
  subnet_id      = aws_subnet.private_db[count.index].id
  route_table_id = aws_route_table.private_db.id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_app_subnet_ids" {
  description = "IDs of the private application subnets"
  value       = aws_subnet.private_app[*].id
}

output "private_db_subnet_ids" {
  description = "IDs of the private database subnets"
  value       = aws_subnet.private_db[*].id
}

output "nat_gateway_public_ips" {
  description = "Public IP addresses of the NAT Gateways"
  value       = aws_eip.nat[*].public_ip
}
```

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# --- Variables ---

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources in"
  default     = "us-east-1"
}

variable "bucket_name" {
  type        = string
  description = "Base name for the S3 bucket"
  default     = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  type        = bool
  description = "Whether to prefix the bucket name with the AWS IAM account alias"
  default     = false
}

variable "use_random_suffix" {
  type        = bool
  description = "Whether to append a random suffix to the bucket name"
  default     = false
}

variable "force_destroy" {
  type        = bool
  description = "Whether to force destroy the bucket even if it contains objects"
  default     = false
}

variable "enable_s3_public_access_block" {
  type        = bool
  description = "Whether to enable S3 Public Access Block settings"
  default     = true
}

variable "object_ownership" {
  type        = string
  description = "Object ownership control setting (e.g., BucketOwnerEnforced, BucketOwnerPreferred, ObjectWriter)"
  default     = "BucketOwnerEnforced"
}

variable "versioning_status" {
  type        = string
  description = "Versioning status for the bucket (Enabled, Suspended, or Disabled)"
  default     = "Enabled"
}

variable "kms_master_key_id" {
  type        = string
  description = "KMS Master Key ID or ARN for SSE-KMS encryption. If null, AES256 is used."
  default     = null
}

variable "bucket_key_enabled" {
  type        = bool
  description = "Whether S3 Bucket Keys are enabled for SSE-KMS"
  default     = false
}

variable "enable_analytics" {
  type        = bool
  description = "Whether to enable S3 Storage Class Analytics"
  default     = true
}

variable "enable_bucket_inventory" {
  type        = bool
  description = "Whether to enable S3 Bucket Inventory reporting"
  default     = false
}

variable "logging_bucket" {
  type        = string
  description = "Target bucket name for S3 access logs. If null, logging is disabled."
  default     = null
}

variable "transfer_acceleration" {
  type        = string
  description = "Transfer acceleration status (Enabled or Suspended). If null, left unconfigured."
  default     = null
}

variable "s3_bucket_acl" {
  type        = string
  description = "Bucket ACL (e.g., private). Ignored if object_ownership is BucketOwnerEnforced."
  default     = null
}

variable "cors_rules" {
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  description = "List of CORS rules to apply to the bucket"
  default     = []
}

variable "custom_bucket_policy" {
  type        = string
  description = "Custom JSON bucket policy to combine with mandatory security policies"
  default     = ""
}

# --- Data Sources & Helpers ---

data "aws_caller_identity" "current" {}

data "aws_iam_account_alias" "current" {}

resource "random_string" "suffix" {
  count   = var.use_random_suffix ? 1 : 0
  length  = 8
  special = false
  upper   = false
}

locals {
  account_alias = length(data.aws_iam_account_alias.current.account_alias) > 0 ? data.aws_iam_account_alias.current.account_alias : data.aws_caller_identity.current.account_id
  prefix        = var.use_account_alias_prefix ? "${local.account_alias}-" : ""
  suffix        = var.use_random_suffix ? "-${random_string.suffix[0].result}" : ""
  final_bucket_name = lower("${local.prefix}${var.bucket_name}${local.suffix}")
}

# --- S3 Bucket ---

resource "aws_s3_bucket" "this" {
  bucket        = local.final_bucket_name
  force_destroy = var.force_destroy
}

# --- Object Ownership & Public Access Block ---

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  count  = var.enable_s3_public_access_block ? 1 : 0
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# --- Server Side Encryption ---

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_master_key_id != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_master_key_id
    }
    bucket_key_enabled = var.kms_master_key_id != null ? var.bucket_key_enabled : false
  }
}

# --- Versioning ---

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_status
  }
}

# --- Bucket ACL (Optional) ---

resource "aws_s3_bucket_acl" "this" {
  count      = var.s3_bucket_acl != null && var.object_ownership != "BucketOwnerEnforced" ? 1 : 0
  bucket     = aws_s3_bucket.this.id
  acl        = var.s3_bucket_acl
  depends_on = [aws_s3_bucket_ownership_controls.this]
}

# --- Logging (Optional) ---

resource "aws_s3_bucket_logging" "this" {
  count         = var.logging_bucket != null ? 1 : 0
  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging_bucket
  target_prefix = "s3/${aws_s3_bucket.this.id}/"
}

# --- Transfer Acceleration (Optional) ---

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = var.transfer_acceleration != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration
}

# --- CORS Configuration (Optional) ---

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# --- Lifecycle Configuration ---

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  transition_default_minimum_object_size = "all_storage_classes_128K"

  rule {
    id     = "general-lifecycle-rule"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  rule {
    id     = "analytics-export-lifecycle"
    status = var.enable_analytics ? "Enabled" : "Disabled"

    filter {
      prefix = "_AWSBucketAnalytics/"
    }

    expiration {
      days = 30
    }
  }

  rule {
    id     = "inventory-export-lifecycle"
    status = var.enable_bucket_inventory ? "Enabled" : "Disabled"

    filter {
      prefix = "_AWSBucketInventory/"
    }

    expiration {
      days = 14
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

# --- Bucket Policy ---

data "aws_iam_policy_document" "combined_policy" {
  source_policy_documents = var.custom_bucket_policy != "" ? [var.custom_bucket_policy] : []

  # Deny unencrypted transport
  statement {
    sid     = "EnforceTLSRequestsOnly"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*"
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  # Allow S3 delivery for analytics and inventory
  statement {
    sid     = "AllowS3DeliveryAnalyticsAndInventory"
    effect  = "Allow"
    actions = ["s3:PutObject"]
    resources = [
      "${aws_s3_bucket.this.arn}/_AWSBucketAnalytics/*",
      "${aws_s3_bucket.this.arn}/_AWSBucketInventory/*"
    ]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket     = aws_s3_bucket.this.id
  policy     = data.aws_iam_policy_document.combined_policy.json
  depends_on = [aws_s3_bucket_public_access_block.this]
}

# --- Analytics Configuration ---

resource "aws_s3_bucket_analytics_configuration" "this" {
  count  = var.enable_analytics ? 1 : 0
  bucket = aws_s3_bucket.this.id
  name   = "EntireBucketAnalytics"

  storage_class_analysis {
    data_export {
      destination {
        s3_bucket_destination {
          bucket_arn = aws_s3_bucket.this.arn
          format     = "CSV"
          prefix     = "_AWSBucketAnalytics/"
        }
      }
      output_schema_version = "V_1"
    }
  }

  depends_on = [aws_s3_bucket_policy.this]
}

# --- Inventory Configuration (Optional) ---

resource "aws_s3_bucket_inventory" "this" {
  count                    = var.enable_bucket_inventory ? 1 : 0
  bucket                   = aws_s3_bucket.this.id
  name                     = "EntireBucketInventory"
  included_object_versions = "All"

  schedule {
    frequency = "Weekly"
  }

  destination {
    bucket {
      format     = "ORC"
      bucket_arn = aws_s3_bucket.this.arn
      prefix     = "_AWSBucketInventory/"
    }
  }

  depends_on = [aws_s3_bucket_policy.this]
}

# --- Outputs ---

output "bucket_id" {
  description = "The name/ID of the S3 bucket"
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket"
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "The bucket domain name"
  value       = aws_s3_bucket.this.bucket_domain_name
}
```

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  description = "The AWS region where resources will be deployed."
  type        = string
  default     = "us-east-1"
}

variable "bucket_name" {
  description = "Name of the S3 bucket."
  type        = string
  default     = "benchmark-access-logs-bkt"
}

variable "environment" {
  description = "Environment identifier to tag resources with."
  type        = string
  default     = "Development"
}

variable "custom_tags" {
  description = "Additional tags to merge with default tags."
  type        = map(string)
  default     = {}
}

variable "force_destroy" {
  description = "A boolean that indicates all objects should be deleted from the bucket so that the bucket can be destroyed without error."
  type        = bool
  default     = false
}

# Encryption Variables
variable "sse_algorithm" {
  description = "Server-side encryption algorithm to use. Options: 'AES256', 'aws:kms', or 'none' to disable."
  type        = string
  default     = "AES256"
}

variable "kms_master_key_id" {
  description = "AWS KMS master key ID used for the SSE-KMS encryption. Required if sse_algorithm is 'aws:kms'."
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Whether or not to use Amazon S3 Bucket Keys for SSE-KMS."
  type        = bool
  default     = false
}

# Public Access Block
variable "block_public_access" {
  description = "Whether to provision the public access block resource."
  type        = bool
  default     = true
}

variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket."
  type        = bool
  default     = true
}

# Ownership and ACL
variable "control_object_ownership" {
  description = "Whether to manage S3 Bucket Ownership Controls."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership rule. Valid values: BucketOwnerPreferred, ObjectWriter or BucketOwnerEnforced."
  type        = string
  default     = "ObjectWriter"
}

variable "acl" {
  description = "The canned ACL to apply. Mutually exclusive with grants."
  type        = string
  default     = null
}

variable "grants" {
  description = "List of ACL grants to apply. Mutually exclusive with acl variable."
  type = list(object({
    id          = optional(string)
    type        = string
    permissions = list(string)
    uri         = optional(string)
  }))
  default = []
}

# Versioning
variable "versioning_enabled" {
  description = "Enable versioning for bucket objects."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Enable MFA delete for bucket objects."
  type        = bool
  default     = false
}

# Logging
variable "bucket_logging" {
  description = "Whether bucket logging should be enabled."
  type        = bool
  default     = false
}

variable "target_bucket" {
  description = "The name of the bucket where you want Amazon S3 to store server access logs."
  type        = string
  default     = null
}

variable "target_prefix" {
  description = "A prefix for all log object keys."
  type        = string
  default     = "logs/"
}

# Object Lock
variable "object_lock_enabled" {
  description = "Whether S3 Object Lock configuration should be enabled on the bucket."
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "The default Object Lock retention mode to apply. Valid values: GOVERNANCE, COMPLIANCE."
  type        = string
  default     = "GOVERNANCE"
}

variable "object_lock_days" {
  description = "The number of days that you want to specify for the default retention period."
  type        = number
  default     = 30
}

variable "object_lock_years" {
  description = "The number of years that you want to specify for the default retention period."
  type        = number
  default     = null
}

# Static Website
variable "website_enabled" {
  description = "Whether to configure the bucket as a static website."
  type        = bool
  default     = false
}

variable "index_document" {
  description = "S3 website index document."
  type        = string
  default     = "index.html"
}

variable "error_document" {
  description = "S3 website error document."
  type        = string
  default     = "error.html"
}

variable "routing_rules" {
  description = "JSON array containing routing rules for static website hosting."
  type        = string
  default     = null
}

# Intelligent Tiering
variable "intelligent_tiering_configs" {
  description = "Map of intelligent tiering configurations to create."
  type = map(object({
    status = optional(string, "Enabled")
    prefix = optional(string, null)
    tierings = list(object({
      access_tier = string
      days        = number
    }))
  }))
  default = {}
}

# CloudWatch Metrics
variable "metric_configurations" {
  description = "Map of CloudWatch metric configurations for the bucket."
  type = map(object({
    prefix = optional(string, null)
    tags   = optional(map(string), {})
  }))
  default = {}
}

# CORS
variable "cors_rules" {
  description = "List of maps representing CORS rules."
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

# Lifecycle Configuration
variable "lifecycle_rules" {
  description = "List of lifecycle rules to configure."
  type = list(object({
    id      = string
    enabled = bool
    prefix  = optional(string)
    tags    = optional(map(string))

    abort_incomplete_multipart_upload_days = optional(number)

    expiration = optional(object({
      date = optional(string)
      days = optional(number)
    }))

    transitions = optional(list(object({
      date          = optional(string)
      days          = optional(number)
      storage_class = string
    })))

    noncurrent_version_expiration = optional(object({
      noncurrent_days = number
    }))

    noncurrent_version_transitions = optional(list(object({
      noncurrent_days = number
      storage_class   = string
    })))
  }))
  default = []
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES
# ---------------------------------------------------------------------------------------------------------------------

data "aws_canonical_user_id" "current" {}

# ---------------------------------------------------------------------------------------------------------------------
# RESOURCES
# ---------------------------------------------------------------------------------------------------------------------

locals {
  default_tags = {
    Environment     = var.environment
    ServiceProvider = "Rackspace"
  }
  all_tags = merge(local.default_tags, var.custom_tags)
}

resource "aws_s3_bucket" "this" {
  bucket              = var.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = local.all_tags
}

# Public Access Block
resource "aws_s3_bucket_public_access_block" "this" {
  count = var.block_public_access ? 1 : 0

  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = var.block_public_acls
  ignore_public_acls      = var.ignore_public_acls
  block_public_policy     = var.block_public_policy
  restrict_public_buckets = var.restrict_public_buckets
}

# Ownership Controls
resource "aws_s3_bucket_ownership_controls" "this" {
  count  = var.control_object_ownership ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

# Bucket ACL Configuration
resource "aws_s3_bucket_acl" "this" {
  count = (var.acl != null || length(var.grants) > 0) ? 1 : 0

  bucket                = aws_s3_bucket.this.id
  expected_bucket_owner = null
  acl                   = var.acl != null ? var.acl : null

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []
    content {
      owner {
        id = data.aws_canonical_user_id.current.id
      }

      dynamic "grant" {
        for_each = var.grants
        content {
          grantee {
            id   = grant.value.id != null ? grant.value.id : (grant.value.type == "CanonicalUser" ? data.aws_canonical_user_id.current.id : null)
            type = grant.value.type
            uri  = grant.value.uri
          }
          permission = grant.value.permissions[0]
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

# Server-Side Encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = lower(var.sse_algorithm) != "none" ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    bucket_key_enabled = var.bucket_key_enabled

    apply_server_side_encryption_by_default {
      sse_algorithm     = var.sse_algorithm
      kms_master_key_id = var.sse_algorithm == "aws:kms" ? var.kms_master_key_id : null
    }
  }
}

# Bucket Versioning
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = var.versioning_enabled ? "Enabled" : "Suspended"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

# Bucket Logging
resource "aws_s3_bucket_logging" "this" {
  count = (var.bucket_logging && var.target_bucket != null) ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.target_bucket
  target_prefix = var.target_prefix
}

# Object Lock Configuration
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.object_lock_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_mode
      days  = var.object_lock_years == null ? var.object_lock_days : null
      years = var.object_lock_years
    }
  }
}

# Static Website Configuration
resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.website_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id

  index_document {
    suffix = var.index_document
  }

  error_document {
    key = var.error_document
  }

  routing_rules = var.routing_rules
}

# Intelligent Tiering
resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  for_each = var.intelligent_tiering_configs

  bucket = aws_s3_bucket.this.id
  name   = each.key
  status = each.value.status

  dynamic "filter" {
    for_each = each.value.prefix != null ? [1] : []
    content {
      prefix = each.value.prefix
    }
  }

  dynamic "tiering" {
    for_each = each.value.tierings
    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }
}

# CloudWatch Request Metrics
resource "aws_s3_bucket_metric" "this" {
  for_each = var.metric_configurations

  bucket = aws_s3_bucket.this.id
  name   = each.key

  dynamic "filter" {
    for_each = (each.value.prefix != null || length(each.value.tags) > 0) ? [1] : []
    content {
      prefix = each.value.prefix
      tags   = length(each.value.tags) > 0 ? each.value.tags : null
    }
  }
}

# CORS Configuration
resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# Lifecycle Configuration
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = (rule.value.prefix != null || (rule.value.tags != null && length(rule.value.tags) > 0)) ? [1] : []
        content {
          dynamic "and" {
            for_each = (rule.value.prefix != null && rule.value.tags != null && length(rule.value.tags) > 0) ? [1] : []
            content {
              prefix = rule.value.prefix
              tags   = rule.value.tags
            }
          }

          prefix = (rule.value.prefix != null && (rule.value.tags == null || length(rule.value.tags) == 0)) ? rule.value.prefix : null
          tags   = ((rule.value.prefix == null) && rule.value.tags != null && length(rule.value.tags) > 0) ? rule.value.tags : null
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [1] : []
        content {
          days_after_initiation = rule.value.abort_incomplete_multipart_upload_days
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          date = expiration.value.date
          days = expiration.value.days
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions != null ? rule.value.transitions : []
        content {
          date          = transition.value.date
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions != null ? rule.value.noncurrent_version_transitions : []
        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "bucket_id" {
  description = "The name/ID of the bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "The bucket domain name."
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "The bucket region-specific domain name."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "bucket" {
  description = "The name of the bucket. If omitted, Terraform will assign a random name using bucket_prefix."
  type        = string
  default     = null
  validation {
    condition     = var.bucket == null || can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.bucket))
    error_message = "Bucket name must be between 3 and 63 characters long, and contain only lowercase letters, numbers, hyphens, and dots."
  }
}

variable "bucket_prefix" {
  description = "Creates a unique bucket name beginning with the specified prefix. Max 37 chars."
  type        = string
  default     = null
  validation {
    condition     = var.bucket_prefix == null || length(var.bucket_prefix) <= 37
    error_message = "Bucket prefix must be at most 37 characters."
  }
}

variable "force_destroy" {
  description = "A boolean that indicates all objects should be deleted from the bucket so that the bucket can be destroyed without error."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership rule. Can be BucketOwnerEnforced, BucketOwnerPreferred, or ObjectWriter."
  type        = string
  default     = "BucketOwnerEnforced"
  validation {
    condition     = contains(["BucketOwnerEnforced", "BucketOwnerPreferred", "ObjectWriter"], var.object_ownership)
    error_message = "Allowed values are BucketOwnerEnforced, BucketOwnerPreferred, or ObjectWriter."
  }
}

variable "acl" {
  description = "The canned ACL to apply. Only used if object_ownership is ObjectWriter."
  type        = string
  default     = "private"
}

variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "versioning_enabled" {
  description = "Whether versioning is enabled for the bucket."
  type        = bool
  default     = false
}

variable "kms_key_arn" {
  description = "The ARN of the KMS key to use for encryption. If null, AES256 is used."
  type        = string
  default     = null
}

variable "logging_source_bucket_arns" {
  description = "List of source bucket ARNs allowed to write logs into this bucket via logging.s3.amazonaws.com."
  type        = list(string)
  default     = []
}

variable "custom_bucket_policy_json" {
  description = "A custom JSON policy string to merge with the baseline security policy."
  type        = string
  default     = null
}

variable "enable_eventbridge" {
  description = "Whether to enable EventBridge notifications for the S3 bucket."
  type        = bool
  default     = false
}

variable "logging_target_bucket" {
  description = "Destination bucket name for server access logging."
  type        = string
  default     = null
}

variable "logging_target_prefix" {
  description = "Prefix for server access logging objects."
  type        = string
  default     = "logs/"
}

variable "object_lock_configuration" {
  description = "Object Lock configuration parameters."
  type = object({
    enabled = bool
    rule = optional(object({
      default_retention = object({
        mode  = string
        days  = optional(number)
        years = optional(number)
      })
    }))
  })
  default = null
}

variable "replication_configuration" {
  description = "Cross-region replication configuration."
  type = object({
    role = string
    rules = list(object({
      id       = string
      priority = optional(number)
      status   = string
      filter   = optional(any)
      delete_marker_replication = optional(object({
        status = string
      }))
      destination = object({
        bucket        = string
        storage_class = optional(string)
        account       = optional(string)
        encryption_configuration = optional(object({
          replica_kms_key_id = string
        }))
        replication_time = optional(object({
          status = string
          time = object({
            minutes = number
          })
        }))
        metrics = optional(object({
          status = string
          event_threshold = object({
            minutes = number
          })
        }))
      })
      source_selection_criteria = optional(object({
        sse_kms_encrypted_objects = optional(object({
          status = string
        }))
      }))
    }))
  })
  default = null
}

variable "inventory_configuration" {
  description = "Inventory configuration settings."
  type = object({
    name                     = string
    included_object_versions = string
    enabled                  = optional(bool, true)
    schedule_frequency       = string
    destination_bucket_arn   = string
    destination_format       = optional(string, "Parquet")
    destination_prefix       = optional(string, "inventory")
    destination_account_id   = optional(string)
    sse_kms_key_id           = optional(string)
  })
  default = null
}

variable "cors_rules" {
  description = "List of CORS rules to apply to the S3 bucket."
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle management rules."
  type = list(object({
    id      = string
    enabled = bool
    filter = optional(object({
      prefix                   = optional(string)
      object_size_greater_than = optional(number)
      object_size_less_than    = optional(number)
      tags                     = optional(map(string))
    }))
    expiration = optional(object({
      date                         = optional(string)
      days                         = optional(number)
      expired_object_delete_marker = optional(bool)
    }))
    transitions = optional(list(object({
      date          = optional(string)
      days          = optional(number)
      storage_class = string
    })), [])
    noncurrent_version_expiration = optional(object({
      newer_noncurrent_versions = optional(number)
      noncurrent_days           = optional(number)
    }))
    noncurrent_version_transitions = optional(list(object({
      newer_noncurrent_versions = optional(number)
      noncurrent_days           = optional(number)
      storage_class             = string
    })), [])
    abort_incomplete_multipart_upload = optional(object({
      days_after_initiation = number
    }))
  }))
  default = []
}

variable "tags" {
  description = "A mapping of tags to assign to the bucket."
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------------------------------------------------
# PRIMARY S3 BUCKET & ATTRIBUTES
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket" "this" {
  bucket        = var.bucket
  bucket_prefix = var.bucket != null ? null : (var.bucket_prefix != null ? var.bucket_prefix : "enterprise-s3-")
  force_destroy = var.force_destroy

  object_lock_enabled = try(var.object_lock_configuration.enabled, false)

  tags = var.tags
}

# Object Ownership
resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

# ACL provisioned conditionally only if ObjectWriter is explicitly configured
resource "aws_s3_bucket_acl" "this" {
  count      = var.object_ownership == "ObjectWriter" ? 1 : 0
  bucket     = aws_s3_bucket.this.id
  acl        = var.acl
  depends_on = [aws_s3_bucket_ownership_controls.this]
}

# Public Access Block
resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# Versioning Configuration
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_enabled ? "Enabled" : "Suspended"
  }
}

# Server-Side Encryption Configuration
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_key_arn != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_key_arn
    }
    bucket_key_enabled = var.kms_key_arn != null ? true : false
  }
}

# Server Access Logging with precondition checks against concurrent object locking
resource "aws_s3_bucket_logging" "this" {
  count  = var.logging_target_bucket != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_target_bucket
  target_prefix = var.logging_target_prefix

  lifecycle {
    precondition {
      condition     = !(try(var.object_lock_configuration.enabled, false) && var.logging_target_bucket == aws_s3_bucket.this.id)
      error_message = "A bucket cannot act as its own access log target while Object Lock is enabled."
    }
  }
}

# Object Lock Configuration with retention policies
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = try(var.object_lock_configuration.enabled, false) ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.rule.default_retention.mode
      days  = var.object_lock_configuration.rule.default_retention.days
      years = var.object_lock_configuration.rule.default_retention.years
    }
  }

  lifecycle {
    precondition {
      condition     = length(var.logging_source_bucket_arns) == 0
      error_message = "Object Lock cannot be configured on a bucket acting as an S3 access logging target."
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

# EventBridge Notification Configuration
resource "aws_s3_bucket_notification" "this" {
  count       = var.enable_eventbridge ? 1 : 0
  bucket      = aws_s3_bucket.this.id
  eventbridge = true
}

# CORS Configuration
resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# Lifecycle Management Rules
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count      = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket     = aws_s3_bucket.this.id
  depends_on = [aws_s3_bucket_versioning.this]

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix                   = filter.value.prefix
          object_size_greater_than = filter.value.object_size_greater_than
          object_size_less_than    = filter.value.object_size_less_than

          dynamic "tag" {
            for_each = filter.value.tags != null ? filter.value.tags : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          date                         = expiration.value.date
          days                         = expiration.value.days
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions != null ? rule.value.transitions : []
        content {
          date          = transition.value.date
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          newer_noncurrent_versions = noncurrent_version_expiration.value.newer_noncurrent_versions
          noncurrent_days           = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions != null ? rule.value.noncurrent_version_transitions : []
        content {
          newer_noncurrent_versions = noncurrent_version_transition.value.newer_noncurrent_versions
          noncurrent_days           = noncurrent_version_transition.value.noncurrent_days
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }
}

# Cross-Region Replication Configuration
resource "aws_s3_bucket_replication_configuration" "this" {
  count      = var.replication_configuration != null ? 1 : 0
  bucket     = aws_s3_bucket.this.id
  role       = var.replication_configuration.role
  depends_on = [aws_s3_bucket_versioning.this]

  dynamic "rule" {
    for_each = var.replication_configuration.rules
    content {
      id       = rule.value.id
      priority = rule.value.priority
      status   = rule.value.status

      dynamic "delete_marker_replication" {
        for_each = rule.value.delete_marker_replication != null ? [rule.value.delete_marker_replication] : []
        content {
          status = delete_marker_replication.value.status
        }
      }

      dynamic "destination" {
        for_each = [rule.value.destination]
        content {
          bucket        = destination.value.bucket
          storage_class = destination.value.storage_class
          account       = destination.value.account

          dynamic "encryption_configuration" {
            for_each = destination.value.encryption_configuration != null ? [destination.value.encryption_configuration] : []
            content {
              replica_kms_key_id = encryption_configuration.value.replica_kms_key_id
            }
          }

          dynamic "replication_time" {
            for_each = destination.value.replication_time != null ? [destination.value.replication_time] : []
            content {
              status = replication_time.value.status
              time {
                minutes = replication_time.value.time.minutes
              }
            }
          }

          dynamic "metrics" {
            for_each = destination.value.metrics != null ? [destination.value.metrics] : []
            content {
              status = metrics.value.status
              event_threshold {
                minutes = metrics.value.event_threshold.minutes
              }
            }
          }
        }
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.source_selection_criteria != null ? [rule.value.source_selection_criteria] : []
        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = source_selection_criteria.value.sse_kms_encrypted_objects != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []
            content {
              status = sse_kms_encrypted_objects.value.status
            }
          }
        }
      }
    }
  }
}

# Inventory Configuration
resource "aws_s3_bucket_inventory" "this" {
  count                    = var.inventory_configuration != null ? 1 : 0
  bucket                   = aws_s3_bucket.this.id
  name                     = var.inventory_configuration.name
  included_object_versions = var.inventory_configuration.included_object_versions
  enabled                  = var.inventory_configuration.enabled

  schedule {
    frequency = var.inventory_configuration.schedule_frequency
  }

  destination {
    bucket {
      format     = var.inventory_configuration.destination_format
      bucket_arn = var.inventory_configuration.destination_bucket_arn
      prefix     = var.inventory_configuration.destination_prefix
      account_id = var.inventory_configuration.destination_account_id

      dynamic "encryption" {
        for_each = var.inventory_configuration.sse_kms_key_id != null ? [1] : [0]
        content {
          dynamic "sse_kms" {
            for_each = encryption.value == 1 ? [1] : []
            content {
              key_id = var.inventory_configuration.sse_kms_key_id
            }
          }
          dynamic "sse_s3" {
            for_each = encryption.value == 0 ? [1] : []
            content {}
          }
        }
      }
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# BUCKET POLICY COMBINATION (TLS ENFORCEMENT, LOGGING, AND CUSTOM POLICY)
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "combined_policy" {
  source_policy_documents = var.custom_bucket_policy_json != null ? [var.custom_bucket_policy_json] : []

  # Enforce TLS 1.2+ / Deny Insecure Transport
  statement {
    sid     = "EnforceSecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*"
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  # Conditional S3 Access Logging Destination Permissions
  dynamic "statement" {
    for_each = length(var.logging_source_bucket_arns) > 0 ? [1] : []
    content {
      sid     = "S3ServerAccessLogsPolicy"
      effect  = "Allow"
      actions = ["s3:PutObject"]
      resources = [
        "${aws_s3_bucket.this.arn}/*"
      ]

      principals {
        type        = "Service"
        identifiers = ["logging.s3.amazonaws.com"]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = var.logging_source_bucket_arns
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket     = aws_s3_bucket.this.id
  policy     = data.aws_iam_policy_document.combined_policy.json
  depends_on = [aws_s3_bucket_public_access_block.this]
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "bucket_id" {
  description = "The name of the bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_region" {
  description = "The AWS region the bucket resides in."
  value       = aws_s3_bucket.this.region
}

output "bucket_domain_name" {
  description = "The bucket domain name."
  value       = aws_s3_bucket.this.bucket_domain_name
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "The target AWS region for deployment and developer bucket creation restriction."
  default     = "us-east-1"
}

variable "group_name_prefix" {
  type        = string
  description = "Prefix for IAM group names."
  default     = "app"
}

variable "remote_state_bucket_name" {
  type        = string
  description = "Name of the remote-state S3 bucket to which developer access is explicitly denied."
  default     = "app-terraform-remote-state-bucket"
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}

# ==============================================================================
# Account-Wide Security Baselines
# ==============================================================================

# Account-wide IAM Password Policy
resource "aws_iam_account_password_policy" "strict" {
  minimum_password_length        = 12
  require_lowercase_characters   = true
  require_numbers                = true
  require_uppercase_characters   = true
  require_symbols                = true
  allow_users_to_change_password = true
  hard_expiry                    = false
}

# Account-wide S3 Public Access Block
resource "aws_s3_account_public_access_block" "account_level" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ==============================================================================
# IAM Groups
# ==============================================================================

resource "aws_iam_group" "developer" {
  name = "${var.group_name_prefix}_developer"
}

resource "aws_iam_group" "admin" {
  name = "${var.group_name_prefix}_admin"
}

# ==============================================================================
# Developer Policies & Attachments
# ==============================================================================

# 1. AWS Managed Policies
resource "aws_iam_group_policy_attachment" "dev_iam_readonly" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "dev_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserChangePassword"
}

resource "aws_iam_group_policy_attachment" "dev_user_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserSSHKeys"
}

# 2. Self-Management of Access Keys
resource "aws_iam_policy" "dev_manage_access_keys" {
  name        = "${var.group_name_prefix}-developer-manage-access-keys"
  description = "Allows users to manage their own IAM access keys"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageOwnAccessKeys"
        Effect = "Allow"
        Action = [
          "iam:CreateAccessKey",
          "iam:DeleteAccessKey",
          "iam:ListAccessKeys",
          "iam:UpdateAccessKey",
          "iam:GetAccessKeyLastUsed"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "dev_manage_access_keys_attach" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.dev_manage_access_keys.arn
}

# 3. Virtual MFA Device Management (Requires MFA to delete or deactivate)
resource "aws_iam_policy" "dev_manage_mfa" {
  name        = "${var.group_name_prefix}-developer-manage-mfa"
  description = "Allows users to manage their own MFA devices; requires MFA to deactivate or delete"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowManageMFAWithoutMfaRequirement"
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListMFADevices",
          "iam:ListVirtualMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = [
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}",
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
        ]
      },
      {
        Sid    = "AllowDeactivateAndDeleteMFAWithMfaRequirement"
        Effect = "Allow"
        Action = [
          "iam:DeactivateMFADevice",
          "iam:DeleteVirtualMFADevice"
        ]
        Resource = [
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}",
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
        ]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "dev_manage_mfa_attach" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.dev_manage_mfa.arn
}

# 4. MFA-Gated S3 Access with Region and Remote State Denials
resource "aws_iam_policy" "dev_s3_mfa_gated" {
  name        = "${var.group_name_prefix}-developer-s3-mfa-gated"
  description = "MFA-gated S3 access, restricting bucket creation region and denying remote state bucket access"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowS3WithMFA"
        Effect   = "Allow"
        Action   = "s3:*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid      = "DenyBucketCreationOutsideDesignatedRegion"
        Effect   = "Deny"
        Action   = "s3:CreateBucket"
        Resource = "*"
        Condition = {
          StringNotEquals = {
            "aws:RequestedRegion" = var.aws_region
          }
        }
      },
      {
        Sid    = "DenyRemoteStateBucketAccess"
        Effect = "Deny"
        Action = "s3:*"
        Resource = [
          "arn:aws:s3:::${var.remote_state_bucket_name}",
          "arn:aws:s3:::${var.remote_state_bucket_name}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "dev_s3_mfa_gated_attach" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.dev_s3_mfa_gated.arn
}

# 5. MFA-Gated EC2, ELB, CloudWatch, AutoScaling and SLR Access
resource "aws_iam_policy" "dev_services_mfa_gated" {
  name        = "${var.group_name_prefix}-developer-services-mfa-gated"
  description = "Allows MFA-gated management for EC2, ELB, CloudWatch, and AutoScaling, with SLR creation"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowServicesWithMFA"
        Effect = "Allow"
        Action = [
          "ec2:*",
          "elasticloadbalancing:*",
          "cloudwatch:*",
          "logs:*",
          "autoscaling:*"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "AllowServiceLinkedRoleCreation"
        Effect = "Allow"
        Action = "iam:CreateServiceLinkedRole"
        Resource = [
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling",
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/elasticloadbalancing.amazonaws.com/AWSServiceRoleForElasticLoadBalancing"
        ]
        Condition = {
          StringLike = {
            "iam:AWSServiceName" = [
              "autoscaling.amazonaws.com",
              "elasticloadbalancing.amazonaws.com"
            ]
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "dev_services_mfa_gated_attach" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.dev_services_mfa_gated.arn
}

# ==============================================================================
# Administrator Role and Group Configurations
# ==============================================================================

# Admin Role assumed by Account Root with MFA requirement
resource "aws_iam_role" "admin" {
  name = "admin"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "RootAssumeRoleWithMFA"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# Full Admin Access Policy with MFA Condition
resource "aws_iam_policy" "admin_full_access" {
  name        = "AdminFullAccessWithMFA"
  description = "Provides full administrative privileges conditioned on multi-factor authentication"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAllWithMFA"
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "admin_role_attach" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_full_access.arn
}

# Group Policy for Admin Group to assume the admin role with MFA
resource "aws_iam_policy" "admin_assume_role" {
  name        = "${var.group_name_prefix}-admin-assume-role"
  description = "Allows group members to assume the admin role requiring MFA"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AssumeAdminRoleWithMFA"
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.admin.arn
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "admin_group_assume_role_attach" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_assume_role.arn
}

# ==============================================================================
# Outputs
# ==============================================================================

output "developer_group_name" {
  description = "Name of the IAM group created for developers."
  value       = aws_iam_group.developer.name
}

output "admin_group_name" {
  description = "Name of the IAM group created for administrators."
  value       = aws_iam_group.admin.name
}

output "admin_role_arn" {
  description = "ARN of the admin IAM role."
  value       = aws_iam_role.admin.arn
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region for infrastructure deployment"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "Primary IPv4 CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnets_config" {
  type = list(object({
    name = string
    cidr = string
    az   = string
  }))
  description = "List of 16 subnet definitions spanning 10.0.0.0/24 to 10.0.15.0/24 across three AZs"
  default = [
    { name = "subnet-0",  cidr = "10.0.0.0/24",  az = "us-east-1a" },
    { name = "subnet-1",  cidr = "10.0.1.0/24",  az = "us-east-1b" },
    { name = "subnet-2",  cidr = "10.0.2.0/24",  az = "us-east-1c" },
    { name = "subnet-3",  cidr = "10.0.3.0/24",  az = "us-east-1a" },
    { name = "subnet-4",  cidr = "10.0.4.0/24",  az = "us-east-1b" },
    { name = "subnet-5",  cidr = "10.0.5.0/24",  az = "us-east-1c" },
    { name = "subnet-6",  cidr = "10.0.6.0/24",  az = "us-east-1a" },
    { name = "subnet-7",  cidr = "10.0.7.0/24",  az = "us-east-1b" },
    { name = "subnet-8",  cidr = "10.0.8.0/24",  az = "us-east-1c" },
    { name = "subnet-9",  cidr = "10.0.9.0/24",  az = "us-east-1a" },
    { name = "subnet-10", cidr = "10.0.10.0/24", az = "us-east-1b" },
    { name = "subnet-11", cidr = "10.0.11.0/24", az = "us-east-1c" },
    { name = "subnet-12", cidr = "10.0.12.0/24", az = "us-east-1a" },
    { name = "subnet-13", cidr = "10.0.13.0/24", az = "us-east-1b" },
    { name = "subnet-14", cidr = "10.0.14.0/24", az = "us-east-1c" },
    { name = "subnet-15", cidr = "10.0.15.0/24", az = "us-east-1a" }
  ]
}

# VPC Configuration
resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  instance_tenancy                 = "default"
  assign_generated_ipv6_cidr_block = true
  enable_dns_hostnames             = true
  enable_dns_support               = true

  tags = {
    Name = "my-deploy-me-vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "igw-deploy-me"
  }
}

# Subnets Configuration (16 Subnets)
resource "aws_subnet" "subnets" {
  for_each = { for s in var.subnets_config : s.name => s }

  vpc_id                  = aws_vpc.main.id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = false

  tags = {
    Name = each.value.name
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "eip-deploy-me"
  }
}

# NAT Gateway in the first private subnet (subnet-0)
resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.subnets["subnet-0"].id

  tags = {
    Name = "deployme-natgw"
  }

  depends_on = [aws_internet_gateway.igw]
}

# 1. Private Route Table (for 8 private subnets: subnet-0 to subnet-7)
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "rt-private-deploy-me"
  }
}

# Set Private Route Table as the Main Route Table for the VPC
resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id
}

# Private Subnets Associations
locals {
  private_subnet_names = [
    "subnet-0", "subnet-1", "subnet-2", "subnet-3",
    "subnet-4", "subnet-5", "subnet-6", "subnet-7"
  ]
  public_subnet_names = [
    "subnet-8", "subnet-9", "subnet-10", "subnet-11"
  ]
  spare_subnet_names = [
    "subnet-12", "subnet-13", "subnet-14", "subnet-15"
  ]
}

resource "aws_route_table_association" "private" {
  for_each       = toset(locals.private_subnet_names)
  subnet_id      = aws_subnet.subnets[each.value].id
  route_table_id = aws_route_table.private.id
}

# 2. Public Route Table (for 4 public subnets: subnet-8 to subnet-11)
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "rt-public-deploy-me"
  }
}

resource "aws_route_table_association" "public" {
  for_each       = toset(locals.public_subnet_names)
  subnet_id      = aws_subnet.subnets[each.value].id
  route_table_id = aws_route_table.public.id
}

# 3. Spare Route Table (for 4 spare subnets: subnet-12 to subnet-15)
resource "aws_route_table" "spare" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "rt-spare-deploy-me"
  }
}

resource "aws_route_table_association" "spare" {
  for_each       = toset(locals.spare_subnet_names)
  subnet_id      = aws_subnet.subnets[each.value].id
  route_table_id = aws_route_table.spare.id
}

# Security Group
resource "aws_security_group" "allow_web_traffic" {
  name        = "allow_web_traffic"
  description = "Allow inbound HTTP/HTTPS from anywhere, SSH from VPC CIDR, and outbound to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Outbound traffic restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "allow_web_traffic"
  }
}

# Output
output "server_public_ip" {
  description = "The public IP address allocated for the NAT Gateway"
  value       = aws_eip.nat.public_ip
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# --------------------------------------------------------------------------------------------------
# INPUT VARIABLES
# --------------------------------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region for provisioning resources."
  default     = "us-east-1"
}

variable "enable" {
  type        = bool
  description = "Flag to enable or disable the creation of security group resources."
  default     = true
}

variable "name" {
  type        = string
  description = "Name identifier for the resource label."
  default     = "app"
}

variable "environment" {
  type        = string
  description = "Environment identifier (e.g. dev, prod, staging)."
  default     = "dev"
}

variable "managedby" {
  type        = string
  description = "Entity responsible for managing the resources."
  default     = "opsstation"
}

variable "label_order" {
  type        = list(string)
  description = "Order in which label components are stitched together."
  default     = ["name", "environment"]
}

variable "repository" {
  type        = string
  description = "Repository source URL tag."
  default     = "https://github.com/opsstation/terraform-aws-security_group"
}

variable "vpc_id" {
  type        = string
  description = "VPC ID where the security group is created. If empty, uses the default VPC."
  default     = ""
}

variable "description" {
  type        = string
  description = "Description for the security group."
  default     = "Security group managed by Terraform"
}

variable "new_sg" {
  type        = bool
  description = "Flag to decide whether to create a new security group or use an existing one."
  default     = true
}

variable "existing_sg_id" {
  type        = string
  description = "ID of an existing security group to attach rules to if new_sg is false."
  default     = ""
}

# Prefix List Variables
variable "prefix_list_enabled" {
  type        = bool
  description = "Flag to enable creation of an EC2 managed prefix list."
  default     = false
}

variable "prefix_list_address_family" {
  type        = string
  description = "Address family for the prefix list (IPv4 or IPv6)."
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  type        = number
  description = "Maximum number of entries allowed in the prefix list."
  default     = 5
}

variable "prefix_list_entries" {
  type = list(object({
    cidr        = string
    description = optional(string, "")
  }))
  description = "List of CIDR entries to populate into the prefix list."
  default     = []
}

variable "prefix_list_ids" {
  type        = list(string)
  description = "External prefix list IDs to attach to security group rules if not creating a new one."
  default     = []
}

# Security Group Rules Definitions
variable "ingress_cidr_rules" {
  type = list(object({
    from_port        = number
    to_port          = number
    protocol         = string
    cidr_blocks      = optional(list(string), [])
    ipv6_cidr_blocks = optional(list(string), [])
    description      = optional(string, "")
  }))
  description = "List of ingress CIDR rules."
  default     = []
}

variable "egress_cidr_rules" {
  type = list(object({
    from_port        = number
    to_port          = number
    protocol         = string
    cidr_blocks      = optional(list(string), [])
    ipv6_cidr_blocks = optional(list(string), [])
    description      = optional(string, "")
  }))
  description = "List of egress CIDR rules."
  default = [
    {
      from_port   = 0
      to_port     = 0
      protocol    = "-1"
      cidr_blocks = ["0.0.0.0/0"]
      description = "Allow all outbound traffic"
    }
  ]
}

variable "ingress_self_rules" {
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = optional(string, "")
  }))
  description = "List of self-referencing ingress rules."
  default     = []
}

variable "egress_self_rules" {
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = optional(string, "")
  }))
  description = "List of self-referencing egress rules."
  default     = []
}

variable "ingress_source_sg_rules" {
  type = list(object({
    from_port                = number
    to_port                  = number
    protocol                 = string
    source_security_group_id = string
    description              = optional(string, "")
  }))
  description = "List of ingress rules referencing other source security groups."
  default     = []
}

variable "egress_source_sg_rules" {
  type = list(object({
    from_port                = number
    to_port                  = number
    protocol                 = string
    source_security_group_id = string
    description              = optional(string, "")
  }))
  description = "List of egress rules referencing other source security groups."
  default     = []
}

variable "ingress_prefix_list_rules" {
  type = list(object({
    from_port       = number
    to_port         = number
    protocol        = string
    prefix_list_ids = optional(list(string), [])
    description     = optional(string, "")
  }))
  description = "List of ingress rules referencing prefix list IDs."
  default     = []
}

variable "egress_prefix_list_rules" {
  type = list(object({
    from_port       = number
    to_port         = number
    protocol        = string
    prefix_list_ids = optional(list(string), [])
    description     = optional(string, "")
  }))
  description = "List of egress rules referencing prefix list IDs."
  default     = []
}

# --------------------------------------------------------------------------------------------------
# DATA SOURCES
# --------------------------------------------------------------------------------------------------
data "aws_vpc" "default" {
  count   = var.vpc_id == "" ? 1 : 0
  default = true
}

# --------------------------------------------------------------------------------------------------
# MODULE: LABELS
# --------------------------------------------------------------------------------------------------
module "labels" {
  source      = "git::git@github.com:opsstation/terraform-aws-labels.git?ref=v1.0.0"
  name        = var.name
  environment = var.environment
  managedby   = var.managedby
  label_order = var.label_order
  repository  = var.repository
}

# --------------------------------------------------------------------------------------------------
# MANAGED PREFIX LIST
# --------------------------------------------------------------------------------------------------
resource "aws_ec2_managed_prefix_list" "prefix_list" {
  count          = var.enable && var.prefix_list_enabled && length(var.prefix_list_ids) == 0 ? 1 : 0
  name           = format("%s-prefix-list", module.labels.id)
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = lookup(entry.value, "description", null)
    }
  }

  tags = merge(
    module.labels.tags,
    {
      "Name" = format("%s-prefix-list", module.labels.id)
    }
  )
}

# --------------------------------------------------------------------------------------------------
# SECURITY GROUP
# --------------------------------------------------------------------------------------------------
locals {
  target_vpc_id = var.vpc_id != "" ? var.vpc_id : try(data.aws_vpc.default[0].id, "")
  created_pl_id = try(aws_ec2_managed_prefix_list.prefix_list[0].id, null)
  effective_pl_ids = (
    length(var.prefix_list_ids) > 0 ? var.prefix_list_ids :
    (local.created_pl_id != null ? [local.created_pl_id] : [])
  )
}

resource "aws_security_group" "default" {
  count       = var.enable && var.new_sg ? 1 : 0
  name        = format("%s-sg", module.labels.id)
  description = var.description
  vpc_id      = local.target_vpc_id

  tags = merge(
    module.labels.tags,
    {
      "Name" = format("%s-sg", module.labels.id)
    }
  )

  lifecycle {
    create_before_destroy = true
  }
}

locals {
  security_group_id = var.enable ? (
    var.new_sg ? try(aws_security_group.default[0].id, "") : var.existing_sg_id
  ) : ""
}

# --------------------------------------------------------------------------------------------------
# SECURITY GROUP RULES
# --------------------------------------------------------------------------------------------------

# CIDR Ingress Rules
resource "aws_security_group_rule" "ingress_cidr" {
  count             = var.enable && length(local.security_group_id) > 0 ? length(var.ingress_cidr_rules) : 0
  type              = "ingress"
  security_group_id = local.security_group_id
  from_port         = var.ingress_cidr_rules[count.index].from_port
  to_port           = var.ingress_cidr_rules[count.index].to_port
  protocol          = var.ingress_cidr_rules[count.index].protocol
  cidr_blocks       = length(lookup(var.ingress_cidr_rules[count.index], "cidr_blocks", [])) > 0 ? var.ingress_cidr_rules[count.index].cidr_blocks : null
  ipv6_cidr_blocks  = length(lookup(var.ingress_cidr_rules[count.index], "ipv6_cidr_blocks", [])) > 0 ? var.ingress_cidr_rules[count.index].ipv6_cidr_blocks : null
  description       = lookup(var.ingress_cidr_rules[count.index], "description", null)
}

# CIDR Egress Rules
resource "aws_security_group_rule" "egress_cidr" {
  count             = var.enable && length(local.security_group_id) > 0 ? length(var.egress_cidr_rules) : 0
  type              = "egress"
  security_group_id = local.security_group_id
  from_port         = var.egress_cidr_rules[count.index].from_port
  to_port           = var.egress_cidr_rules[count.index].to_port
  protocol          = var.egress_cidr_rules[count.index].protocol
  cidr_blocks       = length(lookup(var.egress_cidr_rules[count.index], "cidr_blocks", [])) > 0 ? var.egress_cidr_rules[count.index].cidr_blocks : null
  ipv6_cidr_blocks  = length(lookup(var.egress_cidr_rules[count.index], "ipv6_cidr_blocks", [])) > 0 ? var.egress_cidr_rules[count.index].ipv6_cidr_blocks : null
  description       = lookup(var.egress_cidr_rules[count.index], "description", null)
}

# Self Ingress Rules
resource "aws_security_group_rule" "ingress_self" {
  count             = var.enable && length(local.security_group_id) > 0 ? length(var.ingress_self_rules) : 0
  type              = "ingress"
  security_group_id = local.security_group_id
  from_port         = var.ingress_self_rules[count.index].from_port
  to_port           = var.ingress_self_rules[count.index].to_port
  protocol          = var.ingress_self_rules[count.index].protocol
  self              = true
  description       = lookup(var.ingress_self_rules[count.index], "description", null)
}

# Self Egress Rules
resource "aws_security_group_rule" "egress_self" {
  count             = var.enable && length(local.security_group_id) > 0 ? length(var.egress_self_rules) : 0
  type              = "egress"
  security_group_id = local.security_group_id
  from_port         = var.egress_self_rules[count.index].from_port
  to_port           = var.egress_self_rules[count.index].to_port
  protocol          = var.egress_self_rules[count.index].protocol
  self              = true
  description       = lookup(var.egress_self_rules[count.index], "description", null)
}

# Source Security Group Ingress Rules
resource "aws_security_group_rule" "ingress_source_sg" {
  count                    = var.enable && length(local.security_group_id) > 0 ? length(var.ingress_source_sg_rules) : 0
  type                     = "ingress"
  security_group_id        = local.security_group_id
  from_port                = var.ingress_source_sg_rules[count.index].from_port
  to_port                  = var.ingress_source_sg_rules[count.index].to_port
  protocol                 = var.ingress_source_sg_rules[count.index].protocol
  source_security_group_id = var.ingress_source_sg_rules[count.index].source_security_group_id
  description              = lookup(var.ingress_source_sg_rules[count.index], "description", null)
}

# Source Security Group Egress Rules
resource "aws_security_group_rule" "egress_source_sg" {
  count                    = var.enable && length(local.security_group_id) > 0 ? length(var.egress_source_sg_rules) : 0
  type                     = "egress"
  security_group_id        = local.security_group_id
  from_port                = var.egress_source_sg_rules[count.index].from_port
  to_port                  = var.egress_source_sg_rules[count.index].to_port
  protocol                 = var.egress_source_sg_rules[count.index].protocol
  source_security_group_id = var.egress_source_sg_rules[count.index].source_security_group_id
  description              = lookup(var.egress_source_sg_rules[count.index], "description", null)
}

# Prefix List Ingress Rules
resource "aws_security_group_rule" "ingress_prefix_list" {
  count             = var.enable && length(local.security_group_id) > 0 ? length(var.ingress_prefix_list_rules) : 0
  type              = "ingress"
  security_group_id = local.security_group_id
  from_port         = var.ingress_prefix_list_rules[count.index].from_port
  to_port           = var.ingress_prefix_list_rules[count.index].to_port
  protocol          = var.ingress_prefix_list_rules[count.index].protocol
  prefix_list_ids   = length(lookup(var.ingress_prefix_list_rules[count.index], "prefix_list_ids", [])) > 0 ? var.ingress_prefix_list_rules[count.index].prefix_list_ids : local.effective_pl_ids
  description       = lookup(var.ingress_prefix_list_rules[count.index], "description", null)
}

# Prefix List Egress Rules
resource "aws_security_group_rule" "egress_prefix_list" {
  count             = var.enable && length(local.security_group_id) > 0 ? length(var.egress_prefix_list_rules) : 0
  type              = "egress"
  security_group_id = local.security_group_id
  from_port         = var.egress_prefix_list_rules[count.index].from_port
  to_port           = var.egress_prefix_list_rules[count.index].to_port
  protocol          = var.egress_prefix_list_rules[count.index].protocol
  prefix_list_ids   = length(lookup(var.egress_prefix_list_rules[count.index], "prefix_list_ids", [])) > 0 ? var.egress_prefix_list_rules[count.index].prefix_list_ids : local.effective_pl_ids
  description       = lookup(var.egress_prefix_list_rules[count.index], "description", null)
}

# --------------------------------------------------------------------------------------------------
# OUTPUTS
# --------------------------------------------------------------------------------------------------
output "security_group_id" {
  description = "The ID of the security group provisioned or targeted."
  value       = local.security_group_id
}

output "security_group_arn" {
  description = "The ARN of the provisioned security group."
  value       = try(aws_security_group.default[0].arn, "")
}

output "prefix_list_id" {
  description = "The ID of the EC2 managed prefix list if created."
  value       = try(aws_ec2_managed_prefix_list.prefix_list[0].id, "")
}

output "prefix_list_arn" {
  description = "The ARN of the EC2 managed prefix list if created."
  value       = try(aws_ec2_managed_prefix_list.prefix_list[0].arn, "")
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region for resources"
  default     = "us-east-1"
}

variable "environment_name" {
  type        = string
  description = "Environment identifier used for naming conventions"
  default     = "dev"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# IAM Account Password Policy
# -----------------------------------------------------------------------------
resource "aws_iam_account_password_policy" "strict_policy" {
  minimum_password_length        = 14
  require_lowercase_characters   = true
  require_uppercase_characters   = true
  require_numbers                = true
  require_symbols                = false
  allow_users_to_change_password = true
  max_password_age               = 90
  password_reuse_prevention      = 3
}

# -----------------------------------------------------------------------------
# ECS Task Role
# -----------------------------------------------------------------------------
resource "aws_iam_role" "ecs_task_role" {
  name = "ecs-task-role-for-${var.environment_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_secrets_manager" {
  role       = aws_iam_role.ecs_task_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/SecretsManagerReadWrite"
}

resource "aws_iam_role_policy_attachment" "ecs_task_s3" {
  role       = aws_iam_role.ecs_task_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_role_policy" "ecs_task_ssm_messages" {
  name = "ecs-task-ssm-messages-inline"
  role = aws_iam_role.ecs_task_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ssmmessages:CreateControlChannel",
          "ssmmessages:CreateDataChannel",
          "ssmmessages:OpenControlChannel",
          "ssmmessages:OpenDataChannel"
        ]
        Resource = "*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# ECS Execution Role
# -----------------------------------------------------------------------------
resource "aws_iam_role" "ecs_execution_role" {
  name = "ecs-execution-role-for-${var.environment_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_execution_task_policy" {
  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy_attachment" "ecs_execution_container_service" {
  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

resource "aws_iam_role_policy" "ecs_execution_secrets_kms" {
  name = "ecs-execution-secrets-kms-inline"
  role = aws_iam_role.ecs_execution_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# EventBridge ECS Events Role
# -----------------------------------------------------------------------------
resource "aws_iam_role" "ecs_events_role" {
  name = "ecs_events_role-for-${var.environment_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_events_task_policy" {
  role       = aws_iam_role.ecs_events_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy_attachment" "ecs_events_container_service" {
  role       = aws_iam_role.ecs_events_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

# -----------------------------------------------------------------------------
# Lambda Public Role
# -----------------------------------------------------------------------------
resource "aws_iam_role" "lambda_public_role" {
  name = "lambda-public-role-${var.environment_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "lambda_public_logging" {
  name = "lambda-public-cw-logging"
  role = aws_iam_role.lambda_public_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:logs:*:*:*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Lambda VPC Role
# -----------------------------------------------------------------------------
resource "aws_iam_role" "lambda_vpc_role" {
  name = "lambda-vpc-role-${var.environment_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "lambda_vpc_policy" {
  name = "lambda-vpc-extended-policy"
  role = aws_iam_role.lambda_vpc_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:logs:*:*:*"
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:AssignPrivateIpAddresses",
          "ec2:UnassignPrivateIpAddresses"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction"
        ]
        Resource = "*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Step Functions State Machine Role
# -----------------------------------------------------------------------------
resource "aws_iam_role" "step_functions_role" {
  name = "step-functions-role-${var.environment_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "states.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "step_functions_policy" {
  name = "step-functions-service-policy"
  role = aws_iam_role.step_functions_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogDelivery",
          "logs:CreateLogStream",
          "logs:GetLogDelivery",
          "logs:UpdateLogDelivery",
          "logs:DeleteLogDelivery",
          "logs:ListLogDeliveries",
          "logs:PutLogEvents",
          "logs:PutResourcePolicy",
          "logs:DescribeResourcePolicies",
          "logs:DescribeLogGroups"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "cloudwatch:DescribeAlarms"
        ]
        Resource = "*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# EventBridge Execution Role (Targeting Step Functions)
# -----------------------------------------------------------------------------
resource "aws_iam_role" "eventbridge_sfn_role" {
  name = "eventbridge-sfn-execution-role-${var.environment_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "eventbridge_sfn_policy" {
  name = "eventbridge-sfn-execution-policy"
  role = aws_iam_role.eventbridge_sfn_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "states:StartExecution"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:states:*:${data.aws_caller_identity.current.account_id}:stateMachine:*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Governance: Developers Limited MFA Policy
# -----------------------------------------------------------------------------
resource "aws_iam_policy" "developers_policy_limited_mfa" {
  name        = "developers-policy-limited-mfa"
  description = "Developer access with self-service credential management and MFA enforcement"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSelfServiceCredentials"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:GetUser",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice",
          "iam:DeleteVirtualMFADevice",
          "iam:DeactivateMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ListMFADevices",
          "iam:CreateAccessKey",
          "iam:UpdateAccessKey",
          "iam:DeleteAccessKey",
          "iam:ListAccessKeys",
          "iam:UploadSSHPublicKey",
          "iam:GetSSHPublicKey",
          "iam:UpdateSSHPublicKey",
          "iam:DeleteSSHPublicKey",
          "iam:ListSSHPublicKeys"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}",
          "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}"
        ]
      },
      {
        Sid    = "AllowIAMAccountListing"
        Effect = "Allow"
        Action = [
          "iam:GetAccountPasswordPolicy",
          "iam:ListAccountAliases"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowS3Operations"
        Effect = "Allow"
        Action = [
          "s3:ListAllMyBuckets",
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowSecretsManagerReadWithMFA"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
          "secretsmanager:ListSecrets"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "AllowCloudWatchAndECSReadWithMFA"
        Effect = "Allow"
        Action = [
          "cloudwatch:Describe*",
          "cloudwatch:Get*",
          "cloudwatch:List*",
          "logs:Describe*",
          "logs:Get*",
          "logs:FilterLogEvents",
          "ecs:Describe*",
          "ecs:List*"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "DenyAllExceptSelfManagementWithoutMFA"
        Effect = "Deny"
        NotAction = [
          "iam:ChangePassword",
          "iam:GetUser",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ListMFADevices",
          "iam:GetAccountPasswordPolicy",
          "iam:ListAccountAliases"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Governance: Billing Limited MFA Policy
# -----------------------------------------------------------------------------
resource "aws_iam_policy" "billing_policy_limited_mfa" {
  name        = "billing-policy-limited-mfa"
  description = "Billing access requiring MFA, with self-service MFA and password management"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSelfServiceCredentials"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:GetUser",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice",
          "iam:DeleteVirtualMFADevice",
          "iam:DeactivateMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ListMFADevices"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}",
          "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}"
        ]
      },
      {
        Sid    = "AllowIAMAccountListing"
        Effect = "Allow"
        Action = [
          "iam:GetAccountPasswordPolicy",
          "iam:ListAccountAliases"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowBillingOperationsWithMFA"
        Effect = "Allow"
        Action = [
          "aws-portal:*",
          "billing:*",
          "budgets:*",
          "ce:*",
          "cur:*",
          "payments:*",
          "tax:*"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "DenyBillingWithoutMFA"
        Effect = "Deny"
        NotAction = [
          "iam:ChangePassword",
          "iam:GetUser",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ListMFADevices",
          "iam:GetAccountPasswordPolicy",
          "iam:ListAccountAliases"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "ecs_task_role_arn" {
  description = "ARN of the ECS Task IAM Role"
  value       = aws_iam_role.ecs_task_role.arn
}

output "ecs_execution_role_arn" {
  description = "ARN of the ECS Execution IAM Role"
  value       = aws_iam_role.ecs_execution_role.arn
}

output "ecs_events_role_arn" {
  description = "ARN of the ECS Events IAM Role"
  value       = aws_iam_role.ecs_events_role.arn
}

output "lambda_public_role_arn" {
  description = "ARN of the public Lambda IAM Role"
  value       = aws_iam_role.lambda_public_role.arn
}

output "lambda_vpc_role_arn" {
  description = "ARN of the VPC Lambda IAM Role"
  value       = aws_iam_role.lambda_vpc_role.arn
}

output "step_functions_role_arn" {
  description = "ARN of the Step Functions execution role"
  value       = aws_iam_role.step_functions_role.arn
}

output "eventbridge_sfn_role_arn" {
  description = "ARN of the EventBridge to Step Functions execution role"
  value       = aws_iam_role.eventbridge_sfn_role.arn
}

output "developers_policy_limited_mfa_arn" {
  description = "ARN of the Developer limited MFA policy"
  value       = aws_iam_policy.developers_policy_limited_mfa.arn
}

output "billing_policy_limited_mfa_arn" {
  description = "ARN of the Billing limited MFA policy"
  value       = aws_iam_policy.billing_policy_limited_mfa.arn
}
```

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "The AWS Region where resources will be deployed."
  default     = "us-east-1"
}

variable "environment" {
  type        = string
  description = "Deployment environment name."
  default     = "dev"
}

variable "codestar_connection_providers" {
  type = map(object({
    provider_type = string
    endpoint_url  = optional(string)
  }))
  description = "Map of CodeStar Connections to configure (e.g. GitHub, Bitbucket, GitHubEnterpriseServer)."
  default = {
    "github" = {
      provider_type = "GitHub"
      endpoint_url  = null
    }
  }
}

variable "config" {
  type        = string
  description = "YAML configuration string defining pipelines, sources, triggers, and builds."
  default     = <<-EOT
    pipelines:
      service-api:
        source_provider: "CodeCommit"
        repository: "service-api"
        branch: "main"
        build_project: "service-api-build"
        enable_approval: true
        approval_sns_topic_arn: ""
        schedule: "cron(0 0 * * ? *)"
        tag_pattern: ""
      worker-daemon:
        source_provider: "CodeStar"
        repository: "my-org/worker-daemon"
        branch: "master"
        codestar_connection_key: "github"
        build_project: "worker-daemon-build"
        enable_approval: false
        schedule: ""
        tag_pattern: ""
  EOT
}

# ---------------------------------------------------------------------------------------------------------------------
# LOCAL DEFINITIONS
# ---------------------------------------------------------------------------------------------------------------------

locals {
  parsed_config = yamldecode(var.config)
  pipelines     = try(local.parsed_config.pipelines, {})

  # Filter pipelines that have schedule triggers
  scheduled_pipelines = {
    for name, pipe in local.pipelines : name => pipe
    if try(pipe.schedule, "") != ""
  }

  # Filter pipelines with CodeCommit branch triggers
  codecommit_branch_pipelines = {
    for name, pipe in local.pipelines : name => pipe
    if try(pipe.source_provider, "") == "CodeCommit" && try(pipe.branch, "") != ""
  }

  # Filter pipelines with CodeCommit tag triggers
  codecommit_tag_pipelines = {
    for name, pipe in local.pipelines : name => pipe
    if try(pipe.source_provider, "") == "CodeCommit" && try(pipe.tag_pattern, "") != ""
  }
}

# Data lookup for current AWS account identity
data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------------------------------------------------
# S3 ARTIFACT & BUILD CACHE BUCKETS
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket" "pipeline_artifacts" {
  bucket_prefix = "terraforest-artifacts-${var.environment}-"
  force_destroy = true

  tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
    Purpose     = "CI/CD Artifact Storage"
  }
}

resource "aws_s3_bucket_versioning" "pipeline_artifacts" {
  bucket = aws_s3_bucket.pipeline_artifacts.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "pipeline_artifacts" {
  bucket = aws_s3_bucket.pipeline_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "pipeline_artifacts" {
  bucket                  = aws_s3_bucket.pipeline_artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket" "build_cache" {
  bucket_prefix = "terraforest-cache-${var.environment}-"
  force_destroy = true

  tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
    Purpose     = "CodeBuild Shared Cache"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "build_cache" {
  bucket                  = aws_s3_bucket.build_cache.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------------------------------------------------
# CODESTAR CONNECTIONS
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_codestarconnections_connection" "connections" {
  for_each = var.codestar_connection_providers

  name              = "${each.key}-conn-${var.environment}"
  provider_type     = each.value.provider_type
  host_arn          = each.value.endpoint_url != null ? each.value.endpoint_url : null

  tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM ROLE FOR CODEPIPELINE (PATH /terraforest/)
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "codepipeline_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codepipeline.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codepipeline_role" {
  name_prefix        = "codepipeline-runner-"
  path               = "/terraforest/"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_assume_role.json

  tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

data "aws_iam_policy_document" "codepipeline_policy" {
  statement {
    sid       = "S3ArtifactStorageAccess"
    effect    = "Allow"
    actions   = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetBucketVersioning",
      "s3:PutObject",
      "s3:PutObjectAcl"
    ]
    resources = [
      aws_s3_bucket.pipeline_artifacts.arn,
      "${aws_s3_bucket.pipeline_artifacts.arn}/*",
      aws_s3_bucket.build_cache.arn,
      "${aws_s3_bucket.build_cache.arn}/*"
    ]
  }

  statement {
    sid       = "CodeStarConnectionAccess"
    effect    = "Allow"
    actions   = ["codestar-connections:UseConnection"]
    resources = ["*"]
  }

  statement {
    sid     = "CodeCommitAccess"
    effect  = "Allow"
    actions = [
      "codecommit:GetBranch",
      "codecommit:GetCommit",
      "codecommit:UploadArchive",
      "codecommit:GetUploadArchiveStatus",
      "codecommit:CancelUploadArchive"
    ]
    resources = ["*"]
  }

  statement {
    sid     = "CodeBuildExecution"
    effect  = "Allow"
    actions = [
      "codebuild:BatchGetBuilds",
      "codebuild:StartBuild"
    ]
    resources = ["*"]
  }

  statement {
    sid     = "ECRAccess"
    effect  = "Allow"
    actions = [
      "ecr:DescribeImages",
      "ecr:GetAuthorizationToken",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage"
    ]
    resources = ["*"]
  }

  statement {
    sid     = "LambdaActionExecution"
    effect  = "Allow"
    actions = [
      "lambda:InvokeFunction",
      "lambda:ListFunctions"
    ]
    resources = ["*"]
  }

  statement {
    sid     = "SNSManualApproval"
    effect  = "Allow"
    actions = ["sns:Publish"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "codepipeline_permissions" {
  name   = "terraforest-codepipeline-policy"
  role   = aws_iam_role.codepipeline_role.id
  policy = data.aws_iam_policy_document.codepipeline_policy.json
}

# ---------------------------------------------------------------------------------------------------------------------
# SAMPLE CODEBUILD PROJECT FOR PIPELINES
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "codebuild_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codebuild_role" {
  name_prefix        = "codebuild-runner-"
  path               = "/terraforest/"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role.json

  tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

resource "aws_iam_role_policy" "codebuild_policy" {
  name = "codebuild-execution-policy"
  role = aws_iam_role.codebuild_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject"
        ]
        Resource = [
          "${aws_s3_bucket.pipeline_artifacts.arn}/*",
          "${aws_s3_bucket.build_cache.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_codebuild_project" "build_projects" {
  for_each     = local.pipelines
  name         = each.value.build_project
  description  = "Build stage for pipeline ${each.key}"
  service_role = aws_iam_role.codebuild_role.arn

  artifacts {
    type = "CODEPIPELINE"
  }

  cache {
    type     = "S3"
    location = "${aws_s3_bucket.build_cache.bucket}/${each.key}"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    privileged_mode             = true
    image_pull_credentials_type = "CODEBUILD"
  }

  source {
    type = "CODEPIPELINE"
  }

  tags = {
    Pipeline    = each.key
    Environment = var.environment
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# CODEPIPELINE PROVISIONING
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_codepipeline" "pipeline" {
  for_each = local.pipelines

  name     = each.key
  role_arn = aws_iam_role.codepipeline_role.arn

  artifact_store {
    location = aws_s3_bucket.pipeline_artifacts.bucket
    type     = "S3"
  }

  stage {
    name = "Source"

    action {
      name             = "SourceAction"
      category         = "Source"
      owner            = each.value.source_provider == "CodeStar" ? "AWS" : "AWS"
      provider         = each.value.source_provider == "CodeStar" ? "CodeStarSourceConnection" : "CodeCommit"
      version          = "1"
      output_artifacts = ["source_output"]

      configuration = each.value.source_provider == "CodeStar" ? {
        ConnectionArn    = aws_codestarconnections_connection.connections[try(each.value.codestar_connection_key, "github")].arn
        FullRepositoryId = each.value.repository
        BranchName       = each.value.branch
      } : {
        RepositoryName = each.value.repository
        BranchName     = each.value.branch
      }
    }
  }

  dynamic "stage" {
    for_each = try(each.value.enable_approval, false) ? [1] : []
    content {
      name = "Manual-Approval"

      action {
        name     = "ApprovalAction"
        category = "Approval"
        owner    = "AWS"
        provider = "Manual"
        version  = "1"

        configuration = {
          CustomData = "Approval to proceed with deployment to ${var.environment}"
        }
      }
    }
  }

  stage {
    name = "Build"

    action {
      name             = "BuildAction"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      input_artifacts  = ["source_output"]
      output_artifacts = ["build_output"]
      version          = "1"

      configuration = {
        ProjectName = aws_codebuild_project.build_projects[each.key].name
      }
    }
  }

  tags = {
    PipelineName = each.key
    Environment  = var.environment
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# DEDICATED EVENTBRIDGE ROLES (PREFIX: terrabits-)
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "events_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eventbridge_pipeline_role" {
  for_each           = local.pipelines
  name               = "terrabits-${each.key}-trigger"
  assume_role_policy = data.aws_iam_policy_document.events_assume_role.json

  tags = {
    Pipeline    = each.key
    Environment = var.environment
  }
}

resource "aws_iam_role_policy" "eventbridge_pipeline_policy" {
  for_each = local.pipelines
  name     = "terrabits-${each.key}-trigger-policy"
  role     = aws_iam_role.eventbridge_pipeline_role[each.key].id

  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["codepipeline:StartPipelineExecution"]
        Resource = aws_codepipeline.pipeline[each.key].arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# EVENTBRIDGE TRIGGER RULES (CODECOMMIT BRANCH & SCHEDULE)
# ---------------------------------------------------------------------------------------------------------------------

# CodeCommit Branch Push Trigger
resource "aws_cloudwatch_event_rule" "codecommit_branch_rule" {
  for_each    = local.codecommit_branch_pipelines
  name        = "terrabits-${each.key}-branch-trigger"
  description = "Trigger pipeline ${each.key} on CodeCommit branch push"

  event_pattern = jsonencode({
    source      = ["aws.codecommit"]
    detail-type = ["CodeCommit Repository State Change"]
    resources   = ["arn:aws:codecommit:${var.aws_region}:${data.aws_caller_identity.current.account_id}:${each.value.repository}"]
    detail      = {
      event         = ["referenceCreated", "referenceUpdated"]
      referenceType = ["branch"]
      referenceName = [each.value.branch]
    }
  })

  tags = {
    Pipeline = each.key
  }
}

resource "aws_cloudwatch_event_target" "codecommit_branch_target" {
  for_each  = local.codecommit_branch_pipelines
  rule      = aws_cloudwatch_event_rule.codecommit_branch_rule[each.key].name
  target_id = "CodePipelineTarget-${each.key}"
  arn       = aws_codepipeline.pipeline[each.key].arn
  role_arn  = aws_iam_role.eventbridge_pipeline_role[each.key].arn
}

# Schedule-Based Trigger
resource "aws_cloudwatch_event_rule" "schedule_rule" {
  for_each            = local.scheduled_pipelines
  name                = "terrabits-${each.key}-sched-trigger"
  description         = "Cron trigger for pipeline ${each.key}"
  schedule_expression = each.value.schedule

  tags = {
    Pipeline = each.key
  }
}

resource "aws_cloudwatch_event_target" "schedule_target" {
  for_each  = local.scheduled_pipelines
  rule      = aws_cloudwatch_event_rule.schedule_rule[each.key].name
  target_id = "CodePipelineCronTarget-${each.key}"
  arn       = aws_codepipeline.pipeline[each.key].arn
  role_arn  = aws_iam_role.eventbridge_pipeline_role[each.key].arn
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "artifact_bucket_id" {
  description = "The S3 bucket ID used for storing pipeline artifacts."
  value       = aws_s3_bucket.pipeline_artifacts.id
}

output "build_cache_bucket_id" {
  description = "The S3 bucket ID used for CodeBuild caching."
  value       = aws_s3_bucket.build_cache.id
}

output "pipeline_arns" {
  description = "ARNs of the provisioned CodePipelines."
  value       = { for k, v in aws_codepipeline.pipeline : k => v.arn }
}

output "pipeline_role_arn" {
  description = "The ARN of the central IAM role used by CodePipeline under path /terraforest/."
  value       = aws_iam_role.codepipeline_role.arn
}

output "eventbridge_role_arns" {
  description = "ARNs of the created terrabits-prefixed EventBridge execution roles."
  value       = { for k, v in aws_iam_role.eventbridge_pipeline_role : k => v.arn }
}

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "The AWS region to deploy resources into."
  default     = "us-east-1"
}

variable "server_name" {
  type        = string
  description = "Name identifier for the SFTP Server and associated resources."
  default     = "sftp-efs-server"
}

variable "efs_performance_mode" {
  type        = string
  description = "The EFS performance mode. Defaults to generalPurpose."
  default     = "generalPurpose"
}

variable "efs_kms_key_arn" {
  type        = string
  description = "ARN for the KMS key to encrypt the EFS file system. Uses default AWS managed key if null."
  default     = null
}

variable "vpc_id" {
  type        = string
  description = "VPC ID where the SFTP server endpoint and EFS mount targets will be placed (optional)."
  default     = ""
}

variable "subnet_ids" {
  type        = list(string)
  description = "List of Subnet IDs for EFS mount targets and VPC endpoint allocation."
  default     = []
}

variable "is_public" {
  type        = bool
  description = "Whether the SFTP server endpoint in a VPC should be internet-facing (allocates EIPs)."
  default     = false
}

variable "logging_enabled" {
  type        = bool
  description = "Enable CloudWatch logging for SFTP server sessions."
  default     = true
}

variable "custom_user_role_arn" {
  type        = string
  description = "Optional ARN of a pre-existing IAM role to attach to SFTP users. If not provided, an IAM role is generated automatically."
  default     = ""
}

variable "sftp_users" {
  type = map(object({
    uid            = number
    gid            = number
    secondary_gids = optional(list(number), [])
    ssh_public_key = optional(string, "")
    restricted     = optional(bool, true)
    subfolder      = optional(string, "")
  }))
  description = "Map of SFTP users and their POSIX and SSH configurations."
  default     = {
    "sftpuser1" = {
      uid            = 1001
      gid            = 1001
      secondary_gids = []
      ssh_public_key = "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIG1lY2hpbWFsZHVtbXlwdWJsaWNrZXlmb3J0ZXN0aW5ncHVycG9zZXM= user1@example.com"
      restricted     = true
      subfolder      = "user1"
    }
  }
}

variable "additional_access_points" {
  type = map(object({
    path = string
    posix_user = object({
      uid = number
      gid = number
    })
    creation_info = optional(object({
      owner_uid   = number
      owner_gid   = number
      permissions = string
    }), null)
  }))
  description = "Additional EFS access points to configure on the file system."
  default     = {}
}

variable "tags" {
  type        = map(string)
  description = "Tags applied to all supported resources."
  default = {
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

# -----------------------------------------------------------------------------
# Amazon EFS File System
# -----------------------------------------------------------------------------

resource "aws_efs_file_system" "this" {
  creation_token   = "${var.server_name}-efs"
  performance_mode = var.efs_performance_mode
  throughput_mode  = "bursting"
  encrypted        = true
  kms_key_id       = var.efs_kms_key_arn

  tags = merge(
    var.tags,
    {
      Name = "${var.server_name}-efs"
    }
  )
}

# -----------------------------------------------------------------------------
# Security Groups (Conditional on VPC configuration)
# -----------------------------------------------------------------------------

resource "aws_security_group" "sftp" {
  count       = var.vpc_id != "" ? 1 : 0
  name        = "${var.server_name}-sftp-sg"
  description = "Security group for AWS Transfer SFTP server endpoint"
  vpc_id      = var.vpc_id

  ingress {
    description = "Allow inbound SFTP (port 22)"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(
    var.tags,
    {
      Name = "${var.server_name}-sftp-sg"
    }
  )
}

resource "aws_security_group" "efs" {
  count       = var.vpc_id != "" && length(var.subnet_ids) > 0 ? 1 : 0
  name        = "${var.server_name}-efs-sg"
  description = "Security group for EFS Mount Targets"
  vpc_id      = var.vpc_id

  ingress {
    description     = "Allow NFS traffic from SFTP endpoint"
    from_port       = 2049
    to_port         = 2049
    protocol        = "tcp"
    security_groups = [aws_security_group.sftp[0].id]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(
    var.tags,
    {
      Name = "${var.server_name}-efs-sg"
    }
  )
}

# -----------------------------------------------------------------------------
# EFS Mount Targets
# -----------------------------------------------------------------------------

resource "aws_efs_mount_target" "this" {
  count           = var.vpc_id != "" ? length(var.subnet_ids) : 0
  file_system_id  = aws_efs_file_system.this.id
  subnet_id       = var.subnet_ids[count.index]
  security_groups = [aws_security_group.efs[0].id]
}

# -----------------------------------------------------------------------------
# EFS Access Points
# -----------------------------------------------------------------------------

resource "aws_efs_access_point" "user_aps" {
  for_each       = var.sftp_users
  file_system_id = aws_efs_file_system.this.id

  posix_user {
    uid            = each.value.uid
    gid            = each.value.gid
    secondary_gids = each.value.secondary_gids
  }

  root_directory {
    path = "/${each.value.subfolder != "" ? each.value.subfolder : each.key}"
    creation_info {
      owner_uid   = each.value.uid
      owner_gid   = each.value.gid
      permissions = "0755"
    }
  }

  tags = merge(
    var.tags,
    {
      Name = "${var.server_name}-ap-${each.key}"
      User = each.key
    }
  )
}

resource "aws_efs_access_point" "additional_aps" {
  for_each       = var.additional_access_points
  file_system_id = aws_efs_file_system.this.id

  posix_user {
    uid = each.value.posix_user.uid
    gid = each.value.posix_user.gid
  }

  root_directory {
    path = each.value.path
    dynamic "creation_info" {
      for_each = each.value.creation_info != null ? [each.value.creation_info] : []
      content {
        owner_uid   = creation_info.value.owner_uid
        owner_gid   = creation_info.value.owner_gid
        permissions = creation_info.value.permissions
      }
    }
  }

  tags = merge(
    var.tags,
    {
      Name = "${var.server_name}-ap-${each.key}"
    }
  )
}

# -----------------------------------------------------------------------------
# CloudWatch Logging IAM Role
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "transfer_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

resource "aws_cloudwatch_log_group" "sftp" {
  count             = var.logging_enabled ? 1 : 0
  name              = "/aws/transfer/${var.server_name}"
  retention_in_days = 30
  tags              = var.tags
}

resource "aws_iam_role" "logging" {
  count              = var.logging_enabled ? 1 : 0
  name               = "${var.server_name}-logging-role"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json
  tags               = var.tags
}

data "aws_iam_policy_document" "logging" {
  count = var.logging_enabled ? 1 : 0
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "logging" {
  count  = var.logging_enabled ? 1 : 0
  name   = "${var.server_name}-logging-policy"
  role   = aws_iam_role.logging[0].id
  policy = data.aws_iam_policy_document.logging[0].json
}

# -----------------------------------------------------------------------------
# SFTP User IAM Role for EFS Access
# -----------------------------------------------------------------------------

resource "aws_iam_role" "user_role" {
  count              = var.custom_user_role_arn == "" ? 1 : 0
  name               = "${var.server_name}-role"
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json
  tags               = var.tags
}

data "aws_iam_policy_document" "user_efs_policy" {
  count = var.custom_user_role_arn == "" ? 1 : 0
  statement {
    effect = "Allow"
    actions = [
      "elasticfilesystem:ClientMount",
      "elasticfilesystem:ClientWrite",
      "elasticfilesystem:ClientRootAccess",
      "elasticfilesystem:DescribeMountTargets"
    ]
    resources = [aws_efs_file_system.this.arn]
  }
}

resource "aws_iam_role_policy" "user_efs_policy" {
  count  = var.custom_user_role_arn == "" ? 1 : 0
  name   = "${var.server_name}-efs-policy"
  role   = aws_iam_role.user_role[0].id
  policy = data.aws_iam_policy_document.user_efs_policy[0].json
}

locals {
  user_role_arn = var.custom_user_role_arn != "" ? var.custom_user_role_arn : aws_iam_role.user_role[0].arn
  is_vpc_type   = var.vpc_id != ""
}

# -----------------------------------------------------------------------------
# Elastic IPs for VPC Endpoint (if public VPC endpoint)
# -----------------------------------------------------------------------------

resource "aws_eip" "sftp" {
  count  = local.is_vpc_type && var.is_public ? length(var.subnet_ids) : 0
  domain = "vpc"
  tags = merge(
    var.tags,
    {
      Name = "${var.server_name}-eip-${count.index}"
    }
  )
}

# -----------------------------------------------------------------------------
# AWS Transfer Family SFTP Server
# -----------------------------------------------------------------------------

resource "aws_transfer_server" "this" {
  domain                 = "EFS"
  identity_provider_type = "SERVICE_MANAGED"
  protocols              = ["SFTP"]
  security_policy_name   = "TransferSecurityPolicy-2023-05"
  endpoint_type          = local.is_vpc_type ? "VPC" : "PUBLIC"
  logging_role           = var.logging_enabled ? aws_iam_role.logging[0].arn : null

  dynamic "endpoint_details" {
    for_each = local.is_vpc_type ? [1] : []
    content {
      vpc_id             = var.vpc_id
      subnet_ids         = var.subnet_ids
      security_group_ids = [aws_security_group.sftp[0].id]
      address_allocation_ids = var.is_public ? [
        for eip in aws_eip.sftp : eip.id
      ] : null
    }
  }

  tags = merge(
    var.tags,
    {
      Name = var.server_name
    }
  )
}

# -----------------------------------------------------------------------------
# SFTP Users
# -----------------------------------------------------------------------------

resource "aws_transfer_user" "users" {
  for_each       = var.sftp_users
  server_id      = aws_transfer_server.this.id
  user_name      = each.key
  role           = local.user_role_arn
  home_directory_type = "LOGICAL"

  home_directory_mappings {
    entry  = "/"
    target = "/${aws_efs_file_system.this.id}/${aws_efs_access_point.user_aps[each.key].id}"
  }

  posix_profile {
    uid            = each.value.uid
    gid            = each.value.gid
    secondary_gids = each.value.secondary_gids
  }

  tags = merge(
    var.tags,
    {
      Name = "${var.server_name}-${each.key}"
    }
  )
}

resource "aws_transfer_ssh_key" "keys" {
  for_each   = { for k, v in var.sftp_users : k => v if v.ssh_public_key != "" }
  server_id  = aws_transfer_server.this.id
  user_name  = aws_transfer_user.users[each.key].user_name
  body       = each.value.ssh_public_key
  depends_on = [aws_transfer_user.users]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "sftp_server_id" {
  description = "The ID of the AWS Transfer Family SFTP Server."
  value       = aws_transfer_server.this.id
}

output "sftp_server_endpoint" {
  description = "The endpoint of the AWS Transfer Family SFTP Server."
  value       = aws_transfer_server.this.endpoint
}

output "efs_file_system_id" {
  description = "The ID of the encrypted EFS File System."
  value       = aws_efs_file_system.this.id
}

output "efs_file_system_arn" {
  description = "The ARN of the encrypted EFS File System."
  value       = aws_efs_file_system.this.arn
}

output "user_access_point_ids" {
  description = "Map of user names to their assigned EFS access point IDs."
  value       = { for k, ap in aws_efs_access_point.user_aps : k => ap.id }
}
```

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

################################################################################
# Variables
################################################################################

variable "aws_region" {
  description = "AWS region to deploy resources in"
  type        = string
  default     = "us-east-1"
}

variable "create_bucket" {
  description = "Controls if S3 bucket should be created"
  type        = bool
  default     = true
}

variable "enabled" {
  description = "Secondary switch to control whether resources are created"
  type        = bool
  default     = true
}

variable "bucket" {
  description = "The name of the bucket. If omitted, Terraform will assign a random, unique name."
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Creates a unique bucket name beginning with the specified prefix."
  type        = string
  default     = null
}

variable "force_destroy" {
  description = "A boolean that indicates all objects should be deleted from the bucket so that the bucket can be destroyed without error."
  type        = bool
  default     = false
}

variable "object_lock_enabled" {
  description = "Indicates whether this bucket has an Object Lock configuration enabled."
  type        = bool
  default     = false
}

variable "object_lock_configuration" {
  description = "Map containing object lock default retention settings."
  type = object({
    mode  = optional(string)
    days  = optional(number)
    years = optional(number)
  })
  default = null
}

variable "tags" {
  description = "A mapping of tags to assign to the bucket."
  type        = map(string)
  default     = {}
}

# KMS & Encryption
variable "create_kms_key" {
  description = "Controls if a new KMS key should be created for bucket encryption (when server_side_encryption_configuration is empty)."
  type        = bool
  default     = true
}

variable "kms_key_deletion_window_in_days" {
  description = "The waiting period, specified in number of days. After the time period ends, KMS deletes the KMS key."
  type        = number
  default     = 7
}

variable "server_side_encryption_configuration" {
  description = "Map containing server-side encryption configuration to override default KMS encryption."
  type        = any
  default     = {}
}

# Access Control & Ownership
variable "acl" {
  description = "The canned ACL to apply. Conflicts with `grant`."
  type        = string
  default     = null
}

variable "grants" {
  description = "An array of ACL policy grant configurations."
  type        = any
  default     = []
}

variable "control_object_ownership" {
  description = "Whether to manage S3 Bucket Ownership Controls."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership rule. Valid values: BucketOwnerPreferred, ObjectWriter or BucketOwnerEnforced."
  type        = string
  default     = "ObjectWriter"
}

variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket."
  type        = bool
  default     = true
}

# S3 Features
variable "versioning" {
  description = "Map containing versioning configuration. Set status to 'Enabled' or 'Suspended'."
  type        = map(string)
  default     = {}
}

variable "logging" {
  description = "Map containing access logging configuration (target_bucket, target_prefix)."
  type        = map(string)
  default     = {}
}

variable "website" {
  description = "Map containing static website hosting configuration."
  type        = any
  default     = {}
}

variable "cors_rule" {
  description = "List of maps containing CORS rules."
  type        = any
  default     = []
}

variable "lifecycle_rule" {
  description = "List of maps containing lifecycle management configuration."
  type        = any
  default     = []
}

variable "replication_configuration" {
  description = "Map containing cross-region replication configuration."
  type        = any
  default     = {}
}

variable "intelligent_tiering" {
  description = "Map containing intelligent tiering configurations."
  type        = any
  default     = {}
}

variable "acceleration_status" {
  description = "Sets the accelerate configuration of an existing bucket. Can be Enabled or Suspended."
  type        = string
  default     = null
}

variable "request_payer" {
  description = "Specifies who should bear the cost of Amazon S3 data transfer. Can be BucketOwner or Requester."
  type        = string
  default     = null
}

# Bucket Policy Toggles
variable "attach_policy" {
  description = "Controls if an S3 bucket policy should be attached."
  type        = bool
  default     = false
}

variable "attach_deny_insecure_transport_policy" {
  description = "Controls if S3 bucket should deny non-SSL/insecure transport."
  type        = bool
  default     = false
}

variable "attach_require_latest_tls_policy" {
  description = "Controls if S3 bucket should require TLS 1.2 or higher."
  type        = bool
  default     = false
}

variable "attach_elb_log_delivery_policy" {
  description = "Controls if S3 bucket should permit Classic ELB log delivery."
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Controls if S3 bucket should permit ALB/NLB log delivery."
  type        = bool
  default     = false
}

variable "policy" {
  description = "A valid bucket policy JSON document to be merged into the policy."
  type        = string
  default     = null
}

################################################################################
# Data Sources
################################################################################

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

data "aws_elb_service_account" "main" {
  count = (var.create_bucket && var.enabled && (var.attach_elb_log_delivery_policy || var.attach_lb_log_delivery_policy)) ? 1 : 0
}

################################################################################
# KMS Key (Default SSE-KMS)
################################################################################

locals {
  create_bucket = var.create_bucket && var.enabled
  create_kms    = local.create_bucket && length(keys(var.server_side_encryption_configuration)) == 0 && var.create_kms_key

  # Check if policy is required
  requires_policy = local.create_bucket && (
    var.attach_policy ||
    var.attach_deny_insecure_transport_policy ||
    var.attach_require_latest_tls_policy ||
    var.attach_elb_log_delivery_policy ||
    var.attach_lb_log_delivery_policy ||
    var.policy != null
  )
}

resource "aws_kms_key" "this" {
  count                   = local.create_kms ? 1 : 0
  description             = "KMS Key for S3 bucket default encryption"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true
  tags                    = var.tags
}

resource "aws_kms_alias" "this" {
  count         = local.create_kms ? 1 : 0
  name_prefix   = "alias/s3-bucket-"
  target_key_id = aws_kms_key.this[0].key_id
}

################################################################################
# S3 Bucket
################################################################################

resource "aws_s3_bucket" "this" {
  count         = local.create_bucket ? 1 : 0
  bucket        = var.bucket
  bucket_prefix = var.bucket_prefix
  force_destroy = var.force_destroy

  object_lock_enabled = var.object_lock_enabled

  tags = var.tags
}

################################################################################
# Encryption Configuration
################################################################################

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = local.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = length(keys(var.server_side_encryption_configuration)) > 0 ? [var.server_side_encryption_configuration] : []
    content {
      dynamic "apply_server_side_encryption_by_default" {
        for_each = lookup(rule.value, "apply_server_side_encryption_by_default", null) != null ? [rule.value.apply_server_side_encryption_by_default] : []
        content {
          sse_algorithm     = apply_server_side_encryption_by_default.value.sse_algorithm
          kms_master_key_id = lookup(apply_server_side_encryption_by_default.value, "kms_master_key_id", null)
        }
      }
      bucket_key_enabled = lookup(rule.value, "bucket_key_enabled", null)
    }
  }

  dynamic "rule" {
    for_each = length(keys(var.server_side_encryption_configuration)) == 0 ? [1] : []
    content {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = local.create_kms ? aws_kms_key.this[0].arn : null
      }
      bucket_key_enabled = true
    }
  }
}

################################################################################
# Bucket Policies
################################################################################

data "aws_iam_policy_document" "combined" {
  count = local.requires_policy ? 1 : 0

  source_policy_documents = var.policy != null ? [var.policy] : []

  # Deny Insecure Transport (HTTP)
  dynamic "statement" {
    for_each = var.attach_deny_insecure_transport_policy ? [1] : []
    content {
      sid     = "DenyInsecureTransport"
      effect  = "Deny"
      actions = ["s3:*"]
      resources = [
        aws_s3_bucket.this[0].arn,
        "${aws_s3_bucket.this[0].arn}/*"
      ]
      principals {
        type        = "*"
        identifiers = ["*"]
      }
      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
    }
  }

  # Require TLS 1.2+
  dynamic "statement" {
    for_each = var.attach_require_latest_tls_policy ? [1] : []
    content {
      sid     = "DenyOutdatedTLS"
      effect  = "Deny"
      actions = ["s3:*"]
      resources = [
        aws_s3_bucket.this[0].arn,
        "${aws_s3_bucket.this[0].arn}/*"
      ]
      principals {
        type        = "*"
        identifiers = ["*"]
      }
      condition {
        test     = "NumericLessThan"
        variable = "s3:TlsVersion"
        values   = ["1.2"]
      }
    }
  }

  # ELB Log Delivery Policy
  dynamic "statement" {
    for_each = var.attach_elb_log_delivery_policy ? [1] : []
    content {
      sid     = "ELBAccessLogDelivery"
      effect  = "Allow"
      actions = ["s3:PutObject"]
      resources = [
        "${aws_s3_bucket.this[0].arn}/*"
      ]
      principals {
        type        = "AWS"
        identifiers = [data.aws_elb_service_account.main[0].arn]
      }
    }
  }

  # ALB / NLB Log Delivery Policy
  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      sid     = "AWSLogDeliveryWrite"
      effect  = "Allow"
      actions = ["s3:PutObject"]
      resources = [
        "${aws_s3_bucket.this[0].arn}/*"
      ]
      principals {
        type        = "Service"
        identifiers = ["delivery.logs.amazonaws.com"]
      }
      condition {
        test     = "StringEquals"
        variable = "s3:x-amz-acl"
        values   = ["bucket-owner-full-control"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      sid     = "AWSLogDeliveryAclCheck"
      effect  = "Allow"
      actions = ["s3:GetBucketAcl"]
      resources = [
        aws_s3_bucket.this[0].arn
      ]
      principals {
        type        = "Service"
        identifiers = ["delivery.logs.amazonaws.com"]
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count  = local.requires_policy ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json
}

################################################################################
# Ownership Controls & Public Access Block
# Note: Applied strictly after bucket policy to avoid conflicting S3 operations.
################################################################################

resource "aws_s3_bucket_ownership_controls" "this" {
  count  = (local.create_bucket && var.control_object_ownership) ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }

  depends_on = [aws_s3_bucket_policy.this]
}

resource "aws_s3_bucket_public_access_block" "this" {
  count  = local.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets

  depends_on = [
    aws_s3_bucket_policy.this,
    aws_s3_bucket_ownership_controls.this
  ]
}

################################################################################
# ACLs
################################################################################

resource "aws_s3_bucket_acl" "this" {
  count  = (local.create_bucket && (var.acl != null || length(var.grants) > 0)) ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  acl    = var.acl

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []
    content {
      dynamic "grant" {
        for_each = var.grants
        content {
          dynamic "grantee" {
            for_each = [grant.value.grantee]
            content {
              type          = grantee.value.type
              id            = lookup(grantee.value, "id", null)
              uri           = lookup(grantee.value, "uri", null)
              email_address = lookup(grantee.value, "email_address", null)
            }
          }
          permission = grant.value.permission
        }
      }
      owner {
        id = data.aws_caller_identity.current.account_id
      }
    }
  }

  depends_on = [
    aws_s3_bucket_ownership_controls.this,
    aws_s3_bucket_public_access_block.this
  ]
}

################################################################################
# Object Lock Configuration
################################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = (local.create_bucket && var.object_lock_enabled && var.object_lock_configuration != null) ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.mode
      days  = var.object_lock_configuration.days
      years = var.object_lock_configuration.years
    }
  }
}

################################################################################
# Versioning
################################################################################

resource "aws_s3_bucket_versioning" "this" {
  count  = (local.create_bucket && length(keys(var.versioning)) > 0) ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status = lookup(var.versioning, "status", "Enabled")
    mfa_delete = lookup(var.versioning, "mfa_delete", null)
  }
}

################################################################################
# Access Logging
################################################################################

resource "aws_s3_bucket_logging" "this" {
  count  = (local.create_bucket && length(keys(var.logging)) > 0) ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  target_bucket = var.logging["target_bucket"]
  target_prefix = lookup(var.logging, "target_prefix", null)
}

################################################################################
# Website Hosting
################################################################################

resource "aws_s3_bucket_website_configuration" "this" {
  count  = (local.create_bucket && length(keys(var.website)) > 0) ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "index_document" {
    for_each = lookup(var.website, "index_document", null) != null ? [var.website.index_document] : []
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = lookup(var.website, "error_document", null) != null ? [var.website.error_document] : []
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = lookup(var.website, "redirect_all_requests_to", null) != null ? [var.website.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = lookup(redirect_all_requests_to.value, "protocol", null)
    }
  }
}

################################################################################
# CORS Configuration
################################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = (local.create_bucket && length(var.cors_rule) > 0) ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rule
    content {
      id              = lookup(cors_rule.value, "id", null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      allowed_headers = lookup(cors_rule.value, "allowed_headers", null)
      expose_headers  = lookup(cors_rule.value, "expose_headers", null)
      max_age_seconds = lookup(cors_rule.value, "max_age_seconds", null)
    }
  }
}

################################################################################
# Lifecycle Configuration
################################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = (local.create_bucket && length(var.lifecycle_rule) > 0) ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rule
    content {
      id     = lookup(rule.value, "id", null)
      status = lookup(rule.value, "status", "Enabled")

      dynamic "expiration" {
        for_each = lookup(rule.value, "expiration", null) != null ? [rule.value.expiration] : []
        content {
          date                         = lookup(expiration.value, "date", null)
          days                         = lookup(expiration.value, "days", null)
          expired_object_delete_marker = lookup(expiration.value, "expired_object_delete_marker", null)
        }
      }

      dynamic "transition" {
        for_each = lookup(rule.value, "transition", [])
        content {
          date          = lookup(transition.value, "date", null)
          days          = lookup(transition.value, "days", null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = lookup(rule.value, "noncurrent_version_expiration", null) != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = lookup(noncurrent_version_expiration.value, "noncurrent_days", null)
        }
      }
    }
  }
}

################################################################################
# Replication Configuration
################################################################################

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = (local.create_bucket && length(keys(var.replication_configuration)) > 0) ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  role   = var.replication_configuration["role"]

  dynamic "rule" {
    for_each = var.replication_configuration["rules"]
    content {
      id     = lookup(rule.value, "id", null)
      status = lookup(rule.value, "status", "Enabled")

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = lookup(rule.value.destination, "storage_class", null)
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

################################################################################
# Intelligent Tiering
################################################################################

resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  for_each = (local.create_bucket && length(keys(var.intelligent_tiering)) > 0) ? var.intelligent_tiering : {}

  bucket = aws_s3_bucket.this[0].id
  name   = each.key
  status = lookup(each.value, "status", "Enabled")

  dynamic "tiering" {
    for_each = lookup(each.value, "tiering", [])
    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }
}

################################################################################
# Transfer Acceleration & Requester Pays
################################################################################

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = (local.create_bucket && var.acceleration_status != null) ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  status = var.acceleration_status
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count  = (local.create_bucket && var.request_payer != null) ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  payer  = var.request_payer
}

################################################################################
# Outputs
################################################################################

output "s3_bucket_id" {
  description = "The name of the bucket."
  value       = try(aws_s3_bucket.this[0].id, "")
}

output "s3_bucket_arn" {
  description = "The ARN of the bucket."
  value       = try(aws_s3_bucket.this[0].arn, "")
}

output "s3_bucket_bucket_domain_name" {
  description = "The bucket domain name."
  value       = try(aws_s3_bucket.this[0].bucket_domain_name, "")
}

output "kms_key_arn" {
  description = "The ARN of the KMS key created for bucket encryption."
  value       = try(aws_kms_key.this[0].arn, "")
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# --------------------------------------------------------------------------------------------------
# Input Variables
# --------------------------------------------------------------------------------------------------
variable "target_stack" {
  type        = string
  description = "Target environment/stack name."
  default     = "benchmark"
}

variable "stack_githash" {
  type        = string
  description = "Short Git commit hash for the stack."
  default     = "benchmark0000"
}

variable "stack_githash_long" {
  type        = string
  description = "Long Git commit hash for the stack."
  default     = "benchmark000000000000000000000000000000000"
}

variable "stack_s3_bucket" {
  type        = string
  description = "S3 bucket storing artifacts, configuration, and datasets."
  default     = "benchmark-stack-bucket"
}

variable "dataset_s3_object_key" {
  type        = string
  description = "S3 key for the main dataset."
  default     = "dataset.csv"
}

variable "destigmatized_dataset_s3_object_key" {
  type        = string
  description = "S3 key for the destigmatized dataset."
  default     = "destigmatized_dataset.csv"
}

variable "genomic_dataset_s3_object_key" {
  type        = string
  description = "S3 key for the genomic dataset."
  default     = "genomic_dataset.csv"
}

# --------------------------------------------------------------------------------------------------
# EC2 Trust Policy
# --------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# --------------------------------------------------------------------------------------------------
# 1. Wildfly Deployment Role & Instance Profile
# --------------------------------------------------------------------------------------------------
resource "aws_iam_role" "wildfly" {
  name               = "wildfly-deployment-s3-${var.target_stack}-${var.stack_githash}"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

resource "aws_iam_instance_profile" "wildfly" {
  name = "wildfly-deployment-s3-${var.target_stack}-${var.stack_githash}"
  role = aws_iam_role.wildfly.name
}

resource "aws_iam_role_policy_attachment" "wildfly_cw" {
  role       = aws_iam_role.wildfly.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "wildfly_ssm" {
  role       = aws_iam_role.wildfly.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

data "aws_iam_policy_document" "wildfly_inline" {
  statement {
    sid       = "CloudWatchMetrics"
    effect    = "Allow"
    actions   = ["cloudwatch:PutMetricData"]
    resources = ["*"]
  }

  statement {
    sid       = "EC2Tagging"
    effect    = "Allow"
    actions   = ["ec2:CreateTags"]
    resources = ["arn:aws:ec2:*:*:instance/*"]
  }

  statement {
    sid       = "S3ListTierBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = ["arn:aws:s3:::${var.stack_s3_bucket}"]
  }

  statement {
    sid    = "S3TierArtifacts"
    effect = "Allow"
    actions = [
      "s3:GetObject"
    ]
    resources = [
      "arn:aws:s3:::${var.stack_s3_bucket}/wildfly/*",
      "arn:aws:s3:::${var.stack_s3_bucket}/common/*",
      "arn:aws:s3:::${var.stack_s3_bucket}/certs/*",
      "arn:aws:s3:::${var.stack_s3_bucket}/${var.dataset_s3_object_key}"
    ]
  }
}

resource "aws_iam_role_policy" "wildfly_inline" {
  name   = "wildfly-deployment-inline-policy"
  role   = aws_iam_role.wildfly.id
  policy = data.aws_iam_policy_document.wildfly_inline.json
}

# --------------------------------------------------------------------------------------------------
# 2. HTTPD Deployment Role & Instance Profile
# --------------------------------------------------------------------------------------------------
resource "aws_iam_role" "httpd" {
  name               = "httpd-deployment-s3-${var.target_stack}-${var.stack_githash}"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
