      "arn:aws:s3:::${var.stack_s3_bucket}/certs/*"
    ]
  }
}

resource "aws_iam_role_policy" "httpd_inline" {
  name   = "httpd-deployment-inline-policy"
  role   = aws_iam_role.httpd.id
  policy = data.aws_iam_policy_document.httpd_inline.json
}

# --------------------------------------------------------------------------------------------------
# 3. Auth HPDS Deployment Role & Instance Profile
# --------------------------------------------------------------------------------------------------
resource "aws_iam_role" "auth_hpds" {
  name               = "auth-hpds-deployment-s3-${var.target_stack}-${var.stack_githash}"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
