```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region for provisioning resources"
  type        = string
  default     = "us-east-1"
}

variable "create_security_group_module" {
  description = "Global toggle to control whether any resources in this configuration are created."
  type        = bool
  default     = true
}

variable "create_new_security_group" {
  description = "Whether to create a new security group. If false, existing_security_group_id must be provided."
  type        = bool
  default     = true
}

variable "existing_security_group_id" {
  description = "The ID of an existing security group to which rules should be applied if create_new_security_group is false."
  type        = string
  default     = ""
}

variable "vpc_id" {
  description = "The target VPC ID where the security group will be created."
  type        = string
  default     = ""
}

variable "security_group_name" {
  description = "Name for the new security group."
  type        = string
  default     = "custom-security-group"
}

variable "security_group_description" {
  description = "Description for the new security group."
  type        = string
  default     = "Managed by Terraform"
}

variable "revoke_rules_on_delete" {
  description = "Whether to revoke all ingress and egress rules before deleting the security group."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Map of tags to assign to resources."
  type        = map(string)
  default = {
    Environment = "production"
    Terraform   = "true"
  }
}

# Prefix List Variables
variable "create_prefix_list" {
  description = "Whether to create a customer-managed EC2 prefix list."
  type        = bool
  default     = false
}

variable "prefix_list_name" {
  description = "Name of the managed prefix list."
  type        = string
  default     = "custom-prefix-list"
}

variable "prefix_list_address_family" {
  description = "The address family for the prefix list (IPv4 or IPv6)."
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries allowed in the prefix list."
  type        = number
  default     = 5
}

variable "prefix_list_entries" {
  description = "List of prefix list entry objects containing cidr and optional description."
  type = list(object({
    cidr        = string
    description = optional(string, "")
  }))
  default = []
}

# Rule Definitions
variable "ingress_rules" {
  description = "List of ingress rule definitions. Exactly one target source must be specified."
  type = list(object({
    description                  = optional(string, null)
    ip_protocol                  = string
    from_port                    = optional(number, null)
    to_port                      = optional(number, null)
    cidr_ipv4                    = optional(string, null)
    cidr_ipv6                    = optional(string, null)
    referenced_security_group_id = optional(string, null)
    prefix_list_id               = optional(string, null)
  }))
  default = []
}

variable "egress_rules" {
  description = "List of egress rule definitions. If empty, a default allow-all-IPv4 egress rule will be attached."
  type = list(object({
    description                  = optional(string, null)
    ip_protocol                  = string
    from_port                    = optional(number, null)
    to_port                      = optional(number, null)
    cidr_ipv4                    = optional(string, null)
    cidr_ipv6                    = optional(string, null)
    referenced_security_group_id = optional(string, null)
    prefix_list_id               = optional(string, null)
  }))
  default = []
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES (Fallback default VPC if not provided)
# ---------------------------------------------------------------------------------------------------------------------

data "aws_vpc" "default" {
  count   = var.create_security_group_module && var.create_new_security_group && var.vpc_id == "" ? 1 : 0
  default = true
}

locals {
  target_vpc_id = var.vpc_id != "" ? var.vpc_id : (length(data.aws_vpc.default) > 0 ? data.aws_vpc.default[0].id : "")

  # Target Security Group ID
  security_group_id = var.create_security_group_module ? (
    var.create_new_security_group ? (
      length(aws_security_group.this) > 0 ? aws_security_group.this[0].id : ""
    ) : var.existing_security_group_id
  ) : ""

  # Outbound rules list - use provided egress rules, or fallback to default allow-all IPv4
  effective_egress_rules = length(var.egress_rules) > 0 ? var.egress_rules : [
    {
      description                  = "Allow all outbound IPv4 traffic by default"
      ip_protocol                  = "-1"
      from_port                    = null
      to_port                      = null
      cidr_ipv4                    = "0.0.0.0/0"
      cidr_ipv6                    = null
      referenced_security_group_id = null
      prefix_list_id               = null
    }
  ]
}

# ---------------------------------------------------------------------------------------------------------------------
# MANAGED PREFIX LIST
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_ec2_managed_prefix_list" "this" {
  count          = var.create_security_group_module && var.create_prefix_list ? 1 : 0
  name           = var.prefix_list_name
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = merge(
    var.tags,
    {
      Name = var.prefix_list_name
    }
  )
}

# ---------------------------------------------------------------------------------------------------------------------
# SECURITY GROUP
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_security_group" "this" {
  count                  = var.create_security_group_module && var.create_new_security_group ? 1 : 0
  name_prefix            = "${var.security_group_name}-"
  description            = var.security_group_description
  vpc_id                 = local.target_vpc_id
  revoke_rules_on_delete = var.revoke_rules_on_delete

  tags = merge(
    var.tags,
    {
      Name = var.security_group_name
    }
  )

  lifecycle {
    create_before_destroy = true
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# SECURITY GROUP RULES (INGRESS & EGRESS)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_vpc_security_group_ingress_rule" "rules" {
  for_each = {
    for idx, rule in var.ingress_rules : idx => rule
    if var.create_security_group_module && local.security_group_id != ""
  }

  security_group_id            = local.security_group_id
  description                  = each.value.description
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id
}

resource "aws_vpc_security_group_egress_rule" "rules" {
  for_each = {
    for idx, rule in local.effective_egress_rules : idx => rule
    if var.create_security_group_module && local.security_group_id != ""
  }

  security_group_id            = local.security_group_id
  description                  = each.value.description
  ip_protocol                  = each.value.ip_protocol
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  cidr_ipv4                    = each.value.cidr_ipv4
  cidr_ipv6                    = each.value.cidr_ipv6
  referenced_security_group_id = each.value.referenced_security_group_id
  prefix_list_id               = each.value.prefix_list_id
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "security_group_id" {
  description = "The ID of the security group (newly created or supplied existing)."
  value       = local.security_group_id
}

output "security_group_arn" {
  description = "The ARN of the newly created security group (if created)."
  value       = length(aws_security_group.this) > 0 ? aws_security_group.this[0].arn : null
}

output "managed_prefix_list_id" {
  description = "The ID of the created managed prefix list (if created)."
  value       = length(aws_ec2_managed_prefix_list.this) > 0 ? aws_ec2_managed_prefix_list.this[0].id : null
}

output "managed_prefix_list_arn" {
  description = "The ARN of the created managed prefix list (if created)."
  value       = length(aws_ec2_managed_prefix_list.this) > 0 ? aws_ec2_managed_prefix_list.this[0].arn : null
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "The AWS region to deploy resources into."
  default     = "us-east-1"
}

variable "project_name" {
  type        = string
  description = "Project name prefix for IAM resources."
  default     = "Cv-React-App"
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# --------------------------------------------------------------------------------------------------
# 1. EC2 CodeDeploy Role & Instance Profile
# --------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_trust_policy" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ec2_codedeploy_role" {
  name               = "${var.project_name}_ec2_codedeploy_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_trust_policy.json

  tags = {
    Project = var.project_name
  }
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_role_codedeploy" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEC2RoleforAWSCodeDeploy"
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_role_ec2_full" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEC2FullAccess"
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_role_s3_full" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_instance_profile" "ec2_codedeploy_instance_profile" {
  name = "${var.project_name}_ec2_codedeploy_instance_profile"
  role = aws_iam_role.ec2_codedeploy_role.name
}

# --------------------------------------------------------------------------------------------------
# 2. Dedicated CodeDeploy Service Role
# --------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "codedeploy_service_trust_policy" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codedeploy.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codedeploy_service_role" {
  name               = "${var.project_name}_codedeploy_service_role"
  assume_role_policy = data.aws_iam_policy_document.codedeploy_service_trust_policy.json

  tags = {
    Project = var.project_name
  }
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_role_policy" {
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSCodeDeployRole"
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_role_s3_full" {
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonS3FullAccess"
}

# --------------------------------------------------------------------------------------------------
# 3. EC2 CloudWatch Agent Role & Instance Profile
# --------------------------------------------------------------------------------------------------
resource "aws_iam_role" "ec2_cloudwatch_agent_role" {
  name               = "${var.project_name}_ec2_cloudwatch_agent_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_trust_policy.json

  tags = {
    Project = var.project_name
  }
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_policy" {
  role       = aws_iam_role.ec2_cloudwatch_agent_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_s3_full" {
  role       = aws_iam_role.ec2_cloudwatch_agent_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_instance_profile" "ec2_cloudwatch_agent_instance_profile" {
  name = "${var.project_name}_ec2_cloudwatch_agent_instance_profile"
  role = aws_iam_role.ec2_cloudwatch_agent_role.name
}

# --------------------------------------------------------------------------------------------------
# 4. CodeBuild Role & Permissions
# --------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "codebuild_trust_policy" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codebuild_role" {
  name               = "CodeBuildRole"
  assume_role_policy = data.aws_iam_policy_document.codebuild_trust_policy.json

  tags = {
    Project = var.project_name
  }
}

resource "aws_iam_role_policy_attachment" "codebuild_s3_full" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonS3FullAccess"
}

data "aws_iam_policy_document" "codebuild_inline_policy" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:logs:*:*:log-group:/aws/codebuild/*"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetBucketAcl",
      "s3:GetBucketLocation"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:s3:::codepipeline-us-east-1-*",
      "arn:${data.aws_partition.current.partition}:s3:::codepipeline-us-east-1-*/*"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "codebuild:CreateReportGroup",
      "codebuild:CreateReport",
      "codebuild:UpdateReport",
      "codebuild:BatchPutTestCases",
      "codebuild:BatchPutCodeCoverages"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:codebuild:*:*:report-group/*"
    ]
  }
}

resource "aws_iam_role_policy" "codebuild_custom_policy" {
  name   = "CodeBuildPolicy"
  role   = aws_iam_role.codebuild_role.id
  policy = data.aws_iam_policy_document.codebuild_inline_policy.json
}

# --------------------------------------------------------------------------------------------------
# 5. CodePipeline Role & Permissions
# --------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "codepipeline_trust_policy" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type = "Service"
      identifiers = [
        "codepipeline.amazonaws.com",
        "codebuild.amazonaws.com",
        "codedeploy.amazonaws.com"
      ]
    }
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

resource "aws_iam_role" "codepipeline_role" {
  name               = "CodePipelineRole"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_trust_policy.json

  tags = {
    Project = var.project_name
  }
}

data "aws_iam_policy_document" "codepipeline_inline_policy" {
  statement {
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = ["*"]
    condition {
      test     = "StringEqualsIfExists"
      variable = "iam:PassedToService"
      values = [
        "cloudformation.amazonaws.com",
        "elasticbeanstalk.amazonaws.com",
        "ec2.amazonaws.com",
        "lambda.amazonaws.com",
        "ecs-tasks.amazonaws.com"
      ]
    }
  }

  statement {
    effect = "Allow"
    actions = [
      "codecommit:CancelUploadArchive",
      "codecommit:GetBranch",
      "codecommit:GetCommit",
      "codecommit:GetRepository",
      "codecommit:GetUploadArchiveStatus",
      "codecommit:UploadArchive"
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "codedeploy:CreateDeployment",
      "codedeploy:GetApplication",
      "codedeploy:GetApplicationRevision",
      "codedeploy:GetDeployment",
      "codedeploy:GetDeploymentConfig",
      "codedeploy:RegisterApplicationRevision"
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "codestar-connections:UseConnection"
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "lambda:InvokeFunction",
      "lambda:ListFunctions"
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "cloudformation:CreateStack",
      "cloudformation:DeleteStack",
      "cloudformation:DescribeStacks",
      "cloudformation:UpdateStack",
      "cloudformation:CreateChangeSet",
      "cloudformation:DeleteChangeSet",
      "cloudformation:DescribeChangeSet",
      "cloudformation:ExecuteChangeSet",
      "cloudformation:SetStackPolicy",
      "cloudformation:ValidateTemplate"
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "codebuild:BatchGetBuilds",
      "codebuild:StartBuild",
      "codebuild:BatchGetBuildBatches",
      "codebuild:StartBuildBatch"
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetBucketVersioning",
      "s3:PutObject",
      "s3:PutObjectAcl"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:s3:::*"
    ]
  }
}

resource "aws_iam_role_policy" "codepipeline_custom_policy" {
  name   = "CodePipelinePolicy"
  role   = aws_iam_role.codepipeline_role.id
  policy = data.aws_iam_policy_document.codepipeline_inline_policy.json
}

# --------------------------------------------------------------------------------------------------
# Outputs
# --------------------------------------------------------------------------------------------------
output "ec2_codedeploy_role_arn" {
  description = "ARN of the EC2 CodeDeploy role."
  value       = aws_iam_role.ec2_codedeploy_role.arn
}

output "ec2_codedeploy_instance_profile_name" {
  description = "Name of the EC2 CodeDeploy instance profile."
  value       = aws_iam_instance_profile.ec2_codedeploy_instance_profile.name
}

output "codedeploy_service_role_arn" {
  description = "ARN of the CodeDeploy service role."
  value       = aws_iam_role.codedeploy_service_role.arn
}

output "ec2_cloudwatch_agent_role_arn" {
  description = "ARN of the EC2 CloudWatch Agent role."
  value       = aws_iam_role.ec2_cloudwatch_agent_role.arn
}

output "ec2_cloudwatch_agent_instance_profile_name" {
  description = "Name of the EC2 CloudWatch Agent instance profile."
  value       = aws_iam_instance_profile.ec2_cloudwatch_agent_instance_profile.name
}

output "codebuild_role_arn" {
  description = "ARN of the CodeBuild role."
  value       = aws_iam_role.codebuild_role.arn
}

output "codepipeline_role_arn" {
  description = "ARN of the CodePipeline role."
  value       = aws_iam_role.codepipeline_role.arn
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region for resources"
  default     = "us-east-1"
}

variable "environment" {
  type        = string
  description = "Environment identifier"
  default     = "dev"
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# 1. near-app-actions-mapping (hash: appId)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_app_actions_mapping" {
  name         = "near-app-actions-mapping"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "appId"

  attribute {
    name = "appId"
    type = "S"
  }

  tags = {
    Name        = "near-app-actions-mapping"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 2. near-app-actions-master (hash: actionId)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_app_actions_master" {
  name         = "near-app-actions-master"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "actionId"

  attribute {
    name = "actionId"
    type = "S"
  }

  tags = {
    Name        = "near-app-actions-master"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 3. near-app-categories (hash: categoryId)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_app_categories" {
  name         = "near-app-categories"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "categoryId"

  attribute {
    name = "categoryId"
    type = "S"
  }

  tags = {
    Name        = "near-app-categories"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 4. near-apps (hash: appId, GSI: categoryId-Index)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_apps" {
  name         = "near-apps"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "appId"

  attribute {
    name = "appId"
    type = "S"
  }

  attribute {
    name = "categoryId"
    type = "S"
  }

  global_secondary_index {
    name            = "categoryId-Index"
    hash_key        = "categoryId"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-apps"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 5. near-connected-apps (hash: connectionId, GSIs: userId-Index, appId-Index)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_connected_apps" {
  name         = "near-connected-apps"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "connectionId"

  attribute {
    name = "connectionId"
    type = "S"
  }

  attribute {
    name = "userId"
    type = "S"
  }

  attribute {
    name = "appId"
    type = "S"
  }

  global_secondary_index {
    name            = "userId-Index"
    hash_key        = "userId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "appId-Index"
    hash_key        = "appId"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-connected-apps"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 6. near-contacts (hash: contactId, GSI: userId-contactId-index)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_contacts" {
  name         = "near-contacts"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "contactId"

  attribute {
    name = "contactId"
    type = "S"
  }

  attribute {
    name = "userId"
    type = "S"
  }

  global_secondary_index {
    name            = "userId-contactId-index"
    hash_key        = "userId"
    range_key       = "contactId"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-contacts"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 7. near-fiat-tokens (hash: symbol)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_fiat_tokens" {
  name         = "near-fiat-tokens"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "symbol"

  attribute {
    name = "symbol"
    type = "S"
  }

  tags = {
    Name        = "near-fiat-tokens"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 8. near-files-invitations (hash: pk, range: sk, stream, TTL: ttl)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_files_invitations" {
  name             = "near-files-invitations"
  billing_mode     = "PAY_PER_REQUEST"
  hash_key         = "pk"
  range_key        = "sk"
  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  ttl {
    attribute_name = "ttl"
    enabled        = true
  }

  tags = {
    Name        = "near-files-invitations"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 9. near-files (hash: walletId, range: fileId, stream, TTL: ttl, 3 GSIs)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_files" {
  name             = "near-files"
  billing_mode     = "PAY_PER_REQUEST"
  hash_key         = "walletId"
  range_key        = "fileId"
  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  attribute {
    name = "walletId"
    type = "S"
  }

  attribute {
    name = "fileId"
    type = "S"
  }

  attribute {
    name = "ownerId"
    type = "S"
  }

  attribute {
    name = "hash"
    type = "S"
  }

  global_secondary_index {
    name            = "ownerId-walletId-index"
    hash_key        = "ownerId"
    range_key       = "walletId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "hash-index"
    hash_key        = "hash"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "ownerId-fileId-index"
    hash_key        = "ownerId"
    range_key       = "fileId"
    projection_type = "ALL"
  }

  ttl {
    attribute_name = "ttl"
    enabled        = true
  }

  tags = {
    Name        = "near-files"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 10. near-folders (hash: walletId, range: id)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_folders" {
  name         = "near-folders"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "walletId"
  range_key    = "id"

  attribute {
    name = "walletId"
    type = "S"
  }

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name        = "near-folders"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 11. near-hashes (hash: hk, range: sk, stream, GSI: hk1-sk1-Index)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_hashes" {
  name             = "near-hashes"
  billing_mode     = "PAY_PER_REQUEST"
  hash_key         = "hk"
  range_key        = "sk"
  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  attribute {
    name = "hk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  attribute {
    name = "hk1"
    type = "S"
  }

  attribute {
    name = "sk1"
    type = "S"
  }

  global_secondary_index {
    name            = "hk1-sk1-Index"
    hash_key        = "hk1"
    range_key       = "sk1"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-hashes"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 12. near-hidden (hash: id)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_hidden" {
  name         = "near-hidden"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name        = "near-hidden"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 13. near-nft-access-requests (hash: requestId, GSIs: nftId-Index, ownerId-Index, requesterId-Index)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_nft_access_requests" {
  name         = "near-nft-access-requests"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "requestId"

  attribute {
    name = "requestId"
    type = "S"
  }

  attribute {
    name = "nftId"
    type = "S"
  }

  attribute {
    name = "ownerId"
    type = "S"
  }

  attribute {
    name = "requesterId"
    type = "S"
  }

  global_secondary_index {
    name            = "nftId-Index"
    hash_key        = "nftId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "ownerId-Index"
    hash_key        = "ownerId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "requesterId-Index"
    hash_key        = "requesterId"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-nft-access-requests"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 14. near-nft-activities (hash: activityId, range: created [N], GSI: nftId-Index)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_nft_activities" {
  name         = "near-nft-activities"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "activityId"
  range_key    = "created"

  attribute {
    name = "activityId"
    type = "S"
  }

  attribute {
    name = "created"
    type = "N"
  }

  attribute {
    name = "nftId"
    type = "S"
  }

  global_secondary_index {
    name            = "nftId-Index"
    hash_key        = "nftId"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-nft-activities"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 15. near-nft-categories (hash: categoryId)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_nft_categories" {
  name         = "near-nft-categories"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "categoryId"

  attribute {
    name = "categoryId"
    type = "S"
  }

  tags = {
    Name        = "near-nft-categories"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 16. near-nft-collections (hash: collectionId, GSI: OwnerIdIndex)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_nft_collections" {
  name         = "near-nft-collections"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "collectionId"

  attribute {
    name = "collectionId"
    type = "S"
  }

  attribute {
    name = "ownerId"
    type = "S"
  }

  global_secondary_index {
    name            = "OwnerIdIndex"
    hash_key        = "ownerId"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-nft-collections"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 17. near-nft-offers (hash: offerId, GSI: nftId-Index)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_nft_offers" {
  name         = "near-nft-offers"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "offerId"

  attribute {
    name = "offerId"
    type = "S"
  }

  attribute {
    name = "nftId"
    type = "S"
  }

  global_secondary_index {
    name            = "nftId-Index"
    hash_key        = "nftId"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-nft-offers"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 18. near-nft-shares (hash: shareId, GSIs: nftId-Index, ownerWalletId-Index, recipientWalletId-Index)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_nft_shares" {
  name         = "near-nft-shares"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "shareId"

  attribute {
    name = "shareId"
    type = "S"
  }

  attribute {
    name = "nftId"
    type = "S"
  }

  attribute {
    name = "ownerWalletId"
    type = "S"
  }

  attribute {
    name = "recipientWalletId"
    type = "S"
  }

  global_secondary_index {
    name            = "nftId-Index"
    hash_key        = "nftId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "ownerWalletId-Index"
    hash_key        = "ownerWalletId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "recipientWalletId-Index"
    hash_key        = "recipientWalletId"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-nft-shares"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 19. near-nfts (hash: nftId, GSIs: ownerWalletId-Index, transactionId-Index)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_nfts" {
  name         = "near-nfts"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "nftId"

  attribute {
    name = "nftId"
    type = "S"
  }

  attribute {
    name = "ownerWalletId"
    type = "S"
  }

  attribute {
    name = "transactionId"
    type = "S"
  }

  global_secondary_index {
    name            = "ownerWalletId-Index"
    hash_key        = "ownerWalletId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "transactionId-Index"
    hash_key        = "transactionId"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-nfts"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 20. near-otp (hash: userId, range: ttl [N], TTL: ttl)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_otp" {
  name         = "near-otp"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "userId"
  range_key    = "ttl"

  attribute {
    name = "userId"
    type = "S"
  }

  attribute {
    name = "ttl"
    type = "N"
  }

  ttl {
    attribute_name = "ttl"
    enabled        = true
  }

  tags = {
    Name        = "near-otp"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 21. near-shared-files (hash: fileId, range: userId)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_shared_files" {
  name         = "near-shared-files"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "fileId"
  range_key    = "userId"

  attribute {
    name = "fileId"
    type = "S"
  }

  attribute {
    name = "userId"
    type = "S"
  }

  tags = {
    Name        = "near-shared-files"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 22. near-storage (hash: pk, range: sk, stream, TTL: ttl, GSI: GSI1)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_storage" {
  name             = "near-storage"
  billing_mode     = "PAY_PER_REQUEST"
  hash_key         = "pk"
  range_key        = "sk"
  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  attribute {
    name = "pk1"
    type = "S"
  }

  attribute {
    name = "sk1"
    type = "S"
  }

  global_secondary_index {
    name            = "GSI1"
    hash_key        = "pk1"
    range_key       = "sk1"
    projection_type = "ALL"
  }

  ttl {
    attribute_name = "ttl"
    enabled        = true
  }

  tags = {
    Name        = "near-storage"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 23. near-transactions (hash: transactionId, 4 GSIs)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_transactions" {
  name         = "near-transactions"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "transactionId"

  attribute {
    name = "transactionId"
    type = "S"
  }

  attribute {
    name = "senderWalletId"
    type = "S"
  }

  attribute {
    name = "receiverWalletId"
    type = "S"
  }

  attribute {
    name = "jobId"
    type = "S"
  }

  attribute {
    name = "parentId"
    type = "S"
  }

  attribute {
    name = "created"
    type = "N"
  }

  global_secondary_index {
    name            = "senderWalletId-Index"
    hash_key        = "senderWalletId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "receiverWalletId-Index"
    hash_key        = "receiverWalletId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "jobId-created-Index"
    hash_key        = "jobId"
    range_key       = "created"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "parentId-created-Index"
    hash_key        = "parentId"
    range_key       = "created"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-transactions"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 24. near-users (hash: userId, GSIs: PhoneIndex, EmailIndex)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_users" {
  name         = "near-users"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "userId"

  attribute {
    name = "userId"
    type = "S"
  }

  attribute {
    name = "phone"
    type = "S"
  }

  attribute {
    name = "email"
    type = "S"
  }

  global_secondary_index {
    name            = "PhoneIndex"
    hash_key        = "phone"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "EmailIndex"
    hash_key        = "email"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-users"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 25. near-wallets-blockchain (hash: wallet_id)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_wallets_blockchain" {
  name         = "near-wallets-blockchain"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "wallet_id"

  attribute {
    name = "wallet_id"
    type = "S"
  }

  tags = {
    Name        = "near-wallets-blockchain"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 26. near-wallets-private (hash: walletId, GSI: UserIdIndex with range key walletId)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_wallets_private" {
  name         = "near-wallets-private"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "walletId"

  attribute {
    name = "walletId"
    type = "S"
  }

  attribute {
    name = "userId"
    type = "S"
  }

  global_secondary_index {
    name            = "UserIdIndex"
    hash_key        = "userId"
    range_key       = "walletId"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-wallets-private"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# 27. near-wallets (hash: walletId, stream, GSIs: userId-Index, walletName-Index, jobId-Index)
# -----------------------------------------------------------------------------
resource "aws_dynamodb_table" "near_wallets" {
  name             = "near-wallets"
  billing_mode     = "PAY_PER_REQUEST"
  hash_key         = "walletId"
  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  attribute {
    name = "walletId"
    type = "S"
  }

  attribute {
    name = "userId"
    type = "S"
  }

  attribute {
    name = "walletName"
    type = "S"
  }

  attribute {
    name = "jobId"
    type = "S"
  }

  global_secondary_index {
    name            = "userId-Index"
    hash_key        = "userId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "walletName-Index"
    hash_key        = "walletName"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "jobId-Index"
    hash_key        = "jobId"
    projection_type = "ALL"
  }

  tags = {
    Name        = "near-wallets"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

