    aws_dynamodb_table.near_apps.name,
    aws_dynamodb_table.near_connected_apps.name,
    aws_dynamodb_table.near_contacts.name,
    aws_dynamodb_table.near_fiat_tokens.name,
    aws_dynamodb_table.near_files_invitations.name,
    aws_dynamodb_table.near_files.name,
    aws_dynamodb_table.near_folders.name,
    aws_dynamodb_table.near_hashes.name,
    aws_dynamodb_table.near_hidden.name,
    aws_dynamodb_table.near_nft_access_requests.name,
