terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "The AWS region to deploy resources to."
  default     = "us-east-1"
}

variable "user_name" {
  type        = string
  description = "The name of the IAM user for API integration and testing."
  default     = "postman-user"
}

variable "cognito_user_pool_arn" {
  type        = string
  description = "Optional ARN of a Cognito User Pool to grant cognito-idp:AdminInitiateAuth permissions."
  default     = ""
}

# -----------------------------------------------------------------------------
# IAM User and Access Keys
# -----------------------------------------------------------------------------
resource "aws_iam_user" "api_tester" {
  name = var.user_name
  path = "/"

  tags = {
    Purpose   = "API integration testing and monitoring"
    ManagedBy = "Terraform"
  }
}

resource "aws_iam_access_key" "api_tester_key" {
  user = aws_iam_user.api_tester.name
}

# -----------------------------------------------------------------------------
# Policy: API Gateway & CloudWatch Read Access
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "api_monitoring_policy_doc" {
  statement {
    sid       = "APIGatewayReadOnly"
    effect    = "Allow"
    actions   = ["apigateway:GET"]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchMetricsReadOnly"
    effect = "Allow"
    actions = [
      "cloudwatch:GetMetricData",
      "cloudwatch:ListMetrics"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_user_policy" "api_monitoring_policy" {
  name   = "${var.user_name}-monitoring-policy"
  user   = aws_iam_user.api_tester.name
  policy = data.aws_iam_policy_document.api_monitoring_policy_doc.json
}

# -----------------------------------------------------------------------------
# Conditional Policy: Cognito Authentication Access
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "cognito_auth_policy_doc" {
  count = var.cognito_user_pool_arn != "" ? 1 : 0

  statement {
    sid    = "CognitoAdminInitiateAuth"
    effect = "Allow"
    actions = [
      "cognito-idp:AdminInitiateAuth"
    ]
    resources = [var.cognito_user_pool_arn]
  }
}

resource "aws_iam_user_policy" "cognito_auth_policy" {
  count  = var.cognito_user_pool_arn != "" ? 1 : 0
  name   = "${var.user_name}-cognito-auth-policy"
  user   = aws_iam_user.api_tester.name
  policy = data.aws_iam_policy_document.cognito_auth_policy_doc[0].json
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "iam_user_name" {
  description = "The name of the created IAM user."
  value       = aws_iam_user.api_tester.name
}

output "iam_user_arn" {
  description = "The ARN of the created IAM user."
  value       = aws_iam_user.api_tester.arn
}

output "iam_access_key_id" {
  description = "The access key ID for programmatic access."
  value       = aws_iam_access_key.api_tester_key.id
}

output "iam_secret_access_key" {
  description = "The secret access key for programmatic access."
  value       = aws_iam_access_key.api_tester_key.secret
  sensitive   = true
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "The AWS region to deploy resources in."
  default     = "us-east-1"
}

variable "cluster_name" {
  type        = string
  description = "The name of the EKS cluster."
  default     = "legion"
}

# ------------------------------------------------------------------------------
# EKS Master / Control Plane IAM Role & Policies
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "eks_master_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_master" {
  name               = "tf-${var.cluster_name}"
  assume_role_policy = data.aws_iam_policy_document.eks_master_assume_role.json
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_master.name
}

resource "aws_iam_role_policy_attachment" "eks_service_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
  role       = aws_iam_role.eks_master.name
}

# ------------------------------------------------------------------------------
# EKS Worker Node IAM Role, Instance Profile & Policies
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "eks_node_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_node" {
  name               = "tf-${var.cluster_name}-node"
  assume_role_policy = data.aws_iam_policy_document.eks_node_assume_role.json
}

resource "aws_iam_instance_profile" "eks_node" {
  name = "tf-${var.cluster_name}-node"
  role = aws_iam_role.eks_node.name
}

resource "aws_iam_role_policy_attachment" "eks_worker_node_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_role_policy_attachment" "eks_cni_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_role_policy_attachment" "eks_container_registry_readonly" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.eks_node.name
}

# ------------------------------------------------------------------------------
# Cluster Autoscaler IAM Policy & Attachment
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "cluster_autoscaler" {
  statement {
    sid    = "AutoscalingDescribePermissions"
    effect = "Allow"
    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "ec2:DescribeLaunchTemplateVersions"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AutoscalingModificationPermissions"
    effect = "Allow"
    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup"
    ]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/kubernetes.io/cluster/${var.cluster_name}"
      values   = ["owned"]
    }

    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "cluster_autoscaler" {
  name        = "eks-worker-autoscaling-${var.cluster_name}"
  description = "IAM policy for Cluster Autoscaler on EKS worker nodes for ${var.cluster_name}"
  policy      = data.aws_iam_policy_document.cluster_autoscaler.json
}

resource "aws_iam_role_policy_attachment" "cluster_autoscaler" {
  policy_arn = aws_iam_policy.cluster_autoscaler.arn
  role       = aws_iam_role.eks_node.name
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "master_role_arn" {
  description = "ARN of the EKS master control plane IAM role."
  value       = aws_iam_role.eks_master.arn
}

output "worker_node_role_arn" {
  description = "ARN of the EKS worker node IAM role."
  value       = aws_iam_role.eks_node.arn
}

output "worker_node_instance_profile_arn" {
  description = "ARN of the EKS worker node EC2 instance profile."
  value       = aws_iam_instance_profile.eks_node.arn
}

output "cluster_autoscaler_policy_arn" {
  description = "ARN of the Cluster Autoscaler IAM policy."
  value       = aws_iam_policy.cluster_autoscaler.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# --------------------------------------------------------------------------------------------------
# Input Variables
# --------------------------------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "172.69.0.0/16"
}

variable "public_subnet_cidr" {
  type        = string
  description = "CIDR block for the public subnet"
  default     = "172.69.1.0/24"
}

variable "private_subnet_cidr" {
  type        = string
  description = "CIDR block for the private subnet"
  default     = "172.69.2.0/24"
}

variable "web_ingress_rules" {
  type = list(object({
    description = string
    port        = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  description = "Dynamic ingress rules for the web server security group"
  default = [
    {
      description = "HTTP access from anywhere"
      port        = 80
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    },
    {
      description = "SSH access restricted to VPC CIDR"
      port        = 22
      protocol    = "tcp"
      cidr_blocks = ["172.69.0.0/16"]
    }
  ]
}

# --------------------------------------------------------------------------------------------------
# VPC and Networking Resources
# --------------------------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "vpc_name"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  map_public_ip_on_launch = true

  tags = {
    Name = "public_subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidr
  map_public_ip_on_launch = false

  tags = {
    Name = "private_subnet"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "igw_tag"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "rtb_tag"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# --------------------------------------------------------------------------------------------------
# Security Groups
# --------------------------------------------------------------------------------------------------
resource "aws_security_group" "webserver" {
  name        = "webserver-sg_${aws_vpc.main.id}"
  description = "Web server security group with dynamic ingress rules"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.web_ingress_rules
    content {
      description = ingress.value.description
      from_port   = ingress.value.port
      to_port     = ingress.value.port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  egress {
    description = "Allow outbound egress limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "web-server_security_group"
  }
}

resource "aws_security_group" "database" {
  name        = "database-sg_${aws_vpc.main.id}"
  description = "Database security group allowing port 3306"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Allow MySQL/Aurora traffic from web server security group"
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.webserver.id]
  }

  ingress {
    description = "Allow MySQL/Aurora traffic from VPC CIDR"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "database-sg"
  }
}

# --------------------------------------------------------------------------------------------------
# Outputs
# --------------------------------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "The ID of the public subnet"
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "The ID of the private subnet"
  value       = aws_subnet.private.id
}

output "webserver_sg_id" {
  description = "The ID of the webserver security group"
  value       = aws_security_group.webserver.id
}

output "database_sg_id" {
  description = "The ID of the database security group"
  value       = aws_security_group.database.id
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "The AWS region where resources should be created."
  type        = string
  default     = "us-east-1"
}

variable "tags" {
  description = "A map of tags to assign to the resources."
  type        = map(string)
  default     = {}
}

# Assume role policy document for EC2 instances
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# Control Plane IAM Role and Instance Profile
resource "aws_iam_role" "control_plane" {
  name               = "aws_ccm_k8s_controlplane"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = var.tags
}

resource "aws_iam_instance_profile" "control_plane" {
  name = "aws_ccm_k8s_controlplane"
  role = aws_iam_role.control_plane.name
  tags = var.tags
}

# Control Plane Policy Document for AWS Cloud Controller Manager
data "aws_iam_policy_document" "control_plane" {
  statement {
    sid    = "EC2NetworkingAndCompute"
    effect = "Allow"
    actions = [
      "ec2:AuthorizeSecurityGroupIngress",
      "ec2:CreateRoute",
      "ec2:CreateSecurityGroup",
      "ec2:DeleteRoute",
      "ec2:DeleteSecurityGroup",
      "ec2:DescribeAvailabilityZones",
      "ec2:DescribeInstances",
      "ec2:DescribeRegions",
      "ec2:DescribeRouteTables",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSubnets",
      "ec2:DescribeVolumes",
      "ec2:DescribeVpcs",
      "ec2:ModifyInstanceAttribute",
      "ec2:ModifyVolume",
      "ec2:RevokeSecurityGroupIngress",
      "ec2:CreateTags",
      "ec2:DeleteTags"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AutoScalingDescribe"
    effect = "Allow"
    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ElasticLoadBalancingManagement"
    effect = "Allow"
    actions = [
      "elasticloadbalancing:*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "KMSDescribeKey"
    effect = "Allow"
    actions = [
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CreateServiceLinkedRole"
    effect = "Allow"
    actions = [
      "iam:CreateServiceLinkedRole"
    ]
    resources = [
      "arn:aws:iam::*:role/aws-service-role/elasticloadbalancing.amazonaws.com/AWSServiceRoleForElasticLoadBalancing"
    ]
    condition {
      test     = "StringLike"
      variable = "iam:AWSServiceName"
      values   = ["elasticloadbalancing.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "control_plane" {
  name        = "aws_ccm_k8s_controlplane"
  description = "IAM policy for Kubernetes Control Plane AWS Cloud Controller Manager"
  policy      = data.aws_iam_policy_document.control_plane.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "control_plane" {
  role       = aws_iam_role.control_plane.name
  policy_arn = aws_iam_policy.control_plane.arn
}

# Worker IAM Role and Instance Profile
resource "aws_iam_role" "worker" {
  name               = "aws_ccm_k8s_worker"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = var.tags
}

resource "aws_iam_instance_profile" "worker" {
  name = "aws_ccm_k8s_worker"
  role = aws_iam_role.worker.name
  tags = var.tags
}

# Worker Policy Document for EC2 description and ECR Read-Only access
data "aws_iam_policy_document" "worker" {
  statement {
    sid    = "EC2Describe"
    effect = "Allow"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeRegions"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ECRReadOnlyAccess"
    effect = "Allow"
    actions = [
      "ecr:GetAuthorizationToken",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:GetRepositoryPolicy",
      "ecr:DescribeRepositories",
      "ecr:ListImages",
      "ecr:DescribeImages",
      "ecr:BatchGetImage",
      "ecr:GetLifecyclePolicy",
      "ecr:GetLifecyclePolicyPreview",
      "ecr:ListTagsForResource",
      "ecr:DescribeImageScanFindings"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "worker" {
  name        = "aws_ccm_k8s_worker"
  description = "IAM policy for Kubernetes Worker Nodes (EC2 describe and ECR read-only)"
  policy      = data.aws_iam_policy_document.worker.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "worker" {
  role       = aws_iam_role.worker.name
  policy_arn = aws_iam_policy.worker.arn
}

output "control_plane_role_arn" {
  description = "ARN of the control plane IAM role."
  value       = aws_iam_role.control_plane.arn
}

output "control_plane_instance_profile_name" {
  description = "Name of the control plane IAM instance profile."
  value       = aws_iam_instance_profile.control_plane.name
}

output "worker_role_arn" {
  description = "ARN of the worker IAM role."
  value       = aws_iam_role.worker.arn
}

output "worker_instance_profile_name" {
  description = "Name of the worker IAM instance profile."
  value       = aws_iam_instance_profile.worker.name
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

variable "prefix" {
  type        = string
  description = "Prefix for naming IAM resources"
  default     = "awscademo-"
}

variable "contact" {
  type        = string
  description = "Contact email/owner tag"
  default     = "security-team@example.com"
}

variable "deployment_method" {
  type        = string
  description = "Deployment method tag"
  default     = "Terraform"
}

variable "deployment_date" {
  type        = string
  description = "Deployment date tag"
  default     = "2024-01-01"
}

variable "ttl" {
  type        = string
  description = "TTL tag value"
  default     = "infinite"
}

provider "aws" {
  region = var.aws_region
  default_tags {
    tags = {
      Contact          = var.contact
      DeploymentMethod = var.deployment_method
      DeploymentDate   = var.deployment_date
      TTL              = var.ttl
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

# -----------------------------------------------------------------------------
# 1. Demo Users Group & Self-Management Policy
# -----------------------------------------------------------------------------

resource "aws_iam_group" "demo_users" {
  name = "${var.prefix}demo-users"
}

data "aws_iam_policy_document" "self_management" {
  # Allow viewing account-level information and finding own username
  statement {
    sid    = "AllowViewAccountInfo"
    effect = "Allow"
    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:GetAccountSummary",
      "iam:ListVirtualMFADevices"
    ]
    resources = ["*"]
  }

  # Allow user to view their own credentials & MFA devices
  statement {
    sid    = "AllowManageOwnCredentials"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey",
      "iam:GetAccessKeyLastUsed",
      "iam:UploadSSHPublicKey",
      "iam:DeleteSSHPublicKey",
      "iam:GetSSHPublicKey",
      "iam:ListSSHPublicKeys",
      "iam:UpdateSSHPublicKey",
      "iam:ListMFADevices",
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice"
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}",
      "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}"
    ]
  }

  # Allow deactivating own MFA only when MFA is currently authenticated
  statement {
    sid    = "AllowDeactivateOwnMFAWithMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice"
    ]
    resources = [
      "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}",
      "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}"
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "self_management" {
  name        = "${var.prefix}self-management-policy"
  description = "Allows users to self-manage their credentials and MFA devices"
  policy      = data.aws_iam_policy_document.self_management.json
}

resource "aws_iam_group_policy_attachment" "demo_users_attach" {
  group      = aws_iam_group.demo_users.name
  policy_arn = aws_iam_policy.self_management.arn
}

# -----------------------------------------------------------------------------
# 2. Read-Only Users Group
# -----------------------------------------------------------------------------

resource "aws_iam_group" "read_only_users" {
  name = "${var.prefix}read-only-users"
}

resource "aws_iam_group_policy_attachment" "read_only_attach" {
  group      = aws_iam_group.read_only_users.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/ReadOnlyAccess"
}

# -----------------------------------------------------------------------------
# 3. Administrative IAM Role & Policy
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid     = "AllowAccountRootAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }
}

resource "aws_iam_role" "admin_role" {
  name_prefix          = substr("${var.prefix}admin-", 0, 31)
  max_session_duration = 43200
  assume_role_policy   = data.aws_iam_policy_document.admin_assume_role.json
  description          = "Administrator role requiring MFA for execution"
}

data "aws_iam_policy_document" "admin_policy" {
  statement {
    sid       = "FullAdminWithMFA"
    effect    = "Allow"
    actions   = ["*"]
    resources = ["*"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_policy" {
  name        = "${var.prefix}mfa-admin-policy"
  description = "Provides full administrator access conditional on MFA presence"
  policy      = data.aws_iam_policy_document.admin_policy.json
}

resource "aws_iam_role_policy_attachment" "admin_role_attach" {
  role       = aws_iam_role.admin_role.name
  policy_arn = aws_iam_policy.admin_policy.arn
}

# -----------------------------------------------------------------------------
# 4. MFA Superadmin Group & AssumeRole Policy
# -----------------------------------------------------------------------------

resource "aws_iam_group" "mfa_superadmin" {
  name = "${var.prefix}mfa-superadmin"
}

data "aws_iam_policy_document" "assume_admin_role" {
  statement {
    sid     = "AllowAssumeAdminRoleWithMFA"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    resources = [
      aws_iam_role.admin_role.arn
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_group_policy" "assume_admin_role" {
  name   = "${var.prefix}assume-admin-role"
  group  = aws_iam_group.mfa_superadmin.name
  policy = data.aws_iam_policy_document.assume_admin_role.json
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "demo_users_group_name" {
  description = "The name of the demo users IAM group"
  value       = aws_iam_group.demo_users.name
}

output "read_only_users_group_name" {
  description = "The name of the read-only users IAM group"
  value       = aws_iam_group.read_only_users.name
}

output "mfa_superadmin_group_name" {
  description = "The name of the MFA superadmin IAM group"
  value       = aws_iam_group.mfa_superadmin.name
}

output "admin_role_arn" {
  description = "The ARN of the MFA-enforced administrative role"
  value       = aws_iam_role.admin_role.arn
}
