terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region for deployment"
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Data Sources: IAM Policy Documents
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "admin_policy" {
  statement {
    sid       = "FullAdminAccess"
    effect    = "Allow"
    actions   = ["*"]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "github_policy" {
  statement {
    sid    = "GitHubCICDAccess"
    effect = "Allow"
    actions = [
      "acm:*",
      "cloudfront:*",
      "iam:Get*",
      "iam:List*",
      "iam:PassRole",
      "lambda:*",
      "route53:*",
      "s3:*",
      "sqs:*"
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "serverless_policy" {
  statement {
    sid    = "ServerlessDeploymentAccess"
    effect = "Allow"
    actions = [
      "acm:*",
      "cloudfront:*",
      "iam:Get*",
      "iam:List*",
      "iam:PassRole",
      "lambda:*",
      "logs:*",
      "route53:*",
      "s3:*",
      "sqs:*"
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "lambda_edge_assume_role" {
  statement {
    sid    = "LambdaAndEdgeAssumeRole"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = [
        "lambda.amazonaws.com",
        "edgelambda.amazonaws.com"
      ]
    }
    actions = ["sts:AssumeRole"]
  }
}

# -----------------------------------------------------------------------------
# IAM Groups & Inline Policies
# -----------------------------------------------------------------------------

# Admin Group
resource "aws_iam_group" "admin" {
  name = "admin"
  path = "/admin/"
}

resource "aws_iam_group_policy" "admin" {
  name   = "admin-policy"
  group  = aws_iam_group.admin.name
  policy = data.aws_iam_policy_document.admin_policy.json
}

# Admin Terraform Cloud Group
resource "aws_iam_group" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
  path = "/admin_terraform_cloud/"
}

resource "aws_iam_group_policy" "admin_terraform_cloud" {
  name   = "admin-terraform-cloud-policy"
  group  = aws_iam_group.admin_terraform_cloud.name
  policy = data.aws_iam_policy_document.admin_policy.json
}

# GitHub Group
resource "aws_iam_group" "github" {
  name = "github"
  path = "/github/"
}

resource "aws_iam_group_policy" "github" {
  name   = "github-policy"
  group  = aws_iam_group.github.name
  policy = data.aws_iam_policy_document.github_policy.json
}

# Serverless Group
resource "aws_iam_group" "serverless" {
  name = "serverless"
  path = "/serverless/"
}

resource "aws_iam_group_policy" "serverless" {
  name   = "serverless-policy"
  group  = aws_iam_group.serverless.name
  policy = data.aws_iam_policy_document.serverless_policy.json
}

# -----------------------------------------------------------------------------
# IAM Users, Keys & Group Memberships
# -----------------------------------------------------------------------------

# Admin Users
resource "aws_iam_user" "admin" {
  name = "admin"
  path = "/admin/"
}

resource "aws_iam_user_group_membership" "admin" {
  user   = aws_iam_user.admin.name
  groups = [aws_iam_group.admin.name]
}

resource "aws_iam_user" "admin_macbook_pro" {
  name = "admin-macbook-pro"
  path = "/admin/"
}

resource "aws_iam_access_key" "admin_macbook_pro" {
  user = aws_iam_user.admin_macbook_pro.name
}

resource "aws_iam_user_group_membership" "admin_macbook_pro" {
  user   = aws_iam_user.admin_macbook_pro.name
  groups = [aws_iam_group.admin.name]
}

# Admin Terraform Cloud User
resource "aws_iam_user" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
  path = "/admin_terraform_cloud/"
}

resource "aws_iam_access_key" "admin_terraform_cloud" {
  user = aws_iam_user.admin_terraform_cloud.name
}

resource "aws_iam_user_group_membership" "admin_terraform_cloud" {
  user   = aws_iam_user.admin_terraform_cloud.name
  groups = [aws_iam_group.admin_terraform_cloud.name]
}

# GitHub User
resource "aws_iam_user" "github" {
  name = "github"
  path = "/github/"
}

resource "aws_iam_user_group_membership" "github" {
  user   = aws_iam_user.github.name
  groups = [aws_iam_group.github.name]
}

# Serverless User
resource "aws_iam_user" "serverless" {
  name = "serverless"
  path = "/serverless/"
}

resource "aws_iam_user_group_membership" "serverless" {
  user   = aws_iam_user.serverless.name
  groups = [aws_iam_group.serverless.name]
}

# -----------------------------------------------------------------------------
# Serverless IAM Role & Managed Policy
# -----------------------------------------------------------------------------

resource "aws_iam_policy" "serverless" {
  name        = "serverless"
  path        = "/serverless/"
  description = "Dedicated policy for serverless deployment actions"
  policy      = data.aws_iam_policy_document.serverless_policy.json
}

resource "aws_iam_role" "serverless" {
  name               = "serverless"
  path               = "/serverless/"
  assume_role_policy = data.aws_iam_policy_document.lambda_edge_assume_role.json
}

resource "aws_iam_role_policy_attachment" "serverless" {
  role       = aws_iam_role.serverless.name
  policy_arn = aws_iam_policy.serverless.arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "admin_macbook_pro_access_key_id" {
  description = "Access key ID for admin-macbook-pro"
  value       = aws_iam_access_key.admin_macbook_pro.id
}

output "admin_terraform_cloud_access_key_id" {
  description = "Access key ID for admin-terraform-cloud"
  value       = aws_iam_access_key.admin_terraform_cloud.id
}

output "serverless_role_arn" {
  description = "ARN of the serverless IAM role"
  value       = aws_iam_role.serverless.arn
}

output "serverless_policy_arn" {
  description = "ARN of the serverless IAM customer managed policy"
  value       = aws_iam_policy.serverless.arn
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region for deployment"
  default     = "us-east-1"
}

variable "namespace" {
  type        = string
  description = "Namespace (e.g. organization name or abbreviation)"
  default     = "corp"
}

variable "environment" {
  type        = string
  description = "Environment identifier (e.g. prod, dev, stg)"
  default     = "prod"
}

variable "name" {
  type        = string
  description = "Base solution or project name"
  default     = "iam"
}

variable "admin_users" {
  type        = list(string)
  description = "List of IAM usernames to assign to the Admin group"
  default     = []
}

variable "non_admin_users" {
  type        = list(string)
  description = "List of IAM usernames to assign to the Non-Admin group"
  default     = []
}

variable "tags" {
  type        = map(string)
  description = "Additional tags to apply to resources"
  default = {
    ManagedBy = "Terraform"
  }
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# CloudPosse Label Modules
# -----------------------------------------------------------------------------
module "base_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  tags        = var.tags
}

module "admin_group_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  context    = module.base_label.context
  attributes = ["admins"]
}

module "non_admin_group_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  context    = module.base_label.context
  attributes = ["users"]
}

module "admin_role_label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  context    = module.base_label.context
  attributes = ["admin", "role"]
}

# -----------------------------------------------------------------------------
# IAM Groups
# -----------------------------------------------------------------------------
resource "aws_iam_group" "admins" {
  name = module.admin_group_label.id
}

resource "aws_iam_group" "non_admins" {
  name = module.non_admin_group_label.id
}

# Membership Management
resource "aws_iam_group_membership" "admins" {
  count = length(var.admin_users) > 0 ? 1 : 0
  name  = "${module.admin_group_label.id}-membership"
  users = var.admin_users
  group = aws_iam_group.admins.name
}

resource "aws_iam_group_membership" "non_admins" {
  count = length(var.non_admin_users) > 0 ? 1 : 0
  name  = "${module.non_admin_group_label.id}-membership"
  users = var.non_admin_users
  group = aws_iam_group.non_admins.name
}

# -----------------------------------------------------------------------------
# Self-Management & MFA Policy (Shared)
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "self_management" {
  statement {
    sid    = "AllowViewAccountInfo"
    effect = "Allow"
    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:ListVirtualMFADevices",
      "iam:ListUsers"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowManageOwnCredentials"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey",
      "iam:CreateServiceSpecificCredential",
      "iam:DeleteServiceSpecificCredential",
      "iam:ListServiceSpecificCredentials",
      "iam:UpdateServiceSpecificCredential",
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}",
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}"
    ]
  }

  statement {
    sid    = "RequireMFAToDeactivateSelfMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}",
      "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:mfa/$${aws:username}"
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "self_management" {
  name        = "${module.base_label.id}-mfa-self-management"
  description = "Allows users to manage credentials and MFA, requiring MFA to deactivate MFA devices."
  policy      = data.aws_iam_policy_document.self_management.json
  tags        = module.base_label.tags
}

resource "aws_iam_group_policy_attachment" "admins_self_mgmt" {
  group      = aws_iam_group.admins.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "non_admins_self_mgmt" {
  group      = aws_iam_group.non_admins.name
  policy_arn = aws_iam_policy.self_management.arn
}

# -----------------------------------------------------------------------------
# Admin Role and Policies
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "admin_role_assume" {
  statement {
    sid     = "RequireMFAForRootAssumption"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin_role" {
  name               = module.admin_role_label.id
  assume_role_policy = data.aws_iam_policy_document.admin_role_assume.json
  tags               = module.admin_role_label.tags
}

resource "aws_iam_role_policy_attachment" "admin_full_access" {
  role       = aws_iam_role.admin_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AdministratorAccess"
}

data "aws_iam_policy_document" "group_assume_admin_role" {
  statement {
    sid       = "AllowAssumeAdminRoleWithMFA"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin_role.arn]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_role_assumption" {
  name        = "${module.admin_group_label.id}-assume-role"
  description = "Allows assuming the admin role with active MFA"
  policy      = data.aws_iam_policy_document.group_assume_admin_role.json
  tags        = module.admin_group_label.tags
}

resource "aws_iam_group_policy_attachment" "admins_assume_role" {
  group      = aws_iam_group.admins.name
  policy_arn = aws_iam_policy.admin_role_assumption.arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "admin_group_name" {
  description = "The name of the Admin IAM Group"
  value       = aws_iam_group.admins.name
}

output "non_admin_group_name" {
  description = "The name of the Non-Admin IAM Group"
  value       = aws_iam_group.non_admins.name
}

output "admin_role_arn" {
  description = "The ARN of the MFA-protected Admin IAM Role"
  value       = aws_iam_role.admin_role.arn
}

output "self_management_policy_arn" {
  description = "The ARN of the MFA self-management policy"
  value       = aws_iam_policy.self_management.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  description = "The AWS region to deploy the network stack into."
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "The deployment environment name."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "The CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# VPC and Internet Gateway
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${var.environment}-vpc"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${var.environment}-igw"
    Environment = var.environment
  }
}

# -----------------------------------------------------------------------------
# Subnets (2 AZs: 1 Public and 2 Private per AZ)
# -----------------------------------------------------------------------------
# Public Subnets (Public IPs disabled on launch per requirements)
resource "aws_subnet" "public_az1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 1) # 10.0.1.0/24
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${var.environment}-public-subnet-az1"
    Environment = var.environment
    Tier        = "Public"
  }
}

resource "aws_subnet" "public_az2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 2) # 10.0.2.0/24
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${var.environment}-public-subnet-az2"
    Environment = var.environment
    Tier        = "Public"
  }
}

# Private Tier 1 Subnets (e.g., App tier)
resource "aws_subnet" "private_tier1_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 11) # 10.0.11.0/24
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name        = "${var.environment}-private-tier1-subnet-az1"
    Environment = var.environment
    Tier        = "Private-Tier1"
  }
}

resource "aws_subnet" "private_tier1_az2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 12) # 10.0.12.0/24
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name        = "${var.environment}-private-tier1-subnet-az2"
    Environment = var.environment
    Tier        = "Private-Tier1"
  }
}

# Private Tier 2 Subnets (e.g., Database tier)
resource "aws_subnet" "private_tier2_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 21) # 10.0.21.0/24
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name        = "${var.environment}-private-tier2-subnet-az1"
    Environment = var.environment
    Tier        = "Private-Tier2"
  }
}

resource "aws_subnet" "private_tier2_az2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 22) # 10.0.22.0/24
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name        = "${var.environment}-private-tier2-subnet-az2"
    Environment = var.environment
    Tier        = "Private-Tier2"
  }
}

# -----------------------------------------------------------------------------
# Route Tables and Associations
# -----------------------------------------------------------------------------
# Public Route Table with route to Internet Gateway
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name        = "${var.environment}-public-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "public_az1" {
  subnet_id      = aws_subnet.public_az1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_az2" {
  subnet_id      = aws_subnet.public_az2.id
  route_table_id = aws_route_table.public.id
}

# Private Route Table (No explicit routes out, stays purely local)
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${var.environment}-private-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "private_tier1_az1" {
  subnet_id      = aws_subnet.private_tier1_az1.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_tier1_az2" {
  subnet_id      = aws_subnet.private_tier1_az2.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_tier2_az1" {
  subnet_id      = aws_subnet.private_tier2_az1.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_tier2_az2" {
  subnet_id      = aws_subnet.private_tier2_az2.id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Security Groups
# -----------------------------------------------------------------------------
# Public Security Group
resource "aws_security_group" "public_sg" {
  name        = "${var.environment}-public-sg"
  description = "Public security group allowing VPC ingress, HTTP from anywhere, SSH from VPC, and VPC-only egress"
  vpc_id      = aws_vpc.main.id

  # Ingress: All traffic from the VPC CIDR
  ingress {
    description = "Allow all traffic from within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  # Ingress: SSH from VPC CIDR
  ingress {
    description = "Allow SSH from within the VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  # Ingress: HTTP from anywhere
  ingress {
    description = "Allow HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Egress: Outbound traffic only to the VPC CIDR
  egress {
    description = "Allow outbound traffic only to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name        = "${var.environment}-public-sg"
    Environment = var.environment
  }
}

# Private Security Group
resource "aws_security_group" "private_sg" {
  name        = "${var.environment}-private-sg"
  description = "Private security group allowing all traffic from VPC and egress only to VPC"
  vpc_id      = aws_vpc.main.id

  # Ingress: All traffic from the VPC CIDR
  ingress {
    description = "Allow all traffic from within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  # Egress: Outbound traffic only to the VPC CIDR
  egress {
    description = "Allow outbound traffic only to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name        = "${var.environment}-private-sg"
    Environment = var.environment
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the created VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = [aws_subnet.public_az1.id, aws_subnet.public_az2.id]
}

output "private_subnet_tier1_ids" {
  description = "IDs of tier 1 private subnets."
  value       = [aws_subnet.private_tier1_az1.id, aws_subnet.private_tier1_az2.id]
}

output "private_subnet_tier2_ids" {
  description = "IDs of tier 2 private subnets."
  value       = [aws_subnet.private_tier2_az1.id, aws_subnet.private_tier2_az2.id]
}

output "public_security_group_id" {
  description = "ID of the public security group."
  value       = aws_security_group.public_sg.id
}

output "private_security_group_id" {
  description = "ID of the private security group."
  value       = aws_security_group.private_sg.id
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "The AWS region to deploy resources into."
  default     = "us-east-1"
}

variable "name_suffix" {
  type        = string
  description = "Configurable suffix to append to all resource names."
  default     = ""
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM ROLE
# ---------------------------------------------------------------------------------------------------------------------

# Assume role policy document with wildcard principal
data "aws_iam_policy_document" "assume_role_trust_policy" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
  }
}

resource "aws_iam_role" "ci_role" {
  name               = "prod-ci-role${var.name_suffix}"
  assume_role_policy = data.aws_iam_policy_document.assume_role_trust_policy.json

  tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM POLICY
# ---------------------------------------------------------------------------------------------------------------------

# Policy document granting permission to assume the created role
data "aws_iam_policy_document" "assume_ci_role_policy_doc" {
  statement {
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.ci_role.arn]
  }
}

resource "aws_iam_policy" "ci_assume_policy" {
  name        = "prod-ci-policy${var.name_suffix}"
  description = "Policy allowing assumption of the prod-ci role"
  policy      = data.aws_iam_policy_document.assume_ci_role_policy_doc.json
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM GROUP & ATTACHMENT
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_iam_group" "ci_group" {
  name = "prod-ci-group${var.name_suffix}"
}

resource "aws_iam_group_policy_attachment" "ci_group_policy_attachment" {
  group      = aws_iam_group.ci_group.name
  policy_arn = aws_iam_policy.ci_assume_policy.arn
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM USER & MEMBERSHIP
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_iam_user" "ci_user" {
  name = "prod-ci-user${var.name_suffix}"

  tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_group_membership" "ci_group_membership" {
  name  = "prod-ci-membership${var.name_suffix}"
  users = [aws_iam_user.ci_user.name]
  group = aws_iam_group.ci_group.name
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "iam_role_arn" {
  description = "ARN of the CI IAM role"
  value       = aws_iam_role.ci_role.arn
}

output "iam_policy_arn" {
  description = "ARN of the assume role policy"
  value       = aws_iam_policy.ci_assume_policy.arn
}

output "iam_group_name" {
  description = "Name of the CI IAM group"
  value       = aws_iam_group.ci_group.name
}

output "iam_user_name" {
  description = "Name of the CI IAM user"
  value       = aws_iam_user.ci_user.name
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  description = "The AWS region to deploy the configuration aggregator into."
  type        = String
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      ManagedBy   = "Terraform"
      Environment = "Production"
    }
  }
}

# Fetch the current AWS caller identity (account ID)
data "aws_caller_identity" "current" {}

# Create the AWS Config Configuration Aggregator for the current account across all regions
resource "aws_config_configuration_aggregator" "default" {
  name = "default"

  account_aggregation_source {
    account_ids = [data.aws_caller_identity.current.account_id]
    all_regions = true
  }

  tags = {
    Name = "default"
  }
}

output "aggregator_arn" {
  description = "The ARN of the AWS Config configuration aggregator."
  value       = aws_config_configuration_aggregator.default.arn
}

output "aggregator_name" {
  description = "The name of the AWS Config configuration aggregator."
  value       = aws_config_configuration_aggregator.default.name
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region for infrastructure deployment"
  default     = "us-east-1"
}

variable "vpc_name" {
  type        = string
  description = "Name identifier for the VPC and related resources"
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  type        = string
  description = "The CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "ssh_inbound" {
  type        = list(string)
  description = "List of CIDR blocks permitted for SSH access"
  default     = ["10.0.0.0/16"]
}

variable "tags" {
  type        = map(string)
  description = "Additional tags to apply to all resources"
  default     = {}
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# VPC and Default Resources Management
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    var.tags,
    {
      Name = var.vpc_name
    }
  )
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-Default"
    }
  )
}

resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-Default"
    }
  )
}

# -----------------------------------------------------------------------------
# Subnets (Dynamic CIDRs across AZs)
# -----------------------------------------------------------------------------
# Calculate subnet bits needed: log2(AZ_count * 2) rounded up or fixed offset
# Splitting /16 into public (even indices) and private (odd indices)
locals {
  az_count = length(data.aws_availability_zones.available.names)
}

resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 4, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-public-${data.aws_availability_zones.available.names[count.index]}"
      Tier = "Public"
    }
  )
}

resource "aws_subnet" "private" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 4, count.index + local.az_count)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-private-${data.aws_availability_zones.available.names[count.index]}"
      Tier = "Private"
    }
  )
}

# -----------------------------------------------------------------------------
# Gateways & Outbound Connectivity
# -----------------------------------------------------------------------------
resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-igw"
    }
  )
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.gw]

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-nat-eip"
    }
  )
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id
  depends_on    = [aws_internet_gateway.gw]

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-nat-gw"
    }
  )
}

# -----------------------------------------------------------------------------
# Route Tables and Associations
# -----------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-public-rt"
    }
  )
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-private-rt"
    }
  )
}

resource "aws_route_table_association" "private" {
  count          = local.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Security Groups
# -----------------------------------------------------------------------------
resource "aws_security_group" "public" {
  name        = "${var.vpc_name}-public-sg"
  description = "Security group for public tier instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP inbound from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS inbound from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH inbound restricted"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.ssh_inbound
  }

  egress {
    description = "HTTP outbound to VPC only"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "HTTPS outbound to VPC only"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-public-sg"
    }
  )
}

resource "aws_security_group" "private" {
  name        = "${var.vpc_name}-private-sg"
  description = "Security group for private backend instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP inbound from public subnets"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [for s in aws_subnet.public : s.cidr_block]
  }

  ingress {
    description = "HTTPS inbound from public subnets"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [for s in aws_subnet.public : s.cidr_block]
  }

  egress {
    description = "HTTPS outbound to VPC only"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-private-sg"
    }
  )
}

# -----------------------------------------------------------------------------
# Network Access Control Lists (NACLs)
# -----------------------------------------------------------------------------
resource "aws_network_acl" "public" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [for s in aws_subnet.public : s.id]

  # Egress Rules
  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  egress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  egress {
    protocol   = "tcp"
    rule_no    = 120
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  # Ingress Rules
  ingress {
    protocol   = "tcp"
    rule_no    = 10
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 20
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 30
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-public-nacl"
    }
  )
}

# Public NACL Dynamic SSH Ingress entries
resource "aws_network_acl_rule" "public_ssh_ingress" {
  count          = length(var.ssh_inbound)
  network_acl_id = aws_network_acl.public.id
  rule_number    = 100 + count.index
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = var.ssh_inbound[count.index]
  from_port      = 22
  to_port        = 22
}

resource "aws_network_acl" "private" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [for s in aws_subnet.private : s.id]

  # Ingress ephemeral ports from everywhere
  ingress {
    protocol   = "tcp"
    rule_no    = 10
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  # Egress HTTPS to everywhere
  egress {
    protocol   = "tcp"
    rule_no    = 10
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  tags = merge(
    var.tags,
    {
      Name = "${var.vpc_name}-private-nacl"
    }
  )
}

# Private NACL Ingress: HTTP from public subnets
resource "aws_network_acl_rule" "private_ingress_http" {
  count          = length(aws_subnet.public)
  network_acl_id = aws_network_acl.private.id
  rule_number    = 100 + count.index
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = aws_subnet.public[count.index].cidr_block
  from_port      = 80
  to_port        = 80
}

# Private NACL Ingress: HTTPS from public subnets
resource "aws_network_acl_rule" "private_ingress_https" {
  count          = length(aws_subnet.public)
  network_acl_id = aws_network_acl.private.id
  rule_number    = 200 + count.index
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = aws_subnet.public[count.index].cidr_block
  from_port      = 443
  to_port        = 443
}

# Private NACL Egress: ephemeral return traffic to private subnets
resource "aws_network_acl_rule" "private_egress_ephemeral_to_private" {
  count          = length(aws_subnet.private)
  network_acl_id = aws_network_acl.private.id
  rule_number    = 300 + count.index
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = aws_subnet.private[count.index].cidr_block
  from_port      = 1024
  to_port        = 65535
}

# Private NACL Egress: ephemeral traffic to public subnets
resource "aws_network_acl_rule" "private_egress_ephemeral_to_public" {
  count          = length(aws_subnet.public)
  network_acl_id = aws_network_acl.private.id
  rule_number    = 400 + count.index
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = aws_subnet.public[count.index].cidr_block
  from_port      = 1024
  to_port        = 65535
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "List of IDs of public subnets"
  value       = [for s in aws_subnet.public : s.id]
}

output "private_subnet_ids" {
  description = "List of IDs of private subnets"
  value       = [for s in aws_subnet.private : s.id]
}

output "nat_gateway_ip" {
  description = "Elastic IP associated with the NAT Gateway"
  value       = aws_eip.nat.public_ip
}

output "public_security_group_id" {
  description = "Security Group ID for public tier"
  value       = aws_security_group.public.id
}

output "private_security_group_id" {
  description = "Security Group ID for private tier"
  value       = aws_security_group.private.id
}

