terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into."
  default     = "us-east-1"
}

variable "environment" {
  type        = string
  description = "Environment identifier (e.g., dev, staging, prod) used as a resource prefix."
  default     = "dev"
}

variable "target_account_id" {
  type        = string
  description = "The 12-digit AWS Account ID containing the target role with access to S3 software installation files."
  default     = "123456789012"

  validation {
    condition     = can(regex("^[0-9]{12}$", var.target_account_id))
    error_message = "The target_account_id must be a 12-digit AWS account ID."
  }
}

variable "target_role_name" {
  type        = string
  description = "The name of the IAM role in the target account to assume."
  default     = "s3-software-installer-role"
}

variable "tags" {
  type        = map(string)
  description = "A mapping of tags to assign to the resources."
  default = {
    ManagedBy = "Terraform"
    Purpose   = "PackerBuilder"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM ROLE & ASSUME ROLE POLICY FOR EC2 PACKER BUILDER
# ---------------------------------------------------------------------------------------------------------------------

# Trust policy allowing EC2 service to assume the Packer builder role
data "aws_iam_policy_document" "ec2_assume_role_policy" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# Packer Builder IAM Role
resource "aws_iam_role" "packer_builder_role" {
  name        = "${var.environment}-packer-builder-role"
  path        = "/"
  description = "IAM role for Packer builder EC2 instance to assume cross-account S3 access role."

  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role_policy.json

  tags = merge(
    var.tags,
    {
      Name        = "${var.environment}-packer-builder-role"
      Environment = var.environment
    }
  )
}

# ---------------------------------------------------------------------------------------------------------------------
# CROSS-ACCOUNT STS ASSUME ROLE POLICY
# ---------------------------------------------------------------------------------------------------------------------

# Policy allowing Packer builder instance to assume the target cross-account role
data "aws_iam_policy_document" "assume_target_role_policy" {
  statement {
    sid    = "AllowAssumeTargetAccountRole"
    effect = "Allow"
    actions = [
      "sts:AssumeRole"
    ]
    resources = [
      "arn:aws:iam::${var.target_account_id}:role/${var.target_role_name}"
    ]
  }
}

resource "aws_iam_policy" "packer_cross_account_policy" {
  name        = "${var.environment}-packer-cross-account-s3-assume-policy"
  path        = "/"
  description = "Allows Packer builder instance to assume target account role for S3 software installations."
  policy      = data.aws_iam_policy_document.assume_target_role_policy.json

  tags = merge(
    var.tags,
    {
      Name        = "${var.environment}-packer-cross-account-s3-assume-policy"
      Environment = var.environment
    }
  )
}

# Attach the policy to the Packer builder role
resource "aws_iam_role_policy_attachment" "packer_policy_attachment" {
  role       = aws_iam_role.packer_builder_role.name
  policy_arn = aws_iam_policy.packer_cross_account_policy.arn
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM INSTANCE PROFILE
# ---------------------------------------------------------------------------------------------------------------------

# Instance profile used by EC2 Packer builder instances
resource "aws_iam_instance_profile" "packer_instance_profile" {
  name = "${var.environment}-packer-builder-instance-profile"
  role = aws_iam_role.packer_builder_role.name

  tags = merge(
    var.tags,
    {
      Name        = "${var.environment}-packer-builder-instance-profile"
      Environment = var.environment
    }
  )
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "iam_role_arn" {
  description = "The ARN of the Packer builder IAM role."
  value       = aws_iam_role.packer_builder_role.arn
}

output "iam_role_name" {
  description = "The name of the Packer builder IAM role."
  value       = aws_iam_role.packer_builder_role.name
}

output "iam_instance_profile_name" {
  description = "The name of the Packer builder IAM instance profile."
  value       = aws_iam_instance_profile.packer_instance_profile.name
}

output "iam_instance_profile_arn" {
  description = "The ARN of the Packer builder IAM instance profile."
  value       = aws_iam_instance_profile.packer_instance_profile.arn
}

output "cross_account_role_arn_target" {
  description = "The full ARN of the target role that can be assumed."
  value       = "arn:aws:iam::${var.target_account_id}:role/${var.target_role_name}"
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy the resources"
  default     = "us-east-1"
}

variable "vpc_name" {
  type        = string
  description = "Name tag for the VPC"
  default     = "three-tier-vpc"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.16.0.0/16"
}

variable "presentation_subnet_cidr" {
  type        = string
  description = "CIDR block for the presentation tier subnet"
  default     = "10.16.0.0/24"
}

variable "application_subnet_cidr" {
  type        = string
  description = "CIDR block for the application tier subnet"
  default     = "10.16.1.0/24"
}

variable "data_subnet_cidr" {
  type        = string
  description = "CIDR block for the data tier subnet"
  default     = "10.16.2.0/24"
}

provider "aws" {
  region = variable.aws_region
}

# VPC Definition
resource "aws_vpc" "main" {
  cidr_block           = variable.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = variable.vpc_name
  }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${variable.vpc_name}-igw"
  }
}

# Presentation Subnet (Web Tier)
resource "aws_subnet" "presentation" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = variable.presentation_subnet_cidr
  map_public_ip_on_launch = true

  tags = {
    Name = "presentation-subnet"
  }
}

# Application Subnet (App Tier)
resource "aws_subnet" "application" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = variable.application_subnet_cidr
  map_public_ip_on_launch = false

  tags = {
    Name = "application-subnet"
  }
}

# Data Subnet (Database Tier)
resource "aws_subnet" "data" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = variable.data_subnet_cidr
  map_public_ip_on_launch = false

  tags = {
    Name = "data-subnet"
  }
}

# Presentation Route Table (Public Route Table)
resource "aws_route_table" "presentation" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "presentation-rt"
  }
}

# Route Table Association strictly for the presentation subnet
resource "aws_route_table_association" "presentation" {
  subnet_id      = aws_subnet.presentation.id
  route_table_id = aws_route_table.presentation.id
}

# Outputs
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "presentation_subnet_id" {
  description = "The ID of the presentation subnet"
  value       = aws_subnet.presentation.id
}

output "application_subnet_id" {
  description = "The ID of the application subnet"
  value       = aws_subnet.application.id
}

output "data_subnet_id" {
  description = "The ID of the data subnet"
  value       = aws_subnet.data.id
}

output "internet_gateway_id" {
  description = "The ID of the Internet Gateway"
  value       = aws_internet_gateway.igw.id
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "The AWS region to deploy resources into."
  default     = "us-east-1"
}

variable "role_name" {
  type        = string
  description = "Name of the Service Catalog launch constraint role."
  default     = "test_role"
}

variable "group_name" {
  type        = string
  description = "Name of the IAM group for Service Catalog testing."
  default     = "servicecatalog-test-group"
}

variable "user_name" {
  type        = string
  description = "Name of the IAM test user."
  default     = "servicecatalog-test-user"
}

provider "aws" {
  region = var.aws_region
}

# 1. IAM Role assumed by AWS Service Catalog for launch constraints
data "aws_iam_policy_document" "servicecatalog_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["servicecatalog.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "test_role" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.servicecatalog_assume_role.json

  tags = {
    Environment = "Testing"
    ManagedBy   = "Terraform"
    Purpose     = "ServiceCatalogLaunchConstraint"
  }
}

# 2. Scoped Launch Constraint Policy for Service Catalog role
data "aws_iam_policy_document" "launch_constraint_policy_doc" {
  statement {
    sid    = "CloudFormationPermissions"
    effect = "Allow"
    actions = [
      "cloudformation:CreateStack",
      "cloudformation:DeleteStack",
      "cloudformation:DescribeStackEvents",
      "cloudformation:DescribeStacks",
      "cloudformation:GetTemplateSummary",
      "cloudformation:SetStackPolicy",
      "cloudformation:ValidateTemplate",
      "cloudformation:UpdateStack"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3ScopedPermissions"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:CreateBucket",
      "s3:DeleteBucket"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "PassRoleToCloudFormation"
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = ["*"]
    condition {
      test     = "StringEqualsIfExists"
      variable = "iam:PassedToService"
      values   = ["cloudformation.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "launch_constraint_policy" {
  name        = "${var.role_name}-launch-constraint-policy"
  description = "Scoped launch constraint policy for Service Catalog testing"
  policy      = data.aws_iam_policy_document.launch_constraint_policy_doc.json
}

resource "aws_iam_role_policy_attachment" "launch_constraint_attachment" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.launch_constraint_policy.arn
}

# 3. IAM Group with Service Catalog End-User permissions
resource "aws_iam_group" "sc_group" {
  name = var.group_name
}

data "aws_iam_policy_document" "sc_group_policy_doc" {
  statement {
    sid    = "ServiceCatalogEndUserAccess"
    effect = "Allow"
    actions = [
      "servicecatalog:List*",
      "servicecatalog:Describe*",
      "servicecatalog:SearchProducts",
      "servicecatalog:SearchProductsAsAdmin",
      "servicecatalog:SearchProvisionedProducts",
      "servicecatalog:ProvisionProduct",
      "servicecatalog:UpdateProvisionedProduct",
      "servicecatalog:TerminateProvisionedProduct"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_group_policy" "sc_group_policy" {
  name   = "${var.group_name}-policy"
  group  = aws_iam_group.sc_group.name
  policy = data.aws_iam_policy_document.sc_group_policy_doc.json
}

# 4. IAM User with console access and group membership
resource "aws_iam_user" "sc_user" {
  name          = var.user_name
  force_destroy = true

  tags = {
    Environment = "Testing"
    ManagedBy   = "Terraform"
  }
}

resource "random_password" "user_password" {
  length           = 16
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_iam_user_login_profile" "sc_user_profile" {
  user                    = aws_iam_user.sc_user.name
  password_reset_required = false
  password                = random_password.user_password.result
}

resource "aws_iam_user_group_membership" "sc_user_membership" {
  user   = aws_iam_user.sc_user.name
  groups = [aws_iam_group.sc_group.name]
}

# Outputs
output "service_catalog_role_arn" {
  description = "ARN of the Service Catalog launch constraint IAM role"
  value       = aws_iam_role.test_role.arn
}

output "iam_group_name" {
  description = "Name of the IAM group"
  value       = aws_iam_group.sc_group.name
}

output "iam_user_name" {
  description = "Name of the console-enabled IAM test user"
  value       = aws_iam_user.sc_user.name
}

output "iam_user_initial_password" {
  description = "Initial generated console password for the IAM test user"
  value       = aws_iam_user_login_profile.sc_user_profile.password
  sensitive   = true
}
```

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
  default_tags {
    tags = {
      Datadog               = "true"
      DatadogAgentlessScanner = "true"
    }
  }
}

# --- Variables ---

variable "aws_region" {
  description = "AWS region to deploy the infrastructure."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "The CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the VPC."
  type        = string
  default     = "DatatogAgentlessScanner"
}

variable "enable_ssm_endpoints" {
  description = "Whether to provision SSM interface endpoints (ssm, ssmmessages, ec2messages)."
  type        = bool
  default     = false
}

# --- Data Sources ---

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  # Limit up to 3 AZs
  azs = slice(data.aws_availability_zones.available.names, 0, min(3, length(data.aws_availability_zones.available.names)))
}

# --- VPC and Gateways ---

resource "aws_vpc" "scanner_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.scanner_vpc.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

# --- Subnets ---

resource "aws_subnet" "public" {
  count                   = length(locals.azs)
  vpc_id                  = aws_vpc.scanner_vpc.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = locals.azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.vpc_name}-public-${locals.azs[count.index]}"
    Tier = "Public"
  }
}

resource "aws_subnet" "private" {
  count                   = length(locals.azs)
  vpc_id                  = aws_vpc.scanner_vpc.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index + 10)
  availability_zone       = locals.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.vpc_name}-private-${locals.azs[count.index]}"
    Tier = "Private"
  }
}

# --- NAT Gateway & Elastic IP ---

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-eip"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${var.vpc_name}-nat-gw"
  }

  depends_on = [aws_internet_gateway.igw]
}

# --- Route Tables and Associations ---

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.scanner_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${var.vpc_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.scanner_vpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "${var.vpc_name}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# --- S3 Gateway VPC Endpoint ---

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.scanner_vpc.id
  service_name      = "com.amazonaws.${var.aws_region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id, aws_route_table.private.id]

  tags = {
    Name = "${var.vpc_name}-vpce-s3"
  }
}

# --- Interface VPC Endpoints Security Group ---

resource "aws_security_group" "vpc_endpoints" {
  name        = "${var.vpc_name}-vpce-sg"
  description = "Security group for interface VPC endpoints permitting HTTPS from VPC"
  vpc_id      = aws_vpc.scanner_vpc.id

  ingress {
    description = "Allow TLS inbound from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.vpc_name}-vpce-sg"
  }
}

# --- Interface VPC Endpoints (Required: Lambda, EBS) ---

resource "aws_vpc_endpoint" "lambda" {
  vpc_id              = aws_vpc.scanner_vpc.id
  service_name        = "com.amazonaws.${var.aws_region}.lambda"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.vpc_name}-vpce-lambda"
  }
}

resource "aws_vpc_endpoint" "ebs" {
  vpc_id              = aws_vpc.scanner_vpc.id
  service_name        = "com.amazonaws.${var.aws_region}.ebs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.vpc_name}-vpce-ebs"
  }
}

# --- Optional SSM Interface VPC Endpoints ---

locals {
  ssm_services = var.enable_ssm_endpoints ? toset(["ec2messages", "ssmmessages", "ssm"]) : toset([])
}

resource "aws_vpc_endpoint" "ssm_endpoints" {
  for_each = local.ssm_services

  vpc_id              = aws_vpc.scanner_vpc.id
  service_name        = "com.amazonaws.${var.aws_region}.${each.key}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "${var.vpc_name}-vpce-${each.key}"
  }
}

# --- Outputs ---

output "vpc_id" {
  description = "The ID of the VPC."
  value       = aws_vpc.scanner_vpc.id
}

output "public_subnet_ids" {
  description = "List of public subnet IDs."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "List of private subnet IDs."
  value       = aws_subnet.private[*].id
}

output "nat_gateway_ip" {
  description = "Public Elastic IP assigned to the NAT Gateway."
  value       = aws_eip.nat.public_ip
}

output "vpc_endpoint_security_group_id" {
  description = "ID of the security group attached to the interface VPC endpoints."
  value       = aws_security_group.vpc_endpoints.id
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

variable "name" {
  type        = string
  description = "Base name for the resources"
  default     = "app"
}

variable "environment" {
  type        = string
  description = "Environment name (e.g. prod, dev, stage)"
  default     = "dev"
}

variable "enable" {
  type        = bool
  description = "Main enable toggle for creating and managing security group resources"
  default     = true
}

variable "create_sg" {
  type        = bool
  description = "Set to true to create a new security group, false to attach rules to an existing one"
  default     = true
}

variable "existing_sg_id" {
  type        = string
  description = "The ID of an existing security group when create_sg is false"
  default     = ""
}

variable "vpc_id" {
  type        = string
  description = "The VPC ID to associate the security group with. If blank and create_sg is true, a fallback VPC will be created."
  default     = ""
}

variable "create_prefix_list" {
  type        = bool
  description = "Toggle to create an AWS managed prefix list"
  default     = false
}

variable "prefix_list_entries" {
  type = list(object({
    cidr        = string
    description = optional(string)
  }))
  description = "Entries to include in the managed prefix list"
  default = [
    {
      cidr        = "10.0.0.0/24"
      description = "Internal network segment"
    }
  ]
}

variable "prefix_list_max_entries" {
  type        = number
  description = "Maximum entries allowed in the managed prefix list"
  default     = 5
}

variable "ingress_cidr_rules" {
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
    description = optional(string)
  }))
  description = "Ingress rules by CIDR blocks"
  default = [
    {
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      cidr_blocks = ["10.0.0.0/8"]
      description = "HTTPS ingress from internal"
    }
  ]
}

variable "ingress_self_rules" {
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = optional(string)
  }))
  description = "Ingress self-referencing rules"
  default     = []
}

variable "ingress_source_sg_rules" {
  type = list(object({
    from_port         = number
    to_port           = number
    protocol          = string
    source_sg_id      = string
    description       = optional(string)
  }))
  description = "Ingress rules allowing traffic from source security groups"
  default     = []
}

variable "ingress_prefix_list_rules" {
  type = list(object({
    from_port       = number
    to_port         = number
    protocol        = string
    prefix_list_ids = optional(list(string))
    description     = optional(string)
  }))
  description = "Ingress rules allowing traffic from prefix lists"
  default     = []
}

variable "egress_cidr_rules" {
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
    description = optional(string)
  }))
  description = "Egress rules by CIDR blocks"
  default = [
    {
      from_port   = 0
      to_port     = 0
      protocol    = "-1"
      cidr_blocks = ["0.0.0.0/0"]
      description = "Allow all outbound traffic"
    }
  ]
}

variable "egress_self_rules" {
  type = list(object({
    from_port   = number
    to_port     = number
    protocol    = string
    description = optional(string)
  }))
  description = "Egress self-referencing rules"
  default     = []
}

variable "egress_source_sg_rules" {
  type = list(object({
    from_port         = number
    to_port           = number
    protocol          = string
    source_sg_id      = string
    description       = optional(string)
  }))
  description = "Egress rules allowing traffic to target security groups"
  default     = []
}

variable "egress_prefix_list_rules" {
  type = list(object({
    from_port       = number
    to_port         = number
    protocol        = string
    prefix_list_ids = optional(list(string))
    description     = optional(string)
  }))
  description = "Egress rules allowing traffic to prefix lists"
  default     = []
}

# ---------------------------------------------------------------------------------------------------------------------
# LABELS MODULE
# ---------------------------------------------------------------------------------------------------------------------

module "labels" {
  source      = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"
  name        = var.name
  environment = var.environment
}

# ---------------------------------------------------------------------------------------------------------------------
# FALLBACK VPC
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_vpc" "fallback" {
  count                = var.enable && var.create_sg && var.vpc_id == "" ? 1 : 0
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    module.labels.tags,
    {
      Name = "${module.labels.id}-fallback-vpc"
    }
  )
}

locals {
  vpc_id = var.vpc_id != "" ? var.vpc_id : (length(aws_vpc.fallback) > 0 ? aws_vpc.fallback[0].id : "")
}

# ---------------------------------------------------------------------------------------------------------------------
# MANAGED PREFIX LIST
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_ec2_managed_prefix_list" "this" {
  count          = var.enable && var.create_prefix_list ? 1 : 0
  name           = "${module.labels.id}-prefix-list"
  address_family = "IPv4"
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = lookup(entry.value, "description", null)
    }
  }

  tags = merge(
    module.labels.tags,
    {
      Name = "${module.labels.id}-prefix-list"
    }
  )
}

# ---------------------------------------------------------------------------------------------------------------------
# SECURITY GROUP
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_security_group" "this" {
  count       = var.enable && var.create_sg ? 1 : 0
  name        = "${module.labels.id}-sg"
  description = "Managed security group for ${module.labels.id}"
  vpc_id      = local.vpc_id

  tags = merge(
    module.labels.tags,
    {
      Name = "${module.labels.id}-sg"
    }
  )

  lifecycle {
    create_before_destroy = true
  }
}

locals {
  target_sg_id = var.enable ? (var.create_sg ? try(aws_security_group.this[0].id, "") : var.existing_sg_id) : ""
  created_pl_id = length(aws_ec2_managed_prefix_list.this) > 0 ? aws_ec2_managed_prefix_list.this[0].id : ""
}

# ---------------------------------------------------------------------------------------------------------------------
# INGRESS RULES
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_security_group_rule" "ingress_cidr" {
  for_each          = var.enable ? { for idx, rule in var.ingress_cidr_rules : idx => rule } : {}
  security_group_id = local.target_sg_id
  type              = "ingress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  cidr_blocks       = each.value.cidr_blocks
  description       = lookup(each.value, "description", null)
}

resource "aws_security_group_rule" "ingress_self" {
  for_each          = var.enable ? { for idx, rule in var.ingress_self_rules : idx => rule } : {}
  security_group_id = local.target_sg_id
  type              = "ingress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  self              = true
  description       = lookup(each.value, "description", null)
}

resource "aws_security_group_rule" "ingress_source_sg" {
  for_each                 = var.enable ? { for idx, rule in var.ingress_source_sg_rules : idx => rule } : {}
  security_group_id        = local.target_sg_id
  type                     = "ingress"
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  source_security_group_id = each.value.source_sg_id
  description              = lookup(each.value, "description", null)
}

resource "aws_security_group_rule" "ingress_prefix_list" {
  for_each          = var.enable ? { for idx, rule in var.ingress_prefix_list_rules : idx => rule } : {}
  security_group_id = local.target_sg_id
  type              = "ingress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  prefix_list_ids   = (lookup(each.value, "prefix_list_ids", null) != null && length(lookup(each.value, "prefix_list_ids", [])) > 0) ? each.value.prefix_list_ids : [local.created_pl_id]
  description       = lookup(each.value, "description", null)
}

# ---------------------------------------------------------------------------------------------------------------------
# EGRESS RULES
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_security_group_rule" "egress_cidr" {
  for_each          = var.enable ? { for idx, rule in var.egress_cidr_rules : idx => rule } : {}
  security_group_id = local.target_sg_id
  type              = "egress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  cidr_blocks       = each.value.cidr_blocks
  description       = lookup(each.value, "description", null)
}

resource "aws_security_group_rule" "egress_self" {
  for_each          = var.enable ? { for idx, rule in var.egress_self_rules : idx => rule } : {}
  security_group_id = local.target_sg_id
  type              = "egress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  self              = true
  description       = lookup(each.value, "description", null)
}

resource "aws_security_group_rule" "egress_source_sg" {
  for_each                 = var.enable ? { for idx, rule in var.egress_source_sg_rules : idx => rule } : {}
  security_group_id        = local.target_sg_id
  type                     = "egress"
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  source_security_group_id = each.value.source_sg_id
  description              = lookup(each.value, "description", null)
}

resource "aws_security_group_rule" "egress_prefix_list" {
  for_each          = var.enable ? { for idx, rule in var.egress_prefix_list_rules : idx => rule } : {}
  security_group_id = local.target_sg_id
  type              = "egress"
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  prefix_list_ids   = (lookup(each.value, "prefix_list_ids", null) != null && length(lookup(each.value, "prefix_list_ids", [])) > 0) ? each.value.prefix_list_ids : [local.created_pl_id]
  description       = lookup(each.value, "description", null)
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "security_group_id" {
  description = "The ID of the security group being managed"
  value       = local.target_sg_id
}

output "prefix_list_id" {
  description = "The ID of the created managed prefix list if enabled"
  value       = local.created_pl_id
}

output "vpc_id" {
  description = "The VPC ID used by the security group"
  value       = local.vpc_id
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "role_name" {
  type        = string
  description = "Name of the IAM role for CloudForecast"
  default     = "CloudForecast-ZeroWaste"
}

variable "external_id" {
  type        = string
  description = "External ID condition for the CloudForecast assume role trust policy"
  default     = "benchmark-external-id"
}

variable "trusted_account_arn" {
  type        = string
  description = "External principal ARN permitted to assume the role"
  default     = "arn:aws:iam::656227328603:root"
}

# -----------------------------------------------------------------------------
# IAM Role with Assume Role Trust Policy
# -----------------------------------------------------------------------------
resource "aws_iam_role" "cloudforecast_role" {
  name        = var.role_name
  description = "Dedicated IAM integration role for CloudForecast read-only cost optimization"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudForecastAssumeRole"
        Effect = "Allow"
        Principal = {
          AWS = var.trusted_account_arn
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = var.external_id
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# 15 Discrete Inline IAM Policies
# -----------------------------------------------------------------------------

# 1. CloudWatch Metrics & Tagging
resource "aws_iam_role_policy" "cloudwatch_metrics_tags" {
  name = "CloudForecast_CloudWatchMetricsAndTags"
  role = aws_iam_role.cloudforecast_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "CloudWatchMetricsAndResourceTagging"
        Effect   = "Allow"
        Action   = [
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:GetMetricData",
          "cloudwatch:ListMetrics",
          "tag:GetResources",
          "tag:GetTagKeys",
          "tag:GetTagValues"
        ]
        Resource = "*"
      }
    ]
  })
}

# 2. AWS Organizations
resource "aws_iam_role_policy" "organizations" {
  name = "CloudForecast_Organizations"
  role = aws_iam_role.cloudforecast_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "OrganizationsListAccounts"
        Effect   = "Allow"
        Action   = [
          "organizations:ListAccounts",
          "organizations:DescribeOrganization"
        ]
        Resource = "*"
      }
    ]
  })
}

# 3. Application & Network Load Balancers (ElasticLoadBalancing v2)
resource "aws_iam_role_policy" "elbv2_load_balancers" {
  name = "CloudForecast_ELBv2"
  role = aws_iam_role.cloudforecast_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DescribeELBv2"
        Effect   = "Allow"
        Action   = [
          "elasticloadbalancing:DescribeLoadBalancers",
          "elasticloadbalancing:DescribeListeners",
          "elasticloadbalancing:DescribeTargetGroups",
          "elasticloadbalancing:DescribeTargetHealth",
          "elasticloadbalancing:DescribeTags"
        ]
        Resource = "*"
      }
    ]
  })
}

# 4. Classic Load Balancers
resource "aws_iam_role_policy" "classic_load_balancers" {
  name = "CloudForecast_ClassicELB"
  role = aws_iam_role.cloudforecast_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DescribeClassicELB"
        Effect   = "Allow"
        Action   = [
          "elasticloadbalancing:DescribeLoadBalancerAttributes",
          "elasticloadbalancing:DescribeInstanceHealth"
        ]
        Resource = "*"
      }
    ]
  })
}

# 5. EBS Snapshots
resource "aws_iam_role_policy" "ebs_snapshots" {
  name = "CloudForecast_EBSSnapshots"
  role = aws_iam_role.cloudforecast_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DescribeEBSSnapshots"
        Effect   = "Allow"
        Action   = [
          "ec2:DescribeSnapshots",
          "ec2:DescribeSnapshotAttribute"
        ]
        Resource = "*"
      }
    ]
  })
}

# 6. EBS Volumes
resource "aws_iam_role_policy" "ebs_volumes" {
  name = "CloudForecast_EBSVolumes"
  role = aws_iam_role.cloudforecast_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DescribeEBSVolumes"
        Effect   = "Allow"
        Action   = [
          "ec2:DescribeVolumes",
          "ec2:DescribeVolumeStatus",
          "ec2:DescribeVolumeAttribute"
        ]
        Resource = "*"
      }
    ]
  })
}

# 7. EC2 Instances
resource "aws_iam_role_policy" "ec2_instances" {
  name = "CloudForecast_EC2Instances"
  role = aws_iam_role.cloudforecast_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DescribeEC2Instances"
        Effect   = "Allow"
        Action   = [
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeInstanceTypes",
          "ec2:DescribeRegions",
          "ec2:DescribeAvailabilityZones"
        ]
        Resource = "*"
      }
    ]
  })
}

# 8. EC2 Tags & General Metadata
resource "aws_iam_role_policy" "ec2_tags" {
  name = "CloudForecast_EC2Tags"
  role = aws_iam_role.cloudforecast_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DescribeEC2Tags"
        Effect   = "Allow"
        Action   = [
          "ec2:DescribeTags"
        ]
        Resource = "*"
      }
    ]
  })
}

# 9. RDS Instances & Clusters
resource "aws_iam_role_policy" "rds_instances" {
  name = "CloudForecast_RDSInstances"
  role = aws_iam_role.cloudforecast_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DescribeRDSInstances"
        Effect   = "Allow"
        Action   = [
          "rds:DescribeDBInstances",
          "rds:DescribeDBClusters",
          "rds:ListTagsForResource"
        ]
        Resource = "*"
      }
    ]
  })
}

# 10. RDS Snapshots
resource "aws_iam_role_policy" "rds_snapshots" {
  name = "CloudForecast_RDSSnapshots"
  role = aws_iam_role.cloudforecast_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DescribeRDSSnapshots"
        Effect   = "Allow"
        Action   = [
          "rds:DescribeDBSnapshots",
          "rds:DescribeDBClusterSnapshots",
          "rds:DescribeDBSnapshotAttributes"
        ]
        Resource = "*"
      }
    ]
  })
}

# 11. S3 Bucket Metadata & Inventory
resource "aws_iam_role_policy" "s3_bucket_metadata" {
  name = "CloudForecast_S3BucketMetadata"
  role = aws_iam_role.cloudforecast_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "S3BucketMetadataAndTags"
        Effect   = "Allow"
        Action   = [
          "s3:ListAllMyBuckets",
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:GetBucketTagging"
        ]
        Resource = "*"
      }
    ]
  })
}

# 12. S3 Lifecycle Configuration
resource "aws_iam_role_policy" "s3_lifecycle" {
  name = "CloudForecast_S3Lifecycle"
  role = aws_iam_role.cloudforecast_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "S3LifecycleConfiguration"
        Effect   = "Allow"
        Action   = [
          "s3:GetLifecycleConfiguration"
        ]
        Resource = "*"
      }
    ]
  })
}

# 13. CloudWatch Log Groups
resource "aws_iam_role_policy" "cloudwatch_logs" {
  name = "CloudForecast_CloudWatchLogs"
  role = aws_iam_role.cloudforecast_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DescribeLogGroups"
        Effect   = "Allow"
        Action   = [
          "logs:DescribeLogGroups"
        ]
        Resource = "*"
      }
    ]
  })
}

# 14. AWS Support
resource "aws_iam_role_policy" "aws_support" {
  name = "CloudForecast_AWSSupport"
  role = aws_iam_role.cloudforecast_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "SupportRead"
        Effect   = "Allow"
        Action   = [
          "support:DescribeServices",
          "support:DescribeSeverityLevels",
          "support:DescribeCases"
        ]
        Resource = "*"
      }
    ]
  })
}

# 15. Trusted Advisor Checks
resource "aws_iam_role_policy" "trusted_advisor" {
  name = "CloudForecast_TrustedAdvisor"
  role = aws_iam_role.cloudforecast_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "TrustedAdvisorChecks"
        Effect   = "Allow"
        Action   = [
          "support:DescribeTrustedAdvisorChecks",
          "support:DescribeTrustedAdvisorCheckSummaries",
          "support:DescribeTrustedAdvisorCheckResult",
          "support:RefreshTrustedAdvisorCheck"
        ]
        Resource = "*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "iam_role_arn" {
  description = "ARN of the created CloudForecast IAM integration role"
  value       = aws_iam_role.cloudforecast_role.arn
}

output "iam_role_name" {
  description = "Name of the created CloudForecast IAM integration role"
  value       = aws_iam_role.cloudforecast_role.name
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "The AWS region to deploy resources into."
  default     = "us-east-1"
}

variable "environment" {
  type        = string
  description = "Environment suffix used in naming conventions (e.g. dev, prod)."
  default     = "dev"
}

variable "enable_db_dr_user" {
  type        = bool
  description = "Toggle for creating the Database Disaster Recovery user and policy."
  default     = true
}

variable "enable_data_exports_user" {
  type        = bool
  description = "Toggle for creating the Data Exports user and policy."
  default     = true
}

variable "data_export_bucket_arn" {
  type        = string
  description = "The ARN of the S3 bucket used for data exports."
  default     = "arn:aws:s3:::mattermost-data-exports-bucket-example"
}

variable "enable_packer_builder_user" {
  type        = bool
  description = "Toggle for creating the Packer Image Builder user and policy."
  default     = true
}

variable "packer_monitoring_bucket_arn" {
  type        = string
  description = "The ARN of the S3 bucket used for Packer monitoring state."
  default     = "arn:aws:s3:::mattermost-packer-monitoring-bucket-example"
}

variable "packer_server_role_name" {
  type        = string
  description = "The name of the dedicated server IAM role that Packer can pass."
  default     = "MattermostServerRole"
}

# -----------------------------------------------------------------------------
# 1. Cost Reporting IAM User (Mandatory)
# -----------------------------------------------------------------------------
resource "aws_iam_user" "cost_report_user" {
  name = "mattermost-cost-report-${var.environment}"
  path = "/service-users/"
  tags = {
    Environment = var.environment
    Service     = "CostReporting"
  }
}

resource "aws_iam_user_policy" "cost_report_policy" {
  name = "mattermost-cost-report-policy-${var.environment}"
  user = aws_iam_user.cost_report_user.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowCostExplorerFullAccess"
        Effect   = "Allow"
        Action   = "ce:*"
        Resource = "*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# 2. Database Disaster Recovery User (Conditional)
# -----------------------------------------------------------------------------
resource "aws_iam_user" "db_dr_user" {
  count = var.enable_db_dr_user ? 1 : 0
  name  = "mattermost-db-dr-${var.environment}"
  path  = "/service-users/"
  tags = {
    Environment = var.environment
    Service     = "DisasterRecovery"
  }
}

resource "aws_iam_user_policy" "db_dr_policy" {
  count = var.enable_db_dr_user ? 1 : 0
  name  = "mattermost-db-dr-policy-${var.environment}"
  user  = aws_iam_user.db_dr_user[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowRDSAndKMSAccess"
        Effect = "Allow"
        Action = [
          "rds:*",
          "kms:*"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowSecretsManagerMultiTenantSecrets"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
          "secretsmanager:ListSecretVersionIds"
        ]
        Resource = "arn:aws:secretsmanager:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:secret:rds-cluster-multitenant-*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# 3. Data Exports User (Conditional)
# -----------------------------------------------------------------------------
resource "aws_iam_user" "data_exports_user" {
  count = var.enable_data_exports_user ? 1 : 0
  name  = "mattermost-data-exports-${var.environment}"
  path  = "/service-users/"
  tags = {
    Environment = var.environment
    Service     = "DataExports"
  }
}

resource "aws_iam_user_policy" "data_exports_policy" {
  count = var.enable_data_exports_user ? 1 : 0
  name  = "mattermost-data-exports-policy-${var.environment}"
  user  = aws_iam_user.data_exports_user[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowBucketListing"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = var.data_export_bucket_arn
      },
      {
        Sid    = "AllowObjectReadWrite"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:AbortMultipartUpload",
          "s3:ListMultipartUploadParts"
        ]
        Resource = "${var.data_export_bucket_arn}/*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# 4. Packer Image Builder User (Conditional)
# -----------------------------------------------------------------------------
resource "aws_iam_user" "packer_builder_user" {
  count = var.enable_packer_builder_user ? 1 : 0
  name  = "mattermost-packer-builder-${var.environment}"
  path  = "/service-users/"
  tags = {
    Environment = var.environment
    Service     = "PackerBuilder"
  }
}

resource "aws_iam_user_policy" "packer_builder_policy" {
  count = var.enable_packer_builder_user ? 1 : 0
  name  = "mattermost-packer-builder-policy-${var.environment}"
  user  = aws_iam_user.packer_builder_user[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2AndAutoScalingPermissions"
        Effect = "Allow"
        Action = [
          "ec2:AttachVolume",
          "ec2:AuthorizeSecurityGroupIngress",
          "ec2:CopyImage",
          "ec2:CreateImage",
          "ec2:CreateKeypair",
          "ec2:CreateSecurityGroup",
          "ec2:CreateSnapshot",
          "ec2:CreateTags",
          "ec2:CreateVolume",
          "ec2:DeleteKeyPair",
          "ec2:DeleteSecurityGroup",
          "ec2:DeleteSnapshot",
          "ec2:DeleteVolume",
          "ec2:DeregisterImage",
          "ec2:DescribeImageAttribute",
          "ec2:DescribeImages",
          "ec2:DescribeInstances",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeRegions",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSnapshots",
          "ec2:DescribeSubnets",
          "ec2:DescribeTags",
          "ec2:DescribeVolumes",
          "ec2:DescribeVpcs",
          "ec2:DetachVolume",
          "ec2:GetPasswordData",
          "ec2:ModifyImageAttribute",
          "ec2:ModifyInstanceAttribute",
          "ec2:ModifySnapshotAttribute",
          "ec2:RegisterImage",
          "ec2:RunInstances",
          "ec2:StopInstances",
          "ec2:TerminateInstances",
          "autoscaling:DescribeAutoScalingGroups",
          "autoscaling:DescribeLaunchConfigurations"
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudWatchEventsAndSSM"
        Effect = "Allow"
        Action = [
          "events:DescribeRule",
          "events:ListRuleNamesByTarget",
          "events:ListRules",
          "events:ListTargetsByRule",
          "ssm:DescribeParameters",
          "ssm:GetParameter",
          "ssm:GetParameters"
        ]
        Resource = "*"
      },
      {
        Sid    = "IAMInspectPermissions"
        Effect = "Allow"
        Action = [
          "iam:GetInstanceProfile",
          "iam:GetRole",
          "iam:ListInstanceProfiles"
        ]
        Resource = "*"
      },
      {
        Sid    = "S3MonitoringAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          var.packer_monitoring_bucket_arn,
          "${var.packer_monitoring_bucket_arn}/*"
        ]
      },
      {
        Sid    = "LambdaBindNetworkAttachmentConfig"
        Effect = "Allow"
        Action = [
          "lambda:GetFunction",
          "lambda:GetFunctionConfiguration",
          "lambda:UpdateFunctionConfiguration"
        ]
        Resource = "arn:aws:lambda:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:function:bind-server-network-attachment"
      },
      {
        Sid    = "PassRoleToServerRole"
        Effect = "Allow"
        Action = [
          "iam:PassRole"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/${var.packer_server_role_name}"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "cost_report_user_arn" {
  description = "The ARN of the Cost Report IAM user."
  value       = aws_iam_user.cost_report_user.arn
}

output "db_dr_user_arn" {
  description = "The ARN of the Database DR IAM user, if enabled."
  value       = try(aws_iam_user.db_dr_user[0].arn, null)
}

output "data_exports_user_arn" {
  description = "The ARN of the Data Exports IAM user, if enabled."
  value       = try(aws_iam_user.data_exports_user[0].arn, null)
}

output "packer_builder_user_arn" {
  description = "The ARN of the Packer Builder IAM user, if enabled."
  value       = try(aws_iam_user.packer_builder_user[0].arn, null)
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "AWS region for resources"
  default     = "us-east-1"
}

variable "output_bucket_name" {
  type        = string
  description = "Name of the S3 output bucket for HealthOmics"
  default     = "tf-benchmark-omics-output-bucket"
}

variable "service_account_username" {
  type        = string
  description = "Name of the IAM user for programmatic access"
  default     = "workbench-health-omics"
}

variable "service_role_name" {
  type        = string
  description = "Name of the IAM role assumed by Amazon HealthOmics"
  default     = "HealthOmicsRole"
}

variable "service_policy_name" {
  type        = string
  description = "Name of the IAM policy attached to the HealthOmics service role"
  default     = "HealthOmicsServicePolicy"
}

variable "user_policy_name" {
  type        = string
  description = "Name of the IAM policy attached to the user"
  default     = "HealthOmicsUserPolicy"
}

variable "ecr_repository_names" {
  type        = set(string)
  description = "Set of ECR repository names to create for workflow containers"
  default     = ["healthomics-workflows"]
}

variable "external_account_ids" {
  type        = list(string)
  description = "List of external AWS Account IDs granted cross-account pull access to ECR"
  default     = []
}

variable "additional_read_bucket_arns" {
  type        = list(string)
  description = "Optional additional S3 bucket ARNs for read-only access by the user/service"
  default     = []
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# KMS Key for S3 Encryption
# ------------------------------------------------------------------------------

resource "aws_kms_key" "omics_kms_key" {
  description             = "KMS Key for HealthOmics S3 Bucket Encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "omics-kms-policy"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowHealthOmicsServiceKeyUsage"
        Effect    = "Allow"
        Principal = {
          Service = "omics.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "omics_kms_alias" {
  name          = "alias/omics-output-key"
  target_key_id = aws_kms_key.omics_kms_key.key_id
}

# ------------------------------------------------------------------------------
# S3 Output Bucket
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "output_bucket" {
  bucket        = var.output_bucket_name
  force_destroy = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "output_bucket_crypto" {
  bucket = aws_s3_bucket.output_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.omics_kms_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "output_bucket_pab" {
  bucket = aws_s3_bucket.output_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# ECR Repositories
# ------------------------------------------------------------------------------

resource "aws_ecr_repository" "workflow_repos" {
  for_each             = var.ecr_repository_names
  name                 = each.value
  image_tag_mutability = "MUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }
}

resource "aws_ecr_repository_policy" "workflow_repos_policy" {
  for_each   = aws_ecr_repository.workflow_repos
  repository = each.value.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Sid    = "AllowOmicsServicePull"
          Effect = "Allow"
          Principal = {
            Service = "omics.amazonaws.com"
          }
          Action = [
            "ecr:BatchCheckLayerAvailability",
            "ecr:GetDownloadUrlForLayer",
            "ecr:BatchGetImage"
          ]
        }
      ],
      length(var.external_account_ids) > 0 ? [
        {
          Sid    = "AllowExternalAccountsPull"
          Effect = "Allow"
          Principal = {
            AWS = [for id in var.external_account_ids : "arn:aws:iam::${id}:root"]
          }
          Action = [
            "ecr:BatchCheckLayerAvailability",
            "ecr:GetDownloadUrlForLayer",
            "ecr:BatchGetImage"
          ]
        }
      ] : []
    )
  })
}

# ------------------------------------------------------------------------------
# IAM Service Role for HealthOmics
# ------------------------------------------------------------------------------

resource "aws_iam_role" "omics_service_role" {
  name = var.service_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "omics.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "omics_service_policy" {
  name        = var.service_policy_name
  description = "IAM Policy for Amazon HealthOmics Service Role"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3Access"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = concat(
          [
            aws_s3_bucket.output_bucket.arn,
            "${aws_s3_bucket.output_bucket.arn}/*"
          ],
          var.additional_read_bucket_arns,
          [for arn in var.additional_read_bucket_arns : "${arn}/*"]
        )
      },
      {
        Sid    = "KmsAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.omics_kms_key.arn]
      },
      {
        Sid    = "ECRImagePull"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:GetAuthorizationToken"
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "service_role_attachment" {
  role       = aws_iam_role.omics_service_role.name
  policy_arn = aws_iam_policy.omics_service_policy.arn
}

# ------------------------------------------------------------------------------
# IAM Workbench User
# ------------------------------------------------------------------------------

resource "aws_iam_user" "workbench_user" {
  name = var.service_account_username
}

resource "aws_iam_access_key" "workbench_user_key" {
  user = aws_iam_user.workbench_user.name
}

resource "aws_iam_policy" "workbench_user_policy" {
  name        = var.user_policy_name
  description = "IAM Policy for Omics Workbench User allowing omics actions, pass role, and bucket access"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "HealthOmicsFullAccess"
        Effect = "Allow"
        Action = [
          "omics:*"
        ]
        Resource = "*"
      },
      {
        Sid    = "PassRoleToOmicsService"
        Effect = "Allow"
        Action = [
          "iam:PassRole"
        ]
        Resource = aws_iam_role.omics_service_role.arn
        Condition = {
          StringEquals = {
            "iam:PassedToService" = "omics.amazonaws.com"
          }
        }
      },
      {
        Sid    = "S3ReadOnlyAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = concat(
          [
            aws_s3_bucket.output_bucket.arn,
            "${aws_s3_bucket.output_bucket.arn}/*"
          ],
          var.additional_read_bucket_arns,
          [for arn in var.additional_read_bucket_arns : "${arn}/*"]
        )
      },
      {
        Sid    = "KmsDecryptAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.omics_kms_key.arn]
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "workbench_user_attachment" {
  user       = aws_iam_user.workbench_user.name
  policy_arn = aws_iam_policy.workbench_user_policy.arn
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "output_bucket_arn" {
  description = "ARN of the output S3 bucket"
  value       = aws_s3_bucket.output_bucket.arn
}

output "omics_role_arn" {
  description = "ARN of the HealthOmics IAM service role"
  value       = aws_iam_role.omics_service_role.arn
}

output "workbench_user_arn" {
  description = "ARN of the IAM workbench user"
  value       = aws_iam_user.workbench_user.arn
}

output "workbench_access_key_id" {
  description = "Access key ID for the workbench user"
  value       = aws_iam_access_key.workbench_user_key.id
}

output "workbench_secret_access_key" {
  description = "Secret access key for the workbench user"
  value       = aws_iam_access_key.workbench_user_key.secret
  sensitive   = true
}

output "ecr_repository_arns" {
  description = "ARNs of the created ECR repositories"
  value       = { for k, v in aws_ecr_repository.workflow_repos : k => v.arn }
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "The AWS region where resources will be created."
  default     = "us-east-1"
}

variable "cluster_name" {
  type        = string
  description = "The base name for the cluster and associated resources."
  default     = "benchmark"
}

variable "vpc_cidr_network_octets" {
  type        = string
  description = "The first two octets of the VPC CIDR block (e.g., '10.0')."
  default     = "10.0"
}

variable "default_tags" {
  type        = map(string)
  description = "A map of default tags to apply to all resources."
  default     = {}
}

provider "aws" {
  region = var.aws_region
  default_tags {
    tags = var.default_tags
  }
}

# Fetch availability zones in the current region
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_suffixes         = ["a", "b", "c"]
  public_subnet_cidrs = [
    "${var.vpc_cidr_network_octets}.12.0/22",
    "${var.vpc_cidr_network_octets}.16.0/22",
    "${var.vpc_cidr_network_octets}.20.0/22"
  ]
  private_subnet_cidrs = [
    "${var.vpc_cidr_network_octets}.0.0/22",
    "${var.vpc_cidr_network_octets}.4.0/22",
    "${var.vpc_cidr_network_octets}.8.0/22"
  ]
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "${var.vpc_cidr_network_octets}.0.0/16"
  enable_dns_hostnames = false
  enable_dns_support   = true

  tags = {
    Name = "${var.cluster_name}-vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.cluster_name}-ig"
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = "${var.aws_region}${local.az_suffixes[count.index]}"
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.cluster_name}-public-subnet-${local.az_suffixes[count.index]}"
  }
}

# Private Subnets
resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = "${var.aws_region}${local.az_suffixes[count.index]}"

  tags = {
    Name = "${var.cluster_name}-private-subnet-${local.az_suffixes[count.index]}"
  }
}

# Shared Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.cluster_name}-public-rt"
  }
}

# Public Route Table Associations
resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Elastic IPs for NAT Gateways
resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"

  tags = {
    Name = "${var.cluster_name}-nat-eip-${local.az_suffixes[count.index]}"
  }
}

# NAT Gateways
resource "aws_nat_gateway" "nat" {
  count         = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.cluster_name}-nat-gw-${local.az_suffixes[count.index]}"
  }

  depends_on = [aws_internet_gateway.main]
}

# Private Route Tables
resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = {
    Name = "${var.cluster_name}-private-rt-${local.az_suffixes[count.index]}"
  }
}

# Private Route Table Associations
resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ECS Cluster
resource "aws_ecs_cluster" "main" {
  name = "dit-paas-${var.cluster_name}-cluster"

  tags = {
    Name = "dit-paas-${var.cluster_name}-cluster"
  }
}

output "ecs_cluster_id" {
  description = "The ID of the ECS cluster."
  value       = aws_ecs_cluster.main.id
}

output "ecs_cluster_name" {
  description = "The name of the ECS cluster."
  value       = aws_ecs_cluster.main.name
}

output "vpc_id" {
  description = "The ID of the VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "The IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "The IDs of the private subnets."
  value       = aws_subnet.private[*].id
}
```

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "AWS region for the VPC and resources."
  default     = "us-east-1"
}

variable "vpc_name" {
  type        = string
  description = "The name of the VPC."
  default     = "benchmark-vpc"
}

variable "cidr_block" {
  type        = string
  description = "The primary IPv4 CIDR block for the VPC."
  default     = "172.16.0.0/16"
}

variable "availability_zones" {
  type        = list(string)
  description = "List of availability zones to deploy subnets in."
  default     = ["us-east-1a", "us-east-1b", "us-east-1c"]
}

# ------------------------------------------------------------------------------
# VPC AND DEFAULT SECURITY GROUP RESTRICTIONS
# ------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block                       = var.cidr_block
  enable_dns_hostnames             = true
  enable_dns_support               = true
  assign_generated_ipv6_cidr_block = false

  tags = {
    Name = var.vpc_name
  }
}

# Secure default security group to deny all incoming and outgoing traffic
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-default-sg"
  }
}

# ------------------------------------------------------------------------------
# INTERNET GATEWAY & SUBNETS
# ------------------------------------------------------------------------------

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count                   = length(var.availability_zones)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.cidr_block, 4, count.index)
  availability_zone       = var.availability_zones[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.vpc_name}-public-${var.availability_zones[count.index]}"
    Type = "public"
  }
}

# Private Subnets
resource "aws_subnet" "private" {
  count             = length(var.availability_zones)
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.cidr_block, 4, count.index + 8)
  availability_zone = var.availability_zones[count.index]

  tags = {
    Name = "${var.vpc_name}-private-${var.availability_zones[count.index]}"
    Type = "private"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.igw]

  tags = {
    Name = "${var.vpc_name}-nat-eip"
  }
}

# NAT Gateway (single NAT for subnets)
resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${var.vpc_name}-nat-gateway"
  }

  depends_on = [aws_internet_gateway.igw]
}

# ------------------------------------------------------------------------------
# ROUTING TABLES
# ------------------------------------------------------------------------------

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${var.vpc_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private Route Table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "${var.vpc_name}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Default Route Table
resource "aws_default_route_table" "default" {
  default_route_table_id = aws_vpc.main.default_route_table_id

  tags = {
    Name = "${var.vpc_name}-default-rt"
  }
}

# ------------------------------------------------------------------------------
# SECURITY GROUP FOR VPC INTERFACE ENDPOINTS
# ------------------------------------------------------------------------------

resource "aws_security_group" "vpc_endpoint_sg" {
  name        = "vpc_endpoint_sg"
  description = "Security group for VPC Interface Endpoints with self-referencing and VPC CIDR ingress on port 443"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "vpc_endpoint_sg"
  }
}

resource "aws_security_group_rule" "endpoint_ingress_self" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.vpc_endpoint_sg.id
  security_group_id        = aws_security_group.vpc_endpoint_sg.id
  description              = "Allow HTTPS from self"
}

resource "aws_security_group_rule" "endpoint_ingress_vpc" {
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [var.cidr_block]
  security_group_id = aws_security_group.vpc_endpoint_sg.id
  description       = "Allow HTTPS from VPC CIDR"
}

resource "aws_security_group_rule" "endpoint_egress_self" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.vpc_endpoint_sg.id
  security_group_id        = aws_security_group.vpc_endpoint_sg.id
  description              = "Allow HTTPS to self"
}

# ------------------------------------------------------------------------------
# GATEWAY VPC ENDPOINT: S3
# ------------------------------------------------------------------------------

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.aws_region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids = [
    aws_route_table.public.id,
    aws_route_table.private.id,
    aws_default_route_table.default.id
  ]

  tags = {
    Name = "${var.vpc_name}-s3-gateway-endpoint"
  }
}

# ------------------------------------------------------------------------------
# INTERFACE VPC ENDPOINTS
# ------------------------------------------------------------------------------

locals {
  interface_endpoints = {
    "ecr_api" = "com.amazonaws.${var.aws_region}.ecr.api"
    "ecr_dkr" = "com.amazonaws.${var.aws_region}.ecr.dkr"
    "logs"    = "com.amazonaws.${var.aws_region}.logs"
    "ssm"     = "com.amazonaws.${var.aws_region}.ssm"
    "kms"     = "com.amazonaws.${var.aws_region}.kms"
  }
}

resource "aws_vpc_endpoint" "interface_endpoints" {
  for_each = local.interface_endpoints

  vpc_id              = aws_vpc.main.id
  service_name        = each.value
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]

  tags = {
    Name = "${var.vpc_name}-${each.key}-endpoint"
  }
}

# ------------------------------------------------------------------------------
# OUTPUTS
# ------------------------------------------------------------------------------

output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "The IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "The IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "endpoint_security_group_id" {
  description = "The ID of the endpoint security group"
  value       = aws_security_group.vpc_endpoint_sg.id
}

output "s3_gateway_endpoint_id" {
  description = "The ID of the S3 Gateway endpoint"
  value       = aws_vpc_endpoint.s3.id
}

output "interface_endpoint_ids" {
  description = "The IDs of the interface endpoints"
  value       = { for k, ep in aws_vpc_endpoint.interface_endpoints : k => ep.id }
}
```

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "The AWS region to deploy the infrastructure."
  default     = "us-east-1"
}

variable "vpc_name" {
  type        = string
  description = "The name of the VPC."
  default     = "benchmark-vpc"
}

variable "cidr_block" {
  type        = string
  description = "The CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "instance_tenancy" {
  type        = string
  description = "Tenancy of instances spin up within VPC."
  default     = "default"
}

variable "enable_dns_hostnames" {
  type        = bool
  description = "Whether to enable DNS hostnames in the VPC."
  default     = true
}

variable "enable_dns_support" {
  type        = bool
  description = "Whether to enable DNS support in the VPC."
  default     = true
}

variable "subnet_cidrs" {
  type        = list(string)
  description = "Subnet CIDR blocks for VPC endpoints."
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "source_security_group_ids" {
  type        = list(string)
  description = "List of security group IDs allowed to access VPC endpoints."
  default     = []
}

variable "gateway_endpoints" {
  type        = set(string)
  description = "Set of Gateway Endpoints to deploy (e.g. s3, dynamodb)."
  default     = ["s3", "dynamodb"]
}

variable "aws_interface_endpoints" {
  type        = set(string)
  description = "Set of standard AWS interface endpoint services (e.g. logs, ssm)."
  default     = ["logs"]
}

variable "custom_interface_endpoints" {
  type = map(object({
    service_name = string
    port         = number
  }))
  description = "Map of custom interface endpoints with key, service_name, and port."
  default     = {}
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES
# ---------------------------------------------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------------------------------------------------
# VPC & BASE NETWORKING
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.cidr_block
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = {
    Name = var.vpc_name
  }
}

# Manage default VPC security group to ensure it is locked down
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-default-sg"
  }
}

# Private Subnets for VPC Endpoints
resource "aws_subnet" "endpoints" {
  count             = length(var.subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index % length(data.aws_availability_zones.available.names)]

  tags = {
    Name = "${var.vpc_name}-endpoint-subnet-${count.index + 1}"
  }
}

# Route Table for Gateway Endpoints
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.endpoints)
  subnet_id      = aws_subnet.endpoints[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------------------------------------------------
# VPC FLOW LOGS & CLOUDWATCH
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name              = "/aws/vpc-flow-logs/${var.vpc_name}"
  retention_in_days = 180

  tags = {
    Name = "/aws/vpc-flow-logs/${var.vpc_name}"
  }
}

resource "aws_iam_role" "vpc_flow_logs" {
  name = "vpc_flow_logs_${var.vpc_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "vpc_flow_logs_${var.vpc_name}"
  }
}

resource "aws_iam_role_policy" "vpc_flow_logs" {
  name = "vpc_flow_logs_${var.vpc_name}_policy"
  role = aws_iam_role.vpc_flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.vpc_flow_logs.arn}:*"
      }
    ]
  })
}

resource "aws_flow_log" "main" {
  iam_role_arn    = aws_iam_role.vpc_flow_logs.arn
  log_destination = aws_cloudwatch_log_group.vpc_flow_logs.arn
  traffic_type    = "ALL"
  vpc_id          = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-flow-log"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# SECURITY GROUPS FOR ENDPOINTS
# ---------------------------------------------------------------------------------------------------------------------

# 1. Security Group for standard AWS VPC Interface Endpoints
resource "aws_security_group" "vpc_endpoints" {
  name        = "vpc-endpoints-${var.vpc_name}"
  description = "Security Group for standard AWS VPC Interface Endpoints"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "vpc-endpoints-${var.vpc_name}"
  }
}

resource "aws_security_group_rule" "vpc_endpoints_ingress_sg" {
  count                    = length(var.source_security_group_ids)
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = var.source_security_group_ids[count.index]
  security_group_id        = aws_security_group.vpc_endpoints.id
}

resource "aws_security_group_rule" "vpc_endpoints_ingress_self" {
  count             = length(var.source_security_group_ids) == 0 ? 1 : 0
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  self              = true
  security_group_id = aws_security_group.vpc_endpoints.id
}

resource "aws_security_group_rule" "vpc_endpoints_egress_sg" {
  count                    = length(var.source_security_group_ids)
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = var.source_security_group_ids[count.index]
  security_group_id        = aws_security_group.vpc_endpoints.id
}

resource "aws_security_group_rule" "vpc_endpoints_egress_self" {
  count             = length(var.source_security_group_ids) == 0 ? 1 : 0
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  self              = true
  security_group_id = aws_security_group.vpc_endpoints.id
}

# 2. Security Group for Custom Endpoint Services
resource "aws_security_group" "custom_endpoints" {
  name        = "custom-endpoints-${var.vpc_name}"
  description = "Security Group for Custom VPC Interface Endpoints"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "custom-endpoints-${var.vpc_name}"
  }
}

locals {
  # Build cartesian product of custom endpoints and source security groups
  custom_rules = flatten([
    for endpoint_key, endpoint_cfg in var.custom_interface_endpoints : [
      for sg_id in var.source_security_group_ids : {
        endpoint_key = endpoint_key
        port         = endpoint_cfg.port
        sg_id        = sg_id
      }
    ]
  ])
}

resource "aws_security_group_rule" "custom_ingress" {
  for_each = {
    for rule in local.custom_rules : "${rule.endpoint_key}-${rule.port}-${rule.sg_id}" => rule
  }

  type                     = "ingress"
  from_port                = each.value.port
  to_port                  = each.value.port
  protocol                 = "tcp"
  source_security_group_id = each.value.sg_id
  security_group_id        = aws_security_group.custom_endpoints.id
}

resource "aws_security_group_rule" "custom_egress" {
  for_each = {
    for rule in local.custom_rules : "${rule.endpoint_key}-${rule.port}-${rule.sg_id}" => rule
  }

  type                     = "egress"
  from_port                = each.value.port
  to_port                  = each.value.port
  protocol                 = "tcp"
  source_security_group_id = each.value.sg_id
  security_group_id        = aws_security_group.custom_endpoints.id
}

# ---------------------------------------------------------------------------------------------------------------------
# VPC ENDPOINTS
# ---------------------------------------------------------------------------------------------------------------------

# Gateway Endpoints (s3, dynamodb)
resource "aws_vpc_endpoint" "gateway" {
  for_each = var.gateway_endpoints

  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.aws_region}.${each.value}"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = {
    Name = "${var.vpc_name}-gateway-${each.value}"
  }
}

# Standard AWS Interface Endpoints (with private DNS enabled)
resource "aws_vpc_endpoint" "aws_interface" {
  for_each = var.aws_interface_endpoints

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${var.aws_region}.${each.value}"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = aws_subnet.endpoints[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]

  tags = {
    Name = "${var.vpc_name}-interface-${each.value}"
  }
}

# Custom Service Interface Endpoints (non-private DNS)
resource "aws_vpc_endpoint" "custom_interface" {
  for_each = var.custom_interface_endpoints

  vpc_id              = aws_vpc.main.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = false
  subnet_ids          = aws_subnet.endpoints[*].id
  security_group_ids  = [aws_security_group.custom_endpoints.id]

  tags = {
    Name = "${var.vpc_name}-custom-${each.key}"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# CONDITIONAL SSM IAM ROLE AND INSTANCE PROFILE
# ---------------------------------------------------------------------------------------------------------------------

locals {
  enable_ssm = contains(var.aws_interface_endpoints, "ssm")
}

resource "aws_iam_role" "ssm" {
  count = local.enable_ssm ? 1 : 0
  name  = "ssm_${var.vpc_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "ssm_${var.vpc_name}"
  }
}

resource "aws_iam_role_policy_attachment" "ssm_core" {
  count      = local.enable_ssm ? 1 : 0
  role       = aws_iam_role.ssm[0].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm" {
  count = local.enable_ssm ? 1 : 0
  name  = "ssm_${var.vpc_name}"
  role  = aws_iam_role.ssm[0].name

  tags = {
    Name = "ssm_${var.vpc_name}"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "vpc_id" {
  description = "The ID of the VPC."
  value       = aws_vpc.main.id
}

output "vpc_flow_log_id" {
  description = "The ID of the VPC Flow Log."
  value       = aws_flow_log.main.id
}

output "cloudwatch_log_group_arn" {
  description = "The ARN of the CloudWatch Log Group for VPC Flow Logs."
  value       = aws_cloudwatch_log_group.vpc_flow_logs.arn
}

output "vpc_endpoints_security_group_id" {
  description = "The ID of the security group for standard VPC interface endpoints."
  value       = aws_security_group.vpc_endpoints.id
}

output "custom_endpoints_security_group_id" {
  description = "The ID of the security group for custom VPC interface endpoints."
  value       = aws_security_group.custom_endpoints.id
}

output "ssm_instance_profile_arn" {
  description = "ARN of the SSM Instance Profile if created."
  value       = try(aws_iam_instance_profile.ssm[0].arn, null)
}
```

```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Project name prefix for KMS aliases and resource naming."
  type        = string
  default     = "secure-baseline"
}

variable "kms_key_rotation_period_in_days" {
  description = "Number of days between automatic KMS key rotations."
  type        = number
  default     = 90
}

variable "external_ebs_kms_key_arn" {
  description = "Optional external KMS key ARN to use as the default EBS encryption key. If empty, the compute KMS key is used."
  type        = string
  default     = ""
}

variable "enable_imds_defaults" {
  description = "Whether to enforce account-level EC2 IMDSv2 defaults."
  type        = bool
  default     = true
}

variable "http_put_response_hop_limit" {
  description = "Hop limit for account-level IMDSv2."
  type        = number
  default     = 1
}

variable "disable_ec2_serial_console" {
  description = "Whether to disable EC2 Serial Console access at the account level."
  type        = bool
  default     = true
}

variable "enable_emr_block_public_access" {
  description = "Whether to enable EMR block public access at the account level."
  type        = bool
  default     = true
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# KMS Key Policies
# -----------------------------------------------------------------------------

# 1. Compute KMS Policy
data "aws_iam_policy_document" "kms_compute_policy" {
  statement {
    sid       = "EnableIAMRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowEC2AndAutoScalingUsage"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    principals {
      type = "Service"
      identifiers = [
        "ec2.amazonaws.com",
        "autoscaling.amazonaws.com"
      ]
    }
  }

  statement {
    sid    = "AllowAutoScalingServiceLinkedRoleGrantCreation"
    effect = "Allow"
    actions = [
      "kms:CreateGrant",
      "kms:ListGrants",
      "kms:RevokeGrant"
    ]
    resources = ["*"]
    principals {
      type = "AWS"
      identifiers = [
        "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling"
      ]
    }
    condition {
      test     = "Bool"
      variable = "kms:GrantIsForAWSResource"
      values   = ["true"]
    }
  }
}

# 2. Observability KMS Policy
data "aws_iam_policy_document" "kms_observability_policy" {
  statement {
    sid       = "EnableIAMRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogs"
    effect = "Allow"
    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*"
    ]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["logs.${var.aws_region}.amazonaws.com"]
    }
    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${data.aws_partition.current.partition}:logs:${var.aws_region}:${data.aws_caller_identity.current.account_id}:log-group:*"]
    }
  }

  statement {
    sid    = "AllowObservabilityServices"
    effect = "Allow"
    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*"
    ]
    resources = ["*"]
    principals {
      type = "Service"
      identifiers = [
        "cloudtrail.amazonaws.com",
        "events.amazonaws.com",
        "sns.amazonaws.com",
        "sqs.amazonaws.com"
      ]
    }
  }

  statement {
    sid    = "AllowCloudWatchAlarmsUsage"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }
  }
}

# 3. Storage KMS Policy
data "aws_iam_policy_document" "kms_storage_policy" {
  statement {
    sid       = "EnableIAMRootPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowS3AndStorageServices"
    effect = "Allow"
    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*"
    ]
    resources = ["*"]
    principals {
      type = "Service"
      identifiers = [
        "s3.amazonaws.com",
        "cloudtrail.amazonaws.com",
        "config.amazonaws.com"
      ]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

# -----------------------------------------------------------------------------
# KMS Keys & Aliases
# -----------------------------------------------------------------------------

# Compute Key
resource "aws_kms_key" "compute" {
  description             = "Compute layer KMS key for ${var.project_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_key_rotation_period_in_days
  policy                  = data.aws_iam_policy_document.kms_compute_policy.json

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name  = "${var.project_name}-compute-kms"
    Layer = "compute"
  }
}

resource "aws_kms_alias" "compute" {
  name          = "alias/${var.project_name}-compute"
  target_key_id = aws_kms_key.compute.key_id
}

# Observability Key
resource "aws_kms_key" "observability" {
  description             = "Observability layer KMS key for ${var.project_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_key_rotation_period_in_days
  policy                  = data.aws_iam_policy_document.kms_observability_policy.json

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name  = "${var.project_name}-observability-kms"
    Layer = "observability"
  }
}

resource "aws_kms_alias" "observability" {
  name          = "alias/${var.project_name}-observability"
  target_key_id = aws_kms_key.observability.key_id
}

# Storage Key
resource "aws_kms_key" "storage" {
  description             = "Storage layer KMS key for ${var.project_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.kms_key_rotation_period_in_days
  policy                  = data.aws_iam_policy_document.kms_storage_policy.json

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name  = "${var.project_name}-storage-kms"
    Layer = "storage"
  }
}

resource "aws_kms_alias" "storage" {
  name          = "alias/${var.project_name}-storage"
  target_key_id = aws_kms_key.storage.key_id
}

# -----------------------------------------------------------------------------
# EBS Default Encryption & Key Configuration
# -----------------------------------------------------------------------------
resource "aws_ebs_encryption_by_default" "ebs_encryption" {
  enabled = true
}

resource "aws_ebs_default_kms_key" "ebs_kms" {
  key_arn = coalesce(var.external_ebs_kms_key_arn, aws_kms_key.compute.arn)

  depends_on = [
    aws_ebs_encryption_by_default.ebs_encryption
  ]
}

# -----------------------------------------------------------------------------
# Account-level Public Access & Hardening Guardrails
# -----------------------------------------------------------------------------

# Block new AMI public sharing
resource "aws_ec2_image_block_public_access" "block_ami_sharing" {
  state = "block-new-sharing"
}

# Block all EBS snapshot public sharing
resource "aws_ebs_snapshot_block_public_access" "block_snapshot_sharing" {
  state = "block-all-sharing"
}

# Account-wide IMDSv2 requirement
resource "aws_ec2_instance_metadata_defaults" "imds_defaults" {
  count                       = var.enable_imds_defaults ? 1 : 0
  http_tokens                 = "required"
  http_put_response_hop_limit = var.http_put_response_hop_limit
}

# Disable EC2 Serial Console access
resource "aws_ec2_serial_console_access" "serial_console" {
  count   = var.disable_ec2_serial_console ? 1 : 0
  enabled = false
}

# Block public access for Amazon EMR clusters
resource "aws_emr_block_public_access_configuration" "emr_block_public_access" {
  count                              = var.enable_emr_block_public_access ? 1 : 0
  block_public_security_group_rules = true
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "compute_kms_key_arn" {
  description = "The ARN of the KMS Key for Compute workloads."
  value       = aws_kms_key.compute.arn
}

output "observability_kms_key_arn" {
  description = "The ARN of the KMS Key for Observability workloads."
  value       = aws_kms_key.observability.arn
}

output "storage_kms_key_arn" {
  description = "The ARN of the KMS Key for Storage workloads."
  value       = aws_kms_key.storage.arn
}

output "ebs_default_kms_key_arn" {
  description = "The ARN of the configured default EBS KMS key."
  value       = aws_ebs_default_kms_key.ebs_kms.key_arn
}
```

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "AWS deployment region"
  default     = "us-east-1"
}

variable "cluster_prefix" {
  type        = string
  description = "Cluster prefix for naming resources (restricted to 5-8 alphanumeric characters)"
  default     = "bench"

  validation {
    condition     = can(regex("^[a-z0-9]{5,8}$", var.cluster_prefix))
    error_message = "The cluster_prefix must be between 5 and 8 lowercase alphanumeric characters."
  }
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "172.16.0.0/16"
}

variable "ssh_key_name" {
  type        = string
  description = "Name for the EC2 deployment key pair"
  default     = "benchmark-keypair"
}

variable "ssh_public_key" {
  type        = string
  description = "Public key material for SSH access"
  default     = "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIClf3c95t2t8rPq8q8o0fN1YFq7lT2Q0X7T0+m9k7xYz benchmark-test-key"
}

variable "public_subnets" {
  type = list(object({
    name = string
    az   = string
    net  = number
  }))
  description = "Public subnets definitions with subnet index offset"
  default = [
    { name = "pub-a", az = "us-east-1a", net = 0 },
    { name = "pub-b", az = "us-east-1b", net = 1 }
  ]
}

variable "private_subnets" {
  type = list(object({
    name = string
    az   = string
    net  = number
  }))
  description = "Private subnets definitions with subnet index offset"
  default = [
    { name = "priv-a", az = "us-east-1a", net = 10 },
    { name = "priv-b", az = "us-east-1b", net = 11 }
  ]
}

variable "ingress_cidr_rules" {
  type = list(object({
    description = string
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  description = "Dynamic ingress CIDR rules for default security group"
  default = [
    {
      description = "Allow SSH from within VPC"
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = ["172.16.0.0/16"]
    }
  ]
}

variable "inventory_nodes" {
  type = list(object({
    node_name              = string
    instance_type          = string
    subnet_type            = string # "public" or "private"
    subnet_index           = number
    assign_eip             = bool
    root_volume_size_gb    = number
    root_volume_type       = string
    secondary_ebs_volumes  = list(object({
      device_name = string
      size_gb     = number
      type        = string
    }))
  }))
  description = "Inventory list defining compute nodes and secondary volume mappings"
  default = [
    {
      node_name           = "test-node-01"
      instance_type       = "t3.medium"
      subnet_type         = "public"
      subnet_index        = 0
      assign_eip          = true
      root_volume_size_gb = 30
      root_volume_type    = "gp3"
      secondary_ebs_volumes = [
        {
          device_name = "/dev/xvdf"
          size_gb     = 20
          type        = "gp3"
        }
      ]
    },
    {
      node_name           = "test-node-02"
      instance_type       = "t3.medium"
      subnet_type         = "private"
      subnet_index        = 0
      assign_eip          = false
      root_volume_size_gb = 30
      root_volume_type    = "gp3"
      secondary_ebs_volumes = []
    }
  ]
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES
# ---------------------------------------------------------------------------------------------------------------------

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# NETWORK RESOURCES (VPC, IGW, SUBNETS)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.cluster_prefix}-vpc"
  }
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.cluster_prefix}-igw"
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count                   = length(var.public_subnets)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, var.public_subnets[count.index].net)
  availability_zone       = var.public_subnets[count.index].az
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.cluster_prefix}-public-${var.public_subnets[count.index].name}"
    Type = "Public"
  }
}

# Private Subnets
resource "aws_subnet" "private" {
  count                   = length(var.private_subnets)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, var.private_subnets[count.index].net)
  availability_zone       = var.private_subnets[count.index].az
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.cluster_prefix}-private-${var.private_subnets[count.index].name}"
    Type = "Private"
  }
}

# Public Routing
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = {
    Name = "${var.cluster_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# NAT Gateways and Private Routing
resource "aws_eip" "nat" {
  count  = length(aws_subnet.public)
  domain = "vpc"

  tags = {
    Name = "${var.cluster_prefix}-nat-eip-${count.index}"
  }

  depends_on = [aws_internet_gateway.gw]
}

resource "aws_nat_gateway" "nat" {
  count         = length(aws_subnet.public)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.cluster_prefix}-nat-gw-${count.index}"
  }

  depends_on = [aws_internet_gateway.gw]
}

resource "aws_route_table" "private" {
  count  = length(aws_subnet.private)
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = length(aws_nat_gateway.nat) > 0 ? aws_nat_gateway.nat[count.index % length(aws_nat_gateway.nat)].id : null
  }

  tags = {
    Name = "${var.cluster_prefix}-private-rt-${count.index}"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------------------------------------------------------------------------------------------------------------
# SECURITY GROUP & KEY PAIR
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_key_pair" "deployer" {
  key_name   = var.ssh_key_name
  public_key = var.ssh_public_key

  tags = {
    Name = "${var.cluster_prefix}-keypair"
  }
}

resource "aws_security_group" "cluster" {
  name        = "${var.cluster_prefix}-sg"
  description = "Default cluster security group"
  vpc_id      = aws_vpc.main.id

  # Self-referencing intra-group ingress
  ingress {
    description = "Self-referencing intra-group ingress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  # Dynamic ingress rules
  dynamic "ingress" {
    for_each = var.ingress_cidr_rules
    content {
      description = ingress.value.description
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  # Outbound traffic restricted to VPC CIDR
  egress {
    description = "Outbound traffic restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.cluster_prefix}-sg"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# COMPUTE NODES & EBS VOLUMES
# ---------------------------------------------------------------------------------------------------------------------

locals {
  # Helper to resolve target subnet ID based on type and index
  node_subnets = [
    for node in var.inventory_nodes :
    node.subnet_type == "public" ?
    aws_subnet.public[node.subnet_index].id :
    aws_subnet.private[node.subnet_index].id
  ]

  # Flattened secondary volumes mapping for iteration
  secondary_volumes = flatten([
    for node_idx, node in var.inventory_nodes : [
      for vol_idx, vol in node.secondary_ebs_volumes : {
        key          = "${node.node_name}-${vol.device_name}"
        instance_idx = node_idx
        device_name  = vol.device_name
        size_gb      = vol.size_gb
        type         = vol.type
      }
    ]
  ])
}

resource "aws_instance" "nodes" {
  count                  = length(var.inventory_nodes)
  ami                    = data.aws_ami.amazon_linux_2023.id
  instance_type          = var.inventory_nodes[count.index].instance_type
  key_name               = aws_key_pair.deployer.key_name
  subnet_id              = local.node_subnets[count.index]
  vpc_security_group_ids = [aws_security_group.cluster.id]
  ebs_optimized          = true

  root_block_device {
    volume_size           = var.inventory_nodes[count.index].root_volume_size_gb
    volume_type           = var.inventory_nodes[count.index].root_volume_type
    delete_on_termination = true
    encrypted             = true
  }

  tags = {
    Name = "${var.cluster_prefix}-${var.inventory_nodes[count.index].node_name}"
  }
}

# Optional Elastic IPs for specific inventory nodes
resource "aws_eip" "node_eip" {
  count    = length(var.inventory_nodes)
  domain   = "vpc"
  instance = var.inventory_nodes[count.index].assign_eip ? aws_instance.nodes[count.index].id : null

  tags = {
    Name = "${var.cluster_prefix}-${var.inventory_nodes[count.index].node_name}-eip"
  }
}

# Secondary EBS Volumes
resource "aws_ebs_volume" "secondary" {
  for_each = { for vol in local.secondary_volumes : vol.key => vol }

  availability_zone = aws_instance.nodes[each.value.instance_idx].availability_zone
  size              = each.value.size_gb
  type              = each.value.type
  encrypted         = true

  tags = {
    Name = "${var.cluster_prefix}-${each.value.key}"
  }
}

resource "aws_volume_attachment" "secondary_attach" {
  for_each = { for vol in local.secondary_volumes : vol.key => vol }

  device_name = each.value.device_name
  volume_id   = aws_ebs_volume.secondary[each.key].id
  instance_id = aws_instance.nodes[each.value.instance_idx].id
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "List of public subnet IDs"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "List of private subnet IDs"
  value       = aws_subnet.private[*].id
}

output "security_group_id" {
  description = "Cluster Security Group ID"
  value       = aws_security_group.cluster.id
}

output "instance_ids" {
  description = "Map of node names to EC2 Instance IDs"
  value = {
    for idx, node in var.inventory_nodes :
    node.node_name => aws_instance.nodes[idx].id
  }
}

output "instance_private_ips" {
  description = "Map of node names to private IP addresses"
  value = {
    for idx, node in var.inventory_nodes :
    node.node_name => aws_instance.nodes[idx].private_ip
  }
}

output "instance_public_eips" {
  description = "Map of node names to allocated Elastic IPs (if requested)"
  value = {
    for idx, node in var.inventory_nodes :
    node.node_name => var.inventory_nodes[idx].assign_eip ? aws_eip.node_eip[idx].public_ip : null
  }
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region for deployment"
  default     = "us-east-1"
}

variable "vpc_name" {
  type        = string
  description = "VPC resource name"
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  type        = string
  description = "VPC CIDR block"
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  type        = list(string)
  description = "Ordered list of 4 subnet CIDRs to allocate"
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24", "10.0.4.0/24"]
}

variable "enable_private_subnets" {
  type        = bool
  description = "Toggle layout: true for 2 public + 2 private in 2 AZs; false for 4 public in 4 AZs"
  default     = true
}

variable "enable_nat_gateways" {
  type        = bool
  description = "Deploy redundant AWS NAT Gateways for private subnet egress"
  default     = true
}

variable "enable_nat_instances" {
  type        = bool
  description = "Deploy redundant NAT EC2 instances for private subnet egress"
  default     = false
}

variable "enable_egress_only_igw" {
  type        = bool
  description = "Deploy an Egress-Only Internet Gateway for IPv6 private egress"
  default     = false
}

variable "nat_instance_type" {
  type        = string
  description = "Instance type for NAT EC2 instances"
  default     = "m1.small"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# Amazon Linux NAT AMI lookup for NAT instance option
data "aws_ami" "nat_ami" {
  count       = var.enable_nat_instances ? 1 : 0
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn-ami-vpc-nat-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# -----------------------------------------------------------------------------
# VPC and Base Gateways
# -----------------------------------------------------------------------------
resource "aws_vpc" "benchmark" {
  cidr_block                       = var.vpc_cidr
  enable_dns_hostnames             = true
  enable_dns_support               = true
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.benchmark.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

# -----------------------------------------------------------------------------
# Security Groups
# -----------------------------------------------------------------------------
# Default security group: allow only self-referencing ingress and egress
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.benchmark.id

  ingress {
    protocol  = "-1"
    self      = true
    from_port = 0
    to_port   = 0
  }

  egress {
    protocol  = "-1"
    self      = true
    from_port = 0
    to_port   = 0
  }

  tags = {
    Name = "${var.vpc_name}-default-sg"
  }
}

# Additional security group allowing inbound TLS on port 443
resource "aws_security_group" "tls" {
  name        = "${var.vpc_name}-tls-sg"
  description = "Allow inbound TLS traffic on port 443"
  vpc_id      = aws_vpc.benchmark.id

  ingress {
    description      = "TLS from anywhere"
    from_port        = 443
    to_port          = 443
    protocol         = "tcp"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = ["::/0"]
  }

  egress {
    description      = "Allow all outbound traffic"
    from_port        = 0
    to_port          = 0
    protocol         = "-1"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = ["::/0"]
  }

  tags = {
    Name = "${var.vpc_name}-tls-sg"
  }
}

# Security group for NAT instances (when enabled)
resource "aws_security_group" "nat_instance" {
  count       = var.enable_nat_instances ? 1 : 0
  name        = "${var.vpc_name}-nat-instance-sg"
  description = "Security group for NAT instances forwarding VPC traffic"
  vpc_id      = aws_vpc.benchmark.id

  ingress {
    description = "Traffic from VPC subnets"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description      = "Outbound to internet"
    from_port        = 0
    to_port          = 0
    protocol         = "-1"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = ["::/0"]
  }

  tags = {
    Name = "${var.vpc_name}-nat-instance-sg"
  }
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------
# Public Subnets:
# - If enable_private_subnets is true: 2 public subnets in AZs 0 and 1 using cidr index 0, 1
# - If enable_private_subnets is false: 4 public subnets in AZs 0, 1, 2, 3 using cidr index 0, 1, 2, 3
resource "aws_subnet" "public" {
  count                   = var.enable_private_subnets ? 2 : 4
  vpc_id                  = aws_vpc.benchmark.id
  cidr_block              = var.subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.vpc_name}-public-subnet-${count.index + 1}"
    Tier = "Public"
  }
}

# Private Subnets:
# - If enable_private_subnets is true: 2 private subnets in AZs 0 and 1 using cidr index 2, 3
resource "aws_subnet" "private" {
  count                   = var.enable_private_subnets ? 2 : 0
  vpc_id                  = aws_vpc.benchmark.id
  cidr_block              = var.subnet_cidrs[count.index + 2]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.vpc_name}-private-subnet-${count.index + 1}"
    Tier = "Private"
  }
}

# -----------------------------------------------------------------------------
# Public Routing
# -----------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.benchmark.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  tags = {
    Name = "${var.vpc_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Egress Option 1: Redundant AWS NAT Gateways
# -----------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count  = (var.enable_private_subnets && var.enable_nat_gateways) ? 2 : 0
  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-eip-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.gw]
}

resource "aws_nat_gateway" "nat" {
  count         = (var.enable_private_subnets && var.enable_nat_gateways) ? 2 : 0
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.vpc_name}-nat-gw-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.gw]
}

resource "aws_route_table" "private_nat_gw" {
  count  = (var.enable_private_subnets && var.enable_nat_gateways) ? 2 : 0
  vpc_id = aws_vpc.benchmark.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = {
    Name = "${var.vpc_name}-private-rt-nat-gw-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private_nat_gw" {
  count          = (var.enable_private_subnets && var.enable_nat_gateways) ? 2 : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_nat_gw[count.index].id
}

# -----------------------------------------------------------------------------
# Egress Option 2: Redundant NAT EC2 Instances
# -----------------------------------------------------------------------------
resource "aws_instance" "nat" {
  count                  = (var.enable_private_subnets && var.enable_nat_instances) ? 2 : 0
  ami                    = data.aws_ami.nat_ami[0].id
  instance_type          = var.nat_instance_type
  subnet_id              = aws_subnet.public[count.index].id
  vpc_security_group_ids = [aws_security_group.nat_instance[0].id]
  source_dest_check      = false

  tags = {
    Name = "${var.vpc_name}-nat-instance-${count.index + 1}"
  }
}

resource "aws_route_table" "private_nat_instance" {
  count  = (var.enable_private_subnets && var.enable_nat_instances) ? 2 : 0
  vpc_id = aws_vpc.benchmark.id

  route {
    cidr_block           = "0.0.0.0/0"
    network_interface_id = aws_instance.nat[count.index].primary_network_interface_id
  }

  tags = {
    Name = "${var.vpc_name}-private-rt-nat-instance-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private_nat_instance" {
  count          = (var.enable_private_subnets && var.enable_nat_instances) ? 2 : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_nat_instance[count.index].id
}

# -----------------------------------------------------------------------------
# Egress Option 3: Egress-Only Internet Gateway (IPv6)
# -----------------------------------------------------------------------------
resource "aws_egress_only_internet_gateway" "eigw" {
  count  = (var.enable_private_subnets && var.enable_egress_only_igw) ? 1 : 0
  vpc_id = aws_vpc.benchmark.id

  tags = {
    Name = "${var.vpc_name}-eigw"
  }
}

resource "aws_route_table" "private_eigw" {
  count  = (var.enable_private_subnets && var.enable_egress_only_igw && !var.enable_nat_gateways && !var.enable_nat_instances) ? 1 : 0
  vpc_id = aws_vpc.benchmark.id

  route {
    ipv6_cidr_block        = "::/0"
    egress_only_gateway_id = aws_egress_only_internet_gateway.eigw[0].id
  }

  tags = {
    Name = "${var.vpc_name}-private-rt-eigw"
  }
}

resource "aws_route_table_association" "private_eigw" {
  count          = (var.enable_private_subnets && var.enable_egress_only_igw && !var.enable_nat_gateways && !var.enable_nat_instances) ? 2 : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_eigw[0].id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.benchmark.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets (if enabled)"
  value       = aws_subnet.private[*].id
}

output "default_security_group_id" {
  description = "ID of the default security group"
  value       = aws_default_security_group.default.id
}

output "tls_security_group_id" {
  description = "ID of the TLS security group"
  value       = aws_security_group.tls.id
}

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "primary_region" {
  description = "The primary AWS region for Terraform state and logs"
  type        = string
  default     = "us-east-1"
}

variable "replica_region" {
  description = "The secondary AWS region for cross-region replication"
  type        = string
  default     = "us-west-2"
}

variable "environment" {
  description = "Environment name used for tagging and resource naming"
  type        = string
  default     = "benchmark"
}

variable "log_glacier_transition_days" {
  description = "Number of days before transitioning log objects to Glacier"
  type        = number
  default     = 7
}

variable "log_expiration_days" {
  description = "Number of days before expiring log objects"
  type        = number
  default     = 30
}

provider "aws" {
  alias  = "primary"
  region = var.primary_region
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

data "aws_caller_identity" "current" {}

resource "random_id" "suffix" {
  byte_length = 4
}

# -----------------------------------------------------------------------------
# KMS Keys for Server-Side Encryption
# -----------------------------------------------------------------------------

# Primary KMS Key for State Bucket
resource "aws_kms_key" "primary_state_key" {
  provider                = aws.primary
  description             = "KMS key for primary Terraform state bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Environment = var.environment
    Name        = "${var.environment}-primary-state-kms-key"
  }
}

resource "aws_kms_alias" "primary_state_key_alias" {
  provider      = aws.primary
  name          = "alias/${var.environment}-state-key-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.primary_state_key.key_id
}

# Secondary/Replica KMS Key for State Replica Bucket
resource "aws_kms_key" "replica_state_key" {
  provider                = aws.replica
  description             = "KMS key for replica Terraform state bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Environment = var.environment
    Name        = "${var.environment}-replica-state-kms-key"
  }
}

resource "aws_kms_alias" "replica_state_key_alias" {
  provider      = aws.replica
  name          = "alias/${var.environment}-state-replica-key-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.replica_state_key.key_id
}

# -----------------------------------------------------------------------------
# S3 Buckets - Logs Buckets
# -----------------------------------------------------------------------------

# Replica Access Logs Bucket (Secondary Region)
resource "aws_s3_bucket" "replica_logs" {
  provider      = aws.replica
  bucket        = "${var.environment}-replica-tfstate-logs-${random_id.suffix.hex}"
  force_destroy = true

  tags = {
    Environment = var.environment
    Name        = "${var.environment}-replica-tfstate-logs"
  }
}

resource "aws_s3_bucket_versioning" "replica_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "replica_logs" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_logs.id

  rule {
    id     = "glacier-transition-and-expiration"
    status = "Enabled"

    filter {}

    transition {
      days          = var.log_glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.log_expiration_days
    }
  }
}

# Primary Access Logs Bucket (Primary Region)
resource "aws_s3_bucket" "primary_logs" {
  provider      = aws.primary
  bucket        = "${var.environment}-primary-tfstate-logs-${random_id.suffix.hex}"
  force_destroy = true

  tags = {
    Environment = var.environment
    Name        = "${var.environment}-primary-tfstate-logs"
  }
}

resource "aws_s3_bucket_ownership_controls" "primary_logs" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary_logs.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "primary_logs" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_acl" "primary_logs" {
  provider   = aws.primary
  bucket     = aws_s3_bucket.primary_logs.id
  acl        = "log-delivery-write"
  depends_on = [aws_s3_bucket_ownership_controls.primary_logs]
}

resource "aws_s3_bucket_versioning" "primary_logs" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "primary_logs" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary_logs.id

  rule {
    id     = "glacier-transition-and-expiration"
    status = "Enabled"

    filter {}

    transition {
      days          = var.log_glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.log_expiration_days
    }
  }
}

# -----------------------------------------------------------------------------
# S3 Buckets - State Buckets
# -----------------------------------------------------------------------------

# Replica State Bucket (Secondary Region)
resource "aws_s3_bucket" "replica_state" {
  provider      = aws.replica
  bucket        = "${var.environment}-replica-tfstate-${random_id.suffix.hex}"
  force_destroy = true

  tags = {
    Environment = var.environment
    Name        = "${var.environment}-replica-tfstate"
  }
}

resource "aws_s3_bucket_versioning" "replica_state" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica_state" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica_state_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica_state" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Primary State Bucket (Primary Region)
resource "aws_s3_bucket" "primary_state" {
  provider      = aws.primary
  bucket        = "${var.environment}-primary-tfstate-${random_id.suffix.hex}"
  force_destroy = true

  tags = {
    Environment = var.environment
    Name        = "${var.environment}-primary-tfstate"
  }
}

resource "aws_s3_bucket_versioning" "primary_state" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary_state" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary_state_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_logging" "primary_state" {
  provider      = aws.primary
  bucket        = aws_s3_bucket.primary_state.id
  target_bucket = aws_s3_bucket.primary_logs.id
  target_prefix = "state-logs/"
}

resource "aws_s3_bucket_public_access_block" "primary_state" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# Bucket Policies for State Buckets
# -----------------------------------------------------------------------------

# Primary State Bucket Policy
resource "aws_s3_bucket_policy" "primary_state_policy" {
  provider   = aws.primary
  bucket     = aws_s3_bucket.primary_state.id
  depends_on = [aws_s3_bucket_public_access_block.primary_state]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyExternalAccountAccess"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.primary_state.arn,
          "${aws_s3_bucket.primary_state.arn}/*"
        ]
        Condition = {
          StringNotEquals = {
            "aws:PrincipalAccount" = data.aws_caller_identity.current.account_id
          }
        }
      },
      {
        Sid       = "EnforceBucketOwnerFullControl"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.primary_state.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

# Replica State Bucket Policy
resource "aws_s3_bucket_policy" "replica_state_policy" {
  provider   = aws.replica
  bucket     = aws_s3_bucket.replica_state.id
  depends_on = [aws_s3_bucket_public_access_block.replica_state]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyExternalAccountAccess"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.replica_state.arn,
          "${aws_s3_bucket.replica_state.arn}/*"
        ]
        Condition = {
          StringNotEquals = {
            "aws:PrincipalAccount" = data.aws_caller_identity.current.account_id
          }
        }
      },
      {
        Sid       = "EnforceBucketOwnerFullControl"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.replica_state.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Replication IAM Roles and Policies
# -----------------------------------------------------------------------------

# IAM Role for State Replication
resource "aws_iam_role" "state_replication" {
  name = "${var.environment}-state-s3-replication-role-${random_id.suffix.hex}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Environment = var.environment
  }
}

resource "aws_iam_policy" "state_replication" {
  name = "${var.environment}-state-s3-replication-policy-${random_id.suffix.hex}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [aws_s3_bucket.primary_state.arn]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = ["${aws_s3_bucket.primary_state.arn}/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetObjectVersion",
          "s3:ObjectOwnerOverrideToBucketOwner"
        ]
        Resource = ["${aws_s3_bucket.replica_state.arn}/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = [aws_kms_key.primary_state_key.arn]
        Condition = {
          StringLike = {
            "kms:ViaService" = "s3.${var.primary_region}.amazonaws.com"
          }
        }
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt"
        ]
        Resource = [aws_kms_key.replica_state_key.arn]
        Condition = {
          StringLike = {
            "kms:ViaService" = "s3.${var.replica_region}.amazonaws.com"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "state_replication" {
  role       = aws_iam_role.state_replication.name
  policy_arn = aws_iam_policy.state_replication.arn
}

# IAM Role for Logs Replication
resource "aws_iam_role" "logs_replication" {
  name = "${var.environment}-logs-s3-replication-role-${random_id.suffix.hex}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Environment = var.environment
  }
}

resource "aws_iam_policy" "logs_replication" {
  name = "${var.environment}-logs-s3-replication-policy-${random_id.suffix.hex}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [aws_s3_bucket.primary_logs.arn]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = ["${aws_s3_bucket.primary_logs.arn}/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetObjectVersion",
          "s3:ObjectOwnerOverrideToBucketOwner"
        ]
        Resource = ["${aws_s3_bucket.replica_logs.arn}/*"]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "logs_replication" {
  role       = aws_iam_role.logs_replication.name
  policy_arn = aws_iam_policy.logs_replication.arn
}

# -----------------------------------------------------------------------------
# Replication Configurations
# -----------------------------------------------------------------------------

# Primary State Bucket Replication Configuration
resource "aws_s3_bucket_replication_configuration" "state_replication" {
  provider   = aws.primary
  role       = aws_iam_role.state_replication.arn
  bucket     = aws_s3_bucket.primary_state.id
  depends_on = [aws_s3_bucket_versioning.primary_state]

  rule {
    id     = "state-cross-region-replication"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica_state.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica_state_key.arn
      }

      access_control_translation {
        owner = "Destination"
      }

      account = data.aws_caller_identity.current.account_id
    }
  }
}

# Primary Logs Bucket Replication Configuration
resource "aws_s3_bucket_replication_configuration" "logs_replication" {
  provider   = aws.primary
  role       = aws_iam_role.logs_replication.arn
  bucket     = aws_s3_bucket.primary_logs.id
  depends_on = [aws_s3_bucket_versioning.primary_logs]

  rule {
    id     = "logs-cross-region-replication"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.replica_logs.arn
      storage_class = "STANDARD"

      access_control_translation {
        owner = "Destination"
      }

      account = data.aws_caller_identity.current.account_id
    }
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "primary_state_bucket_id" {
  description = "The ID of the primary state S3 bucket"
  value       = aws_s3_bucket.primary_state.id
}

output "primary_state_bucket_arn" {
  description = "The ARN of the primary state S3 bucket"
  value       = aws_s3_bucket.primary_state.arn
}

output "replica_state_bucket_id" {
  description = "The ID of the replica state S3 bucket"
  value       = aws_s3_bucket.replica_state.id
}

output "primary_logs_bucket_id" {
  description = "The ID of the primary logs S3 bucket"
  value       = aws_s3_bucket.primary_logs.id
}

output "replica_logs_bucket_id" {
  description = "The ID of the replica logs S3 bucket"
  value       = aws_s3_bucket.replica_logs.id
}

output "primary_kms_key_arn" {
  description = "The ARN of the primary KMS key"
  value       = aws_kms_key.primary_state_key.arn
}

output "replica_kms_key_arn" {
  description = "The ARN of the replica KMS key"
  value       = aws_kms_key.replica_state_key.arn
}
```

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# --------------------------------------------------------------------------------------------------
# Input Variables
# --------------------------------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region for provisioning resources."
  default     = "us-east-1"
}

variable "name" {
  type        = string
  description = "Base name used to identify resources."
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  type        = string
  description = "The primary CIDR block for the new VPC."
  default     = "10.0.0.0/16"
}

variable "existing_vpc_id" {
  type        = string
  description = "ID of an existing VPC. If set, creating a new VPC is skipped."
  default     = null
}

variable "availability_zones" {
  type        = list(string)
  description = "Availability zones used for subnet distribution."
  default     = ["us-east-1a", "us-east-1b"]
}

variable "public_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for public subnets."
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for private subnets."
  default     = ["10.0.11.0/24", "10.0.12.0/24"]
}

variable "database_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for database subnets."
  default     = ["10.0.21.0/24", "10.0.22.0/24"]
}

variable "existing_public_subnet_ids" {
  type        = list(string)
  description = "Pre-existing public subnet IDs to skip subnet creation."
  default     = []
}

variable "existing_private_subnet_ids" {
  type        = list(string)
  description = "Pre-existing private subnet IDs to skip subnet creation."
  default     = []
}

variable "existing_database_subnet_ids" {
  type        = list(string)
  description = "Pre-existing database subnet IDs to skip subnet creation."
  default     = []
}

variable "existing_nat_id" {
  type        = string
  description = "Existing NAT Gateway ID to bypass creating a new NAT Gateway."
  default     = null
}

variable "existing_security_group_id" {
  type        = string
  description = "Existing security group ID for interface endpoints."
  default     = null
}

variable "interface_endpoint_services" {
  type        = list(string)
  description = "List of AWS interface endpoints to create."
  default = [
    "ec2",
    "ecr.api",
    "ecr.dkr",
    "s3",
    "logs",
    "sts",
    "elasticloadbalancing",
    "autoscaling"
  ]
}

variable "tags" {
  type        = map(string)
  description = "Common tags applied to resources."
  default     = {}
}

# --------------------------------------------------------------------------------------------------
# Data Sources
# --------------------------------------------------------------------------------------------------
data "aws_vpc" "existing" {
  count = var.existing_vpc_id != null ? 1 : 0
  id    = var.existing_vpc_id
}

# --------------------------------------------------------------------------------------------------
# VPC Resource
# --------------------------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  count                = var.existing_vpc_id == null ? 1 : 0
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    var.tags,
    {
      Name = var.name
    }
  )
}

locals {
  vpc_id   = var.existing_vpc_id != null ? var.existing_vpc_id : aws_vpc.main[0].id
  vpc_cidr = var.existing_vpc_id != null ? data.aws_vpc.existing[0].cidr_block : aws_vpc.main[0].cidr_block
}

# --------------------------------------------------------------------------------------------------
# Subnets
# --------------------------------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count                   = length(var.existing_public_subnet_ids) == 0 ? length(var.public_subnet_cidrs) : 0
  vpc_id                  = local.vpc_id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = var.availability_zones[count.index % length(var.availability_zones)]
  map_public_ip_on_launch = false

  tags = merge(
    var.tags,
    {
      Name = "${var.name}-public-${count.index + 1}"
      Type = "Public"
    }
  )
}

resource "aws_subnet" "private" {
  count             = length(var.existing_private_subnet_ids) == 0 ? length(var.private_subnet_cidrs) : 0
  vpc_id            = local.vpc_id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = var.availability_zones[count.index % length(var.availability_zones)]

  tags = merge(
    var.tags,
    {
      Name = "${var.name}-private-${count.index + 1}"
      Type = "Private"
    }
  )
}

resource "aws_subnet" "database" {
  count             = length(var.existing_database_subnet_ids) == 0 ? length(var.database_subnet_cidrs) : 0
  vpc_id            = local.vpc_id
  cidr_block        = var.database_subnet_cidrs[count.index]
  availability_zone = var.availability_zones[count.index % length(var.availability_zones)]

  tags = merge(
    var.tags,
    {
      Name = "${var.name}-database-${count.index + 1}"
      Type = "Database"
    }
  )
}

locals {
  public_subnet_ids   = length(var.existing_public_subnet_ids) > 0 ? var.existing_public_subnet_ids : aws_subnet.public[*].id
  private_subnet_ids  = length(var.existing_private_subnet_ids) > 0 ? var.existing_private_subnet_ids : aws_subnet.private[*].id
  database_subnet_ids = length(var.existing_database_subnet_ids) > 0 ? var.existing_database_subnet_ids : aws_subnet.database[*].id
}

# --------------------------------------------------------------------------------------------------
# RDS Subnet Group
# --------------------------------------------------------------------------------------------------
resource "aws_db_subnet_group" "default" {
  name       = lower(var.name)
  subnet_ids = local.database_subnet_ids

  tags = merge(
    var.tags,
    {
      Name = lower(var.name)
    }
  )
}

# --------------------------------------------------------------------------------------------------
# Internet Gateway and Public Route Table
# --------------------------------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  count  = var.existing_vpc_id == null ? 1 : 0
  vpc_id = local.vpc_id

  tags = merge(
    var.tags,
    {
      Name = "${var.name}-igw"
    }
  )
}

resource "aws_route_table" "public" {
  count  = length(var.existing_public_subnet_ids) == 0 ? 1 : 0
  vpc_id = local.vpc_id

  tags = merge(
    var.tags,
    {
      Name = "${var.name}-public-rt"
    }
  )
}

resource "aws_route" "public_internet" {
  count                  = length(var.existing_public_subnet_ids) == 0 && var.existing_vpc_id == null ? 1 : 0
  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

resource "aws_route_table_association" "public" {
  count          = length(var.existing_public_subnet_ids) == 0 ? length(aws_subnet.public) : 0
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# --------------------------------------------------------------------------------------------------
# NAT Gateway and Private Route Table
# --------------------------------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count  = var.existing_nat_id == null && length(local.public_subnet_ids) > 0 ? 1 : 0
  domain = "vpc"

  tags = merge(
    var.tags,
    {
      Name = "${var.name}-nat-eip"
    }
  )
}

resource "aws_nat_gateway" "main" {
  count         = var.existing_nat_id == null && length(local.public_subnet_ids) > 0 ? 1 : 0
  allocation_id = aws_eip.nat[0].id
  subnet_id     = local.public_subnet_ids[0]

  tags = merge(
    var.tags,
    {
      Name = "${var.name}-nat-gw"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

locals {
  nat_gateway_id = var.existing_nat_id != null ? var.existing_nat_id : (length(aws_nat_gateway.main) > 0 ? aws_nat_gateway.main[0].id : null)
}

resource "aws_route_table" "private" {
  count  = length(var.existing_private_subnet_ids) == 0 ? 1 : 0
  vpc_id = local.vpc_id

  tags = merge(
    var.tags,
    {
      Name = "${var.name}-private-rt"
    }
  )
}

resource "aws_route" "private_nat" {
  count                  = length(var.existing_private_subnet_ids) == 0 && local.nat_gateway_id != null ? 1 : 0
  route_table_id         = aws_route_table.private[0].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = local.nat_gateway_id
}

resource "aws_route_table_association" "private" {
  count          = length(var.existing_private_subnet_ids) == 0 ? length(aws_subnet.private) : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# --------------------------------------------------------------------------------------------------
# Endpoints Security Group
# --------------------------------------------------------------------------------------------------
resource "aws_security_group" "endpoints" {
  count       = var.existing_security_group_id == null ? 1 : 0
  name        = "${var.name}-vpc-endpoints"
  description = "Security group for VPC Interface Endpoints"
  vpc_id      = local.vpc_id

  ingress {
    description = "Allow HTTPS from within the VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Allow outbound traffic only within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(
    var.tags,
    {
      Name = "${var.name}-vpc-endpoints"
    }
  )
}

locals {
  endpoint_security_group_ids = [
    var.existing_security_group_id != null ? var.existing_security_group_id : aws_security_group.endpoints[0].id
  ]
}

# --------------------------------------------------------------------------------------------------
# VPC Interface Endpoints
# --------------------------------------------------------------------------------------------------
resource "aws_vpc_endpoint" "interfaces" {
  for_each            = toset(var.interface_endpoint_services)
  vpc_id              = local.vpc_id
  service_name        = "com.amazonaws.${var.aws_region}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.private_subnet_ids
  security_group_ids  = local.endpoint_security_group_ids
  private_dns_enabled = true

  tags = merge(
    var.tags,
    {
      Name = "${var.name}-endpoint-${replace(each.value, ".", "-")}"
    }
  )
}

# --------------------------------------------------------------------------------------------------
# Outputs
# --------------------------------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the VPC."
  value       = local.vpc_id
}

output "vpc_cidr" {
  description = "The CIDR block of the VPC."
  value       = local.vpc_cidr
}

output "public_subnet_ids" {
  description = "List of public subnet IDs."
  value       = local.public_subnet_ids
}

output "private_subnet_ids" {
  description = "List of private subnet IDs."
  value       = local.private_subnet_ids
}

output "database_subnet_ids" {
  description = "List of database subnet IDs."
  value       = local.database_subnet_ids
}

output "db_subnet_group_name" {
  description = "The name of the database subnet group."
  value       = aws_db_subnet_group.default.name
}

output "endpoint_security_group_id" {
  description = "Security group ID attached to interface endpoints."
  value       = local.endpoint_security_group_ids[0]
}

output "vpc_endpoints" {
  description = "Map of created VPC interface endpoints."
  value       = { for k, v in aws_vpc_endpoint.interfaces : k => v.id }
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region to deploy the infrastructure."
  default     = "us-east-1"
}

variable "app_shortcode" {
  type        = string
  description = "Application shortcode prefix for IAM and resource naming."
  default     = "bmk"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the isolated VPC."
  default     = "10.8.0.0/16"
}

variable "subnet_cidr" {
  type        = string
  description = "CIDR block for the private subnet."
  default     = "10.8.1.0/24"
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

# -----------------------------------------------------------------------------
# VPC and Subnet
# -----------------------------------------------------------------------------
resource "aws_vpc" "isolated" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.app_shortcode}-isolated-vpc"
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.isolated.id
  cidr_block              = var.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.app_shortcode}-private-subnet"
  }
}

# -----------------------------------------------------------------------------
# Security Groups
# -----------------------------------------------------------------------------
resource "aws_security_group" "endpoints" {
  name        = "${var.app_shortcode}-vpce-sg"
  description = "Security group for interface VPC endpoints allowing inbound HTTPS from VPC"
  vpc_id      = aws_vpc.isolated.id

  ingress {
    description = "Allow inbound HTTPS from VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  # No egress rules required
  egress = []

  tags = {
    Name = "${var.app_shortcode}-vpce-sg"
  }
}

resource "aws_security_group" "instance" {
  name        = "${var.app_shortcode}-instance-sg"
  description = "Security group for isolated test EC2 instance"
  vpc_id      = aws_vpc.isolated.id

  # No ingress rules required
  ingress = []

  egress {
    description = "Allow outbound HTTPS to VPC CIDR (endpoints)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${var.app_shortcode}-instance-sg"
  }
}

# -----------------------------------------------------------------------------
# VPC Interface Endpoints
# -----------------------------------------------------------------------------
locals {
  services = [
    "ssm",
    "ec2messages",
    "ssmmessages",
    "logs"
  ]
}

resource "aws_vpc_endpoint" "interfaces" {
  for_each = toset(locals.services)

  vpc_id              = aws_vpc.isolated.id
  service_name        = "com.amazonaws.${var.aws_region}.${each.value}"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  auto_accept         = true

  subnet_ids         = [aws_subnet.private.id]
  security_group_ids = [aws_security_group.endpoints.id]

  tags = {
    Name = "${var.app_shortcode}-vpce-${each.value}"
  }
}

# -----------------------------------------------------------------------------
# IAM Role and Instance Profile
# -----------------------------------------------------------------------------
resource "aws_iam_role" "ssm_role" {
  name_prefix = "${var.app_shortcode}-role-"
  description = "IAM role for EC2 SSM Session Manager testing in isolated VPC"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "${var.app_shortcode}-ssm-role"
  }
}

resource "aws_iam_policy" "ssm_permissions" {
  name_prefix = "${var.app_shortcode}-policy-"
  description = "IAM policy granting SSM, Logs, KMS, and S3 permissions for session management"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SSMAndMessagesPermissions"
        Effect = "Allow"
        Action = [
          "ssm:DescribeAssociation",
          "ssm:GetDeployablePatchSnapshotForInstance",
          "ssm:GetDocument",
          "ssm:DescribeDocument",
          "ssm:GetManifest",
          "ssm:GetParameter",
          "ssm:GetParameters",
          "ssm:ListAssociations",
          "ssm:ListInstanceAssociations",
          "ssm:PutInventory",
          "ssm:PutComplianceItems",
          "ssm:PutConfigurePackageResult",
          "ssm:UpdateAssociationStatus",
          "ssm:UpdateInstanceAssociationStatus",
          "ssm:UpdateInstanceInformation",
          "ssmmessages:CreateControlChannel",
          "ssmmessages:CreateDataChannel",
          "ssmmessages:OpenControlChannel",
          "ssmmessages:OpenDataChannel",
          "ec2messages:AcknowledgeMessage",
          "ec2messages:DeleteMessage",
          "ec2messages:FailMessage",
          "ec2messages:GetEndpoint",
          "ec2messages:GetMessages",
          "ec2messages:SendReply"
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudWatchLogsPermissions"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      },
      {
        Sid    = "KMSPermissions"
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "S3Permissions"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:PutObjectAcl",
          "s3:GetEncryptionConfiguration"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ssm_attach" {
  role       = aws_iam_role.ssm_role.name
  policy_arn = aws_iam_policy.ssm_permissions.arn
}

resource "aws_iam_instance_profile" "instance_profile" {
  name_prefix = "${var.app_shortcode}-profile-"
  role        = aws_iam_role.ssm_role.name
}

# -----------------------------------------------------------------------------
# EC2 Instance
# -----------------------------------------------------------------------------
resource "aws_instance" "test_instance" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = "t3.small"
  subnet_id                   = aws_subnet.private.id
  vpc_security_group_ids      = [aws_security_group.instance.id]
  iam_instance_profile        = aws_iam_instance_profile.instance_profile.name
  source_dest_check           = false
  associate_public_ip_address = false

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required" # IMDSv2 enforced
    http_put_response_hop_limit = 1
  }

  root_block_device {
    encrypted   = true
    volume_type = "gp2"
    volume_size = 20
  }

  tags = {
    Name = "${var.app_shortcode}-ssm-test-instance"
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the isolated VPC"
  value       = aws_vpc.isolated.id
}

output "subnet_id" {
  description = "The ID of the private subnet"
  value       = aws_subnet.private.id
}

output "instance_id" {
  description = "The ID of the test EC2 instance"
  value       = aws_instance.test_instance.id
}

output "instance_private_ip" {
  description = "The private IP address of the EC2 instance"
  value       = aws_instance.test_instance.private_ip
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "aws_region" {
  description = "The AWS region where resources will be created"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.11.0/24", "10.0.12.0/24", "10.0.13.0/24"]
}

variable "namespace_name" {
  description = "Domain name for private service discovery"
  type        = string
  default     = "private-fargate-crowdnews.hands-on.cloud.local"
}

variable "service_discovery_name" {
  description = "Record name for the ECS service"
  type        = string
  default     = "nginx"
}

variable "jumphost_static_ip" {
  description = "Static private IP for the Jumphost ENI"
  type        = string
  default     = "10.0.1.50"
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# ------------------------------------------------------------------------------
# VPC and Networking
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "fargate-vpc"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "fargate-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "fargate-public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "fargate-private-subnet-${count.index + 1}"
  }
}

# Elastic IPs and NAT Gateways
resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"

  tags = {
    Name = "fargate-nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "nat" {
  count         = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "fargate-nat-gw-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.igw]
}

# Route Tables
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "fargate-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = {
    Name = "fargate-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ------------------------------------------------------------------------------
# VPC Endpoints
# ------------------------------------------------------------------------------
resource "aws_security_group" "vpc_endpoints" {
  name        = "fargate-vpc-endpoints-sg"
  description = "Security group for VPC Interface Endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow TLS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "vpc-endpoints-sg"
  }
}

# Gateway Endpoint for S3
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.aws_region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "s3-gateway-endpoint"
  }
}

# Interface Endpoints
locals {
  interface_endpoints = {
    ecr_api = "com.amazonaws.${var.aws_region}.ecr.api"
    ecr_dkr = "com.amazonaws.${var.aws_region}.ecr.dkr"
    logs    = "com.amazonaws.${var.aws_region}.logs"
    secrets = "com.amazonaws.${var.aws_region}.secretsmanager"
    ssm     = "com.amazonaws.${var.aws_region}.ssm"
    kms     = "com.amazonaws.${var.aws_region}.kms"
  }
}

resource "aws_vpc_endpoint" "interfaces" {
  for_each            = local.interface_endpoints
  vpc_id              = aws_vpc.main.id
  service_name        = each.value
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "vpce-${each.key}"
  }
}

# ------------------------------------------------------------------------------
# Cloud Map Service Discovery
# ------------------------------------------------------------------------------
resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = var.namespace_name
  description = "Private DNS namespace for internal ECS microservices"
  vpc         = aws_vpc.main.id
}

resource "aws_service_discovery_service" "nginx" {
  name = var.service_discovery_name

  dns_config {
    namespace_id = aws_service_discovery_private_dns_namespace.main.id

    dns_records {
      ttl  = 10
      type = "A"
    }

    dns_records {
      ttl  = 10
      type = "SRV"
    }

    routing_policy = "MULTIVALUE"
  }

  health_check_custom_config {
    failure_threshold = 1
  }
}

# ------------------------------------------------------------------------------
# ECR and CloudWatch Logs
# ------------------------------------------------------------------------------
resource "aws_ecr_repository" "nginx" {
  name                 = "private-nginx"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = {
    Name = "private-nginx-repo"
  }
}

resource "aws_cloudwatch_log_group" "ecs" {
  name              = "/ecs/nginx-service"
  retention_in_days = 7

  tags = {
    Name = "ecs-nginx-logs"
  }
}

# ------------------------------------------------------------------------------
# IAM Roles for ECS
# ------------------------------------------------------------------------------
resource "aws_iam_role" "ecs_execution_role" {
  name = "ecsExecutionRole-nginx"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ecs-tasks.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_execution_standard" {
  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy" "ecs_execution_extra" {
  name = "ecsExecutionExtraPolicy"
  role = aws_iam_role.ecs_execution_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ssm:GetParameters",
          "secretsmanager:GetSecretValue",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "ecs_task_role" {
  name = "ecsTaskRole-nginx"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ecs-tasks.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy" "ecs_task_policy" {
  name = "ecsTaskPolicy"
  role = aws_iam_role.ecs_task_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "servicediscovery:DiscoverInstances",
          "servicediscovery:Get*",
          "servicediscovery:List*"
        ]
        Resource = "*"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# ECS Cluster, Task Definition & Service
# ------------------------------------------------------------------------------
resource "aws_ecs_cluster" "main" {
  name = "fargate-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }
}

resource "aws_security_group" "ecs_task" {
  name        = "nginx-fargate-task-sg"
  description = "Allow inbound HTTP from VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow HTTP within VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "nginx-fargate-task-sg"
  }
}

resource "aws_ecs_task_definition" "nginx" {
  family                   = "nginx-task"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "512"
  memory                   = "1024"
  execution_role_arn       = aws_iam_role.ecs_execution_role.arn
  task_role_arn            = aws_iam_role.ecs_task_role.arn

  container_definitions = jsonencode([
    {
      name      = "nginx"
      image     = "nginx:alpine"
      essential = true
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]
      environment = [
        {
          name  = "SERVICE_DISCOVERY_NAMESPACE_ID"
          value = aws_service_discovery_private_dns_namespace.main.id
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.ecs.name
          "awslogs-region"        = var.aws_region
          "awslogs-stream-prefix" = "nginx"
        }
      }
    }
  ])
}

resource "aws_ecs_service" "nginx" {
  name            = "nginx-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.nginx.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs_task.id]
    assign_public_ip = false
  }

  service_registries {
    registry_arn   = aws_service_discovery_service.nginx.arn
    container_name = "nginx"
    container_port = 80
  }

  depends_on = [
    aws_vpc_endpoint.interfaces,
    aws_vpc_endpoint.s3
  ]
}

# ------------------------------------------------------------------------------
# SSM Jumphost
# ------------------------------------------------------------------------------
resource "aws_security_group" "jumphost" {
  name        = "jumphost-sg"
  description = "Security group for Jumphost instance"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow inbound traffic from VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "jumphost-sg"
  }
}

resource "aws_network_interface" "jumphost" {
  subnet_id       = aws_subnet.public[0].id
  private_ips     = [var.jumphost_static_ip]
  security_groups = [aws_security_group.jumphost.id]

  tags = {
    Name = "jumphost-primary-eni"
  }
}

resource "aws_iam_role" "jumphost" {
  name = "jumphost-ssm-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "jumphost_ssm" {
  role       = aws_iam_role.jumphost.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "jumphost" {
  name = "jumphost-instance-profile"
  role = aws_iam_role.jumphost.name
}

resource "aws_instance" "jumphost" {
  ami                  = data.aws_ami.amazon_linux_2.id
  instance_type        = "t3.micro"
  iam_instance_profile = aws_iam_instance_profile.jumphost.name

  network_interface {
    network_interface_id = aws_network_interface.jumphost.id
    device_index         = 0
  }

  tags = {
    Name = "internal-test-jumphost"
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "jumphost_instance_id" {
  description = "Instance ID of the jumphost"
  value       = aws_instance.jumphost.id
}

output "jumphost_private_ip" {
  description = "Static private IP of the jumphost"
  value       = aws_network_interface.jumphost.private_ip
}

output "service_discovery_dns" {
  description = "Full internal DNS name of the NGINX service"
  value       = "${var.service_discovery_name}.${var.namespace_name}"
}

output "nginx_service_curl_command" {
  description = "Exact curl command to test the NGINX service internally via Cloud Map DNS"
  value       = "curl http://${var.service_discovery_name}.${var.namespace_name}"
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region for resources"
  type        = string
  default     = "us-east-1"
}

variable "project" {
  description = "Project name for resource naming and tagging"
  type        = string
  default     = "benchmark"
}

variable "application" {
  description = "Application name for resource naming and tagging"
  type        = string
  default     = "hpc-test"
}

variable "environment" {
  description = "Deployment environment (e.g. dev, test, prod)"
  type        = string
  default     = "bench"
}

variable "availability_zone_id" {
  description = "Target availability zone suffix or identifier"
  type        = string
  default     = "us-east-1a"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "custom_routes" {
  description = "Optional list of additional custom routes to inject into the route table"
  type = list(object({
    cidr_block     = string
    gateway_id     = optional(string)
    nat_gateway_id = optional(string)
  }))
  default = []
}

variable "allocate_eip" {
  description = "Whether to allocate and associate a static Elastic IP to the instance network interface"
  type        = bool
  default     = true
}

variable "generate_key_pair" {
  description = "Whether to generate and associate an SSH key pair with the EC2 instance"
  type        = bool
  default     = true
}

variable "attach_managed_ssm_policy" {
  description = "Whether to attach standard AmazonSSMManagedInstanceCore policy in addition to custom policy"
  type        = bool
  default     = true
}

variable "instance_type" {
  description = "EC2 instance type"
  type        = string
  default     = "t3.micro"
}

# ---------------------------------------------------------------------------------------------------------------------
# LOCALS & TAGS
# ---------------------------------------------------------------------------------------------------------------------

locals {
  name_prefix = "${var.project}-${var.application}-${var.environment}-${var.availability_zone_id}"

  common_tags = {
    Project          = var.project
    Application      = var.application
    Environment      = var.environment
    AvailabilityZone = var.availability_zone_id
    ManagedBy        = "Terraform"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES
# ---------------------------------------------------------------------------------------------------------------------

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# NETWORKING
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr
  availability_zone       = var.availability_zone_id
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.gw.id
  }

  dynamic "route" {
    for_each = var.custom_routes
    content {
      cidr_block     = route.value.cidr_block
      gateway_id     = try(route.value.gateway_id, null)
      nat_gateway_id = try(route.value.nat_gateway_id, null)
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "instance_sg" {
  name        = "${local.name_prefix}-sg"
  description = "Security group for benchmark EC2 instance"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port        = 0
    to_port          = 0
    protocol         = "-1"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = ["::/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sg"
  })
}

resource "aws_network_interface" "primary" {
  subnet_id       = aws_subnet.public.id
  security_groups = [aws_security_group.instance_sg.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-eni"
  })
}

resource "aws_eip" "instance_eip" {
  count             = var.allocate_eip ? 1 : 0
  domain            = "vpc"
  network_interface = aws_network_interface.primary.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-eip"
  })

  depends_on = [aws_internet_gateway.gw]
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM FOR SSM & INSTANCE PROFILE
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_iam_role" "ec2_ssm_role" {
  name = "${local.name_prefix}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = [
            "ec2.amazonaws.com",
            "ssm.amazonaws.com"
          ]
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-role"
  })
}

resource "aws_iam_policy" "ssm_session_manager" {
  name        = "${local.name_prefix}-ssm-policy"
  description = "Explicit permissions for SSM Session Manager channels and operational control"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ssmmessages:CreateControlChannel",
          "ssmmessages:CreateDataChannel",
          "ssmmessages:OpenControlChannel",
          "ssmmessages:OpenDataChannel",
          "ssm:UpdateInstanceInformation"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ssm-policy"
  })
}

resource "aws_iam_role_policy_attachment" "ssm_custom" {
  role       = aws_iam_role.ec2_ssm_role.name
  policy_arn = aws_iam_policy.ssm_session_manager.arn
}

resource "aws_iam_role_policy_attachment" "ssm_core" {
  count      = var.attach_managed_ssm_policy ? 1 : 0
  role       = aws_iam_role.ec2_ssm_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "profile" {
  name = "${local.name_prefix}-instance-profile"
  role = aws_iam_role.ec2_ssm_role.name

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-profile"
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# OPTIONAL KEY PAIR
# ---------------------------------------------------------------------------------------------------------------------

resource "tls_private_key" "ssh" {
  count     = var.generate_key_pair ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "generated" {
  count      = var.generate_key_pair ? 1 : 0
  key_name   = "${local.name_prefix}-key"
  public_key = tls_private_key.ssh[0].public_key_openssh

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-key"
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# EC2 INSTANCE
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_instance" "benchmark_instance" {
  ami                  = data.aws_ami.amazon_linux_2.id
  instance_type        = var.instance_type
  iam_instance_profile = aws_iam_instance_profile.profile.name
  key_name             = var.generate_key_pair ? aws_key_pair.generated[0].key_name : null

  network_interface {
    network_interface_id = aws_network_interface.primary.id
    device_index         = 0
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
    instance_metadata_tags      = "enabled"
  }

  root_block_device {
    volume_size           = 20
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true
    tags = merge(local.common_tags, {
      Name = "${local.name_prefix}-root-volume"
    })
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ec2"
  })
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "ec2_instance_id" {
  description = "ID of the deployed EC2 instance"
  value       = aws_instance.benchmark_instance.id
}

output "ec2_instance_arn" {
  description = "ARN of the deployed EC2 instance"
  value       = aws_instance.benchmark_instance.arn
}

output "iam_role_id" {
  description = "ID of the IAM role attached to the EC2 instance"
  value       = aws_iam_role.ec2_ssm_role.id
}

output "iam_role_arn" {
  description = "ARN of the IAM role attached to the EC2 instance"
  value       = aws_iam_role.ec2_ssm_role.arn
}

output "iam_instance_profile_id" {
  description = "ID of the IAM instance profile"
  value       = aws_iam_instance_profile.profile.id
}

output "iam_instance_profile_arn" {
  description = "ARN of the IAM instance profile"
  value       = aws_iam_instance_profile.profile.arn
}

output "subnet_id" {
  description = "ID of the public subnet"
  value       = aws_subnet.public.id
}

output "subnet_arn" {
  description = "ARN of the public subnet"
  value       = aws_subnet.public.arn
}

output "route_table_id" {
  description = "ID of the route table"
  value       = aws_route_table.public.id
}

output "route_table_arn" {
  description = "ARN of the route table"
  value       = aws_route_table.public.arn
}

output "elastic_ip" {
  description = "Allocated Elastic IP (if enabled)"
  value       = try(aws_eip.instance_eip[0].public_ip, null)
}

output "ssh_private_key_pem" {
  description = "Generated SSH Private Key in PEM format (if enabled)"
  value       = try(tls_private_key.ssh[0].private_key_pem, null)
  sensitive   = true
}
```

```terraform
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.9"
    }
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      "kubernetes.io/cluster/demo-eks" = "owned"
    }
  }
}

variable "aws_region" {
  type        = string
  default     = "us-east-1"
  description = "AWS region for deployments"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# VPC and Networking
# -----------------------------------------------------------------------------
resource "aws_vpc" "eks_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "demo-eks-vpc"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.eks_vpc.id

  tags = {
    Name = "demo-eks-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.eks_vpc.id
  cidr_block              = "10.0.101.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name                     = "demo-eks-public-subnet"
    "kubernetes.io/role/elb" = "1"
  }
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.igw]

  tags = {
    Name = "demo-eks-nat-eip"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "demo-eks-nat-gateway"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.eks_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "demo-eks-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.eks_vpc.id
  cidr_block              = "10.0.${count.index + 1}.0/24"
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name                              = "demo-eks-private-subnet-${count.index + 1}"
    "kubernetes.io/role/internal-elb" = "1"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.eks_vpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "demo-eks-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# KMS Key for EKS Secrets Encryption
# -----------------------------------------------------------------------------
resource "aws_kms_key" "eks" {
  description             = "KMS Key for EKS cluster secret encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "demo-eks-kms-key"
  }
}

# -----------------------------------------------------------------------------
# EKS Cluster Control Plane IAM Role
# -----------------------------------------------------------------------------
resource "aws_iam_role" "eks_cluster" {
  name = "eksClusterRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_iam_role_policy_attachment" "vpc_controller" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_iam_policy" "eks_kms" {
  name        = "EKSClusterKMSPolicy"
  description = "Allows EKS control plane to use KMS for secret encryption"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.eks.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cluster_kms" {
  policy_arn = aws_iam_policy.eks_kms.arn
  role       = aws_iam_role.eks_cluster.name
}

# -----------------------------------------------------------------------------
# EKS Cluster
# -----------------------------------------------------------------------------
resource "aws_eks_cluster" "demo" {
  name     = "demo-eks"
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    endpoint_private_access = true
    endpoint_public_access  = false
    subnet_ids              = aws_subnet.private[*].id
  }

  encryption_config {
    provider {
      key_arn = aws_kms_key.eks.arn
    }
    resources = ["secrets"]
  }

  depends_on = [
    aws_iam_role_policy_attachment.cluster_policy,
    aws_iam_role_policy_attachment.vpc_controller,
    aws_iam_role_policy_attachment.cluster_kms
  ]
}

# -----------------------------------------------------------------------------
# Worker Nodes Key Pair
# -----------------------------------------------------------------------------
resource "tls_private_key" "node_key" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_sensitive_file" "ssh_key_file" {
  content         = tls_private_key.node_key.private_key_pem
  filename        = pathexpand("~/.ssh/eks-aws.pem")
  file_permission = "0400"
}

resource "aws_key_pair" "eks_kp" {
  key_name   = "eks_kp"
  public_key = tls_private_key.node_key.public_key_openssh
}

# -----------------------------------------------------------------------------
# Security Groups & Traffic Rules
# -----------------------------------------------------------------------------
resource "aws_security_group" "node_sg" {
  name        = "demo-eks-node-sg"
  description = "Security group for all nodes in the demo-eks cluster"
  vpc_id      = aws_vpc.eks_vpc.id

  # Outbound traffic only within the VPC CIDR
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.eks_vpc.cidr_block]
  }

  # Unrestricted internal communication between nodes
  ingress {
    from_port = 0
    to_port   = 0
    protocol  = "-1"
    self      = true
  }

  tags = {
    Name = "demo-eks-node-sg"
  }
}

# Allow pods and kubelet to receive communication from the cluster control plane
resource "aws_security_group_rule" "node_ingress_cluster_443" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.node_sg.id
  source_security_group_id = aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id
  description              = "Allow cluster control plane to communicate with pods on 443"
}

resource "aws_security_group_rule" "node_ingress_cluster_kubelet" {
  type                     = "ingress"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  security_group_id        = aws_security_group.node_sg.id
  source_security_group_id = aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id
  description              = "Allow cluster control plane to communicate with worker kubelet and pods"
}

# Allow worker nodes to communicate with the cluster control plane
resource "aws_security_group_rule" "cluster_ingress_node_443" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id
  source_security_group_id = aws_security_group.node_sg.id
  description              = "Allow worker Kubelets and pods to communicate with control plane API"
}

resource "aws_security_group_rule" "cluster_ingress_node_ports" {
  type                     = "ingress"
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  security_group_id        = aws_eks_cluster.demo.vpc_config[0].cluster_security_group_id
  source_security_group_id = aws_security_group.node_sg.id
  description              = "Allow worker nodes communication to cluster on high ports"
}

# -----------------------------------------------------------------------------
# Worker Nodes IAM Role & Instance Profile
# -----------------------------------------------------------------------------
resource "aws_iam_role" "node_role" {
  name = "eks-demo-node"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "node_worker_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.node_role.name
}

resource "aws_iam_role_policy_attachment" "node_cni_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.node_role.name
}

resource "aws_iam_role_policy_attachment" "node_ecr_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.node_role.name
}

resource "aws_iam_role_policy_attachment" "node_ssm_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
  role       = aws_iam_role.node_role.name
}

resource "aws_iam_instance_profile" "node_profile" {
  name = "eks-demo-node-profile"
  role = aws_iam_role.node_role.name
}

# -----------------------------------------------------------------------------
# Amazon Linux 2 EKS AMI Lookup
# -----------------------------------------------------------------------------
data "aws_ssm_parameter" "eks_ami" {
  name = "/aws/service/eks/optimized-ami/${aws_eks_cluster.demo.version}/amazon-linux-2/recommended/image_id"
}

# -----------------------------------------------------------------------------
# EC2 Launch Template
# -----------------------------------------------------------------------------
resource "aws_launch_template" "eks_nodes" {
  name_prefix   = "demo-eks-node-"
  image_id      = data.aws_ssm_parameter.eks_ami.value
  instance_type = "t3.medium"
  key_name      = aws_key_pair.eks_kp.key_name

  iam_instance_profile {
    arn = aws_iam_instance_profile.node_profile.arn
  }

  network_interfaces {
    associate_public_ip_address = false
    security_groups             = [aws_security_group.node_sg.id]
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 30
      volume_type           = "gp2"
      delete_on_termination = true
    }
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  user_data = base64encode(<<-EOF
    #!/bin/bash
    set -o xtrace
    /etc/eks/bootstrap.sh ${aws_eks_cluster.demo.name} --b64-cluster-ca ${aws_eks_cluster.demo.certificate_authority[0].data} --apiserver-endpoint ${aws_eks_cluster.demo.endpoint}
    /opt/aws/bin/cfn-signal --exit-code $? --stack eks-cluster-stack --resource NodeGroup --region ${var.aws_region}
  EOF
  )

  tag_specifications {
    resource_type = "instance"
    tags = {
      Name                             = "demo-eks-node"
      "kubernetes.io/cluster/demo-eks" = "owned"
    }
  }

  lifecycle {
    create_before_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Delay before CloudFormation deployment
# -----------------------------------------------------------------------------
resource "time_sleep" "wait_30_seconds" {
  depends_on      = [aws_launch_template.eks_nodes]
  create_duration = "30s"
}

# -----------------------------------------------------------------------------
# CloudFormation Managed Auto Scaling Group
# -----------------------------------------------------------------------------
resource "aws_cloudformation_stack" "eks_asg" {
  name = "eks-cluster-stack"

  template_body = jsonencode({
    AWSTemplateFormatVersion = "2010-09-09"
    Description              = "CloudFormation-managed Auto Scaling Group for EKS worker nodes"
    Resources = {
      NodeGroup = {
        Type = "AWS::AutoScaling::AutoScalingGroup"
        Properties = {
          DesiredCapacity = "3"
          MinSize         = "1"
          MaxSize         = "4"
          VPCZoneIdentifier = aws_subnet.private[*].id
          LaunchTemplate = {
            LaunchTemplateId = aws_launch_template.eks_nodes.id
            Version          = tostring(aws_launch_template.eks_nodes.latest_version)
          }
          Tags = [
            {
              Key               = "Name"
              Value             = "demo-eks-node"
              PropagateAtLaunch = true
            },
            {
              Key               = "kubernetes.io/cluster/demo-eks"
              Value             = "owned"
              PropagateAtLaunch = true
            }
          ]
        }
        UpdatePolicy = {
          AutoScalingRollingUpdate = {
            MaxBatchSize          = 1
            MinInstancesInService = 3
            PauseTime             = "PT5M"
            WaitOnResourceSignals = true
          }
        }
      }
    }
    Outputs = {
      AutoScalingGroupName = {
        Description = "The Auto Scaling Group name/ID"
        Value       = { Ref = "NodeGroup" }
      }
    }
  })

  depends_on = [
    time_sleep.wait_30_seconds,
    aws_eks_cluster.demo
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "node_instance_role_arn" {
  description = "ARN of the IAM role assigned to worker nodes"
  value       = aws_iam_role.node_role.arn
}

output "node_security_group_id" {
  description = "ID of the dedicated worker node security group"
  value       = aws_security_group.node_sg.id
}

output "auto_scaling_group_id" {
  description = "Auto Scaling Group ID returned from the CloudFormation stack"
  value       = aws_cloudformation_stack.eks_asg.outputs["AutoScalingGroupName"]
}
```

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
  }
}

variable "primary_region" {
  type        = string
  description = "Primary AWS region for Terraform state storage"
  default     = "us-east-1"
}

variable "replica_region" {
  type        = string
  description = "Secondary AWS region for disaster recovery state replication"
  default     = "us-west-2"
}

variable "eks_stacks" {
  type = map(object({
    region = string
  }))
  description = "Map of EKS stacks and their respective operating regions"
  default = {
    "eks-dev" = {
      region = "us-east-1"
    }
    "eks-staging" = {
      region = "us-east-1"
    }
    "eks-prod" = {
      region = "us-east-1"
    }
  }
}

variable "common_tags" {
  type        = map(string)
  description = "Standardized tags applied to all state management resources"
  default = {
    ManagedBy   = "Terraform"
    Environment = "Core-State-Infrastructure"
    Purpose     = "Terraform-State-Management"
  }
}

# Provider configurations
provider "aws" {
  alias  = "primary"
  region = var.primary_region
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

# Default provider pointing to primary region
provider "aws" {
  region = var.primary_region
}

# Current context data
data "aws_caller_identity" "current" {}

# ==============================================================================
# KMS KEYS (PRIMARY & REPLICA)
# ==============================================================================

# Primary KMS Key
resource "aws_kms_key" "primary_state_key" {
  provider                = aws.primary
  description             = "KMS Key for primary Terraform state encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = var.common_tags
}

resource "aws_kms_alias" "primary_state_key_alias" {
  provider      = aws.primary
  name          = "alias/terraform-state-primary"
  target_key_id = aws_kms_key.primary_state_key.key_id
}

# Replica KMS Key
resource "aws_kms_key" "replica_state_key" {
  provider                = aws.replica
  description             = "KMS Key for replicated Terraform state encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = var.common_tags
}

resource "aws_kms_alias" "replica_state_key_alias" {
  provider      = aws.replica
  name          = "alias/terraform-state-replica"
  target_key_id = aws_kms_key.replica_state_key.key_id
}

# ==============================================================================
# REPLICA S3 BUCKET (DESTINATION)
# ==============================================================================

resource "aws_s3_bucket" "replica_state_bucket" {
  provider      = aws.replica
  bucket        = "tf-state-replica-${data.aws_caller_identity.current.account_id}-${var.replica_region}"
  force_destroy = false
  tags          = var.common_tags
}

resource "aws_s3_bucket_versioning" "replica_versioning" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state_bucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica_public_block" {
  provider                = aws.replica
  bucket                  = aws_s3_bucket.replica_state_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica_encryption" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica_state_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "replica_deny_non_ssl" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica_state_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnforceTLSRequestsOnly"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.replica_state_bucket.arn,
          "${aws_s3_bucket.replica_state_bucket.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# ==============================================================================
# S3 CROSS-REGION REPLICATION IAM ROLE & POLICIES
# ==============================================================================

resource "aws_iam_role" "replication_role" {
  name = "terraform-state-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.common_tags
}

resource "aws_iam_policy" "replication_policy" {
  name        = "terraform-state-replication-policy"
  description = "Allows S3 to replicate KMS-encrypted state objects across regions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:aws:s3:::tf-state-primary-${data.aws_caller_identity.current.account_id}-${var.primary_region}"
        ]
      },
      {
        Sid    = "SourceBucketObjectPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = [
          "arn:aws:s3:::tf-state-primary-${data.aws_caller_identity.current.account_id}-${var.primary_region}/*"
        ]
      },
      {
        Sid    = "DestinationBucketObjectPermissions"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = "${aws_s3_bucket.replica_state_bucket.arn}/*"
      },
      {
        Sid    = "SourceKMSDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = aws_kms_key.primary_state_key.arn
        Condition = {
          StringLike = {
            "kms:ViaService" = "s3.${var.primary_region}.amazonaws.com"
          }
        }
      },
      {
        Sid    = "DestinationKMSEncrypt"
        Effect = "Allow"
        Action = [
          "kms:Encrypt"
        ]
        Resource = aws_kms_key.replica_state_key.arn
        Condition = {
          StringLike = {
            "kms:ViaService" = "s3.${var.replica_region}.amazonaws.com"
          }
        }
      }
    ]
  })

  tags = var.common_tags
}

resource "aws_iam_role_policy_attachment" "replication_attachment" {
  role       = aws_iam_role.replication_role.name
  policy_arn = aws_iam_policy.replication_policy.arn
}

# ==============================================================================
# PRIMARY S3 BUCKET (SOURCE)
# ==============================================================================

resource "aws_s3_bucket" "primary_state_bucket" {
  provider      = aws.primary
  bucket        = "tf-state-primary-${data.aws_caller_identity.current.account_id}-${var.primary_region}"
  force_destroy = false
  tags          = var.common_tags
}

resource "aws_s3_bucket_versioning" "primary_versioning" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary_state_bucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "primary_public_block" {
  provider                = aws.primary
  bucket                  = aws_s3_bucket.primary_state_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary_encryption" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary_state_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary_state_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "primary_deny_non_ssl" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary_state_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnforceTLSRequestsOnly"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.primary_state_bucket.arn,
          "${aws_s3_bucket.primary_state_bucket.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "primary_replication" {
  provider   = aws.primary
  depends_on = [aws_s3_bucket_versioning.primary_versioning, aws_s3_bucket_versioning.replica_versioning]
  bucket     = aws_s3_bucket.primary_state_bucket.id
  role       = aws_iam_role.replication_role.arn

  rule {
    id     = "ReplicateAllStateObjects"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.replica_state_bucket.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica_state_key.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

# ==============================================================================
# DYNAMODB LOCK TABLES & PER-STACK IAM POLICIES
# ==============================================================================

resource "aws_dynamodb_table" "lock_table" {
  for_each     = var.eks_stacks
  name         = "${each.key}-state-lock"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.primary_state_key.arn
  }

  tags = merge(
    var.common_tags,
    {
      StackName = each.key
    }
  )
}

resource "aws_iam_policy" "stack_state_policy" {
  for_each    = var.eks_stacks
  name        = "${each.key}-tf-state-access-policy"
  description = "Scoped permissions for ${each.key} to access S3 state, DynamoDB lock table, and KMS key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3BucketLocationAndList"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          aws_s3_bucket.primary_state_bucket.arn
        ]
      },
      {
        Sid    = "S3StackStateAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = [
          "${aws_s3_bucket.primary_state_bucket.arn}/${each.key}/*",
          "${aws_s3_bucket.primary_state_bucket.arn}/env:/${each.key}/*"
        ]
      },
      {
        Sid    = "DynamoDBLockAccess"
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem",
          "dynamodb:DescribeTable"
        ]
        Resource = [
          aws_dynamodb_table.lock_table[each.key].arn
        ]
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = [
          aws_kms_key.primary_state_key.arn
        ]
      }
    ]
  })

  tags = merge(
    var.common_tags,
    {
      StackName = each.key
    }
  )
}

# ==============================================================================
# LOCAL BACKEND CONFIGURATION FILES GENERATION
# ==============================================================================

resource "local_file" "backend_config" {
  for_each = var.eks_stacks
  filename = "${path.module}/eks-stacks/${each.key}/backend.tf"

  content = <<-EOT
# Auto-generated backend configuration for ${each.key}
terraform {
  backend "s3" {
    bucket         = "${aws_s3_bucket.primary_state_bucket.bucket}"
    key            = "${each.key}/terraform.tfstate"
    region         = "${var.primary_region}"
    dynamodb_table = "${aws_dynamodb_table.lock_table[each.key].name}"
    encrypt        = true
    kms_key_id     = "${aws_kms_key.primary_state_key.arn}"
  }
}
EOT
}

# ==============================================================================
# OUTPUTS
# ==============================================================================

output "primary_bucket_name" {
  value       = aws_s3_bucket.primary_state_bucket.bucket
  description = "Primary S3 bucket name for state storage"
}

output "replica_bucket_name" {
  value       = aws_s3_bucket.replica_state_bucket.bucket
  description = "Replica S3 bucket name for DR replication"
}

output "primary_kms_key_arn" {
  value       = aws_kms_key.primary_state_key.arn
  description = "KMS Key ARN used in the primary region"
}

output "replica_kms_key_arn" {
  value       = aws_kms_key.replica_state_key.arn
  description = "KMS Key ARN used in the replica region"
}

output "dynamodb_table_names" {
  value       = { for k, v in aws_dynamodb_table.lock_table : k => v.name }
  description = "Names of the DynamoDB lock tables by stack"
}

output "stack_iam_policy_arns" {
  value       = { for k, v in aws_iam_policy.stack_state_policy : k => v.arn }
  description = "ARNs of the generated IAM access policies per stack"
}
