terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources in"
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# Amazon Cognito User Pool
resource "aws_cognito_user_pool" "box_things" {
  name = "box_things"

  # Sign-in using email as an alias/username
  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]

  # Verification via link
  verification_message_template {
    default_email_option = "CONFIRM_WITH_LINK"
    email_message_by_link = "Please click the link below to verify your email address: {##Click Here##}"
    email_subject_by_link = "Verify your email for Box Things"
  }

  # Allow self sign-up
  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  # Multi-Factor Authentication disabled
  mfa_configuration = "OFF"

  # Strong 8-character password policy
  password_policy {
    minimum_length                   = 8
    require_lowercase                = true
    require_numbers                  = true
    require_symbols                  = true
    require_uppercase                = true
    temporary_password_validity_days = 7
  }

  # Standard email attribute configuration
  schema {
    name                = "email"
    attribute_data_type = "String"
    required            = true
    mutable             = true

    string_attribute_constraints {
      min_length = "1"
      max_length = "256"
    }
  }
}

# Amazon Cognito User Pool Client
resource "aws_cognito_user_pool_client" "box_things_client" {
  name         = "box_things_client"
  user_pool_id = aws_cognito_user_pool.box_things.id

  # Authentication flows
  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH"
  ]

  # Token validities (60 minutes for Access and ID tokens)
  access_token_validity  = 60
  id_token_validity      = 60
  refresh_token_validity = 30

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }

  # Callback and Logout URLs
  callback_urls = ["https://example.com/callback"]
  logout_urls   = ["https://example.com/logout"]

  # OAuth settings
  allowed_oauth_flows                  = ["code", "implicit"]
  allowed_oauth_scopes                 = ["email", "openid", "profile"]
  allowed_oauth_flows_user_pool_client = true

  # Do not generate client secret for standard public client usage
  generate_secret = false
}

# Outputs
output "user_pool_id" {
  description = "The ID of the created Cognito User Pool"
  value       = aws_cognito_user_pool.box_things.id
}

output "user_pool_arn" {
  description = "The ARN of the created Cognito User Pool"
  value       = aws_cognito_user_pool.box_things.arn
}

output "user_pool_client_id" {
  description = "The ID of the created Cognito User Pool Client"
  value       = aws_cognito_user_pool_client.box_things_client.id
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# Variable Definitions
variable "aws_region" {
  description = "The AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "users" {
  description = "Map of users and their tags"
  type = map(object({
    owner = string
  }))
  default = {
    dev1 = {
      owner = "Devel"
    }
    dev2 = {
      owner = "Devel"
    }
    guest = {
      owner = "Guest"
    }
  }
}

# IAM Groups
resource "aws_iam_group" "devel_group" {
  name = "Ersia_Devel_Group"
  path = "/"
}

resource "aws_iam_group" "guest_group" {
  name = "Ersia_Guest_Group"
  path = "/"
}

# Managed Policy Attachments to IAM Groups
resource "aws_iam_group_policy_attachment" "devel_policy_attachment" {
  group      = aws_iam_group.devel_group.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "guest_policy_attachment" {
  group      = aws_iam_group.guest_group.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

# IAM Users
resource "aws_iam_user" "users" {
  for_each = var.users

  name = each.key
  path = "/"

  tags = {
    Owner = each.value.owner
  }
}

# Group Membership for Devel Group (Users where Owner == "Devel")
resource "aws_iam_group_membership" "devel_group_membership" {
  name  = "ersia-devel-group-membership"
  group = aws_iam_group.devel_group.name

  users = [
    for username, user_data in var.users :
    aws_iam_user.users[username].name
    if user_data.owner == "Devel"
  ]
}

# Group Membership for Guest Group (Users where Owner != "Devel")
resource "aws_iam_group_membership" "guest_group_membership" {
  name  = "ersia-guest-group-membership"
  group = aws_iam_group.guest_group.name

  users = [
    for username, user_data in var.users :
    aws_iam_user.users[username].name
    if user_data.owner != "Devel"
  ]
}

# Outputs
output "devel_group_users" {
  description = "List of users added to the Ersia_Devel_Group"
  value       = aws_iam_group_membership.devel_group_membership.users
}

output "guest_group_users" {
  description = "List of users added to the Ersia_Guest_Group"
  value       = aws_iam_group_membership.guest_group_membership.users
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region for resources"
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# Fetch current account ID and partition
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# Random two-word pet name for API and SQS queue naming
resource "random_pet" "name" {
  length    = 2
  separator = "-"
}

# KMS Key for SQS queue encryption
resource "aws_kms_key" "sqs_key" {
  description             = "KMS key for WebSocket SQS queue encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowAPIGatewayService"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt",
          "kms:Encrypt"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sqs_key_alias" {
  name          = "alias/${random_pet.name.id}-sqs-key"
  target_key_id = aws_kms_key.sqs_key.key_id
}

# Amazon SQS Queue
resource "aws_sqs_queue" "queue" {
  name              = "${random_pet.name.id}-queue"
  kms_master_key_id = aws_kms_key.sqs_key.id
}

# IAM Role for API Gateway to access SQS and CloudWatch Logs
resource "aws_iam_role" "apigw_role" {
  name = "${random_pet.name.id}-apigw-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "apigw_policy" {
  name        = "${random_pet.name.id}-apigw-policy"
  description = "Allows API Gateway to send messages to SQS and write logs to CloudWatch"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SQSSendMessage"
        Effect = "Allow"
        Action = [
          "sqs:SendMessage"
        ]
        Resource = aws_sqs_queue.queue.arn
      },
      {
        Sid    = "KMSUse"
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt",
          "kms:Encrypt"
        ]
        Resource = aws_kms_key.sqs_key.arn
      },
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
          "logs:GetLogEvents",
          "logs:FilterLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "apigw_attachment" {
  role       = aws_iam_role.apigw_role.name
  policy_arn = aws_iam_policy.apigw_policy.arn
}

# API Gateway v2 WebSocket API
resource "aws_apigatewayv2_api" "websocket_api" {
  name                       = random_pet.name.id
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

# -----------------------------------------------------------------------------
# Route: $connect (Mock integration returning 200)
# -----------------------------------------------------------------------------
resource "aws_apigatewayv2_integration" "connect_integration" {
  api_id           = aws_apigatewayv2_api.websocket_api.id
  integration_type = "MOCK"
  request_templates = {
    "application/json" = "{\"statusCode\": 200}"
  }
  template_selection_expression = "\\$default"
}

resource "aws_apigatewayv2_integration_response" "connect_integration_response" {
  api_id                   = aws_apigatewayv2_api.websocket_api.id
  integration_id           = aws_apigatewayv2_integration.connect_integration.id
  integration_response_key = "/200/"
}

resource "aws_apigatewayv2_route" "connect_route" {
  api_id             = aws_apigatewayv2_api.websocket_api.id
  route_key          = "$connect"
  target             = "integrations/${aws_apigatewayv2_integration.connect_integration.id}"
  operation_name     = "ConnectRoute"
  route_response_selection_expression = "$default"
}

resource "aws_apigatewayv2_route_response" "connect_route_response" {
  api_id             = aws_apigatewayv2_api.websocket_api.id
  route_id           = aws_apigatewayv2_route.connect_route.id
  route_response_key = "$default"
}

# -----------------------------------------------------------------------------
# Route: $default (SQS AWS Service Integration forwarding client message body)
# -----------------------------------------------------------------------------
resource "aws_apigatewayv2_integration" "default_integration" {
  api_id                    = aws_apigatewayv2_api.websocket_api.id
  integration_type          = "AWS"
  integration_method        = "POST"
  integration_uri           = "arn:${data.aws_partition.current.partition}:apigateway:${var.aws_region}:sqs:path/${data.aws_caller_identity.current.account_id}/${aws_sqs_queue.queue.name}"
  credentials_arn           = aws_iam_role.apigw_role.arn
  passthrough_behavior      = "WHEN_NO_MATCH"
  content_handling_strategy = "CONVERT_TO_TEXT"

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }

  request_templates = {
    "application/json" = "Action=SendMessage&MessageBody=$util.urlEncode($request.body)"
  }

  template_selection_expression = "\\$default"
}

resource "aws_apigatewayv2_integration_response" "default_integration_response" {
  api_id                   = aws_apigatewayv2_api.websocket_api.id
  integration_id           = aws_apigatewayv2_integration.default_integration.id
  integration_response_key = "/200/"
}

resource "aws_apigatewayv2_route" "default_route" {
  api_id             = aws_apigatewayv2_api.websocket_api.id
  route_key          = "$default"
  target             = "integrations/${aws_apigatewayv2_integration.default_integration.id}"
  operation_name     = "DefaultRoute"
  route_response_selection_expression = "$default"
}

resource "aws_apigatewayv2_route_response" "default_route_response" {
  api_id             = aws_apigatewayv2_api.websocket_api.id
  route_id           = aws_apigatewayv2_route.default_route.id
  route_response_key = "$default"
}

# -----------------------------------------------------------------------------
# Route: $disconnect (SQS AWS Service Integration sending fixed disconnect text)
# -----------------------------------------------------------------------------
resource "aws_apigatewayv2_integration" "disconnect_integration" {
  api_id                    = aws_apigatewayv2_api.websocket_api.id
  integration_type          = "AWS"
  integration_method        = "POST"
  integration_uri           = "arn:${data.aws_partition.current.partition}:apigateway:${var.aws_region}:sqs:path/${data.aws_caller_identity.current.account_id}/${aws_sqs_queue.queue.name}"
  credentials_arn           = aws_iam_role.apigw_role.arn
  passthrough_behavior      = "WHEN_NO_MATCH"
  content_handling_strategy = "CONVERT_TO_TEXT"

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }

  request_templates = {
    "application/json" = "Action=SendMessage&MessageBody=Client%20disconnected"
  }

  template_selection_expression = "\\$default"
}

resource "aws_apigatewayv2_route" "disconnect_route" {
  api_id         = aws_apigatewayv2_api.websocket_api.id
  route_key      = "$disconnect"
  target         = "integrations/${aws_apigatewayv2_integration.disconnect_integration.id}"
  operation_name = "DisconnectRoute"
}

# -----------------------------------------------------------------------------
# CloudWatch Log Group & Stage Deployment
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "api_logs" {
  name              = "/aws/apigateway/${random_pet.name.id}-access-logs"
  retention_in_days = 1
}

resource "aws_apigatewayv2_stage" "dev" {
  api_id      = aws_apigatewayv2_api.websocket_api.id
  name        = "dev"
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_logs.arn
    format          = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      caller         = "$context.identity.caller"
      user           = "$context.identity.user"
      requestTime    = "$context.requestTime"
      eventType      = "$context.eventType"
      routeKey       = "$context.routeKey"
      status         = "$context.status"
      connectionId   = "$context.connectionId"
      integrationErrorMessage = "$context.integrationErrorMessage"
    })
  }

  depends_on = [
    aws_apigatewayv2_route.connect_route,
    aws_apigatewayv2_route.default_route,
    aws_apigatewayv2_route.disconnect_route,
    aws_apigatewayv2_integration_response.connect_integration_response,
    aws_apigatewayv2_integration_response.default_integration_response
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "websocket_url" {
  description = "The WebSocket API execution URL including stage"
  value       = "${aws_apigatewayv2_api.websocket_api.api_endpoint}/${aws_apigatewayv2_stage.dev.name}"
}

output "sqs_queue_url" {
  description = "The URL of the created Amazon SQS queue"
  value       = aws_sqs_queue.queue.id
}

output "sqs_queue_arn" {
  description = "The ARN of the created Amazon SQS queue"
  value       = aws_sqs_queue.queue.arn
}

output "kms_key_arn" {
  description = "The ARN of the customer-managed KMS key"
  value       = aws_kms_key.sqs_key.arn
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  type        = string
  description = "AWS region for VPC deployment"
  default     = "us-east-1"
}

# VPC 1: XXXX-vpc-test
variable "vpc1_cidr_block" {
  type        = string
  description = "CIDR block for VPC 1"
  default     = "10.0.0.0/16"
}

variable "vpc1_enable_dns_support" {
  type        = bool
  description = "Enable DNS support for VPC 1"
  default     = true
}

variable "vpc1_enable_dns_hostnames" {
  type        = bool
  description = "Enable DNS hostnames for VPC 1"
  default     = false
}

variable "vpc1_tags" {
  type        = map(string)
  description = "Tags for VPC 1"
  default = {
    Name = "XXXX-vpc-test"
  }
}

# VPC 2: Default
variable "vpc2_cidr_block" {
  type        = string
  description = "CIDR block for VPC 2"
  default     = "172.31.0.0/16"
}

variable "vpc2_enable_dns_support" {
  type        = bool
  description = "Enable DNS support for VPC 2"
  default     = true
}

variable "vpc2_enable_dns_hostnames" {
  type        = bool
  description = "Enable DNS hostnames for VPC 2"
  default     = true
}

variable "vpc2_tags" {
  type        = map(string)
  description = "Tags for VPC 2"
  default = {
    Name = "Default"
  }
}

# VPC 3: eksctl-eks-cluster-px-cluster/VPC
variable "vpc3_cidr_block" {
  type        = string
  description = "CIDR block for VPC 3"
  default     = "192.168.0.0/16"
}

variable "vpc3_enable_dns_support" {
  type        = bool
  description = "Enable DNS support for VPC 3"
  default     = true
}

variable "vpc3_enable_dns_hostnames" {
  type        = bool
  description = "Enable DNS hostnames for VPC 3"
  default     = true
}

variable "vpc3_tags" {
  type        = map(string)
  description = "Tags for VPC 3"
  default = {
    Name                                            = "eksctl-eks-cluster-px-cluster/VPC"
    "eksctl.cluster.k8s.io/v1alpha1/cluster-name" = "eks-cluster-px"
    "alpha.eksctl.io/eksctl-version"                = "0.94.0"
  }
}

# VPC 4: Untagged
variable "vpc4_cidr_block" {
  type        = string
  description = "CIDR block for VPC 4"
  default     = "10.0.0.0/24"
}

variable "vpc4_enable_dns_support" {
  type        = bool
  description = "Enable DNS support for VPC 4"
  default     = true
}

variable "vpc4_enable_dns_hostnames" {
  type        = bool
  description = "Enable DNS hostnames for VPC 4"
  default     = false
}

variable "vpc4_tags" {
  type        = map(string)
  description = "Tags for VPC 4"
  default     = {}
}

# VPC 5: Empty Name Tag
variable "vpc5_cidr_block" {
  type        = string
  description = "CIDR block for VPC 5"
  default     = "10.0.0.0/16"
}

variable "vpc5_enable_dns_support" {
  type        = bool
  description = "Enable DNS support for VPC 5"
  default     = true
}

variable "vpc5_enable_dns_hostnames" {
  type        = bool
  description = "Enable DNS hostnames for VPC 5"
  default     = false
}

variable "vpc5_tags" {
  type        = map(string)
  description = "Tags for VPC 5"
  default = {
    Name = ""
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# RESOURCES
# ---------------------------------------------------------------------------------------------------------------------

# 1. VPC named "XXXX-vpc-test" with CIDR 10.0.0.0/16
resource "aws_vpc" "vpc_test" {
  cidr_block           = var.vpc1_cidr_block
  instance_tenancy     = "default"
  enable_dns_support   = var.vpc1_enable_dns_support
  enable_dns_hostnames = var.vpc1_enable_dns_hostnames

  tags = var.vpc1_tags
}

# 2. VPC named "Default" with CIDR 172.31.0.0/16 and DNS hostnames enabled
resource "aws_vpc" "vpc_default_named" {
  cidr_block           = var.vpc2_cidr_block
  instance_tenancy     = "default"
  enable_dns_support   = var.vpc2_enable_dns_support
  enable_dns_hostnames = var.vpc2_enable_dns_hostnames

  tags = var.vpc2_tags
}

# 3. VPC named "eksctl-eks-cluster-px-cluster/VPC" with CIDR 192.168.0.0/16 and DNS hostnames enabled
resource "aws_vpc" "vpc_eks" {
  cidr_block           = var.vpc3_cidr_block
  instance_tenancy     = "default"
  enable_dns_support   = var.vpc3_enable_dns_support
  enable_dns_hostnames = var.vpc3_enable_dns_hostnames

  tags = var.vpc3_tags
}

# 4. Untagged VPC with CIDR 10.0.0.0/24
resource "aws_vpc" "vpc_untagged" {
  cidr_block           = var.vpc4_cidr_block
  instance_tenancy     = "default"
  enable_dns_support   = var.vpc4_enable_dns_support
  enable_dns_hostnames = var.vpc4_enable_dns_hostnames

  tags = var.vpc4_tags
}

# 5. VPC with CIDR 10.0.0.0/16 and an empty Name tag
resource "aws_vpc" "vpc_empty_name" {
  cidr_block           = var.vpc5_cidr_block
  instance_tenancy     = "default"
  enable_dns_support   = var.vpc5_enable_dns_support
  enable_dns_hostnames = var.vpc5_enable_dns_hostnames

  tags = var.vpc5_tags
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "vpc_test_id" {
  description = "The ID of the XXXX-vpc-test VPC"
  value       = aws_vpc.vpc_test.id
}

output "vpc_default_named_id" {
  description = "The ID of the Default-named VPC"
  value       = aws_vpc.vpc_default_named.id
}

output "vpc_eks_id" {
  description = "The ID of the EKS cluster VPC"
  value       = aws_vpc.vpc_eks.id
}

output "vpc_untagged_id" {
  description = "The ID of the untagged VPC"
  value       = aws_vpc.vpc_untagged.id
}

output "vpc_empty_name_id" {
  description = "The ID of the VPC with the empty Name tag"
  value       = aws_vpc.vpc_empty_name.id
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region for resources"
  default     = "us-east-1"
}

variable "tags" {
  type        = map(string)
  description = "Optional tags to apply to the IAM resources"
  default     = {}
}

# 1. ECS Service Role
data "aws_iam_policy_document" "ecs_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_role" {
  name                  = "ecs-role"
  path                  = "/"
  assume_role_policy    = data.aws_iam_policy_document.ecs_assume_role.json
  force_detach_policies = true
  tags                  = var.tags
}

resource "aws_iam_role_policy_attachment" "ecs_role_attach" {
  role       = aws_iam_role.ecs_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

# 2. ECS Tasks Execution Role
data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_tasks_role" {
  name                  = "ecs-tasks-role"
  path                  = "/"
  assume_role_policy    = data.aws_iam_policy_document.ecs_tasks_assume_role.json
  force_detach_policies = true
  tags                  = var.tags
}

resource "aws_iam_role_policy_attachment" "ecs_tasks_role_attach" {
  role       = aws_iam_role.ecs_tasks_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# 3. EventBridge Role and Policies
data "aws_iam_policy_document" "events_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "events_role" {
  name                  = "events-role"
  path                  = "/"
  assume_role_policy    = data.aws_iam_policy_document.events_assume_role.json
  force_detach_policies = true
  tags                  = var.tags
}

data "aws_iam_policy_document" "ecs_policy_doc" {
  statement {
    sid       = "AllowRunTask"
    effect    = "Allow"
    actions   = ["ecs:RunTask"]
    resources = ["*"]
  }

  statement {
    sid       = "AllowPassRole"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.ecs_tasks_role.arn]
  }
}

resource "aws_iam_policy" "ecs_policy" {
  name        = "ecs-policy"
  path        = "/"
  description = "Allows EventBridge to trigger ECS tasks and pass the task execution role"
  policy      = data.aws_iam_policy_document.ecs_policy_doc.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "events_role_ecs_policy_attach" {
  role       = aws_iam_role.events_role.name
  policy_arn = aws_iam_policy.ecs_policy.arn
}

resource "aws_iam_role_policy_attachment" "events_role_cloudwatch_attach" {
  role       = aws_iam_role.events_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchLogsFullAccess"
}

# Outputs
output "ecs_service_role_arn" {
  description = "ARN of the ECS service role"
  value       = aws_iam_role.ecs_role.arn
}

output "ecs_tasks_role_arn" {
  description = "ARN of the ECS task execution role"
  value       = aws_iam_role.ecs_tasks_role.arn
}

output "events_role_arn" {
  description = "ARN of the EventBridge role"
  value       = aws_iam_role.events_role.arn
}

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------

variable "primary_bucket_prefix" {
  type        = string
  description = "Prefix for the primary S3 bucket name in us-east-1"
  default     = "example1"
}

variable "secondary_bucket_prefix" {
  type        = string
  description = "Prefix for the secondary S3 bucket name in us-west-2"
  default     = "example2"
}

variable "mrap_name" {
  type        = string
  description = "Name of the S3 Multi-Region Access Point"
  default     = "example-mrap"
}

# -----------------------------------------------------------------------------
# Provider Configurations
# -----------------------------------------------------------------------------

provider "aws" {
  alias  = "primary"
  region = "us-east-1"
}

provider "aws" {
  alias  = "secondary"
  region = "us-west-2"
}

# Default provider for account metadata lookup
provider "aws" {
  region = "us-west-2"
}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# KMS Keys for Default SSE-KMS Encryption
# -----------------------------------------------------------------------------

# Primary KMS Key (us-east-1)
resource "aws_kms_key" "primary" {
  provider                = aws.primary
  description             = "KMS Key for primary S3 bucket in us-east-1"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "primary" {
  provider      = aws.primary
  name          = "alias/s3-primary-key"
  target_key_id = aws_kms_key.primary.key_id
}

# Secondary KMS Key (us-west-2)
resource "aws_kms_key" "secondary" {
  provider                = aws.secondary
  description             = "KMS Key for secondary S3 bucket in us-west-2"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "secondary" {
  provider      = aws.secondary
  name          = "alias/s3-secondary-key"
  target_key_id = aws_kms_key.secondary.key_id
}

# -----------------------------------------------------------------------------
# Primary S3 Bucket (us-east-1)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "primary" {
  provider      = aws.primary
  bucket        = "${var.primary_bucket_prefix}-${data.aws_caller_identity.current.account_id}"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "primary" {
  provider   = aws.primary
  bucket     = aws_s3_bucket.primary.id
  acl        = "private"
  depends_on = [aws_s3_bucket_ownership_controls.primary]
}

resource "aws_s3_bucket_versioning" "primary" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# Secondary S3 Bucket (us-west-2)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "secondary" {
  provider      = aws.secondary
  bucket        = "${var.secondary_bucket_prefix}-${data.aws_caller_identity.current.account_id}"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "secondary" {
  provider   = aws.secondary
  bucket     = aws_s3_bucket.secondary.id
  acl        = "private"
  depends_on = [aws_s3_bucket_ownership_controls.secondary]
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.secondary.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# S3 Replication Configuration
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "s3_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = "s3-replication-role-${data.aws_caller_identity.current.account_id}"
  assume_role_policy = data.aws_iam_policy_document.s3_assume_role.json
}

data "aws_iam_policy_document" "replication_policy" {
  statement {
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]
    resources = [aws_s3_bucket.primary.arn]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging"
    ]
    resources = ["${aws_s3_bucket.primary.arn}/*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags"
    ]
    resources = ["${aws_s3_bucket.secondary.arn}/*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "kms:Decrypt"
    ]
    resources = [aws_kms_key.primary.arn]
    condition {
      test     = "StringLike"
      variable = "kms:ViaService"
      values   = ["s3.us-east-1.amazonaws.com"]
    }
  }

  statement {
    effect = "Allow"
    actions = [
      "kms:Encrypt"
    ]
    resources = [aws_kms_key.secondary.arn]
    condition {
      test     = "StringLike"
      variable = "kms:ViaService"
      values   = ["s3.us-west-2.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "replication" {
  name   = "s3-replication-policy-${data.aws_caller_identity.current.account_id}"
  policy = data.aws_iam_policy_document.replication_policy.json
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

resource "aws_s3_bucket_replication_configuration" "primary_to_secondary" {
  provider   = aws.primary
  role       = aws_iam_role.replication.arn
  bucket     = aws_s3_bucket.primary.id
  depends_on = [aws_s3_bucket_versioning.primary, aws_s3_bucket_versioning.secondary]

  rule {
    id     = "replicate-to-secondary"
    status = "Enabled"

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }
  }
}

# -----------------------------------------------------------------------------
# S3 Multi-Region Access Point (MRAP)
# -----------------------------------------------------------------------------

resource "aws_s3control_multi_region_access_point" "mrap" {
  provider = aws.secondary

  details {
    name = var.mrap_name

    region {
      bucket = aws_s3_bucket.primary.id
    }

    region {
      bucket = aws_s3_bucket.secondary.id
    }
  }
}

resource "aws_s3control_multi_region_access_point_policy" "mrap_policy" {
  provider = aws.secondary

  details {
    name = aws_s3control_multi_region_access_point.mrap.details[0].name
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Sid       = "AllowAccountGetPut"
          Effect    = "Allow"
          Principal = {
            AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
          }
          Action = [
            "s3:GetObject",
            "s3:PutObject"
          ]
          Resource = "${aws_s3control_multi_region_access_point.mrap.arn}/object/*"
        }
      ]
    })
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "mrap_alias" {
  description = "The alias of the Multi-Region Access Point"
  value       = aws_s3control_multi_region_access_point.mrap.alias
}

output "mrap_arn" {
  description = "The ARN of the Multi-Region Access Point"
  value       = aws_s3control_multi_region_access_point.mrap.arn
}

output "primary_bucket_name" {
  description = "Name of the primary bucket in us-east-1"
  value       = aws_s3_bucket.primary.id
}

output "secondary_bucket_name" {
  description = "Name of the secondary bucket in us-west-2"
  value       = aws_s3_bucket.secondary.id
}
```

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region for resources."
  default     = "us-east-1"
}

variable "namespace" {
  type        = string
  description = "Namespace (e.g. `cp` or `org`)."
  default     = "eg"
}

variable "environment" {
  type        = string
  description = "Environment (e.g. `prod`, `staging`, `dev`)."
  default     = "prod"
}

variable "stage" {
  type        = string
  description = "Stage (e.g. `prod`, `qa`)."
  default     = "core"
}

variable "name" {
  type        = string
  description = "Application or solution name."
  default     = "patch-manager"
}

variable "scan_schedule" {
  type        = string
  description = "Cron schedule expression for the scan window."
  default     = "cron(0 0 18 ? * WED *)"
}

variable "install_schedule" {
  type        = string
  description = "Cron schedule expression for the install window."
  default     = "cron(0 0 21 ? * WED *)"
}

variable "window_duration" {
  type        = number
  description = "Duration of the maintenance window in hours."
  default     = 3
}

variable "window_cutoff" {
  type        = number
  description = "Number of hours before the end of the maintenance window that SSM stops scheduling new tasks."
  default     = 1
}

variable "scan_patch_group" {
  type        = string
  description = "Patch Group tag value targeted for scanning."
  default     = "TOSCAN"
}

variable "install_patch_group" {
  type        = string
  description = "Patch Group tag value targeted for patching."
  default     = "TOPATCH"
}

variable "max_concurrency" {
  type        = string
  description = "Maximum concurrency for Run Command task."
  default     = "20"
}

variable "max_errors" {
  type        = string
  description = "Maximum errors allowed for Run Command task."
  default     = "50"
}

variable "install_reboot_option" {
  type        = string
  description = "Reboot option for the install task (RebootIfNeeded, NoReboot)."
  default     = "RebootIfNeeded"
}

variable "s3_log_prefix" {
  type        = string
  description = "S3 key prefix for Run Command output logs."
  default     = "scanning"
}

variable "create_s3_log_bucket" {
  type        = bool
  description = "Whether to create a versioned S3 bucket for task output logs."
  default     = true
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Labels & Naming
# -----------------------------------------------------------------------------
locals {
  name_prefix = lower(format("%s-%s-%s-%s", var.namespace, var.environment, var.stage, var.name))
  tags = {
    Namespace   = var.namespace
    Environment = var.environment
    Stage       = var.stage
    Name        = local.name_prefix
    ManagedBy   = "Terraform"
  }
}

# -----------------------------------------------------------------------------
# Patch Baseline & Patch Group Registrations
# -----------------------------------------------------------------------------
resource "aws_ssm_patch_baseline" "amazon_linux_2" {
  name             = "${local.name_prefix}-al2-baseline"
  description      = "Patch Baseline for Amazon Linux 2 instances"
  operating_system = "AMAZON_LINUX_2"
  compliance_level = "HIGH"

  approval_rule {
    approve_after_days = 7
    compliance_level   = "HIGH"
    enable_non_security = true

    patch_filter {
      key    = "PRODUCT"
      values = ["AmazonLinux2", "AmazonLinux2.0"]
    }

    patch_filter {
      key    = "CLASSIFICATION"
      values = ["Security", "Bugfix", "Recommended"]
    }

    patch_filter {
      key    = "SEVERITY"
      values = ["Critical", "Important", "Medium"]
    }
  }

  tags = local.tags
}

resource "aws_ssm_patch_group" "scan_group" {
  baseline_id = aws_ssm_patch_baseline.amazon_linux_2.id
  patch_group = var.scan_patch_group
}

resource "aws_ssm_patch_group" "install_group" {
  baseline_id = aws_ssm_patch_baseline.amazon_linux_2.id
  patch_group = var.install_patch_group
}

# -----------------------------------------------------------------------------
# S3 Log Bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "patch_logs" {
  count         = var.create_s3_log_bucket ? 1 : 0
  bucket        = "${local.name_prefix}-patch-logs-${data.aws_caller_identity.current.account_id}"
  force_destroy = true

  tags = local.tags
}

resource "aws_s3_bucket_versioning" "patch_logs" {
  count  = var.create_s3_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.patch_logs[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "patch_logs" {
  count  = var.create_s3_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.patch_logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "patch_logs" {
  count  = var.create_s3_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.patch_logs[0].id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "patch_logs" {
  count  = var.create_s3_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.patch_logs[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AccountReadWriteAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.patch_logs[0].arn,
          "${aws_s3_bucket.patch_logs[0].arn}/*"
        ]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# IAM Role for Maintenance Windows
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "ssm_mw_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ssm.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ssm_mw_role" {
  name               = "${local.name_prefix}-ssm-mw-role"
  assume_role_policy = data.aws_iam_policy_document.ssm_mw_assume_role.json
  tags               = local.tags
}

resource "aws_iam_role_policy_attachment" "ssm_mw_service_role" {
  role       = aws_iam_role.ssm_mw_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonSSMMaintenanceWindowRole"
}

# -----------------------------------------------------------------------------
# Maintenance Window: Scan
# -----------------------------------------------------------------------------
resource "aws_ssm_maintenance_window" "scan" {
  name        = "${local.name_prefix}-scan-window"
  description = "SSM Maintenance Window for weekly patch scanning"
  schedule    = var.scan_schedule
  duration    = var.window_duration
  cutoff      = var.window_cutoff

  allow_unassociated_targets = false
  tags                       = local.tags
}

resource "aws_ssm_maintenance_window_target" "scan_target" {
  window_id     = aws_ssm_maintenance_window.scan.id
  name          = "${local.name_prefix}-scan-target"
  description   = "Target instances tagged for patch scanning"
  resource_type = "INSTANCE"

  targets {
    key    = "tag:Patch Group"
    values = [var.scan_patch_group]
  }
}

resource "aws_ssm_maintenance_window_task" "scan_task" {
  window_id        = aws_ssm_maintenance_window.scan.id
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  priority         = 1
  service_role_arn = aws_iam_role.ssm_mw_role.arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.scan_target.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      output_s3_bucket     = var.create_s3_log_bucket ? aws_s3_bucket.patch_logs[0].id : null
      output_s3_key_prefix = var.s3_log_prefix

      parameter {
        name   = "Operation"
        values = ["Scan"]
      }

      parameter {
        name   = "RebootOption"
        values = ["NoReboot"]
      }
    }
  }
}

# -----------------------------------------------------------------------------
# Maintenance Window: Install
# -----------------------------------------------------------------------------
resource "aws_ssm_maintenance_window" "install" {
  name        = "${local.name_prefix}-install-window"
  description = "SSM Maintenance Window for weekly patch installation"
  schedule    = var.install_schedule
  duration    = var.window_duration
  cutoff      = var.window_cutoff

  allow_unassociated_targets = false
  tags                       = local.tags
}

resource "aws_ssm_maintenance_window_target" "install_target" {
  window_id     = aws_ssm_maintenance_window.install.id
  name          = "${local.name_prefix}-install-target"
  description   = "Target instances tagged for patch installation"
  resource_type = "INSTANCE"

  targets {
    key    = "tag:Patch Group"
    values = [var.install_patch_group]
  }
}

resource "aws_ssm_maintenance_window_task" "install_task" {
  window_id        = aws_ssm_maintenance_window.install.id
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  priority         = 1
  service_role_arn = aws_iam_role.ssm_mw_role.arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.install_target.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      output_s3_bucket     = var.create_s3_log_bucket ? aws_s3_bucket.patch_logs[0].id : null
      output_s3_key_prefix = var.s3_log_prefix

      parameter {
        name   = "Operation"
        values = ["Install"]
      }

      parameter {
        name   = "RebootOption"
        values = [var.install_reboot_option]
      }
    }
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "patch_baseline_id" {
  description = "The ID of the Amazon Linux 2 Patch Baseline."
  value       = aws_ssm_patch_baseline.amazon_linux_2.id
}

output "scan_maintenance_window_id" {
  description = "The ID of the scan maintenance window."
  value       = aws_ssm_maintenance_window.scan.id
}

output "install_maintenance_window_id" {
  description = "The ID of the install maintenance window."
  value       = aws_ssm_maintenance_window.install.id
}

output "s3_log_bucket_name" {
  description = "The name of the S3 log bucket created for patch manager output."
  value       = try(aws_s3_bucket.patch_logs[0].id, "")
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into."
  default     = "us-east-1"
}

variable "alert_emails" {
  type        = list(string)
  description = "List of email addresses to receive management activity alert notifications."
  default     = ["alerts@example.com"]
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# KMS Key for CloudTrail & S3
# -----------------------------------------------------------------------------
resource "aws_kms_key" "cloudtrail_key" {
  description             = "KMS key for CloudTrail and CloudTrail S3 bucket logs"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudTrail to encrypt logs"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = "arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:trail/monitor_account_activities"
          }
        }
      },
      {
        Sid    = "Allow CloudTrail to decrypt for log delivery validation"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "kms:Decrypt"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch Logs to use KMS Key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cloudtrail_key_alias" {
  name          = "alias/cloudtrail-monitor-key"
  target_key_id = aws_kms_key.cloudtrail_key.key_id
}

# -----------------------------------------------------------------------------
# KMS Key for SNS
# -----------------------------------------------------------------------------
resource "aws_kms_key" "sns_key" {
  description             = "KMS key for SNS management updates notifications"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch to use KMS Key"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sns_key_alias" {
  name          = "alias/sns-management-updates-key"
  target_key_id = aws_kms_key.sns_key.key_id
}

# -----------------------------------------------------------------------------
# S3 Bucket for CloudTrail Logs
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "cloudtrail_bucket" {
  bucket        = "cloudtrail-monitor-management-event-logs-${data.aws_caller_identity.current.account_id}"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_bucket_block" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_bucket_encryption" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudtrail_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_bucket_policy" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSCloudTrailAclCheck"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.cloudtrail_bucket.arn
        Condition = {
          StringEquals = {
            "aws:SourceArn" = "arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:trail/monitor_account_activities"
          }
        }
      },
      {
        Sid    = "AWSCloudTrailWrite"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.cloudtrail_bucket.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl"  = "bucket-owner-full-control"
            "aws:SourceArn" = "arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:trail/monitor_account_activities"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# CloudWatch Logs Group & IAM Role for CloudTrail
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "cloudtrail_logs" {
  name              = "cloudtrail_to_cloudwatch_logs"
  retention_in_days = 90
}

resource "aws_iam_role" "cloudtrail_cloudwatch_role" {
  name = "CloudTrailToCloudWatchLogsRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch_policy" {
  name = "CloudTrailCloudWatchLogsPolicy"
  role = aws_iam_role.cloudtrail_cloudwatch_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.cloudtrail_logs.arn}:*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# CloudTrail Trail
# -----------------------------------------------------------------------------
resource "aws_cloudtrail" "activity_trail" {
  name                          = "monitor_account_activities"
  s3_bucket_name                = aws_s3_bucket.cloudtrail_bucket.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  kms_key_id                    = aws_kms_key.cloudtrail_key.arn
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail_logs.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch_role.arn

  event_selector {
    read_write_type           = "All"
    include_management_events = true

    exclude_management_event_sources = [
      "kms.amazonaws.com",
      "rdsdata.amazonaws.com"
    ]
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail_bucket_policy,
    aws_iam_role_policy.cloudtrail_cloudwatch_policy
  ]
}

# -----------------------------------------------------------------------------
# SNS Topic for Management Updates
# -----------------------------------------------------------------------------
resource "aws_sns_topic" "management_updates" {
  name              = "management-updates"
  kms_master_key_id = aws_kms_key.sns_key.arn
}

resource "aws_sns_topic_policy" "management_updates_policy" {
  arn = aws_sns_topic.management_updates.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudWatchPublish"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.management_updates.arn
      }
    ]
  })
}

resource "aws_sns_topic_subscription" "email_sub" {
  for_each  = toset(var.alert_emails)
  topic_arn = aws_sns_topic.management_updates.arn
  protocol  = "email"
  endpoint  = each.value
}

# -----------------------------------------------------------------------------
# CloudWatch Metric Filters and Alarms
# -----------------------------------------------------------------------------
locals {
  alarms = {
    "security_group_changes" = {
      metric_name = "SecurityGroupChangesCount"
      pattern     = "{($.eventName = AuthorizeSecurityGroupIngress) || ($.eventName = AuthorizeSecurityGroupEgress) || ($.eventName = RevokeSecurityGroupIngress) || ($.eventName = RevokeSecurityGroupEgress) || ($.eventName = CreateSecurityGroup) || ($.eventName = DeleteSecurityGroup)}"
      description = "Alarm triggered when security group changes occur."
    }
    "iam_user_creation_or_deletion" = {
      metric_name = "IAMUserCreationDeletionCount"
      pattern     = "{($.eventName = CreateUser) || ($.eventName = DeleteUser)}"
      description = "Alarm triggered when IAM users are created or deleted."
    }
    "failed_console_logins" = {
      metric_name = "FailedConsoleLoginsCount"
      pattern     = "{($.eventName = ConsoleLogin) && ($.errorMessage = \"Failed authentication\")}"
      description = "Alarm triggered on failed AWS management console logins."
    }
    "iam_group_role_user_policy_changes" = {
      metric_name = "IAMGroupRoleUserPolicyChangesCount"
      pattern     = "{($.eventName = PutGroupPolicy) || ($.eventName = DeleteGroupPolicy) || ($.eventName = PutRolePolicy) || ($.eventName = DeleteRolePolicy) || ($.eventName = PutUserPolicy) || ($.eventName = DeleteUserPolicy)}"
      description = "Alarm triggered when inline policies on IAM groups, roles, or users are modified."
    }
    "iam_policy_changes" = {
      metric_name = "IAMPolicyChangesCount"
      pattern     = "{($.eventName = CreatePolicy) || ($.eventName = DeletePolicy) || ($.eventName = CreatePolicyVersion) || ($.eventName = DeletePolicyVersion) || ($.eventName = SetDefaultPolicyVersion)}"
      description = "Alarm triggered when customer managed IAM policies are modified or created."
    }
    "users_added_to_groups" = {
      metric_name = "UsersAddedToGroupsCount"
      pattern     = "{($.eventName = AddUserToGroup)}"
      description = "Alarm triggered when IAM users are added to groups."
    }
    "iam_role_creation_or_deletion" = {
      metric_name = "IAMRoleCreationDeletionCount"
      pattern     = "{($.eventName = CreateRole) || ($.eventName = DeleteRole)}"
      description = "Alarm triggered when IAM roles are created or deleted."
    }
  }
}

resource "aws_cloudwatch_log_metric_filter" "activity_filters" {
  for_each       = local.alarms
  name           = each.key
  pattern        = each.value.pattern
  log_group_name = aws_cloudwatch_log_group.cloudtrail_logs.name

  metric_transformation {
    name      = each.value.metric_name
    namespace = "management_activities"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "activity_alarms" {
  for_each            = local.alarms
  alarm_name          = each.key
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = each.value.metric_name
  namespace           = "management_activities"
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_description   = each.value.description
  alarm_actions       = [aws_sns_topic.management_updates.arn]

  depends_on = [
    aws_cloudwatch_log_metric_filter.activity_filters
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "cloudtrail_arn" {
  description = "The ARN of the CloudTrail trail."
  value       = aws_cloudtrail.activity_trail.arn
}

output "s3_bucket_name" {
  description = "Name of the CloudTrail S3 bucket."
  value       = aws_s3_bucket.cloudtrail_bucket.id
}

output "sns_topic_arn" {
  description = "ARN of the management updates SNS topic."
  value       = aws_sns_topic.management_updates.arn
}

output "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch Logs group receiving CloudTrail events."
  value       = aws_cloudwatch_log_group.cloudtrail_logs.name
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "rule_name_prefix" {
  description = "Optional prefix to append to the AWS Config rule name"
  type        = string
  default     = ""
}

variable "rule_enabled" {
  description = "Whether the AWS Config rule should be enabled"
  type        = bool
  default     = true
}

variable "days_to_expiration" {
  description = "The number of days before ACM certificate expiration that triggers a non-compliant status"
  type        = number
  default     = 14
}

# ---------------------------------------------------------------------------------------------------------------------
# AWS CONFIG PREREQUISITES (S3 Bucket, IAM Role, Recorder, and Delivery Channel)
# ---------------------------------------------------------------------------------------------------------------------

# S3 Bucket for AWS Config snapshots and history
resource "aws_s3_bucket" "config_bucket" {
  bucket_prefix = "aws-config-bucket-"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "config_bucket_pab" {
  bucket                  = aws_s3_bucket.config_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# IAM Role for AWS Config
resource "aws_iam_role" "config_role" {
  name_prefix = "aws-config-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "config_role_policy" {
  role       = aws_iam_role.config_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWS_ConfigRole"
}

resource "aws_iam_role_policy" "config_s3_policy" {
  name_prefix = "aws-config-s3-"
  role        = aws_iam_role.config_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:PutObject", "s3:PutObjectAcl"]
        Resource = "${aws_s3_bucket.config_bucket.arn}/AWSLogs/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      },
      {
        Effect   = "Allow"
        Action   = ["s3:GetBucketAcl"]
        Resource = aws_s3_bucket.config_bucket.arn
      }
    ]
  })
}

# AWS Config Recorder
resource "aws_config_configuration_recorder" "main" {
  name     = "default"
  role_arn = aws_iam_role.config_role.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

# AWS Config Delivery Channel
resource "aws_config_delivery_channel" "main" {
  name           = "default"
  s3_bucket_name = aws_s3_bucket.config_bucket.bucket
  depends_on     = [aws_config_configuration_recorder.main]
}

# AWS Config Recorder Status (Starts the recorder)
resource "aws_config_configuration_recorder_status" "main" {
  name       = aws_config_configuration_recorder.main.name
  is_enabled = true
  depends_on = [aws_config_delivery_channel.main]
}

# ---------------------------------------------------------------------------------------------------------------------
# AWS CONFIG MANAGED RULE: ACM Certificate Expiration Check
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_config_config_rule" "acm_certificate_expiration_check" {
  name        = "${var.rule_name_prefix}acm-certificate-expiration-check"
  description = "Checks whether ACM Certificates in the account are expired or scheduled to expire within the specified number of days."

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  input_parameters = jsonencode({
    daysToExpiration = tostring(var.days_to_expiration)
  })

  scope {
    compliance_resource_types = [
      "AWS::ACM::Certificate"
    ]
  }

  depends_on = [aws_config_configuration_recorder_status.main]
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "config_rule_id" {
  description = "The ID of the AWS Config rule"
  value       = aws_config_config_rule.acm_certificate_expiration_check.rule_id
}

output "config_rule_arn" {
  description = "The ARN of the AWS Config rule"
  value       = aws_config_config_rule.acm_certificate_expiration_check.arn
}

output "config_rule_name" {
  description = "The Name of the AWS Config rule"
  value       = aws_config_config_rule.acm_certificate_expiration_check.name
}
