terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "The AWS region where resources will be created"
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = variable "aws_region"
}

# Cognito User Pool
resource "aws_cognito_user_pool" "pool" {
  name                     = "fiap-hackathon-cognito-pool"
  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]
  mfa_configuration        = "OFF"

  password_policy {
    minimum_length                   = 8
    require_lowercase                = true
    require_numbers                  = true
    require_symbols                  = true
    require_uppercase                = true
    temporary_password_validity_days = 7
  }

  schema {
    attribute_data_type      = "String"
    name                     = "name"
    required                 = true
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "1"
      max_length = "2048"
    }
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  tags = {
    Environment = "hackathon"
    Project     = "fiap-hackathon"
  }
}

# Cognito User Pool Client
resource "aws_cognito_user_pool_client" "client" {
  name            = "cognito-pool-client"
  user_pool_id    = aws_cognito_user_pool.pool.id
  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH"
  ]

  prevent_user_existence_errors = "ENABLED"
}

# Outputs
output "cognito_user_pool_id" {
  description = "The ID of the Cognito User Pool"
  value       = aws_cognito_user_pool.pool.id
}

output "cognito_user_pool_arn" {
  description = "The ARN of the Cognito User Pool"
  value       = aws_cognito_user_pool.pool.arn
}

output "cognito_user_pool_client_id" {
  description = "The ID of the Cognito User Pool Client"
  value       = aws_cognito_user_pool_client.client.id
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "azure_tenant_id" {
  type        = string
  description = "The Azure AD tenant ID."
  default     = "221ca1d3-b3f2-4346-8abc-88f802495c7d"
}

variable "azure_client_id" {
  type        = string
  description = "The Azure AD application (client) ID / audience."
  default     = "c8b9cf86-e2b4-4428-b356-14313412a4d1"
}

variable "oidc_thumbprint" {
  type        = string
  description = "SHA-1 thumbprint for sts.windows.net certificate."
  # Microsoft STS certificate thumbprint (standard Digicert root CA thumbprint used for Azure AD)
  default     = "6828482436f564756598c919d3fca8eb9098c474"
}

variable "role_name" {
  type        = string
  description = "The name of the IAM role to be created."
  default     = "Sentinel-OIDC-Organizations-ReadOnly"
}

# -----------------------------------------------------------------------------
# IAM OpenID Connect Provider
# -----------------------------------------------------------------------------
resource "aws_iam_openid_connect_provider" "azure_ad" {
  url             = "https://sts.windows.net/${var.azure_tenant_id}/"
  client_id_list  = [var.azure_client_id]
  thumbprint_list = [var.oidc_thumbprint]

  tags = {
    Name        = "AzureAD-${var.azure_tenant_id}"
    Environment = "Production"
    ManagedBy   = "Terraform"
  }
}

# -----------------------------------------------------------------------------
# IAM Role for Sentinel OIDC Federation
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "sentinel_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.azure_ad.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "sts.windows.net/${var.azure_tenant_id}/:aud"
      values   = [var.azure_client_id]
    }
  }
}

resource "aws_iam_role" "sentinel_role" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.sentinel_assume_role.json
  description        = "IAM role assumed by Sentinel function apps using Azure AD OIDC federation."

  tags = {
    Name        = var.role_name
    Environment = "Production"
    ManagedBy   = "Terraform"
  }
}

# -----------------------------------------------------------------------------
# Policy Attachment: AWSOrganizationsReadOnlyAccess
# -----------------------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "sentinel_org_read_only" {
  role       = aws_iam_role.sentinel_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSOrganizationsReadOnlyAccess"
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "oidc_provider_arn" {
  description = "ARN of the Azure AD OIDC provider."
  value       = aws_iam_openid_connect_provider.azure_ad.arn
}

output "role_arn" {
  description = "ARN of the Sentinel Organizations ReadOnly role."
  value       = aws_iam_role.sentinel_role.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "The AWS region to deploy resources in"
  default     = "us-east-1"
}

variable "role_name" {
  type        = string
  description = "Name of the IAM role to create"
  default     = "ec2-iam-wildcard-test-role"
}

provider "aws" {
  region = var.aws_region
}

# Fetch current AWS account ID and partition for dynamic ARN construction
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# Trust policy document for EC2 assumption
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# The IAM role assumed by EC2
resource "aws_iam_role" "test_role" {
  name               = var.role_name
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Environment = "Testing"
    Purpose     = "IAMPolicyWildcardTest"
  }
}

# 1. Inline policy allowing "rds:AddRoleToDBCluster" on the specific "foo_cluster"
data "aws_iam_policy_document" "allow_specific_cluster" {
  statement {
    sid    = "AllowAddRoleToSpecificCluster"
    effect = "Allow"
    actions = [
      "rds:AddRoleToDBCluster"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:rds:${var.aws_region}:${data.aws_caller_identity.current.account_id}:cluster:foo_cluster"
    ]
  }
}

resource "aws_iam_role_policy" "allow_specific_cluster" {
  name   = "AllowSpecificClusterAddRole"
  role   = aws_iam_role.test_role.id
  policy = data.aws_iam_policy_document.allow_specific_cluster.json
}

# 2. Inline policy allowing "rds:Add*" on all RDS clusters in any region and account
data "aws_iam_policy_document" "allow_wildcard_clusters" {
  statement {
    sid    = "AllowAddWildcardAllClusters"
    effect = "Allow"
    actions = [
      "rds:Add*"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:rds:*:*:cluster:*"
    ]
  }
}

resource "aws_iam_role_policy" "allow_wildcard_clusters" {
  name   = "AllowWildcardAddOnClusters"
  role   = aws_iam_role.test_role.id
  policy = data.aws_iam_policy_document.allow_wildcard_clusters.json
}

# 3. Inline policy denying "rds:Add*" on all RDS clusters in any region and account
data "aws_iam_policy_document" "deny_wildcard_clusters" {
  statement {
    sid    = "DenyAddWildcardAllClusters"
    effect = "Deny"
    actions = [
      "rds:Add*"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:rds:*:*:cluster:*"
    ]
  }
}

resource "aws_iam_role_policy" "deny_wildcard_clusters" {
  name   = "DenyWildcardAddOnClusters"
  role   = aws_iam_role.test_role.id
  policy = data.aws_iam_policy_document.deny_wildcard_clusters.json
}

output "role_arn" {
  description = "The ARN of the created test IAM role"
  value       = aws_iam_role.test_role.arn
}

output "role_name" {
  description = "The name of the created test IAM role"
  value       = aws_iam_role.test_role.name
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "The primary AWS region for resources"
  default     = "us-east-1"
}

variable "environment" {
  type        = string
  description = "Deployment environment name for remote state bucket"
  default     = "prod"
}

provider "aws" {
  region = var.aws_region
}

# CloudFront WAFv2 must always be created in us-east-1
provider "aws" {
  alias  = "us_east_1"
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

# ==============================================================================
# KMS Keys
# ==============================================================================

# KMS Key for Frontend S3 Bucket
resource "aws_kms_key" "frontend_key" {
  description             = "KMS Key for Frontend S3 Bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name        = "frontend-s3-kms-key"
    Environment = var.environment
  }
}

resource "aws_kms_alias" "frontend_key_alias" {
  name          = "alias/frontend-s3-key"
  target_key_id = aws_kms_key.frontend_key.key_id
}

# KMS Key for Terraform Remote State S3 Bucket
resource "aws_kms_key" "state_key" {
  description             = "KMS Key for Terraform State S3 Bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name        = "terraform-state-kms-key"
    Environment = var.environment
  }
}

resource "aws_kms_alias" "state_key_alias" {
  name          = "alias/terraform-state-key"
  target_key_id = aws_kms_key.state_key.key_id
}

# ==============================================================================
# Frontend S3 Bucket Configuration
# ==============================================================================

resource "aws_s3_bucket" "frontend" {
  bucket        = "s3-frontend-nft-maker-v2-${data.aws_caller_identity.current.account_id}"
  force_destroy = true

  tags = {
    Name        = "s3-frontend-nft-maker-v2"
    Environment = var.environment
  }
}

resource "aws_s3_bucket_public_access_block" "frontend" {
  bucket                  = aws_s3_bucket.frontend.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.frontend_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_website_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "index.html"
  }
}

resource "aws_s3_bucket_cors_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST", "DELETE"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }
}

# ==============================================================================
# CloudFront & WAF Configuration
# ==============================================================================

resource "aws_cloudfront_origin_access_identity" "oai" {
  comment = "OAI for frontend S3 bucket: s3-frontend-nft-maker-v2"
}

resource "aws_s3_bucket_policy" "frontend_oai" {
  bucket = aws_s3_bucket.frontend.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudFrontOAIGetAndList"
        Effect = "Allow"
        Principal = {
          AWS = aws_cloudfront_origin_access_identity.oai.iam_arn
        }
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.frontend.arn,
          "${aws_s3_bucket.frontend.arn}/*"
        ]
      }
    ]
  })
}

# WAFv2 Web ACL for CloudFront (must be in us-east-1)
resource "aws_wafv2_web_acl" "cloudfront_waf" {
  provider    = aws.us_east_1
  name        = "frontend-cloudfront-waf-${var.environment}"
  description = "WAFv2 Web ACL for Frontend CloudFront Distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 1

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "AWSManagedRulesCommonRuleSetMetric"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "frontend-waf-metric"
    sampled_requests_enabled   = true
  }

  tags = {
    Name        = "frontend-waf-${var.environment}"
    Environment = var.environment
  }
}

resource "aws_cloudfront_distribution" "frontend" {
  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"
  price_class         = "PriceClass_200"
  web_acl_id          = aws_wafv2_web_acl.cloudfront_waf.arn

  origin {
    domain_name = aws_s3_bucket.frontend.bucket_regional_domain_name
    origin_id   = "S3Origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.oai.cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3Origin"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
    compress               = true
  }

  # Longer-lived cache behavior for /content/immutable/*
  ordered_cache_behavior {
    path_pattern     = "/content/immutable/*"
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3Origin"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 86400
    default_ttl            = 604800
    max_ttl                = 31536000
    compress               = true
  }

  # Longer-lived cache behavior for /content/*
  ordered_cache_behavior {
    path_pattern     = "/content/*"
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3Origin"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 3600
    default_ttl            = 86400
    max_ttl                = 604800
    compress               = true
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = {
    Name        = "frontend-distribution"
    Environment = var.environment
  }
}

# ==============================================================================
# Terraform Remote State Backend (S3 + DynamoDB)
# ==============================================================================

resource "aws_s3_bucket" "terraform_state" {
  bucket        = "near-frontend-${var.environment}-terraform-state-${data.aws_caller_identity.current.account_id}"
  force_destroy = false

  tags = {
    Name        = "near-frontend-${var.environment}-terraform-state"
    Environment = var.environment
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket                  = aws_s3_bucket.terraform_state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_dynamodb_table" "terraform_state_locks" {
  name         = "near-frontend-terraform-state"
  billing_mode = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = {
    Name        = "near-frontend-terraform-state"
    Environment = var.environment
  }
}

# ==============================================================================
# Outputs
# ==============================================================================

output "frontend_s3_bucket_name" {
  description = "The name of the frontend hosting S3 bucket"
  value       = aws_s3_bucket.frontend.id
}

output "cloudfront_distribution_id" {
  description = "The ID of the CloudFront distribution"
  value       = aws_cloudfront_distribution.frontend.id
}

output "cloudfront_domain_name" {
  description = "The domain name of the CloudFront distribution"
  value       = aws_cloudfront_distribution.frontend.domain_name
}

output "remote_state_s3_bucket_name" {
  description = "The name of the S3 bucket used for Terraform remote state"
  value       = aws_s3_bucket.terraform_state.id
}

output "remote_state_dynamodb_table_name" {
  description = "The name of the DynamoDB table used for Terraform state locking"
  value       = aws_dynamodb_table.terraform_state_locks.name
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the EKS cluster for resource tagging and discovery"
  type        = string
  default     = "stackx"
}

variable "base_name" {
  description = "Base naming prefix for all resources"
  type        = string
  default     = "stackx-network"
}

variable "vpc_cidr" {
  description = "Base IPv4 CIDR block for the VPC"
  type        = string
  default     = "10.1.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "IPv4 CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.1.192.0/22", "10.1.196.0/22", "10.1.200.0/22"]
}

variable "private_subnet_cidrs" {
  description = "IPv4 CIDR blocks for private workload subnets"
  type        = list(string)
  default     = ["10.1.0.0/18", "10.1.64.0/18", "10.1.128.0/18"]
}

# Optional Subnet Tiers Configuration
variable "enable_database_subnets" {
  description = "Enable dedicated database subnets and RDS subnet group"
  type        = bool
  default     = false
}

variable "database_subnet_cidrs" {
  description = "IPv4 CIDR blocks for database subnets"
  type        = list(string)
  default     = ["10.1.204.0/24", "10.1.205.0/24", "10.1.206.0/24"]
}

variable "enable_cache_subnets" {
  description = "Enable dedicated cache subnets and ElastiCache subnet group"
  type        = bool
  default     = false
}

variable "cache_subnet_cidrs" {
  description = "IPv4 CIDR blocks for cache subnets"
  type        = list(string)
  default     = ["10.1.207.0/24", "10.1.208.0/24", "10.1.209.0/24"]
}

variable "enable_internal_subnets" {
  description = "Enable isolated internal subnets with no internet egress"
  type        = bool
  default     = false
}

variable "internal_subnet_cidrs" {
  description = "IPv4 CIDR blocks for isolated internal subnets"
  type        = list(string)
  default     = ["10.1.210.0/24", "10.1.211.0/24", "10.1.212.0/24"]
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)
}

# -----------------------------------------------------------------------------
# VPC and Gateways
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name                                        = "${var.base_name}-vpc"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-igw"
  }
}

resource "aws_egress_only_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-eigw"
  }
}

# -----------------------------------------------------------------------------
# Public Subnets Tier
# -----------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count                           = length(local.azs)
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = var.public_subnet_cidrs[count.index]
  availability_zone               = local.azs[count.index]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = true
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index)

  tags = {
    Name                                        = "${var.base_name}-public-${local.azs[count.index]}"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
    "kubernetes.io/role/elb"                    = "1"
    "karpenter.sh/discovery"                    = var.cluster_name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.base_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# NAT Gateways & Elastic IPs (One per AZ)
# -----------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count  = length(local.azs)
  domain = "vpc"

  tags = {
    Name = "${var.base_name}-nat-eip-${local.azs[count.index]}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count         = length(local.azs)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.base_name}-natgw-${local.azs[count.index]}"
  }

  depends_on = [aws_internet_gateway.main]
}

# -----------------------------------------------------------------------------
# Private Workload Subnets Tier (Kubernetes & Karpenter)
# -----------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count                           = length(local.azs)
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = var.private_subnet_cidrs[count.index]
  availability_zone               = local.azs[count.index]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = true
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 10)

  tags = {
    Name                                        = "${var.base_name}-private-${local.azs[count.index]}"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
    "kubernetes.io/role/internal-elb"           = "1"
    "karpenter.sh/discovery"                    = var.cluster_name
  }
}

resource "aws_route_table" "private" {
  count  = length(local.azs)
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  route {
    ipv6_cidr_block        = "::/0"
    egress_only_gateway_id = aws_egress_only_internet_gateway.main.id
  }

  tags = {
    Name = "${var.base_name}-private-rt-${local.azs[count.index]}"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# -----------------------------------------------------------------------------
# Gateway VPC Endpoints (S3)
# -----------------------------------------------------------------------------
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.aws_region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "${var.base_name}-vpce-s3"
  }
}

# -----------------------------------------------------------------------------
# Optional Tier: Database Subnets & Subnet Group
# -----------------------------------------------------------------------------
resource "aws_subnet" "database" {
  count             = var.enable_database_subnets ? length(local.azs) : 0
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.database_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.base_name}-database-${local.azs[count.index]}"
  }
}

resource "aws_route_table" "database" {
  count  = var.enable_database_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-database-rt"
  }
}

resource "aws_route_table_association" "database" {
  count          = var.enable_database_subnets ? length(aws_subnet.database) : 0
  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.database[0].id
}

resource "aws_db_subnet_group" "main" {
  count      = var.enable_database_subnets ? 1 : 0
  name       = "${var.base_name}-db-subnet-group"
  subnet_ids = aws_subnet.database[*].id

  tags = {
    Name = "${var.base_name}-db-subnet-group"
  }
}

# -----------------------------------------------------------------------------
# Optional Tier: ElastiCache Subnets & Subnet Group
# -----------------------------------------------------------------------------
resource "aws_subnet" "cache" {
  count             = var.enable_cache_subnets ? length(local.azs) : 0
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.cache_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.base_name}-cache-${local.azs[count.index]}"
  }
}

resource "aws_route_table" "cache" {
  count  = var.enable_cache_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-cache-rt"
  }
}

resource "aws_route_table_association" "cache" {
  count          = var.enable_cache_subnets ? length(aws_subnet.cache) : 0
  subnet_id      = aws_subnet.cache[count.index].id
  route_table_id = aws_route_table.cache[0].id
}

resource "aws_elasticache_subnet_group" "main" {
  count      = var.enable_cache_subnets ? 1 : 0
  name       = "${var.base_name}-cache-subnet-group"
  subnet_ids = aws_subnet.cache[*].id

  tags = {
    Name = "${var.base_name}-cache-subnet-group"
  }
}

# -----------------------------------------------------------------------------
# Optional Tier: Isolated Internal Subnets
# -----------------------------------------------------------------------------
resource "aws_subnet" "internal" {
  count             = var.enable_internal_subnets ? length(local.azs) : 0
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.internal_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.base_name}-internal-${local.azs[count.index]}"
  }
}

resource "aws_route_table" "internal" {
  count  = var.enable_internal_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-internal-rt"
  }
}

resource "aws_route_table_association" "internal" {
  count          = var.enable_internal_subnets ? length(aws_subnet.internal) : 0
  subnet_id      = aws_subnet.internal[count.index].id
  route_table_id = aws_route_table.internal[0].id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "The IPv4 CIDR block of the VPC"
  value       = aws_vpc.main.cidr_block
}

output "vpc_ipv6_cidr_block" {
  description = "The IPv6 CIDR block assigned to the VPC"
  value       = aws_vpc.main.ipv6_cidr_block
}

output "public_subnet_ids" {
  description = "List of IDs for the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "List of IDs for the private workload subnets"
  value       = aws_subnet.private[*].id
}

output "nat_gateway_ips" {
  description = "List of Public IPs assigned to the NAT Gateways"
  value       = aws_eip.nat[*].public_ip
}

output "s3_vpc_endpoint_id" {
  description = "The ID of the S3 Gateway VPC Endpoint"
  value       = aws_vpc_endpoint.s3.id
}

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  default     = "us-east-1"
  description = "AWS region to deploy resources into"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name

  bucket_names = {
    artefacts = "benchmark-glue-artefacts-${local.account_id}"
    staging   = "benchmark-datalake-staging-${local.account_id}"
    bronze    = "benchmark-datalake-bronze-${local.account_id}"
    silver    = "benchmark-datalake-silver-${local.account_id}"
    gold      = "benchmark-datalake-gold-${local.account_id}"
    logs      = "benchmark-datalake-logs-${local.account_id}"
  }

  versioned_buckets = [
    "artefacts",
    "bronze",
    "silver",
    "gold"
  ]
}

# -----------------------------------------------------------------------------
# Customer Managed KMS Key
# -----------------------------------------------------------------------------
resource "aws_kms_key" "datalake_key" {
  description             = "KMS Key for Benchmark Data Lake and Glue Jobs"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Environment = "benchmark"
    Project     = "datalake"
  }
}

resource "aws_kms_alias" "datalake_key_alias" {
  name          = "alias/benchmark-datalake-key"
  target_key_id = aws_kms_key.datalake_key.key_id
}

# -----------------------------------------------------------------------------
# S3 Buckets
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "buckets" {
  for_each      = local.bucket_names
  bucket        = each.value
  force_destroy = true

  tags = {
    Name        = each.value
    Environment = "benchmark"
    Type        = each.key
  }
}

resource "aws_s3_bucket_versioning" "versioning" {
  for_each = toset(local.versioned_buckets)
  bucket   = aws_s3_bucket.buckets[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sse" {
  for_each = local.bucket_names
  bucket   = aws_s3_bucket.buckets[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.datalake_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "block_public" {
  for_each                = local.bucket_names
  bucket                  = aws_s3_bucket.buckets[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# Glue Artifacts Upload
# -----------------------------------------------------------------------------
resource "aws_s3_object" "script_extrai_dados" {
  bucket  = aws_s3_bucket.buckets["artefacts"].id
  key     = "glueClima/extraiDados.py"
  content = <<EOF
import sys
from awsglue.utils import getResolvedOptions

args = getResolvedOptions(sys.argv, ['JOB_NAME', 'city', 'staging_bucket', 'api_key'])
print(f"Extraction job started for city: {args['city']}")
print("Extraction completed successfully.")
EOF

  kms_key_id = aws_kms_key.datalake_key.arn
}

resource "aws_s3_object" "script_transforma_dados" {
  bucket  = aws_s3_bucket.buckets["artefacts"].id
  key     = "glueClima/transformaDados.py"
  content = <<EOF
import sys
from awsglue.utils import getResolvedOptions

args = getResolvedOptions(sys.argv, ['JOB_NAME', 'staging_bucket', 'bronze_bucket', 'silver_bucket', 'translation_key'])
print("Transformation job started with Iceberg format.")
print("Transformation completed successfully.")
EOF

  kms_key_id = aws_kms_key.datalake_key.arn
}

resource "aws_s3_object" "lib_zip" {
  bucket     = aws_s3_bucket.buckets["artefacts"].id
  key        = "glueClima/lib.zip"
  content    = "PK\x05\x06\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00"
  kms_key_id = aws_kms_key.datalake_key.arn
}

# -----------------------------------------------------------------------------
# Athena Database
# -----------------------------------------------------------------------------
resource "aws_glue_catalog_database" "silver" {
  name         = "silver"
  description  = "Athena Database for Silver tier weather data"
  location_uri = "s3://${aws_s3_bucket.buckets["silver"].id}/"
}

# -----------------------------------------------------------------------------
# IAM Role for AWS Glue
# -----------------------------------------------------------------------------
resource "aws_iam_role" "glue_service_role" {
  name = "benchmark-glue-job-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "glue.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "glue_datalake_policy" {
  name        = "benchmark-glue-datalake-access-policy"
  description = "Access policy for Glue job execution and data lake interaction"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3DataLakeAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = [for b in aws_s3_bucket.buckets : "${b.arn}/*"]
      },
      {
        Sid    = "S3BucketListing"
        Effect = "Allow"
        Action = [
          "s3:ListBucket"
        ]
        Resource = [for b in aws_s3_bucket.buckets : b.arn]
      },
      {
        Sid    = "CloudWatchLogging"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "cloudwatch:PutMetricData"
        ]
        Resource = "*"
      },
      {
        Sid    = "GlueCatalogAccess"
        Effect = "Allow"
        Action = [
          "glue:*"
        ]
        Resource = "*"
      },
      {
        Sid    = "SecretsManagerAccess"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = "*"
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.datalake_key.arn]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "glue_policy_attach" {
  role       = aws_iam_role.glue_service_role.name
  policy_arn = aws_iam_policy.glue_datalake_policy.arn
}

# -----------------------------------------------------------------------------
# AWS Glue 4.0 Jobs
# -----------------------------------------------------------------------------
resource "aws_glue_job" "extrai_dados" {
  name              = "glue-job-extrai-dados"
  role_arn          = aws_iam_role.glue_service_role.arn
  glue_version      = "4.0"
  worker_type       = "G.1X"
  number_of_workers = 20
  timeout           = 2880
  max_retries       = 0

  command {
    name            = "glueetl"
    script_location = "s3://${aws_s3_bucket.buckets["artefacts"].id}/${aws_s3_object.script_extrai_dados.key}"
    python_version  = "3"
  }

  execution_property {
    max_concurrent_runs = 2
  }

  default_arguments = {
    "--TempDir"                          = "s3://${aws_s3_bucket.buckets["logs"].id}/temporary/"
    "--job-bookmark-option"              = "job-bookmark-disable"
    "--enable-continuous-cloudwatch-log" = "true"
    "--enable-metrics"                   = "true"
  }
}

resource "aws_glue_job" "transforma_dados" {
  name              = "glue-job-transforma-dados"
  role_arn          = aws_iam_role.glue_service_role.arn
  glue_version      = "4.0"
  worker_type       = "G.1X"
  number_of_workers = 20
  timeout           = 2880
  max_retries       = 0

  command {
    name            = "glueetl"
    script_location = "s3://${aws_s3_bucket.buckets["artefacts"].id}/${aws_s3_object.script_transforma_dados.key}"
    python_version  = "3"
  }

  execution_property {
    max_concurrent_runs = 2
  }

  default_arguments = {
    "--TempDir"                          = "s3://${aws_s3_bucket.buckets["logs"].id}/temporary/"
    "--extra-py-files"                   = "s3://${aws_s3_bucket.buckets["artefacts"].id}/${aws_s3_object.lib_zip.key}"
    "--additional-python-modules"        = "pyiceberg,requests,pandas"
    "--datalake-formats"                 = "iceberg"
    "--enable-continuous-cloudwatch-log" = "true"
    "--enable-metrics"                   = "true"
  }
}

# -----------------------------------------------------------------------------
# IAM Role for Step Functions
# -----------------------------------------------------------------------------
resource "aws_iam_role" "step_functions_role" {
  name = "benchmark-sfn-glue-orchestrator-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "states.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "step_functions_policy" {
  name        = "benchmark-sfn-glue-exec-policy"
  description = "Allows Step Functions to start and monitor specific Glue jobs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageGlueJobs"
        Effect = "Allow"
        Action = [
          "glue:StartJobRun",
          "glue:GetJobRun",
          "glue:GetJobRuns",
          "glue:BatchStopJobRun"
        ]
        Resource = [
          aws_glue_job.extrai_dados.arn,
          aws_glue_job.transforma_dados.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "step_functions_attach" {
  role       = aws_iam_role.step_functions_role.name
  policy_arn = aws_iam_policy.step_functions_policy.arn
}

# -----------------------------------------------------------------------------
# AWS Step Functions State Machine
# -----------------------------------------------------------------------------
resource "aws_sfn_state_machine" "weather_pipeline" {
  name     = "weather-data-pipeline"
  role_arn = aws_iam_role.step_functions_role.arn

  definition = jsonencode({
    Comment = "Orchestration for Weather Data Lake Glue Jobs"
    StartAt = "RunExtraiDados"
    States = {
      RunExtraiDados = {
        Type     = "Task"
        Resource = "arn:aws:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.extrai_dados.name
          Arguments = {
            "--city.$"           = "States.Format('{}', 'Sao Paulo')"
            "--staging_bucket.$" = "States.Format('{}', '${aws_s3_bucket.buckets["staging"].id}')"
            "--api_key.$"        = "States.Format('{}', 'PLACEHOLDER_API_KEY')"
          }
        }
        Next = "RunTransformaDados"
      }
      RunTransformaDados = {
        Type     = "Task"
        Resource = "arn:aws:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.transforma_dados.name
          Arguments = {
            "--staging_bucket.$"  = "States.Format('{}', '${aws_s3_bucket.buckets["staging"].id}')"
            "--bronze_bucket.$"   = "States.Format('{}', '${aws_s3_bucket.buckets["bronze"].id}')"
            "--silver_bucket.$"   = "States.Format('{}', '${aws_s3_bucket.buckets["silver"].id}')"
            "--translation_key.$" = "States.Format('{}', 'PLACEHOLDER_TRANSLATION_KEY')"
          }
        }
        End = true
      }
    }
  })
}

# -----------------------------------------------------------------------------
# EventBridge Schedule & IAM Role
# -----------------------------------------------------------------------------
resource "aws_iam_role" "eventbridge_role" {
  name = "benchmark-eventbridge-sfn-trigger-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "eventbridge_sfn_policy" {
  name        = "benchmark-eventbridge-sfn-policy"
  description = "Allows EventBridge to start execution of the weather pipeline state machine"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "StartStateMachineExecution"
        Effect = "Allow"
        Action = [
          "states:StartExecution"
        ]
        Resource = [
          aws_sfn_state_machine.weather_pipeline.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eventbridge_attach" {
  role       = aws_iam_role.eventbridge_role.name
  policy_arn = aws_iam_policy.eventbridge_sfn_policy.arn
}

resource "aws_cloudwatch_event_rule" "hourly_pipeline_trigger" {
  name                = "weather-pipeline-hourly-trigger"
  description         = "Triggers the weather pipeline state machine once every hour"
  schedule_expression = "rate(1 hour)"
}

resource "aws_cloudwatch_event_target" "step_function_target" {
  rule     = aws_cloudwatch_event_rule.hourly_pipeline_trigger.name
  arn      = aws_sfn_state_machine.weather_pipeline.arn
  role_arn = aws_iam_role.eventbridge_role.arn
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "kms_key_arn" {
  value       = aws_kms_key.datalake_key.arn
  description = "ARN of the Customer Managed KMS Key"
}

output "state_machine_arn" {
  value       = aws_sfn_state_machine.weather_pipeline.arn
  description = "ARN of the Step Functions orchestration state machine"
}

output "athena_database_name" {
  value       = aws_glue_catalog_database.silver.name
  description = "Name of the Silver tier Athena Database"
}

output "bucket_names" {
  value       = { for k, v in aws_s3_bucket.buckets : k => v.id }
  description = "IDs of all created S3 data lake buckets"
}
```

` tags.

### Architecture Overview
This Terraform configuration builds an automated CI/CD pipeline for hosting and deploying a static website through Amazon CloudFront:
1. **Encryption**: A dedicated AWS KMS customer managed key (CMK) with automated key rotation is used across all buckets and pipeline operations.
2. **Storage**:
   - **Target S3 Bucket**: Hosts website static assets, prefixed with `benchmark-cicd-target-${data.aws_caller_identity.current.account_id}`.
   - **Artifacts S3 Bucket**: Stores CodePipeline artifacts. Configured to deny insecure (non-TLS) transport, encrypted with the KMS CMK, and public access blocked.
   - **Optional Logging Bucket**: Disabled by default via `enable_artifact_logging`.
3. **Distribution**: CloudFront distribution using an Origin Access Control (OAC) to securely serve files from the target S3 bucket with redirect-to-HTTPS enforced.
4. **Build (AWS CodeBuild)**:
   - Configured with a `BUILD_GENERAL1_SMALL` Linux container (`aws/codebuild/amazonlinux2-x86_64-standard:5.0`), 5-minute timeout.
   - Injected environment variables: target S3 bucket, CloudFront distribution ID, and invalidation flag.
   - Scoped IAM role granting permissions to CloudWatch logs, KMS, target and artifact S3 buckets, CloudFront invalidation creation, and SSM parameters.
5. **Orchestration (AWS CodePipeline)**:
   - Dynamic source stage supporting either GitHub v1 (OAuth token + Webhook with HMAC authentication) or GitHub v2 via AWS CodeStar connection.
   - SecureString SSM parameters for the GitHub OAuth Token and Webhook Secret created with placeholders.
   - GitHub webhook configured for `push` events filtering specifically on the target branch.
   - Build stage executing the CodeBuild project.
   - Scoped IAM role for pipeline operations.
6. **Optional Notifications**: Configurable SNS topic notifications using `aws_codestarnotifications_notification_rule` (disabled by default via `enable_pipeline_notifications`).

<iac_template>
```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ------------------------------------------------------------------------------
# Input Variables
# ------------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "The AWS region to deploy resources into."
  default     = "us-east-1"
}

variable "github_owner" {
  type        = string
  description = "GitHub repository owner/organization."
  default     = "example-owner"
}

variable "github_repo" {
  type        = string
  description = "GitHub repository name."
  default     = "example-static-site"
}

variable "github_branch" {
  type        = string
  description = "GitHub branch to trigger CI/CD pipeline."
  default     = "master"
}

variable "codestar_connection_arn" {
  type        = string
  description = "Optional CodeStar Connection ARN for GitHub v2 source. If blank, GitHub v1 (OAuth token/Webhook) is used."
  default     = ""
}

variable "invalidate_cloudfront_cache" {
  type        = bool
  description = "Whether the build job should invalidate CloudFront cache."
  default     = true
}

variable "enable_pipeline_notifications" {
  type        = bool
  description = "Enable SNS notifications for CodePipeline events."
  default     = false
}

variable "enable_artifact_logging" {
  type        = bool
  description = "Enable access logging for the pipeline artifact S3 bucket."
  default     = false
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# KMS Key for Encryption
# ------------------------------------------------------------------------------
resource "aws_kms_key" "cicd_key" {
  description             = "KMS Key for Static Site CI/CD Pipeline and S3 Buckets"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "cicd-kms-policy"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid    = "AllowServicesAccess"
        Effect = "Allow"
        Principal = {
          Service = [
            "codepipeline.amazonaws.com",
            "codebuild.amazonaws.com",
            "s3.amazonaws.com"
          ]
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "cicd_key_alias" {
  name          = "alias/cicd-static-site-key"
  target_key_id = aws_kms_key.cicd_key.key_id
}

# ------------------------------------------------------------------------------
# S3 Buckets (Target & Pipeline Artifacts)
# ------------------------------------------------------------------------------
# Target Bucket for static website files
resource "aws_s3_bucket" "target" {
  bucket        = "benchmark-cicd-target-${data.aws_caller_identity.current.account_id}"
  force_destroy = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "target_encryption" {
  bucket = aws_s3_bucket.target.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cicd_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "target_pab" {
  bucket                  = aws_s3_bucket.target.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Pipeline Artifacts Bucket
resource "aws_s3_bucket" "artifacts" {
  bucket        = "benchmark-cicd-artifacts-${data.aws_caller_identity.current.account_id}"
  force_destroy = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts_encryption" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cicd_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts_pab" {
  bucket                  = aws_s3_bucket.artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "artifacts_tls_only" {
  bucket = aws_s3_bucket.artifacts.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnforceTLSRequestsOnly"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.artifacts.arn,
          "${aws_s3_bucket.artifacts.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# Optional Access Logging Bucket for Artifacts
resource "aws_s3_bucket" "logging" {
  count         = var.enable_artifact_logging ? 1 : 0
  bucket        = "benchmark-cicd-logging-${data.aws_caller_identity.current.account_id}"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "logging_pab" {
  count                   = var.enable_artifact_logging ? 1 : 0
  bucket                  = aws_s3_bucket.logging[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "artifacts_logging" {
  count         = var.enable_artifact_logging ? 1 : 0
  bucket        = aws_s3_bucket.artifacts.id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = "artifacts-log/"
}

# ------------------------------------------------------------------------------
# CloudFront Origin Access Control & Distribution
# ------------------------------------------------------------------------------
resource "aws_cloudfront_origin_access_control" "oac" {
  name                              = "cicd-site-oac-${data.aws_caller_identity.current.account_id}"
  description                       = "OAC for static site S3 bucket"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_cloudfront_distribution" "site_distribution" {
  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"

  origin {
    domain_name              = aws_s3_bucket.target.bucket_regional_domain_name
    origin_id                = "S3Origin"
    origin_access_control_id = aws_cloudfront_origin_access_control.oac.id
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "S3Origin"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

resource "aws_s3_bucket_policy" "target_oac_policy" {
  bucket = aws_s3_bucket.target.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFrontOAC"
        Effect    = "Allow"
        Principal = { Service = "cloudfront.amazonaws.com" }
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.target.arn}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.site_distribution.arn
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# SSM Parameters for GitHub Integration (SecureString)
# ------------------------------------------------------------------------------
resource "aws_ssm_parameter" "github_token" {
  name        = "/cicd/github/token"
  description = "GitHub OAuth Personal Access Token"
  type        = "SecureString"
  value       = "CHANGE_ME_GITHUB_TOKEN"
  key_id      = aws_kms_key.cicd_key.arn

  lifecycle {
    ignore_changes = [value]
  }
}

resource "aws_ssm_parameter" "github_webhook_secret" {
  name        = "/cicd/github/webhook_secret"
  description = "Secret used for GitHub Webhook HMAC signature verification"
  type        = "SecureString"
  value       = "CHANGE_ME_WEBHOOK_SECRET_KEY"
  key_id      = aws_kms_key.cicd_key.arn

  lifecycle {
    ignore_changes = [value]
  }
}

# ------------------------------------------------------------------------------
# IAM Role & Policy for CodeBuild
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-site-builder-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Effect    = "Allow"
        Principal = { Service = "codebuild.amazonaws.com" }
      }
    ]
  })
}

resource "aws_iam_policy" "codebuild_policy" {
  name        = "codebuild-site-builder-policy"
  description = "Permissions scoped to CodeBuild logs, buckets, KMS, CloudFront, and SSM"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:${var.aws_region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/codebuild/*"
      },
      {
        Sid    = "S3TargetAndArtifactsAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.target.arn,
          "${aws_s3_bucket.target.arn}/*",
          aws_s3_bucket.artifacts.arn,
          "${aws_s3_bucket.artifacts.arn}/*"
        ]
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.cicd_key.arn
      },
      {
        Sid      = "CloudFrontInvalidation"
        Effect   = "Allow"
        Action   = ["cloudfront:CreateInvalidation"]
        Resource = aws_cloudfront_distribution.site_distribution.arn
      },
      {
        Sid    = "SSMParametersAccess"
        Effect = "Allow"
        Action = [
          "ssm:GetParameters",
          "ssm:GetParameter"
        ]
        Resource = [
          aws_ssm_parameter.github_token.arn,
          aws_ssm_parameter.github_webhook_secret.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_attach" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.codebuild_policy.arn
}

# ------------------------------------------------------------------------------
# CodeBuild Project
# ------------------------------------------------------------------------------
resource "aws_codebuild_project" "site_build" {
  name          = "static-site-build"
  description   = "Builds the static site and syncs to target S3 bucket"
  build_timeout = 5
  service_role  = aws_iam_role.codebuild_role.arn

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:5.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "TARGET_BUCKET"
      value = aws_s3_bucket.target.bucket
    }

    environment_variable {
      name  = "CLOUDFRONT_DIST_ID"
      value = aws_cloudfront_distribution.site_distribution.id
    }

    environment_variable {
      name  = "INVALIDATE_CACHE"
      value = tostring(var.invalidate_cloudfront_cache)
    }
  }

  source {
    type = "CODEPIPELINE"
    buildspec = <<-EOF
      version: 0.2
      phases:
        build:
          commands:
            - echo "Deploying static assets to s3://$${TARGET_BUCKET}"
            - aws s3 sync . "s3://$${TARGET_BUCKET}" --exclude ".git/*"
            - |
              if [ "$${INVALIDATE_CACHE}" = "true" ]; then
                echo "Invalidating CloudFront Cache for $${CLOUDFRONT_DIST_ID}..."
                aws cloudfront create-invalidation --distribution-id "$${CLOUDFRONT_DIST_ID}" --paths "/*"
              fi
      artifacts:
        files:
          - '**/*'
    EOF
  }

  encryption_key = aws_kms_key.cicd_key.arn
}

# ------------------------------------------------------------------------------
# IAM Role & Policy for CodePipeline
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codepipeline_role" {
  name = "codepipeline-site-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Effect    = "Allow"
        Principal = { Service = "codepipeline.amazonaws.com" }
      }
    ]
  })
}

resource "aws_iam_policy" "codepipeline_policy" {
  name        = "codepipeline-site-policy"
  description = "Permissions for CodePipeline to use S3, KMS, CodeBuild, and CodeStar"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ArtifactsAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:GetBucketVersioning"
        ]
        Resource = [
          aws_s3_bucket.artifacts.arn,
          "${aws_s3_bucket.artifacts.arn}/*"
        ]
      },
      {
        Sid    = "CodeBuildStart"
        Effect = "Allow"
        Action = [
          "codebuild:BatchGetBuilds",
          "codebuild:StartBuild"
        ]
        Resource = aws_codebuild_project.site_build.arn
      },
      {
        Sid    = "KMSPermissions"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.cicd_key.arn
      },
      {
        Sid       = "CodeStarConnectionAccess"
        Effect    = "Allow"
        Action    = ["codestar-connections:UseConnection"]
        Resource  = var.codestar_connection_arn != "" ? var.codestar_connection_arn : "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codepipeline_attach" {
  role       = aws_iam_role.codepipeline_role.name
  policy_arn = aws_iam_policy.codepipeline_policy.arn
}

# ------------------------------------------------------------------------------
# CodePipeline
# ------------------------------------------------------------------------------
resource "aws_codepipeline" "site_pipeline" {
  name     = "static-site-pipeline"
  role_arn = aws_iam_role.codepipeline_role.arn

  artifact_store {
    location = aws_s3_bucket.artifacts.bucket
    type     = "S3"

    encryption_key {
      id   = aws_kms_key.cicd_key.arn
      type = "KMS"
    }
  }

  stage {
    name = "Source"

    dynamic "action" {
      for_each = var.codestar_connection_arn != "" ? [1] : []
      content {
        name             = "Source"
        category         = "Source"
        owner            = "AWS"
        provider         = "CodeStarSourceConnection"
        version          = "1"
        output_artifacts = ["source_output"]

        configuration = {
          ConnectionArn    = var.codestar_connection_arn
          FullRepositoryId = "${var.github_owner}/${var.github_repo}"
          BranchName       = var.github_branch
        }
      }
    }

    dynamic "action" {
      for_each = var.codestar_connection_arn == "" ? [1] : []
      content {
        name             = "Source"
        category         = "Source"
        owner            = "ThirdParty"
        provider         = "GitHub"
        version          = "1"
        output_artifacts = ["source_output"]

        configuration = {
          Owner      = var.github_owner
          Repo       = var.github_repo
          Branch     = var.github_branch
          OAuthToken = aws_ssm_parameter.github_token.value
        }
      }
    }
  }

  stage {
    name = "Build"

    action {
      name             = "Build"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      input_artifacts  = ["source_output"]
      output_artifacts = ["build_output"]
      version          = "1"

      configuration = {
        ProjectName = aws_codebuild_project.site_build.name
      }
    }
  }
}

# ------------------------------------------------------------------------------
# GitHub Webhook (used for GitHub v1 when CodeStar connection is not provided)
# ------------------------------------------------------------------------------
resource "aws_codepipeline_webhook" "github_webhook" {
  count           = var.codestar_connection_arn == "" ? 1 : 0
  name            = "codepipeline-github-webhook"
  authentication  = "GITHUB_HMAC"
  target_action   = "Source"
  target_pipeline = aws_codepipeline.site_pipeline.name

  authentication_configuration {
    secret_token = aws_ssm_parameter.github_webhook_secret.value
  }

  filter {
    json_path    = "$.ref"
    match_equals = "refs/heads/${var.github_branch}"
  }
}

# ------------------------------------------------------------------------------
# Optional Notifications (SNS + CodeStar Notification Rule)
# ------------------------------------------------------------------------------
resource "aws_sns_topic" "pipeline_notifications" {
  count             = var.enable_pipeline_notifications ? 1 : 0
  name              = "pipeline-notifications-topic"
  kms_master_key_id = aws_kms_key.cicd_key.arn
}

resource "aws_codestarnotifications_notification_rule" "pipeline_rule" {
  count          = var.enable_pipeline_notifications ? 1 : 0
  name           = "pipeline-execution-notifications"
  detail_type    = "BASIC"
  resource       = aws_codepipeline.site_pipeline.arn
  event_type_ids = [
    "codepipeline-pipeline-pipeline-execution-failed",
    "codepipeline-pipeline-pipeline-execution-succeeded"
  ]

  target {
    address = aws_sns_topic.pipeline_notifications[0].arn
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "target_bucket_name" {
  description = "Target S3 bucket for website files"
  value       = aws_s3_bucket.target.bucket
}

output "artifact_bucket_name" {
  description = "Artifacts S3 bucket"
  value       = aws_s3_bucket.artifacts.bucket
}

output "cloudfront_distribution_domain" {
  description = "Domain name of CloudFront distribution"
  value       = aws_cloudfront_distribution.site_distribution.domain_name
}

output "codepipeline_name" {
  description = "Name of the created CodePipeline"
  value       = aws_codepipeline.site_pipeline.name
}

output "github_webhook_url" {
  description = "Webhook URL to register in GitHub repository settings"
  value       = length(aws_codepipeline_webhook.github_webhook) > 0 ? aws_codepipeline_webhook.github_webhook[0].url : "N/A - Using CodeStar Connection"
}
```

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

################################################################################
# Variables
################################################################################

variable "create_vpc" {
  description = "Controls if VPC and related resources should be created"
  type        = bool
  default     = true
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "main"
}

variable "vpc_cidr" {
  description = "The CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_tenancy" {
  description = "A tenancy option for instances launched into the VPC"
  type        = string
  default     = "default"
}

variable "enable_dns_support" {
  description = "Should be true to enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Should be true to enable DNS hostnames in the VPC"
  type        = bool
  default     = false
}

variable "single_nat_gateway" {
  description = "Should be true if you want to provision a single shared NAT Gateway across all private networks"
  type        = bool
  default     = true
}

variable "subnet_definitions" {
  description = "List of subnet group specifications (class can be public, private, or intra)"
  type = list(object({
    name                     = string
    class                    = string # "public", "private", "intra"
    cidrs_by_az              = map(string) # e.g. { "us-east-1a" = "10.0.1.0/24", "us-east-1b" = "10.0.2.0/24" }
    create_db_subnet_group   = optional(bool, false)
    create_cache_subnet_group = optional(bool, false)
  }))
  default = []
}

variable "tags" {
  description = "A map of tags to assign to resources"
  type        = map(string)
  default     = {}
}

################################################################################
# Locals
################################################################################

locals {
  # Flatten individual subnets from definitions
  subnets_flattened = flatten([
    for def in var.subnet_definitions : [
      for az, cidr in def.cidrs_by_az : {
        key                       = "${def.name}-${az}"
        name                      = def.name
        class                     = lower(def.class)
        az                        = az
        cidr                      = cidr
        create_db_subnet_group    = def.create_db_subnet_group
        create_cache_subnet_group = def.create_cache_subnet_group
      }
    ]
  ])

  subnets_map = var.create_vpc ? { for s in local.subnets_flattened : s.key => s } : {}

  # Subnets separated by class
  public_subnets  = { for k, v in local.subnets_map : k => v if v.class == "public" }
  private_subnets = { for k, v in local.subnets_map : k => v if v.class == "private" }
  intra_subnets   = { for k, v in local.subnets_map : k => v if v.class == "intra" }

  # Distinct AZs where public subnets exist
  public_azs = distinct([for s in local.public_subnets : s.az])

  # NAT Gateway config
  create_igw = var.create_vpc && length(local.public_subnets) > 0
  create_nat = var.create_vpc && length(local.public_subnets) > 0 && length(local.private_subnets) > 0

  # Map of NAT Gateways needed: either one single or one per public AZ
  nat_gateways = local.create_nat ? (
    var.single_nat_gateway ? {
      "default" = {
        az        = element(local.public_azs, 0)
        subnet_id = [for k, v in local.public_subnets : k if v.az == element(local.public_azs, 0)][0]
      }
    } : {
      for az in local.public_azs : az => {
        az        = az
        subnet_id = [for k, v in local.public_subnets : k if v.az == az][0]
      }
    }
  ) : {}

  # DB and Cache subnet definitions
  db_subnet_defs    = [for def in var.subnet_definitions : def if try(def.create_db_subnet_group, false)]
  cache_subnet_defs = [for def in var.subnet_definitions : def if try(def.create_cache_subnet_group, false)]
}

################################################################################
# VPC
################################################################################

resource "aws_vpc" "this" {
  count = var.create_vpc ? 1 : 0

  cidr_block                       = var.vpc_cidr
  instance_tenancy                 = var.instance_tenancy
  enable_dns_support               = var.enable_dns_support
  enable_dns_hostnames             = var.enable_dns_hostnames
  assign_generated_ipv6_cidr_block = false

  tags = merge(
    var.tags,
    {
      "Name" = var.vpc_name
    }
  )
}

################################################################################
# Subnets
################################################################################

resource "aws_subnet" "this" {
  for_each = local.subnets_map

  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = each.value.class == "public"

  tags = merge(
    var.tags,
    {
      "Name"  = "${var.vpc_name}-${each.value.name}-${each.value.az}"
      "Class" = each.value.class
    }
  )
}

################################################################################
# Internet Gateway
################################################################################

resource "aws_internet_gateway" "this" {
  count = local.create_igw ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    var.tags,
    {
      "Name" = "${var.vpc_name}-igw"
    }
  )
}

################################################################################
# NAT Gateway and Elastic IP
################################################################################

resource "aws_eip" "nat" {
  for_each = local.nat_gateways

  domain = "vpc"

  tags = merge(
    var.tags,
    {
      "Name" = "${var.vpc_name}-nat-${each.key}"
    }
  )

  depends_on = [aws_internet_gateway.this]
}

resource "aws_nat_gateway" "this" {
  for_each = local.nat_gateways

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.this[each.value.subnet_id].id

  tags = merge(
    var.tags,
    {
      "Name" = "${var.vpc_name}-nat-${each.key}"
    }
  )

  depends_on = [aws_internet_gateway.this]
}

################################################################################
# Route Tables & Routes
################################################################################

# Public Route Table
resource "aws_route_table" "public" {
  count = local.create_igw ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    var.tags,
    {
      "Name" = "${var.vpc_name}-public"
    }
  )
}

resource "aws_route" "public_internet" {
  count = local.create_igw ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  for_each = local.public_subnets

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public[0].id
}

# Private Route Tables
# If single_nat_gateway, create 1 route table. If multi-AZ, create 1 route table per AZ with private subnets.
locals {
  private_azs = distinct([for s in local.private_subnets : s.az])
  private_route_table_keys = length(local.private_subnets) > 0 ? (
    var.single_nat_gateway || !local.create_nat ? ["default"] : local.private_azs
  ) : []
}

resource "aws_route_table" "private" {
  for_each = toset(local.private_route_table_keys)

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    var.tags,
    {
      "Name" = "${var.vpc_name}-private-${each.key}"
    }
  )
}

resource "aws_route" "private_nat" {
  for_each = local.create_nat ? toset(local.private_route_table_keys) : []

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id = var.single_nat_gateway ? (
    aws_nat_gateway.this["default"].id
  ) : (
    contains(keys(aws_nat_gateway.this), each.key) ? aws_nat_gateway.this[each.key].id : aws_nat_gateway.this[element(keys(aws_nat_gateway.this), 0)].id
  )
}

resource "aws_route_table_association" "private" {
  for_each = local.private_subnets

  subnet_id = aws_subnet.this[each.key].id
  route_table_id = var.single_nat_gateway || !local.create_nat ? (
    aws_route_table.private["default"].id
  ) : aws_route_table.private[each.value.az].id
}

# Intra Route Table (No internet route)
resource "aws_route_table" "intra" {
  count = var.create_vpc && length(local.intra_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    var.tags,
    {
      "Name" = "${var.vpc_name}-intra"
    }
  )
}

resource "aws_route_table_association" "intra" {
  for_each = local.intra_subnets

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.intra[0].id
}

################################################################################
# Subnet Groups (RDS & ElastiCache)
################################################################################

resource "aws_db_subnet_group" "this" {
  for_each = var.create_vpc ? { for def in local.db_subnet_defs : def.name => def } : {}

  name = "${var.vpc_name}-${each.key}-db-subnet-group"
  subnet_ids = [
    for k, s in local.subnets_map : aws_subnet.this[k].id if s.name == each.key
  ]

  tags = merge(
    var.tags,
    {
      "Name" = "${var.vpc_name}-${each.key}-db-subnet-group"
    }
  )
}

resource "aws_elasticache_subnet_group" "this" {
  for_each = var.create_vpc ? { for def in local.cache_subnet_defs : def.name => def } : {}

  name = "${var.vpc_name}-${each.key}-cache-subnet-group"
  subnet_ids = [
    for k, s in local.subnets_map : aws_subnet.this[k].id if s.name == each.key
  ]

  tags = merge(
    var.tags,
    {
      "Name" = "${var.vpc_name}-${each.key}-cache-subnet-group"
    }
  )
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  description = "The ID of the VPC"
  value       = try(aws_vpc.this[0].id, null)
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC"
  value       = try(aws_vpc.this[0].cidr_block, null)
}

output "public_subnet_ids" {
  description = "List of IDs of public subnets"
  value       = [for k, v in local.public_subnets : aws_subnet.this[k].id]
}

output "private_subnet_ids" {
  description = "List of IDs of private subnets"
  value       = [for k, v in local.private_subnets : aws_subnet.this[k].id]
}

output "intra_subnet_ids" {
  description = "List of IDs of intra subnets"
  value       = [for k, v in local.intra_subnets : aws_subnet.this[k].id]
}

output "internet_gateway_id" {
  description = "The ID of the Internet Gateway"
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "nat_gateway_ids" {
  description = "List of NAT Gateway IDs"
  value       = [for ngw in aws_nat_gateway.this : ngw.id]
}

output "db_subnet_group_ids" {
  description = "Map of database subnet group IDs"
  value       = { for k, v in aws_db_subnet_group.this : k => v.id }
}

output "elasticache_subnet_group_ids" {
  description = "Map of ElastiCache subnet group IDs"
  value       = { for k, v in aws_elasticache_subnet_group.this : k => v.id }
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  description = "The AWS region where resources will be managed."
  type        = string
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# Trust policy document allowing EC2 instances to assume the role
data "aws_iam_policy_document" "ec2_assume_role_policy" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# IAM Role for EC2 Systems Manager
resource "aws_iam_role" "ec2_ssm_role" {
  name               = "ec2-ssm-association"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role_policy.json

  tags = {
    Name = "ec2-ssm-association"
  }
}

# Attach the AWS-managed AmazonSSMManagedInstanceCore policy to the role
resource "aws_iam_role_policy_attachment" "ssm_managed_instance_core" {
  role       = aws_iam_role.ec2_ssm_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# IAM Instance Profile to attach the role to EC2 instances
resource "aws_iam_instance_profile" "ec2_instance_profile" {
  name = "ec2-s3-ssm-association"
  role = aws_iam_role.ec2_ssm_role.name

  tags = {
    Name = "ec2-s3-ssm-association"
  }
}

output "iam_role_arn" {
  description = "The ARN of the IAM role."
  value       = aws_iam_role.ec2_ssm_role.arn
}

output "instance_profile_arn" {
  description = "The ARN of the IAM instance profile."
  value       = aws_iam_instance_profile.ec2_instance_profile.arn
}

output "instance_profile_name" {
  description = "The name of the IAM instance profile."
  value       = aws_iam_instance_profile.ec2_instance_profile.name
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region where resources will be deployed"
  default     = "us-east-1"
}

# Fetch current AWS account details for KMS key policy
data "aws_caller_identity" "current" {}

# Customer Managed KMS Key for SQS encryption
resource "aws_kms_key" "sqs_dlq_key" {
  description             = "KMS key used to encrypt the aggregation-lambda-dead-letter-queue"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name        = "aggregation-lambda-dlq-kms-key"
    Environment = "production"
  }
}

# Alias for the KMS Key
resource "aws_kms_alias" "sqs_dlq_key_alias" {
  name          = "alias/aggregation-lambda-dlq-key"
  target_key_id = aws_kms_key.sqs_dlq_key.key_id
}

# Dead-Letter SQS Queue
resource "aws_sqs_queue" "aggregation_lambda_dlq" {
  name                      = "aggregation-lambda-dead-letter-queue"
  message_retention_seconds = 1209600 # 14 days in seconds (14 * 24 * 60 * 60)
  kms_master_key_id         = aws_kms_key.sqs_dlq_key.arn
  kms_data_key_reuse_period_seconds = 300

  tags = {
    Name        = "aggregation-lambda-dead-letter-queue"
    Environment = "production"
  }
}

# Outputs
output "dlq_arn" {
  description = "The ARN of the dead-letter queue"
  value       = aws_sqs_queue.aggregation_lambda_dlq.arn
}

output "dlq_url" {
  description = "The URL of the dead-letter queue"
  value       = aws_sqs_queue.aggregation_lambda_dlq.url
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used to encrypt the queue"
  value       = aws_kms_key.sqs_dlq_key.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy the SQS queue."
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# Standard SQS Queue with auto-generated name and specified properties
resource "aws_sqs_queue" "standard_queue" {
  name_prefix                = "standard-queue-"
  visibility_timeout_seconds = 30
  message_retention_seconds  = 345600
  max_message_size           = 262144
  delay_seconds              = 0
  receive_wait_time_seconds  = 0
  fifo_queue                 = false

  tags = {
    Environment = "production"
    ManagedBy   = "Terraform"
