variable "aws_region" {
  type        = string
  description = "The AWS region where resources will be created."
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# Generate a random pet-name suffix
resource "random_pet" "suffix" {
  length    = 2
  separator = "-"
}

# Create the CloudWatch Log Group
resource "aws_cloudwatch_log_group" "log_group" {
  name              = "logs-${random_pet.suffix.id}"
  retention_in_days = 7
}

# IAM Policy Document restricting permissions to the specific log group
data "aws_iam_policy_document" "logs_policy_doc" {
  statement {
    sid    = "CloudWatchLogsWriteAccess"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents"
    ]
    resources = [
      aws_cloudwatch_log_group.log_group.arn,
      "${aws_cloudwatch_log_group.log_group.arn}:*"
    ]
  }
}

# Create the IAM Policy
resource "aws_iam_policy" "logs_policy" {
  name        = "logs-${random_pet.suffix.id}-policy"
  description = "IAM policy for writing log streams and events to ${aws_cloudwatch_log_group.log_group.name}"
  policy      = data.aws_iam_policy_document.logs_policy_doc.json
}

output "log_group_name" {
  description = "The name of the created CloudWatch Log Group."
  value       = aws_cloudwatch_log_group.log_group.name
}

output "log_group_arn" {
  description = "The ARN of the created CloudWatch Log Group."
  value       = aws_cloudwatch_log_group.log_group.arn
}

output "iam_policy_arn" {
  description = "The ARN of the created IAM policy."
  value       = aws_iam_policy.logs_policy.arn
}

