variable "enabled" {
  type        = bool
  description = "Flag to enable or disable SSM automation logging and document sharing restrictions"
  default     = true
}

provider "aws" {
  region = var.aws_region
}

# CloudWatch Log Group for SSM Automation executeScript logs
resource "aws_cloudwatch_log_group" "ssm_automation_scripts" {
  count             = var.enabled ? 1 : 0
  name              = "/aws/ssm/automation/executeScript"
  retention_in_days = 14

  tags = {
    ManagedBy   = "Terraform"
    Description = "Log group for Systems Manager Automation executeScript step outputs"
  }
}

# SSM Service Setting to configure script logging destination to the CloudWatch Log Group
resource "aws_ssm_service_setting" "automation_script_logging" {
  count         = var.enabled ? 1 : 0
  setting_id    = "arn:aws:ssm:${var.aws_region}:${data.aws_caller_identity.current.account_id}:servicesetting/ssm/automation/customer-script-log-group-name"
  setting_value = aws_cloudwatch_log_group.ssm_automation_scripts[0].name

  depends_on = [
    aws_cloudwatch_log_group.ssm_automation_scripts
  ]
}

# SSM Service Setting to disable public sharing of SSM documents
resource "aws_ssm_service_setting" "disable_public_document_sharing" {
  count         = var.enabled ? 1 : 0
  setting_id    = "arn:aws:ssm:${var.aws_region}:${data.aws_caller_identity.current.account_id}:servicesetting/ssm/documents/console/public-sharing-permission"
  setting_value = "Disable"
}

# Data source for current AWS account ID
data "aws_caller_identity" "current" {}

output "cloudwatch_log_group_name" {
  description = "The name of the SSM Automation executeScript log group"
  value       = var.enabled ? aws_cloudwatch_log_group.ssm_automation_scripts[0].name : null
}

output "cloudwatch_log_group_arn" {
  description = "The ARN of the SSM Automation executeScript log group"
  value       = var.enabled ? aws_cloudwatch_log_group.ssm_automation_scripts[0].arn : null
}

output "ssm_automation_script_logging_setting_status" {
  description = "Current status of the SSM Automation script logging service setting"
  value       = var.enabled ? aws_ssm_service_setting.automation_script_logging[0].status : null
}

output "ssm_public_sharing_setting_status" {
  description = "Current status of the public SSM document sharing service setting"
  value       = var.enabled ? aws_ssm_service_setting.disable_public_document_sharing[0].status : null
}
