terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy the resources"
  default     = "us-east-1"
}

# Trust policy for Lambda service
data "aws_iam_policy_document" "lambda_assume_role_policy" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

# Shared CloudWatch logging policy document
data "aws_iam_policy_document" "lambda_logging_policy_doc" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = ["arn:aws:logs:*:*:*"]
  }
}

# Shared Customer Managed Policy for Lambda logging
resource "aws_iam_policy" "lambda_logging" {
  name        = "lambda_logging"
  description = "Shared IAM policy for Lambda functions to write CloudWatch logs"
  policy      = data.aws_iam_policy_document.lambda_logging_policy_doc.json
}

# Policy Document: Create DynamoDB Backups
data "aws_iam_policy_document" "create_backup_doc" {
  statement {
    effect = "Allow"
    actions = [
      "dynamodb:CreateBackup"
    ]
    resources = ["*"]
  }
}

# IAM Policy: Create DynamoDB Backups
resource "aws_iam_policy" "create_ddb_backup_policy" {
  name        = "create_ddb_backup_policy"
  description = "IAM policy allowing creation of DynamoDB backups"
  policy      = data.aws_iam_policy_document.create_backup_doc.json
}

# IAM Role: Create DynamoDB Backup Role
resource "aws_iam_role" "create_ddb_backup_role" {
  name               = "create_ddb_backup_role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role_policy.json
}

# Attach Create Backup Policy to Role
resource "aws_iam_role_policy_attachment" "create_backup_attach" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

# Attach Shared Logging Policy to Create Backup Role
resource "aws_iam_role_policy_attachment" "create_backup_logging_attach" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

# Policy Document: Remove/List DynamoDB Backups
data "aws_iam_policy_document" "remove_backup_doc" {
  statement {
    effect = "Allow"
    actions = [
      "dynamodb:ListBackups",
      "dynamodb:DeleteBackup"
    ]
    resources = ["*"]
  }
}

# IAM Policy: Remove DynamoDB Backups
resource "aws_iam_policy" "remove_ddb_backup_policy" {
  name        = "remove_ddb_backup_policy"
  description = "IAM policy allowing listing and deleting of DynamoDB backups"
  policy      = data.aws_iam_policy_document.remove_backup_doc.json
}

# IAM Role: Remove DynamoDB Backup Role
resource "aws_iam_role" "remove_ddb_backup_role" {
  name               = "remove_ddb_backup_role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role_policy.json
}

# Attach Remove Backup Policy to Role
resource "aws_iam_role_policy_attachment" "remove_backup_attach" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup_policy.arn
}

# Attach Shared Logging Policy to Remove Backup Role
resource "aws_iam_role_policy_attachment" "remove_backup_logging_attach" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

# Outputs
output "create_ddb_backup_role_arn" {
  description = "The ARN of the create_ddb_backup_role"
  value       = aws_iam_role.create_ddb_backup_role.arn
}

output "create_ddb_backup_role_name" {
  description = "The name of the create_ddb_backup_role"
  value       = aws_iam_role.create_ddb_backup_role.name
}

output "remove_ddb_backup_role_arn" {
  description = "The ARN of the remove_ddb_backup_role"
  value       = aws_iam_role.remove_ddb_backup_role.arn
}

output "remove_ddb_backup_role_name" {
  description = "The name of the remove_ddb_backup_role"
  value       = aws_iam_role.remove_ddb_backup_role.name
}

