terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region to deploy resources into."
  type        = string
  default     = "us-east-1"
}

variable "github_oidc_url" {
  description = "The URL of the GitHub Actions OIDC identity provider."
  type        = string
  default     = "https://token.actions.githubusercontent.com"
}

variable "client_id_list" {
  description = "List of audience (client ID) values for GitHub Actions."
  type        = list(string)
  default     = ["sts.amazonaws.com"]
}

variable "roles" {
  description = <<-EOT
    Map of optional GitHub Actions federated IAM roles to create.
    Example:
    {
      "my-github-role" = {
        description        = "Role assumed by CI/CD"
        subjects           = ["repo:my-org/my-repo:ref:refs/heads/main"]
        policy_arns        = ["arn:aws:iam::aws:policy/ReadOnlyAccess"]
        max_session_duration = 3600
      }
    }
  EOT
  type = map(object({
    description          = optional(string, "IAM Role assumed by GitHub Actions")
    subjects             = list(string)
    policy_arns          = optional(list(string), [])
    max_session_duration = optional(number, 3600)
  }))
  default = {}
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES & THUMBPRINT RETRIEVAL
# ---------------------------------------------------------------------------------------------------------------------

# Fetch the remote certificate thumbprint from GitHub's OIDC issuer
data "tls_certificate" "github" {
  url = var.github_oidc_url
}

locals {
  # GitHub's published standard thumbprints
  github_published_thumbprints = [
    "6938fd4d98bab03faadb97b34396831e3780aea1",
    "1c58a3a8518e8759bf075b76b750d4f2df264fcd"
  ]

  # Dynamic thumbprints extracted from TLS certificate chain
  dynamic_thumbprints = [for cert in data.tls_certificate.github.certificates : cert.sha1_fingerprint]

  # Combine and deduplicate
  all_thumbprints = distinct(concat(local.dynamic_thumbprints, local.github_published_thumbprints))
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM OIDC PROVIDER
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_iam_openid_connect_provider" "github_actions" {
  url             = var.github_oidc_url
  client_id_list  = var.client_id_list
  thumbprint_list = local.all_thumbprints

  tags = {
    Name = "github-actions-oidc"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# OPTIONAL IAM ROLES
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "github_actions_assume_role" {
  for_each = var.roles

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github_actions.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = var.client_id_list
    }

    condition {
      test     = "StringLike"
      variable = "token.actions.githubusercontent.com:sub"
      values   = each.value.subjects
    }
  }
}

resource "aws_iam_role" "github_actions_role" {
  for_each = var.roles

  name                 = each.key
  description          = each.value.description
  assume_role_policy   = data.aws_iam_policy_document.github_actions_assume_role[each.key].json
  max_session_duration = each.value.max_session_duration

  tags = {
    Name      = each.key
    ManagedBy = "Terraform"
  }
}

locals {
  # Flatten role and policy ARN combinations for attachments
  role_policy_attachments = flatten([
    for role_name, role_config in var.roles : [
      for policy_arn in role_config.policy_arns : {
        role_name  = role_name
        policy_arn = policy_arn
        key        = "${role_name}-${policy_arn}"
      }
    ]
  ])
}

resource "aws_iam_role_policy_attachment" "github_actions_attachments" {
  for_each = { for item in local.role_policy_attachments : item.key => item }

  role       = aws_iam_role.github_actions_role[each.value.role_name].name
  policy_arn = each.value.policy_arn
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "openid_connect_provider_arn" {
  description = "The ARN of the GitHub Actions IAM OpenID Connect provider."
  value       = aws_iam_openid_connect_provider.github_actions.arn
}

output "openid_connect_provider_url" {
  description = "The URL of the GitHub Actions IAM OpenID Connect provider."
  value       = aws_iam_openid_connect_provider.github_actions.url
}

output "openid_connect_provider_thumbprints" {
  description = "The list of thumbprints associated with the OIDC provider."
  value       = aws_iam_openid_connect_provider.github_actions.thumbprint_list
}

output "role_arns" {
  description = "ARNs of the created federated IAM roles (if any)."
  value       = { for k, v in aws_iam_role.github_actions_role : k => v.arn }
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region for resources"
  default     = "us-east-1"
}

# 1. VPC
resource "aws_vpc" "projectvpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "projectvpc"
  }
}

# 2. Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.projectvpc.id

  tags = {
    Name = "projectvpc-igw"
  }
}

# 3. Public Subnet (in the first AZ of us-east-1)
resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.projectvpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "${var.aws_region}a"
  map_public_ip_on_launch = true

  tags = {
    Name = "projectvpc-public-subnet"
  }
}

# 4. Private Subnet (in the second AZ of us-east-1)
resource "aws_subnet" "private_subnet" {
  vpc_id            = aws_vpc.projectvpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "${var.aws_region}b"

  tags = {
    Name = "projectvpc-private-subnet"
  }
}

# 5. Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.igw]

  tags = {
    Name = "projectvpc-nat-eip"
  }
}

# 6. NAT Gateway (placed in public subnet)
resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public_subnet.id

  tags = {
    Name = "projectvpc-nat-gw"
  }

  depends_on = [aws_internet_gateway.igw]
}

# 7. Route Table for Public Subnet (routes to IGW)
resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.projectvpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "projectvpc-public-rt"
  }
}

resource "aws_route_table_association" "public_assoc" {
  subnet_id      = aws_subnet.public_subnet.id
  route_table_id = aws_route_table.public_rt.id
}

# 8. Route Table for Private Subnet (routes to NAT Gateway)
resource "aws_route_table" "private_rt" {
  vpc_id = aws_vpc.projectvpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "projectvpc-private-rt"
  }
}

resource "aws_route_table_association" "private_assoc" {
  subnet_id      = aws_subnet.private_subnet.id
  route_table_id = aws_route_table.private_rt.id
}

# Outputs
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.projectvpc.id
}

output "public_subnet_id" {
  description = "The ID of the public subnet"
  value       = aws_subnet.public_subnet.id
}

output "private_subnet_id" {
  description = "The ID of the private subnet"
  value       = aws_subnet.private_subnet.id
}

output "nat_gateway_ip" {
  description = "The public IP of the NAT Gateway"
  value       = aws_eip.nat.public_ip
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "The AWS region where resources will be provisioned."
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "The CIDR block for the VPC."
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  type        = list(string)
  description = "List of CIDR blocks for the public subnets."
  default     = ["10.0.101.0/24", "10.0.102.0/24", "10.0.103.0/24"]
}

variable "private_subnet_cidrs" {
  type        = list(string)
  description = "List of CIDR blocks for the private subnets."
  default     = ["10.0.11.0/24", "10.0.12.0/24", "10.0.13.0/24"]
}

# Fetch available Availability Zones in the region
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "demo_vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name        = "demo-vpc"
    Environment = "development"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.demo_vpc.id

  tags = {
    Name        = "demo-vpc-igw"
    Environment = "development"
  }
}

# Public Subnets (placed in 2nd, 3rd, and 4th AZs: index 1, 2, 3)
resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.demo_vpc.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index + 1]
  map_public_ip_on_launch = true

  tags = {
    Name        = "demo-vpc-public-subnet-${count.index + 1}"
    Environment = "development"
    Type        = "public"
  }
}

# Private Subnets (placed in 2nd, 3rd, and 4th AZs: index 1, 2, 3)
resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.demo_vpc.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index + 1]

  tags = {
    Name        = "demo-vpc-private-subnet-${count.index + 1}"
    Environment = "development"
    Type        = "private"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.igw]

  tags = {
    Name        = "demo-vpc-nat-eip"
    Environment = "development"
  }
}

# NAT Gateway in the first public subnet
resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name        = "demo-vpc-nat-gw"
    Environment = "development"
  }

  depends_on = [aws_internet_gateway.igw]
}

# Route Table for Public Subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.demo_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name        = "demo-vpc-public-rt"
    Environment = "development"
  }
}

# Associate Public Subnets with Public Route Table
resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Route Table for Private Subnets
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.demo_vpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name        = "demo-vpc-private-rt"
    Environment = "development"
  }
}

# Associate Private Subnets with Private Route Table
resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Outputs
output "vpc_id" {
  description = "The ID of the VPC."
  value       = aws_vpc.demo_vpc.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "nat_gateway_ip" {
  description = "The public IP address of the NAT Gateway."
  value       = aws_eip.nat.public_ip
}
