terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

# Trust policy document for EC2 service
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# Common permissions policy document allowing EC2 describe actions
data "aws_iam_policy_document" "ec2_describe" {
  statement {
    effect    = "Allow"
    actions   = ["ec2:Describe*"]
    resources = ["*"]
  }
}

# IAM Roles
resource "aws_iam_role" "test_role" {
  name               = "test-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

resource "aws_iam_role" "test_role2" {
  name               = "test-role2"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
}

# Customer-Managed IAM Policies
resource "aws_iam_policy" "test_policy" {
  name        = "test-policy"
  description = "Allows EC2 describe actions"
  policy      = data.aws_iam_policy_document.ec2_describe.json
}

resource "aws_iam_policy" "test_policy2" {
  name        = "test-policy2"
  description = "Allows EC2 describe actions"
  policy      = data.aws_iam_policy_document.ec2_describe.json
}

resource "aws_iam_policy" "test_policy3" {
  name        = "test-policy3"
  description = "Allows EC2 describe actions"
  policy      = data.aws_iam_policy_document.ec2_describe.json
}

# Attach test-policy to test-role
resource "aws_iam_role_policy_attachment" "role1_policy1" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.test_policy.arn
}

# Attach test-policy to test-role2
resource "aws_iam_role_policy_attachment" "role2_policy1" {
  role       = aws_iam_role.test_role2.name
  policy_arn = aws_iam_policy.test_policy.arn
}

# Attach test-policy2 to test-role
resource "aws_iam_role_policy_attachment" "role1_policy2" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.test_policy2.arn
}

# Attach test-policy2 to test-role2
resource "aws_iam_role_policy_attachment" "role2_policy2" {
  role       = aws_iam_role.test_role2.name
  policy_arn = aws_iam_policy.test_policy2.arn
}

# Single named policy attachment attaching test-policy3 to both roles
resource "aws_iam_policy_attachment" "test_attachment5" {
  name       = "test-attachment5"
  roles      = [aws_iam_role.test_role.name, aws_iam_role.test_role2.name]
  policy_arn = aws_iam_policy.test_policy3.arn
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "The AWS region where resources are managed."
  default     = "us-east-1"
}

variable "role_name" {
  type        = string
  description = "The name of the IAM role to create for GitHub Actions."
  default     = "github-actions-oidc-role"
}

variable "role_description" {
  type        = string
  description = "The description of the IAM role."
  default     = "IAM role assumed by GitHub Actions via OIDC federation."
}

variable "repository_patterns" {
  type        = list(string)
  description = "A list of GitHub repository subject patterns allowed to assume this role (e.g., 'repo:my-org/my-repo:*', 'repo:my-org/my-repo:ref:refs/heads/main')."
  default     = []
}

variable "managed_policy_arns" {
  type        = list(string)
  description = "List of IAM managed policy ARNs to attach to the role."
  default     = []
}

variable "tags" {
  type        = map(string)
  description = "A map of tags to assign to the resources."
  default     = {}
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# GitHub OIDC Identity Provider
# -----------------------------------------------------------------------------
# Official thumbprints for token.actions.githubusercontent.com
resource "aws_iam_openid_connect_provider" "github" {
  url             = "https://token.actions.githubusercontent.com"
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = [
    "6938fd4d98bab03faadb97b34396831e3780aea1",
    "1c58a3a8518e8759bf075b76b750d4f8d264fcd9"
  ]

  tags = var.tags
}

# -----------------------------------------------------------------------------
# Trust Policy Document
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "github_actions_assume_role_policy" {
  statement {
    sid     = "GitHubActionsOIDC"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    # Audience condition
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    # Issuer / Subject condition
    # If patterns are provided, match them with StringLike; otherwise use StringEquals
    dynamic "condition" {
      for_each = length(var.repository_patterns) > 0 ? [1] : []
      content {
        test     = "StringLike"
        variable = "token.actions.githubusercontent.com:sub"
        values   = var.repository_patterns
      }
    }
  }
}

# -----------------------------------------------------------------------------
# IAM Role
# -----------------------------------------------------------------------------
resource "aws_iam_role" "github_actions" {
  name                  = var.role_name
  path                  = "/"
  description           = var.role_description
  assume_role_policy    = data.aws_iam_policy_document.github_actions_assume_role_policy.json
  force_detach_policies = true
  managed_policy_arns   = var.managed_policy_arns

  tags = var.tags
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "arn" {
  description = "The Amazon Resource Name (ARN) of the IAM role."
  value       = aws_iam_role.github_actions.arn
}

output "name" {
  description = "The name of the IAM role."
  value       = aws_iam_role.github_actions.name
}

output "path" {
  description = "The path of the IAM role."
  value       = aws_iam_role.github_actions.path
}

output "unique_id" {
  description = "The stable and unique string identifying the IAM role."
  value       = aws_iam_role.github_actions.unique_id
}
```

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "The AWS region to deploy resources into."
  default     = "us-east-1"
}

data "aws_iam_policy_document" "force_mfa_policy_doc" {
  # 1. Allow users to view basic account information
  statement {
    sid    = "AllowViewAccountInfo"
    effect = "Allow"
    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:ListAccountAliases",
      "iam:ListVirtualMFADevices"
    ]
    resources = ["*"]
  }

  # 2. Allow users to manage their own password
  statement {
    sid    = "AllowManageOwnPassword"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser"
    ]
    resources = ["arn:aws:iam::*:user/$${aws:username}"]
  }

  # 3. Allow users to create and manage their own Virtual MFA Device
  statement {
    sid    = "AllowManageOwnVirtualMFADevice"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeleteVirtualMFADevice"
    ]
    resources = ["arn:aws:iam::*:mfa/$${aws:username}"]
  }

  # 4. Allow users to manage their own MFA associations (enable/sync)
  statement {
    sid    = "AllowManageOwnUserMFA"
    effect = "Allow"
    actions = [
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice"
    ]
    resources = ["arn:aws:iam::*:user/$${aws:username}"]
  }

  # 5. Allow deactivating MFA or accessing additional self-management only when MFA is present
  statement {
    sid    = "AllowDeactivateMFADeviceOnlyWithMFA"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice"
    ]
    resources = [
      "arn:aws:iam::*:mfa/$${aws:username}",
      "arn:aws:iam::*:user/$${aws:username}"
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  # 6. Block all other IAM self-management actions if MFA is not authenticated
  statement {
    sid    = "DenyAllExceptListedIfNoMFA"
    effect = "Deny"
    not_actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
      "iam:ChangePassword",
      "iam:GetUser",
      "iam:GetAccountPasswordPolicy",
      "iam:ListAccountAliases",
      "iam:ListVirtualMFADevices"
    ]
    resources = ["arn:aws:iam::*:user/$${aws:username}"]
    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_policy" "force_mfa_policy" {
  name        = "managed-force-mfa-policy"
  path        = "/"
  description = "Allows IAM users to view basic account info and manage MFA/passwords, enforcing MFA where required."
  policy      = data.aws_iam_policy_document.force_mfa_policy_doc.json

  tags = {
    Name = "managed-force-mfa-policy"
  }
}

output "policy_arn" {
  description = "The ARN of the created IAM force MFA policy."
  value       = aws_iam_policy.force_mfa_policy.arn
}

output "policy_id" {
  description = "The ID of the created IAM force MFA policy."
  value       = aws_iam_policy.force_mfa_policy.id
}
```

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "The AWS region where resources will be provisioned."
  default     = "us-east-1"
}

# -----------------------------------------------------------------------------
# IAM Groups
# -----------------------------------------------------------------------------
resource "aws_iam_group" "billing_group" {
  name = "BillingGroup"
}

resource "aws_iam_group" "admin_group" {
  name = "AdminGroup"
}

resource "aws_iam_group" "suport_group" {
  name = "SuportGroup"
}

# -----------------------------------------------------------------------------
# IAM Policies
# -----------------------------------------------------------------------------

# Custom Billing Policy: Read-only billing, usage, budget, cost report, and pricing visibility
resource "aws_iam_policy" "billing_policy" {
  name        = "BillingPolicy"
  description = "Read-only access to billing, budgets, cost explorer, usage, and pricing."
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "BillingReadOnlyAccess"
        Effect   = "Allow"
        Action   = [
          "aws-portal:ViewBilling",
          "aws-portal:ViewUsage",
          "billing:Get*",
          "billing:List*",
          "budgets:View*",
          "budgets:Describe*",
          "ce:Get*",
          "ce:Describe*",
          "ce:List*",
          "cur:DescribeReportDefinitions",
          "pricing:DescribeServices",
          "pricing:GetAttributeValues",
          "pricing:GetProducts"
        ]
        Resource = "*"
      }
    ]
  })
}

# Custom Support Policy: Read-only access to EC2, S3, CloudWatch, and RDS
resource "aws_iam_policy" "suport_policy" {
  name        = "SuportPolicy"
  description = "Read-only access to EC2, S3, CloudWatch, and RDS."
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "SupportReadOnlyAccess"
        Effect   = "Allow"
        Action   = [
          "ec2:Describe*",
          "ec2:Get*",
          "s3:Get*",
          "s3:List*",
          "cloudwatch:Describe*",
          "cloudwatch:Get*",
          "cloudwatch:List*",
          "logs:Describe*",
          "logs:Get*",
          "logs:FilterLogEvents",
          "rds:Describe*",
          "rds:List*"
        ]
        Resource = "*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# IAM Policy Attachments to Groups
# -----------------------------------------------------------------------------
resource "aws_iam_group_policy_attachment" "billing_attachment" {
  group      = aws_iam_group.billing_group.name
  policy_arn = aws_iam_policy.billing_policy.arn
}

resource "aws_iam_group_policy_attachment" "admin_attachment" {
  group      = aws_iam_group.admin_group.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_group_policy_attachment" "suport_attachment" {
  group      = aws_iam_group.suport_group.name
  policy_arn = aws_iam_policy.suport_policy.arn
}

# -----------------------------------------------------------------------------
# IAM Users
# -----------------------------------------------------------------------------
resource "aws_iam_user" "billing_user" {
  name          = "Billing"
  force_destroy = true
}

resource "aws_iam_user" "admin_user" {
  name          = "Admin"
  force_destroy = true
}

resource "aws_iam_user" "suport_user" {
  name          = "Suport"
  force_destroy = true
}

# -----------------------------------------------------------------------------
# User Group Memberships
# -----------------------------------------------------------------------------
resource "aws_iam_user_group_membership" "billing_user_group" {
  user   = aws_iam_user.billing_user.name
  groups = [aws_iam_group.billing_group.name]
}

resource "aws_iam_user_group_membership" "admin_user_group" {
  user   = aws_iam_user.admin_user.name
  groups = [aws_iam_group.admin_group.name]
}

resource "aws_iam_user_group_membership" "suport_user_group" {
  user   = aws_iam_user.suport_user.name
  groups = [aws_iam_group.suport_group.name]
}

# -----------------------------------------------------------------------------
# Passwords and Login Profiles
# -----------------------------------------------------------------------------
resource "random_password" "billing_password" {
  length           = 8
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "random_password" "admin_password" {
  length           = 8
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "random_password" "suport_password" {
  length           = 8
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_iam_user_login_profile" "billing_login" {
  user                    = aws_iam_user.billing_user.name
  password_reset_required = true
  password_length_decrement = 0

  lifecycle {
    ignore_changes = [password_reset_required]
  }

  depends_on = [random_password.billing_password]
}

# Set the password using user login profile with explicit password
resource "aws_iam_user_login_profile" "billing_login_profile" {
  user                    = aws_iam_user.billing_user.name
  password                = random_password.billing_password.result
  password_reset_required = true
}

resource "aws_iam_user_login_profile" "admin_login_profile" {
  user                    = aws_iam_user.admin_user.name
  password                = random_password.admin_password.result
  password_reset_required = true
}

resource "aws_iam_user_login_profile" "suport_login_profile" {
  user                    = aws_iam_user.suport_user.name
  password                = random_password.suport_password.result
  password_reset_required = true
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "billing_user_credentials" {
  description = "Credentials for Billing user"
  sensitive   = true
  value = {
    username = aws_iam_user.billing_user.name
    password = random_password.billing_password.result
  }
}

output "admin_user_credentials" {
  description = "Credentials for Admin user"
  sensitive   = true
  value = {
    username = aws_iam_user.admin_user.name
    password = random_password.admin_password.result
  }
}

output "suport_user_credentials" {
  description = "Credentials for Suport user"
  sensitive   = true
  value = {
    username = aws_iam_user.suport_user.name
    password = random_password.suport_password.result
  }
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "The AWS region to deploy the EFS file system in."
  default     = "us-east-1"
}

variable "name" {
  type        = string
  description = "Name tag for the EFS file system."
  default     = "testing-efs-storage"
}

provider "aws" {
  region = var.aws_region
}

# Generate a unique token for the EFS creation token
resource "random_id" "efs_token" {
  byte_length = 8
  prefix      = "efs-"
}

# Amazon EFS File System
resource "aws_efs_file_system" "this" {
  creation_token   = random_id.efs_token.hex
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"
  encrypted        = true

  tags = {
    Name        = var.name
    Environment = "testing"
  }
}

# EFS Backup Policy to enable automatic backups
resource "aws_efs_backup_policy" "policy" {
  file_system_id = aws_efs_file_system.this.id

  backup_policy {
    status = "ENABLED"
  }
}

output "efs_file_system_id" {
  description = "The ID of the created EFS file system."
  value       = aws_efs_file_system.this.id
}

output "efs_file_system_arn" {
  description = "The ARN of the created EFS file system."
  value       = aws_efs_file_system.this.arn
}

output "efs_dns_name" {
  description = "The DNS name of the created EFS file system."
  value       = aws_efs_file_system.this.dns_name
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

variable "nlp_pipeline_bucket_name" {
  type        = string
  description = "The S3 bucket name used for the NLP pipeline data"
  default     = "nlp-pipeline-bucket"
}

variable "nlp_results_table_name" {
  type        = string
  description = "DynamoDB table name storing NLP results"
  default     = "NLPResults"
}

variable "state_machine_name" {
  type        = string
  description = "Name of the Step Functions state machine"
  default     = "YourStateMachineName"
}

provider "aws" {
  region = var.aws_region
}

# Data sources for account and region discovery
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ==============================================================================
# KMS Key for Terraform Remote State Encryption
# ==============================================================================
resource "aws_kms_key" "terraform_state_key" {
  description             = "KMS Key for Terraform remote state S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name    = "terraform-state-key"
    Purpose = "Terraform Remote State Encryption"
  }
}

resource "aws_kms_alias" "terraform_state_key_alias" {
  name          = "alias/terraform-state-key"
  target_key_id = aws_kms_key.terraform_state_key.key_id
}

# ==============================================================================
# S3 Bucket for Terraform Remote State
# ==============================================================================
resource "aws_s3_bucket" "terraform_state" {
  bucket        = "my-terraform-state-bucket-${data.aws_caller_identity.current.account_id}"
  force_destroy = false

  tags = {
    Name    = "my-terraform-state-bucket-${data.aws_caller_identity.current.account_id}"
    Purpose = "Terraform State Storage"
  }
}

resource "aws_s3_bucket_versioning" "terraform_state_versioning" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state_encryption" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.terraform_state_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state_block_public" {
  bucket                  = aws_s3_bucket.terraform_state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ==============================================================================
# DynamoDB Lock Table for Terraform Remote State
# ==============================================================================
resource "aws_dynamodb_table" "terraform_locks" {
  name         = "terraform-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  tags = {
    Name    = "terraform-locks"
    Purpose = "Terraform State Locking"
  }
}

# ==============================================================================
# 1. Glue Service Role
# ==============================================================================
data "aws_iam_policy_document" "glue_assume_role_policy" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["glue.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "glue_service_role" {
  name               = "glue-service-role"
  assume_role_policy = data.aws_iam_policy_document.glue_assume_role_policy.json

  tags = {
    Name    = "glue-service-role"
    Service = "AWS Glue"
  }
}

resource "aws_iam_role_policy_attachment" "glue_service_role_managed" {
  role       = aws_iam_role.glue_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSGlueServiceRole"
}

data "aws_iam_policy_document" "glue_s3_policy" {
  statement {
    sid    = "GlueS3Access"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject"
    ]
    resources = [
      "arn:aws:s3:::${var.nlp_pipeline_bucket_name}/*"
    ]
  }
}

resource "aws_iam_role_policy" "glue_s3_inline_policy" {
  name   = "GlueS3ObjectAccessPolicy"
  role   = aws_iam_role.glue_service_role.id
  policy = data.aws_iam_policy_document.glue_s3_policy.json
}

# ==============================================================================
# 2. Comprehend Service Role
# ==============================================================================
data "aws_iam_policy_document" "comprehend_assume_role_policy" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["comprehend.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "comprehend_service_role" {
  name               = "comprehend-service-role"
  assume_role_policy = data.aws_iam_policy_document.comprehend_assume_role_policy.json

  tags = {
    Name    = "comprehend-service-role"
    Service = "Amazon Comprehend"
  }
}

data "aws_iam_policy_document" "comprehend_s3_policy" {
  statement {
    sid    = "ComprehendS3Access"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject"
    ]
    resources = [
      "arn:aws:s3:::${var.nlp_pipeline_bucket_name}/*"
    ]
  }
}

resource "aws_iam_role_policy" "comprehend_s3_inline_policy" {
  name   = "ComprehendS3ObjectAccessPolicy"
  role   = aws_iam_role.comprehend_service_role.id
  policy = data.aws_iam_policy_document.comprehend_s3_policy.json
}

# ==============================================================================
# 3. Lambda Execution Role
# ==============================================================================
data "aws_iam_policy_document" "lambda_assume_role_policy" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_execution_role" {
  name               = "lambda-execution-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role_policy.json

  tags = {
    Name    = "lambda-execution-role"
    Service = "AWS Lambda"
  }
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

data "aws_iam_policy_document" "lambda_pipeline_policy" {
  statement {
    sid    = "S3Access"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject"
    ]
    resources = [
      "arn:aws:s3:::${var.nlp_pipeline_bucket_name}/*"
    ]
  }

  statement {
    sid    = "DynamoDBWriteAccess"
    effect = "Allow"
    actions = [
      "dynamodb:PutItem",
      "dynamodb:UpdateItem",
      "dynamodb:BatchWriteItem"
    ]
    resources = [
      "arn:aws:dynamodb:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:table/${var.nlp_results_table_name}"
    ]
  }

  statement {
    sid    = "StepFunctionsStartExecution"
    effect = "Allow"
    actions = [
      "states:StartExecution"
    ]
    resources = [
      "arn:aws:states:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:stateMachine:${var.state_machine_name}"
    ]
  }
}

resource "aws_iam_role_policy" "lambda_pipeline_inline_policy" {
  name   = "LambdaPipelineAccessPolicy"
  role   = aws_iam_role.lambda_execution_role.id
  policy = data.aws_iam_policy_document.lambda_pipeline_policy.json
}

# ==============================================================================
# 4. Step Functions Service Role
# ==============================================================================
data "aws_iam_policy_document" "step_functions_assume_role_policy" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["states.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "step_functions_service_role" {
  name               = "step-functions-service-role"
  assume_role_policy = data.aws_iam_policy_document.step_functions_assume_role_policy.json

  tags = {
    Name    = "step-functions-service-role"
    Service = "AWS Step Functions"
  }
}

data "aws_iam_policy_document" "step_functions_pipeline_policy" {
  statement {
    sid    = "LambdaInvokeAccess"
    effect = "Allow"
    actions = [
      "lambda:InvokeFunction"
    ]
    resources = [
      "arn:aws:lambda:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:function:*"
    ]
  }

  statement {
    sid    = "GlueJobRunAccess"
    effect = "Allow"
    actions = [
      "glue:StartJobRun",
      "glue:GetJobRun",
      "glue:GetJobRuns",
      "glue:BatchStopJobRun"
    ]
    resources = [
      "arn:aws:glue:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:job/*"
    ]
  }
}

resource "aws_iam_role_policy" "step_functions_pipeline_inline_policy" {
  name   = "StepFunctionsPipelinePolicy"
  role   = aws_iam_role.step_functions_service_role.id
  policy = data.aws_iam_policy_document.step_functions_pipeline_policy.json
}

# ==============================================================================
# Outputs
# ==============================================================================
output "terraform_state_bucket_name" {
  description = "The name of the S3 bucket created for Terraform state"
  value       = aws_s3_bucket.terraform_state.id
}

output "terraform_state_dynamodb_table_name" {
  description = "The name of the DynamoDB table created for Terraform state locking"
  value       = aws_dynamodb_table.terraform_locks.name
}

output "terraform_state_kms_key_arn" {
  description = "The ARN of the KMS key used for encrypting Terraform state"
  value       = aws_kms_key.terraform_state_key.arn
}

output "glue_service_role_arn" {
  description = "ARN of the Glue service role"
  value       = aws_iam_role.glue_service_role.arn
}

output "comprehend_service_role_arn" {
  description = "ARN of the Comprehend service role"
  value       = aws_iam_role.comprehend_service_role.arn
}

output "lambda_execution_role_arn" {
  description = "ARN of the Lambda execution role"
  value       = aws_iam_role.lambda_execution_role.arn
}

output "step_functions_service_role_arn" {
  description = "ARN of the Step Functions service role"
  value       = aws_iam_role.step_functions_service_role.arn
}
```

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region for the ZenML resources"
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
  default_tags {
    tags = {
      managedBy   = "terraform"
      application = "demo"
    }
  }
}

# Fetch current AWS account and region info
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# KMS Key for S3 Bucket Server-Side Encryption
resource "aws_kms_key" "zenml_artifacts_key" {
  description             = "KMS key for ZenML artifact store"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "zenml_artifacts_key_alias" {
  name          = "alias/zenml-artifact-store-key"
  target_key_id = aws_kms_key.zenml_artifacts_key.key_id
}

# S3 Bucket for ZenML Artifact Store
resource "aws_s3_bucket" "artifact_store" {
  bucket        = "demo-artifact-store-${data.aws_caller_identity.current.account_id}"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "artifact_store" {
  depends_on = [aws_s3_bucket_ownership_controls.artifact_store]
  bucket     = aws_s3_bucket.artifact_store.id
  acl        = "private"
}

resource "aws_s3_bucket_public_access_block" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.zenml_artifacts_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# ECR Repository for container images
resource "aws_ecr_repository" "zenml_repo" {
  name                 = "zenml-kubernetes"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }
}

# Local ZenML Stack Configuration YAML
resource "local_file" "zenml_stack_yaml" {
  filename = "${path.module}/zenml_stack.yaml"
  content  = <<-EOT
    # ZenML Stack Configuration
    zenml_version: 0.12.0
    stack_name: aws-demo-stack
    components:
      artifact_store:
        flavor: s3
        name: s3_artifact_store
        configuration:
          path: s3://${aws_s3_bucket.artifact_store.id}
      container_registry:
        flavor: aws
        name: ecr_container_registry
        configuration:
          uri: ${data.aws_caller_identity.current.account_id}.dkr.ecr.${data.aws_region.current.name}.amazonaws.com
      secrets_manager:
        flavor: aws
        name: aws_secrets_manager
        configuration:
          region_name: ${data.aws_region.current.name}
  EOT
}

output "artifact_bucket_name" {
  description = "Name of the S3 artifact store bucket"
  value       = aws_s3_bucket.artifact_store.id
}

output "artifact_bucket_arn" {
  description = "ARN of the S3 artifact store bucket"
  value       = aws_s3_bucket.artifact_store.arn
}

output "ecr_repository_url" {
  description = "URL of the ECR repository"
  value       = aws_ecr_repository.zenml_repo.repository_url
}

output "kms_key_arn" {
  description = "ARN of the customer managed KMS key"
  value       = aws_kms_key.zenml_artifacts_key.arn
}

output "zenml_stack_file" {
  description = "Path to the generated ZenML stack definition file"
  value       = local_file.zenml_stack_yaml.filename
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into."
  default     = "us-east-1"
}

variable "prefix" {
  type        = string
  description = "Prefix for naming resources."
  default     = "nim"
}

variable "registry_username" {
  type        = string
  description = "Username for container registry credentials."
  default     = "AWS"
}

variable "registry_password" {
  type        = string
  description = "Password for container registry credentials."
  default     = ""
  sensitive   = true
}

# 1. AWS Secrets Manager Secret
resource "aws_secretsmanager_secret" "repo_secret" {
  name_prefix             = "${var.prefix}-reposecret-"
  description             = "Container registry credentials secret"
  recovery_window_in_days = 0
}

resource "aws_secretsmanager_secret_version" "repo_secret_version" {
  secret_id = aws_secretsmanager_secret.repo_secret.id
  secret_string = jsonencode({
    username = var.registry_username
    password = var.registry_password
  })
}

# 2. IAM Task Execution Role for Amazon ECS tasks
data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_task_execution_role" {
  name_prefix        = "${var.prefix}-ecs_task_execution-"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json
  description        = "ECS task execution role with access to registry secrets"
}

# 3. Attach AWS-managed AmazonECSTaskExecutionRolePolicy
resource "aws_iam_role_policy_attachment" "ecs_task_execution_managed_policy" {
  role       = aws_iam_role.ecs_task_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# 4. Inline Policy for reading the created secret value
data "aws_iam_policy_document" "ecs_task_access_secrets" {
  statement {
    effect    = "Allow"
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [aws_secretsmanager_secret.repo_secret.arn]
  }
}

resource "aws_iam_role_policy" "ecs_task_access_secrets" {
  name   = "ECSTaskAccessSecretsPolicy"
  role   = aws_iam_role.ecs_task_execution_role.id
  policy = data.aws_iam_policy_document.ecs_task_access_secrets.json
}

# Outputs
output "ecs_task_execution_role_arn" {
  description = "The ARN of the ECS task execution role."
  value       = aws_iam_role.ecs_task_execution_role.arn
}

output "ecs_task_execution_role_name" {
  description = "The name of the ECS task execution role."
  value       = aws_iam_role.ecs_task_execution_role.name
}

output "secrets_manager_secret_arn" {
  description = "The ARN of the created repository secret."
  value       = aws_secretsmanager_secret.repo_secret.arn
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region for the provider"
  default     = "us-east-1"
}

variable "ou_paths" {
  type        = list(string)
  description = "List of slash-delimited nested OU paths to create up to 5 levels deep (e.g., ['Workloads/Prod/App1', 'Core/Security'])"
  default     = []
}

# 1. AWS Organization with all required policy types enabled
resource "aws_organizations_organization" "org" {
  aws_service_access_principals = [
    "cloudtrail.amazonaws.com",
    "config.amazonaws.com"
  ]
  feature_set = "ALL"

  enabled_policy_types = [
    "AISERVICES_OPT_OUT_POLICY",
    "BACKUP_POLICY",
    "SERVICE_CONTROL_POLICY",
    "TAG_POLICY"
  ]
}

# 2. Local computations to handle up to 5 levels of nested OUs
locals {
  # Normalize and filter input paths
  normalized_paths = distinct([
    for p in var.ou_paths : trim(p, "/") if length(trim(p, "/")) > 0
  ])

  # Expand all intermediate paths (e.g., "A/B/C" -> "A", "A/B", "A/B/C")
  expanded_paths = distinct(flatten([
    for p in local.normalized_paths : [
      for i in range(1, length(split("/", p)) + 1) :
      join("/", slice(split("/", p), 0, i))
    ]
  ]))

  # Level 1 OUs (Direct children of the Organization Root)
  level_1 = {
    for p in local.expanded_paths : p => split("/", p)[0]
    if length(split("/", p)) == 1
  }

  # Level 2 OUs
  level_2 = {
    for p in local.expanded_paths : p => {
      name        = split("/", p)[1]
      parent_path = split("/", p)[0]
    }
    if length(split("/", p)) == 2
  }

  # Level 3 OUs
  level_3 = {
    for p in local.expanded_paths : p => {
      name        = split("/", p)[2]
      parent_path = join("/", slice(split("/", p), 0, 2))
    }
    if length(split("/", p)) == 3
  }

  # Level 4 OUs
  level_4 = {
    for p in local.expanded_paths : p => {
      name        = split("/", p)[3]
      parent_path = join("/", slice(split("/", p), 0, 3))
    }
    if length(split("/", p)) == 4
  }

  # Level 5 OUs
  level_5 = {
    for p in local.expanded_paths : p => {
      name        = split("/", p)[4]
      parent_path = join("/", slice(split("/", p), 0, 4))
    }
    if length(split("/", p)) == 5
  }
}

# Level 1 Organizational Units
resource "aws_organizations_organizational_unit" "level_1" {
  for_each  = local.level_1
  name      = each.value
  parent_id = aws_organizations_organization.org.roots[0].id
}

# Level 2 Organizational Units
resource "aws_organizations_organizational_unit" "level_2" {
  for_each  = local.level_2
  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level_1[each.value.parent_path].id
}

# Level 3 Organizational Units
resource "aws_organizations_organizational_unit" "level_3" {
  for_each  = local.level_3
  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level_2[each.value.parent_path].id
}

# Level 4 Organizational Units
resource "aws_organizations_organizational_unit" "level_4" {
  for_each  = local.level_4
  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level_3[each.value.parent_path].id
}

# Level 5 Organizational Units
resource "aws_organizations_organizational_unit" "level_5" {
  for_each  = local.level_5
  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level_4[each.value.parent_path].id
}

# Outputs
output "organization_id" {
  description = "The ID of the AWS Organization"
  value       = aws_organizations_organization.org.id
}

output "organization_root_id" {
  description = "The ID of the Root in the AWS Organization"
  value       = aws_organizations_organization.org.roots[0].id
}

output "organizational_units" {
  description = "Map of all created Organizational Units paths to their IDs"
  value = merge(
    { for k, v in aws_organizations_organizational_unit.level_1 : k => v.id },
    { for k, v in aws_organizations_organizational_unit.level_2 : k => v.id },
    { for k, v in aws_organizations_organizational_unit.level_3 : k => v.id },
    { for k, v in aws_organizations_organizational_unit.level_4 : k => v.id },
    { for k, v in aws_organizations_organizational_unit.level_5 : k => v.id }
  )
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

# 1. VPC Configuration
resource "aws_vpc" "swe_vpc" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name          = "swe-vpc"
    ResourceGroup = "default"
  }
}

# 2. Adopt Default Network ACL
resource "aws_default_network_acl" "swe_vpc_default_acl" {
  default_network_acl_id = aws_vpc.swe_vpc.default_network_acl_id

  # Explicitly deny inbound SSH (port 22) from anywhere
  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "deny"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  # Explicitly deny inbound RDP (port 3389) from anywhere
  ingress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "deny"
    cidr_block = "0.0.0.0/0"
    from_port  = 3389
    to_port    = 3389
  }

  # Allow all inbound traffic from VPC's own CIDR
  ingress {
    protocol   = "-1"
    rule_no    = 200
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 0
    to_port    = 0
  }

  # Allow all outbound traffic to VPC's own CIDR
  egress {
    protocol   = "-1"
    rule_no    = 200
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name          = "swe-vpc-default_acl"
    ResourceGroup = "default"
  }
}

# 3. Adopt Default Security Group with no rules defined inline
resource "aws_default_security_group" "swe_vpc_default_sg" {
  vpc_id = aws_vpc.swe_vpc.id

  tags = {
    Name          = "swe-vpc-default_sg"
    ResourceGroup = "default"
  }
}

# 4. Standalone Inbound Security Group Rules for Default SG

# Allow ICMP echo (ping) from anywhere
resource "aws_security_group_rule" "default_sg_ingress_icmp" {
  type              = "ingress"
  security_group_id = aws_default_security_group.swe_vpc_default_sg.id
  protocol          = "icmp"
  from_port         = 8 # ICMP Echo Request type
  to_port           = 0 # ICMP Echo Request code
  cidr_blocks       = ["0.0.0.0/0"]
  description       = "Allow ICMP echo from anywhere"
}

# Allow HTTP (port 80) from anywhere
resource "aws_security_group_rule" "default_sg_ingress_http" {
  type              = "ingress"
  security_group_id = aws_default_security_group.swe_vpc_default_sg.id
  protocol          = "tcp"
  from_port         = 80
  to_port           = 80
  cidr_blocks       = ["0.0.0.0/0"]
  description       = "Allow HTTP from anywhere"
}

# Outputs
output "vpc_id" {
  description = "The ID of the created VPC"
  value       = aws_vpc.swe_vpc.id
}

output "default_network_acl_id" {
  description = "The ID of the adopted default Network ACL"
  value       = aws_default_network_acl.swe_vpc_default_acl.id
}

output "default_security_group_id" {
  description = "The ID of the adopted default Security Group"
  value       = aws_default_security_group.swe_vpc_default_sg.id
}
```

terraform {
  required_version = ">= 1.0.0"
