variable "aws_region" {
  type        = string
  description = "AWS region for resources"
  default     = "eu-west-1"
}

provider "aws" {
  region = var.aws_region
}

# Fetch the first two available AZs in the current region
data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Development VPC (vpc_dev)
# -----------------------------------------------------------------------------
resource "aws_vpc" "dev" {
  cidr_block                       = "10.16.0.0/16"
  assign_generated_ipv6_cidr_block = true
  enable_dns_support               = true
  enable_dns_hostnames             = true

  tags = {
    Name = "vpc_dev"
  }
}

resource "aws_internet_gateway" "dev" {
  vpc_id = aws_vpc.dev.id

  tags = {
    Name = "gatway_dev"
  }
}

resource "aws_default_route_table" "dev" {
  default_route_table_id = aws_vpc.dev.default_route_table_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.dev.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.dev.id
  }

  tags = {
    Name = "rt_dev_default"
  }
}

# Dev Subnets - Public
resource "aws_subnet" "dev_public_a" {
  vpc_id            = aws_vpc.dev.id
  cidr_block        = "10.16.12.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "subnet_dev_public_a"
  }
}

resource "aws_subnet" "dev_public_b" {
  vpc_id            = aws_vpc.dev.id
  cidr_block        = "10.16.11.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "subnet_dev_public_b"
  }
}

# Dev Subnets - Internal
resource "aws_subnet" "dev_internal_a" {
  vpc_id            = aws_vpc.dev.id
  cidr_block        = "10.16.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "subnet_dev_internal_a"
  }
}

resource "aws_subnet" "dev_internal_b" {
  vpc_id            = aws_vpc.dev.id
  cidr_block        = "10.16.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "subnet_dev_internal_b"
  }
}

# Dev Subnets - External
resource "aws_subnet" "dev_external_a" {
  vpc_id            = aws_vpc.dev.id
  cidr_block        = "10.16.5.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "subnet_dev_external_a"
  }
}

resource "aws_subnet" "dev_external_b" {
  vpc_id            = aws_vpc.dev.id
  cidr_block        = "10.16.6.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "subnet_dev_external_b"
  }
}

# -----------------------------------------------------------------------------
# Recette / Staging VPC (vpc_rec)
# -----------------------------------------------------------------------------
resource "aws_vpc" "rec" {
  cidr_block                       = "10.32.0.0/16"
  assign_generated_ipv6_cidr_block = true
  enable_dns_support               = true
  enable_dns_hostnames             = true

  tags = {
    Name = "vpc_rec"
  }
}

resource "aws_internet_gateway" "rec" {
  vpc_id = aws_vpc.rec.id

  tags = {
    Name = "gatway_rec"
  }
}

resource "aws_default_route_table" "rec" {
  default_route_table_id = aws_vpc.rec.default_route_table_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.rec.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.rec.id
  }

  tags = {
    Name = "rt_rec_default"
  }
}

# Rec Subnets - Public
resource "aws_subnet" "rec_public_a" {
  vpc_id            = aws_vpc.rec.id
  cidr_block        = "10.32.12.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "subnet_rec_public_a"
  }
}

resource "aws_subnet" "rec_public_b" {
  vpc_id            = aws_vpc.rec.id
  cidr_block        = "10.32.11.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "subnet_rec_public_b"
  }
}

# Rec Subnets - Internal
resource "aws_subnet" "rec_internal_a" {
  vpc_id            = aws_vpc.rec.id
  cidr_block        = "10.32.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "subnet_rec_internal_a"
  }
}

resource "aws_subnet" "rec_internal_b" {
  vpc_id            = aws_vpc.rec.id
  cidr_block        = "10.32.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "subnet_rec_internal_b"
  }
}

# Rec Subnets - External
resource "aws_subnet" "rec_external_a" {
  vpc_id            = aws_vpc.rec.id
  cidr_block        = "10.32.5.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

