  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "subnet_rec_external_b"
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_dev_id" {
  description = "The ID of the Development VPC"
  value       = aws_vpc.dev.id
}

output "vpc_rec_id" {
  description = "The ID of the Recette VPC"
  value       = aws_vpc.rec.id
