terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.region
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

variable "namespace" {
  type        = string
  description = "Namespace, which could be your organization name or abbreviation, e.g. 'eg' or 'cp'"
  default     = "cp"
}

variable "environment" {
  type        = string
  description = "Environment, e.g. 'ue1', 'useast1'"
  default     = "use1"
}

variable "stage" {
  type        = string
  description = "Stage, e.g. 'prod', 'staging', 'dev'"
  default     = "prod"
}

variable "name" {
  type        = string
  description = "Solution name, e.g. 'guardduty'"
  default     = "guardduty"
}

variable "attributes" {
  type        = list(string)
  description = "Additional attributes (e.g. `1`)"
  default     = []
}

variable "tags" {
  type        = map(string)
  description = "Additional tags (e.g. `map('BusinessUnit','XYZ')`"
  default     = {}
}

variable "finding_publishing_frequency" {
  type        = string
  description = "Specifies the frequency of notifications sent for subsequent finding occurrences. Options: FIFTEEN_MINUTES, ONE_HOUR, SIX_HOURS"
  default     = "SIX_HOURS"
}

variable "enable_s3_protection" {
  type        = bool
  description = "Configures S3 protection in GuardDuty"
  default     = false
}

variable "enable_notifications" {
  type        = bool
  description = "Flag to enable/disable EventBridge rules and SNS notifications for GuardDuty findings"
  default     = false
}

# ---------------------------------------------------------------------------------------------------------------------
# LOCALS
# ---------------------------------------------------------------------------------------------------------------------

locals {
  # Build Cloud Posse standard ID: [namespace]-[environment]-[stage]-[name]-[attributes]
  raw_id = compact(concat([var.namespace, var.environment, var.stage, var.name], var.attributes))
  id     = lower(join("-", local.raw_id))

  tags = merge(
    {
      "Namespace"   = var.namespace
      "Environment" = var.environment
      "Stage"       = var.stage
      "Name"        = local.id
    },
    var.tags
  )
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES
# ---------------------------------------------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------------------------------------------------
# GUARDDUTY DETECTOR
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_guardduty_detector" "default" {
  enable                       = true
  finding_publishing_frequency = var.finding_publishing_frequency

  datasources {
    s3_logs {
      enable = var.enable_s3_protection
    }
  }

  tags = local.tags
}

# ---------------------------------------------------------------------------------------------------------------------
# OPTIONAL NOTIFICATIONS (SNS & EVENTBRIDGE) - DISABLED BY DEFAULT
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_sns_topic" "guardduty_findings" {
  count = var.enable_notifications ? 1 : 0
  name  = "${local.id}-findings"
  tags  = local.tags
}

data "aws_iam_policy_document" "sns_topic_policy" {
  count = var.enable_notifications ? 1 : 0

  statement {
    sid       = "AllowGuardDutyEventsToPublish"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.guardduty_findings[0].arn]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

resource "aws_sns_topic_policy" "default" {
  count  = var.enable_notifications ? 1 : 0
  arn    = aws_sns_topic.guardduty_findings[0].arn
  policy = data.aws_iam_policy_document.sns_topic_policy[0].json
}

resource "aws_cloudwatch_event_rule" "guardduty_findings" {
  count       = var.enable_notifications ? 1 : 0
  name        = "${local.id}-findings-rule"
  description = "Capture AWS GuardDuty Findings"

  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = ["GuardDuty Finding"]
  })

  tags = local.tags
}

resource "aws_cloudwatch_event_target" "sns" {
  count     = var.enable_notifications ? 1 : 0
  rule      = aws_cloudwatch_event_rule.guardduty_findings[0].name
  target_id = "SendToSNS"
  arn       = aws_sns_topic.guardduty_findings[0].arn
}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "guardduty_detector_id" {
  description = "The ID of the GuardDuty detector"
  value       = aws_guardduty_detector.default.id
}

output "guardduty_detector_arn" {
  description = "The ARN of the GuardDuty detector"
  value       = aws_guardduty_detector.default.arn
}

output "sns_topic_arn" {
  description = "The ARN of the SNS topic (if notifications enabled)"
  value       = try(aws_sns_topic.guardduty_findings[0].arn, null)
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

# Generate 6-character lowercase alphanumeric string
resource "random_string" "suffix" {
  length  = 6
  special = false
  upper   = false
}

locals {
  prefix = "sudo-backup-${random_string.suffix.result}"
}

# Fetch current AWS account ID and partition for KMS policy
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# Customer Managed KMS Key for AWS Backup Vault
resource "aws_kms_key" "backup_key" {
  description             = "KMS Key for ${local.prefix}-backup-vault"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${local.prefix}-backup-kms-key"
  }
}

resource "aws_kms_alias" "backup_key_alias" {
  name          = "alias/${local.prefix}-backup-key"
  target_key_id = aws_kms_key.backup_key.key_id
}

# AWS Backup Vault
resource "aws_backup_vault" "vault" {
  name        = "${local.prefix}-backup-vault"
  kms_key_arn = aws_kms_key.backup_key.arn

  tags = {
    Name = "${local.prefix}-backup-vault"
  }
}

# AWS Backup Plan
resource "aws_backup_plan" "plan" {
  name = "${local.prefix}-backup-plan"

  rule {
    rule_name         = "${local.prefix}-backup-rule"
    target_vault_name = aws_backup_vault.vault.name
    schedule          = "cron(0 12 * * ? *)"

    recovery_point_tags = {
      Name = "${local.prefix}-recovery-point"
    }
  }

  tags = {
    Name = "${local.prefix}-backup-plan"
  }
}

# IAM Role for AWS Backup
resource "aws_iam_role" "backup_role" {
  name = "${local.prefix}-backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "${local.prefix}-backup-role"
  }
}

# Attach AWS Backup managed policy to the IAM role
resource "aws_iam_role_policy_attachment" "backup_policy_attachment" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
  role       = aws_iam_role.backup_role.name
}

# AWS Backup Selection
resource "aws_backup_selection" "selection" {
  name         = "${local.prefix}-backup-selection"
  iam_role_arn = aws_iam_role.backup_role.arn
  plan_id      = aws_backup_plan.plan.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "backup"
    value = "true"
  }
}

output "prefix" {
  description = "The generated prefix used for resources"
  value       = local.prefix
}

output "backup_vault_arn" {
  description = "ARN of the backup vault"
  value       = aws_backup_vault.vault.arn
}

output "backup_plan_id" {
  description = "ID of the backup plan"
  value       = aws_backup_plan.plan.id
}

output "backup_role_arn" {
  description = "ARN of the IAM role used by AWS Backup"
  value       = aws_iam_role.backup_role.arn
}

