terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region for resources"
  default     = "us-east-1"
}

variable "user_pool_domain_prefix" {
  type        = string
  description = "Domain prefix for the Cognito hosted UI"
  default     = "coop-tweets-domain"
}

# 1. Cognito User Pool
resource "aws_cognito_user_pool" "coop_tweets" {
  name = "coop-tweets"

  admin_create_user_config {
    allow_admin_create_user_only = true
  }

  password_policy {
    minimum_length    = 6
    require_numbers   = true
    require_uppercase = true
    require_symbols   = true
    require_lowercase = false
  }
}

# 2. Cognito User Pool Domain
resource "aws_cognito_user_pool_domain" "coop_tweets_domain" {
  domain       = var.user_pool_domain_prefix
  user_pool_id = aws_cognito_user_pool.coop_tweets.id
}

# 3. Cognito User Pool Client
resource "aws_cognito_user_pool_client" "coop_tweets_client" {
  name         = "coop-tweets-client"
  user_pool_id = aws_cognito_user_pool.coop_tweets.id

  generate_secret = false
}

# 4. Cognito Identity Pool
resource "aws_cognito_identity_pool" "coop_tweets_identity_pool" {
  identity_pool_name               = "coop tweets"
  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.coop_tweets_client.id
    provider_name           = aws_cognito_user_pool.coop_tweets.endpoint
    server_side_token_check = false
  }
}

# 5. IAM Roles for Authenticated and Unauthenticated Identities
data "aws_iam_policy_document" "cognito_auth_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.coop_tweets_identity_pool.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

data "aws_iam_policy_document" "cognito_unauth_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.coop_tweets_identity_pool.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["unauthenticated"]
    }
  }
}

resource "aws_iam_role" "authenticated" {
  name               = "coop-tweets_cognito_auth_role"
  assume_role_policy = data.aws_iam_policy_document.cognito_auth_assume_role.json
}

resource "aws_iam_role" "unauthenticated" {
  name               = "coop-tweets_cognito_unauth_role"
  assume_role_policy = data.aws_iam_policy_document.cognito_unauth_assume_role.json
}

# 6. IAM Policies for Mobile Analytics, Cognito Sync, and Cognito Identity
data "aws_iam_policy_document" "cognito_permissions" {
  statement {
    effect = "Allow"
    actions = [
      "mobileanalytics:PutEvents",
      "cognito-sync:*",
      "cognito-identity:*"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "auth_policy" {
  name        = "cognito_kibana_auth_coop-tweets"
  description = "Allows mobile analytics and cognito access for authenticated users"
  policy      = data.aws_iam_policy_document.cognito_permissions.json
}

resource "aws_iam_policy" "unauth_policy" {
  name        = "cognito_kibana_unauth_coop-tweets"
  description = "Allows mobile analytics and cognito access for unauthenticated users"
  policy      = data.aws_iam_policy_document.cognito_permissions.json
}

resource "aws_iam_role_policy_attachment" "auth_attachment" {
  role       = aws_iam_role.authenticated.name
  policy_arn = aws_iam_policy.auth_policy.arn
}

resource "aws_iam_role_policy_attachment" "unauth_attachment" {
  role       = aws_iam_role.unauthenticated.name
  policy_arn = aws_iam_policy.unauth_policy.arn
}

# 7. Attach IAM Roles to Cognito Identity Pool
resource "aws_cognito_identity_pool_roles_attachment" "coop_tweets_roles" {
  identity_pool_id = aws_cognito_identity_pool.coop_tweets_identity_pool.id

  roles = {
    "authenticated"   = aws_iam_role.authenticated.arn
    "unauthenticated" = aws_iam_role.unauthenticated.arn
  }
}

output "user_pool_id" {
  description = "The ID of the Cognito User Pool"
  value       = aws_cognito_user_pool.coop_tweets.id
}

output "identity_pool_id" {
  description = "The ID of the Cognito Identity Pool"
  value       = aws_cognito_identity_pool.coop_tweets_identity_pool.id
}

output "user_pool_domain" {
  description = "The domain endpoint for the hosted Cognito UI"
  value       = "${aws_cognito_user_pool_domain.coop_tweets_domain.domain}.auth.${var.aws_region}.amazoncognito.com"
}
