terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# ---------------------------------------------------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------------------------------------------------
variable "aws_region" {
  description = "The AWS region where resources will be deployed."
  type        = string
  default     = "us-east-1"
}

variable "enable_s3_export" {
  description = "Whether to create an S3 bucket and configure GuardDuty to export findings to it."
  type        = bool
  default     = false
}

# ---------------------------------------------------------------------------------------------------------------------
# Data Sources
# ---------------------------------------------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ---------------------------------------------------------------------------------------------------------------------
# KMS Key and Policy for GuardDuty
# ---------------------------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_guardduty_policy" {
  # Full administrative access for the account root
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  # Allow GuardDuty to generate data keys for findings export
  statement {
    sid    = "AllowGuardDutyKeyUsage"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey"
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "guardduty" {
  description             = "KMS Key for Amazon GuardDuty findings encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_guardduty_policy.json

  tags = {
    Name = "guardduty-findings-key"
  }
}

resource "aws_kms_alias" "guardduty" {
  name          = "alias/guardduty"
  target_key_id = aws_kms_key.guardduty.key_id
}

# ---------------------------------------------------------------------------------------------------------------------
# GuardDuty Detector
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_guardduty_detector" "primary" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"

  tags = {
    Name = "primary-guardduty-detector"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# Amazon EventBridge Rule for GuardDuty Findings
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_cloudwatch_event_rule" "guardduty_findings" {
  name        = "guardduty-finding-events"
  description = "Captures all GuardDuty Finding events"

  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = ["GuardDuty Finding"]
  })

  tags = {
    Name = "guardduty-finding-events"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# Optional: S3 Findings Export Resources
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_s3_bucket" "guardduty_findings" {
  count         = var.enable_s3_export ? 1 : 0
  bucket_prefix = "guardduty-findings-"
  force_destroy = true

  tags = {
    Name = "guardduty-findings-bucket"
  }
}

resource "aws_s3_bucket_public_access_block" "guardduty_findings" {
  count  = var.enable_s3_export ? 1 : 0
  bucket = aws_s3_bucket.guardduty_findings[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "s3_guardduty_policy" {
  count = var.enable_s3_export ? 1 : 0

  statement {
    sid       = "AllowGuardDutyGetBucketLocation"
    effect    = "Allow"
    actions   = ["s3:GetBucketLocation"]
    resources = [aws_s3_bucket.guardduty_findings[0].arn]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }
  }

  statement {
    sid       = "AllowGuardDutyPutObject"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.guardduty_findings[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }
  }

  statement {
    sid       = "DenyUnencryptedObjectUploads"
    effect    = "Deny"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.guardduty_findings[0].arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption"
      values   = ["aws:kms"]
    }
  }

  statement {
    sid       = "DenyIncorrectKmsKey"
    effect    = "Deny"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.guardduty_findings[0].arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption-aws-kms-key-id"
      values   = [aws_kms_key.guardduty.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "guardduty_findings" {
  count  = var.enable_s3_export ? 1 : 0
  bucket = aws_s3_bucket.guardduty_findings[0].id
  policy = data.aws_iam_policy_document.s3_guardduty_policy[0].json
}

resource "aws_guardduty_publishing_destination" "s3_export" {
  count           = var.enable_s3_export ? 1 : 0
  detector_id     = aws_guardduty_detector.primary.id
  destination_arn = aws_s3_bucket.guardduty_findings[0].arn
  kms_key_arn     = aws_kms_key.guardduty.arn

  depends_on = [
    aws_s3_bucket_policy.guardduty_findings
  ]
}

# ---------------------------------------------------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------------------------------------------------
output "guardduty_detector_id" {
  description = "The ID of the GuardDuty detector."
  value       = aws_guardduty_detector.primary.id
}

output "kms_key_arn" {
  description = "The ARN of the KMS key created for GuardDuty."
  value       = aws_kms_key.guardduty.arn
}

output "kms_key_alias" {
  description = "The alias of the KMS key."
  value       = aws_kms_alias.guardduty.name
}

output "eventbridge_rule_arn" {
  description = "The ARN of the EventBridge rule for GuardDuty finding events."
  value       = aws_cloudwatch_event_rule.guardduty_findings.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "The AWS region to deploy the S3 bucket into"
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
}

# 1. S3 Bucket with auto-generated name and force_destroy enabled
resource "aws_s3_bucket" "this" {
  bucket_prefix = "private-bucket-"
  force_destroy = true

  tags = {
    Name        = "Private S3 Bucket"
    Environment = "Production"
  }
}

# 2. Public Access Block (all 4 settings enabled)
resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# 3. Bucket Versioning enabled with MFA delete disabled
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = "Disabled"
  }
}

# 4. Server-side encryption with AES256 (SSE-S3) and bucket key enabled
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
    bucket_key_enabled = true
  }
}

# 5. Object ownership set to "BucketOwnerPreferred"
resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

# 6. Private canned ACL applied after ownership controls
resource "aws_s3_bucket_acl" "this" {
  depends_on = [aws_s3_bucket_ownership_controls.this]

  bucket = aws_s3_bucket.this.id
  acl    = "private"
}

output "bucket_name" {
  description = "The name of the created S3 bucket"
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the created S3 bucket"
  value       = aws_s3_bucket.this.arn
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region for provider configuration"
  default     = "us-east-1"
}

variable "billing_full_access_group_users" {
  type        = list(string)
  description = "List of IAM usernames to add to the billing-full-access group"
  default     = []
}

variable "billing_view_access_group_users" {
  type        = list(string)
  description = "List of IAM usernames to add to the billing-view-access group"
  default     = []
}

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# IAM Assume Role Trust Policy (MFA Required within the current account)
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "billing_role_trust_policy" {
  statement {
    sid     = "AllowAccountAssumeRoleWithMFA"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# ------------------------------------------------------------------------------
# Role 1: Billing Full Access
# ------------------------------------------------------------------------------
resource "aws_iam_role" "billing_full_access" {
  name               = "billing-full-access"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.billing_role_trust_policy.json

  tags = {
    Name = "billing-full-access"
  }
}

data "aws_iam_policy_document" "billing_full_access" {
  statement {
    sid    = "BillingFullAccessPermissions"
    effect = "Allow"
    actions = [
      "account:*",
      "aws-portal:*",
      "budgets:*",
      "ce:*",
      "cur:*",
      "freetier:*",
      "invoicing:*",
      "payments:*",
      "purchase-orders:*",
      "tax:*"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_full_access" {
  name        = "billing-full-access"
  path        = "/"
  description = "Provides full access to billing, usage, payment methods, accounts, and budgets"
  policy      = data.aws_iam_policy_document.billing_full_access.json
}

resource "aws_iam_role_policy_attachment" "billing_full_access" {
  role       = aws_iam_role.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access.arn
}

# ------------------------------------------------------------------------------
# Role 2: Billing View Access
# ------------------------------------------------------------------------------
resource "aws_iam_role" "billing_view_access" {
  name               = "billing-view-access"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.billing_role_trust_policy.json

  tags = {
    Name = "billing-view-access"
  }
}

data "aws_iam_policy_document" "billing_view_access" {
  statement {
    sid    = "BillingViewAccessPermissions"
    effect = "Allow"
    actions = [
      "account:GetAccountInformation",
      "account:GetAlternateContact",
      "account:GetChallengeQuestions",
      "account:GetContactInformation",
      "aws-portal:ViewBilling",
      "aws-portal:ViewPaymentMethods",
      "aws-portal:ViewUsage",
      "budgets:ViewBudget",
      "ce:DescribeCostCategoryDefinition",
      "ce:DescribeNotificationSubscription",
      "ce:DescribeReport",
      "ce:Get*",
      "ce:List*",
      "cur:DescribeReportDefinitions",
      "freetier:GetFreeTierAlertPreference",
      "freetier:GetFreeTierUsage",
      "invoicing:Get*",
      "invoicing:List*",
      "payments:Get*",
      "payments:List*",
      "purchase-orders:Get*",
      "purchase-orders:List*",
      "purchase-orders:ViewPurchaseOrders",
      "tax:Get*",
      "tax:List*"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_view_access" {
  name        = "billing-view-access"
  path        = "/"
  description = "Provides view-only access to billing, usage, payment methods, accounts, and budgets"
  policy      = data.aws_iam_policy_document.billing_view_access.json
}

resource "aws_iam_role_policy_attachment" "billing_view_access" {
  role       = aws_iam_role.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access.arn
}

# ------------------------------------------------------------------------------
# Groups and Assume Role Policies
# ------------------------------------------------------------------------------

# Group 1: billing-full-access
resource "aws_iam_group" "billing_full_access" {
  name = "billing-full-access"
  path = "/"
}

data "aws_iam_policy_document" "billing_full_access_assume_role" {
  statement {
    sid     = "AllowAssumeBillingFullAccessRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    resources = [
      aws_iam_role.billing_full_access.arn
    ]
  }
}

resource "aws_iam_policy" "billing_full_access_assume_role" {
  name        = "billing-full-access-assume-role"
  path        = "/"
  description = "Allows members to assume the billing-full-access role"
  policy      = data.aws_iam_policy_document.billing_full_access_assume_role.json
}

resource "aws_iam_group_policy_attachment" "billing_full_access" {
  group      = aws_iam_group.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access_assume_role.arn
}

resource "aws_iam_group_membership" "billing_full_access" {
  count = length(var.billing_full_access_group_users) > 0 ? 1 : 0
  name  = "billing-full-access-membership"
  group = aws_iam_group.billing_full_access.name
  users = var.billing_full_access_group_users
}

# Group 2: billing-view-access
resource "aws_iam_group" "billing_view_access" {
  name = "billing-view-access"
  path = "/"
}

data "aws_iam_policy_document" "billing_view_access_assume_role" {
  statement {
    sid     = "AllowAssumeBillingViewAccessRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    resources = [
      aws_iam_role.billing_view_access.arn
    ]
  }
}

resource "aws_iam_policy" "billing_view_access_assume_role" {
  name        = "billing-view-access-assume-role"
  path        = "/"
  description = "Allows members to assume the billing-view-access role"
  policy      = data.aws_iam_policy_document.billing_view_access_assume_role.json
}

resource "aws_iam_group_policy_attachment" "billing_view_access" {
  group      = aws_iam_group.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access_assume_role.arn
}

resource "aws_iam_group_membership" "billing_view_access" {
  count = length(var.billing_view_access_group_users) > 0 ? 1 : 0
  name  = "billing-view-access-membership"
  group = aws_iam_group.billing_view_access.name
  users = var.billing_view_access_group_users
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "billing_full_access_role_arn" {
  description = "ARN of the billing-full-access IAM role"
  value       = aws_iam_role.billing_full_access.arn
}

output "billing_view_access_role_arn" {
  description = "ARN of the billing-view-access IAM role"
  value       = aws_iam_role.billing_view_access.arn
}

output "billing_full_access_group_arn" {
  description = "ARN of the billing-full-access IAM group"
  value       = aws_iam_group.billing_full_access.arn
}

output "billing_view_access_group_arn" {
  description = "ARN of the billing-view-access IAM group"
  value       = aws_iam_group.billing_view_access.arn
}
```

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region for provisioning resources"
  default     = "us-east-1"
}

# Current AWS Partition, Region, and Account ID
data "aws_partition" "current" {}
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

# Random pet name for resource naming
resource "random_pet" "suffix" {
  length    = 2
  separator = "-"
}

# Random 16-character uppercase external ID for SMS role
resource "random_string" "sms_external_id" {
  length  = 16
  upper   = true
  lower   = false
  numeric = false
  special = false
}

locals {
  base_name      = "cognito"
  resource_name  = "${local.base_name}-${random_pet.suffix.id}"
  user_pool_name = replace(local.resource_name, "-", "_")
}

# IAM Role for Cognito User Pool SMS sending
data "aws_iam_policy_document" "sms_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["cognito-idp.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [random_string.sms_external_id.result]
    }
  }
}

resource "aws_iam_role" "sms" {
  name               = "${local.resource_name}-sms-role"
  assume_role_policy = data.aws_iam_policy_document.sms_assume_role.json
}

data "aws_iam_policy_document" "sms_publish" {
  statement {
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "sms" {
  name        = "${local.resource_name}-sms-policy"
  description = "Allows Cognito to publish SMS messages via SNS"
  policy      = data.aws_iam_policy_document.sms_publish.json
}

resource "aws_iam_role_policy_attachment" "sms" {
  role       = aws_iam_role.sms.name
  policy_arn = aws_iam_policy.sms.arn
}

# Cognito User Pool
resource "aws_cognito_user_pool" "pool" {
  name                     = local.user_pool_name
  mfa_configuration        = "OFF"
  auto_verified_attributes = ["email"]

  sms_configuration {
    external_id    = random_string.sms_external_id.result
    sns_caller_arn = aws_iam_role.sms.arn
  }

  # Required immutable standard email attribute
  schema {
    attribute_data_type      = "String"
    name                     = "email"
    required                 = true
    mutable                  = false
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "1"
      max_length = "2048"
    }
  }

  # Optional immutable standard phone_number attribute
  schema {
    attribute_data_type      = "String"
    name                     = "phone_number"
    required                 = false
    mutable                  = false
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "1"
      max_length = "2048"
    }
  }

  # Mutable custom string attributes
  schema {
    attribute_data_type      = "String"
    name                     = "user_id"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "0"
      max_length = "256"
    }
  }

  schema {
    attribute_data_type      = "String"
    name                     = "profile_email"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "0"
      max_length = "256"
    }
  }

  schema {
    attribute_data_type      = "String"
    name                     = "first_name"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "0"
      max_length = "256"
    }
  }

  schema {
    attribute_data_type      = "String"
    name                     = "last_name"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "0"
      max_length = "256"
    }
  }

  schema {
    attribute_data_type      = "String"
    name                     = "gender"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "0"
      max_length = "256"
    }
  }

  schema {
    attribute_data_type      = "String"
    name                     = "age"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "0"
      max_length = "256"
    }
  }

  schema {
    attribute_data_type      = "String"
    name                     = "persona"
    required                 = false
    mutable                  = true
    developer_only_attribute = false

    string_attribute_constraints {
      min_length = "0"
      max_length = "256"
    }
  }
}

# Cognito User Pool Client
resource "aws_cognito_user_pool_client" "client" {
  name         = "${local.resource_name}-client"
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret = false
}

# Cognito Identity Pool
resource "aws_cognito_identity_pool" "identity_pool" {
  identity_pool_name               = "${local.resource_name}-identity-pool"
  allow_unauthenticated_identities = true

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.client.id
    provider_name           = aws_cognito_user_pool.pool.endpoint
    server_side_token_check = false
  }
}

# IAM Role for Authenticated Identities (signed-users)
data "aws_iam_policy_document" "authenticated_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.identity_pool.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

resource "aws_iam_role" "authenticated" {
  name               = "${local.resource_name}-signed-users"
  assume_role_policy = data.aws_iam_policy_document.authenticated_trust.json
}

data "aws_iam_policy_document" "authenticated_policy" {
  statement {
    effect = "Allow"
    actions = [
      "cognito-identity:GetId",
      "cognito-identity:GetCredentialsForIdentity",
      "cognito-identity:GetOpenIdToken"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:cognito-identity:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:identitypool/${aws_cognito_identity_pool.identity_pool.id}"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "cognito-sync:*"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:cognito-sync:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:identitypool/${aws_cognito_identity_pool.identity_pool.id}*"
    ]
  }
}

resource "aws_iam_policy" "authenticated" {
  name        = "${local.resource_name}-authenticated-policy"
  description = "Allows Cognito Identity and Sync actions scoped to the identity pool"
  policy      = data.aws_iam_policy_document.authenticated_policy.json
}

resource "aws_iam_role_policy_attachment" "authenticated" {
  role       = aws_iam_role.authenticated.name
  policy_arn = aws_iam_policy.authenticated.arn
}

# IAM Role for Unauthenticated Identities (anonymous-users)
data "aws_iam_policy_document" "unauthenticated_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.identity_pool.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["unauthenticated"]
    }
  }
}

resource "aws_iam_role" "unauthenticated" {
  name               = "${local.resource_name}-anonymous-users"
  assume_role_policy = data.aws_iam_policy_document.unauthenticated_trust.json
}

data "aws_iam_policy_document" "unauthenticated_policy" {
  statement {
    effect = "Allow"
    actions = [
      "cognito-identity:GetId",
      "cognito-identity:GetCredentialsForIdentity",
      "cognito-identity:GetOpenIdToken"
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:cognito-identity:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:identitypool/${aws_cognito_identity_pool.identity_pool.id}"
    ]
  }
}

resource "aws_iam_policy" "unauthenticated" {
  name        = "${local.resource_name}-unauthenticated-policy"
  description = "Allows Cognito Identity actions scoped to the identity pool"
  policy      = data.aws_iam_policy_document.unauthenticated_policy.json
}

resource "aws_iam_role_policy_attachment" "unauthenticated" {
  role       = aws_iam_role.unauthenticated.name
  policy_arn = aws_iam_policy.unauthenticated.arn
}

# Attach roles to Identity Pool
resource "aws_cognito_identity_pool_roles_attachment" "roles" {
  identity_pool_id = aws_cognito_identity_pool.identity_pool.id

  roles = {
    "authenticated"   = aws_iam_role.authenticated.arn
    "unauthenticated" = aws_iam_role.unauthenticated.arn
  }
}

# Outputs
output "user_pool_id" {
  value       = aws_cognito_user_pool.pool.id
  description = "The ID of the Cognito User Pool"
}

output "user_pool_client_id" {
  value       = aws_cognito_user_pool_client.client.id
  description = "The ID of the Cognito User Pool Client"
}

output "identity_pool_id" {
  value       = aws_cognito_identity_pool.identity_pool.id
  description = "The ID of the Cognito Identity Pool"
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  type        = string
  description = "AWS region for deployment"
  default     = "us-east-1"
}

provider "aws" {
  region = var.aws_region
  default_tags {
    tags = {
      Environment = terraform.workspace
      Project     = "${terraform.workspace}-batch"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "${terraform.workspace}-batch"
  az          = data.aws_availability_zones.available.names[1]
  account_id  = data.aws_caller_identity.current.account_id
}

# ==============================================================================
# Networking (VPC, Subnets, Route Tables, Gateways)
# ==============================================================================

resource "aws_vpc" "main" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.10.0/24"
  availability_zone       = local.az
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.0.0/24"
  availability_zone       = local.az
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-private-subnet"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${local.name_prefix}-nat-eip"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "${local.name_prefix}-nat-gw"
  }

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${local.name_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "${local.name_prefix}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

# ==============================================================================
# Security Group
# ==============================================================================

resource "aws_security_group" "batch_compute" {
  name        = "${local.name_prefix}-sg"
  description = "Security group for Batch EC2 instances"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow HTTPS egress to VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${local.name_prefix}-sg"
  }
}

# ==============================================================================
# KMS & S3 Bucket
# ==============================================================================

resource "aws_kms_key" "results_key" {
  description             = "KMS Key for ${local.name_prefix} results bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${local.name_prefix}-results-key"
  }
}

resource "aws_kms_alias" "results_key_alias" {
  name          = "alias/${local.name_prefix}-results-key"
  target_key_id = aws_kms_key.results_key.key_id
}

resource "aws_s3_bucket" "results" {
  bucket        = "benchmark-batch-results-${local.account_id}"
  force_destroy = true

  tags = {
    Name = "benchmark-batch-results-${local.account_id}"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "results" {
  bucket = aws_s3_bucket.results.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.results_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "results" {
  bucket = aws_s3_bucket.results.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ==============================================================================
# IAM Roles & Policies
# ==============================================================================

# ECS Instance Role & Profile for Batch Compute Nodes
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_instance_role" {
  name               = "${local.name_prefix}-ecs-instance-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Name = "${local.name_prefix}-ecs-instance-role"
  }
}

resource "aws_iam_role_policy_attachment" "ecs_instance_role_ec2" {
  role       = aws_iam_role.ecs_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

data "aws_iam_policy_document" "ecs_s3_policy_doc" {
  statement {
    sid    = "S3GeneralReadList"
    effect = "Allow"
    actions = [
      "s3:Get*",
      "s3:List*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3ResultsBucketAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject*",
      "s3:PutObject*",
      "s3:DeleteObject*",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.results.arn,
      "${aws_s3_bucket.results.arn}/*"
    ]
  }

  statement {
    sid    = "KMSAccess"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = [aws_kms_key.results_key.arn]
  }
}

resource "aws_iam_policy" "ecs_s3_policy" {
  name        = "ecs_s3_policy"
  description = "Custom S3 and KMS permissions for ECS Batch instances"
  policy      = data.aws_iam_policy_document.ecs_s3_policy_doc.json

  tags = {
    Name = "ecs_s3_policy"
  }
}

resource "aws_iam_role_policy_attachment" "ecs_instance_role_s3" {
  role       = aws_iam_role.ecs_instance_role.name
  policy_arn = aws_iam_policy.ecs_s3_policy.arn
}

resource "aws_iam_instance_profile" "ecs_instance_profile" {
  name = "${local.name_prefix}-ecs-instance-profile"
  role = aws_iam_role.ecs_instance_role.name

  tags = {
    Name = "${local.name_prefix}-ecs-instance-profile"
  }
}

# AWS Batch Service Role
data "aws_iam_policy_document" "batch_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["batch.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "batch_service_role" {
  name               = "${local.name_prefix}-service-role"
  assume_role_policy = data.aws_iam_policy_document.batch_assume_role.json

  tags = {
    Name = "${local.name_prefix}-service-role"
  }
}

resource "aws_iam_role_policy_attachment" "batch_service_role_attachment" {
  role       = aws_iam_role.batch_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBatchServiceRole"
}

# ==============================================================================
# AWS Batch Compute Environment & Job Queue
# ==============================================================================

resource "aws_batch_compute_environment" "compute_environment" {
  compute_environment_name = local.name_prefix
  type                     = "MANAGED"
  state                    = "ENABLED"
  service_role             = aws_iam_role.batch_service_role.arn

  compute_resources {
    type                = "EC2"
    allocation_strategy = "BEST_FIT"
    instance_type       = ["optimal"]
    image_type          = "ECS_AL2023"
    min_vcpus           = 0
    max_vcpus           = 4
    instance_role       = aws_iam_instance_profile.ecs_instance_profile.arn

    subnets = [
      aws_subnet.private.id
    ]

    security_group_ids = [
      aws_security_group.batch_compute.id
    ]

    tags = {
      Name = "${local.name_prefix}-ec2-instance"
    }
  }

  tags = {
    Name = local.name_prefix
  }

  depends_on = [
    aws_iam_role_policy_attachment.batch_service_role_attachment,
    aws_iam_role_policy_attachment.ecs_instance_role_ec2,
    aws_iam_role_policy_attachment.ecs_instance_role_s3
  ]
}

resource "aws_batch_job_queue" "job_queue" {
  name     = "${local.name_prefix}-queue"
  state    = "ENABLED"
  priority = 1

  compute_environments = [
    aws_batch_compute_environment.compute_environment.arn
  ]

  tags = {
    Name = "${local.name_prefix}-queue"
  }
}

# ==============================================================================
# Outputs
# ==============================================================================

output "batch_compute_environment_arn" {
  description = "ARN of the Batch Compute Environment"
  value       = aws_batch_compute_environment.compute_environment.arn
}

output "batch_job_queue_arn" {
  description = "ARN of the Batch Job Queue"
  value       = aws_batch_job_queue.job_queue.arn
}

output "s3_results_bucket" {
  description = "Name of the S3 results bucket"
  value       = aws_s3_bucket.results.bucket
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key"
  value       = aws_kms_key.results_key.arn
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-east-1"
}

# Fetch the current AWS Account ID and Region
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  bucket_name = "endpoint-backup-${data.aws_caller_identity.current.account_id}"
}

# S3 Bucket
resource "aws_s3_bucket" "endpoint_backup" {
  bucket              = local.bucket_name
  object_lock_enabled = false

  tags = {
    Name        = local.bucket_name
    Environment = "Backup"
  }
}

# Block all public access
resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Default server-side encryption with S3-managed keys (AES256)
resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Suspend transfer acceleration
resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

# S3 Bucket Policy
resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnforceTLS12OrHigher"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.endpoint_backup.arn,
          "${aws_s3_bucket.endpoint_backup.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
          NumericLessThan = {
            "s3:TlsVersion" = "1.2"
          }
        }
      },
      {
        Sid       = "DenyComplianceLockOver90Days"
        Effect    = "Deny"
        Principal = "*"
        Action = [
          "s3:PutObjectRetention",
          "s3:PutObject"
        ]
        Resource = "${aws_s3_bucket.endpoint_backup.arn}/*"
        Condition = {
          StringEquals = {
            "s3:object-lock-mode" = "COMPLIANCE"
          }
          NumericGreaterThan = {
            "s3:object-lock-remaining-retention-days" = "90"
          }
        }
      }
    ]
  })
}

# IAM User
resource "aws_iam_user" "endpoint_backup" {
  name = "endpoint-backup"

  tags = {
    Name = "endpoint-backup"
  }
}

# Customer-Managed IAM Policy
resource "aws_iam_policy" "endpoint_backup_read_write" {
  name        = "endpoint-backup-bucket-read-write-access"
  description = "Grant read, write, retention, and KMS access for the endpoint backup bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3BucketAccess"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:ListBucketVersions",
          "s3:GetBucketLocation",
          "s3:GetBucketVersioning"
        ]
        Resource = aws_s3_bucket.endpoint_backup.arn
      },
      {
        Sid    = "S3ObjectAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:DeleteObjectVersion",
          "s3:RestoreObject",
          "s3:GetObjectRetention",
          "s3:PutObjectRetention"
        ]
        Resource = "${aws_s3_bucket.endpoint_backup.arn}/*"
      },
      {
        Sid    = "KMSAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey"
        ]
        Resource = "arn:aws:kms:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:alias/aws/s3"
      }
    ]
  })
}

# Attach IAM Policy to IAM User
resource "aws_iam_user_policy_attachment" "endpoint_backup_attachment" {
  user       = aws_iam_user.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_backup_read_write.arn
}

output "bucket_name" {
  description = "The name of the endpoint backup S3 bucket"
  value       = aws_s3_bucket.endpoint_backup.id
}

output "iam_user_name" {
  description = "The IAM user created for endpoint backups"
  value       = aws_iam_user.endpoint_backup.name
}

output "iam_policy_arn" {
  description = "The ARN of the IAM policy created"
  value       = aws_iam_policy.endpoint_backup_read_write.arn
}

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region to deploy resources into"
  default     = "us-west-2"
}

variable "cognito_domain_prefix" {
  type        = string
  description = "Domain prefix for the Cognito Hosted UI domain"
  default     = "unity-shared-services-test"
}

variable "uds_distribution_callback_urls" {
  type        = list(string)
  description = "Callback URLs for unity-uds-distribution-user-pool-client"
  default     = ["https://api.example.com/uds/oauth2/idpresponse"]
}

variable "uds_distribution_logout_urls" {
  type        = list(string)
  description = "Logout URLs for unity-uds-distribution-user-pool-client"
  default     = ["https://api.example.com/uds/logout"]
}

variable "localhost_jupyterhub_callback_urls" {
  type        = list(string)
  description = "Callback URLs for localhost-jupyterhub-user-pool-client"
  default     = ["http://localhost:8000/hub/oauth_callback"]
}

variable "localhost_jupyterhub_logout_urls" {
  type        = list(string)
  description = "Logout URLs for localhost-jupyterhub-user-pool-client"
  default     = ["http://localhost:8000/hub/logout"]
}

variable "app_to_app_callback_urls" {
  type        = list(string)
  description = "Callback URLs for unity-app-to-app-client-user-pool-client"
  default     = ["https://api.example.com/app/oauth2/callback"]
}

variable "app_to_app_logout_urls" {
  type        = list(string)
  description = "Logout URLs for unity-app-to-app-client-user-pool-client"
  default     = ["https://api.example.com/app/logout"]
}

variable "uads_jupyter_dev_callback_urls" {
  type        = list(string)
  description = "Callback URLs for uads-jupyter-development-client-user-pool-client"
  default     = ["https://jupyter-dev.example.com/oauth2/callback"]
}

variable "uads_jupyter_dev_logout_urls" {
  type        = list(string)
  description = "Logout URLs for uads-jupyter-development-client-user-pool-client"
  default     = ["https://jupyter-dev.example.com/logout"]
}

variable "hysds_ui_callback_urls" {
  type        = list(string)
  description = "Callback URLs for hysds-ui-client-user-pool-client"
  default     = ["https://hysds.example.com/login/oauth2/code/cognito"]
}

variable "hysds_ui_logout_urls" {
  type        = list(string)
  description = "Logout URLs for hysds-ui-client-user-pool-client"
  default     = ["https://hysds.example.com/logout"]
}

variable "localhost_hysds_ui_callback_urls" {
  type        = list(string)
  description = "Callback URLs for localhost-hysds-ui-client-user-pool-client"
  default     = ["http://localhost:3000/login/oauth2/code/cognito"]
}

variable "localhost_hysds_ui_logout_urls" {
  type        = list(string)
  description = "Logout URLs for localhost-hysds-ui-client-user-pool-client"
  default     = ["http://localhost:3000/logout"]
}

# -----------------------------------------------------------------------------
# Cognito User Pool
# -----------------------------------------------------------------------------
resource "aws_cognito_user_pool" "pool" {
  name = "unity-shared-services-user-pool"

  admin_create_user_config {
    allow_admin_create_user_only = true
    invite_message_template {
      email_message = "Your Unity username is {username} and your temporary password is {####}. Please log in and change your password."
      email_subject = "Welcome to Unity Shared Services - Your Credentials"
      sms_message   = "Your Unity username is {username} and your temporary password is {####}."
    }
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  auto_verified_attributes = ["email"]
}

# -----------------------------------------------------------------------------
# Cognito User Pool Domain (Hosted UI)
# -----------------------------------------------------------------------------
resource "aws_cognito_user_pool_domain" "main" {
  domain       = var.cognito_domain_prefix
  user_pool_id = aws_cognito_user_pool.pool.id
}

# -----------------------------------------------------------------------------
# SSM Parameter for User Pool ID
# -----------------------------------------------------------------------------
resource "aws_ssm_parameter" "user_pool_id" {
  name        = "/unity/cs/security/shared-services-cognito-user-pool/user-pool-id"
  description = "Cognito User Pool ID for Unity Shared Services"
  type        = "String"
  value       = aws_cognito_user_pool.pool.id
}

# -----------------------------------------------------------------------------
# Cognito User Groups
# -----------------------------------------------------------------------------
resource "aws_cognito_user_group" "admin" {
  name         = "Unity_Admin"
  user_pool_id = aws_cognito_user_pool.pool.id
  description  = "Unity Administrator Group"
  priority     = 1
}

resource "aws_cognito_user_group" "viewer" {
  name         = "Unity_Viewer"
  user_pool_id = aws_cognito_user_pool.pool.id
  description  = "Unity Viewer Group"
  priority     = 2
}

# -----------------------------------------------------------------------------
# Cognito App Clients
# -----------------------------------------------------------------------------

# 1. unity-uds-distribution-user-pool-client (Secret: Yes, Auth Flow: Default/SRP)
resource "aws_cognito_user_pool_client" "uds_distribution" {
  name         = "unity-uds-distribution-user-pool-client"
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]
  callback_urls                        = var.uds_distribution_callback_urls
  logout_urls                          = var.uds_distribution_logout_urls

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH"
  ]
}

# 2. localhost-jupyterhub-user-pool-client (Secret: Yes, Auth Flow: Default/SRP)
resource "aws_cognito_user_pool_client" "localhost_jupyterhub" {
  name         = "localhost-jupyterhub-user-pool-client"
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]
  callback_urls                        = var.localhost_jupyterhub_callback_urls
  logout_urls                          = var.localhost_jupyterhub_logout_urls

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH"
  ]
}

# 3. unity-app-to-app-client-user-pool-client (Secret: Yes, No username/password auth)
resource "aws_cognito_user_pool_client" "app_to_app" {
  name         = "unity-app-to-app-client-user-pool-client"
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]
  callback_urls                        = var.app_to_app_callback_urls
  logout_urls                          = var.app_to_app_logout_urls

  # Username/password auth disabled: no USER_PASSWORD_AUTH or USER_SRP_AUTH
  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_CUSTOM_AUTH"
  ]
}

# 4. uads-jupyter-development-client-user-pool-client (Secret: Yes, No username/password auth)
resource "aws_cognito_user_pool_client" "uads_jupyter_dev" {
  name         = "uads-jupyter-development-client-user-pool-client"
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]
  callback_urls                        = var.uads_jupyter_dev_callback_urls
  logout_urls                          = var.uads_jupyter_dev_logout_urls

  # Username/password auth disabled: no USER_PASSWORD_AUTH or USER_SRP_AUTH
  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_CUSTOM_AUTH"
  ]
}

# 5. hysds-ui-client-user-pool-client (Secret: No)
resource "aws_cognito_user_pool_client" "hysds_ui" {
  name         = "hysds-ui-client-user-pool-client"
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret                      = false
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]
  callback_urls                        = var.hysds_ui_callback_urls
  logout_urls                          = var.hysds_ui_logout_urls

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH"
  ]
}

# 6. localhost-hysds-ui-client-user-pool-client (Secret: No)
resource "aws_cognito_user_pool_client" "localhost_hysds_ui" {
  name         = "localhost-hysds-ui-client-user-pool-client"
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret                      = false
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]
  callback_urls                        = var.localhost_hysds_ui_callback_urls
  logout_urls                          = var.localhost_hysds_ui_logout_urls

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH"
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "cognito_user_pool_id" {
  description = "The ID of the Cognito User Pool"
  value       = aws_cognito_user_pool.pool.id
}

output "cognito_user_pool_arn" {
  description = "The ARN of the Cognito User Pool"
  value       = aws_cognito_user_pool.pool.arn
}

output "cognito_user_pool_endpoint" {
  description = "The endpoint of the Cognito User Pool"
  value       = aws_cognito_user_pool.pool.endpoint
}

output "ssm_parameter_name" {
  description = "The name of the SSM Parameter holding the User Pool ID"
  value       = aws_ssm_parameter.user_pool_id.name
}
```

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region for deploying resources"
  default     = "us-east-1"
}

variable "app_name" {
  type        = string
  description = "Application name used for resource naming and tagging"
  default     = "terraform"
}

variable "environment" {
  type        = string
  description = "Deployment environment name"
  default     = "testing"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "enable_dns_hostnames" {
  type        = bool
  description = "Flag to enable/disable DNS hostnames in the VPC"
  default     = false
}

variable "enable_dns_support" {
  type        = bool
  description = "Flag to enable/disable DNS support in the VPC"
  default     = true
}

variable "enable_ipv6" {
  type        = bool
  description = "Flag to enable/disable IPv6 for the VPC"
  default     = false
}

variable "public_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for public subnets"
  default     = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]
}

variable "private_subnet_cidrs" {
  type        = list(string)
  description = "CIDR blocks for private subnets"
  default     = ["10.0.11.0/24", "10.0.22.0/24", "10.0.33.0/24"]
}

variable "enable_transit_gateway_attachment" {
  type        = bool
  description = "Whether to create a Transit Gateway attachment"
  default     = false
}

variable "transit_gateway_id" {
  type        = string
  description = "Optional Transit Gateway ID if attachment is enabled"
  default     = null
}

variable "enable_ipv6_egress_only_internet_gateway" {
  type        = bool
  description = "Whether to create an egress-only internet gateway for IPv6"
  default     = false
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "${var.app_name}-${var.environment}"
  azs         = slice(data.aws_availability_zones.available.names, 0, 3)
  common_tags = {
    Application = var.app_name
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

# -----------------------------------------------------------------------------
# VPC and Gateways
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  enable_dns_hostnames             = var.enable_dns_hostnames
  enable_dns_support               = var.enable_dns_support
  assign_generated_ipv6_cidr_block = var.enable_ipv6

  tags = merge(
    local.common_tags,
    {
      Name = "vpc-${local.name_prefix}"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "igw-${local.name_prefix}"
    }
  )
}

resource "aws_egress_only_internet_gateway" "main" {
  count  = var.enable_ipv6 && var.enable_ipv6_egress_only_internet_gateway ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "eigw-${local.name_prefix}"
    }
  )
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    {
      Name = "subnet-public-${local.name_prefix}-${local.azs[count.index]}"
      Type = "Public"
    }
  )
}

resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "subnet-private-${local.name_prefix}-${local.azs[count.index]}"
      Type = "Private"
    }
  )
}

# -----------------------------------------------------------------------------
# NAT Gateway
# -----------------------------------------------------------------------------
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(
    local.common_tags,
    {
      Name = "eip-${local.name_prefix}-nat"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(
    local.common_tags,
    {
      Name = "nat-${local.name_prefix}"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

# -----------------------------------------------------------------------------
# Route Tables and Routes
# -----------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "rt-public-${local.name_prefix}"
    }
  )
}

resource "aws_route" "public_internet_access" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "rt-private-${local.name_prefix}"
    }
  )
}

resource "aws_route" "private_nat_gateway_access" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# RDS DB Subnet Group
# -----------------------------------------------------------------------------
resource "aws_db_subnet_group" "main" {
  name        = "db-subnet-${local.name_prefix}"
  description = "Database subnet group spanning private subnets for ${local.name_prefix}"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(
    local.common_tags,
    {
      Name = "db-subnet-${local.name_prefix}"
    }
  )
}

# -----------------------------------------------------------------------------
# Optional Transit Gateway Attachment
# -----------------------------------------------------------------------------
resource "aws_ec2_transit_gateway_vpc_attachment" "main" {
  count              = var.enable_transit_gateway_attachment && var.transit_gateway_id != null ? 1 : 0
  transit_gateway_id = var.transit_gateway_id
  vpc_id             = aws_vpc.main.id
  subnet_ids         = aws_subnet.private[*].id

  tags = merge(
    local.common_tags,
    {
      Name = "tgw-attachment-${local.name_prefix}"
    }
  )
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC"
  value       = aws_vpc.main.cidr_block
}

output "default_security_group_id" {
  description = "The ID of the VPC default security group"
  value       = aws_vpc.main.default_security_group_id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "nat_gateway_id" {
  description = "The ID of the NAT Gateway"
  value       = aws_nat_gateway.main.id
}

output "nat_gateway_public_ip" {
  description = "The Public IP associated with the NAT Gateway"
  value       = aws_eip.nat.public_ip
}

output "db_subnet_group_name" {
  description = "The name of the DB subnet group"
  value       = aws_db_subnet_group.main.name
}

output "db_subnet_group_arn" {
  description = "The ARN of the DB subnet group"
  value       = aws_db_subnet_group.main.arn
}
```

```terraform
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
  }
}

variable "aws_region" {
  description = "The AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "repositories" {
  description = "List of CodeCommit repository names"
  type        = list(string)
  default     = ["gitops-apps", "gitops-platform", "gitops-addons"]
}

variable "iam_user_name" {
  description = "IAM user name for GitOps operations"
  type        = string
  default     = "gitops-bridge-gitops"
}

variable "ssh_key_path" {
  description = "Local path for writing the private SSH key"
  type        = string
  default     = "~/.ssh/gitops_ssh.pem"
}

variable "ssh_config_path" {
  description = "Local path for writing the SSH config file entry"
  type        = string
  default     = "~/.ssh/config-codecommit"
}

provider "aws" {
  region = var.aws_region
}

# 1. AWS CodeCommit Repositories
resource "aws_codecommit_repository" "gitops_repos" {
  for_each        = toset(var.repositories)
  repository_name = each.value
  description     = "GitOps repository for ${each.value}"
}

# 2. RSA 4096-bit Key Pair
resource "tls_private_key" "gitops_ssh_key" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

# 3. IAM User and Uploaded SSH Key
resource "aws_iam_user" "gitops_user" {
  name = var.iam_user_name
  path = "/"
}

resource "aws_iam_user_ssh_key" "gitops_user_ssh_key" {
  username   = aws_iam_user.gitops_user.name
  encoding   = "SSH"
  public_key = tls_private_key.gitops_ssh_key.public_key_openssh
}

# 4. Customer-Managed IAM Policy for Pull/Push Access
data "aws_iam_policy_document" "codecommit_access" {
  statement {
    sid    = "CodeCommitRepoAccess"
    effect = "Allow"
    actions = [
      "codecommit:GitPull",
      "codecommit:GitPush",
      "codecommit:GitBranch",
      "codecommit:GetBranch",
      "codecommit:GetCommit",
      "codecommit:GetRepository",
      "codecommit:ListBranches",
      "codecommit:ListTags"
    ]
    resources = [
      for repo in aws_codecommit_repository.gitops_repos : repo.arn
    ]
  }
}

resource "aws_iam_policy" "gitops_policy" {
  name        = var.iam_user_name
  description = "Git pull and push access to GitOps CodeCommit repositories"
  policy      = data.aws_iam_policy_document.codecommit_access.json
}

resource "aws_iam_user_policy_attachment" "gitops_attachment" {
  user       = aws_iam_user.gitops_user.name
  policy_arn = aws_iam_policy.gitops_policy.arn
}

# 5. Secrets Manager Secret with random 5-character suffix
resource "random_string" "suffix" {
  length  = 5
  special = false
  upper   = false
}

resource "aws_secretsmanager_secret" "ssh_key_secret" {
  name                    = "codecommit-key-${random_string.suffix.result}"
  description             = "SSH private key for CodeCommit user ${var.iam_user_name}"
  recovery_window_in_days = 0
}

resource "aws_secretsmanager_secret_version" "ssh_key_secret_val" {
  secret_id     = aws_secretsmanager_secret.ssh_key_secret.id
  secret_string = tls_private_key.gitops_ssh_key.private_key_pem
}

# 6. Local files: Private Key and SSH Config
resource "local_file" "ssh_private_key" {
  content         = tls_private_key.gitops_ssh_key.private_key_pem
  filename        = pathexpand(var.ssh_key_path)
  file_permission = "0600"
}

resource "local_file" "ssh_config_entry" {
  content = <<-EOT
Host git-codecommit.*.amazonaws.com
    User ${aws_iam_user_ssh_key.gitops_user_ssh_key.ssh_public_key_id}
    IdentityFile ${pathexpand(var.ssh_key_path)}
    StrictHostKeyChecking accept-new
EOT

  filename        = pathexpand(var.ssh_config_path)
  file_permission = "0600"
}

output "repository_clone_urls_ssh" {
  description = "SSH clone URLs for the CodeCommit repositories"
  value = {
    for k, repo in aws_codecommit_repository.gitops_repos : k => repo.clone_url_ssh
  }
}

output "ssh_public_key_id" {
  description = "The SSH Public Key ID associated with the IAM user"
  value       = aws_iam_user_ssh_key.gitops_user_ssh_key.ssh_public_key_id
}

output "secret_arn" {
  description = "The ARN of the secret containing the private key in AWS Secrets Manager"
  value       = aws_secretsmanager_secret.ssh_key_secret.arn
}
```

```hcl
terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

# -----------------------------------------------------------------------------
# Input Variables
# -----------------------------------------------------------------------------
variable "aws_region" {
  type        = string
  description = "AWS region for resources"
  default     = "us-east-1"
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the VPC"
  default     = "10.70.0.0/16"
}

variable "subnet_cidr" {
  type        = string
  description = "CIDR block for the subnet"
  default     = "10.70.0.0/24"
}

variable "instance_name" {
  type        = string
  description = "Name tag for the EC2 instance"
  default     = "benchmark-instance"
}

variable "instance_type" {
  type        = string
  description = "EC2 instance type"
  default     = "t2.micro"
}

variable "public_key" {
  type        = string
  description = "SSH public key to use for EC2 key pair creation (if empty, an ED25519 key will be generated)"
  default     = ""
}

variable "extra_ebs_volumes" {
  type = list(object({
    device_name = string
    size        = number
    type        = optional(string, "gp3")
    encrypted   = optional(bool, true)
  }))
  description = "Optional additional EBS volumes to attach"
  default     = []
}

variable "additional_network_interfaces" {
  type = list(object({
    subnet_id         = string
    security_group_ids = optional(list(string))
    allocate_eip      = optional(bool, true)
  }))
  description = "Optional additional network interfaces with optional Elastic IPs"
  default     = []
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "benchmark-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "benchmark-igw"
  }
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "benchmark-subnet"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "benchmark-public-rt"
  }
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Security & IAM
# -----------------------------------------------------------------------------
resource "aws_security_group" "instance_sg" {
  name        = "benchmark-instance-sg"
  description = "Security group allowing egress strictly to VPC CIDR"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow egress to VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "benchmark-instance-sg"
  }
}

resource "aws_iam_role" "ec2_role" {
  name = "benchmark-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "benchmark-ec2-role"
  }
}

resource "aws_iam_instance_profile" "instance_profile" {
  name = "benchmark-ec2-instance-profile"
  role = aws_iam_role.ec2_role.name
}

# Fallback ED25519 key if none provided
resource "tls_private_key" "generated" {
  count     = var.public_key == "" ? 1 : 0
  algorithm = "ED25519"
}

resource "aws_key_pair" "benchmark_key" {
  key_name   = "benchmark-d8bc612be4e0-key"
  public_key = var.public_key != "" ? var.public_key : tls_private_key.generated[0].public_key_openssh

  tags = {
    Name = "benchmark-d8bc612be4e0-key"
  }
}

# -----------------------------------------------------------------------------
# AMI Lookup
# -----------------------------------------------------------------------------
data "aws_ami" "ubuntu_2204" {
  most_recent = true
  owners      = ["099720109477"] # Canonical

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-amd64-server-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# -----------------------------------------------------------------------------
# EC2 Instance & Attached Resources
# -----------------------------------------------------------------------------
resource "aws_instance" "benchmark" {
  ami                         = data.aws_ami.ubuntu_2204.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.main.id
  vpc_security_group_ids      = [aws_security_group.instance_sg.id]
  key_name                    = aws_key_pair.benchmark_key.key_name
  iam_instance_profile        = aws_iam_instance_profile.instance_profile.name
  associate_public_ip_address = true
  monitoring                  = true

  root_block_device {
    volume_type           = "gp2"
    volume_size           = 10
    encrypted             = true
    delete_on_termination = true
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  tags = {
    Name = var.instance_name
  }
}

resource "aws_eip" "main" {
  domain   = "vpc"
  instance = aws_instance.benchmark.id

  tags = {
    Name = "benchmark-instance-eip"
  }
}

# Extra EBS Volumes (Optional, none created by default)
resource "aws_ebs_volume" "extra" {
  count             = length(var.extra_ebs_volumes)
  availability_zone = aws_subnet.main.availability_zone
  size              = var.extra_ebs_volumes[count.index].size
  type              = var.extra_ebs_volumes[count.index].type
  encrypted         = var.extra_ebs_volumes[count.index].encrypted

  tags = {
    Name = "${var.instance_name}-extra-volume-${count.index}"
  }
}

resource "aws_volume_attachment" "extra" {
  count       = length(var.extra_ebs_volumes)
  device_name = var.extra_ebs_volumes[count.index].device_name
  volume_id   = aws_ebs_volume.extra[count.index].id
  instance_id = aws_instance.benchmark.id
}

# Additional Network Interfaces (Optional, none created by default)
resource "aws_network_interface" "extra" {
  count           = length(var.additional_network_interfaces)
  subnet_id       = var.additional_network_interfaces[count.index].subnet_id
  security_groups = var.additional_network_interfaces[count.index].security_group_ids

  tags = {
    Name = "${var.instance_name}-extra-eni-${count.index}"
  }
}

resource "aws_network_interface_attachment" "extra" {
  count                = length(var.additional_network_interfaces)
  instance_id          = aws_instance.benchmark.id
  network_interface_id = aws_network_interface.extra[count.index].id
  device_index         = count.index + 1
}

resource "aws_eip" "extra" {
  count             = length([for idx, iface in var.additional_network_interfaces : idx if iface.allocate_eip])
  domain            = "vpc"
  network_interface = aws_network_interface.extra[count.index].id

  tags = {
    Name = "${var.instance_name}-extra-eip-${count.index}"
  }
}

# -----------------------------------------------------------------------------
# CloudWatch Auto-Recovery / Reboot Alarm
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_metric_alarm" "reboot_on_status_check_failed" {
  alarm_name          = "benchmark-instance-status-check-reboot"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 5
  metric_name         = "StatusCheckFailed_Instance"
  namespace           = "AWS/EC2"
  period              = 60
  statistic           = "Maximum"
  threshold           = 1
  alarm_description   = "Reboot the instance when StatusCheckFailed_Instance is >= 1 for 5 consecutive 60-second periods"
  alarm_actions       = ["arn:aws:automate:${var.aws_region}:ec2:reboot"]

  dimensions = {
    InstanceId = aws_instance.benchmark.id
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "instance_id" {
  description = "ID of the launched EC2 instance"
  value       = aws_instance.benchmark.id
}

output "instance_public_ip" {
  description = "Primary Elastic IP of the instance"
  value       = aws_eip.main.public_ip
}

output "vpc_id" {
  description = "ID of the created VPC"
  value       = aws_vpc.main.id
}

output "subnet_id" {
  description = "ID of the created Subnet"
  value       = aws_subnet.main.id
}
```

```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# --- Region Configurations ---
variable "source_region_1" {
  description = "Primary source AWS region"
  type        = string
  default     = "us-east-1"
}

variable "source_region_2" {
  description = "Secondary source AWS region"
  type        = string
  default     = "us-east-2"
}

variable "replica_region_1" {
  description = "First replica AWS region"
  type        = string
  default     = "us-west-1"
}

variable "replica_region_2" {
  description = "Second replica AWS region"
  type        = string
  default     = "us-west-2"
}

# --- Providers ---
provider "aws" {
  alias  = "source1"
  region = var.source_region_1
}

provider "aws" {
  alias  = "source2"
  region = var.source_region_2
}

provider "aws" {
  alias  = "replica1"
  region = var.replica_region_1
}

provider "aws" {
  alias  = "replica2"
  region = var.replica_region_2
}

# Default provider for global resources (IAM, caller identity)
provider "aws" {
  region = var.source_region_1
}

# Account & Partition Info
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  common_tags = {
    Env = "dev"
  }
}

# ==============================================================================
# KMS Customer Managed Keys
# ==============================================================================

# Key Policy Document Helper
data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid       = "EnableIAMUserPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }
}

# KMS Key - Source Region 1
resource "aws_kms_key" "source_key_1" {
  provider                = aws.source1
  description             = "KMS key for source region 1 log buckets"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
  tags                    = local.common_tags
}

resource "aws_kms_alias" "source_key_1_alias" {
  provider      = aws.source1
  name          = "alias/sourcekey1"
  target_key_id = aws_kms_key.source_key_1.key_id
}

# KMS Key - Source Region 2
resource "aws_kms_key" "source_key_2" {
  provider                = aws.source2
  description             = "KMS key for source region 2 log buckets"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
  tags                    = local.common_tags
}

resource "aws_kms_alias" "source_key_2_alias" {
  provider      = aws.source2
  name          = "alias/sourcekey2"
  target_key_id = aws_kms_key.source_key_2.key_id
}

# KMS Key - Replica Region 1
resource "aws_kms_key" "replica_key_1" {
  provider                = aws.replica1
  description             = "KMS key for replica region 1 log buckets"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
  tags                    = local.common_tags
}

resource "aws_kms_alias" "replica_key_1_alias" {
  provider      = aws.replica1
  name          = "alias/replicakey1"
  target_key_id = aws_kms_key.replica_key_1.key_id
}

# KMS Key - Replica Region 2
resource "aws_kms_key" "replica_key_2" {
  provider                = aws.replica2
  description             = "KMS key for replica region 2 log buckets"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
  tags                    = local.common_tags
}

resource "aws_kms_alias" "replica_key_2_alias" {
  provider      = aws.replica2
  name          = "alias/replicakey2"
  target_key_id = aws_kms_key.replica_key_2.key_id
}

# ==============================================================================
# Replica Buckets - Replica Region 1 (4 buckets)
# ==============================================================================

# Bucket: log1a.veerum-replica1
resource "aws_s3_bucket" "replica1_log1a" {
  provider      = aws.replica1
  bucket        = "log1a.veerum-replica1-${local.account_id}"
  force_destroy = true
  tags          = local.common_tags
}

resource "aws_s3_bucket_versioning" "replica1_log1a" {
  provider = aws.replica1
  bucket   = aws_s3_bucket.replica1_log1a.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica1_log1a" {
  provider = aws.replica1
  bucket   = aws_s3_bucket.replica1_log1a.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica_key_1.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replica1_log1a" {
  provider                = aws.replica1
  bucket                  = aws_s3_bucket.replica1_log1a.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Bucket: log1b.veerum-replica1
resource "aws_s3_bucket" "replica1_log1b" {
  provider      = aws.replica1
  bucket        = "log1b.veerum-replica1-${local.account_id}"
  force_destroy = true
  tags          = local.common_tags
}

resource "aws_s3_bucket_versioning" "replica1_log1b" {
  provider = aws.replica1
  bucket   = aws_s3_bucket.replica1_log1b.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica1_log1b" {
  provider = aws.replica1
  bucket   = aws_s3_bucket.replica1_log1b.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica_key_1.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replica1_log1b" {
  provider                = aws.replica1
  bucket                  = aws_s3_bucket.replica1_log1b.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Bucket: log2a.veerum-replica1
resource "aws_s3_bucket" "replica1_log2a" {
  provider      = aws.replica1
  bucket        = "log2a.veerum-replica1-${local.account_id}"
  force_destroy = true
  tags          = local.common_tags
}

resource "aws_s3_bucket_versioning" "replica1_log2a" {
  provider = aws.replica1
  bucket   = aws_s3_bucket.replica1_log2a.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica1_log2a" {
  provider = aws.replica1
  bucket   = aws_s3_bucket.replica1_log2a.id
  rule {
    apply_server_side_encryption_by_default {
