# ==============================================================================
# IAM Role and Policies for S3 Replication
# ==============================================================================

data "aws_iam_policy_document" "s3_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = "s3-cross-region-replication-role"
  assume_role_policy = data.aws_iam_policy_document.s3_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "replication_policy" {
  # Read Source Buckets & Objects
  statement {
    sid    = "SourceBucketPermissions"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]
    resources = [
      "arn:${local.partition}:s3:::log1a.veerum-${local.account_id}",
      "arn:${local.partition}:s3:::log1b.veerum-${local.account_id}",
      "arn:${local.partition}:s3:::log2a.veerum-${local.account_id}",
      "arn:${local.partition}:s3:::log2b.veerum-${local.account_id}"
    ]
  }

  statement {
    sid    = "SourceObjectPermissions"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging"
    ]
    resources = [
      "arn:${local.partition}:s3:::log1a.veerum-${local.account_id}/*",
      "arn:${local.partition}:s3:::log1b.veerum-${local.account_id}/*",
      "arn:${local.partition}:s3:::log2a.veerum-${local.account_id}/*",
      "arn:${local.partition}:s3:::log2b.veerum-${local.account_id}/*"
    ]
  }

  # Write Replicas & Deletes
  statement {
    sid    = "DestinationReplicationPermissions"
    effect = "Allow"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:GetObjectVersion",
      "s3:ObjectOwnerOverrideToBucketOwner"
    ]
    resources = [
      "${aws_s3_bucket.replica1_log1a.arn}/*",
      "${aws_s3_bucket.replica1_log1b.arn}/*",
      "${aws_s3_bucket.replica1_log2a.arn}/*",
      "${aws_s3_bucket.replica1_log2b.arn}/*",
      "${aws_s3_bucket.replica2_log1a.arn}/*",
      "${aws_s3_bucket.replica2_log1b.arn}/*",
      "${aws_s3_bucket.replica2_log2a.arn}/*",
      "${aws_s3_bucket.replica2_log2b.arn}/*"
    ]
  }

  # Decrypt with Source KMS Keys
  statement {
    sid    = "SourceKMSDecrypt"
    effect = "Allow"
    actions = [
      "kms:Decrypt"
    ]
    resources = [
      aws_kms_key.source_key_1.arn,
      aws_kms_key.source_key_2.arn
    ]
  }

  # Encrypt with Destination KMS Keys
  statement {
    sid    = "DestinationKMSEncrypt"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey"
    ]
    resources = [
      aws_kms_key.replica_key_1.arn,
      aws_kms_key.replica_key_2.arn
    ]
  }
}

resource "aws_iam_policy" "replication" {
  name        = "s3-cross-region-replication-policy"
  description = "Allows S3 to replicate objects and decrypt/encrypt KMS across source and replica buckets"
  policy      = data.aws_iam_policy_document.replication_policy.json
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# ==============================================================================
# Source Buckets - Source Region 1 (us-east-1)
# ==============================================================================

# Bucket: log1a.veerum
resource "aws_s3_bucket" "source_log1a" {
  provider      = aws.source1
  bucket        = "log1a.veerum-${local.account_id}"
  force_destroy = true
  tags          = local.common_tags
}

resource "aws_s3_bucket_versioning" "source_log1a" {
  provider = aws.source1
  bucket   = aws_s3_bucket.source_log1a.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source_log1a" {
  provider = aws.source1
  bucket   = aws_s3_bucket.source_log1a.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.source_key_1.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "source_log1a" {
  provider                = aws.source1
  bucket                  = aws_s3_bucket.source_log1a.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_replication_configuration" "source_log1a" {
  provider = aws.source1
  bucket   = aws_s3_bucket.source_log1a.id
  role     = aws_iam_role.replication.arn

  rule {
    id     = "replicate-to-replica1"
    status = "Enabled"

    filter {}

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica1_log1a.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica_key_1.arn
      }
    }
  }

  rule {
    id     = "replicate-to-replica2"
    status = "Enabled"

    filter {}

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica2_log1a.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica_key_2.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.source_log1a,
    aws_s3_bucket_versioning.replica1_log1a,
    aws_s3_bucket_versioning.replica2_log1a,
    aws_iam_role_policy_attachment.replication
  ]
}

