```hcl
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

# --- Variables ---

variable "aws_region" {
  type        = string
  description = "AWS region to deploy GuardDuty and primary resources."
  default     = "us-east-1"
}

variable "replica_region" {
  type        = string
  description = "AWS region for replica findings export bucket."
  default     = "us-west-2"
}

variable "repository_url" {
  type        = string
  description = "Repository URL tag for resources."
  default     = "https://github.com/example-org/terraform-aws-guardduty"
}

variable "enable_findings_export" {
  type        = string
  description = "Whether to create KMS-encrypted, access-logged, cross-region-replicated S3 bucket export for findings."
  default     = false
}

variable "enable_filter" {
  type        = bool
  description = "Whether to deploy a sample GuardDuty findings filter."
  default     = false
}

variable "enable_ipset" {
  type        = bool
  description = "Whether to deploy a GuardDuty trusted IP set."
  default     = false
}

variable "ipset_location" {
  type        = string
  description = "S3 URI containing the trusted IP set list."
  default     = ""
}

variable "enable_threatintelset" {
  type        = bool
  description = "Whether to deploy a GuardDuty ThreatIntelSet."
  default     = false
}

variable "threatintelset_location" {
  type        = string
  description = "S3 URI containing the threat intelligence set list."
  default     = ""
}

variable "enable_malware_protection_plan" {
  type        = bool
  description = "Whether to enable S3 Malware Protection Plan."
  default     = false
}

variable "malware_protection_bucket_name" {
  type        = string
  description = "The target S3 bucket name for malware protection."
  default     = ""
}

# --- Data Sources ---

data "aws_caller_identity" "current" {}

# --- Amazon GuardDuty Detector ---

resource "aws_guardduty_detector" "this" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"

  tags = {
    Repository = var.repository_url
  }
}

# Feature: S3 Data Events
resource "aws_guardduty_detector_feature" "s3_data_events" {
  detector_id = aws_guardduty_detector.this.id
  name        = "S3_DATA_EVENTS"
  status      = "ENABLED"
}

# Feature: RDS Login Events
resource "aws_guardduty_detector_feature" "rds_login_events" {
  detector_id = aws_guardduty_detector.this.id
  name        = "RDS_LOGIN_EVENTS"
  status      = "ENABLED"
}

# Feature: Lambda Network Logs
resource "aws_guardduty_detector_feature" "lambda_network_logs" {
  detector_id = aws_guardduty_detector.this.id
  name        = "LAMBDA_NETWORK_LOGS"
  status      = "ENABLED"
}

# Feature: EKS Audit Logs
resource "aws_guardduty_detector_feature" "eks_audit_logs" {
  detector_id = aws_guardduty_detector.this.id
  name        = "EKS_AUDIT_LOGS"
  status      = "ENABLED"
}

# Feature: EBS Malware Protection
resource "aws_guardduty_detector_feature" "ebs_malware_protection" {
  detector_id = aws_guardduty_detector.this.id
  name        = "EBS_MALWARE_PROTECTION"
  status      = "ENABLED"
}

# Feature: Runtime Monitoring with manual agent management
resource "aws_guardduty_detector_feature" "runtime_monitoring" {
  detector_id = aws_guardduty_detector.this.id
  name        = "RUNTIME_MONITORING"
  status      = "ENABLED"

  additional_configuration {
    name   = "EKS_ADDON_MANAGEMENT"
    status = "DISABLED"
  }

  additional_configuration {
    name   = "ECS_FARGATE_AGENT_MANAGEMENT"
    status = "DISABLED"
  }

  additional_configuration {
    name   = "EC2_AGENT_MANAGEMENT"
    status = "DISABLED"
  }
}

# Configure Malware Scan Settings (EBS Snapshot Retention = false) via AWS CLI
resource "null_resource" "malware_scan_settings" {
  triggers = {
    detector_id = aws_guardduty_detector.this.id
  }

  provisioner "local-exec" {
    command = "aws guardduty update-malware-scan-settings --detector-id ${aws_guardduty_detector.this.id} --scan-options '{\"ScanPreservedSnapshot\": \"NO_RETENTION\"}' --region ${var.aws_region}"
  }

  depends_on = [
    aws_guardduty_detector_feature.ebs_malware_protection
  ]
}

# --- Optional Resources (Disabled by default) ---

# GuardDuty Filter
resource "aws_guardduty_filter" "example" {
  count       = var.enable_filter ? 1 : 0
  name        = "sample-filter"
  action      = "NOOP"
  detector_id = aws_guardduty_detector.this.id
  rank        = 1

  finding_criteria {
    criterion {
      field  = "severity"
      greater_than_or_equal = "4.0"
    }
  }

  tags = {
    Repository = var.repository_url
  }
}

# GuardDuty Trusted IP Set
resource "aws_guardduty_ipset" "example" {
  count       = var.enable_ipset && var.ipset_location != "" ? 1 : 0
  activate    = true
  detector_id = aws_guardduty_detector.this.id
  format      = "TXT"
  location    = var.ipset_location
  name        = "TrustedIPSet"

  tags = {
    Repository = var.repository_url
  }
}

# GuardDuty ThreatIntelSet
resource "aws_guardduty_threatintelset" "example" {
  count       = var.enable_threatintelset && var.threatintelset_location != "" ? 1 : 0
  activate    = true
  detector_id = aws_guardduty_detector.this.id
  format      = "TXT"
  location    = var.threatintelset_location
  name        = "ThreatIntelSet"

  tags = {
    Repository = var.repository_url
  }
}

# S3 Malware Protection Plan
resource "aws_iam_role" "guardduty_malware_role" {
  count = var.enable_malware_protection_plan ? 1 : 0
  name  = "GuardDutyMalwareProtectionRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "malware-protection-plan.guardduty.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "guardduty_malware_policy" {
  count = var.enable_malware_protection_plan ? 1 : 0
  name  = "GuardDutyMalwareProtectionPolicy"
  role  = aws_iam_role.guardduty_malware_role[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObjectTagging",
          "s3:GetObjectTagging"
        ]
        Resource = "arn:aws:s3:::${var.malware_protection_bucket_name}/*"
      }
    ]
  })
}

resource "aws_guardduty_malware_protection_plan" "example" {
  count    = var.enable_malware_protection_plan && var.malware_protection_bucket_name != "" ? 1 : 0
  role     = aws_iam_role.guardduty_malware_role[0].arn

  protected_resource {
    s3_bucket {
      bucket_name = var.malware_protection_bucket_name
    }
  }

  actions {
    tagging {
      status = "ENABLED"
    }
  }

  tags = {
    Repository = var.repository_url
  }
}

# --- Optional Findings Export Infrastructure (Disabled by default) ---

# Replica KMS Key
resource "aws_kms_key" "replica" {
  provider                = aws.replica
  count                   = var.enable_findings_export ? 1 : 0
  description             = "GuardDuty export destination KMS key in replica region"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Repository = var.repository_url
  }
}

# Replica S3 Bucket
resource "aws_s3_bucket" "replica" {
  provider      = aws.replica
  count         = var.enable_findings_export ? 1 : 0
  bucket_prefix = "guardduty-findings-replica-"
  force_destroy = true

  tags = {
    Repository = var.repository_url
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica
  count    = var.enable_findings_export ? 1 : 0
  bucket   = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica
  count    = var.enable_findings_export ? 1 : 0
  bucket   = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Replication IAM Role
resource "aws_iam_role" "replication" {
  count = var.enable_findings_export ? 1 : 0
  name  = "guardduty-findings-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "replication" {
  count = var.enable_findings_export ? 1 : 0
  name  = "guardduty-findings-replication-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = aws_s3_bucket.primary[0].arn
      },
      {
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.primary[0].arn}/*"
      },
      {
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.replica[0].arn}/*"
      },
      {
        Action = [
          "kms:Decrypt"
        ]
        Effect   = "Allow"
        Resource = aws_kms_key.primary[0].arn
      },
      {
        Action = [
          "kms:Encrypt"
        ]
        Effect   = "Allow"
        Resource = aws_kms_key.replica[0].arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count      = var.enable_findings_export ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

# Access Logs Bucket
resource "aws_s3_bucket" "log_bucket" {
  count         = var.enable_findings_export ? 1 : 0
  bucket_prefix = "guardduty-findings-access-logs-"
  force_destroy = true

  tags = {
    Repository = var.repository_url
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_bucket" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Primary KMS Key
resource "aws_kms_key" "primary" {
  count                   = var.enable_findings_export ? 1 : 0
  description             = "GuardDuty export destination KMS key"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow GuardDuty to use the key"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Encrypt"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Repository = var.repository_url
  }
}

# Primary S3 Bucket
resource "aws_s3_bucket" "primary" {
  count         = var.enable_findings_export ? 1 : 0
  bucket_prefix = "guardduty-findings-primary-"
  force_destroy = true

  tags = {
    Repository = var.repository_url
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.primary[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "primary" {
  count         = var.enable_findings_export ? 1 : 0
  bucket        = aws_s3_bucket.primary[0].id
  target_bucket = aws_s3_bucket.log_bucket[0].id
  target_prefix = "log/"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.primary[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_replication_configuration" "primary" {
  count      = var.enable_findings_export ? 1 : 0
  depends_on = [aws_s3_bucket_versioning.primary]
  role       = aws_iam_role.replication[0].arn
  bucket     = aws_s3_bucket.primary[0].id

  rule {
    id     = "ReplicateAll"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica[0].arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

resource "aws_s3_bucket_policy" "primary" {
  count  = var.enable_findings_export ? 1 : 0
  bucket = aws_s3_bucket.primary[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Allow GuardDuty to write findings"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.primary[0].arn}/*"
      },
      {
        Sid    = "Allow GuardDuty to check bucket permissions"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.primary[0].arn
      }
    ]
  })
}

# GuardDuty Publishing Destination
resource "aws_guardduty_publishing_destination" "example" {
  count           = var.enable_findings_export ? 1 : 0
  detector_id     = aws_guardduty_detector.this.id
  destination_arn = aws_s3_bucket.primary[0].arn
  kms_key_arn     = aws_kms_key.primary[0].arn

  depends_on = [
    aws_s3_bucket_policy.primary
  ]
}

# --- Outputs ---

output "guardduty_detector_id" {
  description = "The ID of the Amazon GuardDuty detector."
  value       = aws_guardduty_detector.this.id
}

output "guardduty_detector_arn" {
  description = "The ARN of the Amazon GuardDuty detector."
  value       = aws_guardduty_detector.this.arn
}
```
